local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:1438"] = {n="瓦拉里尔的搜寻",s="在完成瓦拉里尔的搜寻的第二部分后，瓦拉里尔·屠魔者派你从堡垒开始，寻找黛琳达和泰拉尼斯·玛雷姆。消息传到了瓦拉里尔在达纳苏斯的上级那里，他们对泰拉尼斯的动机心存疑虑，最看重的是让黛琳达平安归来。",h="在完成瓦拉里尔的搜寻的第二部分后，瓦拉里尔·屠魔者派你从堡垒开始，寻找黛琳达和泰拉尼斯·玛雷姆。消息传到了瓦拉里尔在达纳苏斯的上级那里，他们对泰拉尼斯的动机心存疑虑，最看重的是让黛琳达平安归来。",kw={"火刃氏族","黛琳达","达纳苏斯","屠魔者","凄凉之地","马雷姆","雷斧堡垒","泰拉尼斯","瓦拉里尔"},sec={{t="堡垒中的搜寻",b="瓦拉里尔·屠魔者希望你从堡垒开始，寻找黛琳达和泰拉尼斯，并带回你了解到的情况。瓦拉里尔会立即联系达纳苏斯的上级。随后，他私下透露：他们对泰拉尼斯来到凄凉之地的原因心存疑虑，最关心的是让黛琳达平安回家。至于泰拉尼斯，他们想先对他作出评估，再考虑让他回来。"},{t="俘虏的讲述",b="黛琳达就在正对入口的大建筑里，她说火刃氏族抓住了她和泰拉尼斯，把他们带到了这里，她相信自己将被献祭给他们的恶魔主人。她说，这趟旅程从一开始就是个错误。泰拉尼斯渐渐渴求奥术知识，违背族人的意愿，不顾此地有恶魔的警告，执意出发。她害怕知道他如今的下场。"}},faq={{q="黛琳达·玛雷姆在哪里？",a="在凄凉之地的雷斧堡垒区域，正对入口的大建筑里。",al={"黛琳达·玛雷姆位置","哪里能找到 黛琳达","凄凉之地寻找 黛琳达"}},{q="谁派你寻找黛琳达和泰拉尼斯？",a="瓦拉里尔·屠魔者请你从堡垒开始，尽可能找到他们两人，同时由瓦拉里尔向达纳苏斯的上级通报情况。",al={"谁发布 瓦拉里尔的搜寻","任务给予者 瓦拉里尔","瓦拉里尔·屠魔者任务"}},{q="为什么达纳苏斯更关心黛琳达，而不是泰拉尼斯？",a="瓦拉里尔的上级怀疑泰拉尼斯来到凄凉之地的动机，他们最看重的是让黛琳达平安归来。",al={"为什么怀疑 泰拉尼斯","泰拉尼斯 的动机","为什么优先救 黛琳达"}},{q="这部分搜寻之前是什么？",a="它接在瓦拉里尔的搜寻的第二部分之后。",al={"上一个任务","瓦拉里尔 前置任务","瓦拉里尔 搜寻任务链"}}},fp="19,228,24.343.0,19.417.1,23.99.0,46.124.0,56.124.0,41.52.0"}
P.entries["quest:1439"] = {n="寻找泰拉尼斯",s="黛琳达·玛雷姆告诉你，兽人杀光了他们的守卫和仆人，随后将她和泰拉尼斯带到了这里。泰拉尼斯曾试着与兽人交谈，而她在得知弟弟的下落之前，绝不肯离开。她请你找到他，查明他的命运后再回来。",h="黛琳达·玛雷姆告诉你，兽人杀光了他们的守卫和仆人，随后将她和泰拉尼斯带到了这里。泰拉尼斯曾试着与兽人交谈，而她在得知弟弟的下落之前，绝不肯离开。她请你找到他，查明他的命运后再回来。",kw={"火刃氏族","黛琳达","凄凉之地","马雷姆","坠饰","雷斧堡垒","泰拉尼斯","瓦拉里尔"},sec={{t="被掳走的弟弟",b="黛琳达告诉你，兽人杀光了他们的每一个守卫和仆人，随后将她和泰拉尼斯拖到了这里。她原以为自己会立刻被杀，兽人却显然另有打算。泰拉尼斯曾试着与他们交谈，也许是希望用自己的奥术学识打动他们，但她也说不清缘由。在查明弟弟的命运之前，她不肯逃走，因此请你找到他，得知结果后再回来。他就在堡垒入口左侧的一座建筑里。"},{t="黛琳达的恐惧",b="黛琳达害怕，只要有机会，泰拉尼斯就会探求火刃氏族的秘密，成为他们中的一员。力量一直吸引着他，正如所有受到魔法诱惑的人一样。对她的族人来说，哪怕只是研究这些东西，也是重罪。她怀疑，若要告诉家人他的灵魂曾触碰那样的危险，自己是否还有勇气面对他们。"},{t="黛琳达得知的真相",b="你回来后，黛琳达说，这件事虽然可怕，却非做不可。即使你没有动手，她的族人也会这么做。如果她的谢意听起来空洞无力，她请求你的原谅。得知弟弟的命运后，她已经准备好逃走，只要你仍然愿意，她就会接受你的帮助。"}},faq={{q="泰拉尼斯·玛雷姆是谁？",a="他是黛琳达的弟弟。他曾与俘虏他们的人交谈，也许是希望用奥术学识打动对方。她说，魔法的力量一直吸引着他。",al={"泰拉尼斯是谁","泰拉尼斯的身世","泰拉尼斯·玛雷姆"}},{q="黛琳达为什么还不肯离开？",a="在得知弟弟遭遇了什么之前，她不肯离开。她请你找到他，查明他的命运后再回来接她。",al={"黛琳达为何不肯离开","黛琳达为何留下","为何不立即逃走"}},{q="那些守卫和仆人怎么了？",a="兽人杀光了他们，随后活捉了黛琳达和泰拉尼斯，显然另有打算。",al={"他们的守卫怎么了","谁被杀了","守卫和仆人"}},{q="泰拉尼斯在哪里？",a="他在凄凉之地的雷斧堡垒里，就在进入堡垒时左手边的建筑中。",al={"泰拉尼斯在哪里","泰拉尼斯的位置"}},{q="这一步之前是什么任务？",a="这一步接在瓦拉里尔的搜寻的第三部分之后，在那一步中，瓦拉里尔派你去寻找黛琳达。",al={"前置任务是什么","任务流程","瓦拉里尔任务链"}}},fp="18,260,15.423.0,14.295.0,19.304.1,21.166.0,37.130.0,41.100.0,17.89.0,27.94.0"}
P.entries["quest:144"] = {n="送往西部荒野的信",s="在湖畔镇，所罗门镇长收到了西部荒野令人失望的答复。他曾请求格里安·斯托曼派兵保卫赤脊山，但西部荒野也有自己的难处。",h="在湖畔镇，所罗门镇长收到了西部荒野令人失望的答复。他曾请求格里安·斯托曼派兵保卫赤脊山，但西部荒野也有自己的难处。",kw={"格里安·斯托曼","湖畔镇","所罗门镇长","送往西部荒野的信","人民军","赤脊山","哨兵岭","西部荒野"},ang={["faction:Alliance"]="这些书信揭示了暴风要塞的统治者与外围行省之间的隔阂。西部荒野和赤脊山被迫独自抵御威胁。",["race:Human"]="作为一名人类旅者，你看到了各行省的城镇有多么孤立无援。平民与老兵流血奋战，保卫着暴风城贵族不愿保护的土地。"},sec={{t="跨越动荡边境的求援",b="所罗门镇长面对着赤脊山日益严峻的困境，却没有暴风城的皇家驻军相助。于是，他写信给西部荒野人民军的指挥官格里安·斯托曼，向南部边境求援。所罗门希望哨兵岭的志愿者能抽调一些战士，加强湖畔镇的防御。他并不知道西部平原的处境有多么艰难。"},{t="无奈的拒绝",b="格里安·斯托曼拒绝了请求，尽管这个答复让他心情沉重。西部荒野正在与迪菲亚潜行者和四处劫掠的豺狼人作战，因为贵族和王室已经抛弃了这片王国的粮仓。人民军为帮助人民生存而成立。队伍每天都在失去优秀的战士，斯托曼无法为赤脊山抽调哪怕一名战士。"},{t="王国疆土的裂痕",b="当你将斯托曼的回信带回湖畔镇时，所罗门意识到各处边境领地都遭到了同样的冷落。当地的行政官和民兵必须自行防御，而暴风城军队仍未获派出。所罗门转而向南，向暮色森林的夜色镇求援，希望能在那里找到援助。"}},faq={{q="所罗门镇长为何向西部荒野求援？",a="所罗门镇长寻求援助，是因为湖畔镇面临着日益严峻的威胁，却没有暴风城的军队相助。他知道格里安·斯托曼组织了人民军来保卫西部荒野，希望这支队伍能抽调士兵支援赤脊山。",al={"为何向西部荒野求援","所罗门致斯托曼的信","西部荒野为何成立民兵"}},{q="格里安·斯托曼为何拒绝派出援兵？",a="西部荒野已经在与迪菲亚潜行者和四处劫掠的豺狼人作战。斯托曼说，正是因为暴风城抛弃了西部荒野，民兵才会成立，如今已没有余力抽调战士。",al={"斯托曼为何拒绝","民兵拒绝湖畔镇","斯托曼的答复"}},{q="这些危机发生时，暴风城军队在哪里？",a="信中没有说明暴风城军队为何不在。所罗门和斯托曼只能猜测，究竟是什么让这支军队无法保卫外围行省。",al={"暴风城为何不援助","军队在哪里","暴风城的遗弃"}},{q="将斯托曼的信交还给所罗门后，会发生什么？",a="得知西部荒野无法提供帮助后，所罗门镇长转而向暮色森林求援。他派你前往夜色镇，希望埃伯洛克镇长麾下的守夜人能够提供援助。",al={"送往西部荒野的信后续任务","所罗门接下来做什么"}},{q="人民军是什么？",a="人民军是由格里安·斯托曼组织、驻扎在哨兵岭的一支志愿队伍。没有王室军队相助，当地的农民、老兵和居民便自行抵御匪徒和豺狼人，保卫西部荒野。",al={"人民军是谁","西部荒野民兵"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一名久经沙场的军人，领导着西部荒野的防御。他在哨兵岭的高塔中召集志愿者，指挥对抗迪菲亚潜行者的战斗。",al={"格里安·斯托曼的故事","斯托曼是谁"}}},fx={["84b4f9a5"]={q="格里安·斯托曼为什么派你去，而不派自己的民兵？",a="人民军为了保护西部荒野的农场，抵御迪菲亚潜行者和四处劫掠的豺狼人，已经到了人手的极限。斯托曼抽不出任何一名战士，向东长途跋涉，穿过艾尔文森林前往赤脊山。既然最初就是你带来了所罗门镇长的求援信，你已经在充当赤脊山的信使，也最适合把这封沉重的回信带回去。",al={"为何派我去","为何不派民兵传令","格里安为何需要信使"}}},fp="21,170,32.385.0,16.361.0,30.296.1,49.224.0,46.180.0,48.144.0,61.158.1,29.201.0,25.177.0"}
P.entries["quest:1440"] = {n="回复瓦拉里尔",s="黛琳达·玛雷姆已准备好离开雷斧堡垒。她感谢你为她和她的家人所做的一切，并说出发的时机由你决定。你护送她离开，然后找到瓦拉里尔·屠魔者。",h="黛琳达·玛雷姆已准备好离开雷斧堡垒。她感谢你为她和她的家人所做的一切，并说出发的时机由你决定。你护送她离开，然后找到瓦拉里尔·屠魔者。",kw={"黛琳达·玛雷姆","达纳苏斯","凄凉之地","护送","尼耶尔前哨站","雷斧堡垒","泰拉尼斯","瓦拉里尔"},sec={{t="离开堡垒",b="黛琳达问你是否该出发了，并感谢你为她和她的家人所做的一切，以免事情无法如愿。只要你准备好了，这里就没有什么能让她继续停留，你认为时机合适，她便会动身。你护送她离开雷斧堡垒，然后在凄凉之地找到瓦拉里尔·屠魔者。"},{t="瓦拉里尔的消息",b="瓦拉里尔向你道谢。黛琳达抵达尼耶尔前哨站时的状况远比瓦拉里尔所能期望的还要好，而她能凭自己的力量抵达，也是个好兆头。两个手足都未能归来，这让瓦拉里尔痛心，但等她回到达纳苏斯，泰拉尼斯的选择所带来的羞辱就得由她自己承受。"}},faq={{q="谁请求你护送她？",a="黛琳达·玛雷姆，只要你认为时机合适，她就准备离开雷斧堡垒。",al={"回复瓦拉里尔由谁提供","回复瓦拉里尔任务给予者","黛琳达·玛雷姆是谁"}},{q="从哪里开始？",a="在凄凉之地的雷斧堡垒，黛琳达就在那里。",al={"黛琳达·玛雷姆位置","黛琳达·玛雷姆在哪里","回复瓦拉里尔在哪里开始"}},{q="黛琳达脱险后，你要去找谁？",a="凄凉之地的瓦拉里尔·屠魔者。",al={"回复瓦拉里尔在哪里交","回复瓦拉里尔交给谁","回复瓦拉里尔终点"}},{q="这一步之前是什么？",a="这一步接在寻找泰拉尼斯之后，属于更长的瓦拉里尔的搜寻任务系列。",al={"回复瓦拉里尔前置任务","回复瓦拉里尔上一步","回复瓦拉里尔之前是什么任务"}}},fp="20,170,20.330.0,20.317.1,27.90.0,22.78.0,38.67.0,27.72.0"}
P.entries["quest:1442"] = {n="寻找科尔宝石",s="你远渡重洋，来到黑海岸，为乔丹·斯迪威尔寻找一颗科尔宝石。桑迪斯·织风派一位联盟的圣骑士学徒前往黑暗深渊，那里的纳迦用邪恶力量污染了这种强大的宝石。乔丹需要用它来锻造。",h="你远渡重洋，来到黑海岸，为乔丹·斯迪威尔寻找一颗科尔宝石。桑迪斯·织风派一位联盟的圣骑士学徒前往黑暗深渊，那里的纳迦用邪恶力量污染了这种强大的宝石。乔丹需要用它来锻造。",kw={"奥伯丁","黑暗深渊","黑海岸","乔丹·斯迪威尔","科尔宝石","纳迦","圣骑士","正义试炼","桑迪斯·织风"},ang={["class:Paladin"]="作为联盟的圣骑士，你将面对一场考验品格与毅力的试炼。它考验你是否愿意深入卡利姆多危机四伏的深处，为锻造一件受祝福的圣光武器出力。",["faction:Alliance"]="作为联盟的一员，你会看到一位人类铁匠借助暗夜精灵的智慧和矮人的钢铁，打造武器，对抗日益猖獗的黑暗。",["race:NightElf"]="作为暗夜精灵，你会看到桑迪斯·织风在古老的Kaldorei与来自东部王国、新近结盟的圣光信徒之间，架起一座脆弱却日渐稳固的桥梁。"},sec={{t="值得信赖的盟友",b="受训的圣骑士跨越大陆，来到黑海岸，为人类铁匠乔丹·斯迪威尔寻找所需的材料。在奥伯丁，暗夜精灵桑迪斯·织风提起这位铁匠时，仍怀着敬意。暗夜精灵一向与外人保持距离，一些堕落的人类也曾辜负他们的信任，但桑迪斯仍相信圣骑士能够遵循正义之道。他告诉他们，在哪里可以找到古老的宝石。"},{t="深入黑暗深渊",b="黑暗深渊位于灰谷西北部迷雾笼罩的海岸之下。暮光之锤教徒和阴险的海中生物盘踞在被水淹没的殿堂中。那里的纳迦女祭司通过古老的科尔宝石引导邪恶的魔法。你要寻找的宝石就在这片神殿建筑群深处，藏于幽暗的殿堂和危险的居民之间。"},{t="净化宝石",b="当你将一颗被污染的科尔宝石带回桑迪斯·织风身边时，他必须先清除其中的黑暗，乔丹·斯迪威尔才能将它锻造成神圣的武器。纳迦赋予宝石强大的原始魔力，却让它的附魔偏向邪恶。桑迪斯会净化这份污染，让宝石的力量保持纯净而稳定，用于接下来的神圣锻造仪式。"}},faq={{q="是谁派你寻找科尔宝石？",a="桑迪斯·织风是一位暗夜精灵，身在黑海岸的沿海港口奥伯丁，是他派圣骑士去寻找科尔宝石。他代表武器匠乔丹·斯迪威尔行事。",al={"寻找科尔宝石任务给予者","谁给予寻找科尔宝石任务","桑迪斯·织风任务"}},{q="科尔宝石在哪里？",a="科尔宝石就在黑暗深渊中，那是一座位于灰谷西北海岸的古老地下神殿。栖身于废墟中的纳迦女祭司携带着这些宝石。",al={"科尔宝石位置","哪里获取科尔宝石","被污染的科尔宝石在哪里"}},{q="乔丹·斯迪威尔为什么需要科尔宝石？",a="在圣骑士的正义试炼试炼中，乔丹·斯迪威尔需要用科尔宝石蕴含的强大魔力作为材料，打造他精制的武器。",al={"为什么需要科尔宝石","科尔宝石用途","斯迪威尔的宝石"}},{q="桑迪斯为什么必须净化宝石？",a="纳迦为科尔宝石注入了大量奥术能量，但他们邪恶的附魔也污染了这股力量。桑迪斯会净化宝石，让其中剩余的力量能够安全地用于一件圣光武器。",al={"为什么净化科尔宝石","被污染的科尔宝石净化","净化宝石"}},{q="桑迪斯为什么提到“堕落的同胞”？",a="桑迪斯很可能指的是人类的背叛，例如阿尔萨斯·米奈希尔王子堕入黑暗，让白银之手在整个艾泽拉斯的声誉蒙尘。即便如此，他仍会根据每位圣骑士自身的品行作出判断。",al={"堕落者是谁","桑迪斯堕落的同胞","堕落圣骑士所指"}},{q="获取科尔宝石需要组队吗？",a="桑迪斯告诫冒险者不要独自前往。黑暗深渊深处的精英纳迦携带着宝石，因此强烈建议组织一支专门的冒险队伍。",al={"科尔宝石能否单人获取","能否单人获取科尔宝石","黑暗深渊组队"}}},fp="19,223,18.381.0,14.318.0,19.332.1,34.169.0,29.156.0,40.144.0,41.167.0,42.203.0,37.145.0"}
P.entries["quest:1444"] = {n="向费泽鲁尔复命",s="一名流亡辛特兰的阿塔莱检查了送来的器物，认为它们并无危害。流放者对预言者迦玛兰有着更深的忧虑，而斯通纳德的费泽鲁尔需要听到这些消息。",h="一名流亡辛特兰的阿塔莱检查了送来的器物，认为它们并无危害。流放者对预言者迦玛兰有着更深的忧虑，而斯通纳德的费泽鲁尔需要听到这些消息。",kw={"阿塔莱流放者","费泽鲁尔","辛特兰","迦玛兰","斯通纳德","召唤仪式","阿塔哈卡神庙"},sec={{t="流放者的话",b="阿塔莱流放者曾认为预言者迦玛兰是一位称职的高阶祭司。但这位先知对预言的执迷，或许会让阿塔莱走向毁灭，甚至可能已经如此。流放者因直言进谏而被斥为异教徒，逐出了阿塔哈卡神庙。你带来的器物并无危害。流放者害怕的是，迦玛兰可能已经找到了适用于召唤仪式的神像附魔，这将使整个世界陷入极大的危险。斯通纳德的费泽鲁尔正等着听取这些消息。"}},faq={{q="我该去哪里与费泽鲁尔交谈？",a="费泽鲁尔在斯通纳德。",al={"费泽鲁尔位置","费泽鲁尔在哪里","提交 向费泽鲁尔复命"}},{q="阿塔莱流放者为何遭到放逐？",a="流放者曾直言质疑预言者迦玛兰对预言的执迷，认为这会毁灭阿塔莱。由于说出了这些忧虑，流放者被斥为异教徒，逐出了阿塔哈卡神庙。",al={"阿塔莱流放者为何被放逐","流放者为何在辛特兰","阿塔莱流放者背景"}},{q="带给流放者的器物有危险吗？",a="流放者说它们并无危害。令人担忧的是召唤仪式，以及迦玛兰是否已经找到了适用于这个仪式的神像附魔。",al={"器物有害吗","神像器物的危险"}}},fp="19,168,19.514.0,40.24.0,35.213.0,49.151.0"}
P.entries["quest:1447"] = {n="失踪的使节",s="你在暴风城寻找失踪的外交官，并在旧城区找到了达舍尔·石拳。你需要从这个宁愿守口如瓶的人口中问出答案。",h="你在暴风城寻找失踪的外交官，并在旧城区找到了达舍尔·石拳。你需要从这个宁愿守口如瓶的人口中问出答案。",kw={"斗殴","阴谋","达舍尔","失踪的外交官","旧城区","石拳","暴风城","打手"},ang={["class:Rogue"]="身为潜行者，你在逼问线人、打探街头情报时，要应付达舍尔·石拳这样的恶徒。",["faction:Alliance"]="身为联盟的一员，关于外交官失踪的每条线索，都可能揭露威胁领导层稳定的背叛行径。",["race:Human"]="身为人类，你看到暴风城的打手阻挠寻找失踪外交官的调查，威胁着王国的安全。"},sec={{t="旧城区的一场友好交谈",b="在旧城区，搜寻的线索带你穿过扒手和黑市掮客出没的地带，远离大教堂警惕的目光。达舍尔·石拳是当地的线人，与暴风城的犯罪势力有所勾连。他知道那起绑架的内情，却不愿向追问敏感问题的调查者透露半点消息。"},{t="巷中斗殴",b="你上前询问时，达舍尔·石拳拒绝配合。他想把你打倒，让调查就此终止，而旧城区里忠于他的打手也来助阵。等你制服达舍尔和他的手下，他便改了口，让你得以追查这场阴谋的下一条线索。"}},faq={{q="达舍尔·石拳是谁？",a="达舍尔·石拳是旧城区一个行事可疑的当地线人，与暴风城的地下犯罪势力有所勾连。对于城内的非法活动，他知道的远比透露出来的多。",al={"达舍尔·石拳","石拳是谁","达舍尔"}},{q="为什么我必须和达舍尔打一场，不能直接交谈？",a="达舍尔根本不想配合调查者。你问起失踪的外交官时，他以为轻易就能吓住你，便叫来打手让你闭嘴。只有狠狠教训他一顿，才能让他开口。",al={"为什么要和达舍尔战斗","能和石拳交谈吗","为什么要揍达舍尔"}},{q="我必须杀死达舍尔·石拳吗？",a="不用。你需要把达舍尔打到服软，而不是杀死他。当他的生命值降到足够低时，他就会认输，喝退手下，并答应回答你的问题。",al={"要杀死达舍尔吗","石拳活着","达舍尔死了吗"}},{q="这场战斗发生在哪里？",a="这场战斗发生在旧城区的露天场地，靠近猪和哨声旅店后方的小巷和当地的训练大厅，达舍尔·石拳平时就在这一带出没。",al={"石拳位置","达舍尔在哪里","旧城区斗殴"}},{q="打败达舍尔后会发生什么？",a="你击败达舍尔后，他会道歉，并答应说出自己所知的阴谋内情。他指引你前往都城之外，追查下一个环节。",al={"打败达舍尔后做什么","石拳后续任务","外交官任务线后续"}},{q="“失踪的使节”任务线究竟讲述了什么？",a="寻找失踪大使的过程中，一张围绕外交官遭绑架一事及其幕后神秘人物编织的欺诈之网逐渐浮现。",al={"失踪的外交官背景故事","外交官是谁","失踪的国王"}}},fx={c22a58c4={q="这场冲突中，你要与谁交战？",a="你要对付达舍尔·石拳，以及他手下两名来自旧城区的壮硕打手。达舍尔在旧城区混乱的小巷中活动，身边围着当地的恶棍，替他干脏活，恐吓那些打探不该打探之事的人。达舍尔不愿回答有关他非法勾当的问题，而是叫来同伙，要把你打得再也无法开口，让你永远走不出这座城。",al={"失踪的使节中与谁交战","谁与达舍尔一起攻击","失踪的使节第八步的目标"}},["15b1a9ee"]={q="达舍尔·石拳为什么攻击你？",a="达舍尔不希望有人追问失踪的使节，也不希望有人打听他那些见不得光的关系。他在旧城区的阴影中活动，靠保密、恐吓和武力生存。你逼他回答时，他把你当作一个多管闲事、容易下手的探子，指望手下的打手在他参与更黑暗阴谋的事情败露之前，让你永远闭嘴。",al={"达舍尔·石拳为何动手","达舍尔为何攻击","达舍尔·石拳的动机"}}},fp="20,149,27.304.0,18.260.1,24.173.0,61.224.0,35.163.0,33.166.0,34.164.1,50.126.2"}
P.entries["quest:145"] = {n="送往夜色镇的信",s="在湖畔镇，所罗门镇长向夜色镇发出紧急求援。黑石兽人和豺狼人威胁着赤脊山，所罗门转而向邻镇寻求军事支援。一名信使必须穿过暮色森林阴暗的道路，将信送到夜色镇镇长艾尔罗·埃伯洛克公爵手中。",h="在湖畔镇，所罗门镇长向夜色镇发出紧急求援。黑石兽人和豺狼人威胁着赤脊山，所罗门转而向邻镇寻求军事支援。一名信使必须穿过暮色森林阴暗的道路，将信送到夜色镇镇长艾尔罗·埃伯洛克公爵手中。",kw={"夜色镇","暮色森林","埃伯洛克","湖畔镇","信使","守夜人","赤脊山","所罗门"},ang={["faction:Alliance"]="所罗门的紧急书信表明，在暴风城王廷陷入瘫痪之际，偏远的联盟城镇受到了何等冷落。",["race:Human"]="身为人类，你与南方的人类聚居地有着共同的困境，王国撤回正规军巡逻队后，这些地方只能依靠当地民兵。"},sec={{t="迫切的求援",b="黑石兽人和豺狼人群给赤脊山带来的压力与日俱增，湖畔镇的卫兵已疲于应付。暴风城王廷对所罗门镇长的求援置之不理，而西部荒野也深陷自身的叛乱。附近几乎无援可求，所罗门便写信给暮色森林的埃伯洛克镇长，希望夜色镇能借调守夜人，或允许雇用他们，以加强湖畔镇的防御。"},{t="通往阴霾的道路",b="所罗门的信必须向南送往暮色森林，那片森林笼罩在超自然的阴霾之下。他警告你沿着道路走，因为湖畔镇和夜色镇之间的荒野危机四伏。这封信要送到大厅，埃伯洛克公爵会在那里收信。至于暮色森林能否抽调兵力，就是另一回事了。"}},faq={{q="湖畔镇为什么向夜色镇求援？",a="暴风城迟迟不肯正式出兵援助，让湖畔镇独自面对黑石兽人等威胁。所罗门镇长正在向附近的盟友求援，希望夜色镇的守夜人能借调训练有素的战士。",al={"为何向暮色森林求援","为何向夜色镇求援","所罗门向夜色镇求援"}},{q="艾尔罗·埃伯洛克公爵是谁？",a="艾尔罗·埃伯洛克公爵是夜色镇的镇长，也是暮色森林一位重要的平民领袖。他在大厅主持镇务，并与率领守夜人的指挥官阿尔泰娅·埃伯洛克协调民政事务。",al={"埃伯洛克","埃伯洛克是谁","夜色镇镇长"}},{q="守夜人是什么组织？",a="守夜人是夜色镇独立的平民武装。没有暴风城的驻军，他们便在镇子周边巡逻，与暮色森林中的亡灵、野兽和暗影作战。",al={"暮色森林守夜人","守夜人是谁"}},{q="所罗门为什么警告我要沿着道路走？",a="暮色森林的荒野中潜藏着恐怖的亡灵、蜘蛛和凶猛的野兽。离开铺好的道路，就会让你落入捕食者和伏击者的攻击范围。",al={"暮色森林道路警告","暮色森林沿道路走"}},{q="这条任务线从哪里开始？",a="所罗门镇长的一连串紧急书信，始于他向西部荒野的格里安·斯托曼发出的求援。他仍在继续为湖畔镇寻求援助。",al={"前置任务","信使任务顺序"}},{q="夜色镇真的有多余的卫兵可派吗？",a="暮色森林也面临着自身的危机，死者复起，狼人肆虐，怪物潜伏。守夜人的战士勉强够守卫夜色镇，因此所罗门的求援希望渺茫。",al={"夜色镇会援助吗","埃伯洛克会派卫兵吗"}}},fp="22,269,24.368.0,23.314.0,43.219.0,27.211.0,24.179.0,46.142.0,31.141.0,45.187.0"}
P.entries["quest:1450"] = {n="狮鹫管理员",s="弗斯塔德·蛮锤不愿谈论那位探险者协会老友曾与谁一同飞行，便打发你去问狮鹫管理员。狮鹫管理员沙拉克·鹰斧正在鹰巢山的狮鹫舍里等候。",h="弗斯塔德·蛮锤不愿谈论那位探险者协会老友曾与谁一同飞行，便打发你去问狮鹫管理员。狮鹫管理员沙拉克·鹰斧正在鹰巢山的狮鹫舍里等候。",kw={"鹰巢山","狮鹫舍","布罗哈恩·铁桶","探险者协会","弗斯塔德·蛮锤","狮鹫管理员沙拉克·鹰斧","拉普索迪·铁铲","奥达曼"},sec={{t="被打发走",b="弗斯塔德·蛮锤没有耐心招呼替一位探险者协会老成员跑腿的人。弗斯塔德不知道那位朋友曾与谁一同飞行，飞行任务的安排得去问狮鹫管理员。狮鹫管理员沙拉克·鹰斧就在鹰巢山的狮鹫舍里，要是继续在弗斯塔德身边逗留，可就真有活儿要干了。"},{t="鹰斧的回忆",b="鹰斧记得曾派一名狮鹫骑士去帮助布罗哈恩·铁桶，而且一直对探险者协会颇有好感，因为鹰斧的父亲曾协助第一支发现奥达曼的挖掘队。那名骑士就是拉普索迪·铁铲，鹰斧当时认为他是最出色的。"}},faq={{q="弗斯塔德·蛮锤为什么让你去找鹰斧？",a="弗斯塔德不知道那位探险者协会的朋友曾与谁一同飞行，便指引你去找负责安排飞行任务的狮鹫管理员。",al={"为什么找鹰斧","弗斯塔德打发人走","鹰斧是谁"}},{q="狮鹫管理员沙拉克·鹰斧在哪里？",a="狮鹫管理员沙拉克·鹰斧在鹰巢山的狮鹫舍里。",al={"鹰斧在哪里","鹰斧位置","鹰巢山狮鹫舍"}}},fp="23,189,9.313.0,23.286.1,49.147.0,41.59.0"}
P.entries["quest:1451"] = {n="拉普索迪·铁铲",s="狮鹫管理员鹰斧说起了拉普索迪·铁铲。拉普索迪曾是鸟舍最出色的飞行员，却因嗜酒如命而不得不被解雇。鹰斧听说，拉普索迪如今在辛特兰的鸟舍以东经营着一处酿酒营地。",h="狮鹫管理员鹰斧说起了拉普索迪·铁铲。拉普索迪曾是鸟舍最出色的飞行员，却因嗜酒如命而不得不被解雇。鹰斧听说，拉普索迪如今在辛特兰的鸟舍以东经营着一处酿酒营地。",kw={"鹰巢山","鸟舍","布罗哈恩","狮鹫管理员鹰斧","辛特兰","拉普索迪·铁铲"},sec={{t="堕落的飞行员",b="鹰斧强调，鸟舍的矮人都爱喝上好的麦酒，但拉普索迪迷上烈酒，就像狮鹫迷恋天空一样。没人能像拉普索迪那样飞行，在鹰斧看来，这实在太可惜了。最初的麻烦出现在拉普索迪与布罗哈恩出行归来时，拉普索迪脚步踉跄，此后情况便急转直下。最终，拉普索迪不得不被解雇。据最新消息，鹰巢山以东如今有了一处酿酒营地。"}},faq={{q="谁派你去寻找拉普索迪·铁铲？",a="鹰巢山鸟舍的狮鹫管理员鹰斧指引你去找拉普索迪。",al={"谁开启拉普索迪·铁铲任务","谁提供拉普索迪任务","哪里开始拉普索迪任务"}},{q="拉普索迪·铁铲为什么被鸟舍解雇？",a="拉普索迪迷上烈酒，就像狮鹫迷恋天空一样。最初的麻烦出现在与布罗哈恩一同飞行归来时，拉普索迪脚步踉跄，此后情况迅速恶化，鹰斧只好将拉普索迪解雇。",al={"拉普索迪为何被解雇","拉普索迪出了什么事","拉普索迪·铁铲背景故事"}},{q="拉普索迪现在在哪里？",a="鹰斧听说，拉普索迪如今在辛特兰的鸟舍以东经营着一处酿酒营地。",al={"拉普索迪·铁铲在哪里","拉普索迪营地位置","如何找到拉普索迪"}}},fp="19,238,14.423.0,42.76.0,51.198.0,22.94.0"}
P.entries["quest:1452"] = {n="拉普索迪的卡利姆多鸡尾酒",s="身在辛特兰的拉普索迪·铁铲只有喝上烈酒，才肯谈起沼泽里发生的事。调制卡利姆多 鸡尾酒 需要塔纳利斯的大鹏砂囊，以及菲拉斯的格罗多克肝脏和铁鬃肝脏。",h="身在辛特兰的拉普索迪·铁铲只有喝上烈酒，才肯谈起沼泽里发生的事。调制卡利姆多 鸡尾酒 需要塔纳利斯的大鹏砂囊，以及菲拉斯的格罗多克肝脏和铁鬃肝脏。",kw={"布罗哈恩","菲拉斯","格罗多克 肝脏","铁鬃 肝脏","卡利姆多 鸡尾酒","拉普索迪·铁铲","大鹏 砂囊","塔纳利斯"},sec={{t="一杯烈酒",b="拉普索迪打着酒嗝，迎接布罗哈恩派来的信使。他们两人经历了一场惊险的冒险，而沼泽里发生的那番不堪回首的情景，只有喝上烈酒才说得出口。拉普索迪心里已经有了配方，就是卡利姆多 鸡尾酒，并答应只要酒调好了，就把一切都说出来。"},{t="卡利姆多的原料",b="调制这种酒需要三个塔纳利斯的大鹏砂囊、三个菲拉斯的格罗多克肝脏，以及三个同样来自菲拉斯的铁鬃肝脏。就连拉普索迪最好的麦芽酒，也不够烈，不足以让他面对那次飞越沼泽的可怕经历。"}},faq={{q="拉普索迪要用什么调制卡利姆多 鸡尾酒？",a="三个大鹏砂囊、三个格罗多克肝脏和三个铁鬃肝脏。拉普索迪想先喝上一杯烈酒，才肯谈起沼泽里发生的事。",al={"为什么要 鸡尾酒","为什么要 大鹏 砂囊","为什么要肝脏"}},{q="这些原料来自哪里？",a="大鹏砂囊来自塔纳利斯。格罗多克肝脏和铁鬃肝脏来自菲拉斯。",al={"哪里找砂囊","鸡尾酒原料位置","格罗多克 在哪里"}},{q="是谁派你去找拉普索迪·铁铲的？",a="是布罗哈恩派你来的，拉普索迪称他为疯子。在那之前，狮鹫管理员鹰斧告诉了你在哪里能找到拉普索迪。",al={"谁派我去找 拉普索迪","前置任务","布罗哈恩"}}},fp="28,214,13.292.0,25.213.0,50.178.0,35.85.0,36.142.0"}
P.entries["quest:1453"] = {n="寻物公司的业务",s="罗顿·石锤派遣旅行者从铁炉堡远渡重洋，前往凄凉之地，为寻物公司做些有偿的工作。在尼耶尔前哨站，克雷迪格·安戈尔需要人手，帮忙找回遗失的财宝和遗物。",h="罗顿·石锤派遣旅行者从铁炉堡远渡重洋，前往凄凉之地，为寻物公司做些有偿的工作。在尼耶尔前哨站，克雷迪格·安戈尔需要人手，帮忙找回遗失的财宝和遗物。",kw={"半人马","凄凉之地","铁炉堡","克雷迪格·安戈尔","尼耶尔前哨站","寻物公司","罗顿·石锤","石爪山脉"},ang={["faction:Alliance"]="尼耶尔前哨站是联盟在卡利姆多中部西侧荒原上的主要庇护所。敌对的半人马氏族环伺四周。",["race:Dwarf"]="身为矮人，即使在卡利姆多最荒凉的角落，你也能找到矮人经营的事业，从探险者协会到寻物公司这样的独立回收团体。"},sec={{t="荒原的召唤",b="大海彼岸的凄凉之地是卡利姆多的一片险恶之地，由相互征战的半人马氏族统治。寻物公司在这里被遗忘的废墟与荒地中寻求利益。对于愿意直面危险的人来说，这趟旅程或许能带来丰厚的报酬。"},{t="尼耶尔前哨站与寻物公司",b="这条路线向西穿过石爪山脉，进入凄凉之地北部。尼耶尔前哨站是一座高踞峭壁间的联盟哨站，克雷迪格·安戈尔在这里欢迎新帮手的到来。寻物公司找回散落在这个饱受战火蹂躏的世界各地的传家宝、魔法物品和家族财宝。只要价钱合适，克雷迪格和他的同伴就会从荒野中取回这些贵重物品。"}},faq={{q="谁提供这个任务？",a="罗顿·石锤在铁炉堡提供有偿的工作，并派你远渡重洋，去见他在卡利姆多的同伴。",al={"任务给予者","谁提供寻物公司的业务任务","罗顿·石锤位置"}},{q="尼耶尔前哨站在哪里？",a="尼耶尔前哨站位于凄凉之地东北部的峭壁之间。从石爪山脉向南进入凄凉之地，再沿着峭壁向东走，就能找到通往这座联盟哨站的上山小径，沿途有火把照明。",al={"寻找尼耶尔前哨站","如何前往尼耶尔前哨站","尼耶尔前哨站位置"}},{q="寻物公司是什么组织？",a="寻物公司是由克雷迪格·安戈尔这样的矮人干员领导的营利组织。他们受客户雇用，从危险的地方找回遗失的传家宝、古物和魔法遗物。",al={"寻物公司是什么","寻物公司阵营","寻物公司背景故事"}},{q="凄凉之地有哪些威胁？",a="凄凉之地是石爪山脉另一侧的一片干旱荒原，相互征战的半人马部族、亡灵残部和凶猛的野生动物威胁着这里的旅行者。",al={"凄凉之地的危险","凄凉之地有什么"}},{q="克雷迪格·安戈尔是谁？",a="克雷迪格·安戈尔是凄凉之地尼耶尔前哨站的一名矮人。他在这一带组织回收和搜寻遗物的工作，招募有能力的旅行者，前往废墟和半人马营地冒险。",al={"克雷迪格·安戈尔背景故事","克雷迪格是谁"}},{q="在凄凉之地做任务必须先完成这个任务吗？",a="不必。你可以不经罗顿·石锤指引，直接前往尼耶尔前哨站，不过他会在你出发前介绍背景并指明道路。",al={"这个任务是否必做","寻物公司的业务是否必做"}}},fx={["7014e979"]={q="罗顿·石锤为什么派你去凄凉之地？",a="罗顿·石锤在安全的铁炉堡担任寻物公司的联络人。他在尼耶尔前哨站的同伴身处凄凉之地的险境，需要沉着可靠、能力出众的人手来承接委托。罗顿把你这样能干的冒险者引荐给克雷迪格·安戈尔，确保他们的寻宝团即使身处危机四伏的半人马领地，也依然人手充足、有利可图。",al={"为何派往凄凉之地","罗顿·石锤的动机","为何帮助克雷迪格·安戈尔"}},f82b8baa={q="罗顿·石锤为什么招募冒险者，而不亲自前往？",a="经营一支跨越大陆的寻宝队，既需要在野外干活的人手，也同样需要大城市里的耳目。罗顿留在铁炉堡，指引新来的人才，牵线寻找机会，把穿越石爪山脉的艰苦跋涉和凄凉之地的重重危险，留给那些身经百战、愿意为钱冒险的旅人。",al={"罗顿为何需要我","为何不亲自去","为何招募冒险者"}}},fp="32,193,23.222.0,32.374.0,21.113.0,23.194.0,23.181.0,31.144.0,21.181.0,44.127.0"}
P.entries["quest:1454"] = {n="卡尼托的海难",s="克雷迪格·安戈尔向你提起了卡尼托，一位在暴风城似乎有些贵族身份的法师。海巨人在凄凉之地西北海域袭击了他的船，他丢下一个贵重的箱子，传送离开了。需要找到那个箱子和里面的东西。",h="克雷迪格·安戈尔向你提起了卡尼托，一位在暴风城似乎有些贵族身份的法师。海巨人在凄凉之地西北海域袭击了他的船，他丢下一个贵重的箱子，传送离开了。需要找到那个箱子和里面的东西。",kw={"凄凉之地","艾瑟雷索","卡尼托","克雷迪格·安戈尔","寻物公司","海巨人","船难","暴风城"},sec={{t="贵族的逃离",b="在凄凉之地完成寻物公司的业务后，克雷迪格·安戈尔告诉你，有件事需要先办。此事与卡尼托有关，他是一位在暴风城似乎有些贵族身份的法师。海巨人在凄凉之地西北海域袭击了卡尼托的船。卡尼托和仆人们试图把他较为贵重的一个箱子搬到岸上，但海巨人蜂拥而至，他只得放弃箱子，施法将自己和仆人们传送走。需要找到箱子和里面的东西，再送还给暴风城的卡尼托。箱子就在北部海岸线的艾瑟雷索一带。"},{t="箱子上的痕迹",b="箱子没有被水浸坏的迹象，但箱盖已被强行打开，边缘的烧灼痕迹表明，守护箱子的魔法陷阱早已被触发。"}},faq={{q="卡尼托是谁？",a="一位在暴风城似乎有些贵族身份的法师。海巨人在凄凉之地西北海域袭击了他的船。",al={"卡尼托","卡尼托是谁","谁想要箱子"}},{q="卡尼托的船出了什么事？",a="海巨人在凄凉之地西北海域袭击了那艘船。卡尼托和仆人们试图把一个贵重的箱子搬到岸上，但海巨人蜂拥而至，他只得丢下箱子，带着仆人们传送离开。",al={"船难故事","船为何沉没","海巨人袭击"}},{q="谁在寻找箱子？",a="克雷迪格·安戈尔，他说卡尼托希望有人找到箱子和里面的东西，并送还给暴风城的他。",al={"谁提供任务","克雷迪格·安戈尔的作用"}},{q="箱子在哪里？",a="在凄凉之地北部海岸线的艾瑟雷索一带。",al={"卡尼托的箱子位置","卡尼托的箱子在哪","艾瑟雷索的箱子"}}},fp="22,150,16.527.0,20.148.1,16.114.0,33.217.0,29.122.0,25.80.0"}
P.entries["quest:1455"] = {n="卡尼托的海难",s="法师卡尼托的箱子被撬开了，里面空空如也。箱子侧面和顶部又长又深的抓痕表明，这既非人类所为，也非巨人所为，你便返回尼耶尔前哨站，向克雷迪格·安戈尔复命。",h="法师卡尼托的箱子被撬开了，里面空空如也。箱子侧面和顶部又长又深的抓痕表明，这既非人类所为，也非巨人所为，你便返回尼耶尔前哨站，向克雷迪格·安戈尔复命。",kw={"凄凉之地","卡尼托","卡尼托的箱子","克雷迪格·安戈尔","尼耶尔前哨站","沉船"},sec={{t="空箱子",b="你仔细查看箱子被强行打开的痕迹。箱子侧面和顶部布满了又长又深的抓痕。这些痕迹表明，动手的既不是人类，也不是巨人，而且看起来也不像是匕首或剑留下的。箱子里空空如也。既然再无他事可做，你便合上箱子，准备离开，心知克雷迪格·安戈尔会很失望。"}},faq={{q="卡尼托的箱子里有什么？",a="什么也没有。箱子里空空如也。",al={"卡尼托的箱子里有什么","卡尼托的箱子是空的吗","箱内物品"}},{q="箱子上的痕迹是什么留下的？",a="箱子侧面和顶部布满了又长又深的抓痕。这些痕迹表明，这既非人类所为，也非巨人所为，而且看起来也不像是匕首或剑留下的。",al={"什么打开了箱子","谁拿走了货物","箱子上的爪痕"}},{q="你要向谁复命？",a="克雷迪格·安戈尔，他在凄凉之地的尼耶尔前哨站。",al={"向谁交任务","克雷迪格·安戈尔在哪里","接下来去哪里"}},{q="在这之前发生了什么？",a="克雷迪格·安戈尔委托你寻找卡尼托的箱子。",al={"前置任务","卡尼托沉船任务链"}}},fp="22,144,14.281.0,32.60.0,33.142.0,21.57.0,22.68.0"}
P.entries["quest:1456"] = {n="卡尼托的海难",s="克雷迪格·安戈尔仍然认为能找到卡尼托的物品。沿着同一片海岸往北，在拉纳加尔岛附近，滑刃纳迦占据了海底暗夜精灵遗迹中的一处地方，克雷迪格·安戈尔认为背包最有可能就在那里。",h="克雷迪格·安戈尔仍然认为能找到卡尼托的物品。沿着同一片海岸往北，在拉纳加尔岛附近，滑刃纳迦占据了海底暗夜精灵遗迹中的一处地方，克雷迪格·安戈尔认为背包最有可能就在那里。",kw={"凄凉之地","卡尼托","克雷迪格·安戈尔","拉纳加尔岛","寻物公司","背包","海巫","滑刃","潮汐猎手"},sec={{t="深海遗迹",b="在卡尼托沉船搜寻的第二阶段之后，克雷迪格·安戈尔告诉你，希望尚未破灭。沿着同一片海岸继续向北，拉纳加尔岛附近的海底有一片沉没的暗夜精灵遗迹，滑刃纳迦以此为家。克雷迪格·安戈尔判断，那里最有可能找到卡尼托的背包。你会获得一瓶打捞潜水药水。"},{t="更强大的纳迦",b="克雷迪格·安戈尔认为，能向南深入这么远的侦察队，实力一定很强。因此，要寻找卡尼托的物品，克雷迪格·安戈尔会先从更强大的纳迦入手，也就是潮汐猎手和海巫。"}},faq={{q="谁让你寻找卡尼托的背包？",a="凄凉之地的克雷迪格·安戈尔。",al={"谁提供这个任务","卡尼托背包任务给予者","克雷迪格·安戈尔是谁"}},{q="克雷迪格·安戈尔认为物品在哪里？",a="沿海岸向北，在拉纳加尔岛附近沉没的暗夜精灵遗迹中，滑刃纳迦以那里为家。",al={"卡尼托的背包在哪里","背包位置","滑刃纳迦在哪里"}},{q="克雷迪格·安戈尔建议先搜查哪些纳迦？",a="潮汐猎手和海巫，也就是更强大的纳迦。克雷迪格·安戈尔认为，能向南深入这么远的侦察队，实力一定很强。",al={"背包在谁手里","哪些纳迦拿着背包","潮汐猎手还是海巫"}},{q="这之前是什么？",a="这之前是卡尼托沉船搜寻的第二阶段。",al={"卡尼托沉船任务链","前置任务是什么"}}},fp="22,202,17.318.0,17.159.0,40.62.0,44.160.0,48.150.0,22.66.0"}
P.entries["quest:1457"] = {n="卡尼托的背包",s="克雷迪格·安戈尔让你带着卡尼托的背包前往铁炉堡，交给罗顿·石锤，他会为你的工作支付报酬。",h="克雷迪格·安戈尔让你带着卡尼托的背包前往铁炉堡，交给罗顿·石锤，他会为你的工作支付报酬。",kw={"凄凉之地","铁炉堡","卡尼托","卡尼托的背包","克雷迪格·安戈尔","寻物公司","罗顿·石锤"},sec={{t="返回铁炉堡",b="克雷迪格·安戈尔让你把卡尼托的东西带回铁炉堡，交给罗顿·石锤，他会为你的工作支付报酬。克雷迪格笑着补充说，罗顿说不定会高兴得邀请你正式加入寻物公司。回去的路上要小心，也别耽搁，因为卡尼托虽然为人慷慨，却没什么耐心。"},{t="在铁炉堡",b="罗顿·石锤对你在凄凉之地处理卡尼托事务的结果表示满意。箱子本身虽然毁了，但里面的东西都在，罗顿把这件事留给卡尼托自己评判。人们指望寻物公司找回失物，而不是保证东西送回来时依然光鲜完好。随后，罗顿便着手为你支付报酬。"}},faq={{q="我该把卡尼托的背包交给谁？",a="铁炉堡的罗顿·石锤。",al={"背包送到哪里","交付卡尼托沉船任务","卡尼托的背包交给谁"}},{q="是谁让我返回铁炉堡的？",a="克雷迪格·安戈尔，他对你完成的工作赞赏有加。",al={"谁发布任务","卡尼托沉船第四部分任务发布者"}},{q="为什么要尽快送达背包？",a="克雷迪格说，卡尼托虽然十分慷慨，却没什么耐心。",al={"为什么要赶回铁炉堡","卡尼托有耐心吗"}},{q="罗顿·石锤是谁？",a="寻物公司在铁炉堡的负责人。他的生意十分兴隆，小事都交给手下处理。",al={"罗顿·石锤的故事","罗顿是谁"}}},fp="22,98,17.314.0,12.292.1,39.63.0,31.64.0,51.70.0,27.134.0"}
P.entries["quest:1458"] = {n="寻物公司的委托",s="克雷迪格·安戈尔正在为住在卡拉诺斯的侏儒法师莱弗维奇收集材料，而寻物公司人手不足。他要先拿到东边怨怒萨特的爪子和角，才能着手收集清单上的其余材料。",h="克雷迪格·安戈尔正在为住在卡拉诺斯的侏儒法师莱弗维奇收集材料，而寻物公司人手不足。他要先拿到东边怨怒萨特的爪子和角，才能着手收集清单上的其余材料。",kw={"凄凉之地","怨怒","卡拉诺斯","克雷迪格·安戈尔","莱弗维奇","寻物公司","罗顿","萨格隆","萨特"},sec={{t="莱弗维奇的清单",b="在凄凉之地的寻物公司的业务之后，克雷迪格·安戈尔手头又多了一份差事：为住在卡拉诺斯的侏儒法师莱弗维奇收集材料。罗顿觉得这钱很容易赚，毕竟寻物公司已经在凄凉之地了，而克雷迪格说，他并不在乎队伍人手不足。"},{t="角与爪子",b="清单上的头几样东西应该不难收集。克雷迪格要东边怨怒萨特的十只爪子和十只角，这些萨特就在尼耶尔前哨站正东边的萨格隆废墟里。等这些东西到手，就可以着手收集清单上的其余材料了。"}},faq={{q="是谁要这些材料？",a="克雷迪格·安戈尔正在为一位名叫莱弗维奇的侏儒法师收集这些材料，他住在卡拉诺斯。罗顿觉得这钱很容易赚，毕竟寻物公司已经在凄凉之地了。",al={"莱弗维奇是谁","寻物公司的委托任务给予者","谁要这些材料"}},{q="怨怒萨特在哪里？",a="怨怒萨特就在萨格隆废墟里，位于尼耶尔前哨站正东边。",al={"怨怒萨特位置","怨怒的爪子在哪里","怨怒的角位置"}},{q="克雷迪格要从萨特身上收集什么？",a="十只怨怒的爪子和十只怨怒的角。拿到这些之后，你和他就能继续收集莱弗维奇清单上的后几样材料了。",al={"需要收集什么","寻物公司的委托任务物品","需要的萨特身体部位"}},{q="克雷迪格怎么看待萨特？",a="他称它们为卑鄙的生物。他听说它们与暗夜精灵有某种联系，不过他对此心存怀疑。在他看来，这种说法源于几年前那个把它们带入战争的精灵，而从那以后，这个世界就变得更加危险，也更加可怕了。",al={"克雷迪格的萨特传闻","萨特是暗夜精灵吗"}}},fp="28,189,16.282.0,15.217.0,33.156.0,38.73.0,39.134.0,37.290.0"}
P.entries["quest:1459"] = {n="寻物公司的委托",s="莱弗维奇给克雷迪格·安戈尔的清单上，接下来要收集的是scorpashi的毒液和老迈科多兽的皮。克雷迪格说不出这两样东西该去哪里找，因为他对凄凉之地并不熟悉。",h="莱弗维奇给克雷迪格·安戈尔的清单上，接下来要收集的是scorpashi的毒液和老迈科多兽的皮。克雷迪格说不出这两样东西该去哪里找，因为他对凄凉之地并不熟悉。",kw={"老迈科多兽的皮","凄凉之地","铁炉堡","克雷迪格·安戈尔","莱弗维奇","寻物公司","毒蝎毒液"},sec={{t="接下来的材料",b="完成莱弗维奇清单上的第一部分后，克雷迪格·安戈尔开始着手收集接下来的材料。这些东西看起来并不难找，但要求很明确。这位法师要的是scorpashi的毒液，哪一种都行，还要科多兽的皮，但必须来自老迈的科多兽。濒死和上古科多兽的皮都不行。克雷迪格需要七瓶毒液和三张皮。克雷迪格心想，法师要的东西还真是古怪。"},{t="陌生的土地",b="克雷迪格不知道科多兽和scorpashi在哪里出没。克雷迪格对这一带几乎一无所知，也一直没有时间四处探索。"}},faq={{q="是谁要这些材料？",a="是一位名叫莱弗维奇的法师，克雷迪格·安戈尔正在照着他的清单收集材料。",al={"谁要材料","莱弗维奇是谁","克雷迪格的上司"}},{q="为什么克雷迪格需要别人帮忙寻找这些生物？",a="克雷迪格对凄凉之地几乎一无所知，也一直没有时间四处探索，所以说不出科多兽和巨钳蝎在哪里出没。",al={"克雷迪格为什么无法收集材料","克雷迪格对当地的了解"}},{q="任何科多兽的皮都能用吗？",a="不能。莱弗维奇明确要求只收老迈科多兽的皮；濒死和上古科多兽的皮都不算。",al={"任何科多兽的皮","上古科多兽的皮","濒死科多兽的皮"}},{q="巨钳蝎是什么？",a="它们是遍布凄凉之地的蝎子。莱弗维奇说，哪一种的毒液都能用。",al={"巨钳蝎毒液","巨钳蝎在哪里"}},{q="老迈的科多兽在哪里出没？",a="它们成群沿着小径游荡，主要在南部和西部，许多最终会来到科多兽坟场附近。",al={"老迈科多兽的位置","老迈的科多兽在哪里"}}},fp="28,162,14.258.0,17.117.0,33.66.0,51.115.0,32.76.0,23.97.0,28.96.0"}
P.entries["quest:146"] = {n="送往夜色镇的信",s="在夜色镇，艾尔罗·埃伯洛克公爵回应了湖畔镇的求援。黑石兽人和豺狼人正向镇子逼近，但他无法答应援助。",h="在夜色镇，艾尔罗·埃伯洛克公爵回应了湖畔镇的求援。黑石兽人和豺狼人正向镇子逼近，但他无法答应援助。",kw={"夜色镇","埃伯洛克","湖畔镇","信使","守夜人","所罗门","暴风城"},ang={["faction:Alliance"]="对联盟而言，这封信揭露了南方王国深刻的裂痕。边远的城镇遭到遗弃，无力自保。",["race:Human"]="身为人类旅行者，你能看到，在王室的漠视下，王国的城镇已变得何等孤立。"},sec={{t="绝境中的求援遭拒",b="赤脊山的所罗门镇长向暮色森林的一位老同僚请求援兵。黑石兽人和豺狼人正向他的镇子逼近。艾尔罗·埃伯洛克公爵愤怒地作出了回应。夜色镇正艰难抵御来自四面八方的活死人、饥饿的野兽和诅咒魔法。埃伯洛克说，正是因为暴风城抛弃了暮色森林，才有了守夜人。失去守卫，夜色镇还等不到一支巡逻队穿过森林就会陷落。"},{t="接连遭弃的城镇",b="所罗门镇长读完埃伯洛克的回信，看出王国各地都在接连撤防。暴风城的军队撤离了西部荒野，夜色镇被迫自保，湖畔镇的求援也始终无人回应。王国各地的领袖私下议论，这或许不只是疏忽或无能所致。如今，所罗门也不得不面对他们的猜疑：暴风城的核心有人背叛了王国。"}},faq={{q="为什么埃伯洛克领主不派守夜人援助湖畔镇？",a="夜色镇遭到亡灵、野兽和邪恶巫术的围困。守夜人是暴风城撤走驻军后组建的地方民兵。如果埃伯洛克把守卫派往赤脊山，他们还没穿过森林，夜色镇就会陷落。",al={"埃伯洛克为何拒绝","为何不派守夜人援助湖畔镇","夜色镇拒绝援助"}},{q="所罗门镇长读完回信后意识到了什么？",a="所罗门看出，湖畔镇的困境是整个王国危机的一部分。军队已经撤离西部荒野，夜色镇也被迫独自防守。他怀疑暴风城的统治者中有人背叛，而不只是疏于照管。",al={"所罗门的反应","所罗门意识到了什么"}},{q="谁组建了守夜人？",a="暴风城的部队撤离后，将暮色森林留给了黑暗与腐朽。饱受困扰的当地居民和领袖在艾尔罗·埃伯洛克公爵的领导下组建了守夜人。",al={"守夜人的起源","谁组建了守夜人"}},{q="接下来所罗门会去哪里寻求帮助？",a="夜色镇拒绝援助，西部荒野又被迪菲亚潜行者占据，湖畔镇孤立无援。所罗门转而向暴风城的宫廷寻求答案，想知道王室为何不肯保护边远领地。",al={"所罗门接下来做什么","还有谁能帮助湖畔镇"}},{q="暴风城正式撤出了暮色森林和西部荒野吗？",a="是的。随着黑暗魔法腐蚀暮色森林，西部荒野爆发动乱，暴风城的正规军撤离了这些地区。为了生存，边境城镇组建了地方民兵，包括守夜人和人民军。",al={"暴风城为何撤离","暴风城抛弃城镇"}},{q="所罗门和埃伯洛克是什么关系？",a="所罗门和埃伯洛克是相识多年的同僚，都担任着治理边境城镇的地方长官。所罗门请求援兵时，指望他们的私交能有所帮助，但暮色森林的险境让埃伯洛克无法答应。",al={"所罗门和埃伯洛克是朋友吗","所罗门和艾尔罗的关系"}}},fx={ec08915e={q="伊伯洛克领主为什么派你送信，而不是派自己的卫兵？",a="伊伯洛克领主一个守夜人都抽调不出来。夜色镇被黑暗和可怕的邪物围困，每一把剑都急需用于防守，以免城镇沦陷。你从湖畔镇赶来，是所罗门镇长派出的信使；由你带着他的回信返回，夜色镇就不必牺牲宝贵的防守力量。",al={"为什么派我去","为什么不派守夜人","为什么派冒险者去"}}},fp="22,155,26.418.0,24.375.1,64.232.0,63.217.0,27.162.0,44.216.0,59.208.0,51.227.0"}
P.entries["quest:1462"] = {n="大地灵契",s="在纳拉其营地，若年轻的萨满祭司在完成仪式前遗失了药剂，鸦羽先知会再配制一份大地灵契。这种药剂能让初学者看见岩石之灵，使试炼得以继续。",h="在纳拉其营地，若年轻的萨满祭司在完成仪式前遗失了药剂，鸦羽先知会再配制一份大地灵契。这种药剂能让初学者看见岩石之灵，使试炼得以继续。",kw={"大地的召唤","纳拉其营地","药剂","大地灵契","元素","莫高雷","鸦羽先知","萨满祭司"},ang={["class:Shaman"]="作为萨满祭司，你首先会饮用一份sapta，让自己看见引导这个世界的元素之力。",["faction:Horde"]="作为部落的一员，你会看到萨满传统在莫高雷得到传承，部族的先知在这里引导着下一代精神领袖。",["race:Tauren"]="作为牛头人，你从学习聆听大地开始，向Earth Mother表达敬意。纳拉其营地的长者确保每一位年轻人都能踏上这条神圣的道路。"},sec={{t="开启灵视的药剂",b="年轻的萨满祭司首先要学会感知寻常视野之外的力量。为了与莫高雷的土元素相见，学徒会饮下一份灵契，这种仪式药剂以岩石和土壤的天然精华配制而成。大地灵契揭开物质世界与精神世界之间的帷幕，让初学者得以看见大地之灵，并与之交流。"},{t="重获灵视的机会",b="初学者可能在抵达石碑、与灵体交流之前遗失或洒掉药剂。鸦羽先知在纳拉其营地等候，若有学生需要，她就会再配制一份。重新取得药剂后，初学者便能继续仪式，面对那些灵体。"}},faq={{q="大地灵契是什么？",a="大地灵契是萨满长者配制的一种草药制剂。学徒饮下后，药剂会唤醒内在感官，赋予他们灵视，使其得以感知寻常目光无法看见的土元素，并与之交流。",al={"灵契是什么","大地灵契背景故事","药剂有什么作用"}},{q="学徒为什么会需要另一份大地灵契？",a="学徒可能在抵达圣地前，于荒野中遗失或洒掉药剂。鸦羽先知会再提供一剂，让一次失误不至于中断训练。",al={"灵契丢失","为什么要再领一份灵契","大地灵契丢失"}},{q="鸦羽先知是谁？",a="鸦羽先知是莫高雷纳拉其营地的一位牛头人精神导师。她引导年轻的牛头人萨满祭司完成最初的试炼，并首次与大地之灵交流。",al={"鸦羽是谁","鸦羽先知背景故事","纳拉其营地先知"}},{q="萨满祭司为什么必须饮用灵契才能看见元素？",a="初学的萨满祭司还未学会随心感知元素。灵契能暂时帮助他们的感官触及元素，直到他们学会凭借自身力量聆听元素，并与之交流。",al={"为什么需要药水才能看见灵体","为什么要喝灵契"}},{q="大地灵契的试炼在哪里进行？",a="试炼在莫高雷红云台地的丘陵间进行，地点就在纳拉其营地附近。初学者带着药剂前往一座神圣的石碑，当地的大地之灵便栖居于此。",al={"在哪里使用灵契","大地的召唤地点"}},{q="所有萨满祭司都会使用灵契吗？",a="牛头人与兽人的萨满传统都会在最初的元素启蒙仪式中使用灵契。大地、火焰和水各有对应的灵契，使萨满祭司的感官与相应的元素位面协调一致。",al={"兽人使用灵契吗","只有牛头人使用灵契吗"}}},fp="11,221,19.318.0,24.259.0,23.225.0,47.168.0,25.185.0,48.182.0,51.169.0,25.192.0"}
P.entries["quest:1463"] = {n="大地灵契",s="在试炼谷，丢失了大地灵契的学徒可以向坎纳甘·地鸣再要一份。补发的药剂让年轻的萨满祭司有机会与大地之灵沟通，同时也告诫他们要小心保管神圣的饮剂。",h="在试炼谷，丢失了大地灵契的学徒可以向坎纳甘·地鸣再要一份。补发的药剂让年轻的萨满祭司有机会与大地之灵沟通，同时也告诫他们要小心保管神圣的饮剂。",kw={"大地的召唤","坎纳甘·地鸣","饮剂","杜隆塔尔","大地灵契","萨满祭司","图腾","试炼谷"},ang={["class:Shaman"]="作为一名萨满祭司学徒，丢失sapta会让你懂得自律：与元素沟通需要心神专注，行事谨慎。",["race:Orc"]="作为一名兽人，你在杜隆塔尔干旱的岩崖间学习古老的萨满之道，证明自己对先祖和脚下大地的虔诚。",["race:Troll"]="作为一名暗矛巨魔，你在试炼谷学习如何在传统的洛阿崇拜与对元素之灵的直接敬奉之间取得平衡。"},sec={{t="再次与元素沟通的机会",b="遗失大地灵契可能会打断学徒与岩石和泥土之灵的沟通。这种元素药剂通过特定仪式调制，能使物质世界与灵体之间的帷幕变得稀薄。学徒在杜隆塔尔行走时若将它遗失或洒出，坎纳甘·地鸣会出于善意再调制一份，但也会告诫新手要更加小心地保管神圣的馈赠。"},{t="坎纳甘的指引",b="坎纳甘·地鸣照看着从试炼谷大兽穴走出的萨满祭司新秀。他明白，年轻的兽人和巨魔在最初的试炼中难免手忙脚乱，但他强调，元素之灵不会宽容疏忽之举。接受第二份灵契，也是在学习谦卑：大地赐予的力量必须得到守护与尊重。"}},faq={{q="什么是大地灵契？",a="大地灵契是专为萨满祭司学徒调制的仪式饮剂。饮下它便能获得灵视，让他们察觉凡眼无法看见的土元素之灵，并与之交谈。",al={"什么是灵契","大地灵契的用法","灵契的用途"}},{q="坎纳甘·地鸣为何提供这个任务？",a="在大地的召唤的试炼中，若学徒尚未完成沟通仪式便丢失或遗落了大地灵契，坎纳甘·地鸣就会补发一份。他出于善意再提供一份，让学徒能够完成与灵体沟通的使命。",al={"坎纳甘为何给予灵契","丢失大地灵契"}},{q="仪式在哪里举行？",a="这次交接发生在试炼谷，那是杜隆塔尔西南部一处烈日炙烤的峡谷，年轻的兽人和巨魔在这里踏上追求自律与荣耀的旅程。",al={"坎纳甘在哪里","试炼谷灵契位置"}},{q="丢失灵契会招致灵体的不满吗？",a="坎纳甘提醒学徒，草率对待神圣的饮剂，说明心神不够专注。真正的萨满祭司必须以无比敬畏之心对待元素的每一份馈赠。",al={"丢失灵契有影响吗","丢失灵契的背景故事"}},{q="谁能进行这次沟通？",a="正在修习、寻求与自己的第一个元素图腾——大地图腾建立联系的萨满祭司，可以准备并饮用大地灵契。",al={"谁能获得大地灵契","使用灵契的职业"}},{q="学徒饮下灵契后会发生什么？",a="饮下药剂会开启学徒的内在视觉，让他们能够找到隐于试炼谷岩隙中的当地大地之灵的化身，并与之交谈。",al={"饮下灵契的效果","饮用大地灵契之后"}}},fp="11,228,33.384.0,17.329.0,23.191.0,45.246.0,34.170.0,47.145.0,33.124.0,48.180.0"}
P.entries["quest:1465"] = {n="瓦拉里尔的搜寻",s="继续搜查玛雷姆兄妹的货车时，你发现了一条坠饰，以及一串向南延伸的脚印。远处，一座大堡垒升起了烟。应该把坠饰交给尼耶尔前哨站的瓦拉里尔·屠魔者看，并告诉他这些迹象表明玛雷姆兄妹两人可能还活着。",h="继续搜查玛雷姆兄妹的货车时，你发现了一条坠饰，以及一串向南延伸的脚印。远处，一座大堡垒升起了烟。应该把坠饰交给尼耶尔前哨站的瓦拉里尔·屠魔者看，并告诉他这些迹象表明玛雷姆兄妹两人可能还活着。",kw={"火刃氏族","斩魔剑","凄凉之地","堡垒","马雷姆","尼耶尔前哨站","坠饰","瓦拉里尔"},sec={{t="生还的迹象",b="继续搜查货车时，你发现了一条坠饰，再往前则是一串向南延伸的脚印。远处，一座大堡垒升起了烟。那是有人照看的炉火冒出的烟，并非房屋失火，而你的直觉告诉你，如果玛雷姆兄妹两人还活着，他们就是被带往那个方向了。"},{t="给瓦拉里尔的消息",b="应该把玛雷姆坠饰交给尼耶尔前哨站的瓦拉里尔·屠魔者看，并告诉他那串向南延伸的脚印。"},{t="当地人的说法",b="瓦拉里尔对整件事十分愤怒。玛雷姆兄妹两人早就被告诫过凄凉之地有多危险，如今却双双失踪，甚至可能已经遭遇不测。听说脚印通往附近的堡垒，瓦拉里尔表示，这是目前最有价值的线索。据当地人说，那座堡垒已被火刃氏族占据，这些兽人投身于恶魔的事业。他们并不代表部落的大多数成员，但他们邪恶至极，任何被发现窥探他们的人都会当场遭到杀害。"}},faq={{q="你在货车里发现了什么？",a="一条坠饰，以及一串向南延伸的脚印。远处，一座大堡垒升起了烟。",al={"箱子里有什么","货车线索","玛雷姆坠饰"}},{q="脚印通向哪里？",a="向南，通往一座大堡垒。堡垒上方的烟来自有人照看的炉火，并非燃烧的房屋，这表明玛雷姆兄妹两人如果还活着，就是被带往那个方向了。",al={"脚印通向哪里","堡垒在哪里","足迹方向"}},{q="瓦拉里尔·屠魔者在哪里？",a="瓦拉里尔·屠魔者在凄凉之地的尼耶尔前哨站。坠饰和脚印的消息都应该送到那里。",al={"瓦拉里尔的位置","玛雷姆坠饰在哪里交","瓦拉里尔·屠魔者的位置"}}},fp="19,255,13.248.0,19.117.0,19.361.1,31.108.0,25.166.0,40.103.0"}
P.entries["quest:1466"] = {n="寻物公司的委托",s="克雷迪格·安戈尔手里有Leftwitch想要的最后一些物品，但他承认这可不是什么好差事，而且会比之前的任务花更久的时间。所有这些东西都来自恶魔：大脑、翅膀和血瓶。",h="克雷迪格·安戈尔手里有Leftwitch想要的最后一些物品，但他承认这可不是什么好差事，而且会比之前的任务花更久的时间。所有这些东西都来自恶魔：大脑、翅膀和血瓶。",kw={"凄凉之地","末日守卫血液","地狱犬大脑","克雷迪格·安戈尔","leftwitch","玛诺洛克集会所","虚空之翼","reclaimers inc"},sec={{t="清单上的最后一项",b="克雷迪格警告说这最后一批物品处理起来很麻烦，收集速度比以往任何时候都要慢。Leftwitch需要三种部件，每种十个。大脑来自地狱犬：法力吞噬者、法师猎手或魔网猎手。翅膀来自虚空女妖、虚空姐妹或虚空女巫。血液来自末日守卫队长或领主。克雷迪格说如果你拒绝这个任务，他完全理解。"},{t="凄凉之地的恶魔",b="克雷迪格甚至都没意识到这些恶魔竟然在凄凉之地。据他阅读的资料，自从暗夜精灵多年前离开后，凄凉之地大部属于半人马，他很纳闷这些恶魔是怎么来的，为什么要在这里定居。它们就栖息在凄凉之地南部的玛诺洛克集会所附近，越过科多兽坟场就能找到。"}},faq={{q="是谁在索要这些恶魔部件？",a="克雷迪格·安戈尔转交了Leftwitch的清单，而这些恶魔部件就是上面的最后几项物品。",al={"谁发布的任务","谁想要恶魔部件","克雷迪格·安戈尔是谁"}},{q="哪些生物身上有所需的物品？",a="地狱犬大脑来自法力吞噬者、法师猎手和魔网猎手。翅膀来自虚空女妖、虚空姐妹和虚空女巫。血液来自末日守卫队长和领主。",al={"什么掉落地狱犬大脑","去哪获得虚空之翼","哪些末日守卫有血液"}},{q="在哪里可以找到这些恶魔？",a="它们聚集在凄凉之地南端的玛诺洛克集会所附近，越过科多兽坟场。",al={"恶魔位置","玛诺洛克集会所在哪里","恶魔在哪里游荡"}},{q="为什么克雷迪格觉得这些恶魔很奇怪？",a="他曾读到过，在暗夜精灵多年前离开后，半人马占据了凄凉之地，所以恶魔的出现让他感到困惑。",al={"为什么恶魔在凄凉之地","凄凉之地半人马背景"}}},fp="28,119,20.384.0,18.293.0,36.99.0,39.159.0,32.86.0,44.122.0"}
P.entries["quest:1467"] = {n="寻物公司的委托",s="克雷迪格·安戈尔把莱弗维奇的包裹交给你，派你返回铁炉堡。你的报酬要找罗顿·石锤领取，克雷迪格还答应回家后替你说几句好话。",h="克雷迪格·安戈尔把莱弗维奇的包裹交给你，派你返回铁炉堡。你的报酬要找罗顿·石锤领取，克雷迪格还答应回家后替你说几句好话。",kw={"凄凉之地","铁炉堡","克雷迪格·安戈尔","莱弗维奇的包裹","为寻物公司提供试剂","罗顿·石锤"},sec={{t="铁炉堡的报酬",b="克雷迪格说，你的报酬就在铁炉堡，由罗顿·石锤本人保管。罗顿会很高兴能摆脱莱弗维奇的包裹，只要把包裹交给他，你应该就能拿到应得的报酬。克雷迪格预计自己在凄凉之地待不了多久了，仍打算回家后替你说几句好话。"},{t="罗顿的谢意",b="罗顿·石锤很高兴收到了从凄凉之地送来的莱弗维奇的包裹，并感谢你迅速完成了这项工作。你的报酬已经备好，罗顿还说，为寻物公司.辛苦工作一周，总能得到丰厚的报酬。"}},faq={{q="谁派你返回铁炉堡？",a="试剂收集齐后，克雷迪格·安戈尔派你带着莱弗维奇的包裹返回铁炉堡。",al={"任务给予者","谁给予任务","谁发起任务"}},{q="莱弗维奇的包裹需要送到哪里？",a="要送给铁炉堡的罗顿·石锤。",al={"包裹送到哪里","包裹目的地","谁接收包裹"}},{q="为什么要把包裹送给罗顿？",a="克雷迪格说，你的报酬由罗顿本人支付，所以包裹要送到铁炉堡交给他。",al={"为什么运送包裹","为什么拜访罗顿"}},{q="克雷迪格·安戈尔还会留在凄凉之地吗？",a="据克雷迪格所说，他待不了多久了，仍打算回家后替你说几句好话。",al={"克雷迪格是否离开凄凉之地","克雷迪格要去哪里"}}},fp="28,170,20.291.0,16.210.1,32.95.0,42.61.0,40.89.0,39.93.0"}
P.entries["quest:1469"] = {n="拉普索迪的故事",s="拉普索迪·铁铲拿到卡利姆多 鸡尾酒后，终于讲起了他与布罗哈恩·铁桶一同飞行的经历。他交出一块阿塔莱石板碎片，请人把它带给暴风城的布罗哈恩。",h="拉普索迪·铁铲拿到卡利姆多 鸡尾酒后，终于讲起了他与布罗哈恩·铁桶一同飞行的经历。他交出一块阿塔莱石板碎片，请人把它带给暴风城的布罗哈恩。",kw={"阿塔莱","布罗哈恩","铁桶","碎片","辛特兰","拉普索迪","铁铲","暴风城","石板"},sec={{t="交给布罗哈恩的碎片",b="喝下那杯酒后，拉普索迪·铁铲终于开口了。起飞前，他喝了整整一桶烈性黑啤酒，随后布罗哈恩跟着他在空中飞行。他留下的纪念品是一件巨魔的东西，一块阿塔莱石板碎片，他想请人把它带给暴风城的布罗哈恩·铁桶。"},{t="飞行的终点",b="拉普索迪在空中没有看到任何神庙。后来，他有些醉过了头，从坐骑上掉下来，一头栽进水里。他被吸入水下，发现自己落在一群阴森可怖的巨魔中间，便赶紧游了出去，还顺手带走了一件纪念品。看来，布罗哈恩要找的神庙果然就在那水下。"}},faq={{q="阿塔莱石板碎片要交给谁？",a="拉普索迪请人把它带给暴风城的布罗哈恩·铁桶。",al={"碎片交给谁","布罗哈恩的位置","石板交到哪里"}},{q="拉普索迪还记得与布罗哈恩一同飞行时的什么事？",a="拉普索迪在起飞前喝了整整一桶烈性黑啤酒，随后在空中四处疾飞，布罗哈恩则跟在后面。",al={"拉普索迪为什么飞行","布罗哈恩和拉普索迪"}},{q="这一步之前是什么？",a="之前是拉普索迪卡利姆多 鸡尾酒。只有调好那杯酒，拉普索迪才肯讲述那段经历。",al={"前置任务","拉普索迪的故事前置任务"}}},fp="15,173,22.278.0,22.233.1,41.67.0,55.112.0,27.93.0"}
P.entries["quest:147"] = {n="猎杀收货人",s="在艾尔文森林，治安官杜汉派你寻找收货人，一名替迪菲亚收钱的人。他以被占领的布莱克威尔南瓜田为据点，将从森林矿井中窃取的黄金送往兄弟会。",h="在艾尔文森林，治安官杜汉派你寻找收货人，一名替迪菲亚收钱的人。他以被占领的布莱克威尔南瓜田为据点，将从森林矿井中窃取的黄金送往兄弟会。",kw={"布莱克威尔南瓜田","收货人","迪菲亚","闪金镇","搜捕行动","治安官杜汉","戒指","石匠行会"},ang={["class:Rogue"]="身为潜行者，你能看出Collector的秘密活动如何映照出一个日益壮大的网络：拦路强盗和扒手正扎根于艾尔文森林各处。",["faction:Alliance"]="身为联盟的一员，你协助保护暴风城当地的资源。阻止Collector，就能切断王国黄金的非法流向，这些黄金原本将用于资助首都附近的叛乱。",["race:Human"]="身为人类，找回Stonemason的戒指或许会让你感到肩上的分量。它令人想起暴风城重建后，那些令王国分裂的激烈劳资纠纷。"},sec={{t="南瓜田里的正义",b="在艾尔文的豺狼人身上发现黄金收取时间表后，治安官杜汉派你前往布莱克威尔南瓜田。迪菲亚强盗和豺狼人占据了这座曾经宁静的农庄。收货人藏身于杂草丛生的藤蔓间，侵吞王国矿井的矿石，为日益壮大的叛乱安排运输。"},{t="工匠的印记",b="击杀收货人后，你取下他的戒指，交给治安官杜汉。治安官十分困惑：戒指上刻着暴风城旧日石匠行会的标记，而非普通罪犯的徽记。这枚戒指表明，扼住艾尔文森林交通要道的拦路强盗并非只是一群投机之徒。其中一些人曾是工匠，在暴风城重建后心生怨恨，沦为亡命之徒。"}},faq={{q="在哪里能找到收货人？",a="收货人藏在艾尔文森林东南部的布莱克威尔南瓜田，就在马科伦农场以东、作为边界的河流以北。",al={"收货人位置","收货人在哪里","收货人地点"}},{q="收货人为什么要从艾尔文的矿井中偷取黄金？",a="收货人从狗头人盘踞的法戈第和玉石矿井收集走私矿石和勒索所得的钱财，为迪菲亚潜行者在王国各地的秘密行动提供资金。",al={"为什么偷黄金","迪菲亚矿井","收货人在做什么"}},{q="收货人的戒指有什么意义？",a="这枚戒指是旧日石匠行会的成员戒指，该公会的工匠曾在第一次战争后重建暴风城。治安官杜汉无法解释，一个与迪菲亚勾结的卑微盗贼为何会带着工匠公会的戒指，他希望这个疑问终有一天能得到解答。",al={"收货人戒指背景","石匠戒指","戒指有什么含义"}},{q="治安官杜汉查出兄弟会的幕后主使了吗？",a="还没有。治安官杜汉认出了戒指上的工匠徽记，却无法解释一个普通盗贼为何会带着工匠公会的印戒。在闪金镇，这场更大阴谋的真相仍未揭晓。",al={"杜汉是否知情","杜汉的反应","治安官杜汉 石匠"}},{q="是谁派你展开这场追捕？",a="你找回迪菲亚的收取时间表后，驻守闪金镇狮王之傲旅店的卫戍指挥官治安官杜汉会将这项任务交给你。",al={"谁给予追捕任务","追捕任务给予者","治安官杜汉任务"}},{q="布莱克威尔一家出了什么事？",a="布莱克威尔南瓜田已沦为废墟，主人早已离去，如今被迪菲亚潜行者、强盗，以及不断侵入此地的河爪豺狼人占据，这些豺狼人游荡在东南部的林地中。",al={"布莱克威尔背景","南瓜田属于谁","布莱克威尔农场"}}},fx={["1901992d"]={q="治安官杜汉为什么要阻止收货人？",a="从艾尔文森林矿洞中掠走的黄金属于暴风城王国。收货人有组织地转移这些财富，实际上是在劫掠王国，并资助非法活动。治安官杜汉不能容许盗贼肆意掠夺王室资源，尤其是这些失窃的金币还表明，当地的匪患背后可能存在一场有组织的阴谋。",al={"为何击杀收货人","治安官杜汉在追捕中的动机","杜汉为何在意收货人"}},["535c4316"]={q="收货人是谁，为什么会在南瓜田？",a="收货人是一名与迪菲亚盗贼合作的成员，负责收集并转运从艾尔文森林矿洞中非法攫取的黄金。他把废弃的布莱克威尔南瓜田当作隐蔽的藏身处，按照取货时间表等待货物运到，再将王国的财富偷运出森林。",al={"收货人是谁","收货人为何在布莱克威尔南瓜田","追捕的目标"}},e23a6feb={q="治安官杜汉为什么派冒险者去，而不派暴风城的卫兵？",a="暴风城卫兵和闪金镇的驻军分散在艾尔文森林各处，兵力薄弱到了危险的地步，还要忙于应付豺狼人的入侵、矿洞中泛滥的狗头人，以及猖獗的迪菲亚强盗。杜汉根本没有多余的士兵派往偏远的南瓜田展开搜捕，只能依靠有能力、值得信赖的冒险者。",al={"杜汉为何需要我","追捕为何派冒险者","卫兵为何不击杀收货人"}}},fp="7,198,28.325.0,17.371.1,31.145.0,55.184.0,49.271.1,61.207.1,30.143.0,38.176.0"}
P.entries["quest:1470"] = {n="控制小鬼",s="在丧钟镇，温雅·玛山德考验着一名术士新手的决心。这名刚刚复生的被遗忘者必须从附近没有心智的骷髅身上收集颅骨，才能获授召唤并束缚小鬼的知识。",h="在丧钟镇，温雅·玛山德考验着一名术士新手的决心。这名刚刚复生的被遗忘者必须从附近没有心智的骷髅身上收集颅骨，才能获授召唤并束缚小鬼的知识。",kw={"丧钟镇","小鬼","控制小鬼","断骨骷髅的颅骨","提瑞斯法林地","温雅·玛山德","术士"},ang={["class:Warlock"]="身为术士，你真正迈出了研习恶魔学的第一步，并明白混乱魔法必须屈服于钢铁般的意志。",["race:Undead"]="身为被遗忘者，你在丧钟镇的阴影中研习混乱与黑暗魔法，借助的是自身对生死的超然。"},sec={{t="新手的第一步",b="在丧钟镇，温雅·玛山德教导刚刚苏醒的被遗忘者术士，力量源于知识，以及对混乱之力的掌控。她派新手们前往丧钟镇废弃的铁匠铺附近，从断骨骷髅身上收集颅骨。这场试炼考验他们能否专注心神，驾驭这个世界之外的力量，降伏虚空生物。"},{t="降伏虚空",b="温雅收下颅骨，以此证明新手能够战胜没有心智的亡灵，并直面术士技艺中那些残酷的真相。随后，她传授召唤并束缚小鬼的仪式。这种恶魔虽然体型矮小，却擅长诡计与火焰，是个危险的盟友。"}},faq={{q="谁会给予控制小鬼任务？",a="丧钟镇的被遗忘者术士训练师温雅·玛山德会给予这项试炼。",al={"谁给予 控制小鬼","控制小鬼 任务给予者","温雅·玛山德任务"}},{q="完成这个任务需要收集什么？",a="你需要在丧钟镇破败的铁匠铺附近，从断骨骷髅身上收集三个断骨骷髅的颅骨。",al={"控制小鬼 任务目标","控制小鬼 需要收集什么","断骨骷髅的颅骨"}},{q="温雅·玛山德为什么需要骷髅的颅骨？",a="在温雅放心传授更危险的恶魔仪式之前，猎杀没有心智的骷髅可以考验术士新手的控制力、决心和基本法术技巧。",al={"为什么需要 断骨骷髅的颅骨","收集颅骨任务的目的"}},{q="你会学会召唤什么力量或仆从？",a="这番教导为术士召唤并束缚小鬼做好准备，小鬼是他们学会支配的第一个恶魔伙伴。",al={"控制小鬼 奖励法术","能获得什么恶魔","召唤小鬼任务"}},{q="断骨骷髅在哪里？",a="断骨骷髅游荡在丧钟镇外围，尤其集中在镇子中央空地西北方那座破败的废弃铁匠铺周围。",al={"断骨骷髅 位置","丧钟镇骷髅在哪里","丧钟镇废弃铁匠铺"}},{q="谁有资格接受这个任务？",a="在丧钟镇接受过入门训练的被遗忘者术士可以接受这项试炼。",al={"谁能接受 控制小鬼","其他职业能否完成","是否仅限术士"}}},fp="17,178,21.340.0,22.255.0,38.76.0,45.94.0,45.155.0,44.107.0,43.138.0,40.83.0"}
P.entries["quest:1471"] = {n="誓缚",s="在幽暗城的魔法区，被遗忘者术士试图召唤、征服并永久控制一名虚空行者。凯伦丁·哈加尔主持着赋予他们这种力量的仪式。",h="在幽暗城的魔法区，被遗忘者术士试图召唤、征服并永久控制一名虚空行者。凯伦丁·哈加尔主持着赋予他们这种力量的仪式。",kw={"凯伦丁·哈加尔","魔法区","召唤符文","征服","誓缚","幽暗城","虚空行者","术士任务"},ang={["class:Warlock"]="身为术士，这个仪式让你从借助小鬼施展小把戏，迈向支配那些能在战场上承受猛烈物理攻击的生物。",["race:Undead"]="身为被遗忘者的一员，束缚一个暗影生物会进一步增强你的韧性，也让你在运用禁忌魔法时更加不受道德约束。"},sec={{t="征服仪式",b="被遗忘者术士必须证明自己能够驾驭虚空行者，才有资格召唤它。弱小的小鬼很容易被黑暗魔法引诱而订立契约，虚空的生物却憎恶现实，并拥有强大的肉体力量。在魔法区，导师凯伦丁·哈加尔会提供所需的神秘符文，将虚空行者从虚空强行拉入物质世界。"},{t="法阵之内",b="凯伦丁·哈加尔的高台下方，地面上刻着一座发光的召唤法阵。符文激活后，一名不受束缚的虚空行者便会狂怒地现身。你无法通过交涉使它屈服；必须凭借奥术之力和纯粹的意志将它击溃。只有将这生物彻底压服，凯伦丁才会传授真正的召唤法诀，将它的精华永久束缚于你。"}},faq={{q="这个仪式的目的是什么？",a="这个仪式考验你能否压服一个来自虚空的生物。击败不受束缚的虚空行者，就证明你的意志足够强大，能够控制它，随后凯伦丁·哈加尔便会教你永久召唤它的法术。",al={"为何进行誓缚","誓缚任务的作用","誓缚奖励"}},{q="召唤在哪里进行？",a="召唤在幽暗城魔法区的凯伦丁·哈加尔高台下方进行，那里地面上刻着一座紫色法阵。",al={"虚空行者召唤地点","召唤法阵位置","幽暗城召唤法阵"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是幽暗城魔法区的主要术士训练师。他负责指导新近复生的被遗忘者施法者，并主持他们的黑暗入门仪式。",al={"哈加尔是谁","凯伦丁·哈加尔背景故事"}},{q="术士想召唤的每一个恶魔都必须先击败吗？",a="术士必须先在强大的异次元生物面前树立威信，才能命令它们。小鬼这类较弱的生物可以用简单的契约和仪式束缚，而虚空行者则需要在肉体和魔法上被压服，才会俯首为奴。",al={"术士是否总要与恶魔战斗","为何与虚空行者战斗"}},{q="如果术士没能制服虚空行者，会发生什么？",a="不受束缚的虚空行者会不停地猛击附近的任何人。哈加尔警告说，比起被法阵中尚未驯服的生物撕成碎片的危险，辜负他的期望根本算不了什么。",al={"誓缚失败后果","术士失败背景故事"}},{q="虚空行者是什么？",a="虚空行者是来自虚空的暗影异次元生物。它们的肉体极为坚韧，天生渴望熄灭鲜活的光芒与能量，因此是黑暗魔法施法者理想的护盾。",al={"虚空行者是什么","虚空行者背景故事"}}},fp="11,180,21.349.0,17.351.0,35.214.0,36.137.0,23.166.0,59.261.0,57.203.0,21.240.0"}
P.entries["quest:1472"] = {n="噬魂者",s="在幽暗城的诅咒神殿，凯伦丁·哈加尔指引被遗忘者术士学习束缚魅魔。高德瑞克·法杉知道如何用纯洁而心怀挚爱的凡人之心，将魅魔从扭曲虚空引来。",h="在幽暗城的诅咒神殿，凯伦丁·哈加尔指引被遗忘者术士学习束缚魅魔。高德瑞克·法杉知道如何用纯洁而心怀挚爱的凡人之心，将魅魔从扭曲虚空引来。",kw={"诱饵","凯伦丁·哈加尔","高德瑞克·法杉","纯洁者之心","魅魔","诅咒神殿","幽暗城"},ang={["class:Warlock"]="身为术士，束缚魅魔标志着你的修行迈出了重要一步。你利用恶魔的恶习与欲望，将其奴役。",["race:Undead"]="身为Undead，你在诅咒神殿的被遗忘者术士之中接受训练。他们将生者的纯洁与挚爱视为虚空仪式的材料，不受道德约束。"},sec={{t="引诱虚空中的恶魔",b="凯伦丁·哈加尔教导说，必须引诱魅魔跨越界限，而不能靠命令将其召来。这种恶魔渴望摧毁美德，吞噬凡人的精华。要将它引出，你需要献上真正品德高尚、心怀挚爱的男子之心作为诱饵。哈加尔派你去找高德瑞克·法杉，他知道哪里能找到如此罕见的猎物。"},{t="失明的助手",b="在诅咒神殿深处，高德瑞克·法杉协助凯伦丁为束缚恶魔做准备。法尔杉的双眼已无法视物，但他说，这让他获得了更深邃的视野。他声称自己能异常清晰地感知灵魂的流动和远方的灵魂，并能指引你找到引出恶魔所需的纯洁心脏。"}},faq={{q="这个任务的目的是什么？",a="这个任务承接凯伦丁·哈加尔最初的召见，引向束缚魅魔所需的实际狩猎。你前去寻找高德瑞克·法杉，由他说明仪式所需的残酷条件。",al={"为什么做噬魂者","幽暗城魅魔任务","术士二十级任务"}},{q="为什么召唤魅魔需要纯洁的心脏？",a="凯伦丁·哈加尔说，没有无法抗拒的诱饵，魅魔就很难跨入这个世界。这种恶魔渴望腐蚀善良、诱惑凡人的心灵，并吞噬高尚的灵魂，因此善良男子纯洁无瑕的挚爱能引它跨越界限。",al={"为什么需要纯洁者之心","魅魔诱饵背景故事"}},{q="高德瑞克·法杉是谁？",a="高德瑞克·法杉是一名亡灵术士学徒，在诅咒神殿协助凯伦丁·哈加尔。虽然双目失明，他却拥有神秘的感知能力，能洞察灵魂的真相，并在东部王国各处找到合适的猎物。",al={"法尔杉是谁","失明的术士助手"}},{q="这个任务在哪里完成？",a="你在幽暗城的诅咒神殿完成这个任务，高德瑞克·法杉就等在距离凯伦丁·哈加尔几步远的地方。",al={"高德瑞克·法杉在哪里","噬魂者交任务"}},{q="噬魂者之后是什么任务？",a="接下来，高德瑞克·法杉会派你执行纯洁者之心任务。你前往湿地和银松森林的格雷迈恩之墙，夺取两名品德高尚的凡人的心脏。",al={"噬魂者后续任务","纯洁者之心后续"}},{q="任何种族都能进行这个仪式吗？",a="任何希望通过幽暗城导师的指引束缚魅魔的部落术士，都可以遵循哈加尔和法尔杉的仪式步骤。虽然这个仪式由幽暗城的被遗忘者术士传授，但这些术士都可以参与。",al={"谁能做噬魂者","亡灵专属术士任务"}}},fp="17,193,18.302.0,19.334.0,34.160.0,52.226.0,22.234.0,30.123.0,35.167.0,35.207.0"}
P.entries["quest:1473"] = {n="虚空中的生物",s="在幽暗城，一本失落的魔典藏着召唤虚空行者的关键。被遗忘者术士必须从提瑞斯法林地西部的血色十字军手中夺回埃加林的魔典，才能学会如何召唤并束缚虚空行者。",h="在幽暗城，一本失落的魔典藏着召唤虚空行者的关键。被遗忘者术士必须从提瑞斯法林地西部的血色十字军手中夺回埃加林的魔典，才能学会如何召唤并束缚虚空行者。",kw={"凯伦丁·哈加尔","埃加林","埃加林的魔典","派瑞恩","血色十字军","诅咒神殿","提瑞斯法林地","幽暗城","虚空行者"},ang={["class:Warlock"]="身为术士，你不再只是尝试驾驭小鬼，而是开始控制强大的前线暗影实体，它们能承受极为沉重的物理打击。",["faction:Horde"]="身为部落的一员，你将了解幽暗城的黑暗技艺如何通过严谨的学术研究，将危险的位面力量转化为部落边疆战事中可靠的助力。",["race:Undead"]="身为Undead，你打击血色十字军，夺回黑暗知识，让被遗忘者与盘踞在洛丹伦废墟中的活人狂热者之间的残酷斗争愈演愈烈。"},sec={{t="导师的传承",b="凯伦丁·哈加尔在诅咒神殿指引被遗忘者召唤者。当学徒掌握的力量不再局限于弱小的小鬼时，哈加尔便引导他们接触虚空行者，这种由纯粹的暗影与混乱铸成的生物。被遗忘者术士依靠埃加林的严谨研究，他是哈加尔昔日的导师，曾写下降伏这些虚空生物的仪式。"},{t="被盗的魔典",b="埃加林的魔典记载了引导不稳定魔法的方法，掌控虚空行者需要这种魔法。派瑞恩是驻守西部一座哨塔的血色十字军狂热者，他偷走了这本书。血色十字军或许只把它当作应当没收并藏匿的亵渎禁物，但夺回此书能让被遗忘者在尝试撕开帷幕之前，掌握所需的仪式奥秘。"}},faq={{q="埃加林的魔典是什么？",a="埃加林的魔典是埃加林撰写的一本魔法手册，他是凯伦丁·哈加尔的导师。书中记述了突破虚空、召唤虚空行者并使其受施法者控制所需的引导技巧与法术。",al={"埃加林的魔典","这本书是什么","埃加林是谁"}},{q="血色十字军为什么要偷走这本书？",a="血色十字军认为恶魔魔法和暗影魔法都是邪恶的。派瑞恩夺走了魔典，将它藏在提瑞斯法林地西部的一座哨塔里，似乎并不知道书中蕴藏的召唤力量。",al={"血色十字军为何夺走魔典","派瑞恩 魔典","西部血色哨塔"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是幽暗城诅咒神殿的一位大师级术士训练师。他指引初出茅庐的被遗忘者术士，教导他们敬畏变幻莫测的宇宙力量，并以自己过去在召唤中犯下的错误告诫他们谨慎行事。",al={"凯伦丁·哈加尔","幽暗城术士训练师","诅咒神殿训练师"}},{q="术士失去对虚空行者的控制会怎样？",a="虚空行者是由纯粹的混乱与暗影构成的生物。凯伦丁·哈加尔警告说，若没有无懈可击的自制力和足以束缚它的意志，召唤出的虚空行者就会狂暴地将召唤者撕成碎片。",al={"虚空行者能否杀死召唤者","虚空行者的危险","召唤失败"}},{q="夺回魔典后要做什么？",a="哈加尔拿到书后，会研读其中的内容，并教你仪式符文。随后，你将开始誓缚，使用召唤法阵召唤一只虚空行者，并亲自与它战斗，将它击败，确立你的支配地位。",al={"夺回魔典后的下一步","下一个任务","束缚仪式"}},{q="血色十字军的哨站在哪里？",a="血色十字军的哨站是一座位于提瑞斯法林地西部的哨塔。派瑞恩麾下的十字军守卫着那里，魔典就藏在塔内。",al={"派瑞恩在哪里","血色哨塔位置","魔典在哪里"}}},fp="20,209,18.354.0,19.374.0,26.211.0,43.197.0,23.226.0,56.183.0,41.217.1,45.141.0"}
P.entries["quest:1474"] = {n="誓缚",s="在幽暗城，一名学徒正面临一场仪式，完成后便能获得支配魅魔的力量。凯伦丁·哈加尔指引术士用纯洁的心，将恶魔从扭曲虚空引入仪式法阵，再通过战斗将其降服。",h="在幽暗城，一名学徒正面临一场仪式，完成后便能获得支配魅魔的力量。凯伦丁·哈加尔指引术士用纯洁的心，将恶魔从扭曲虚空引入仪式法阵，再通过战斗将其降服。",kw={"誓缚","凯伦丁·哈加尔","魔法区","纯洁的心","魅魔","幽暗城","术士"},ang={["class:Warlock"]="身为术士，这场仪式标志着你在黑暗道路上迈出了关键的一步。它考验你能否驾驭蛊惑心智的力量，让狡诈的虚空生物服从你的意志。",["race:Undead"]="身为被遗忘者，你会使用一切必要的黑暗手段，确保自己在洛丹伦的生存与统治。降服恶魔是实现这些目的的实用手段。"},sec={{t="意志的考验",b="在幽暗城的魔法区，被遗忘者术士磨炼着驾驭恶魔的本领。召唤魅魔是他们训练中的关键一步。虚空行者依靠蛮力，小鬼凭借些许恶意，而魅魔却能用诱惑与精神魔法控制召唤者。凯伦丁·哈加尔要求每名学徒证明自己的心智与魔法都不可动摇，才会让他们长久支配这样的恶魔。"},{t="法阵中的降服",b="从湿地和银松森林的无辜灵魂身上收集的纯洁的心，能打开通往扭曲虚空的通道。被召入束缚法阵的魅魔会立刻发起攻击，试图压倒术士，或使其陷入迷惑。术士必须摧毁它的形体，将它的精魄逐回虚空，才能将其掌控，并学会随意召唤这个恶魔。"}},faq={{q="这个任务的目的是什么？",a="这场仪式让被遗忘者术士证明自己能够驾驭魅魔。术士在魔法区召唤并击败一只魅魔，便证明了自己不会被它的魅惑动摇，并获得在战斗中召唤和指挥魅魔的力量。",al={"为什么做誓缚","誓缚的奖励","这个任务的用途"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔在幽暗城的魔法区训练术士，负责监督被遗忘者施法者的训练与试炼。在允许他们进行更危险的召唤仪式之前，他会考验他们的精神耐力与黑暗法术。",al={"谁发布誓缚","凯伦丁·哈加尔的故事"}},{q="为什么召唤恶魔需要纯洁的心？",a="先前步骤中收集的纯洁的心，对魅魔而言是无法抗拒的灵性诱饵。这些心脏将恶魔引过召唤法阵，使其在凡人世界显形。",al={"为什么需要纯洁的心","纯洁的心的用途"}},{q="召唤在哪里进行？",a="召唤在幽暗城的魔法区进行，所用的仪式法阵就在凯伦丁·哈加尔和术士导师附近。",al={"召唤魅魔的地点","幽暗城召唤法阵的位置"}},{q="为什么必须杀死魅魔？",a="术士不会与仆从谈判；他们会将其降服。术士在法阵中摧毁魅魔的形体，便能迫使它的灵魂服从自己的意志，让它归来时成为奴仆，而非主人。",al={"为什么要与魅魔战斗","为什么要杀死召唤的魅魔"}},{q="魅魔对幽暗城的术士有危险吗？",a="有。尽管被遗忘者对恐惧和睡眠有抵抗力，魅魔的魅惑仍曾束缚许多坚强的心智。仪式中稍有疏忽，便可能招致死亡或奴役。",al={"魅魔能否魅惑亡灵","魅魔的危险"}}},fp="11,210,14.407.0,25.345.1,34.218.0,23.227.0,48.151.0,36.124.0,39.173.0,44.171.0"}
P.entries["quest:1476"] = {n="纯洁者之心",s="在幽暗城，高德瑞克·法杉代凯伦丁·哈加尔交付一项术士试炼。为了准备引诱魅魔的诱饵，你要猎杀两名正直的人类男子；他们纯洁的心对恶魔有着无法抗拒的诱惑。",h="在幽暗城，高德瑞克·法杉代凯伦丁·哈加尔交付一项术士试炼。为了准备引诱魅魔的诱饵，你要猎杀两名正直的人类男子；他们纯洁的心对恶魔有着无法抗拒的诱惑。",kw={"凯伦丁·哈加尔","科马·韦拉德","达林·弗治维特","高德瑞克·法杉","格雷迈恩之墙","纯洁者之心","魅魔","诅咒神殿","萨多尔大桥","幽暗城"},ang={["class:Warlock"]="身为术士，你学会利用的不仅是苦难与恐惧，还有他人的高尚品德，以此束缚恶魔，使其服从你的意志。",["faction:Alliance"]="身为联盟的一员，你眼中的受害者是命运悲惨的人类：一人守护着被吉尔尼斯拒之门外的难民，另一人则在沼泽中寻找失踪的妻子。",["race:Undead"]="身为Undead，你看到了被遗忘者令人心寒的看法：洛丹伦的幸存者及其美德，都是适合用于仪式屠杀的材料。"},sec={{t="恶魔的诱饵",b="诅咒神殿的召唤大师凯伦丁·哈加尔命高德瑞克·法杉为束缚魅魔做准备。魅魔以欲望与毁灭为食，而未受玷污的美德却能将她们从扭曲虚空引出，成为可供腐化的目标。高德瑞克搜遍人类的土地，寻找善良依然纯净无损的灵魂。"},{t="猎物",b="高德瑞克·法杉指出了两名男子，他们的美德使他们成为献祭的目标。达林·弗治维特照料着绝望的洛丹伦难民，他们被挡在银松森林南部紧闭的格雷迈恩之墙外，无法获得庇护。科马·韦拉德不知疲倦地搜寻湿地危机四伏的沼泽，寻找失踪妻子的任何踪迹。他们的奉献、同情与忠诚，使他们成了被遗忘者术士的上好祭品。"},{t="被遗忘者的视角",b="这场猎杀带你穿过危险的联盟领地与荒野，你在那里残杀了两名男子。当你带着他们血淋淋的心脏返回诅咒神殿时，凯伦丁·哈加尔指出，好人的心脏看起来与其他尸体的残骸并无区别。然而，附着在血肉上的纯洁灵魂却是强效的诱饵，足以诱来一只魅魔，将她囚禁。"}},faq={{q="术士为什么需要纯洁的心来召唤魅魔？",a="凡人的纯真与美德会吸引魅魔，她渴望将其腐化。凯伦丁·哈加尔用真正纯洁无私之人的心脏作为无法抗拒的灵魂诱饵，将一只魅魔引过虚空，困在束缚法阵中。",al={"为什么需要纯洁的心","魅魔诱饵背景","为什么杀达林和科马"}},{q="达林·弗治维特是谁？",a="达林·弗治维特是一名正直的人类，骑马沿着银松森林南部格雷迈恩之墙紧闭的大门巡逻。他毕生致力于照料和保护遭吉尔尼斯拒绝、被关在墙外的洛丹伦难民。",al={"达林·弗治维特背景","达林是谁","格雷迈恩之墙的男子"}},{q="科马·韦拉德是谁？",a="科马·韦拉德是一名忠贞的人类，在萨多尔大桥以南、湿地北部的道路上寻觅。悲痛与坚定不移的爱驱使着他，不断寻找失踪妻子的任何踪迹。",al={"科马·韦拉德背景","科马是谁","湿地人类心脏"}},{q="这条任务线接下来会通向何处？",a="将两颗心脏交给凯伦丁·哈加尔后，他便能在诅咒神殿准备召唤法阵。随后，你会召唤并制服一只魅魔，让她成为永久的仆从。",al={"接下来做什么","纯洁者之心后续","魅魔任务奖励"}},{q="谁交付这项任务？",a="高德瑞克·法杉是幽暗城魔法区内诅咒神殿的一名助手，他代凯伦丁·哈加尔交付这项任务。他施法投射出达林与科马的幻象，让你认清要猎杀的目标。",al={"谁开启纯洁者之心","高德瑞克·法杉任务"}},{q="凯伦丁·哈加尔为什么不在意心脏的外观？",a="凯伦丁·哈加尔说，好人的心脏看起来与其他肉块没什么两样。作为一名研习黑暗法术的亡灵，他在意的是心脏作为施法材料的用途，而非其血肉所代表的道德。",al={"凯伦丁对话","心脏外观"}}},fp="18,158,16.336.0,10.395.0,22.367.1,54.239.0,25.241.0,21.191.0,33.188.1,21.219.0,62.196.0"}
P.entries["quest:1478"] = {n="哈加尔的召唤",s="一封正式召令，召集有潜力的被遗忘者术士前往幽暗城接受进阶训练。凯伦丁·哈加尔要求那些技艺已达到一定境界的术士到魔法区与他会合，那里有危险的虚空生物等待着他们。",h="一封正式召令，召集有潜力的被遗忘者术士前往幽暗城接受进阶训练。凯伦丁·哈加尔要求那些技艺已达到一定境界的术士到魔法区与他会合，那里有危险的虚空生物等待着他们。",kw={"埃格隆·卡加尔","凯伦丁·哈加尔","哈加尔的召唤","魔法区","诅咒神殿","幽暗城","虚空行者","术士"},ang={["class:Warlock"]="身为术士，你将在幽暗城最负盛名的黑暗法术大师审视下，从基础训练迈向对异界生物的奴役。",["race:Undead"]="身为被遗忘者，你怀着冷酷的野心追求暗影与邪能。哈加尔的密室体现了你的族人务实的态度，对生者的谨慎毫不在意。"},sec={{t="大师的通知",b="一名术士已能驾驭基础邪能的消息，从布瑞尔或提瑞斯法的荒野传到了幽暗城。埃格隆·卡加尔是一位善于发掘人才的资深术士，他向那些展现出潜力的人发出通知。凯伦丁·哈加尔的召令，既代表着难得的殊荣，也意味着术士的训练将迈入危险的阶段。基础的小鬼召唤术和低阶诅咒已不再足够。"},{t="魔法区",b="凯伦丁·哈加尔在幽暗城的魔法区主持术士仪式，地点就在诅咒神殿附近。被遗忘者的黑暗施法者不受生者的道德约束，但位面召唤仍然需要严守规矩。哈加尔既容不得犹豫，也容不得感情用事。受召前来的人必须表现出恭敬，并准备好面对扭曲虚空中充满敌意的恐怖生物。"}},faq={{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是幽暗城魔法区的首席术士训练师。他督导被遗忘者召唤者在黑暗之道上的修行，并在传授束缚强大虚空生物的方法之前，考验他们的意志。",al={"凯伦丁·哈加尔","哈加尔大师","哈加尔是谁"}},{q="谁指引我去找哈加尔？",a="埃格隆·卡加尔是一位驻守布瑞尔的资深术士训练师，他得知哈加尔大师亲自关注你的进展后，便派你前去。",al={"谁发布哈加尔的召唤","埃格隆·卡加尔","谁发布任务"}},{q="在幽暗城哪里能找到凯伦丁·哈加尔？",a="哈加尔位于幽暗城的魔法区，就在被称为诅咒神殿的黑暗高台附近。",al={"哈加尔位置","哈加尔在哪里","魔法区的哈加尔"}},{q="这封召令为何重要？",a="这封召令标志着你将从基础施法迈向危险的恶魔奴役之术。要束缚一只虚空行者为你效力，就必须通过一系列试炼，而这正是试炼的开端。",al={"为什么需要做这个任务","任务目的","哈加尔的召唤后续"}},{q="哈加尔愿意教导任何人吗？",a="哈加尔只关注有潜力的术士。他没有多少时间应付无谓的寒暄，也要求每一个被带到他面前的学徒，都已证明自己有能力驾驭不稳定的邪能法术。",al={"任何人都能与哈加尔交谈吗","哈加尔的要求"}},{q="向哈加尔报到后会发生什么？",a="当你向哈加尔报到时，他会派你收集召唤并束缚异界暗影仆从所需的材料，以此考验你的法术能力。",al={"接下来做什么","哈加尔的召唤之后"}}},fp="16,231,17.327.0,17.373.0,23.201.0,25.150.0,46.79.0,30.155.0,34.189.0,39.143.0"}
P.entries["quest:148"] = {n="来自夜色镇的货物",s="暮色森林西部的亚伯克隆比请旅人从夜色镇取来一种稀有的丝线。这位隐士声称自己太过虚弱，无法穿过闹鬼的森林，请人向伊瓦夫人索取幽灵的发丝。",h="暮色森林西部的亚伯克隆比请旅人从夜色镇取来一种稀有的丝线。这位隐士声称自己太过虚弱，无法穿过闹鬼的森林，请人向伊瓦夫人索取幽灵的发丝。",kw={"亚伯克隆比","夜色镇","暮色森林","幽灵的发丝","伊瓦夫人","来自夜色镇的补给","隐士"},ang={["faction:Alliance"]="身为联盟冒险者，你可能会在夜色镇周围危险的偏僻小路上奔波，为隐士传递消息、运送物资。",["profession:Tailoring"]="身为裁缝，你知道织物通常使用亚麻或丝绸制成。伊瓦夫人将虚无缥缈的头发纺成丝线，这手艺令人好奇，又透着几分阴森。"},sec={{t="虚弱者的请求",b="亚伯克隆比独自住在暮色森林西部、乌鸦岭墓地北边的一间棚屋里。他告诉旅人，自己年老体弱，无法冒险穿过森林，前往夜色镇购买物资。他的请求看似简单：去镇上的广场，找伊瓦夫人要一卷幽灵的发丝。"},{t="奇特的材料",b="在夜色镇，伊瓦夫人手头并没有现成的幽灵的发丝。这位当地的占卜师会纺制奇异的物品，但这种丝线并非普通的缝纫材料。要纺出这种线，她需要盲眼玛丽的头发，那是一个徘徊在夜色镇南边农舍里的悲伤幽灵。如今，要完成这趟差事，就得先收集伊瓦夫人所需的材料。"}},faq={{q="夜色镇的货物任务由谁发起？",a="亚伯克隆比请求援助，他是一位隐士，住在暮色森林西部、乌鸦岭墓地北边的棚屋里。",al={"夜色镇的补给品任务给予者","夜色镇的补给品由谁发起","亚伯克隆比的差事"}},{q="要取得物资，该在夜色镇找谁交谈？",a="找伊瓦夫人交谈，她住在一栋俯瞰夜色镇中央广场的房子里。",al={"夜色镇的补给品在哪里交任务","夜色镇的补给品交任务","伊瓦夫人位置"}},{q="亚伯克隆比具体在寻找什么物品？",a="亚伯克隆比想要幽灵的发丝，这是伊瓦夫人纺制的一种奇特材料。",al={"亚伯克隆比想要什么","物资是什么","亚伯克隆比所需物品"}},{q="伊瓦夫人有现成的幽灵的发丝吗？",a="没有。你到达时，伊瓦夫人手头没有存货。她答应纺制这种丝线，前提是你从附近的幽灵那里收集到她所需的幽魂材料。",al={"艾瓦有丝线吗","夜色镇的补给品任务完成"}},{q="夜色镇的货物的前置任务是什么？",a="隐士让旅人从夜色镇出发，前往亚伯克隆比的住处寻找他。",al={"夜色镇的补给品前置条件","夜色镇的补给品前置任务"}},{q="夜色镇的货物的后续任务是什么？",a="与伊瓦夫人交谈后，就会直接接到幽灵的发丝任务。你需要把鬼梳交给盲眼玛丽，并收集她的头发。",al={"夜色镇的补给品之后的任务","夜色镇的补给品后续任务"}}},fp="23,178,16.303.0,18.303.1,45.102.0,53.83.0,46.78.0,49.136.0,44.78.0,43.135.0"}
P.entries["quest:1480"] = {n="堕落者",s="这块从雷斧堡垒的火刃氏族手中取得的恶魔皮散发着腐臭，却出奇地柔韧。皮的一面布满了某种语言的红色文字，底部有一个清晰的符号，看起来像是签名。幽灵岗哨的玛乌林·碎骨或许能告诉你更多。",h="这块从雷斧堡垒的火刃氏族手中取得的恶魔皮散发着腐臭，却出奇地柔韧。皮的一面布满了某种语言的红色文字，底部有一个清晰的符号，看起来像是签名。幽灵岗哨的玛乌林·碎骨或许能告诉你更多。",kw={"火刃氏族","艾瑞达语","剥下的恶魔皮","幽灵岗哨","魔王阿兹雷索克","玛乌林·碎骨","堕落者","雷斧堡垒"},sec={{t="一条皮",b="这块撕下来的皮散发着腐臭，虽然看起来干燥易碎，却很容易弯折。展开后，可以看到一面有红色的印记，似乎是某种文字。底部有一个清晰的符号，你觉得那是一个签名。"},{t="玛乌林的看法",b="幽灵岗哨的玛乌林·碎骨或许对这块皮有所了解。玛乌林认为，火刃氏族正逐渐意识到自己有多么弱小，他们的魔法拙劣，力量也微不足道。他们拥有的任何力量都来自他们侍奉的主人，而非对真正力量与知识的领悟。"},{t="文字的含义",b="玛乌林认出这些符文属于一种古老的语言，与艾瑞达语有些相似，细节却大不相同。如果玛乌林判断无误，这块皮就是某种契约，而底部的符号则是一个名叫魔王阿兹雷索克的恶魔的签名。"}},faq={{q="剥下的皮上写着什么？",a="皮的一面布满了红色的印记，似乎是某种文字。底部有一个清晰的符号，看起来像是签名。幽灵岗哨的玛乌林·碎骨或许知道更多。",al={"剥下的皮上的符文","皮上写着什么","皮上的红色文字"}},{q="这块皮来自哪里？",a="它取自凄凉之地雷斧堡垒的火刃氏族。",al={"皮的位置","哪里能获得恶魔皮","如何开始堕落者"}},{q="玛乌林·碎骨是谁？",a="玛乌林·碎骨位于凄凉之地的幽灵岗哨，这块皮被带到了那里。",al={"玛乌林在哪里","玛乌林·碎骨的位置","玛乌林是谁"}},{q="玛乌林如何看待火刃氏族？",a="玛乌林认为他们十分弱小，魔法拙劣，力量微不足道。在他看来，他们拥有的任何力量都来自他们侍奉的主人。",al={"玛乌林 火刃氏族","火刃氏族的力量"}}},fp="13,202,15.210.0,13.289.0,22.230.1,35.190.0,30.78.0,27.83.0,44.145.0"}
P.entries["quest:1481"] = {n="堕落者",s="玛乌林·碎骨相信能找到那位恶魔领主，但首先必须破除它用来抵御占卜的所有结界。为此，玛乌林需要一张怨怒巡影者的头皮，要到凄凉之地东北部的古老废墟中猎取。",h="玛乌林·碎骨相信能找到那位恶魔领主，但首先必须破除它用来抵御占卜的所有结界。为此，玛乌林需要一张怨怒巡影者的头皮，要到凄凉之地东北部的古老废墟中猎取。",kw={"凄凉之地","怨怒巡影者","玛乌林·碎骨","萨格隆","萨特","占卜","暗影潜伏者头皮","堕落者"},sec={{t="破除结界",b="玛乌林·碎骨相信，只要有合适的施法材料，就能找到那位恶魔领主。如果那位领主真像玛乌林猜测的那样强大，这些材料就必须取自致命的生物，而玛乌林确信，以大酋长之名行事的你会接受这项挑战。首先要破除那恶魔用来抵御占卜的所有结界。为此，玛乌林需要一张萨特的头皮，而且只有怨怒巡影者的头皮才行。要寻找它们，就得去凄凉之地东北部、萨格隆附近的古老废墟。"},{t="合适的头皮",b="玛乌林告诫你，千万别带错头皮。错误的施法材料可能害人丧命，因为那位恶魔领主可能设有应急法术，专门杀死任何试图占卜窥探它的人。玛乌林还说，命运带来的苦痛已经够多了。"},{t="归来之时",b="玛乌林认定这张头皮适合他的法术。你离开的这段时间里，他收集了法术所需的其他一些材料，如今已准备得差不多了。他只缺一件聚焦物，用来映出那位恶魔领主的影像，显示它的所在。"}},faq={{q="是谁派你去收集头皮的？",a="玛乌林·碎骨需要这张头皮，用于施法寻找那位恶魔领主。",al={"任务给予者","任务起始者","玛乌林·碎骨"}},{q="为什么玛乌林一定要怨怒巡影者的头皮？",a="必须先破除那位恶魔领主用来抵御占卜的所有结界。为此，玛乌林需要一张萨特的头皮，而且只有怨怒巡影者的头皮才行。",al={"为何需要巡影者头皮","需要萨特头皮的原因","为何选择萨特"}},{q="在哪里能找到怨怒巡影者？",a="在凄凉之地东北部、萨格隆附近的古老废墟中。",al={"巡影者在哪里","巡影者位置","萨特位置"}},{q="使用错误的施法材料有什么危险？",a="玛乌林警告说，错误的施法材料可能导致死亡。那位恶魔领主可能设有应急法术，专门杀死任何试图占卜窥探它的人。",al={"为何必须选对头皮","错误施法材料的风险","应急法术"}},{q="这一步处于寻找恶魔领主的哪个阶段？",a="这一步接在堕落者的第一部分之后，当时你把剥下的恶魔皮交给了玛乌林。",al={"任务链进度","任务顺序","前置任务"}}},fp="13,193,18.423.0,15.230.0,15.226.1,34.87.0,65.141.0,47.91.0,49.146.0,60.95.0"}
P.entries["quest:1482"] = {n="堕落者",s="玛乌林·碎骨想要一块神谕水晶，用它来寻找恶魔领主阿兹雷索克，这种水晶由娜迦为他们的神谕者制作。沿着海岸向西北走，有一片广阔的珊瑚礁，滑刃娜迦就住在那里，他们不会欢迎你的到来。",h="玛乌林·碎骨想要一块神谕水晶，用它来寻找恶魔领主阿兹雷索克，这种水晶由娜迦为他们的神谕者制作。沿着海岸向西北走，有一片广阔的珊瑚礁，滑刃娜迦就住在那里，他们不会欢迎你的到来。",kw={"阿兹雷索克","堕落者","凄凉之地","玛乌林·碎骨","娜迦","神谕水晶","滑刃","大酋长"},sec={{t="一块神谕水晶",b="玛乌林·碎骨说，神谕水晶能找到恶魔领主阿兹雷索克，你带来的那张皮上就有他的签名。娜迦制作这种水晶，供他们的神谕者使用。沿着海岸向西北走，有一片广阔的珊瑚礁，娜迦在靠近岸边时便以此为家，神谕者也能在那里找到。那里的滑刃十分致命，对你的闯入绝不会客气，因此玛乌林叮嘱你小心行事，速去速回。"},{t="共同的奖赏",b="玛乌林指出，找到并消灭阿兹雷索克领主，会让你们两人都大获大酋长的青睐。迅速携手行动，便能达成双方的目的。"}},faq={{q="玛乌林·碎骨为什么需要神谕水晶？",a="他打算找到恶魔领主阿兹雷索克，为此，他要你找来一块神谕水晶。",al={"为什么需要神谕水晶","水晶有什么用途","玛乌林的水晶用途"}},{q="在哪里能找到神谕水晶？",a="娜迦为自己的神谕者制作这些水晶，而那些神谕者就在玛乌林西北方沿海的一片广阔珊瑚礁中。",al={"哪里能找到水晶","神谕水晶位置","滑刃神谕者在哪里"}},{q="滑刃是谁？",a="他们是娜迦，以近岸的一片广阔珊瑚礁为家。玛乌林说他们十分致命，对闯入者绝不会客气。",al={"滑刃是什么","滑刃娜迦","谁住在珊瑚礁中"}},{q="阿兹雷索克是谁？",a="阿兹雷索克是一名恶魔领主，你带给玛乌林的那张皮上有他的签名。玛乌林想要找到并消灭他。",al={"阿兹雷索克是谁","恶魔领主阿兹雷索克","玛乌林在追猎哪个恶魔"}},{q="玛乌林为什么要追猎这个恶魔？",a="玛乌林说，找到并消灭阿兹雷索克领主，会让你们两人都大获大酋长的青睐。",al={"玛乌林的动机","为什么追猎阿兹雷索克","大酋长的青睐"}}},fp="13,194,17.383.0,14.160.0,52.61.0,36.119.0,25.139.0,16.116.0,41.110.0"}
P.entries["quest:1483"] = {n="菲兹克斯",s="在狂风峭壁西侧的山脊上，菲兹克斯离开了荆棘谷地精，加入了技工协会。一名侏儒工程师的到来让他选择离去，可新上司使唤起他来同样毫不留情。",h="在狂风峭壁西侧的山脊上，菲兹克斯离开了荆棘谷地精，加入了技工协会。一名侏儒工程师的到来让他选择离去，可新上司使唤起他来同样毫不留情。",kw={"格雷苏","斯布特瓦夫","石爪山脉","工匠协会","荆棘谷地精","狂风峭壁","菲兹克斯"},ang={["faction:Horde"]="作为石爪山脉的部落冒险者，你可以帮助斯布特瓦夫和菲兹克斯等技工协会干员，削弱荆棘谷地精对狂风峭壁的控制。",["profession:Engineering"]="作为工程师，你能从地精与侏儒工程理念之间由来已久、冲突不断的竞争中，看出菲兹克斯与格雷苏激烈争斗的根源。"},sec={{t="事关职业尊严",b="荆棘谷地精雇用了侏儒工程师格雷苏，菲兹克斯视此为奇耻大辱。他无法忍受与一名侏儒同行共事，于是开始寻找出路。菲兹克斯联系了技工协会的代表斯布特瓦夫，恳求调职，摆脱格雷苏的管束。"},{t="跳出煎锅",b="技工协会给了菲兹克斯一个新职位，却没给他期待中的轻松日子。在狂风峭壁西缘，他发现斯布特瓦夫使唤起他来，丝毫不亚于荆棘谷地精的任何工头。即便如此，菲兹克斯也宁愿在严苛的地精上司手下苦干，而不愿与侏儒共用一间工程作坊。"}},faq={{q="菲兹克斯是谁？",a="菲兹克斯是一名地精工程师，曾在石爪山脉为荆棘谷地精效力。荆棘谷地精雇用了一名侏儒工程师后，他便离开，加入了技工协会。",al={"菲兹克斯 是谁","菲兹克斯在哪","关于 菲兹克斯"}},{q="菲兹克斯为什么离开荆棘谷地精？",a="荆棘谷地精雇用了侏儒工程师格雷苏，菲兹克斯拒绝与他共事。菲兹克斯恳求斯布特瓦夫给他安排一个新职位。",al={"菲兹克斯 为什么辞职","为什么离开荆棘谷地精","菲兹克斯 荆棘谷地精"}},{q="在哪里能找到菲兹克斯？",a="菲兹克斯在石爪山脉的狂风峭壁西缘工作。从那里，他可以俯瞰荆棘谷地精的伐木和挖掘作业。",al={"菲兹克斯 位置","菲兹克斯 在哪里","寻找 菲兹克斯"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是技工协会的一名地精干员。他从荆棘谷地精招揽技艺精湛的工程师，让他们参与与之竞争的项目。",al={"斯布特瓦夫是谁","斯布特瓦夫的职责"}},{q="格雷苏是谁？",a="格雷苏是荆棘谷地精雇来在狂风峭壁工作的侏儒工程师。他的到来激怒了菲兹克斯，引发了激烈的同行竞争。",al={"格雷苏","侏儒工程师是谁"}},{q="技工协会是什么？",a="技工协会是一个老牌地精工程行业协会。它与荆棘谷地精竞争，招揽或召回顶尖人才。",al={"技工协会","地精 技工协会"}}},fp="11,194,30.305.0,21.319.0,19.179.0,46.154.0,31.167.0,20.145.0,29.165.0,27.148.0"}
P.entries["quest:1484"] = {n="堕落者",s="玛乌林·碎骨发现，那个恶魔领主远比预想的危险。他确信塔卡塔·钢刃怀疑自己的能力，而不把发生的事情告诉这位剑士，会有损塔卡塔的荣誉。玛乌林派你去找就在附近的塔卡塔谈谈。",h="玛乌林·碎骨发现，那个恶魔领主远比预想的危险。他确信塔卡塔·钢刃怀疑自己的能力，而不把发生的事情告诉这位剑士，会有损塔卡塔的荣誉。玛乌林派你去找就在附近的塔卡塔谈谈。",kw={"恶魔领主","凄凉之地","科多兽坟场","玛乌林·碎骨","剑士","塔卡塔·钢刃","堕落者"},sec={{t="荣誉之事",b="玛乌林·碎骨发现，那个生物比他预想的危险得多。塔卡塔·钢刃无疑在怀疑玛乌林能否应付它，而不让塔卡塔知晓刚才发生的事情，会有损他的荣誉。玛乌林请你去与这位剑士交谈，并提出在塔卡塔允许的情况下，由你去杀死那个恶魔。玛乌林提醒你，不要逼塔卡塔太紧，因为最好让塔卡塔相信这是他自己的主意。"},{t="小路对面",b="塔卡塔·钢刃就在附近，与玛乌林隔着一条小路，站在俯瞰科多兽坟场的悬崖上。"},{t="塔卡塔的答复",b="塔卡塔亲眼目睹了玛乌林与那个恶魔领主之间发生的事情。即使只是幻影，那个生物似乎也比塔卡塔的术士同伴玛乌林更强大，塔卡塔不禁怀疑玛乌林能否击败它。塔卡塔亲自出马能更好地为大酋长效力，但他在这里身负重任，若为了个人荣誉而抛下职责，去对抗这个邪恶的存在，就会让氏族蒙羞。"}},faq={{q="玛乌林·碎骨为什么想让塔卡塔·钢刃知道这件事？",a="玛乌林发现，那个恶魔领主远比预想的危险。他确信塔卡塔怀疑自己的能力，而不把发生的事情告诉这位剑士，会有损塔卡塔的荣誉。",al={"为什么要与塔卡塔交谈","玛乌林·碎骨的理由","为什么要告诉塔卡塔"}},{q="塔卡塔·钢刃在哪里？",a="就在附近，与玛乌林隔着一条小路，站在凄凉之地一处俯瞰科多兽坟场的悬崖上。",al={"塔卡塔的位置","塔卡塔在哪里","寻找塔卡塔·钢刃"}},{q="玛乌林为什么建议不要逼塔卡塔太紧？",a="玛乌林希望你提出，在塔卡塔允许的情况下，由你去杀死那个恶魔，但不要逼他太紧。最好让塔卡塔相信这是他自己的主意。",al={"为什么不能逼塔卡塔","如何与塔卡塔打交道","塔卡塔的自尊"}}},fp="13,246,17.394.0,15.110.0,15.391.1,57.201.0,35.112.0,56.143.0"}
P.entries["quest:1485"] = {n="邪灵劣魔",s="在大兽穴附近，邪灵劣魔威胁着每一个寻求恶魔之力的术士。鲁赞要求你击败它们，证明自己的实力，并带回它们的头颅。在部落警惕的注视下，这是掌握邪能力量的第一步，虽不起眼，却充满危险。",h="在大兽穴附近，邪灵劣魔威胁着每一个寻求恶魔之力的术士。鲁赞要求你击败它们，证明自己的实力，并带回它们的头颅。在部落警惕的注视下，这是掌握邪能力量的第一步，虽不起眼，却充满危险。",kw={"火刃集会所","杜隆塔尔","小鬼","鲁赞","大兽穴","试炼谷","邪灵劣魔","术士"},ang={["class:Warlock"]="身为术士，你要接受这最初的试炼，证明自己能够降伏恶魔之火，然后才能学习召唤专属小鬼的仪式。",["faction:Horde"]="身为部落的一员，你可以在杜隆塔尔接受术士训练，但黑暗法术仍被限制在大兽穴这样的偏僻之地。",["race:Orc"]="身为兽人，你每天都要面对族人的黑暗历史。在这个仍记得邪能腐化之恐怖的社会里，你必须证明自己的自制力与忠诚。"},sec={{t="部落中的艰难处境",b="在萨尔建立的新部落中，术士们处境不安。恶魔腐化与鲜血契约曾给兽人带来毁灭，留下了深重的创伤与猜忌。杜隆塔尔容许邪能魔法的存在，但施术者既不受爱戴，也不受欢迎。许多术士隐居独处，在大兽穴这样的阴暗之地修习，避开窥探的目光。在那里，他们教导着少数敢于追随这条道路的学徒。"},{t="驾驭之力的试炼",b="鲁赞要求你先证明自己的实力，才会传授让小鬼服从你意志的危险仪式。邪灵劣魔潜伏在大兽穴东北方的一处洞穴附近，向靠近者投掷火焰箭。杀死这些低等恶魔，带回它们的头颅，证明你能战胜这些你希望控制的烈焰生物。只有这样，你才能面对驾驭这种魔法所带来的危险。"}},faq={{q="鲁赞为什么派术士去对付邪灵劣魔？",a="鲁赞派你去对付邪灵劣魔，是为了让你在尝试召唤小鬼之前，先领教它们的烈焰本性与危险。术士人数稀少，又不受信任，因此他要求你先证明自己能击败这样的生物，才会传授恶魔召唤术。",al={"为何杀死邪灵劣魔","鲁赞的考验","小鬼试炼"}},{q="在哪里能找到邪灵劣魔？",a="在试炼谷，越过野猪和蝎子游荡的地带，邪灵劣魔聚集在大兽穴东北方一处洞穴的内外。那处洞穴是火刃集会所的营地。",al={"邪灵劣魔位置","邪灵劣魔在哪里","鲁赞的洞穴"}},{q="部落如何看待杜隆塔尔的术士？",a="由于恶魔腐化曾给兽人留下创伤，术士在整个部落都备受猜疑。萨尔的政权容许他们存在，也认可他们在战斗中的价值，但许多术士依然过着独居的生活。",al={"术士是否受憎恨","部落术士背景","为何不信任术士"}},{q="完成这场试炼能获得什么奖励？",a="将杀死的邪灵劣魔的头颅带给鲁赞，就能证明你拥有驾驭恶魔所需的力量与自制力。之后，他便可以教你召唤小鬼仆从。",al={"能学到什么","鲁赞任务奖励","小鬼法术"}},{q="邪灵劣魔真的是恶魔吗？",a="是的。邪灵劣魔是与邪能魔法相关的低等恶魔小鬼。它们虽然体型小巧，却是强劲的对手，会向敌人投掷火球。",al={"邪灵劣魔是什么","邪灵劣魔是否是小鬼","邪灵劣魔恶魔类型"}},{q="鲁赞是谁？",a="鲁赞是试炼谷大兽穴中的一名兽人术士训练师。他教导初入此道的兽人术士安全地运用邪能，并控制召唤出的仆从。",al={"鲁赞","鲁赞是谁","试炼谷术士"}}},fp="14,239,31.402.0,20.419.0,53.212.0,35.186.0,44.191.0,45.158.0,33.137.0,13.155.0"}
P.entries["quest:1486"] = {n="变异皮革",s="变异皮革是纳尔帕克交付的一项任务，他是纳拉雷克斯的弟子，驻守在哀嚎洞穴入口上方。纳拉雷克斯被困在扭曲的梦魇中，而纳尔帕克试图从贫瘠之地地下滋生的变异野兽身上找出有用之物。他希望收集这些变异掠食者的皮革，将其中奇异的异界特性用于实际用途。",h="变异皮革是纳尔帕克交付的一项任务，他是纳拉雷克斯的弟子，驻守在哀嚎洞穴入口上方。纳拉雷克斯被困在扭曲的梦魇中，而纳尔帕克试图从贫瘠之地地下滋生的变异野兽身上找出有用之物。他希望收集这些变异掠食者的皮革，将其中奇异的异界特...",kw={"贫瘠之地","变异","变异皮革","翡翠梦魇","制皮","纳尔帕克","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="纳尔帕克的营地承载着幸存弟子们对这场彻底失控的行动所作的沉重守望，也让遏制洞穴异变的任务成为其他德鲁伊切身关切之事。",["profession:Herbalism"]="滋养变异野兽的异常生长现象，与洞穴网络中遭到腐化的植物和蜿蜒流淌的地下泉水直接相关。"},sec={{t="腐化的显现",b="暗夜精灵德鲁伊纳拉雷克斯试图借助贫瘠之地下方的地下泉水，让干旱的平原重现繁茂生机，却在此时陷入了可怕的梦魇。那场黑暗的梦境渗入现实，将哀嚎洞穴原有的野生动物变成了凶残的变异野兽。迅猛龙、鳄鱼、蝰蛇和蹒跚的恐怖生物纷纷变得扭曲而狂暴，皆因沉睡的主人泄出的翡翠腐化之力而发生异变。"},{t="务实的德鲁伊",b="纳尔帕克栖身于洞口上方的岩层中，怀着恐惧与务实的好奇心，注视着这场灾难的发展。虽然他明白这些变异生物本性邪恶、有违自然，却相信它们遭到腐化的躯体或许能提供独特的材料。尤其是它们变得坚韧而扭曲的毛皮，其韧性或许能为技艺娴熟的制皮师所用，将悲惨梦魇的产物制成耐用的装备。"}},faq={{q="在哪里可以找到纳尔帕克？",a="纳尔帕克和其他弟子在哀嚎洞穴入口上方形似骷髅的岩层高处建立了一座小营地。不要径直走进主通道，而要攀上洞口后方的山坡，再小心地跳落到上层洞穴的眼窝平台，那里可以俯瞰绿洲。",al={"纳尔帕克位置","纳尔帕克在哪里","如何找到纳尔帕克","变异皮革任务给予者"}},{q="什么是变异生物？",a="变异生物是当地的野兽，因纳拉雷克斯沉睡的意识中逸出的 翡翠梦魇 而发生了异变。贫瘠之地原有的迅猛龙、蛇、鳄鱼和风蛇被扭曲成更加阴暗凶残的形态，具有奇异的魔法特性，皮革也斑驳异常。",al={"什么是变异生物","变异野兽","哀嚎洞穴的动物为何变异"}},{q="纳尔帕克为什么需要这些皮革？",a="纳尔帕克意识到，虽然这些野兽诞生于邪恶的腐化，它们的皮革却具有非同寻常的异界强韧。他相信，制皮师可以通过研究和加工这些毛皮，将梦魇的污秽化为坚韧的装备。",al={"为何收集变异皮革","纳尔帕克要皮革做什么","变异皮革的用途"}},{q="所有变异生物都会掉落这些皮革吗？",a="在哀嚎洞穴各处通道和内部游荡的变异野兽身上都能找到这些皮革。猎人和制皮师常常发现，除了从野兽遗骸上直接搜得的皮革，剥皮还能带来额外的毛皮。",al={"哪些怪物掉落变异皮革","谁掉落变异皮革","刷变异皮革"}},{q="纳尔帕克是部落还是联盟阵营？",a="纳尔帕克是一位牛头人德鲁伊，也是纳拉雷克斯的学徒之一。他保持中立，并会接受任何有能力的冒险者的帮助，无论是联盟还是部落，只要他们有足够的勇气进入这些被腐蚀的洞穴。",al={"纳尔帕克是部落吗","变异皮革是联盟任务吗","联盟可以做变异皮革任务吗"}},{q="纳拉雷克斯遭遇了什么？",a="纳拉雷克斯试图将自己的意识与翡翠梦境相连，以唤醒贫瘠之地的地下泉水。然而，他的睡梦却被 梦魇 占据，将整片洞穴变成了恐怖生物的温床，也让他昏迷在洞穴深处。",al={"纳拉雷克斯是谁","纳拉雷克斯的梦魇","哀嚎洞穴的德鲁伊怎么了"}}},fx={["58e10be2"]={q="变异皮革有什么用？",a="变异皮革具有奇异的异界特性，源自侵蚀洞穴的梦魇。它们的来源生物虽然扭曲而凶恶，纳尔帕克却相信，可以通过制皮将这些异样的毛皮制成结实的护甲和背包，从腐化之中变出有用之物。",al={"变异皮革用途","为什么要收集变异皮革","变异皮革的用途"}}},fp="13,301,24.394.0,17.351.0,24.224.0,27.284.0,33.172.0,40.193.0,49.187.0,25.248.0"}
P.entries["quest:1487"] = {n="清除变异者",s="清除变异者是暗夜精灵德鲁伊厄布鲁在哀嚎洞穴入口上方交付的一项任务。其他信徒专注于唤醒沉睡的领袖，厄布鲁则请冒险者清除洞穴中由他扭曲的幻象催生的变异野兽。清除地下绿洲中的这些恐怖生物，是遏制威胁贫瘠之地的腐化的重要一步。",h="清除变异者是暗夜精灵德鲁伊厄布鲁在哀嚎洞穴入口上方交付的一项任务。其他信徒专注于唤醒沉睡的领袖，厄布鲁则请冒险者清除洞穴中由他扭曲的幻象催生的变异野兽。清除地下绿洲中的这些恐怖生物，是遏制威胁贫瘠之地的腐化的重要一步。",kw={"贫瘠之地","变异尖牙风蛇","清除变异者","变异破坏者","变异蹒跚者","变异剧毒风蛇","厄布鲁","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="洞穴中扭曲的生态无声地警示着人们：与翡翠梦境的交融一旦酿成灾难，便会带来这样的后果。",["faction:Horde"]="哀嚎洞穴位于卡利姆多中部平原的腹地，因此，消灭这些凶猛的掠食者，对于保护十字路口等附近聚落至关重要。",["race:NightElf"]="目睹纳拉雷克斯的崇高愿景沦为噩梦催生的恐怖景象，对kaldorei旅人而言是沉重的负担，他们觉得自己有责任帮助受困的同胞。"},sec={{t="误入歧途的梦境",b="暗夜精灵德鲁伊纳拉雷克斯带领追随者来到贫瘠之地的地下泉水旁，怀着一个宏大的愿景：借助翡翠梦境的力量，让干旱的平原重新成为郁郁葱葱、生机盎然的森林。然而，纳拉雷克斯却被困在梦境之中，沉睡化作了痛苦的噩梦。洞穴中涌动的力量未能治愈这片土地，反而扭曲了当地的动植物，使其变成凶残好斗的怪物，人们称之为变异野兽。"},{t="厄布鲁的坚守",b="在俯瞰洞穴入口的崖壁洞窟中，厄布鲁和少数幸存的信徒纳拉雷克斯绝望地看着同伴日渐凋零。其中一些人倾尽心力，试图唤醒陷入沉睡的导师，厄布鲁却意识到眼前迫在眉睫的危机。若放任不管，迅速繁殖的变异毒蛇、蹒跚者、掠夺者和恐牙兽便会涌入贫瘠之地。因此，厄布鲁招募路过的冒险者深入地下隧道，从源头消灭这些畸变的怪物。"}},faq={{q="在哪里能找到厄布鲁并接取这个任务？",a="厄布鲁与几位信徒纳拉雷克斯同伴驻留在哀嚎洞穴主入口高处的一处隐蔽洞窟中，那里看起来就像骷髅状岩层的右眼窝。要到她那里，通常需要绕着山脊攀爬，再小心地跳落到上方的岩台上。",al={"厄布鲁位置","厄布鲁在哪","如何前往厄布鲁处","哀嚎洞穴眼窝洞窟"}},{q="这些野兽为何会发生变异？",a="这些生物因翡翠梦境中渗出的黑暗能量而发生了变异。德鲁伊纳拉雷克斯为了让贫瘠之地重获生机，将意识与地下泉水相连，却被噩梦侵占了心智，使原本用于复苏的能量扭曲成腐化之力，将当地野生动物变成了变异怪物。",al={"为何发生变异","变异野兽起源","什么腐化了哀嚎洞穴的动物"}},{q="信徒纳拉雷克斯是谁？",a="信徒纳拉雷克斯是一群追随纳拉雷克斯的德鲁伊，他们随他来到哀嚎洞穴，帮助贫瘠之地重获生机。他被困在梦魇之后，许多信徒变得狂野或陷入疯狂，只剩下极少数神志清醒的人试图挽回这场灾难。",al={"信徒 纳拉雷克斯","纳拉雷克斯的追随者","哀嚎洞穴的德鲁伊是谁"}},{q="联盟和部落都能接取这个任务吗？",a="可以。厄布鲁和她的同伴都是中立的德鲁伊，致力于保护自然并遏制梦魇。他们接受部落或联盟中有实力的勇士提供的帮助。",al={"清除变异者 联盟还是部落","清除变异者 是否中立任务"}},{q="需要为厄布鲁消灭哪些生物？",a="厄布鲁让你深入洞穴，猎杀四种特定的腐化野兽：变异破坏者、剧毒飞蛇、变异蹒跚者和变异尖牙风蛇，每种消灭七只。",al={"清除变异者 怪物","清除变异者 目标","需要消灭哪些变异生物"}},{q="完成这个任务能唤醒纳拉雷克斯吗？",a="不能。厄布鲁的任务仅限于减少危险野兽的数量，控制兽患并减轻危害。要唤醒纳拉雷克斯，需要深入洞穴中心他的密室，直接施行仪式。",al={"这能否唤醒纳拉雷克斯","如何唤醒纳拉雷克斯"}}},fx={["62e049f1"]={q="厄布鲁为什么要消灭变异野兽？",a="纳拉雷克斯的其他门徒都专注于唤醒被困的主人，而厄布鲁认为哀嚎洞穴中正滋生着迫在眉睫的威胁。纳拉雷克斯曾想让贫瘠之地恢复成郁郁葱葱的森林，如今他的愿景却化为梦魇，令腐化而不自然的生物遍布隧道。厄布鲁认为，在清除这些扭曲的野兽之前，这片土地无望得到治愈，他们的首领也无望获救。",al={"厄布鲁的目的","为什么要杀死变异野兽","厄布鲁为什么想杀死变异野兽"}},b4bfe70b={q="哀嚎洞穴里的变异生物是什么？",a="它们原本是当地的动物——毒蛇、迅猛龙和蹒跚的植物怪物，却被纳拉雷克斯梦魇泄出的黑暗能量扭曲成了怪物。纳拉雷克斯曾试图引导翡翠梦境，让干旱的贫瘠之地重焕生机；但他的梦境变得污浊后，逸散的魔法能量便使野生动物发生变异，成为凶猛而不自然的掠食者，如今它们遍布洞穴深处。",al={"什么是变异掠夺者","哀嚎洞穴的变异野兽","哀嚎洞穴的腐化生物"}},ab17f40e={q="纳拉雷克斯的门徒为什么不能自行清理洞穴？",a="门徒们人手紧缺，根本无力独自发动攻击。自从纳拉雷克斯陷入梦魇，他们的教派便大幅衰落；仅存的几人还分身乏术，一边准备唤醒他的仪式，一边守卫他们仅剩的据点。他们人数不足，战力也不够强，无法深入洞穴并消灭野兽，只能寻求外援。",al={"厄布鲁为什么需要我的帮助","门徒们为什么不能清理洞穴","纳拉雷克斯的门徒为什么需要帮助"}}},fp="19,299,27.325.0,12.379.0,41.270.0,41.254.0,33.256.0,44.161.0,44.182.0,40.166.0"}
P.entries["quest:1488"] = {n="堕落者",s="塔卡塔·钢刃赞同玛乌林的看法：必须阻止魔王阿兹雷索克，尤其是当他企图影响火刃氏族时。塔卡塔相信你能召集一支队伍，对付这位恶魔领主和他的术士仆从祖格卡。",h="塔卡塔·钢刃赞同玛乌林的看法：必须阻止魔王阿兹雷索克，尤其是当他企图影响火刃氏族时。塔卡塔相信你能召集一支队伍，对付这位恶魔领主和他的术士仆从祖格卡。",kw={"火刃氏族","恶魔","凄凉之地","祖格卡","魔王阿兹雷索克","玛乌林","塔卡塔·钢刃","术士"},sec={{t="组队南下",b="塔卡塔从未听说过魔王阿兹雷索克，但他赞同玛乌林的看法，必须阻止这位恶魔领主。如果阿兹雷索克正试图左右火刃氏族，危险就更大了。你已经表明自己愿意帮助大酋长，因此塔卡塔相信你能召集一支队伍，杀死阿兹雷索克和他的术士仆从祖格卡。径直向南前往玛诺洛克集会所，他们都在那里。"},{t="塔卡塔的忧虑",b="塔卡塔认为，凄凉之地的恶魔带来的威胁比以往任何时候都大。每多来一只邪恶的生物，回到大酋长身边的希望就更渺茫一分。有时，塔卡塔真希望敌人只有半人马。"},{t="塔卡塔的定论",b="威胁消除后，塔卡塔称这是属于所有人的伟大胜利。这里的前景并没有塔卡塔曾经担忧的那样黯淡。恶魔已被消灭，火刃氏族的图谋已经失败，一处可以称为家园的地方又恢复了安宁。"}},faq={{q="是谁派冒险者去对付魔王阿兹雷索克？",a="塔卡塔·钢刃赞同玛乌林的看法，相信你能召集一支队伍去对付这位恶魔领主。",al={"谁发布堕落者","堕落者任务发布者","塔卡塔·钢刃任务"}},{q="必须击败谁？",a="必须击败恶魔领主魔王阿兹雷索克和他的术士仆从祖格卡。",al={"要杀谁","堕落者目标","阿兹雷索克和尤卡"}},{q="目标在哪里？",a="塔卡塔让你径直向南，前往凄凉之地南部的玛诺洛克集会所，他们都在那里。",al={"阿兹雷索克在哪里","尤卡·格瑞姆罗德位置","堕落者去哪里"}},{q="为什么魔王阿兹雷索克如此危险？",a="塔卡塔从未听说过阿兹雷索克，但他也认为必须阻止这位恶魔领主，尤其是当他正试图左右火刃氏族时。",al={"为什么杀阿兹雷索克","阿兹雷索克在做什么","与火刃氏族的关联"}},{q="任务链中前一个任务是什么？",a="这一步接在堕落者任务链的第四部分之后。",al={"前置任务","堕落者前一个任务","堕落者任务链"}},{q="塔卡塔对凄凉之地的恶魔有何担忧？",a="塔卡塔认为，恶魔带来的威胁比以往任何时候都大。每多来一只邪恶的生物，回到大酋长身边的希望就更渺茫一分，塔卡塔有时真希望敌人只有半人马。",al={"塔卡塔背景故事","塔卡塔为什么在这里","塔卡塔·钢刃的职责"}}},fp="13,225,20.384.0,14.201.0,16.230.1,49.92.0,21.88.0,30.96.0,42.137.0,36.57.0,51.193.0"}
P.entries["quest:1489"] = {n="哈缪尔·符文图腾",s="这个任务指引部落冒险者离开贫瘠之地葱郁却危机暗藏的绿洲，前往高耸的雷霆崖。图加·符文图腾怀疑哀嚎洞穴深处存在灵魂层面的腐化，派你去寻求大德鲁伊哈缪尔·符文图腾的指引。",h="这个任务指引部落冒险者离开贫瘠之地葱郁却危机暗藏的绿洲，前往高耸的雷霆崖。图加·符文图腾怀疑哀嚎洞穴深处存在灵魂层面的腐化，派你去寻求大德鲁伊哈缪尔·符文图腾的指引。",kw={"长者高地","哈缪尔·符文图腾","绿洲","污染","贫瘠之地","雷霆崖","图加·符文图腾","哀嚎洞穴"},ang={["class:Druid"]="对牛头人德鲁伊而言，向大德鲁伊哈缪尔·符文图腾报到是一次朝圣，拜访这位在玛法里奥·怒风的教导下确立了现代牛头人德鲁伊之道的导师。",["faction:Horde"]="贫瘠之地是新生部落的交通枢纽，调查不断蔓延的污染，有助于保护连接杜隆塔尔、莫高雷和北方哨站的补给线。",["race:Tauren"]="这项使命将贫瘠之地祖传猎场中的隐患，与居住在莫高雷神圣崖顶的部族长者的指引联系起来。"},sec={{t="不安的梦境",b="图加·符文图腾在研究贫瘠之地的野生动物时，发现葱郁绿洲附近的生物正遭受一种奇怪病症的折磨。这些变异野兽的外壳受到了一股非自然力量的污染，让图加意识到，这片土地本身已陷入混乱而不安的梦境。图加确信，这种腐化源自地下哀嚎洞穴中流出的水，深知要进入洞穴，仅凭一位博物学家的智慧远远不够。"},{t="长者高地的指引",b="为了弄清洞穴中的威胁，图加指引你前往雷霆崖，向他的族人大德鲁伊哈缪尔·符文图腾请教。哈缪尔是地位最高的牛头人德鲁伊，也是在莫高雷备受敬重的塞纳里奥议会精神领袖。哈缪尔驻守在宁静的长者高地之巅，关注着卡利姆多各地的异动，并确认渗入贫瘠之地的梦魇是严重的威胁，需要部落勇士全力应对。"}},faq={{q="图加为什么派我去找哈缪尔？",a="图加发现，贫瘠之地的绿洲受到一种源自哀嚎洞穴的怪异病症污染。这种现象仿佛是梦魇笼罩了大地，因此他派你去长者高地拜访大德鲁伊哈缪尔·符文图腾，在任何人尝试进入洞穴之前，先寻求高阶德鲁伊的指引。",al={"为何找哈缪尔","为何与哈缪尔交谈","哈缪尔任务目的"}},{q="哈缪尔·符文图腾在哪里？",a="大德鲁伊哈缪尔·符文图腾位于莫高雷的牛头人主城雷霆崖。他与其他德鲁伊和萨满祭司一同站在长者高地之巅，俯瞰周围的平原。",al={"哈缪尔位置","哈缪尔在哪","寻找哈缪尔 符文图腾"}},{q="图加察觉的污染源自何处？",a="污染源自哀嚎洞穴的地下泉水。这些诡异的泉水正在腐化当地的动植物，使这片土地仿佛陷入了无法逃脱的梦魇。",al={"污染是什么","绿洲腐化","哀嚎洞穴污染"}},{q="与哈缪尔交谈后会发生什么？",a="哈缪尔欢迎你来到雷霆崖，并让你为前方的试炼做好准备。他警告说，应对贫瘠之地下方的梦魇是一项极其凶险的任务，并指引你去找纳拉·蛮鬃，为深入哀嚎洞穴做好准备。",al={"哈缪尔之后的任务","接下来做什么","哈缪尔后续任务"}},{q="哈缪尔·符文图腾是谁？",a="大德鲁伊哈缪尔·符文图腾是牛头人德鲁伊的首要领袖，也是大酋长凯恩·血蹄自幼相交的挚友和顾问。他在第三次大战后学习了自然之道，如今引导牛头人德鲁伊与自然沟通，并融入塞纳里奥议会。",al={"哈缪尔是谁","哈缪尔背景故事","大德鲁伊哈缪尔"}},{q="进入哀嚎洞穴必须完成这个任务吗？",a="踏入哀嚎洞穴无需完成任何准入任务，但这个任务在部落的故事中承上启下，将贫瘠之地葱郁绿洲的谜团与深入地下城的探险联系起来。",al={"哀嚎洞穴准入任务","此任务是否必须完成"}}},fx={a40fa735={q="图加·符文图腾为什么要冒险者去找哈穆尔？",a="图加·符文图腾驻扎在十字路口，密切观察贫瘠之地及其绿洲中蔓延的种种异变。由于他必须留在前线亲自研究遭到腐化的野生动物，因此需要有能力的旅人替他递交报告，并前往雷霆崖的长者高地直接向大德鲁伊哈穆尔·符文图腾寻求指引。",al={"为什么派我去找哈穆尔","图加为什么不能去找哈穆尔","图加为什么派我去"}}},fp="16,189,18.351.0,21.378.0,33.254.0,34.167.0,46.203.0,40.239.0,24.252.0,52.162.0"}
P.entries["quest:149"] = {n="幽灵的发丝",s="伊瓦夫人正在寻找夜色镇以南丘陵中的幽灵头发。她需要用这些发丝为亚伯克隆比纺制幽灵的发丝，于是派旅人前往一座废弃的农舍寻找盲眼玛丽。一把无形的梳子能让他们从这个饱受折磨的幽灵身上收集头发。",h="伊瓦夫人正在寻找夜色镇以南丘陵中的幽灵头发。她需要用这些发丝为亚伯克隆比纺制幽灵的发丝，于是派旅人前往一座废弃的农舍寻找盲眼玛丽。一把无形的梳子能让他们从这个饱受折磨的幽灵身上收集头发。",kw={"盲眼玛丽","夜色镇","暮色森林","农舍","幽灵","幽灵的发丝","伊瓦夫人","鬼梳"},ang={["class:Priest"]="身为牧师，你能从盲眼玛丽的痛苦中，看到暮色森林那些不得安息的亡灵所承受的悲剧与挥之不去的阴影。",["faction:Alliance"]="身为联盟旅人，你能从夜色镇附近农场中徘徊的悲惨幽灵身上，看出曾经繁荣的Grand Hamlet是如何迅速陷入黑暗与孤立的。",["profession:Tailoring"]="用幽灵无形的残余纺线是一门神秘技艺，与普通纺车和织机所做的活计相去甚远。"},sec={{t="占卜师的请求",b="伊瓦夫人需要幽灵头发，为亚伯克隆比纺线。亚麻和羊毛无法用于暮色森林的仪式，因此她给了你一把鬼梳，让你从幽灵身上收集发丝。它能穿过死亡的帷幕，无须伤害幽灵就能梳下松脱的幽灵发丝。"},{t="盲眼玛丽的悲伤",b="在夜色镇以南，盲眼玛丽徘徊在一座废弃的农舍里。这个饱受折磨的幽灵对自己的容貌绝望，尖叫着让闯入者移开目光。她无法忍受自己如今的模样，在痛苦中挖出了自己的双眼。鬼梳能带来片刻慰藉：她可以梳理幽灵般的头发，但折磨仍未止息。"}},faq={{q="盲眼玛丽是谁？",a="盲眼玛丽是一个悲伤的幽灵，徘徊在夜色镇以南丘陵中的一座废弃农舍里。她认定自己丑陋不堪，绝望之下挖出了双眼，好让自己再也看不到自己的模样。尽管已经失明，只要有人看着她，她仍会痛苦地察觉到。",al={"盲眼玛丽背景故事","暮色森林的玛丽是谁","鬼梳女人"}},{q="伊瓦夫人为什么需要幽灵头发？",a="伊瓦夫人需要用幽灵头发纺制幽灵丝线。普通的手工材料不适合暮色森林的仪式，因此她的工作和防护附魔都要依靠神秘的材料。",al={"为什么需要幽灵头发","幽灵的发丝有什么用","伊瓦夫人发丝"}},{q="在哪里能找到盲眼玛丽的住处？",a="盲眼玛丽破败的农舍位于夜色镇以南的丘陵中，越过镇上的墓地就能找到。恐怖的怪物和亡灵在周围的树林里游荡。",al={"盲眼玛丽在哪里","盲眼玛丽位置","夜色镇以南的农舍"}},{q="鬼梳如何作用于幽灵？",a="鬼梳可以触碰幽灵，收集它们的头发。它能穿过灵体，就像普通梳子梳过活人的头发一样，收集到的发丝仍然无形无质。",al={"鬼梳如何起作用","鬼梳背景故事","梳理幽灵头发"}},{q="盲眼玛丽会敌视旅人吗？",a="不会。盲眼玛丽会尖叫、哭泣，但她并不敌视活着的访客。她将痛苦指向自身，而凶暴的生物和亡灵则在树林与附近的建筑中出没。",al={"盲眼玛丽会攻击吗","盲眼玛丽危险吗"}},{q="把梳子交给玛丽后会发生什么？",a="玛丽用过梳子后，会将缠着她幽灵发丝的梳子交还。把它带回夜色镇交给伊瓦夫人，她就能将这些发丝纺成幽灵的发丝。",al={"幽灵头发下一步","归还梳子任务","幽灵的发丝后续"}}},fp="17,228,25.265.0,24.316.0,18.273.0,36.184.0,38.139.0,44.185.0,35.179.0,40.165.0"}
P.entries["quest:1490"] = {n="纳拉·蛮鬃",s="纳拉·蛮鬃是雷霆崖的一位年轻牛头人德鲁伊，正试图查明哀嚎洞穴深处不断上演的悲剧。大德鲁伊哈缪尔·符文图腾窥探翡翠梦境，并从其中滋生的腐化中抽身后，便派遣冒险者前去与纳拉商谈；她凭借顽强的意志坚持了足够长的时间，亲眼目睹梦魇控制了他们的同胞。她是部落在此事中的关键联络人，指引勇士们终结尖牙德鲁伊。",h="纳拉·蛮鬃是雷霆崖的一位年轻牛头人德鲁伊，正试图查明哀嚎洞穴深处不断上演的悲剧。大德鲁伊哈缪尔·符文图腾窥探翡翠梦境，并从其中滋生的腐化中抽身后，便派遣冒险者前去与纳拉商谈；她凭借顽强的意志坚持了足够长的时间，亲眼目睹梦...",kw={"贫瘠之地","尖牙德鲁伊","长者高地","翡翠梦境","哈缪尔·符文图腾","纳拉·蛮鬃","雷霆崖","哀嚎洞穴"},ang={["class:Druid"]="纳拉敢于深入翡翠梦境中险恶而腐化的地域，这份勇气会赢得德鲁伊们的敬重，就连哈缪尔这样的资深大师也不愿在那里久留。",["faction:Horde"]="纳拉的警觉守护着部落领土的腹地，确保那些扭曲贫瘠之地的黑暗能量不会肆无忌惮地蔓延至莫高雷。",["race:Tauren"]="对于那些刚刚在哈缪尔门下踏上德鲁伊之道的牛头人而言，纳拉代表着年轻而不屈的一代，愿意迎面抗击违背自然的枯萎之灾。"},sec={{t="腐化的幻象",b="当种种怪异、违背自然的现象开始在贫瘠之地蔓延时，大德鲁伊哈缪尔·符文图腾进入翡翠梦境，探寻其中的缘由。在那里，他目睹了一群德鲁伊组成的教派，他们原本想让干旱的草原重获生机，却因邪恶的污染而丧失了心智。哈缪尔年事已高，无法长久抵御梦魇的侵袭，只得逃回清醒的世界。然而，他年轻的弟子纳拉·蛮鬃不愿轻易屈服。她凭借炽烈的决心在梦境中坚持了更长时间，得以亲眼观察这个已然蜕变的教派。"},{t="直面梦魇",b="哈缪尔为雷霆崖的塞纳里奥议会指引大局，而纳拉·蛮鬃则掌握着清除腐化所需的战术情报。她曾直视那些堕落德鲁伊扭曲、覆满蛇鳞的面容，知晓他们的罪行，以及他们企图给卡利姆多带来的灾难。她的决心标志着部落开始向哀嚎洞穴进军，消灭那些背弃神圣誓言的首领。"}},faq={{q="纳拉·蛮鬃是谁？",a="纳拉·蛮鬃是一位年轻而意志坚定的牛头人德鲁伊，居住在雷霆崖的长者高地。她师从大德鲁伊哈缪尔·符文图腾，无惧直面那些威胁自然平衡、带来腐化的梦魇。",al={"纳拉是谁","纳拉 蛮鬃的故事","纳拉·蛮鬃 雷霆崖"}},{q="哈缪尔·符文图腾为何派旅人与她交谈？",a="哈缪尔承认，自己年事已高，力量日渐衰退，无法在尖牙德鲁伊盘踞的腐化梦境中久留。纳拉年轻且意志坚定，因此在梦境中停留了更长时间，收集到了有关这个教派计划的重要情报。",al={"为何与纳拉交谈","哈缪尔到纳拉","哈缪尔为何派我来这里"}},{q="纳拉在翡翠梦境中看到了什么？",a="纳拉亲眼目睹了栖身于哀嚎洞穴的堕落德鲁伊。她看到他们的面孔扭曲成覆满鳞片的蛇形面容，也洞悉了他们打算在贫瘠之地实施的阴谋与罪行。",al={"纳拉看到了什么","纳拉的梦境幻象","梦中覆鳞的德鲁伊"}},{q="在哪里可以找到纳拉·蛮鬃？",a="她就在雷霆崖长者高地顶上的一座德鲁伊帐篷里，位于大德鲁伊哈缪尔·符文图腾的正对面。",al={"纳拉在哪里","纳拉 蛮鬃的位置","寻找纳拉 蛮鬃"}},{q="向纳拉·蛮鬃报告后会发生什么？",a="与她交谈后，纳拉会指示你进入哀嚎洞穴，杀死叛离正道的尖牙德鲁伊，由此开启重要的地下城任务“尖牙德鲁伊”。",al={"纳拉之后的任务","纳拉要我做什么","尖牙德鲁伊后续"}},{q="哀嚎洞穴中的德鲁伊为何会被腐化？",a="在纳拉雷克斯的带领下，德鲁伊们进入洞穴，希望借助翡翠梦境的力量，让贫瘠之地重焕蓬勃生机。然而，纳拉雷克斯的沉睡却化作了可怕的梦魇，将他的追随者困在其中，并把他们扭曲成蛇形的尖牙德鲁伊。",al={"哀嚎洞穴教派","尖牙德鲁伊为何邪恶","贫瘠之地的德鲁伊为何邪恶"}}},fx={["2cdff5a8"]={q="为什么大德鲁伊哈缪尔·符文图腾让你去找纳拉，而不是亲自前往？",a="大德鲁伊哈缪尔·符文图腾年事已高，且多次深入灵界令他身心俱疲。当他进入翡翠梦境调查哀嚎洞穴的异变时，力量不支，只得退了出来。纳拉·蛮鬃年轻而勇猛，在他离开后仍留在梦境之中。哈缪尔如今身在雷霆崖，负责协调牛头人德鲁伊；他所剩无几的精力也经不起奔波传话或独自面对威胁，因此只能托付给有能力的旅人，去打探纳拉的发现。",al={"哈缪尔为什么让我去找纳拉","哈缪尔为什么不能和纳拉谈","为什么派冒险者去找纳拉"}}},fp="13,270,22.497.0,25.408.1,21.173.0,59.226.0,39.173.0,33.123.0,46.170.0,52.251.0"}
P.entries["quest:1491"] = {n="智慧饮料",s="智慧饮料是棘齿城的地精商人麦伯克·米希瑞克斯想出的生财计划。他没能用 赤鳞 迅猛龙的角酿出提升智力的补剂，如今便让冒险者深入哀嚎洞穴，采集灵质残渣，用于他最新的饮料配方。",h="智慧饮料是棘齿城的地精商人麦伯克·米希瑞克斯想出的生财计划。他没能用 赤鳞 迅猛龙的角酿出提升智力的补剂，如今便让冒险者深入哀嚎洞穴，采集灵质残渣，用于他最新的饮料配方。",kw={"贫瘠之地","灵质","麦伯克·米希瑞克斯","迅猛龙角","棘齿城","智慧饮料","哀嚎洞穴","哀嚎香精"},ang={["class:Druid"]="德鲁伊进入哀嚎洞穴，是为了净化扭曲翡翠色梦境的梦魇，麦伯克却只把这场悲惨的生态污染看作自家零售生意所需的廉价糖浆。",["faction:Horde"]="对于穿行在贫瘠之地各条交汇道路上的旅人，棘齿城的商人提供了许多赚快钱的机会，只要你别过问太多，不去打听他们准备拿你送来的怪物肢体做什么。",["profession:Cooking"]="任何厨师都能立刻看出棘齿城正在上演的卫生灾难：将未经处理、受梦魇污染的灵质直接浸入供人饮用的补剂，违背了所有食品安全标准。"},sec={{t="灾祸的配方",b="麦伯克·米希瑞克斯在繁忙的港口城镇棘齿城经营生意，将地精的典型信条奉行到底：把当地任何古怪现象都变成实实在在的金币。他坚信，提升智力的药剂能让自己一夜暴富，起初还认定秘诀就藏在磨成粉末的迅猛龙角中。那一批饮料的效果实在乏善可陈，于是他干脆盯上了更可疑的原料：从附近哀嚎洞穴中渗出的腐化精华。"},{t="哀嚎香精",b="贫瘠之地出现了令人不安的生态异变，葱郁的绿洲突然涌现，当地野生动物也扭曲成了凶暴的怪物。米希瑞克斯推测，这些骤变的诱因是一种被他称为“哀嚎香精”的奇异物质。他断定，既然这种东西能让生物发生如此剧烈的变化，必定也能成为强效的秘密原料，于是派出雇佣兵，消灭洞穴迷宫深处那些黏液淋漓的灵质怪，将它们发光的体液直接抽进饮料瓶。"}},faq={{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是个颇有生意头脑的地精，驻留在港口城镇棘齿城。他对卫生规范毫不在意，一心想调制出一种能在卡利姆多各地销售的“聪明饮料”，借此发家致富。",al={"麦伯克·米希瑞克斯","谁提供 智慧饮料","智慧饮料 任务给予者"}},{q="为什么迅猛龙角没有效果？",a="麦伯克起初相信，将 赤鳞 迅猛龙的角磨碎，就能调制出强效的智力增强饮剂。结果，这种饮料并未如他所言让人变成天才，迫使他转而采用危险得多的有效成分。",al={"迅猛龙角为何无效","迅猛龙角饮料"}},{q="哀嚎香精是什么？",a="哀嚎香精是一种灵质物质，从哀嚎洞穴深处那些违背自然的软泥怪身上滴落。麦伯克相信，这种不稳定的物质正是催生贫瘠之地各处奇异动植物异变的根源。",al={"哀嚎香精是什么","哀嚎洞穴的香精"}},{q="携带香精的灵质怪在哪里？",a="这种香精采自不断进化、吞噬猎物以及带有梦魇之力的灵质生物，它们潜伏在棘齿城以西哀嚎洞穴的地下通道中。",al={"灵质怪在哪里","智慧饮料 任务怪物","谁掉落哀嚎香精"}},{q="聪明饮料喝起来安全吗？",a="这种香精采自梦魇般的软泥怪，而这些怪物又与贫瘠之地各处的腐化异变有关，把它装瓶当作商品补剂出售，实在是鲁莽至极。麦伯克恪守地精的经商之道，远比起顾客的安全，他更在乎产品是否卖得出去。",al={"聪明饮料是否有毒","饮料是否有效"}},{q="完成智慧饮料后还有什么？",a="智慧饮料为麦伯克眼下的饮料生意画上了句号。他对你送来的哀嚎香精十分满意，给了你报酬，还承诺等那可疑的补剂让他发了财，就与你分享今后的利润。",al={"智慧饮料 后续任务","智慧饮料 完成后做什么"}}},fx={b3462a0e={q="麦伯克·米希瑞克斯为什么想要哀嚎香精？",a="麦伯克·米希瑞克斯是棘齿城一名野心勃勃的地精商人，一心想发大财。他最初试图用迅猛龙角制作增强智力的饮料，却没能成功，于是转而采用一种危险得多的原料。他认为，贫瘠之地动植物身上那些扭曲的奇异变异，源自哀嚎香精蕴含的强大能量；他打算将香精直接加入自己的配方，制成号称神奇的聪明饮料，大赚一笔。",al={"麦伯克的动机","麦伯克为什么想要聪明饮料","为什么要制作聪明饮料"}},["6730f7d3"]={q="携带香精的外质是什么？",a="外质是栖居在哀嚎洞穴深处的奇异软泥状实体。绿洲裂隙下方聚集着不稳定的腐化能量，当地的地下精华便凝结成不断变异、吞噬一切的梦魇幽灵软泥怪。这些没有心智的实体吸收着洞穴中原始而致变异的能量，将奇异的哀嚎香精聚集在不断变形的躯体之中，直到有人将其采集。",al={"什么是外质","哀嚎洞穴的外质","谁携带着香精"}}},fp="12,184,21.302.0,19.317.0,22.128.0,33.171.0,24.187.0,54.145.0,35.201.0,41.179.0"}
P.entries["quest:1492"] = {n="码头管理员迪兹维格",s="棘齿城的码头上，一箱炼金物资正等待运往海的另一边。码头管理员迪兹维格安排将它装上一艘驶往黑水湾的船，送往卡利姆多。",h="棘齿城的码头上，一箱炼金物资正等待运往海的另一边。码头管理员迪兹维格安排将它装上一艘驶往黑水湾的船，送往卡利姆多。",kw={"黑水湾","码头","栈桥","棘齿城","保险箱","航运","贫瘠之地","码头管理员迪兹维格"},ang={["faction:Horde"]="作为一名穿行于贫瘠之地的部落冒险者，你可以将货物送到棘齿城，并了解连接卡利姆多与东部王国的海上航线。"},sec={{t="前往港口的信使",b="贫瘠之地的港口里，一箱药水和材料正等待运往卡利姆多的同行手中。原本可以运送这箱货物的商队已经出发，因此你受托将这批妥善封装的货物送到棘齿城的码头。这个港口提供横跨无尽之海、往来于卡利姆多与东部王国之间的航线。"},{t="棘齿城的码头",b="码头管理员迪兹维格在棘齿城的木制码头上经管货物。他通过账簿和货单追踪货物，再为它们安排舱位，装上向东横渡无尽之海的船只。这箱货物已经订好舱位，将随船运往黑水湾。"}},faq={{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格是棘齿城主码头上的地精港务官。他管理船舶货单、货舱，以及卡利姆多与海对岸各港口之间的航运。",al={"码头管理员迪兹维格","迪兹维格 是谁","迪兹维格 在哪里"}},{q="这箱货物要送到哪里？",a="这箱药水和材料将搭乘下一艘从棘齿城驶往黑水湾的船，运往卡利姆多。",al={"箱子运往哪里","黑水湾","箱子的目的地"}},{q="棘齿城在哪里？",a="棘齿城位于贫瘠之地东海岸的一处避风海湾，就在中部十字路口的正东方。",al={"棘齿城位置","如何找到棘齿城"}},{q="为什么通过地精港口运送货物？",a="棘齿城是一座向部落和独立商人开放的中立港口。这里的定期航线横跨无尽之海，避开了军事封锁和政治敌对。",al={"为什么选择棘齿城","为什么使用地精港口"}},{q="保险箱里装着什么？",a="保险箱里装着调配好的药水、制造材料和其他炼金货物，要送给东部王国的同伴。",al={"箱内物品","箱子里有什么"}},{q="谁把这批货物送给迪兹维格？",a="贫瘠之地的一位炼金师错过了出发的商队，于是托人送出这批货物。现在需要一位可靠的跑腿人，在下一次涨潮前将货物送到码头。",al={"谁提供任务","任务给予者"}}},fp="20,158,21.303.0,15.252.0,28.158.0,30.138.0,25.103.0,37.159.0,32.126.0,35.164.0"}
P.entries["quest:1498"] = {n="防御之道",s="在前沿哨所，犹塞克训练年轻的部落战士，让他们保护无力自保的人。他派他们前往雷霆山，与那里能释放电击的野兽交锋，证明自己的耐力。",h="在前沿哨所，犹塞克训练年轻的部落战士，让他们保护无力自保的人。他派他们前往雷霆山，与那里能释放电击的野兽交锋，证明自己的耐力。",kw={"贫瘠之地","杜隆塔尔","前沿哨所","防御之道","烧焦的鳞片","雷霆蜥蜴","雷霆山","犹塞克"},ang={["class:Warrior"]="身为战士，你开始学习防御之道：真正的战斗力量，在于保护盟友免遭毁灭。",["faction:Horde"]="在前沿哨所，部落守卫保护着通往贫瘠之地的道路，因此他们的坚韧关乎部落的安全。"},sec={{t="部落之盾",b="在前沿哨所，犹塞克教导年轻的战士，防御也是部落的职责。哨所位于贫瘠之地与杜隆塔尔的交界处。犹塞克说，战士最崇高的使命，就是挡在危险与无力自保的人之间，承受打击，让部落得以存续。"},{t="雷霆的试炼",b="犹塞克派新兵向北跨过怒水河，前往杜隆塔尔的雷霆山，考验他们的耐力与决心。雷霆蜥蜴和闪电蜥蜴在峡谷中游荡。新兵必须承受住这些野兽的电击，并收集它们身上的烧焦的鳞片，证明自己有坚守前线的毅力。"}},faq={{q="谁发布防御之道任务？",a="老兵犹塞克在前沿哨所交付这项试炼，这座哨所守卫着杜隆塔尔与贫瘠之地东部之间的边界。",al={"任务发布者","谁发布防御之道","犹塞克位置"}},{q="雷霆山在哪里？",a="雷霆山位于杜隆塔尔西部，跨过怒水河上的桥后，在主路以北。凶猛的雷霆蜥蜴和闪电蜥蜴在山谷中游荡。",al={"雷霆山位置","雷霆蜥蜴在哪里","烧焦的鳞片位置"}},{q="犹塞克为什么指定要烧焦的鳞片？",a="犹塞克要求收集雷霆山中那些能释放电击的野兽身上的烧焦的鳞片。承受住它们的电击，就能证明战士拥有学习高深防御技巧所需的坚韧与耐力。",al={"为什么要烧焦的鳞片","鳞片的用途"}},{q="这项试炼蕴含着怎样的理念？",a="犹塞克教导战士，他们的职责不只是杀戮，更是保护他人。在野兽的狂怒中存活下来，能帮助新兵学会保护弱小的盟友。",al={"战士的理念","防御之道背景故事","防御姿态背景故事"}},{q="完成防御之道之后要做什么？",a="向犹塞克证明你的防御本领后，他会指引你前去跟随索恩格瑞姆·火眼继续接受战斗训练。",al={"下一个任务","防御之道之后做什么","后续任务"}},{q="其他职业也能接受这项试炼吗？",a="不能。这项仪式只面向战士，既考验新兵，也传授守卫职责与防御作战的基础知识。",al={"是否仅限战士","谁能做这个任务"}}},fp="15,187,23.298.0,16.317.0,36.107.0,31.173.0,49.201.0,51.159.0,49.121.0,38.107.0"}
P.entries["quest:1499"] = {n="邪灵劣魔",s="在试炼谷，鲁赞派术士学徒去对付邪恶魔仆。杀死它们后，你要向祖雷萨复命，她负责遏制火刃氏族的行动。",h="在试炼谷，鲁赞派术士学徒去对付邪恶魔仆。杀死它们后，你要向祖雷萨复命，她负责遏制火刃氏族的行动。",kw={"火刃集会所","杜隆塔尔","小鬼","鲁赞","大兽穴","试炼谷","邪恶魔仆","术士任务","祖雷萨"},ang={["class:Warlock"]="身为术士，你要直面邪恶魔仆，证明自己能够支配并消灭失控的邪能生物，而不被它们所害。",["race:Orc"]="身为兽人，你知道恶魔仆从会让人想起那些曾奴役你族人的黑暗契约。将它们从杜隆塔尔的土地上清除，关系到你族人的生存。",["race:Troll"]="身为暗矛巨魔，你与其他人一同在试炼谷接受试炼，他们对恶魔魔法深怀戒心。你需要对抗肆意妄为的教徒，以此表明自己的忠诚。"},sec={{t="纪律的考验",b="试炼谷的战士和斥候直接听命于祖雷萨，她派他们去遏制火刃集会所的势力。术士学徒则先听命于鲁赞，这位与暗影为伴的导师。他要求你证明自己能够驾驭低等恶魔，才会派你回去协助部落的防御。你的行动既为术士效力，也保障了大兽穴的安全。"},{t="集会所的威胁",b="祖雷萨监视着试炼谷上方的北部洞穴。邪恶魔仆藏身其中，它们是火刃氏族教徒最弱小的宠物。它们出现在这片神圣的试炼之地，既是对兽人的侮辱，也威胁着试炼谷。你前来报告战果时，也证明了修习邪能魔法的人依然愿意保卫杜隆塔尔，使其免遭腐化。"}},faq={{q="鲁赞为什么让我去见祖雷萨，而不是亲自奖励我？",a="祖雷萨统筹试炼谷的防御，以及清剿火刃氏族的行动。鲁赞考验你控制低等邪能生物的能力，然后派你去见祖雷萨，让她认可你的功绩，并将其纳入试炼谷的防御行动。",al={"为何去见祖雷萨","鲁赞到祖雷萨","为何与祖雷萨交谈"}},{q="邪恶魔仆是什么？",a="邪恶魔仆是受火刃集会所束缚的低等恶魔，包括小鬼和仆从。它们在俯瞰试炼谷的洞穴深处，侍奉着更为邪恶的主人。",al={"邪恶魔仆是什么","邪恶魔仆背景故事","魔仆与火刃氏族"}},{q="在哪里能找到祖雷萨？",a="祖雷萨就在试炼谷大兽穴中央附近的露天处，从鲁赞所在的训练师营地向上走一小段路就能找到她。",al={"祖雷萨在哪里","祖雷萨位置","祖雷萨地图"}},{q="为什么还有一个名字完全相同的任务？",a="大多数冒险者直接从祖雷萨那里接到邪灵劣魔，为她猎杀这些生物。术士则从鲁赞那里接到一个单独的任务，完成后再向祖雷萨复命。",al={"两个邪灵劣魔任务","重复的邪灵劣魔","术士邪灵劣魔"}},{q="火刃氏族在试炼谷做什么？",a="火刃氏族的教徒在杜隆塔尔各处的隐秘据点活动，企图从内部瓦解萨尔建立的新部落。他们以试炼谷内的一处洞穴为据点，袭击尚未证明自己的新手，在兽人监工的眼皮底下散播恶魔的腐化。",al={"火刃氏族与试炼谷","教徒为何在大兽穴"}},{q="杀死这些魔仆就能消灭这个教派吗？",a="不能。邪恶魔仆是集会所内部更为邪恶的势力豢养的宠物和斥候。击败它们，只是揭露并清除试炼谷内更深层教徒威胁的第一步。",al={"火刃氏族是否已被击败","教徒是否已被清除"}}},fp="14,181,22.338.0,23.341.0,75.250.0,27.166.0,34.155.0,52.189.0,56.267.0,47.175.0"}
P.entries["quest:15"] = {n="回音山调查行动",s="狗头人在回音山矿洞大举集结，治安官玛克布莱德因此派你前往北方。这座矿洞为北郡修道院及驻守那里的暴风城卫兵供应矿石和原材料。",h="狗头人在回音山矿洞大举集结，治安官玛克布莱德因此派你前往北方。这座矿洞为北郡修道院及驻守那里的暴风城卫兵供应矿石和原材料。",kw={"回音山","艾尔文","狗头人","狗头人劳工","治安官玛克布莱德","矿洞","北郡","北郡山谷"},ang={["faction:Alliance"]="狗头人已逼近暴风城位于北郡的精神中心。它们的存在表明，当常备军疲于奔命时，王国是何等脆弱。",["profession:Mining"]="回音山矿洞出产的铜对北郡的铁匠至关重要。清理地下矿道关系着矿工们的生计。",["race:Human"]="作为一名刚在北郡山谷开始服役的年轻人类，抵御地下害物、保卫回音山，让你早早就有机会向王国证明自己的价值。"},sec={{t="日益蔓延的侵扰",b="零散的害物一直在北郡附近的山谷林缘滋事。如今，斥候报告说，它们正更有组织地集结。在入口处，你迎战狗头人劳工，并发现它们已深入矿洞盘踞。"},{t="修道院的财富受威胁",b="狗头人占据了矿道，迫使采矿作业停顿。它们的存在让北郡兄弟会的防务吃紧。玛克布莱德要求你消灭十名劳工，但侵扰已蔓延至矿井深处，超出了地面巡逻队所能触及的范围。"}},faq={{q="是谁派我执行这项任务？",a="治安官玛克布莱德统领着北郡修道院的暴风城卫兵，在斥候报告狗头人在北方集结后，他便派你前往那里。",al={"任务给予者","谁给予任务","治安官玛克布莱德"}},{q="回音山矿洞在哪里？",a="回音山矿洞位于北郡山谷最北端，坐落在修道院及其葡萄园上方的山麓地带。",al={"回音山位置","矿洞在哪里","寻找回音山"}},{q="为什么狗头人会威胁北郡？",a="狗头人繁殖迅速，成群结队地在地下矿道中涌动。它们占据回音山矿洞，阻断了至关重要的采矿作业，也让兵力不足的北郡山谷面临被吞没的危险。",al={"为什么杀狗头人","狗头人为何构成威胁","狗头人的危险"}},{q="击败外面的劳工后会发生什么？",a="你返回后，治安官玛克布莱德最担心的事得到了证实：整座矿洞都已被狗头人盘踞。他在回音山清剿行动中征求你的援助，准备进一步深入矿井。",al={"接下来做什么","后续任务","下一个任务"}},{q="为什么暴风城军队不亲自清理矿洞？",a="瓦里安·乌瑞恩国王失踪，艾尔文及周边边境的资源又捉襟见肘，北郡驻军兵力太少，无法抽调完整的巡逻队清剿害物。卫兵们只能依靠有能力的新兵。",al={"暴风城卫兵在哪里","为什么用新兵","暴风城驻军"}},{q="矿洞入口附近有哪些狗头人？",a="狗头人劳工在矿洞入口和上层通道附近劳作。它们挖掘矿道，收集蜡烛用的蜡，供地下族群使用。",al={"狗头人种类","要消灭什么敌人","狗头人劳工"}}},fx={ffd728b0={q="治安官玛克布莱德为什么要调查回音山矿洞？",a="治安官玛克布莱德的斥候发现，狗头人的数量远比北郡驻军最初预想的多。这些生物已经不再局限于小型营地，而是在回音山矿洞附近扎下了根，威胁着当地一处重要的资源产地。治安官玛克布莱德需要你在山谷的防线被彻底冲垮之前，削减它们的前沿兵力，并查明矿洞深处是否还有更庞大的部队正在构筑据点。",al={"为什么清剿回音山","治安官玛克布莱德的动机","为什么调查回音山矿洞"}}},fp="22,180,23.217.0,28.245.0,29.132.0,37.111.0,40.183.0,48.180.1,57.216.0,56.134.0"}
P.entries["quest:150"] = {n="鱼人偷猎者",s="止水湖畔的鱼人偷猎者正在将湖畔镇水域中的鱼捕捞一空。码头管理员巴伦需要你削减它们日益壮大的队伍，以免小镇失去主要的食物来源。",h="止水湖畔的鱼人偷猎者正在将湖畔镇水域中的鱼捕捞一空。码头管理员巴伦需要你削减它们日益壮大的队伍，以免小镇失去主要的食物来源。",kw={"码头管理员巴伦","矮人钓鱼竿","止水湖","湖畔镇","鱼人的鳍","偷猎者","赤脊山"},ang={["faction:Alliance"]="湖畔镇已经在blackrock兽人和豺狼人的威胁下疲于应付，这座联盟小镇几乎无力保护止水湖中至关重要的食物来源。",["race:Human"]="身为人类，你知道赤脊山曾是暴风城王国一处宁静的度假胜地。如今，敌对的鱼人遍布这里纯净的山间水域，足见当地秩序已衰败到何种地步。"},sec={{t="小镇粮食告急",b="码头管理员巴伦需要你保护供养湖畔镇的鱼群。止水湖为这座山间小镇及其集市提供新鲜渔获。如今，大群鱼人部族挤满了浅滩，在水中四处觅食。若不加以遏制，它们可能会将当地的鱼捕捞殆尽，让湖畔镇失去主要的食物来源。"},{t="奇怪的内陆迁徙",b="鱼人通常沿海岸觅食，因此很难解释为何赤脊山的高处会出现如此多的鱼人。码头管理员巴伦想知道，它们为何来到离大海如此遥远的地方。它们可能在躲避海中的捕食者，也可能在领地争夺中落败，或是被止水湖丰富的水产吸引而来。无论是什么将它们带到内陆，它们的出现都表明这片地区的其他地方出了问题。"}},faq={{q="码头管理员巴伦是谁？",a="码头管理员巴伦负责管理湖畔镇止水湖岸边的码头和渔船往来。他经手水路运来的物资，并雇用你抵御水中威胁，保护湖中的资源。",al={"巴伦","谁提供鱼人偷猎者任务","码头管理员巴伦"}},{q="赤脊山为什么会有鱼人？",a="鱼人通常生活在海岸和沼泽地带，因此它们出现在海拔较高的止水湖很不寻常。码头管理员巴伦怀疑，这些部族是为了躲避沿海更可怕的威胁才来到内陆的。",al={"止水湖为什么有鱼人","赤脊山内陆鱼人","湖里为什么有鱼人"}},{q="鱼人对湖畔镇构成了什么威胁？",a="湖畔镇依靠止水湖获取鱼类并开展贸易。鱼人部族在湖中滥捕，威胁着小镇主要的食物来源和当地贸易。",al={"为什么杀鱼人","湖畔镇鱼人问题","止水湖鱼类枯竭"}},{q="码头管理员巴伦为什么收集鱼人的鳍？",a="码头管理员巴伦收集八个鱼人的鳍，作为你已削减沿岸鱼人部族数量、帮助遏制它们推进的证明。",al={"为什么收集鱼人的鳍","湖畔镇鱼人鳍悬赏"}},{q="还有其他与止水湖鱼人有关的任务吗？",a="有。码头管理员巴伦还提供卖鱼任务，要你带回湖中著名的斑点太阳鱼，可以垂钓获取，也可以从鱼人身上取得。",al={"卖鱼任务关联","赤脊山其他鱼人任务"}},{q="清除偷猎者后，码头管理员巴伦会给什么奖励？",a="交给他八个鳍后，码头管理员巴伦会送你一根做工精良的矮人钓鱼竿，鼓励你爱护这片湖水。",al={"鱼人偷猎者奖励","矮人钓鱼竿任务"}}},fp="15,161,29.317.0,24.382.0,24.202.0,38.209.0,45.156.0,46.132.0,57.152.0,65.135.0"}
P.entries["quest:1501"] = {n="虚空中的生物",s="在奥格瑞玛，甘鲁尔·血眼派一名年轻术士去找回被盗的维尔加石板。背叛部落的火刃氏族教徒将它带到了骷髅石的洞穴中，而召唤虚空行者需要用到石板上的符文。",h="在奥格瑞玛，甘鲁尔·血眼派一名年轻术士去找回被盗的维尔加石板。背叛部落的火刃氏族教徒将它带到了骷髅石的洞穴中，而召唤虚空行者需要用到石板上的符文。",kw={"火刃氏族","暗影裂口","虚空中的生物","甘鲁尔·血眼","奥格瑞玛","骷髅石","维尔加石板","虚空行者","术士任务"},ang={["class:Warlock"]="身为术士，你将面对一项至关重要的试炼：不再只召唤小小的小鬼，而是驾驭能在前线作战的暗影仆从。",["faction:Horde"]="身为萨尔麾下的部落一员，你所属的族群对邪能施法者心怀戒备。甘鲁尔这样的导师会引导研习黑暗法术的人，让他们运用自己的力量为大酋长效力。",["race:Orc"]="身为受Shadow Council历史阴影困扰的兽人，你可以通过猎杀火刃氏族，稍偿复仇之愿，因为他们的成员仍在拥抱恶魔带来的毁灭。"},sec={{t="凶险的技艺",b="甘鲁尔·血眼在奥格瑞玛的暗影裂口训练部落术士。兽人氏族的黑暗历史让萨尔新建的国度对邪能魔法深怀戒心。甘鲁尔说，部落中真正的术士已所剩无几，但这些危险的技艺对部落的生存至关重要。要为大酋长效力，学徒就不能只掌握小鬼的混乱之火；他们还必须驾驭由纯粹暗影构成、坚韧无比的生物。"},{t="失窃的石板",b="召唤虚空行者所需的符文刻在维尔加石板上。火刃氏族是一个狂热的暗影教派，他们偷走了这件圣物，就藏在大酋长眼皮底下的骷髅石洞穴中。甘鲁尔派你深入教徒的巢穴，夺回石板，并给这些玷污所有术士名声的叛徒一次血的教训。"}},faq={{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是奥格瑞玛暗影裂口的一位资深术士训练师。他负责指导年轻的部落术士，教他们驾驭黑暗力量、束缚异界仆从，同时避免堕入腐化。",al={"甘鲁尔","甘鲁尔·血眼","任务给予者"}},{q="维尔加石板是什么？",a="维尔加石板上刻着从虚空召唤虚空行者所需的专用召唤符文。火刃氏族偷走了它，而甘鲁尔需要用它来引导学徒完成仪式。",al={"维尔加石板","石板是什么"}},{q="骷髅石在哪里？",a="骷髅石是一处幽暗的洞穴，位于奥格瑞玛正东面、杜隆塔尔崎岖的峭壁沿线。火刃氏族教徒就藏在那里。",al={"骷髅石位置","骷髅石在哪","石板在哪找"}},{q="甘鲁尔·血眼为何鄙视火刃氏族？",a="火刃氏族侍奉恶魔主人，暗中破坏萨尔的部落。在甘鲁尔看来，这个教派既是大酋长的麻烦，也是肆意妄为的祸害，让所有术士都遭到猜疑、蒙受恶名。",al={"火刃氏族术士","为何憎恨火刃氏族"}},{q="术士为什么需要召唤虚空行者？",a="虚空行者是来自虚空的生物，能承受大量伤害，保护召唤者。学会束缚虚空行者，是术士增强生存能力、提升召唤力量的关键一步。",al={"为何召唤虚空行者","虚空行者用途"}},{q="取回石板后会发生什么？",a="甘鲁尔收到维尔加石板后，会将所需的符文交给学徒，并召他们前来，在《誓缚》中完成仪式。在那里，术士必须亲手制服召唤出的虚空行者，才能驾驭它。",al={"后续任务","接下来做什么"}}},fp="20,212,16.387.0,17.324.0,24.196.0,28.173.0,20.116.0,52.201.0,44.180.0,41.214.1"}
P.entries["quest:1502"] = {n="索恩格瑞姆·火眼",s="在荆棘岭顶，索恩格瑞姆·火眼守着一座孤零零的熔炉，过着隐居的生活。部落战士初步学会防御技巧后，便穿越贫瘠之地前来寻找他，求取与日益精进的武艺相称的兵刃。",h="在荆棘岭顶，索恩格瑞姆·火眼守着一座孤零零的熔炉，过着隐居的生活。部落战士初步学会防御技巧后，便穿越贫瘠之地前来寻找他，求取与日益精进的武艺相称的兵刃。",kw={"铁匠","十字路口","锻造钢铁","贫瘠之地","荆棘岭","索恩格瑞姆·火眼","犹塞克","战士武器"},ang={["class:Warrior"]="作为一名年轻的部落战士，你被派往荒野寻找索恩格瑞姆，争取获得一把独具特色的锻造武器，配合你的战斗训练。",["faction:Horde"]="部落依靠经验丰富的工匠，用他们打造的优质钢铁兵器武装保卫卡利姆多的前线士兵。",["profession:Blacksmithing"]="索恩格瑞姆遵循着兽人独自锻造的传统，忍受孤独与失明，将炽热的金属打造成致命的利器。"},sec={{t="山脊上的隐士",b="当你在犹塞克这样的资深训练师指导下展现出防御技巧后，就会被派去寻找合适的兵刃，进一步磨炼战技。寻常军械库能为前线战士提供的帮助终究有限。要真正精通武艺，就需要一位名匠为你打造专属武器。在贫瘠之地，这位铁匠就是索恩格瑞姆·火眼，他是一名年迈的兽人，早已远离聚居地的生活，独自守着平原上方高处的一座熔炉。"},{t="炉火中的一生",b="索恩格瑞姆·火眼住在荆棘岭顶，这片崎岖的高地位于十字路口以东，野生迅猛龙和充满敌意的野猪人在此游荡。他远离城墙的庇护，在独处的时光里锤炼金属。数十年来凝视灼热的炉火，毁了他的视力，但他的直觉依然敏锐。当你登上高处，打破他的独处时，火眼知道你的来意：一名战士前来求取锻造的兵刃。"}},faq={{q="谁会派战士去寻找索恩格瑞姆·火眼？",a="犹塞克是贫瘠之地东部前沿哨所附近路旁的一名战士训练师，你展示防御训练的成果后，他便会派你前去。",al={"谁提供这个任务","谁开启 索恩格瑞姆·火眼 任务","任务给予者"}},{q="索恩格瑞姆·火眼在哪里？",a="索恩格瑞姆住在荆棘岭顶一处偏僻的营地里，那道高耸的山脊位于贫瘠之地十字路口的正东面。",al={"索恩格瑞姆 位置","索恩格瑞姆 在哪里","寻找 火眼"}},{q="索恩格瑞姆为什么独自住在山中？",a="索恩格瑞姆毕生致力于金属锻造，远离城镇的纷扰。尽管周围的山脊上有危险的野兽和野猪人，他仍独自在荆棘岭顶的铁砧前劳作。",al={"索恩格瑞姆 为何隐居","火眼 隐士"}},{q="索恩格瑞姆·火眼的眼睛怎么了？",a="数十年来，索恩格瑞姆·火眼始终在炽热的煤火前劳作，承受熔炉的高温，视力已几乎完全丧失。",al={"索恩格瑞姆 是否失明","火眼 的眼睛"}},{q="见到索恩格瑞姆·火眼后会发生什么？",a="你向索恩格瑞姆报到后，他明白你需要兵器，便让你收集原材料，以便为你打造一把武器。",al={"后续任务","索恩格瑞姆 之后做什么","锻造钢铁后续"}},{q="任何职业都能接取这个任务吗？",a="不能。这条道路只向寻求专属兵器的部落战士开放。",al={"是否仅限战士","谁能做 索恩格瑞姆·火眼 任务"}}},fp="18,183,23.412.0,24.421.0,46.144.0,36.117.0,47.188.0,43.129.0,44.126.0,30.61.0"}
P.entries["quest:1503"] = {n="锻造好的钢锭",s="索恩格瑞姆·火眼在贫瘠之地东部等待有人找回营地里被盗的钢材。他愿意为带回钢材的战士锻造一件武器。",h="索恩格瑞姆·火眼在贫瘠之地东部等待有人找回营地里被盗的钢材。他愿意为带回钢材的战士锻造一件武器。",kw={"贫瘠之地","火眼","锻造钢材","铁箱","野猪人","钢鬃","钢锭","索恩格瑞姆","战士武器"},ang={["class:Warrior"]="身为战士，你要找回被盗的钢材，证明自己的价值，索恩格瑞姆才会为你锻造武器。",["faction:Horde"]="身为部落的一员，你要面对钢鬃对贫瘠之地各处营地和补给线的袭击。",["profession:Blacksmithing"]="身为铁匠，你能明白在卡利姆多严酷的边疆，精炼钢材对部落为何如此重要。"},sec={{t="视力不济，遭贼算计",b="索恩格瑞姆·火眼在贫瘠之地东部经营着一间铁匠铺，远离奥格瑞玛。多年的锻造生涯让他的视力日渐衰退。附近的钢鬃野猪人利用这一弱点，从他的营地偷走了一只铁箱。一些野猪人在一侧哼叫喧闹，引他转头张望，另一些则从另一侧潜入，搬走了他的锻造好的钢锭。"},{t="贵重的金属，无知的窃贼",b="索恩格瑞姆对这次盗窃十分恼火，但他怀疑钢鬃根本用不了这些钢材。野猪人用石头、獠牙和带刺的树根制作器物，不会使用精炼的金属。那只沉重的箱子仍放在他们营地里的一辆破损货车旁，原封未动，对他们毫无用处。对索恩格瑞姆来说，箱中的钢材是他为年轻的部落战士锻造武器所需的原料。"}},faq={{q="索恩格瑞姆·火眼是谁？",a="索恩格瑞姆·火眼是贫瘠之地东部的一名兽人护甲匠兼武器匠。尽管视力日渐衰退，他仍坚持工作，为年轻的部落战士打造装备。",al={"索恩格瑞姆·火眼","铁匠是谁","索恩格瑞姆"}},{q="野猪人为什么偷走钢材？",a="钢鬃野猪人在夜间声东击西，从索恩格瑞姆的营地偷走了铁箱。他们没有加工箱中锻造钢材的技艺。",al={"为什么偷金属","野猪人为什么偷窃","钢鬃想要什么"}},{q="锻造好的钢锭存放在哪里？",a="锻造好的钢锭锁在被偷走的铁箱里，箱子位于索恩格瑞姆营地西北方的钢鬃营地，靠近一辆破损的货车。",al={"箱子在哪里","被偷走的铁箱位置","钢锭在哪里"}},{q="索恩格瑞姆会提供什么武器作为回报？",a="索恩格瑞姆会让找回钢材的年轻战士挑选一件新锻造的武器作为回报。",al={"奖励武器","能得到什么","锻造钢材奖励"}},{q="钢鬃是如何骗过索恩格瑞姆的？",a="钢鬃利用了索恩格瑞姆视力衰退的弱点。一些袭击者哼叫喧闹，吸引他的注意，另一些则潜入营地，偷走了箱子。",al={"他们如何抢走他的东西","索恩格瑞姆如何遭窃","引开索恩格瑞姆的注意"}},{q="索恩格瑞姆为什么住在贫瘠之地，而不是奥格瑞玛？",a="索恩格瑞姆独自驻守在贫瘠之地东部的一处哨站，为从杜隆塔尔前来的战士打造装备，并给予他们指导。",al={"索恩格瑞姆为什么在这里","为什么在贫瘠之地扎营"}}},fp="12,143,22.341.0,33.327.0,26.156.0,37.144.0,37.133.0,43.104.0,49.167.0,64.117.0"}
P.entries["quest:1504"] = {n="誓缚",s="在奥格瑞玛，誓缚 是部落年轻术士的最终入门仪式。甘鲁尔·血眼指引每位求学者使用维尔加石板上的铭文，在尼尔鲁·火刃的召唤法阵中完成仪式。",h="在奥格瑞玛，誓缚 是部落年轻术士的最终入门仪式。甘鲁尔·血眼指引每位求学者使用维尔加石板上的铭文，在尼尔鲁·火刃的召唤法阵中完成仪式。",kw={"暗影裂口","甘鲁尔·血眼","召唤铭文","尼尔鲁·火刃","奥格瑞玛","维尔加石板","誓缚","虚空行者","术士"},ang={["class:Warlock"]="身为术士，你从摆弄小鬼起步，逐渐掌控能在前线作战的恐怖暗影生物。这场仪式教会你，力量必须靠征服与奴役来获取。",["faction:Horde"]="部落公开摒弃过去的恶魔腐化，却出于现实需要，容忍术士在奥格瑞玛地下施展魔法，并对其严加监视。",["race:Orc"]="身为兽人，你在暗影裂口这样的隐蔽角落修习黑暗法术，远离大酋长萨尔不满的目光，也远离萨满之道的复兴。"},sec={{t="征服虚空",b="召唤虚空行者时，你将迎来第一次真正的意志考验。相比之下，召唤小鬼不过是儿戏。术士不会与这些生物订立契约，也不会与它们交流。你以强力将它们拖过维度之间的界限，束缚它们为你效命。甘鲁尔·血眼指引你使用维尔加石板上的铭文，将虚空行者召入尼尔鲁·火刃的仪式法阵，在那里独自击败它，迫使它屈服。"},{t="永无止境的戒备",b="以肉体与魔法的力量击败虚空行者，只完成了这场斗争的一半。甘鲁尔·血眼警告说，被束缚的虚空行者永远不会真正接受奴役。即使它在战斗中如同坚实的暗影壁垒，守护着主人，也仍在等待你分神的那一刻。只要你对仆从的控制稍有松懈，它就会吞噬束缚它的人的灵魂。"}},faq={{q="召唤的是什么生物？",a="你召唤的是虚空行者，一种由宇宙中的暗影与虚空能量凝成的高大生物。与顽皮的小鬼不同，虚空行者是从扭曲虚空和 虚空 中强行拉出的凶蛮存在。术士主要用它们承受毁灭性的物理攻击。",al={"召唤什么","什么恶魔","虚空行者背景"}},{q="召唤仪式在哪里举行？",a="仪式在奥格瑞玛地下暗影裂口中尼尔鲁·火刃的帐篷内举行。刻画在地面上的召唤法阵汇聚维度能量，用以将虚空行者从虚空中强行拉出。",al={"在哪里召唤","召唤法阵位置","仪式地点"}},{q="维尔加石板有什么用途？",a="维尔加石板记载着古老而独特的铭文，能使虚空行者显形，并将它强行拉过现实的屏障。你研习石板上的刻文，制作绘成召唤法阵所需的召唤铭文。",al={"维尔加石板","召唤铭文"}},{q="术士为什么必须击败虚空行者？",a="术士完全凭借压倒性的力量控制异位面的生物。只有当你以肉体与魔法的力量击败虚空行者，证明自己的支配地位后，它才会交出自己的精华，服从命令。",al={"为什么杀死虚空行者","为什么与它战斗","束缚过程"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是奥格瑞玛暗影裂口中一位资深的部落术士训练师。他负责指导部落年轻修习者研习黑暗法术，教他们奴役更强大的恶魔。",al={"甘鲁尔是谁","甘鲁尔·血眼"}},{q="被束缚的虚空行者能得到完全的信任吗？",a="永远不能。虚空行者可能多年毫不反抗地效命，同时等待主人放松警惕。维持束缚需要时刻戒备，因为这种生物对奴役它的人怀着永不消退的怨恨。",al={"虚空行者会反噬吗","虚空行者忠诚吗","恶魔会反抗吗"}}},fx={["066e41c9"]={q="甘鲁尔·血眼为什么想让你完成这件事？",a="甘鲁尔·血眼是聚集在暗影裂口的有潜力术士们的教官。他通过督促你拓展黑暗魔法的技艺，考验并锤炼你的自律。若要为部落驾驭更强大的邪能，你就必须证明自己掌握了召唤并支配强韧虚空行者的本领。",al={"甘鲁尔·血眼的动机","甘鲁尔为什么要召唤虚空行者","甘鲁尔为什么要我束缚虚空行者"}},["3b87ecbf"]={q="为什么甘鲁尔·血眼让你亲自与虚空行者战斗？",a="召唤出的仆从只能靠驾驭它的术士以强大的意志和力量束缚。甘鲁尔·血眼和城卫军都无法让恶魔的意志屈服于你。你必须凭借自己的魔法与武力战胜它，证明你的心智和灵魂足够强大，能够将它奴役。",al={"为什么要独自对抗虚空行者","甘鲁尔为什么不能对付虚空行者","为什么让我去束缚虚空行者"}}},fp="11,197,23.406.0,17.378.0,40.252.0,44.215.0,37.223.0,43.198.0,24.200.0,45.212.0"}
P.entries["quest:1505"] = {n="老兵犹塞克",s="老兵犹塞克是一项部落任务，指引有潜力的年轻战士去寻找一位经验丰富的战斗教官。犹塞克驻扎在杜隆塔尔与贫瘠之地之间、前沿哨所南面不远处，他教导新兵，真正精湛的武艺既需要力量，也需要严谨的学习。",h="老兵犹塞克是一项部落任务，指引有潜力的年轻战士去寻找一位经验丰富的战斗教官。犹塞克驻扎在杜隆塔尔与贫瘠之地之间、前沿哨所南面不远处，他教导新兵，真正精湛的武艺既需要力量，也需要严谨的学习。",kw={"贫瘠之地","战斗指导","杜隆塔尔","前沿哨所","部落","犹塞克","老兵犹塞克","战士"},ang={["class:Warrior"]="年轻战士被派去向犹塞克学习，明白仅凭蛮力还不够，真正的力量源于潜心钻研战斗之道。",["faction:Horde"]="部落将武艺奉为至高，依靠驻扎在边境哨所、身经百战的老兵指导下一代。"},sec={{t="战士之道",b="在部落的文化中，武力的地位毋庸置疑，受到至高无上的尊崇。然而，仅凭蛮力并不能成为勇士。经验丰富的指挥官深知，最出色的战士也会虚心求教，愿意通过自律与学习磨炼战斗本能。那些完成基础训练、准备更进一步的战士，会被指引去寻找经受过战火考验的老兵。"},{t="边境的老兵",b="为了接受更高深的战斗指导，年轻的战士来到杜隆塔尔与贫瘠之地之间干旱的边境。前沿哨所是一座守望东部边境的兽人要塞，犹塞克就驻扎在它南面不远处。犹塞克历经无数血战，如今致力于教导有潜力的新兵，传授至关重要的战斗技艺，以及凭借战术生存的方法。"}},faq={{q="老兵犹塞克是谁？",a="犹塞克是一位久经沙场的部落老兵，负责指导年轻战士作战。他从无数场战斗中幸存下来，如今在杜隆塔尔与贫瘠之地边境附近的营地中，传授自己来之不易的战斗智慧。",al={"犹塞克是谁","犹塞克的故事","老兵是谁"}},{q="在哪里可以找到犹塞克？",a="犹塞克位于前沿哨所南面，这座兽人驻地坐落在东面的杜隆塔尔与贫瘠之地交界处。",al={"犹塞克在哪里","犹塞克的位置","寻找犹塞克"}},{q="前沿哨所是什么地方？",a="前沿哨所是贫瘠之地东部边境的一处兽人驻地，守卫着从杜隆塔尔进入的通道，也是部落的一处防御据点。",al={"前沿哨所是什么地方","前沿哨所的作用"}},{q="为什么年轻战士会被派去找犹塞克？",a="渴望精进的战士会去寻找犹塞克，接受战斗指导。在部落，力量的地位固然毋庸置疑，但真正出色的战士还必须潜心学习，掌握战斗技巧。",al={"为什么要拜访犹塞克","犹塞克教什么","战士指导"}},{q="抵达时，犹塞克会说些什么？",a="年轻战士来到犹塞克的驻地时，他会热情地迎接他们，准备开始考察他们的决心，并传授战争之道。",al={"与犹塞克交谈会发生什么","向犹塞克交任务"}},{q="部落如何看待自己的战士？",a="部落尊崇战士无可置疑的力量，以及他们对武艺的执着，但其文化传统也强调，真正精通武艺需要自律，并向经验丰富的老兵学习。",al={"谁尊崇战士","部落的战士文化"}}},fp="13,180,23.273.0,25.304.0,21.158.0,25.105.0,23.136.0,37.154.0,36.113.0,37.161.0"}
P.entries["quest:1506"] = {n="甘鲁尔的召唤",s="奥菲克将甘鲁尔的召唤带给剃刀岭年轻的部落术士。甘鲁尔·血眼召他们前往暗影裂口，继续深造。在那里，他们将迈出召唤虚空行者的第一步。",h="奥菲克将甘鲁尔的召唤带给剃刀岭年轻的部落术士。甘鲁尔·血眼召他们前往暗影裂口，继续深造。在那里，他们将迈出召唤虚空行者的第一步。",kw={"血眼","暗影裂口","甘鲁尔","奥菲克","奥格瑞玛","召唤","虚空行者","术士任务"},ang={["class:Warlock"]="身为术士，这次召唤标志着你将迈出基础小鬼召唤术的范畴。它将开启一条新的道路，让你能够驱使虚空行者，为你提供坚实的保护。",["faction:Horde"]="身为部落的一员，你知道术士在萨尔的新部落中处境微妙。他们的力量因实用而得到容忍，而他们仍隐居在奥格瑞玛地下。"},sec={{t="来自暗影的召唤",b="在杜隆塔尔，初出茅庐的术士很快就会受到关注。当一名术士展现出足够的本领，能够驾驭最初的小鬼时，消息就会传到奥格瑞玛地下深处的洞窟。奥菲克驻守杜隆塔尔，为资深的黑暗施法者传递消息。他找到这些术士，命他们立即放下手头的事务，前往暗影裂口报到。"},{t="资深术士",b="甘鲁尔·血眼负责指导部落年轻兽人术士的训练。他在奥格瑞玛地下隐秘的洞窟中磨炼他们致命的邪能力量，同时让这些危险的技艺避开大酋长不赞同的目光。获召加入他的圈子，意味着简单的火焰法术和小鬼已不再足够。这名学徒已经准备好束缚一个来自扭曲虚空的生物。"}},faq={{q="奥菲克是谁？",a="奥菲克是驻扎在杜隆塔尔的术士们的同伴。他留意崭露头角的术士，并传达甘鲁尔·血眼等资深导师的命令。",al={"奥菲克","谁提供这个任务","任务给予者"}},{q="甘鲁尔·血眼在哪里？",a="甘鲁尔·血眼位于暗影裂口，那是奥格瑞玛岩石高地下方一片幽暗的洞窟。",al={"甘鲁尔在哪里","甘鲁尔的位置","寻找甘鲁尔·血眼"}},{q="甘鲁尔·血眼为什么要见我？",a="甘鲁尔认为你已经准备好进一步研习术士之道，开始进行召唤并束缚虚空行者的危险仪式。",al={"为何召唤","甘鲁尔有什么要求","任务缘由"}},{q="向甘鲁尔报到后会发生什么？",a="向甘鲁尔报到后，便会开始虚空中的生物。你将受命寻找所需的材料与知识，将一个虚空实体引入艾泽拉斯。",al={"下一个任务","甘鲁尔的召唤的后续任务"}},{q="术士为什么待在暗影裂口？",a="术士修习难以控制的邪能魔法，萨尔和信奉传统萨满之道的部落对此深怀疑虑。暗影裂口让他们能够避开公众的视线举行仪式。",al={"为何选择暗影裂口","术士为何藏身","奥格瑞玛术士洞窟"}},{q="任何职业都能接到这个任务吗？",a="不能。只有修行达到第十阶段的部落术士才能收到召唤。",al={"是否仅限术士","谁能接到这个任务"}}},fx={f5421555={q="奥菲克为什么派你去找甘鲁尔？",a="奥菲克只是甘鲁尔·血眼的跑腿和信使。大断崖的资深术士不会在奥格瑞玛四处寻找学徒，而是派手下去把需要的人带来。奥菲克知道不能耽搁甘鲁尔的召唤，因此提醒你，让术士大师久等通常不会有好下场。",al={"奥菲克为什么派我去","奥菲克的动机","奥菲克为什么传达召唤"}}},fp="17,210,24.340.0,18.373.0,13.160.0,34.100.0,41.122.0,40.142.0,48.179.0,30.100.0"}
P.entries["quest:1507"] = {n="噬魂者",s="甘鲁尔·血眼派一名有志向的部落术士踏上召唤并驾驭魅魔的道路。在奥格瑞玛的暗影裂口，术士向卡祖尔请教如何引诱并束缚这个恶魔。",h="甘鲁尔·血眼派一名有志向的部落术士踏上召唤并驾驭魅魔的道路。在奥格瑞玛的暗影裂口，术士向卡祖尔请教如何引诱并束缚这个恶魔。",kw={"束缚","卡祖尔","暗影裂口","甘鲁尔·血眼","奥格瑞玛","魅魔","召唤","术士"},ang={["class:Warlock"]="身为术士，你向驾驭擅长精神支配与诱惑的恶魔又迈进了一步。这项仪式既需要强大的邪能力量，也需要坚定的心志。",["faction:Horde"]="身为部落的一员，你看到术士在暗影裂口潮湿而隐蔽的岩隙中举行危险的仪式。萨尔麾下的萨满祭司和战士公开修习，而术士则在隐蔽处行事。"},sec={{t="踏入魅惑之影",b="掌握了小鬼和虚空行者等低阶恶魔的部落术士，接下来便可尝试召唤魅魔。甘鲁尔·血眼在奥格瑞玛地下监管黑暗法术，并判断术士何时有能力从扭曲虚空召来魅魔。魅魔能让意志薄弱者自相残杀，因此束缚魅魔既需要力量，也需要巧思。"},{t="卡祖尔的学识",b="魅魔以凡人的欲望为猎物，因此单凭咒语无法将其召来。召唤者必须用一件饱含纯真爱意与忠贞之情的物品引诱它。甘鲁尔不愿或无法亲自提供这样的信物，于是派术士穿过暗影裂口去找卡祖尔。这位年迈的术士通晓仪式下一阶段所需的奥术与恶魔仪轨。"}},faq={{q="这个任务的目的是什么？",a="这个任务让一名有志向的部落术士开始学习如何召唤并驾驭魅魔。它会引导你结识暗影裂口的导师，了解这种恶魔的本性，以及如何将其从扭曲虚空引来。",al={"为什么做噬魂者","魅魔任务起点","这个任务解锁什么"}},{q="在哪里能找到卡祖尔？",a="卡祖尔位于暗影裂口，那是奥格瑞玛地下的一处洞穴，潜行者和术士训练师在那里研习技艺，避开大酋长的审视。",al={"卡祖尔位置","卡祖尔在哪里","奥格瑞玛寻找卡祖尔"}},{q="为什么术士召唤魅魔需要一件承载爱意的物品？",a="魅魔以凡人的情感、痴情和薄弱意志为食。为了从扭曲虚空引来魅魔，召唤者会献上一件饱含真挚忠贞与爱意的信物作为诱饵，再将恶魔压制并束缚。",al={"魅魔诱饵爱意","魅魔为什么需要爱情信物","魅魔召唤背景故事"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是奥格瑞玛暗影裂口的一位部落资深术士训练师。他引导成长中的术士束缚越来越强大的恶魔仆从。",al={"谁提供噬魂者","甘鲁尔背景故事","甘鲁尔·血眼"}},{q="开始这个任务需要多少级？",a="术士必须达到二十级，甘鲁尔才会认为其魔法造诣与心智足够坚韧。这个仪式意味着要与魅魔讨价还价，并在这场交锋中活下来。",al={"魅魔需要多少级","噬魂者等级","魅魔任务链等级要求"}},{q="与卡祖尔交谈后会发生什么？",a="与卡祖尔交谈后，便会接到盲眼卡祖尔。接下来，你要在奥格瑞玛寻找赞卡沙，她的伴侣多格兰前往十字路口执行任务后一直未归。寻找合适爱情信物的旅程便从她这里开始。",al={"噬魂者后续任务","卡祖尔之后是什么","魅魔任务流程"}}},fp="17,155,29.327.0,17.359.0,34.226.0,22.136.0,63.207.0,24.181.0,43.183.0,39.200.1"}
P.entries["quest:1508"] = {n="盲眼卡祖尔",s="在暗影裂口，一名学徒向盲眼卡祖尔寻求魅魔召唤仪式的帮助。这位失明的术士指引他去寻找一件饱含凡人情感的物品。",h="在暗影裂口，一名学徒向盲眼卡祖尔寻求魅魔召唤仪式的帮助。这位失明的术士指引他去寻找一件饱含凡人情感的物品。",kw={"盲眼卡祖尔","卡祖尔","暗影裂口","多格兰","奥格瑞玛","魅魔","术士","赞卡沙"},ang={["class:Warlock"]="身为术士，你会了解到，召唤恶魔既依赖邪能魔法，也依赖情感共鸣。饱含凡人情感的媒介能够引来魅魔。",["faction:Horde"]="身为部落的一员，你会看到暗影裂口的黑暗法术在都城地下运作，触及上方台地上普通人的生活。"},sec={{t="诱惑之道",b="魅魔会回应凡人的渴望、悲伤与欲望。想要将魅魔引过帷幕，有志于召唤的学徒光有意志还不够；这种恶魔以吞噬灵魂闻名。盲眼卡祖尔明白学徒所求，也知道在哪里能找到合适的诱饵。"},{t="高地上的双眼",b="盲眼卡祖尔虽然双目失明，却能感知奥格瑞玛赤红城墙内的众生与悲苦。他让学徒去找赞卡沙，一位住在风骑士栖所附近高地上的兽人女子。她正焦急地等待伴侣多格兰归来，而她的绝望足以引起恶魔的注意。"}},faq={{q="卡祖尔是谁？",a="卡祖尔是一位失明的术士，默默帮助着暗影裂口的术士们。他能辨识召唤恶魔所需的材料与媒介。",al={"盲眼卡祖尔","卡祖尔是谁"}},{q="卡祖尔为什么让你去找赞卡沙？",a="召唤魅魔的仪式需要一件凝聚着凡人强烈渴望或爱意的物品。赞卡沙正痛苦地等待失踪的伴侣多格兰，而她与他的情感羁绊，正是学徒所寻找的情感诱饵。",al={"为什么找赞卡沙","赞卡沙有什么"}},{q="在奥格瑞玛哪里能找到赞卡沙？",a="赞卡沙住在奥格瑞玛的高地上，位于风骑士栖所西侧。从飞行塔过桥，在右手边附近的住处寻找。",al={"赞卡沙位置","赞卡沙在哪里"}},{q="与赞卡沙交谈后会发生什么？",a="赞卡沙因伴侣多格兰失踪而忧心忡忡。与她交谈后，你会前往贫瘠之地打听他的下落，并开始设法取回一件蕴含强烈爱意的信物。",al={"接下来做什么","找过卡祖尔之后的下一步"}},{q="这个任务要你为召唤哪种恶魔做准备？",a="你正准备召唤并奴役一只魅魔，这种恶魔擅长诱惑和精神折磨。",al={"哪种宠物","恶魔奖励"}},{q="术士为什么必须利用个人的悲剧来完成仪式？",a="魅魔会被凡人强烈的情感吸引，尤其是激情、忠贞与心碎。术士在召唤仪式中，用承载悲伤或欲望的信物作为灵魂诱饵。",al={"术士的道德","为什么利用多格兰"}}},fp="11,140,22.241.0,18.282.0,13.143.0,35.199.0,40.163.0,39.185.0,57.102.0,63.181.0"}
P.entries["quest:1509"] = {n="多格兰的消息",s="名叫多格兰的步兵失踪了，赞卡沙仍在奥格瑞玛等他。他的伴侣已有数日未收到消息，于是派你前往十字路口，向他的上级加兹罗格打听。对术士而言，这次寻人也与束缚魅魔的仪式有关。",h="名叫多格兰的步兵失踪了，赞卡沙仍在奥格瑞玛等他。他的伴侣已有数日未收到消息，于是派你前往十字路口，向他的上级加兹罗格打听。对术士而言，这次寻人也与束缚魅魔的仪式有关。",kw={"贫瘠之地","卡祖尔","十字路口","多格兰","加兹罗格","多格兰的消息","野猪人","魅魔","赞卡沙"},ang={["class:Warlock"]="身为术士，为了获得魅魔，你从研读奥格瑞玛的黑暗典籍，走向利用凡人的悲剧。",["faction:Horde"]="身为部落的一员，你看到部落步兵在保卫卡利姆多的十字路口、抵御敌对威胁时所面临的危险。",["race:Orc"]="身为兽人，你从赞卡沙的悲痛中，看到了部落在杜隆塔尔和贫瘠之地扩张与防御时，个人所付出的代价。"},sec={{t="伴侣的绝望",b="赞卡沙在奥格瑞玛的高地上等待，为伴侣多格兰的安危忧心。他因光荣晋升而被派往十字路口，却迟迟未归，她也已有数日未收到消息。她请你向他的指挥官加兹罗格打听消息。她并不知道，这次寻人的背后还有黑暗法术在起作用。"},{t="贫瘠之地的噩耗",b="加兹罗格在十字路口告诉你多格兰的遭遇，这里是部落在贫瘠之地的中心哨站。野猪人遍布平原，多格兰已落入它们手中。他还活着，但被俘的残酷实情让加兹罗格迟疑，不忍将消息传回赞卡沙那里。"},{t="召唤的媒介",b="术士寻找多格兰，也是为了召唤并驾驭魅魔。束缚仪式需要浸染真挚情感的遗物。多格兰的苦难，以及他与赞卡沙之间的羁绊，提供了仪式所需的情感媒介。"}},faq={{q="多格兰是谁？",a="多格兰是一名驻守贫瘠之地的兽人步兵，最近因晋升而调往十字路口。他是赞卡沙的伴侣，而她住在奥格瑞玛。",al={"多格兰背景故事","多格兰是谁","步兵多格兰"}},{q="术士为何关心一名失踪的兽人守卫？",a="暗影裂口的术士导师指引你打听多格兰的消息。束缚魅魔的仪式需要浸染凡人深厚情感的遗物，包括爱、忠贞与苦难。",al={"为何是术士任务","术士为何这样做","与魅魔的关联"}},{q="加兹罗格在哪里？",a="加兹罗格位于贫瘠之地的十字路口，在那里协助部署部落的防御，抵御当地的威胁。",al={"加兹罗格在哪","加兹罗格位置","十字路口加兹罗格"}},{q="多格兰出了什么事？",a="多格兰迟迟未回到赞卡沙身边，她也已有数日未收到他的消息。她请你前往十字路口，向加兹罗格打听。",al={"多格兰死了吗","多格兰在哪","多格兰的命运"}},{q="谁会给予这个任务？",a="术士训练师卡祖尔指引你找到赞卡沙后，她会在奥格瑞玛的高地上给予你这个任务。",al={"任务给予者","多格兰的消息在哪接"}},{q="任务链接下来是什么？",a="继续在贫瘠之地打听，了解多格兰的命运，并将消息传下去。",al={"接下来是什么","后续任务","魅魔任务链后续"}}},fp="14,131,16.238.0,27.241.1,26.243.1,14.137.0,50.186.0,24.103.0,24.137.1,21.103.0,29.90.1"}
P.entries["quest:151"] = {n="老马布兰契",s="在西部荒野的路边，可怜的老布兰契又累又饿，陪着受困的法布隆一家等待着。他们逃难时马车坏了，弗娜请你到附近废弃的农场寻找燕麦，喂饱这匹母马。",h="在西部荒野的路边，可怜的老布兰契又累又饿，陪着受困的法布隆一家等待着。他们逃难时马车坏了，弗娜请你到附近废弃的农场寻找燕麦，喂饱这匹母马。",kw={"收割傀儡","马","燕麦","老布兰契","可怜的老布兰契","弗娜·法布隆","马车","西部荒野"},ang={["class:Hunter"]="身为猎人，你知道照料一头筋疲力尽的役畜，是对劳作之人与忠实替他们负重的牲畜之间情谊的尊重。",["faction:Alliance"]="受困的法布隆一家让人看到，当首都因政局停滞而瘫痪时，乡间的人类子民正遭受冷落。"},sec={{t="受困的一家",b="弗娜和农夫法布隆被困在西部荒野的大路旁。匪徒和失控的机械收割傀儡迫使像他们这样的家庭背井离乡。法布隆一家试图带着家当逃到安全的地方，但马车半路损坏，让他们困在了旷野中。"},{t="慰藉忠诚的母马",b="多年来，老布兰契一直为法布隆一家耕地拉车。如今，行程受阻，这匹温顺的母马已经精疲力竭，饥肠辘辘。弗娜请你到附近沦陷的农庄寻找成袋的燕麦。那里有凶暴的收割机和四处搜掠的豺狼人，但这些粮食能让这匹忠诚的母马好好吃上一顿。"}},faq={{q="老布兰契是谁？",a="老布兰契是法布隆一家心爱的老役马。多年来，她在西部荒野为他们拉犁拖车。如今，他们的马车车轴断了，她也精疲力竭，被困在路旁。",al={"布兰契是谁","老布兰契是什么","布兰契的故事"}},{q="法布隆一家的马车为什么坏了？",a="法布隆一家试图带上全部家当逃离农场，但马车不堪重负，半路损坏。他们被困在大路旁，随时可能遭到匪徒和游荡野兽的袭击。",al={"他们为何受困","法布隆的马车","路边损坏的马车"}},{q="燕麦从哪里来？",a="在西部荒野沦陷的农场里，田野和附属建筑中散落着一袋袋燕麦。农户逃离失控的收割机械和匪徒时，把这些粮食留了下来。",al={"燕麦在哪里","寻找燕麦","成袋的燕麦"}},{q="田里的粮食附近有什么威胁？",a="在道路西南方，失控的机械收割看守和成群的河爪豺狼人正在废弃的谷仓中搜掠。",al={"农场有什么会攻击","农场的危险","收割傀儡 燕麦"}},{q="这家人为什么还没把老布兰契带到安全的地方？",a="老布兰契已经筋疲力尽，饥饿难耐，不吃东西就无法拉车，也走不了多远。法布隆一家不肯丢下这匹忠诚的母马和他们的家当。",al={"为何守着马车","马还能走吗","为何不去哨兵岭"}},{q="暴风城会援助像法布隆一家这样的农户吗？",a="暴风城的王室几乎没有为西部荒野的农户提供任何保护或援助。乡间百姓大多只能自谋生路，或依靠苦苦支撑的人民军。",al={"暴风城援助西部荒野","卫兵在哪里","联盟援助西部荒野"}}},fx={b3f21e2d={q="弗娜·法布隆为什么想要办成这件事？",a="法布隆夫妇的货车在路上意外损坏，让他们被困在离目的地很远的地方。他们忠诚的老马老布兰契一路跋涉，又承受了繁重的劳役，早已精疲力竭。弗娜出发前喂过她，但布兰契现在已经快撑不住了。没有新鲜的燕麦补充营养，这匹疲惫的马就无法恢复继续赶路所需的力气。",al={"为何帮助布兰契","弗娜·法布隆的动机","布兰契为何需要燕麦"}},c126e1f4={q="一捧燕麦有什么用？",a="这些燕麦是维持老布兰契体力、让她恢复元气的重要饲料。法布隆夫妇这匹忠实的挽马拉着满载的货车，早已筋疲力尽，货车突然损坏后，她也快要断粮了。在这家人设法修理断裂的车轴时，喂她几捧从偏远农庄搜集来的谷物，能让她恢复精神和体力。",al={"一捧燕麦有什么用","一捧燕麦的用途","燕麦的用途"}},["3b562f8e"]={q="弗娜·法布隆为什么请你帮忙，而不自己去收集燕麦？",a="法布隆夫妇是无助的旅人，被困在路边损坏的货车旁，根本无力应付西部荒野田间的危险。那些还留着粮袋的废弃农田里，到处都是充满敌意的机械收割机和四处游荡的徘徊者。弗娜和丈夫必须留下照看受损的货车与虚弱的马，只能把危险的觅粮之事交给你这样经验丰富的冒险者。",al={"弗娜为何无法收集燕麦","弗娜为何请求帮忙","法布隆夫妇为何需要帮助"}}},fp="16,200,20.286.0,27.325.0,19.206.0,38.183.0,28.172.0,43.113.0,50.152.0,54.180.0"}
P.entries["quest:1510"] = {n="多格兰的消息",s="在石爪山脉的山麓，多格兰的性命全系于一剂来自玛拉卡金的伤药。最先奉命取药的信使一去不返，你深入山麓，寻找暗矛巨魔肯兹格拉。",h="在石爪山脉的山麓，多格兰的性命全系于一剂来自玛拉卡金的伤药。最先奉命取药的信使一去不返，你深入山麓，寻找暗矛巨魔肯兹格拉。",kw={"陶拉祖营地","多格兰","加兹罗格","肯兹格拉","玛拉卡金","野猪人","石爪山脉"},ang={["class:Warlock"]="身为术士，你面对的似乎是一项救助伤兵的任务。卡祖尔和奥格瑞玛的术士们设下了一场试炼，引导你体会束缚魅魔所需的情感。",["faction:Horde"]="身为部落的一员，你看到了陶拉祖营地与玛拉卡金那处孤立营地之间的补给线有多脆弱，野猪人和地精都在威胁沿途的安全。"},sec={{t="跨越边境的求援",b="多格兰是驻守贫瘠之地南部陶拉祖营地的一名部落步兵，在与盘踞当地的野猪人作战时身受重伤。战友们把他带了回来，但他的伤口已经溃烂。他们担心未经治疗就移动他会有危险。陶拉祖营地向北方的十字路口传信，求取玛拉卡金丛林巨魔配制的传统伤药。"},{t="玛拉卡金的血案",b="在玛拉卡金，你得知最先奉命取药的信使还没来得及把药带回，就被地精杀害了。肯兹格拉仍保管着多格兰需要的伤药。要拿到药，就得面对石爪山脉各处山道上的危险。"}},faq={{q="多格兰是谁，为什么会受伤？",a="多格兰是陶拉祖营地的一名部落步兵。他在贫瘠之地南部与野猪人作战时身受重伤，伤口不断溃烂，未经治疗就移动他似乎太过危险。",al={"多格兰是谁","多格兰为何受伤","多格兰的故事"}},{q="玛拉卡金位于何处？",a="玛拉卡金是暗矛巨魔的一处前哨，坐落在石爪山脉岩石嶙峋的山脚下，就在贫瘠之地西北边界之外。",al={"玛拉卡金位置","玛拉卡金在哪","寻找肯兹格拉"}},{q="最先奉命取药的信使遭遇了什么？",a="第一名从十字路口出发的信使还没来得及带回肯兹格拉的伤药，就在玛拉卡金附近被地精杀害。肯兹格拉只说是地精杀了他。",al={"第一名信使","信使遭遇了什么","死去的信使"}},{q="术士训练师为什么关心多格兰的命运？",a="术士学徒接到一项为盲眼的卡祖尔和加兹罗格跑腿的差事，名义上是帮助多格兰。这场磨炼将引导他们找到一件与爱情和心碎有关的神器，召唤并束缚魅魔需要用到它。",al={"术士任务关联","魅魔与多格兰","术士为何做这件事"}},{q="肯兹格拉是谁？",a="肯兹格拉是石爪山脉玛拉卡金的一名暗矛巨魔炼金师兼草药师。他懂得如何利用荒野中的草药配制强效药剂。",al={"肯兹格拉是谁","肯兹格拉与石爪山脉","肯兹格拉"}},{q="为什么不能直接把多格兰送到城里？",a="与野猪人交战后，多格兰的伤口严重溃烂。他的战友们担心，前去寻求高明医者救治的途中，贫瘠之地崎岖的道路会让他撑不到目的地。",al={"为何不转移多格兰","多格兰的伤势","陶拉祖营地为何留下他"}}},fp="14,184,26.356.0,23.219.1,33.183.0,28.132.0,58.165.0,49.202.1,17.132.0,49.169.0"}
P.entries["quest:1511"] = {n="肯兹格拉的伤药",s="在部落术士召唤魅魔的系列任务中，肯兹格拉的伤药要被送往陶拉祖营地。这位巨魔药剂师在石爪山脉配制了伤药，用来救治失踪的特工多格兰。",h="在部落术士召唤魅魔的系列任务中，肯兹格拉的伤药要被送往陶拉祖营地。这位巨魔药剂师在石爪山脉配制了伤药，用来救治失踪的特工多格兰。",kw={"贫瘠之地","多格兰","伤药","肯兹格拉","劳格玛","石爪山","魅魔","陶拉祖"},ang={["class:Warlock"]="身为术士，在这段旅途中，你必须展现耐心与应变的智慧。在你能够驾驭那充满原始欲望与诱惑的生物之前，你必须先治好那个受伤的凡人，他身上带着用于束缚它的信物。",["faction:Horde"]="身为部落的一员，你见证了石爪山和贫瘠之地的偏远哨站如何依靠旅人，将重要消息和救命的药物送往卡利姆多中部各地。"},sec={{t="救命的药剂",b="第一位信使出了状况后，肯兹格拉又配制了一剂伤药。这位身在石爪山脉的巨魔药剂师担心，那个为失踪斥候多格兰寻找药物的使者一直没有回来。他的伤药药性不稳定，药效却很强。半剂就能让身受致命伤的士兵恢复行动的力气，又不会让伤口重新流血。剩下的半剂必须等到第二天服用，才能让伤者完全康复。"},{t="陶拉祖营地会合",b="你将肯兹格拉的伤药从山中带到陶拉祖营地，交给步兵劳格玛。劳格玛掌握着多格兰下落的关键情报，但外出采集补给的行动让驻军缺少可用的步兵。多格兰被困在敌境，血流不止；伤药送抵陶拉祖，营救行动便即将展开。"}},faq={{q="肯兹格拉的伤药有什么用途？",a="肯兹格拉的伤药是一种强效药物，用来救治受伤的兽人特工多格兰。伤药分两次服用，第一剂让受伤的战士恢复行动的力气，又不会让致命的伤口重新裂开，第二剂则让伤势完全痊愈。",al={"伤药是什么","肯兹格拉的伤药用途","为何配制伤药"}},{q="肯兹格拉是谁？",a="肯兹格拉是石爪山脉的一位巨魔药剂师。他为这一带的部落特工配制专用的炼金药剂。",al={"肯兹格拉的故事","肯兹格拉是谁"}},{q="步兵劳格玛为什么在陶拉祖营地等候？",a="步兵劳格玛驻守在贫瘠之地南部的陶拉祖营地。他追踪当地斥候的动向，掌握着多格兰失踪地点的最后情报，却没有足够的步兵独自展开营救。",al={"步兵劳格玛是谁","劳格玛 陶拉祖","步兵劳格玛的职责"}},{q="这个任务与召唤魅魔有什么关系？",a="奥格瑞玛的部落术士需要多格兰的坠饰来召唤并束缚魅魔，这件物品蕴含着激情与忠贞。他们必须找到多格兰，用肯兹格拉的伤药救他一命，才能拿到坠饰。",al={"魅魔任务为何需要伤药","魅魔系列任务 多格兰"}},{q="第一位信使为什么没有送来伤药？",a="最初被派往石爪山的信使没能完成任务。肯兹格拉为下一位寻找多格兰的旅人配制了备用的伤药。",al={"第一位信使遭遇了什么","上一位信使"}},{q="离开陶拉祖营地后，线索指向哪里？",a="收到伤药后，步兵劳格玛会指引你去找贫瘠之地南部囚禁多格兰的敌人，那里关押着这位奄奄一息的斥候。",al={"多格兰在哪里","见过劳格玛后的下一步"}}},fp="19,162,18.374.0,26.309.1,40.211.0,17.136.0,44.214.0,52.208.0,47.144.0,43.137.1"}
P.entries["quest:1512"] = {n="爱的礼物",s="在奥格瑞玛，甘鲁尔·血眼正等待一条用于魅魔仪式的坠饰。多格兰在贫瘠之地被找到并救醒后，交出了一件珍爱的信物。",h="在奥格瑞玛，甘鲁尔·血眼正等待一条用于魅魔仪式的坠饰。多格兰在贫瘠之地被找到并救醒后，交出了一件珍爱的信物。",kw={"沾满泥土的坠饰","甘鲁尔·血眼","步兵多格兰","爱的礼物","奥格瑞玛","魅魔","贫瘠之地","赞卡沙"},ang={["class:Warlock"]="身为术士，你会明白，仅凭奥术之力无法束缚恶魔。利用魅魔对爱与悲伤等凡人情感的渴望，便能反过来将它困住。",["faction:Horde"]="身为部落的一员，你见证了步兵多格兰宁愿战死，也不愿成为亲人的负担。"},sec={{t="步兵的牺牲",b="步兵多格兰被贫瘠之地的刺背野猪人囚禁，饱受折磨。肯兹格拉的伤药让他恢复了意识，但他的身体已无法康复。他选择战死，也不愿拖着无法战斗的身躯回到伴侣赞卡沙身边。多格兰交出了一枚沾满泥土的坠饰，那是一份因爱而生的礼物，并请求永远不要让赞卡沙知道他交出了什么。"},{t="恶魔的诱饵",b="术士需要一件蕴含强烈而纯粹情感的护符，才能召唤并控制魅魔。这些恶魔以凡人的欲望为食，将真挚的爱意扭曲成痛苦。多格兰的坠饰承载着他的挚爱与两人的离别。将它带给奥格瑞玛幽暗裂隙中的甘鲁尔·血眼，在那里清洗并打磨。它所蕴含的鲜明情感力量，能够引诱那吞噬灵魂的恶魔穿越扭曲虚空。"}},faq={{q="术士为什么需要多格兰的坠饰？",a="魅魔会被凡人深切的情感吸引，并将其扭曲、吞噬。多格兰的坠饰蕴含着无私的爱与牺牲，因此成了引诱魅魔的强大诱饵。",al={"为什么需要坠饰","魅魔诱饵","为什么是沾满泥土的坠饰"}},{q="步兵多格兰是谁？",a="步兵多格兰是一名部落战士，在贫瘠之地南部被刺背野猪人俘虏并折磨。一剂炼金药水让他苏醒，但他的伤势使他无法再以一名骄傲的战士的身份活下去。",al={"多格兰是谁","步兵多格兰的故事"}},{q="赞卡沙是谁？",a="赞卡沙是多格兰年轻的伴侣，一直焦急地等待着他的消息。他舍弃了她的信物，选择寻求战士的死亡，不愿让照顾自己成为她的负担。",al={"赞卡沙的故事","多格兰的伴侣"}},{q="多格兰为什么请求你向赞卡沙保守这个秘密？",a="多格兰不愿让年轻的伴侣被一个垂死的废人拖累。他明知坠饰不会再回到她手中，仍交出了她的坠饰，并请求不要让她因得知他的最终命运而心怀愧疚。",al={"为什么不告诉赞卡沙","多格兰的秘密"}},{q="谁清洗了坠饰，为什么？",a="奥格瑞玛的术士训练师甘鲁尔·血眼接过坠饰，洗去了上面的污垢。这样，它明亮的外观和蕴含的情感力量就能吸引被召唤的恶魔。",al={"甘鲁尔·血眼的作用","为什么清洗坠饰"}},{q="完成这个任务后，紧接着会发生什么？",a="甘鲁尔·血眼派你将净化后的坠饰带入奥格瑞玛地下的召唤法阵。在那里，你施行束缚仪式，独自面对魅魔。",al={"接下来做什么","爱的礼物的后续任务"}}},fp="11,154,19.340.1,16.419.0,41.164.0,20.201.0,15.165.1,57.191.1,31.172.0,53.162.1"}
P.entries["quest:1513"] = {n="誓缚",s="在奥格瑞玛的尼尔鲁·火刃法阵中，一名术士面临着束缚魅魔的试炼。多格兰的坠饰将恶魔从扭曲虚空引来，术士必须以法术和武力击溃它的意志。",h="在奥格瑞玛的尼尔鲁·火刃法阵中，一名术士面临着束缚魅魔的试炼。多格兰的坠饰将恶魔从扭曲虚空引来，术士必须以法术和武力击溃它的意志。",kw={"束缚","暗影裂口","多格兰","甘鲁尔","尼尔鲁","奥格瑞玛","坠饰","魅魔","术士","赞卡沙"},ang={["class:Warlock"]="身为术士，你证明了自己的意志足以驾驭虚空中狡诈、肆意作乱的恶魔，并抵御它们危险的诱惑。",["faction:Horde"]="身为部落的一员，你看到部落如何暗中容忍研习恶魔之术的人藏身于暗影裂口，远离城中崇尚荣誉的民众。",["race:Orc"]="身为兽人，与恶魔打交道时，你背负着族人曾遭腐化的沉痛往事。甘鲁尔对自律与掌控的要求，也承载着这段历史。"},sec={{t="恶魔的锚",b="多格兰的坠饰将回忆与召唤相连。那个身受残害的兽人交出了坠饰，但它曾是他对赞卡沙爱意的寄托，陪他熬过了囚禁与折磨。这份深情赋予坠饰跨越诸界的力量，使它能够连通扭曲虚空，引起魅魔的注意。"},{t="暗影中的法阵",b="在奥格瑞玛下方的裂隙深处，尼尔鲁·火刃的帐篷中设有一座法阵，供危险的仪式使用。在甘鲁尔·血眼的指引下，你激活法阵的符文，与召来的魅魔交战。召来恶魔只是开始；你必须独自将它击败，让它的心智屈从于你的意志。"},{t="诡计与意志",b="甘鲁尔·血眼警告说，魅魔即使沦为仆从，也可能十分危险。它们的存在令人迷醉，诱惑感官，同时吸取疏忽大意的主人的生命力与精神。他告诫你，要记住多格兰与赞卡沙的悲伤，以免骄傲自负让恶魔有机可乘。唯有坚定不屈的意志，才能抵御它的诱惑。"}},faq={{q="这个仪式中会发生什么？",a="你将多格兰的坠饰带到暗影裂口中尼尔鲁·火刃帐篷内的法阵。坠饰承载的深情从扭曲虚空引来一只魅魔，而你要与这恶魔战斗，直到它屈从于你的意志。",al={"仪式如何进行","誓缚 中要做什么","魅魔仪式"}},{q="召唤在何处进行？",a="召唤在奥格瑞玛下方暗影裂口中尼尔鲁·火刃的帐篷内进行。地面上刻着一座仪式法阵。",al={"法阵在哪里","召唤法阵位置","在哪里召唤魅魔"}},{q="多格兰是谁，为什么需要他的坠饰？",a="多格兰曾是一名部落步兵，在贫瘠之地被野猪人俘虏并残害。他的坠饰寄托着他对挚爱赞卡沙的思念，能够引来并锚定一只魅魔。",al={"多格兰 是谁","为什么需要多格兰的坠饰","多格兰 的故事"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是奥格瑞玛下方暗影裂口中的一名资深术士训练师。他教导初出茅庐的术士，指引他们完成降服恶魔的仪式。",al={"谁给予任务","甘鲁尔 是谁","甘鲁尔·血眼的职责"}},{q="完成这场试炼后，术士会获得什么力量？",a="降服魅魔便完成了术士的训练，使其获得随时召唤魅魔为己效力所需的知识，并掌握相关符文。",al={"术士获得什么奖励","为什么召唤魅魔","魅魔宠物技能"}},{q="为什么召唤魅魔被认为格外危险？",a="魅魔会蛊惑凡人，利用他们的欲望。过于自信的术士可能会被慢慢吸走灵魂，直到恶魔的诡计压倒他们的掌控。",al={"魅魔的危险","魅魔为何危险","魅魔背景故事"}}},fp="11,202,16.310.1,25.306.0,19.341.1,32.206.0,36.137.0,45.150.1,24.165.0,58.135.0,60.167.0"}
P.entries["quest:1515"] = {n="多格兰之囚",s="在陶拉祖营地，术士要面对部落训练中的一项重要试炼：营救一名被俘的兽人战士。你必须带着肯兹格拉的伤药，在野猪人的营地中找到遍体鳞伤的步兵多格兰，让他恢复逃脱所需的力气。",h="在陶拉祖营地，术士要面对部落训练中的一项重要试炼：营救一名被俘的兽人战士。你必须带着肯兹格拉的伤药，在野猪人的营地中找到遍体鳞伤的步兵多格兰，让他恢复逃脱所需的力气。",kw={"贫瘠之地","多格兰","伤药","肯兹格拉","劳格玛","野猪人","魅魔","陶拉祖","术士"},ang={["class:Warlock"]="身为术士，你将迈出重要的一步，去理解凡人的激情与牺牲，而这些正是召唤魅魔所必需的。",["faction:Horde"]="身为部落的一员，你知道野猪人威胁着贫瘠之地中部各处的巡逻队和哨站。",["race:Orc"]="身为兽人，你能从多格兰在伤残与折磨中展现的忍耐力中，看到兽人步兵应有的顽强韧性。"},sec={{t="孤身营救",b="陶拉祖营地的步兵劳格玛不愿让部落士兵冒险，对固守阵地的野猪人发动代价高昂的进攻。多格兰的命运就掌握在你这个术士学徒手中，而你手里只有肯兹格拉的伤药。向北穿过荆棘丛和敌人的营地，找到野猪人关押他的地方。"},{t="鲜血的代价",b="步兵多格兰身受重伤，倒在陶拉祖以北的棚屋中，周围尽是敌对的野猪人。肯兹格拉的伤药让他恢复了足够的体力，能够蹒跚着走到安全的地方，但这些伤势使他终身残疾。他失去了一条胳膊和一条腿。"}},faq={{q="步兵多格兰被关在哪里？",a="步兵多格兰被关在贫瘠之地陶拉祖营地正北方的两间野猪人棚屋中。",al={"多格兰位置","多格兰在哪里","贫瘠之地寻找多格兰"}},{q="步兵劳格玛为什么不派士兵帮忙？",a="步兵劳格玛无法从陶拉祖营地的防御部队中抽调兵力。他认为，深入戒备森严的野猪人领地展开营救太过危险，不值得让更多士兵冒生命危险。",al={"部落卫兵为何不帮忙","劳格玛士兵","陶拉祖援军"}},{q="肯兹格拉的伤药是什么？",a="肯兹格拉的伤药是一种药效强劲、味道难喝的滋补药剂，专为身受重伤的多格兰调制，让他恢复足够的力气站起来，逃离野猪人的囚禁。",al={"肯兹格拉药水","伤药是什么","多格兰伤药"}},{q="找到多格兰时，他的状况如何？",a="多格兰遭受了野猪人的折磨，浑身是伤，已濒临死亡。即使喝下伤药，他的一条胳膊和一条腿也已无法治愈。",al={"多格兰伤势","多格兰还活着吗","多格兰胳膊和腿"}},{q="这次营救与召唤魅魔有什么关系？",a="多格兰随身带着一件信物，与爱情和凡人的忠贞有关，而术士正是利用这些情感和观念来召唤并束缚魅魔。",al={"术士为何这样做","魅魔任务关联","术士任务多格兰"}},{q="是谁俘虏了多格兰？",a="多格兰被生活在陶拉祖营地以北荆棘丛中的野猪人部族俘虏。",al={"谁抓走了多格兰","俘虏多格兰的人","贫瘠之地绑架者"}}},fp="18,191,15.297.0,18.220.1,27.107.0,45.164.0,28.161.0,39.167.1,52.123.1,20.84.0"}
P.entries["quest:1516"] = {n="大地的召唤",s="在试炼谷，坎纳甘·地鸣让部落的萨满祭司新手接受耐力与耐心的考验。他们猎杀地狱捕猎者，用来调制仪式所需的灵契。",h="在试炼谷，坎纳甘·地鸣让部落的萨满祭司新手接受耐力与耐心的考验。他们猎杀地狱捕猎者，用来调制仪式所需的灵契。",kw={"火刃氏族","大地的召唤","坎纳甘·地鸣","大地图腾","地狱捕猎者","灵契","萨满祭司试炼","试炼谷"},ang={["class:Shaman"]="身为萨满祭司，你将在这里开始正式与元素沟通，为获得大地图腾奠定基础。",["race:Orc"]="身为萨尔领导的部落中的兽人，重归萨满之道，就是向遭受恶魔腐化之前的古老氏族传统致敬。",["race:Troll"]="身为巨魔，你追随暗矛的巫医和通灵者，接纳大地之灵，为族人与兽人共同建立的新家园提供支撑。"},sec={{t="最初的联结",b="萨满祭司首先要学习如何与每一种元素建立联结。对兽人和巨魔而言，这条道路始于大地，它是生命、耐力与耐心的基石。在试炼谷，坎纳甘·地鸣指引初入此道的萨满祭司，教导他们：唯有心怀敬意、坚定不移，才能获得大地的庇护。"},{t="净化之猎",b="火刃氏族的邪教势力在试炼谷以北的峡谷中滋生。其黑暗魔法召来了地狱捕猎者，这些腐化的猎犬来自这个位面之外。猎杀它们，是为了考验萨满祭司能否保护这片土地，抵御违背自然的腐化。坎纳甘用它们的蹄子调制大地灵契，这种神圣的饮剂能让凡人的双眼看见元素位面。"}},faq={{q="这场试炼的目的是什么？",a="这场试炼让萨满祭司开始研习元素的奥秘，并在大地之灵面前考验其耐心与心灵修为，为与这些元素之灵沟通、赢得大地图腾做好准备。",al={"为什么要做大地的召唤","大地的召唤奖励","任务目的"}},{q="坎纳甘·地鸣是谁？",a="坎纳甘·地鸣是杜隆塔尔试炼谷的一位巨魔萨满祭司训练师。他指引年轻的兽人、巨魔以及来访的牛头人萨满祭司，帮助他们掌握元素之力。",al={"坎纳甘是谁","坎纳甘·地鸣的故事"}},{q="坎纳甘为什么需要地狱捕猎者的蹄子？",a="坎纳甘用地狱捕猎者的蹄子调制大地灵契，这种药剂能让凡人萨满祭司感知元素之灵，并与它们交谈。",al={"为什么需要邪灵劣魔的蹄子","蹄子的用途"}},{q="地狱捕猎者在哪里？",a="地狱捕猎者出没于试炼谷训练场以北、火刃集会所内的洞穴及周围峭壁。",al={"邪灵劣魔位置","哪里能找到邪灵劣魔"}},{q="部落的其他种族也能参加这里的试炼吗？",a="可以。这场试炼主要面向在杜隆塔尔成长的兽人和巨魔萨满祭司，但从红云台地远道而来的牛头人萨满祭司也能在试炼谷参加。",al={"牛头人能否参加","是否仅限兽人"}},{q="对萨满祭司而言，大地代表哪些美德？",a="在萨满传统中，大地是生命的根基。它体现着强大的力量、耐力与永恒的耐心，但若得不到尊重，也会变得固执而反复无常。",al={"大地的美德","大地对萨满祭司的意义"}}},fp="13,154,14.298.0,16.345.0,34.200.0,26.162.0,39.131.0,34.145.0,58.168.0,50.163.0"}
P.entries["quest:1517"] = {n="大地的召唤",s="在灵魂石地，坎纳甘·地鸣引导年轻的萨满祭司完成与元素的首次交流。他们在圣地饮下大地灵契，便能看见大地之魂。",h="在灵魂石地，坎纳甘·地鸣引导年轻的萨满祭司完成与元素的首次交流。他们在圣地饮下大地灵契，便能看见大地之魂。",kw={"大地的召唤","坎纳甘·地鸣","大地灵契","秘道","大地之魂","灵契视界","灵魂石地","试炼谷"},ang={["class:Shaman"]="身为萨满祭司，你迈出了与元素建立共鸣的第一步。真正的精通，始于大地沉静的耐心。",["race:Orc"]="兽人历经数代邪能腐化，如今正重拾先祖之道，对他们而言，通过大地灵契与元素交流，是一次神圣的重新发现，让他们找回族人与灵体之间的传统纽带。",["race:Troll"]="身为暗矛巨魔，你接受这些大地仪式，让自己与先祖的深厚联系适应杜隆塔尔严酷、烈日炙烤的土地。"},sec={{t="灵契的力量",b="灵契是一种神秘的药剂，只有少数萨满大师知晓。它以元素魔法制成，连接凡人的感知与灵魂位面，让意志坚定者获得灵契视觉。由于它会将饮用者的灵魂直接与一种元素相连，传统禁止在经过祝圣的圣地之外饮用。"},{t="前往灵魂石地的朝圣之路",b="要与大地交流，你需要离开试炼谷，沿秘道攀上杜隆塔尔南部的峭壁。灵魂石地就在小径尽头，那是一处地势高耸的圣地，俯瞰着崎岖的荒原。在那里饮下灵契，你就能感知到寻常双眼无法看见的存在：岩石间的元素之灵。"},{t="大地的耐心",b="大地之魂不要求流血，也不要求臣服。它只要求你谦卑地立于世界面前。火、水与空气的灵体躁动不安、变幻无常，时常陷入混乱，而大地教导的是沉稳。高山赋予坚韧，平原教导无尽的耐心。"}},faq={{q="什么是大地灵契？",a="大地灵契是由资深萨满祭司调制的药水，能让饮用者的灵魂暂时与大地产生共鸣。饮下它便能获得内在的视野，看见隐藏的元素之灵并与之交谈。",al={"什么是灵契","大地灵契的含义","灵契有什么作用"}},{q="灵魂石地在哪里？",a="灵魂石地位于试炼谷大兽穴西南方的崎岖山地中。沿着秘道走进谷底南面的山丘，就能抵达。",al={"灵魂石地在哪里","灵魂石地位置","如何找到灵魂石地"}},{q="为什么必须在灵魂石地饮用灵契？",a="萨满传统规定，只有在指定的圣地才能饮用灵契。灵魂石地这样的圣地，是凡人世界与元素之灵之间的天然界限薄弱之处。",al={"为什么在灵魂石地饮用","灵契能在任何地方饮用吗"}},{q="大地之魂是谁？",a="大地之魂是居住在灵魂石地的元素之灵。只有灵契之眼赋予的敏锐感知才能让人看见它；它迎接年轻的萨满祭司，考验他们是否谦卑，并传授元素平衡的最初教诲。",al={"大地之魂","大地之灵是谁"}},{q="所有部落萨满祭司都能接受这项试炼吗？",a="这项仪式主要由在杜隆塔尔受训的年轻兽人和暗矛巨魔萨满祭司完成。来到这里的牛头人萨满祭司也可以完成这项仪式，不过他们对应的仪式是在红云台地举行的。",al={"牛头人能做这个任务吗","谁能完成大地的召唤"}},{q="大地之灵如何对待初学者？",a="与变幻无常的火焰或空气化身不同，大地之灵欢迎并接纳那些怀着谦卑与敬意前来的初学者。它赐下祝福，无须对方通过力量的较量。",al={"大地之灵说什么","大地之灵有敌意吗"}}},fp="13,183,22.296.0,25.303.0,21.285.0,23.183.0,29.163.0,46.180.0,40.220.0,42.197.0,48.185.0"}
P.entries["quest:1518"] = {n="大地的召唤",s="在杜隆塔尔，一名年轻的萨满祭司与大地之灵的化身沟通。学徒带着粗石英回到坎纳甘·地鸣身边，获得了自己的第一个元素图腾。",h="在杜隆塔尔，一名年轻的萨满祭司与大地之灵的化身沟通。学徒带着粗石英回到坎纳甘·地鸣身边，获得了自己的第一个元素图腾。",kw={"大地的召唤","坎纳甘·地鸣","杜隆塔尔","大地图腾","大地之魂","粗石英","萨满祭司","试炼谷"},ang={["class:Shaman"]="身为萨满祭司，这场仪式让你获得第一个图腾，并使你能够扎根于元素之中，呼唤大地的援助。",["faction:Horde"]="身为部落的一员，你知道卡利姆多的元素狂野不驯。部落萨满祭司与它们建立的纽带，对新定居点的存续至关重要。",["race:Orc"]="身为兽人，你参与了杜隆塔尔兽人萨满之道的复兴，在历经数十年的恶魔腐化后，重新寻求元素的平衡。",["race:Troll"]="身为巨魔，你在试炼谷与兽人一同学习，将四种元素之道融入暗矛巫医和通灵者传统的沟通方式之中。"},sec={{t="磐石之心",b="初出茅庐的萨满祭司凭借耐心与谦逊寻求与大地沟通，而非依靠蛮力。大地之魂赐予学徒一块粗石英。这块小小的石头证明大地之灵已接受学徒的誓言，也是一颗力量的种子。"},{t="四道之始",b="你将石英带给试炼谷的坎纳甘·地鸣，便完成了试炼。坎纳甘将它制成大地图腾，让你以此为媒介，引导大地坚定的庇护与力量。这场仪式开启了你研习四种元素之道的旅程，也为你毕生与自然世界的沟通奠定了基础。"}},faq={{q="粗石英有什么用途？",a="粗石英是大地之魂给予的信物，证明你已与大地之灵沟通过。坎纳甘·地鸣将它嵌入你的大地图腾，使其成为图腾的核心，以及你施展大地法术的媒介。",al={"粗石英","石英有什么用","石英用途"}},{q="坎纳甘·地鸣是谁？",a="坎纳甘·地鸣是杜隆塔尔试炼谷的一名萨满祭司训练师。他引导年轻的兽人和巨魔学徒完成最初的试炼，为他们与元素之灵沟通做好准备，并制作他们的第一个图腾。",al={"坎纳甘","坎纳甘·地鸣","坎纳甘是谁"}},{q="牛头人能做这个任务吗？",a="可以。牛头人通常在莫高雷的红云台地，由自己的长者引导完成大地试炼，但任何前往试炼谷的部落萨满祭司，都可以在坎纳甘·地鸣的引导下完成仪式。",al={"牛头人能做杜隆塔尔的大地的召唤吗","牛头人萨满祭司杜隆塔尔","牛头人大地的召唤"}},{q="获得大地图腾意味着什么？",a="获得大地图腾，意味着大地之灵已认可你。它标志着你在萨满祭司中的身份，也为你施展大地的祝福与守护提供了实体媒介。",al={"为何获取大地图腾","萨满祭司大地图腾的意义"}},{q="大地要求萨满祭司具备哪些美德？",a="大地之灵要求学徒具备耐心、力量与智慧。它教导萨满祭司，即使是最小的卵石，也能凭借坚韧比群山存续得更久，并告诫他们尊重大地，大地才会回报以支撑。",al={"大地之灵的教诲","大地有何要求"}},{q="此后，萨满之路将通向何方？",a="大地是萨满祭司必须掌握的四种元素中的第一种。随着修行的深入，你将响应召唤，寻求与火焰、水流和空气之灵沟通。",al={"下一个图腾是什么","大地图腾之后","萨满祭司四种元素之道"}}},fp="13,145,18.262.0,23.364.0,34.215.0,26.220.0,25.202.0,44.187.0,49.210.0,41.164.0"}
P.entries["quest:1519"] = {n="大地的召唤",s="大地呼唤萨满祭司，开始一场考验耐心的沟通试炼。接受大地 灵契 后，求道者便踏上灵魂重生之路，学会聆听生命根基的声音。",h="大地呼唤萨满祭司，开始一场考验耐心的沟通试炼。接受大地 灵契 后，求道者便踏上灵魂重生之路，学会聆听生命根基的声音。",kw={"大地的召唤","大地母亲","元素","耐心","重生","灵契","萨满祭司","耐力"},ang={["class:Shaman"]="作为萨满祭司，这场仪式标志着你修行中的一个转折点。与大地沟通会带来力量、耐力，以及对灵魂的深刻领悟。",["faction:Horde"]="作为部落的一员，你的萨满传统植根于元素之力。你的道路始于大地稳固坚韧的力量。",["race:Tauren"]="作为牛头人，对 Earth Mother 的敬奉是你文化的核心。这场试炼向祖先秉持的信仰致敬。"},sec={{t="万物的根基",b="萨满祭司通过一场奠定根基的仪式，学习与大地的原初力量沟通。大地是所有元素中最顽固、最睿智的，是支撑万物的稳固基石。它在侵蚀与重生的缓慢循环中变迁。高山风化为沙漠，河流历经漫长岁月切出峡谷。要听见大地的声音，初学者也需要这样的耐心。"},{t="灵契 与重生",b="回应召唤会改变求道者，使其再也无法回到从前的无知之中。当初学者证明自己已做好准备，并尊重 大地母亲 的法则时，便会获得大地 灵契。这种药剂开启了全新的视野，萨满祭司由此开始领悟大地赋予力量、耐力和元素防护的奥秘。"}},faq={{q="什么是大地的召唤？",a="大地的召唤考验有志成为萨满祭司的人是否具备耐心，是否已准备好与大地沟通。求道者必须聆听大地亘古长存的智慧。",al={"什么是 大地的召唤","大地任务 萨满祭司","大地的召唤 的目的"}},{q="在萨满祭司的传统中，大地元素代表什么？",a="大地是万物的根基，象征着力量、耐力与耐心。它是最顽固、最睿智的元素，教导人们万物都会随时间流逝而消蚀、重生。",al={"大地代表什么","大地元素背景故事","大地对萨满祭司的意义"}},{q="什么是 灵契？",a="灵契 是由萨满祭司导师调制的元素药剂。接受它便会开启一条灵魂之路，让求道者的感官能够感应元素之灵。",al={"什么是 灵契","大地灵契","灵契 的作用"}},{q="试炼中提到的 大地母亲 是谁？",a="大地母亲 是生命与平衡的源泉，尤其受到牛头人萨满祭司的敬奉。她庇护遵守其法则的人，并将智慧赐予尊重大地的求道者。",al={"大地母亲 是谁","大地母亲 背景故事","与 大地母亲 的联系"}},{q="回应召唤后会发生什么？",a="回应召唤会让求道者做好准备，迈出道路上的下一步。它带来灵魂的重生，此后萨满祭司便无法重归无知，大地新的奥秘也会逐渐显现。",al={"完成后会发生什么","大地的召唤 之后","大地的召唤 重生"}},{q="为什么与大地沟通需要耐心？",a="大地在侵蚀与重生的循环中变迁。高山风化为沙漠，河流切出峡谷，因此萨满祭司需要耐心与耐力，才能感应这些恒久的韵律。",al={"为什么大地需要耐心","耐心与大地"}}},fp="13,187,28.357.0,21.315.0,26.128.0,60.180.0,16.150.0,47.178.0,37.189.0,51.180.0"}
P.entries["quest:152"] = {n="清理海岸",s="遇上海难的水手挣扎着游向西部荒野的西海岸，鱼人正步步逼近。葛瑞森船长请你清除海滩上的鱼人，让幸存者能够安全上岸。",h="遇上海难的水手挣扎着游向西部荒野的西海岸，鱼人正步步逼近。葛瑞森船长请你清除海滩上的鱼人，让幸存者能够安全上岸。",kw={"葛瑞森船长","滩行者","无尽之海","鱼人","神谕","海难","猎潮者","西部荒野灯塔"},ang={["faction:Alliance"]="暴风城的军队不在西部荒野，人民军艰难地保护着内陆的农场。葛瑞森船长这样的盟友则协助守卫海岸。",["race:Human"]="身为人类，你知道商船和渔民长久以来一直在西部荒野的海域航行。如今海岸落入鱼人之手，令人痛心地昭示着王国边疆的失守。"},sec={{t="船只的坟场",b="暗礁、狂风和嶙峋的岩石让船只在西部荒野的浅滩搁浅。幸存者紧抱船只残骸，爬上沙滩，盼着有人前来救援。然而，等待他们的却是沿岸的鱼人部族，而鱼人对这些落难者毫不留情。"},{t="幽灵瞭望者",b="葛瑞森船长在大陆西南方一处孤零零的岩石上守望。他虽已死去，却仍被束缚在灯塔，也依然肩负着照看过往船只和落难水手的职责。滩行者盘踞在北部海岸。再往南，猎潮者、战士和神谕聚集在那里。"}},faq={{q="葛瑞森船长是谁？",a="葛瑞森船长是徘徊在西部荒野灯塔的幽灵船长。他仍觉得自己有责任保护在险恶海域航行的水手，以及海难中的幸存者。",al={"葛瑞森船长","灯塔里的幽灵","西部荒野灯塔看守人"}},{q="格雷森为什么要清除海岸上的鱼人？",a="格雷森想清除鱼人，是因为遇上海难的水手经常被冲上西部荒野的海岸。鱼人从北到南遍布海滩，杀害那些抵达陆地的幸存者。",al={"西部荒野为什么要杀鱼人","清理海岸原因","为什么要清理海岸"}},{q="这些不同的鱼人都在哪里？",a="鱼人滩行者通常栖居在西部荒野的北部海岸。鱼人战士、神谕和猎潮者则聚集在南部海滩的聚落和营地中。",al={"西部荒野鱼人位置","鱼人滩行者在哪里","猎潮者在哪里"}},{q="葛瑞森船长对联盟或部落抱有敌意吗？",a="葛瑞森船长保持中立。他对水手的职责不受阵营界限约束，任何有能力的旅人都可以应他的请求，让海岸变得更安全。",al={"格雷森是否友善","格雷森阵营","部落能否接这个任务"}},{q="这个任务需要先重新点亮灯塔吗？",a="不需要。无论你是否帮忙重新点亮了西部荒野灯塔，葛瑞森船长都会请你清除海岸上的鱼人。",al={"是否需要先完成长明的灯塔","清理海岸前置任务"}},{q="鱼人在为迪菲亚潜行者效力吗？",a="没有。鱼人独自行动，会攻击任何闯入其沿岸猎场的人。迪菲亚潜行者则在附近的月溪镇一带和南部海湾活动。",al={"迪菲亚是否与鱼人结盟","迪菲亚与鱼人的联系"}}},fx={["9a80f3b4"]={q="哪些鱼人正在威胁西部荒野的海岸？",a="你要猎杀的是盘踞在西部荒野西部海滩上的鱼人：在北部浪涛间游荡的滩行者，以及在更南方扎根的战士、猎潮者和神谕。这些水生掠食者在沿岸的沉船残骸间筑巢，劫掠搁浅的船只，袭击不幸被冲上海岸的人。",al={"要杀哪些鱼人","海岸鱼人是谁","西部荒野海岸鱼人目标"}},["49634979"]={q="葛瑞森船长为什么需要冒险者对付鱼人？",a="葛瑞森船长是一个不得安息的幽灵，被束缚在西部荒野灯塔孤寂的礁石上。他无法亲自沿着海岸巡行，而暴风城的驻军又已撤离，任由匪患肆虐，因此他只能依靠你这样的过路冒险者，为幸存的水手扫清海滩上的威胁。",al={"葛瑞森船长为何不杀鱼人","葛瑞森船长为何需要帮忙","为何不让卫兵清理海岸"}}},fp="21,163,20.237.0,19.275.0,23.170.0,57.176.0,42.166.0,52.130.0,56.111.0,51.176.0"}
P.entries["quest:1520"] = {n="大地的召唤",s="在科多石，你通过一项神圣的牛头人仪式，寻求与大地沟通。饮下大地灵契，便能看见大地之魂。",h="在科多石，你通过一项神圣的牛头人仪式，寻求与大地沟通。饮下大地灵契，便能看见大地之魂。",kw={"大地的召唤","纳拉其营地","大地灵契","科多石","显现","莫高雷","灵契","鸦羽先知"},ang={["class:Shaman"]="作为萨满，这项仪式构成了你与土地之间联结的精神核心。它是通往大地沟通、获得大地图腾的桥梁。",["race:Tauren"]="作为牛头人，你可以参加sapta仪式，这是红云台地上灵修者最为崇敬的成年试炼之一。"},sec={{t="灵契的用途",b="萨满长者酿制灵契，将初学者的凡人灵魂与原始元素相连。先祖的魔法守护着酿制的秘密，牛头人中只有少数被选中者知晓。在圣地饮下药剂，你的心智便能超越物质世界。帷幕随之揭开，元素的原始形态显露眼前。"},{t="在科多石沟通大地",b="科多石矗立在纳拉其营地以东，既是一根石柱，也是一处神圣的庇护所。在那里饮下灵契，大地之魂便会出现在你面前。在萨满之道上，自然的其他面貌或是变幻不定，或是炽烈，或是狂暴。大地所要求的却是沉静与谦卑。敬重这片土地，它的灵魂便会赐予你山岳般持久的力量，以及平原般沉静的耐心。"}},faq={{q="什么是大地灵契？",a="大地灵契是萨满长者为仪式酿制的药剂。它的魔力能开启你的感知，让你看见大地元素之灵，并与之交谈。",al={"什么是灵契","大地灵契含义","药剂的作用"}},{q="科多石位于何处？",a="科多石是一块天然巨石，位于纳拉其营地以东，穿过红云台地便可抵达。",al={"寻找科多石","科多石位置","圣所在哪里"}},{q="谁为这场仪式酿制了大地灵契？",a="纳拉其营地的萨满长者鸦羽先知调制并赐予了这瓶药剂。鸦羽先知负责培养年轻的灵魂向导。",al={"谁赐予灵契","鸦羽先知灵契"}},{q="为什么必须在圣地饮用灵契？",a="依照牛头人的传统，灵契只能在经过祝圣的圣所中饮用，元素之灵居于其中，能够安全地接见祈求者。这种药剂十分神圣，使用不当便会带来危险。",al={"为什么在科多石饮用","灵契能在任何地方饮用吗"}},{q="在科多石饮下药剂后会发生什么？",a="在科多石饮下药剂，会揭开凡俗世界的帷幕，让大地之魂显现。与这个灵魂交谈，便能完成萨满与大地的联结。",al={"会出现什么","大地之魂出现"}},{q="大地之灵会向初学者传授什么？",a="大地之灵教导的是谦卑与耐心，而非战斗。火与风可能混乱而狂暴，大地则给予萨满的灵魂力量、坚韧与沉静的根基。",al={"大地之灵的教诲","大地仪式的意义"}}},fp="13,133,24.291.0,22.376.0,23.152.0,27.86.0,42.151.0,46.193.0,52.166.0,54.182.0"}
P.entries["quest:1521"] = {n="大地的召唤",s="在莫高雷首次与大地之灵沟通后，一名年轻的牛头人萨满祭司带着大地的馈赠返回纳拉其营地。饮下大地灵契后，这位学徒便能直接与显现的元素之灵交谈，并获得一块原石，与四大元素中的第一种结下契约。",h="在莫高雷首次与大地之灵沟通后，一名年轻的牛头人萨满祭司带着大地的馈赠返回纳拉其营地。饮下大地灵契后，这位学徒便能直接与显现的元素之灵交谈，并获得一块原石，与四大元素中的第一种结下契约。",kw={"大地的召唤","纳拉其营地","大地图腾","大地之魂","莫高雷","红云台地","粗石英","鸦羽先知","牛头人萨满祭司"},ang={["class:Shaman"]="作为萨满祭司，你会通过这场仪式获得自己的第一个图腾。随身携带它，能让你的精神身份有所依托，并让你施放重要的大地防护结界。",["faction:Horde"]="作为部落的萨满祭司，你是精神上的支柱与顾问，在凡人种族与卡利姆多动荡的元素之力之间架起桥梁。",["race:Tauren"]="牛头人文化对Earth Mother怀有深深的敬意。这场试炼将学徒与祖传家园中富有生命的岩石和土壤联结在一起。"},sec={{t="山峦的馈赠",b="饮下大地灵契后，你在红云台地附近的峭壁顶端见到了大地之魂。大地之魂交给你一块朴实无华的粗石英。它象征着你与大地元素的契约，以及岩石的坚韧。大地之魂提醒你，耐心与力量是大地所要求的美德，并承诺，只要彼此尊重，你便能与这片土地和谐共处。"},{t="第一个图腾",b="在纳拉其营地，鸦羽先知将获赠的石英制成了你的第一个大地图腾。这个图腾不仅是身份的象征，更是长久维系肉体与灵魂的依托。借助这件雕刻而成的施法媒介，你引导大地稳固根基、提供庇护的魔法，在通往四大元素的道路上迈出真正的第一步。"}},faq={{q="粗石英有什么用途？",a="粗石英是大地之魂交给你的信物，证明你已与它沟通。鸦羽先知用它作为你新制大地图腾的灵性核心。",al={"为什么需要粗石英","石英有什么用","粗石英用途"}},{q="大地图腾为何对萨满祭司如此重要？",a="图腾让萨满祭司能够引导元素之力。没有大地图腾作为施法媒介，萨满祭司就无法祈求大地之灵施展法术与防护结界。",al={"为什么需要大地图腾","大地图腾有什么用","大地图腾的传说"}},{q="鸦羽先知是谁？",a="鸦羽先知是红云台地上纳拉其营地的精神导师和萨满祭司训练师。她监督年轻牛头人的元素试炼，引导他们经历最初的幻象，并为他们制作神圣的器具。",al={"鸦羽是谁","鸦羽先知的传说","纳拉其营地的先知"}},{q="鸦羽先知提到的四条道路是什么？",a="鸦羽先知指的是萨满祭司必须掌握的四种原始元素：大地、火焰、水和空气。大地是一切的根基，象征着坚韧与坚定，也是学徒面临的第一场试炼。",al={"四条道路","萨满祭司的四大元素","四条道路是什么"}},{q="这次沟通在哪里进行？",a="这次沟通在莫高雷红云台地边缘的崎岖峭壁间进行。只有饮下大地灵契后，你才能见到大地之魂。",al={"哪里能找到大地之灵","元素之灵显现的位置","元素之灵在哪里"}},{q="其他部落萨满祭司也会经历类似的仪式吗？",a="是的。杜隆塔尔的兽人和暗矛巨魔会在试炼谷完成各自的大地的召唤。他们寻求与当地显现的元素之灵沟通，并雕刻自己的第一个图腾。",al={"兽人也要完成大地的召唤吗","巨魔的大地的召唤","所有萨满祭司都会获得大地图腾吗"}}},fp="13,211,24.333.0,15.307.0,40.165.0,47.153.0,25.219.0,51.198.0,37.170.0,48.186.0"}
P.entries["quest:1522"] = {n="火焰的召唤",s="一位萨满祭司看出了你在大地之道上的实力，派你北上去找卡纳尔·菲斯。在那里，你可以学习火焰之道。",h="一位萨满祭司看出了你在大地之道上的实力，派你北上去找卡纳尔·菲斯。在那里，你可以学习火焰之道。",kw={"贫瘠之地","火焰的召唤","十字路口","大地","火焰","卡纳尔·菲斯","萨满祭司"},ang={["class:Shaman"]="身为萨满祭司，你在展现出大地之道上的实力后，被派去找卡纳尔·菲斯学习火焰之道。"},sec={{t="卡纳尔·菲斯",b="卡纳尔·菲斯住在十字路口以北。那位萨满祭司说，他很容易找到，但也警告你不要走得太远，以免进入精灵的领地。"}},faq={{q="卡纳尔·菲斯是谁？",a="卡纳尔·菲斯是贫瘠之地的一位萨满祭司，可以教你火焰之道。",al={"卡纳尔是谁","卡纳尔"}},{q="在哪里可以找到卡纳尔？",a="卡纳尔住在贫瘠之地的十字路口以北。",al={"卡纳尔的位置","卡纳尔在哪里"}},{q="为什么要派我去找卡纳尔？",a="那位萨满祭司看出了你在大地之道上的实力，认为你已经准备好与卡纳尔交谈，向他学习火焰之道。",al={"为什么找卡纳尔","火焰训练"}}},fp="12,111,11.144.0,19.74.0,24.52.0,30.123.0"}
P.entries["quest:1524"] = {n="火焰的召唤",s="在贫瘠之地，一位志在萨满之道的学徒开始了寻求与火焰沟通的第二场试炼。卡纳尔·菲斯派这位学徒带着尚未点燃的眠炎火炬，渡过怒水河，前往杜隆塔尔一处隐秘的山顶圣殿。",h="在贫瘠之地，一位志在萨满之道的学徒开始了寻求与火焰沟通的第二场试炼。卡纳尔·菲斯派这位学徒带着尚未点燃的眠炎火炬，渡过怒水河，前往杜隆塔尔一处隐秘的山顶圣殿。",kw={"贫瘠之地","火焰的召唤","杜隆塔尔","火焰图腾","卡纳尔·菲斯","眠炎圣殿","怒水河","泰尔夫·祖拉姆"},ang={["class:Shaman"]="身为萨满祭司，你通过与卡利姆多的元素之力沟通，寻求火焰图腾。这条道路会带你前往偏远的圣殿，经历简单教导之外的考验。",["faction:Horde"]="身为部落的一员，你与兽人、牛头人和巨魔共同传承萨满教义。这些传统引领弟子们从贫瘠之地的平原，走向杜隆塔尔的神圣峭壁。"},sec={{t="资格的考验",b="卡纳尔·菲斯将眠炎火炬托付给萨满祭司。仅凭原始的神秘力量，还不足以满足火焰的要求；这场试炼需要节制、专注与敬意。这支火炬既是仪式用具，也是向圣殿守护者出示的凭证，表明持有者已被认定有资格接受试炼。"},{t="隐秘的山巅",b="圣殿坐落在怒水河对岸，杜隆塔尔南部的峭壁之间。一块饱经风霜、刻有火焰符文的石头标示着一条隐蔽的小径，通向这片地区最高的山峰之一。山顶的眠炎圣殿由巨魔隐士泰尔夫·祖拉姆看守。他将好奇的旅人和寻宝者拒之门外，不让寻常人窥见神圣的火盆，直到求见者带着尚未点燃的火炬到来。"}},faq={{q="眠炎火炬有什么用途？",a="卡纳尔·菲斯交出尚未点燃的火炬，作为求道决心的信物。它向圣殿守护者泰尔夫·祖拉姆表明，持有者是一名已被认定有资格接受试炼的萨满学徒。",al={"为何携带火炬","眠炎火炬","火炬的意义"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是部落的一位萨满隐士，守护着杜隆塔尔南部群峰之巅的眠炎圣殿。他看守着火盆，不让那些不理解或不尊重元素之灵的人靠近。",al={"泰尔夫·祖拉姆","圣殿守护者","圣殿的巨魔是谁"}},{q="秘道在哪里？",a="这条隐秘小径的起点位于杜隆塔尔，在怒水河大桥以南。河岸附近，山峦与海岸交汇之处，一块刻有火焰符文的立石标示着通往高处山脊的狭窄山道。",al={"秘道位置","如何找到眠炎圣殿","上山的路"}},{q="为什么必须带来尚未点燃的火炬？",a="火炬必须在尚未点燃时带来，因为火焰必须通过仪式唤醒并掌控，不能直接索取。沉睡的火焰代表着一种有待唤醒的状态，萨满祭司必须通过沟通将其点燃。",al={"火炬为何未点燃","眠炎火炬仪式","火焰为何沉睡"}},{q="找到泰尔夫·祖拉姆之后会发生什么？",a="泰尔夫·祖拉姆查验火炬后，会指引学徒接受更严酷、更危险的仪式，点燃其中沉睡的火焰，并证明自己能够掌控火焰元素。",al={"火焰的召唤下一步","找到泰尔夫·祖拉姆之后"}},{q="为什么要向部落的其他成员隐瞒这座圣殿？",a="圣殿远离人群，是因为元素之力变幻无常，在未经训练的人手中十分危险。萨满传统将圣地设在远离日常聚居地的地方，以免好奇者和寻宝者惊扰休憩的元素之灵，或招来灾祸。",al={"圣殿为何保密","圣殿是否隐蔽"}}},fp="12,231,19.286.0,15.433.0,54.165.0,19.206.0,33.228.0,36.173.0,40.159.0,58.260.0"}
P.entries["quest:1525"] = {n="火焰的召唤",s="泰尔夫·祖拉姆派一名萨满祭司前往杜隆塔尔和贫瘠之地东部，收集制作火焰灵契的材料。这种药剂能让初学者感知火焰之灵，并与之交谈。",h="泰尔夫·祖拉姆派一名萨满祭司前往杜隆塔尔和贫瘠之地东部，收集制作火焰灵契的材料。这种药剂能让初学者感知火焰之灵，并与之交谈。",kw={"火刃氏族","火焰的召唤","尘风洞穴","火焰灵契","火焰焦油","钢鬃","试剂袋","泰尔夫·祖拉姆"},ang={["class:Shaman"]="身为萨满祭司，你面临着平衡对立力量的试炼。在智慧的引导下，火焰既能带来生机与光明，也能释放怒火。",["faction:Horde"]="身为部落的守卫者，你面临着边境上的威胁：在贫瘠之地步步进逼的钢鬃野猪人，以及潜藏在杜隆塔尔境内的火刃氏族教徒。",["race:Orc"]="身为兽人，你要直面火刃氏族，以及曾经腐化你族人的术士魔法。重新掌握作为自然元素的火焰，是重建族群文化的行动。"},sec={{t="调制火焰灵契",b="火焰灵契能让萨满祭司感知到永恒之火。与大地的药剂一样，它能让萨满祭司看见凡人肉眼无法察觉的元素之灵，并与之交谈。泰尔夫·祖拉姆派初学者穿越杜隆塔尔，进入贫瘠之地东部，收集与热量和火焰相连的材料。"},{t="敌人与元素",b="贫瘠之地东部的钢鬃野猪人施法者携带着火焰焦油，那是他们在大地仪式中制成的。火刃氏族的教徒携带着另一种所需的材料，他们藏身于剃刀岭东北方峡谷中的尘风洞穴。教徒们利用火焰制造毁灭和恶魔的混乱，而他们袋中的试剂与火元素有着天然的联系。"},{t="火焰的本质",b="泰尔夫·祖拉姆教导说，火焰带来的不只有毁灭与破坏。它也带来温暖与光明，让创造成为可能。明智的萨满祭司懂得对立的力量如何赋予彼此意义，并将相互对立的元素结合运用，而非仅仅把火焰当作武器。"}},faq={{q="什么是火焰灵契？",a="火焰灵契是一种仪式药剂，由与火焰相连的材料制成。饮下它能让萨满祭司的灵魂与视野短暂地与火焰位面相合，显现出其中的元素之灵，使萨满祭司能与它们交谈。",al={"什么是火焰灵契","火焰灵契含义","为什么要喝灵契"}},{q="在哪里能找到火焰焦油？",a="贫瘠之地东部的钢鬃野猪人施法者携带着火焰焦油，从杜隆塔尔渡过怒水河就能到达那里。地卜师、先知、秘法师和织棘者经常携带罐装的这种黏稠易燃的混合物，用于部族仪式。",al={"火焰焦油位置","谁掉落火焰焦油","火焰焦油野猪人"}},{q="在哪里能找到试剂袋？",a="杜隆塔尔剃刀岭东北方峡谷上方的尘风洞穴中，火刃氏族的教徒携带着试剂袋。这座洞穴与更北边、靠近海岸的骷髅石并非同一处地方。",al={"试剂袋位置","哪个洞穴有试剂袋","火刃氏族袋子"}},{q="为什么萨满祭司要使用术士的物品？",a="泰尔夫·祖拉姆需要浸透火焰之力的材料来制作火焰灵契。火刃氏族的教徒召唤具有毁灭性的恶魔火焰，他们的施法材料袋中装着与火焰相连的强效试剂。",al={"为什么使用火刃氏族试剂","萨满祭司使用术士物品","术士火焰"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一名独居的巨魔萨满祭司，他的营地位于杜隆塔尔的峭壁之巅，在剃刀岭以南。他负责主持部落初学者的火焰试炼，引导他们在毁灭与创造之间寻求平衡。",al={"泰尔夫·祖拉姆背景故事","泰尔夫·祖拉姆是谁"}},{q="这个任务之后会发生什么？",a="泰尔夫·祖拉姆用收集到的材料制成火焰灵契后，会派你前往附近休眠火山高处的炽热之地。你在那里饮下药剂，面对元素之灵，并获得自己的火焰图腾。",al={"火焰的召唤后续任务","取得试剂之后","火焰灵契怎么用"}}},fp="12,172,22.260.0,20.326.0,19.274.1,21.192.0,29.223.0,33.186.0,42.181.0,19.206.0,30.204.1"}
P.entries["quest:1526"] = {n="火焰的召唤",s="在杜隆塔尔的群峰之巅，萨满祭司将面对一场试炼，与火焰建立联系。泰尔夫·祖拉姆指引初学者饮下火焰灵契，迎战火焰之魂，并取得它的余烬，点燃仪式火炬。",h="在杜隆塔尔的群峰之巅，萨满祭司将面对一场试炼，与火焰建立联系。泰尔夫·祖拉姆指引初学者饮下火焰灵契，迎战火焰之魂，并取得它的余烬，点燃仪式火炬。",kw={"眠炎火盆","火焰的召唤","杜隆塔尔","火焰灵契","火焰图腾","火焰之魂","萨满祭司试炼","恒焰圣殿","泰尔夫·祖拉姆"},ang={["class:Shaman"]="作为萨满祭司，你会了解到，火焰变化无常，充满毁灭之力，与坚实不屈的大地截然不同。它会吞噬犹豫不决的召唤者，因此你需要专注与威严才能驾驭它。",["faction:Horde"]="作为部落的萨满祭司，你与兽人和巨魔萨满祭司一同攀上杜隆塔尔的红色峭壁，证明自己与这片土地上的火焰之灵心意相通。"},sec={{t="火焰之眼",b="在杜隆塔尔的山巅，未经训练的人无法看见火焰之灵。要看见它们，你需要饮下火焰灵契，这种药剂由从贫瘠之地和海岸各处收集的材料制成。它能让你的感官察觉隐匿的存在，使山巅乱石间的弱小灵体与化身显现出来。"},{t="迎战化身",b="一只火焰之魂在山顶等候。灵契生效后，这个灵体便知道你能看见它，等待你发起挑战。火焰回应力量与果断的行动，因此你要立即出击。战斗持续得越久，元素之火就燃烧得越猛烈。"},{t="休眠之焰火盆",b="击败化身后，你取得它残留的热量，凝成一块余烬。在山巅的圣坛，你将余烬放入眠炎火盆。铭刻着文字的金属在杜隆塔尔的日晒风吹下依然冰凉，直到余烬落入盆中。随后，炽白的烈焰燃起，点燃仪式火炬。"}},faq={{q="这场试炼的目的是什么？",a="你通过迎战火焰的化身，将它的热量引入仪式火炬，证明自己的力量。通过这场试炼，你便有资格制作火焰图腾。",al={"为什么要做火焰的召唤","火焰图腾任务意义","火焰的召唤试炼"}},{q="为什么需要饮下火焰灵契？",a="饮下火焰灵契后，你就能看见并触碰聚集在山顶的火元素，它们通常不在凡人的视野之内。",al={"火焰灵契有什么用","为什么需要灵契","看不见火元素"}},{q="在哪里能找到火焰之魂？",a="火焰之魂在杜隆塔尔的山脊最高峰等候，位于泰尔夫·祖拉姆栖身之处的上方，靠近恒焰圣殿。",al={"化身位置","火元素在哪里","该去哪里"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位性情古怪的萨满隐士，住在杜隆塔尔一条岩石山脊的高处。他引导年轻的部落初学者经历危险而变幻无常的仪式，理解火焰。",al={"泰尔夫·祖拉姆的作用","泰尔夫·祖拉姆的故事","隐士是谁"}},{q="为什么化身会在战斗中变强？",a="随着时间流逝，火焰会积聚力量，燃烧得更加炽烈。你必须果断出击，因为犹豫会让这个灵体变得更强。",al={"火元素为什么这么强","化身实力增长","迅速出击对抗火焰"}},{q="火盆点燃后会发生什么？",a="点燃火盆便会引燃仪式火炬。你将它的神圣火焰带下山，完成自己的火焰图腾。",al={"眠炎之后做什么","火焰的召唤后续任务","点燃的火炬带到哪里"}}},fp="12,176,17.257.0,29.272.0,32.289.1,34.154.0,38.106.0,47.146.0,19.176.0,58.121.0,38.120.0"}
P.entries["quest:1529"] = {n="水之召唤",s="你的水之召唤之路始于雷霆崖，一位萨满祭司已准备好探寻水元素。为了与水之先知伊斯伦会面，你向东穿过贫瘠之地，来到东部海岸。这次会面开启了一段通往水之图腾的灵性之旅。",h="你的水之召唤之路始于雷霆崖，一位萨满祭司已准备好探寻水元素。为了与水之先知伊斯伦会面，你向东穿过贫瘠之地，来到东部海岸。这次会面开启了一段通往水之图腾的灵性之旅。",kw={"贫瘠之地","水之召唤","水之先知伊斯伦","棘齿城","萨满祭司","怒水河","雷霆崖","水之图腾","萨尼斯·织火"},ang={["class:Shaman"]="作为萨满祭司，你从最初的元素试炼逐步迈向水与潮汐的净化和恢复之力。",["faction:Horde"]="作为部落的一员，你与兽人、巨魔和牛头人的灵修者共享萨满传统。",["race:Tauren"]="作为牛头人，你从雷霆崖出发，离开莫高雷受庇护的平原，走向卡利姆多更广阔的天地。"},sec={{t="雷霆崖的召唤",b="你已掌握大地与火焰的力量，如今导师们认为你已准备好研习水的力量。在雷霆崖，当你展现出接近这种净化元素所需的自律时，萨尼斯·织火便会认可你。你的道路将离开莫高雷的台地，向东穿过贫瘠之地干燥的平原。"},{t="海岸隐士",b="你在东部海岸的一间渔屋里找到了水之先知伊斯伦，那里位于棘齿城和怒水河河口以南。她远离聚落，独自生活在辽阔的大海旁。水之先知伊斯伦从你周围的元素中看出你已做好准备。大地、风与火焰已触及你的灵魂，她将引导你迎接试炼，领悟水的纯净。"}},faq={{q="是谁派我踏上这段旅程？",a="当你的修行进入水之仪式阶段时，雷霆崖的萨满祭司训练师，例如萨尼斯·织火，就会派你踏上旅程。",al={"任务给予者","谁开启水之召唤","雷霆崖哪里接水之召唤"}},{q="水之先知伊斯伦在哪里？",a="水之先知伊斯伦住在贫瘠之地东部海岸的一间渔屋里，位于棘齿城和怒水河河口以南。",al={"水之先知伊斯伦在哪里","水之先知伊斯伦位置","寻找水之先知伊斯伦"}},{q="水之召唤试炼的目的是什么？",a="这场试炼开启了萨满祭司与水的沟通，考验你对水之纯净的理解，并引领你获得水之图腾。",al={"为什么做水之召唤","水之召唤目的","萨满祭司水之图腾任务"}},{q="部落的其他种族也会接受同样的指引吗？",a="牛头人萨满祭司在雷霆崖接受召唤。奥格瑞玛和杜隆塔尔的兽人与巨魔萨满祭司也会收到类似的召唤，前往贫瘠之地海岸寻找水之先知伊斯伦。",al={"是否仅限牛头人","兽人水之召唤","巨魔水之召唤"}},{q="萨满祭司在研习水之前必须掌握哪些元素？",a="在探寻水的力量之前，你会先与大地和火焰沟通。在水展现其纯净之前，水之先知伊斯伦也能看到大地、风与火焰触及你的灵魂。",al={"前置条件","先获取哪些图腾","元素顺序"}},{q="找到水之先知伊斯伦之后会怎样？",a="找到水之先知伊斯伦，就完成了你从雷霆崖出发的旅程。随后，她会安排更多遍及卡利姆多的任务，帮助你理解并净化水。",al={"接下来做什么","找到水之先知伊斯伦之后","水之召唤第二部分"}}},fp="13,169,24.275.0,23.348.0,29.124.0,33.119.0,47.119.0,51.165.0,48.146.0,43.141.0"}
P.entries["quest:153"] = {n="红色皮质面罩",s="在哨兵岭，红色皮质面罩是对抗迪菲亚的标志。人民军艰难地追踪着遍布西部荒野的匪徒，哨兵加里安则在收集他们佩戴的红色面罩。",h="在哨兵岭，红色皮质面罩是对抗迪菲亚的标志。人民军艰难地追踪着遍布西部荒野的匪徒，哨兵加里安则在收集他们佩戴的红色面罩。",kw={"面罩","迪菲亚潜行者","人民军","红色皮质面罩","哨兵加里安","哨兵岭","西部荒野"},ang={["class:Rogue"]="身为潜行者，你看到迪菲亚的拦路强盗如何戴着鲜红的面罩集结起来，在暴风城门前组成一支军队。",["faction:Alliance"]="身为人民军的盟友，你帮助保卫西部荒野，而暴风城的王室统治者却没有派来任何援助。"},sec={{t="效忠的标志",b="在西部荒野各处，红色面罩是迪菲亚潜行者的标志。扒手、劫掠者和来自各行各业的叛徒加入这个团伙，随后聚集在同一个鲜红的标志之下。在哨兵岭，哨兵加里安和人民军收集这些面罩，作为匪徒已被击杀的凭证。这些面罩也帮助他们追踪迪菲亚在乡野间不断变化的战线。"},{t="民兵的侦察行动",b="暴风城拒绝为西部荒野提供应有的军事支援，人民军只能依靠哨兵加里安这样经验丰富的侦察人员，摸清迪菲亚的活动。加里安从哨兵岭监视匪徒的巡逻队，追踪他们的动向。过往的冒险者和民兵志愿者承担起危险的任务，铲除那些将老实农民赶出家园的拦路强盗。"}},faq={{q="迪菲亚为什么佩戴红色皮质面罩？",a="红色皮质面罩表明佩戴者效忠迪菲亚潜行者，也掩盖了那些昔日劳工、窃贼和亡命之徒的身份。它还让西部荒野剩下的农民心生恐惧。",al={"迪菲亚红色面罩的含义","为什么戴红色面罩","迪菲亚面罩的背景故事"}},{q="哨兵加里安是谁？",a="哨兵加里安在哨兵岭为人民军效力。他追踪迪菲亚潜行者在西部荒野的动向和不断变化的战线，并统筹悬赏事宜，遏制匪徒的活动。",al={"哨兵加里安","谁提供红色皮质面罩","哨兵岭的侦察兵"}},{q="民兵为什么需要冒险者收集这些面罩？",a="人民军人手紧缺，既没有王国士兵的支援，也没有暴风城的资金援助。悬赏让加里安这样的侦察人员获得匪徒已被击杀的凭证，也能削弱迪菲亚的势力，同时确保哨兵岭有人防守。",al={"为什么收集面罩","民兵为什么发布悬赏"}},{q="携带这些面罩的匪徒在哪里？",a="迪菲亚匪徒几乎遍布西部荒野的每个角落。他们占据废弃的农庄，在十字路口游荡，还在金海岸沿岸和月溪镇周围的山丘一带扎营。",al={"哪里能找到迪菲亚面罩","迪菲亚在西部荒野的位置"}},{q="交出面罩后，这些面罩会被用来做什么？",a="哨兵加里安将这些面罩作为匪徒已被击杀的凭证。它们帮助他追踪迪菲亚不断变化的战线，并判断民兵的作战行动对兄弟会在当地的人数有何影响。",al={"加里安用面罩做什么"}},{q="暴风城军队参与了这项悬赏吗？",a="没有。暴风城的军队大多已撤离西部荒野，转而处理其他内部问题。当地的防务由格里安·斯托曼和志愿组成的人民军承担。",al={"暴风城卫兵与西部荒野","暴风城是否援助哨兵岭"}}},fx={b62187e9={q="哨兵加里安为什么要收集迪菲亚的头巾？",a="哨兵加里安一直在追踪迪菲亚潜行者在西部荒野各处不断变化的动向。收集他们的步兵和杀手佩戴的红色皮质头巾，能让他确认这伙匪徒的活动，判断他们各处据点的实力，并在他们彻底攻占哨兵岭前削减其人数。",al={"哨兵加里安收集头巾的动机","哨兵加里安为何要头巾","为何收集红色皮质头巾"}},["868cbc1b"]={q="你要猎杀哪些人来取得这些头巾？",a="你要猎杀的是迪菲亚潜行者中游荡在西部荒野平原和废弃农庄的匪徒与密探。哨兵加里安发现，可以通过红色皮质头巾追踪这伙匪徒中的许多成员，而他们不断变化的势力前沿已随着劫掠、盗窃和勒索蔓延到整个地区。",al={"谁有红色头巾","迪菲亚头巾目标","谁掉落红色皮质头巾"}}},fp="20,176,20.374.0,30.375.0,44.189.0,21.194.0,64.210.0,52.170.0,52.188.0,46.166.0"}
P.entries["quest:1530"] = {n="水之召唤",s="水之先知伊斯伦派部落萨满祭司向南穿越贫瘠之地，寻找布瑞恩。在那里，他们将了解水净化与治愈的力量。",h="水之先知伊斯伦派部落萨满祭司向南穿越贫瘠之地，寻找布瑞恩。在那里，他们将了解水净化与治愈的力量。",kw={"贫瘠之地","布瑞恩","水之召唤","水之先知伊斯伦","野猪人","新生","萨满祭司","水之灵契"},ang={["class:Shaman"]="作为一名萨满祭司，与水沟通是你成长中的关键一步。它将水的治愈之力与大地的力量、火焰的威力融为一体。",["faction:Horde"]="作为部落的一员，你穿行于卡利姆多，掌握元素之力，并向诸灵致敬，正是它们赐予大酋长麾下的萨满祭司不可或缺的魔法。"},sec={{t="潮汐的教诲",b="水之先知伊斯伦教导说，水带来新生。流水能侵蚀岩石、洗净杂质、愈合血肉，但它的治愈之力取决于纯净程度。受到污染的水带来的不是生命，而是枯萎。每一位萨满祭司都必须理解这种平衡，才能寻求与水沟通。"},{t="尘土中的隐士",b="你向南远行，穿过干旱的贫瘠之地，寻找布瑞恩。野猪人的袭击侵扰着荒野，布瑞恩却独自生活，既无守卫，也无畏惧。她掌握着帮助你与水建立联系的知识与试炼。"}},faq={{q="水之先知伊斯伦是谁？",a="水之先知伊斯伦是一位萨满祭司导师，居于贫瘠之地沿海、商旅海岸以南。她引导部落萨满祭司完成与水之灵沟通的试炼。",al={"伊斯伦","水之先知","谁给予这个任务"}},{q="为何住在野猪人环伺的南贫瘠之地？",a="尽管不断遭受野猪人的侵扰，布瑞恩仍独自住在南方的荒野中。她知道，在外人看来，置身险境似乎十分愚蠢，但她不愿透露自己的理由，并以此考验你是否有足够的毅力找到她。",al={"布瑞恩为何住在那里","布瑞恩 野猪人","布瑞恩位置"}},{q="水之灵契 有什么用途？",a="灵契是一种用于仪式的混合药剂，能够改变萨满祭司的感知，让他们看见凡人肉眼无法看见的元素之灵，并与之交谈。",al={"灵契","水之灵契 用途","为何获取 水之灵契"}},{q="水为萨满祭司带来的核心教诲是什么？",a="水带来新生、净化与复苏。纯净的水能够治愈伤痛，但污水或死水却会带来腐朽与毁灭。",al={"水的教诲","水元素的含义","水与新生"}},{q="谁能踏上这段旅程？",a="已经证明自身的奉献精神，并与大地和火焰建立联系的部落萨满祭司，会被派去接受水之召唤的试炼。",al={"谁能接受水之召唤","水之召唤是否仅限部落"}},{q="寻找布瑞恩的路上有哪些威胁？",a="南贫瘠之地危机四伏，凶悍的野猪人部族守卫着荆棘密布的巢穴，野兽则猎杀那些远离十字路口或陶拉祖营地庇护的旅人。",al={"南贫瘠之地的危险","前往布瑞恩的路线"}}},fp="13,140,19.259.0,21.220.0,23.158.0,56.204.0,39.145.0,50.128.0,31.112.0,38.154.0"}
P.entries["quest:1531"] = {n="天空的召唤",s="在索尔的堡垒，希尔恩·火结派遣经验丰富的萨满祭司南下，寻求空气图腾。普拉特·白云将引导他们掌握萨满之道的最后一根元素支柱。",h="在索尔的堡垒，希尔恩·火结派遣经验丰富的萨满祭司南下，寻求空气图腾。普拉特·白云将引导他们掌握萨满之道的最后一根元素支柱。",kw={"空气图腾","天空的召唤","奥格瑞玛","普拉特·白云","希尔恩·火结","萨满祭司任务","千针石林","精神谷"},ang={["class:Shaman"]="获得空气图腾，是你初期萨满祭司修行的最终里程碑。它让你能够在呼唤大地、火焰与流水之灵的同时，也呼唤风之灵。",["faction:Horde"]="萨满传统将部落的各个种族联系在一起。散居在卡利姆多中部各地的长者与隐士，传承着这一传统的神圣习俗。"},sec={{t="南方的气息",b="赢得大地、火焰与流水眷顾的萨满祭司，如今已准备好驾驭四大元素中的最后一种——空气。在奥格瑞玛，巨魔训练师希尔恩·火结能看出弟子何时已完成初期训练，准备迈出奠定根基的最后一步。他让萨满祭司向南穿过贫瘠之地，再深入千针石林迷宫般的峡谷。"},{t="普拉特·白云的隐居之所",b="普拉特·白云在千针石林砂岩台地间的一处高崖洞穴中等候。这位隐士与伴侣过着宁静的生活，远离部落营地。她要求来访者心怀敬意，才肯透露风的奥秘。以应有的礼数拜见她，她便会传授凝聚空气图腾所需的知识，并给予相应的施法媒介，让萨满祭司的元素之环完整。"}},faq={{q="这个任务由谁开启？",a="希尔恩·火结是索尔的堡垒的一位巨魔萨满祭司训练师。当萨满祭司的历练达到要求时，他便会向符合条件者提供这个任务。",al={"任务给予者","哪里接取天空的召唤","希尔恩·火结"}},{q="在哪里能找到普拉特·白云？",a="普拉特·白云住在千针石林。从南贫瘠之地乘升降梯下去后，沿峡谷底部向东走，就能找到她的洞穴。",al={"普拉特·白云位置","寻找普拉特·白云","空气图腾非玩家角色"}},{q="空气图腾有什么用途？",a="空气图腾是萨满祭司获得的第四种，也是最后一种元素施法媒介。它让萨满祭司能够施放空气法术、召唤空气图腾，运用赋予迅捷、灵巧及驾驭风的力量。",al={"空气图腾用途","为何做空气图腾任务","空气图腾有什么用"}},{q="希尔恩·火结为什么派你去那么远的地方？",a="要掌握元素，就必须寻找专心与特定元素之灵沟通的导师。普拉特·白云熟知千针石林峡谷中变幻不定的风，因此是引导萨满祭司掌握空气元素的理想人选。",al={"为何去千针石林","为何找普拉特·白云"}},{q="需要先完成其他元素图腾任务吗？",a="是的。萨满祭司的元素训练有着严格的顺序：先是大地，然后是火焰和流水，最后才是空气。",al={"前置条件","图腾顺序","能否先做空气图腾"}},{q="其他城市也有这个任务的不同版本吗？",a="是的。包括雷霆崖在内，其他部落主城的萨满祭司训练师也会提供各自的指引，让你前往千针石林寻找普拉特·白云。",al={"雷霆崖空气图腾","幽暗城空气图腾"}}},fp="11,152,23.299.0,25.374.0,22.117.0,33.153.0,31.163.0,47.187.0,57.107.0,60.123.0"}
P.entries["quest:1532"] = {n="天空的召唤",s="萨尼斯·织火派遣经验丰富的部落萨满祭司从雷霆崖南下，前往千针石林寻找普拉特·白云。他们在那里寻求与风的交流，并获取引导疾风之力所需的空气图腾。",h="萨尼斯·织火派遣经验丰富的部落萨满祭司从雷霆崖南下，前往千针石林寻找普拉特·白云。他们在那里寻求与风的交流，并获取引导疾风之力所需的空气图腾。",kw={"空气图腾","天空的召唤","普拉特·白云","萨满祭司","千针石林","雷霆崖","萨尼斯·织火"},ang={["class:Shaman"]="身为萨满祭司，集齐所有元素图腾是一个转折点。空气图腾让你能够驾驭迅疾的气流和闪电萦绕的力量。",["faction:Horde"]="身为部落萨满祭司，将卡利姆多的狂野之风凝聚于神圣的图腾之中，能巩固部落的精神支柱。",["race:Tauren"]="身为Tauren，你将风尊为神圣的信使。风将Earth Mother的低语从莫高雷高耸的崖顶带向整片平原。"},sec={{t="低语之风",b="与大地、火焰和流水建立联系后，萨满祭司如今要面对最后一种元素：空气。在雷霆崖，萨尼斯·织火指引学徒接受考验，学会谦逊、专注和敬畏天空。风变幻无常，比他们已经掌握的元素更难驾驭。"},{t="南下朝圣",b="这条路向南延伸，穿过贫瘠之地，进入千针石林的峡谷。在遥远的东边，普拉特·白云住在崖壁上一处隐蔽的洞穴里，峡谷中的气流在此日夜呼啸。她会考验每位学徒是否准备妥当，然后才交予空气图腾，用来引导阵风、闪电和迅捷的风之灵。"}},faq={{q="谁会派我执行这个任务？",a="待你积累了足够的经验，雷霆崖的萨满祭司训练师萨尼斯·织火就会派你去与空气元素建立联系。",al={"任务给予者","谁开启天空的召唤","萨尼斯·织火"}},{q="普拉特·白云在哪里？",a="普拉特·白云住在千针石林遥远的东部，一处避风的洞穴中，就在贫瘠之地以南。",al={"普拉特·白云的位置","普拉特在哪里","寻找普拉特·白云"}},{q="为什么最后才寻求空气元素？",a="萨满祭司最后才寻求空气元素，因为气流变幻莫测，难以捉摸。按照传统，必须先掌握大地、火焰和流水，才能尝试与狂野的风建立联系。",al={"为什么最后寻求空气","萨满祭司空气图腾背景","元素顺序"}},{q="找到普拉特·白云后，我会得到什么？",a="普拉特·白云会给你空气图腾，借此凝聚你的元素魔法，并召唤风之灵提供支援。",al={"空气图腾奖励","普拉特给什么","天空的召唤任务奖励"}},{q="这个任务仅限牛头人吗？",a="任何已与大地、火焰和流水建立联系的部落萨满祭司，都可以从雷霆崖前往千针石林，获取空气图腾。",al={"兽人能做吗","是否仅限牛头人","部落萨满祭司空气任务"}},{q="完成这个任务后会怎样？",a="你抵达后，普拉特·白云会给你空气图腾，让你立刻就能召唤风系图腾。她还会提供进一步的训练与试炼，磨炼你与天空之间的联系。",al={"接下来做什么","天空的召唤之后","普拉特·白云的任务"}}},fp="11,209,20.279.0,18.310.0,27.120.0,33.105.0,38.167.0,47.124.0,34.131.0,40.185.0"}
P.entries["quest:1534"] = {n="水之召唤",s="一位萨满祭司从贫瘠之地前往星尘废墟，完成获取水之召唤之旅中最后的采集试炼。布瑞恩派这名学徒北上灰谷，从那里的古老喷泉中汲取纯净之水。",h="一位萨满祭司从贫瘠之地前往星尘废墟，完成获取水之召唤之旅中最后的采集试炼。布瑞恩派这名学徒北上灰谷，从那里的古老喷泉中汲取纯净之水。",kw={"灰谷","蓝色水囊","布瑞恩","水之召唤","水之先知伊斯伦","密斯特拉湖","星尘废墟","萨满祭司"},ang={["class:Shaman"]="身为萨满祭司，你穿越危险的边界，寻求平衡，采集缔结水之图腾所需的最后一份水之精华。",["faction:Horde"]="身为部落旅人，你踏入Kaldorei的古老领地，战歌氏族正为争夺木材，与敌对的暗夜精灵哨兵持续交战。",["race:Tauren"]="身为Tauren，你从卡利姆多中部干旱的故土出发，前往神话与长者歌谣中传颂的神圣林地。"},sec={{t="前往黎明森林",b="从贫瘠之地布瑞恩小屋下方的水池和塔伦米尔的纯净水井取水后，萨满祭司还需要最后一种精华。布瑞恩派这名学徒向北穿过干旱的平原，进入灰谷，那是一片被暗夜精灵视为圣地的古老森林。离开干旱的贫瘠之地，踏入灰谷浓密的树冠之下，水呈现出另一种形态。萨满祭司必须理解这种多样性，才能与元素和谐共处。"},{t="星尘废墟",b="越过波光粼粼的密斯特拉湖，在灰谷与石爪山脉之间的山口附近，便是星尘废墟。这处僻静的精灵圣地中，一座古老的喷泉静立于幽静的水域和古老的石块之间。桀骜不驯的元素之灵与自然之灵守护着废墟，敌视闯入者。萨满祭司必须小心行事，才能从喷泉中取水。"},{t="至纯之水",b="萨满祭司完成横跨卡利姆多与东部王国的朝圣之旅后，将装满水的蓝色水囊交给布瑞恩。她把纯净的泉水与贫瘠之地水塘及塔伦米尔的水样混合，制成一小瓶至纯之水。这瓶水将帮助萨满祭司为下一场试炼做好准备：通过先知水之先知伊斯伦，与水元素之灵沟通。"}},faq={{q="星尘废墟在哪里？",a="星尘废墟位于灰谷西南部。从贫瘠之地向北行进，再沿道路向西，经过密斯特拉湖，前往石爪山脉的山麓。",al={"星尘废墟位置","星尘废墟在哪","如何前往星尘废墟"}},{q="布瑞恩为什么需要精灵废墟中的水？",a="萨满祭司采集水元素不同形态的水，以便与水之灵沟通。星尘废墟的喷泉中蕴藏着古老的泉水，因魔法而纯净，未受贫瘠之地干旱荒芜的侵染，补齐了布瑞恩调配仪式用水所需的三种精华。",al={"为何需要灰谷的水","为何选择星尘废墟","采集星尘废墟泉水的原因"}},{q="星尘废墟周围有哪些威胁？",a="守护此地的野兽与自然之灵看守着废墟及附近的水域。领地意识强烈的水元素和灰谷本土的野兽会攻击扰乱林地的人。",al={"星尘废墟的敌人","星尘废墟危险吗","谁守护喷泉"}},{q="布瑞恩是谁，她为什么提供帮助？",a="布瑞恩是一位苦修的兽人萨满祭司，独自住在贫瘠之地南部的一间小屋里。作为协助水之先知伊斯伦的年长引路人，她会考验萨满祭司学徒的耐心、毅力以及对水的理解，然后才赐予他们水元素的祝福。",al={"布瑞恩是谁","布瑞恩的故事","布瑞恩的职责"}},{q="把这些水交给布瑞恩后会发生什么？",a="布瑞恩收到第三份水样后，会将这些水混合，制成一剂至纯之水。随后，她会派萨满祭司前往贫瘠之地东部海岸，寻找水之先知伊斯伦，在幻象中与元素沟通。",al={"水之召唤下一步","接下来会发生什么","见过布瑞恩后去哪"}},{q="灰谷对低等级的部落萨满祭司来说安全吗？",a="灰谷是一片争夺中的领土，暗夜精灵与部落在此交战。穿过南部树林的路线避开了阿斯特兰纳等主要暗夜精灵聚居地，但四处游荡的野兽、充满敌意的元素和联盟巡逻队都会威胁学徒的安全。",al={"灰谷危险吗","灰谷任务等级"}}},fp="13,142,31.404.0,21.361.0,27.363.1,40.179.0,45.275.0,48.167.0,36.249.0,48.212.1,46.259.0"}
P.entries["quest:1535"] = {n="水之召唤",s="布瑞恩派萨满祭司前往贫瘠之地采集水，用来调制sapta。试炼从她所在山丘下那处有人看守的水池开始，先取一份水样。在那里，水就意味着生存。",h="布瑞恩派萨满祭司前往贫瘠之地采集水，用来调制sapta。试炼从她所在山丘下那处有人看守的水池开始，先取一份水样。在那里，水就意味着生存。",kw={"贫瘠之地","布瑞恩","棕色水囊","水之召唤","野猪人","灵契","水塘"},ang={["class:Shaman"]="身为萨满祭司，你会懂得，水带来治疗与恢复，也会引发冲突和为生存而进行的绝望争斗。",["faction:Horde"]="身为部落的一员，你面临着掌控和分享贫瘠之地水源的挑战。在这里，各个部族和野兽不断争夺着每一股细流。"},sec={{t="荒漠中的一课",b="布瑞恩要求初入门的萨满祭司研习水的各种形态，然后才会赐予他们能与灵魂交流的 水之灵契。在干旱的贫瘠之地，水决定了生存与饥饿的差别。她要求他们留意水能带来什么：水流经之处，森林繁茂；水缺席之地，沙漠贫瘠；而生灵为了守护哪怕最不起眼的泉眼，也会痛下杀手。"},{t="野猪人的珍藏",b="当地的野猪人拼死守卫着布瑞恩所在山丘下的水塘。他们将每一处水池都视为无价的宝藏，每逢降雨便大肆欢宴。布瑞恩为他们囤积水源引发的暴力感到惋惜，但他们排外的贪婪和四分五裂的氏族也限制了他们的威胁。对于在平原上求生的其他种族而言，这维系着一种脆弱的平衡。"}},faq={{q="为布瑞恩采集水有什么用？",a="布瑞恩需要来自世界各处不同地方的纯净水样本，以调制仪式所用的 水之灵契。这种药剂能开启入门者的感知，让他们得以与水元素之灵交流。",al={"为什么要取水","布瑞恩取水任务","水之召唤任务第三步的目的"}},{q="为什么布瑞恩下方的水塘争夺如此激烈？",a="在干旱的贫瘠之地，水是最宝贵的资源。当地的野猪人将每一处水池都视为神圣的宝藏，任何人试图取水，都会遭到他们的猛烈攻击。",al={"野猪人为什么守着水源","野猪人水池","贫瘠之地水塘"}},{q="布瑞恩是谁？",a="布瑞恩是一位兽人萨满祭司，也是一名隐士，住在俯瞰南贫瘠之地的一间孤零零的小屋里。她对水和元素之灵的深刻理解，指引着部落的萨满祭司与它们沟通。",al={"布瑞恩是谁","布瑞恩贫瘠之地","布瑞恩非玩家角色"}},{q="交回装满水的棕色水囊后会发生什么？",a="你带着水塘的水样返回后，布瑞恩会派你前往更远的地方，从截然不同的地点采集纯净的水，其中就包括希尔斯布莱德丘陵塔伦米尔的水井。",al={"水之召唤后续","水塘取水之后","布瑞恩下一步"}},{q="布瑞恩为什么会提到野猪人的分裂？",a="布瑞恩认为，野猪人对领地的执着和氏族间的争斗，是他们苦难的根源。如果他们团结起来，不再为各处零散的泉眼争斗，就会对贫瘠之地的其他居民构成大得多的威胁。",al={"布瑞恩对野猪人的评价","野猪人为什么互相争斗"}},{q="什么是灵契？",a="灵契是一种神秘的药剂，由萨满祭司用采集来的材料和与元素相应的水调制而成。饮下它能拓展灵视，让凡人看见通常隐藏在视野之外的元素生物。",al={"什么是灵契","水之灵契 含义"}}},fp="13,151,22.346.0,20.311.0,50.198.0,58.171.0,13.182.0,56.196.1,49.202.0,16.203.0"}
P.entries["quest:1536"] = {n="水之召唤",s="你从贫瘠之地出发，前往被遗忘者控制的塔伦米尔，寻找一处纯净的泉水。这泉水将帮助布瑞恩配制水之灵契，而它能留存至今，也让人领悟到希望的意义。",h="你从贫瘠之地出发，前往被遗忘者控制的塔伦米尔，寻找一处纯净的泉水。这泉水将帮助布瑞恩配制水之灵契，而它能留存至今，也让人领悟到希望的意义。",kw={"贫瘠之地","布瑞恩","水之召唤","希尔斯布莱德","灵契","萨满祭司","塔伦米尔","萨尔","水囊"},ang={["class:Shaman"]="身为萨满祭司，你为取水而远行，学习在东部王国的苦难之地中寻求和谐与生机。",["faction:Horde"]="身为出生于卡利姆多的部落战士或萨满祭司，你来到塔伦米尔，在对抗希尔斯布莱德人类守军的前线上，见到关系尚不稳固的新盟友被遗忘者。",["race:Orc"]="身为兽人，你可以回想萨尔留下的生存与力量的传承，以及为你们的自由所付出的沉重代价。"},sec={{t="奇迹之泉",b="布瑞恩派你渡海前往希尔斯布莱德丘陵的塔伦米尔，取水配制水之灵契。人类抵抗军和新近结盟的被遗忘者环绕着这座城镇，但镇中央的小井依然涌出纯净的泉水。在布瑞恩看来，这眼泉水是一片污秽之地中留存的圣洁净土。"},{t="黑暗中的坚守",b="在布瑞恩眼中，塔伦米尔的纯净井水不仅仅是一种材料。她将泉水的坚韧比作大酋长萨尔，他历经苦难、囚禁与悲伤，最终成为兽人一族的领袖。萨尔给部落带来了希望，而这口井则表明，即使经历悲剧与腐化，生命与纯净依然能够留存。"}},faq={{q="在哪里采集水样？",a="你从塔伦米尔镇中央的水井中采集水样，这座位于希尔斯布莱德丘陵的古老人类定居点如今由被遗忘者占据。",al={"塔伦米尔的水","水井在哪里","水之召唤水井位置"}},{q="布瑞恩为什么派你去那么远的地方取水？",a="布瑞恩需要不同的水之精华来调制水之灵契，让萨满祭司得以感知元素之灵。她先前前往希尔斯布莱德时发现了这眼泉水，认为它在被遗忘者的腐朽之中依然保持纯净，既蕴含强大的力量，也能给人启迪。",al={"为什么去塔伦米尔","为什么要希尔斯布莱德的水","布瑞恩为什么要这种水"}},{q="塔伦米尔是什么地方？",a="塔伦米尔是希尔斯布莱德丘陵北部的一座人类小镇，如今由希尔瓦娜斯·风行者麾下的被遗忘者占据，是部落对抗当地人类军队的坚固前哨。",al={"塔伦米尔历史","谁占据塔伦米尔"}},{q="这个任务与萨尔有什么联系？",a="布瑞恩将纯净的水井比作大酋长萨尔。萨尔虽曾遭受奴役与苦难，却仍保有领导新部落的力量与远见，就如这口井在瘟疫与死亡之中依然保持清冽。",al={"布瑞恩谈论萨尔的对话","与萨尔的联系"}},{q="交回装满水的水囊后会发生什么？",a="布瑞恩收下装满水的红色水囊，告诉你她还需要一份不同的水样，才能完成为你配制水之灵契所需的试剂混合物。",al={"水之召唤下一步","塔伦米尔取水之后"}},{q="为什么这口井的纯净被认为非同寻常？",a="洛丹伦的大部分土地都被天灾军团的亡灵瘟疫玷污，而被遗忘者的定居点很少让人联想到清泉。塔伦米尔中央的水井仍然涌出纯净的水，是一处罕见的未受腐化的遗存。",al={"塔伦米尔的水为什么纯净","被遗忘者污染的水井"}}},fp="13,150,19.308.0,21.300.0,36.136.0,46.235.0,20.167.0,38.198.0,50.146.0,44.215.0"}
P.entries["quest:154"] = {n="归还梳子",s="伊瓦夫人在夜色镇等着接收盲眼玛丽退回的梳子。梳子上的幽灵发丝可以纺成幽灵的发丝。",h="伊瓦夫人在夜色镇等着接收盲眼玛丽退回的梳子。梳子上的幽灵发丝可以纺成幽灵的发丝。",kw={"盲眼玛丽","夜色镇","暮色森林","幽灵发丝","幽灵的发丝","伊瓦夫人","归还梳子"},ang={["class:Priest"]="盲眼玛丽对自身的憎恶，揭示了那些因悲伤而非恶意被束缚在凡世的灵魂所承受的折磨。",["faction:Alliance"]="夜色镇与玛丽的住处之间，道路阴森，旅人沿途可见笼罩暮色森林的衰败景象。",["profession:Tailoring"]="纺制幽灵的发丝，展现了如何收集暮色森林的幽灵材料，并将其梳理、纺织成结实耐用的超自然织物。"},sec={{t="苦涩的倒影",b="盲眼玛丽在夜色镇南边的一间小屋里等着，为自己的死亡和死后发生的变化而悲伤。伊瓦夫人的梳子让她想起生前梳妆的情景，更添哀伤。她眼中的自己只是一个幽魂，一个失去了生前风姿的怪物，她确信再也不会有人爱她。惊恐之下，她把梳子连同缠在梳齿上的幽灵发丝一并塞回你手中。"},{t="织就灵异之物",b="伊瓦夫人在夜色镇等着接收梳子，深知这趟差事令人难受。梳子上的幽灵发丝正是这位占卜师所需的材料，能让她纺出一卷幽灵的发丝。完成这项精细的工作后，她会付钱买下剩余的发丝。"}},faq={{q="为什么盲眼玛丽会对梳子感到惊恐？",a="梳子让盲眼玛丽想起了生前的生活与美貌。看到自己如今成了枯槁的幽魂，她悲痛欲绝，拒绝收下梳子，哀叹自己已成为无人珍爱的怪物。",al={"玛丽为何难过","盲眼玛丽为何尖叫","玛丽对梳子的反应"}},{q="伊瓦夫人如何处理梳子上的头发？",a="伊瓦夫人将梳子上的头发织成幽灵的发丝，这种神秘的丝线可以束缚邪灵，也能将生命缝入无生命的物体。",al={"为何需要幽灵发丝","艾瓦如何使用幽灵发丝","伊瓦夫人的丝线"}},{q="盲眼玛丽在哪里？",a="盲眼玛丽出没于暮色森林夜色镇南边的一间破旧小屋，那里靠近静谧花园墓场。",al={"盲眼玛丽在哪里","盲眼玛丽的位置"}},{q="伊瓦夫人是谁？",a="伊瓦夫人是一位住在夜色镇的人类秘术师和占卜师。她为那些面对暮色森林种种危险的人占卜命运，提供隐晦的指引，以及魔法饰品和施法材料。",al={"伊瓦夫人是谁","艾瓦 夜色镇"}},{q="将梳子交还给伊瓦夫人之后会发生什么？",a="收下梳子并备好幽灵的发丝后，伊瓦夫人会请你将它送给亚伯克隆比，那位住在乌鸦岭墓地附近的隐士。",al={"接下来做什么","归还梳子后续任务"}},{q="为什么伊瓦夫人会在任务完成时给你钱币？",a="伊瓦夫人说，梳子上的幽灵发丝纺成一卷绰绰有余。她留下了多余的发丝，并为此付给你几枚钱币。",al={"为何获得钱币","多余发丝换钱"}}},fp="15,124,19.349.0,24.207.0,50.200.0,50.145.0,28.101.0,18.183.0,52.145.1,51.133.0"}
P.entries["quest:155"] = {n="迪菲亚兄弟会",s="在西部荒野，人民军正在寻找迪菲亚潜行者的秘密基地。一名被俘的匪徒愿意带你穿过月溪镇，前往艾德温·范克里夫的腹地，以换取保护。",h="在西部荒野，人民军正在寻找迪菲亚潜行者的秘密基地。一名被俘的匪徒愿意带你穿过月溪镇，前往艾德温·范克里夫的腹地，以换取保护。",kw={"死亡矿井","迪菲亚叛徒","艾德温·范克里夫","护送","格里安·斯托曼","月溪镇","人民军","哨兵岭","西部荒野"},ang={["class:Rogue"]="身为潜行者，你深知背叛在地下犯罪世界中的代价，违背誓言的人会招来匕首。",["faction:Alliance"]="对于处境艰难的人民军而言，找到藏身处是一次重大的军事突破，也是他们首次真正有机会给予西部荒野的犯罪叛乱势力决定性打击。",["race:Human"]="身为暴风城的人类，你看到月溪镇已陷入无法无天的境地，被昔日的 Stonemasons 占据。这表明，自第三次大战以来，王国的分裂已何其严重。"},sec={{t="叛徒的交易",b="迪菲亚叛徒害怕遭到处决，或被昔日的兄弟暗杀。于是，他与人民军达成交易：护送他安全穿过敌对地区，他就透露艾德温·范克里夫及其匪首的藏身之处。这个盗贼组织会让泄密者永远闭嘴，因此这名叛徒需要沿途的武装保护。"},{t="穿过月溪镇的道路",b="叛徒带你从哨兵岭向西南行进，进入被兄弟会占据的月溪镇。他带你经过荒废的镇中心广场和喷泉，惹怒了在废墟中巡逻的匪徒、劫掠者和拦路强盗。随后，他带你来到月溪镇下方庞大的死亡矿井入口，范克里夫已在那里筑起一座坚固的地下要塞。"}},faq={{q="迪菲亚叛徒是谁？",a="迪菲亚叛徒曾是兄弟会的一员，后来成了格里安·斯托曼和人民军的线人。他害怕死在昔日同伙手中，于是用艾德温·范克里夫地下堡垒的位置，换取护送他前往安全地带。",al={"叛徒是谁","迪菲亚叛徒身份","迪菲亚 内鬼"}},{q="叛徒会带你去哪里？",a="他带你从哨兵岭向西南进入月溪镇，经过破败的镇中心广场和喷泉，抵达镇子下方的死亡矿井入口。",al={"迪菲亚藏身处 在哪里","叛徒路线","他去哪里"}},{q="格里安·斯托曼为何需要这份情报？",a="人民军一直在西部荒野各地与拦路强盗作战，却不知道艾德温·范克里夫在哪里指挥行动。找到他地下巢穴的入口，就能让民兵有明确的目标，直击叛乱的核心。",al={"为何护送叛徒","斯托曼 的目的","为何寻找藏身处"}},{q="月溪镇为何到处都是迪菲亚？",a="月溪镇曾是繁荣的农业中心，但暴风城王国疏于治理，匪徒便趁虚而入。居民们弃镇而去，迪菲亚潜行者占据了空置的建筑，将其作为守卫死亡矿井入口的地面防线。",al={"月溪镇为何有 迪菲亚","月溪镇被占领","谁控制月溪镇"}},{q="发现藏身处之后会发生什么？",a="叛徒指出死亡矿井的入口后，你会向哨兵岭的格里安·斯托曼报告。有了范克里夫藏身位置的确凿情报，民兵开始准备直接进攻地下巢穴。",al={"接下来做什么","护送 迪菲亚 之后","任务进程"}},{q="兄弟会为何想要叛徒死？",a="迪菲亚依靠隐秘行事，藏身地道之中，指挥遍及暴风城领土的行动。叛徒若透露他们行动中枢的入口，就可能让整个阴谋败露。",al={"为何杀死叛徒","迪菲亚 攻击叛徒"}}},fx={["0ac3b75c"]={q="迪菲亚叛徒为什么愿意为你带路？",a="这名叛徒走投无路，与人民军达成了一笔交易。他背弃了艾德温·范克里夫和兄弟会，知道自己已被盯上，昔日的同伴都想取他性命。直接带你找到秘密藏身处，是他仅剩的筹码，能换来格里安·斯托曼的保护，让自己活下去并重获自由。",al={"为什么帮助迪菲亚叛徒","迪菲亚叛徒的动机","叛徒为什么带路"}},ef72c66d={q="格里安·斯托曼为什么派你护送叛徒，而不是派自己的卫兵？",a="人民军光是守住哨兵岭、抵御西部荒野各处的匪徒袭击，就已经捉襟见肘。暴风城拒绝派遣皇家部队援助这一地区，斯托曼既没有训练有素的士兵，也没有多余的卫兵，无法组织一支能安全穿越敌境的护送队伍。将任务交给有能力独立行动的冒险者，是他唯一可行的选择。",al={"为什么不派民兵卫兵","为什么护送叛徒","斯托曼为什么需要我"}}},fp="22,206,20.335.0,26.377.1,26.261.0,32.143.0,49.224.0,38.270.0,44.197.1,47.210.0"}
P.entries["quest:156"] = {n="收集腐败之花",s="在暮色森林，旅店老板斯密茨需要腐败之花来酿制僵尸酒。这些植物生长在墓地中恐怖骸骨和骷髅魔的头骨内。",h="在暮色森林，旅店老板斯密茨需要腐败之花来酿制僵尸酒。这些植物生长在墓地中恐怖骸骨和骷髅魔的头骨内。",kw={"夜色镇","守夜人","乌鸦岭墓地","腐败之花","骷髅魔","骷髅恐魔","旅店老板斯密茨","静谧花园墓场","僵尸酒"},ang={["faction:Alliance"]="身为联盟冒险者，在暮色森林的墓地中猎杀亡灵，能减轻守夜人每日为守住夜色镇而战的压力。",["profession:Herbalism"]="腐败之花是扎根于通灵术造成的腐朽与复生骸骨中的黑暗植物，与在肥沃土壤和阳光下茁壮生长的普通草药不同。"},sec={{t="古怪的原料",b="旅店老板斯密茨有时会在血鸦旅店酿制一种奇怪的饮料。他的僵尸酒配方需要腐败之花，这种植物扎根于复生骷髅空空的头骨内。斯密茨不愿接近亡灵，因此由路过的雇佣兵替他采集这些花。"},{t="清剿墓地",b="腐败之花生长在静谧花园墓场杂草丛生的墓地，以及乌鸦岭墓地各处的恐怖骸骨和骷髅魔身上。守夜人民兵疲于应对林间悄然蔓延的恐怖威胁，人手捉襟见肘。斯密茨会向指挥官阿尔泰娅·埃伯洛克称赞那些猎杀亡灵的冒险者，他们帮助削减了威胁夜色镇的躁动亡灵的数量。"}},faq={{q="什么是腐败之花？",a="腐败之花是一种在黑暗魔法与腐朽中生长的污秽植物。在暮色森林，它们从复生的恐怖骸骨和骷髅魔的头骨内萌发。",al={"腐败之花","什么是腐败之花","腐败之花的来源"}},{q="旅店老板斯密茨为什么需要腐败之花？",a="旅店老板斯密茨用腐败之花酿制僵尸酒，这是当地某些顾客点名要喝的饮料。",al={"斯密茨为何需要腐败之花","僵尸酒原料","斯密茨的饮料"}},{q="在哪里能找到长着这些花的骷髅？",a="长着腐败之花的恐怖骸骨和骷髅魔在暮色森林的墓地中游荡，尤其是夜色镇附近的静谧花园墓场和西边的乌鸦岭墓地。",al={"恐怖骸骨在哪里","腐败之花位置","静谧花园墓场的骷髅"}},{q="这项任务有助于保卫夜色镇吗？",a="是的。夜色镇依靠守夜人抵御持续不断的亡灵袭击，才得以存续。为采集腐败之花而猎杀骷髅，可以减少威胁镇子的怪物，也能帮助指挥官阿尔泰娅·埃伯洛克。",al={"帮助守夜人","阿尔泰娅·埃伯洛克猎杀骷髅"}},{q="交付腐败之花后，接下来要做什么？",a="收到腐败之花并酿好僵尸酒后，斯密茨会请你把这杯饮料送给亚伯克隆比，他是住在乌鸦岭墓地附近的一位古怪隐士。",al={"腐败之花后续任务","送饮料后续任务"}},{q="僵尸酒是夜色镇供应的普通饮料吗？",a="不是。血鸦旅店通常供应当地的饮食。只有收到古怪的点单时，斯密茨才会调制僵尸酒，这种奇怪的饮料含有坏死原料。",al={"僵尸酒是普通饮料吗","血鸦旅店的饮料"}}},fp="19,149,20.256.0,22.343.0,22.149.0,45.109.0,56.190.0,45.188.0,46.159.1,54.172.0"}
P.entries["quest:1560"] = {n="图加的任务",s="图加是一只迷路的海龟，妻子托尔塔让他出去找晚餐，他却不知在哪里走错了路。图加请你带他回到托尔塔身边，她正在热砂港南边不远处等着。",h="图加是一只迷路的海龟，妻子托尔塔让他出去找晚餐，他却不知在哪里走错了路。图加请你带他回到托尔塔身边，她正在热砂港南边不远处等着。",kw={"热砂港","塔纳利斯","灌木谷","图加","托尔塔","海龟"},sec={{t="迷路的旅者",b="图加在灌木谷附近一艘坠毁的地精飞艇旁徘徊。托尔塔让图加出去找晚餐，他却不知在哪里走错了路，彻底迷失了方向。图加请你带路回去。"},{t="横穿沙漠",b="托尔塔在热砂港南边不远处等着，那里位于塔纳利斯的另一头，因此这一路几乎要横穿整个地区。"},{t="妻子的迎接",b="托尔塔对图加独自找不到回家的路并不意外，还让图加下海带些食物回来。"}},faq={{q="图加是谁？",a="塔纳利斯一只迷路的海龟，需要帮助才能找到回妻子身边的路。",al={"图加是谁","图加 海龟","塔纳利斯的海龟是谁"}},{q="托尔塔是谁？",a="图加的妻子，在热砂港南边不远处等着。",al={"托尔塔是谁","托尔塔在哪里","托尔塔位置"}},{q="图加为什么会在沙漠中迷路？",a="托尔塔让图加出去找晚餐，他却走错了路，迷失了方向。",al={"图加为什么迷路","图加发生了什么事","图加的背景故事"}},{q="最初在哪里能找到图加？",a="在塔纳利斯灌木谷附近，一艘坠毁的地精飞艇旁。",al={"图加起始位置","图加的任务在哪里开始","寻找图加"}}},fp="13,95,15.203.0,15.134.0,16.124.1,13.82.0,13.63.0,32.65.0,32.80.0"}
P.entries["quest:157"] = {n="幽灵的发丝",s="伊瓦夫人将幽灵的发丝从夜色镇送出，穿过暮色森林，交给乌鸦岭墓地附近的亚伯克隆比。这位隐士说，他需要用它来保护小屋，抵御不得安息的幽灵。",h="伊瓦夫人将幽灵的发丝从夜色镇送出，穿过暮色森林，交给乌鸦岭墓地附近的亚伯克隆比。这位隐士说，他需要用它来保护小屋，抵御不得安息的幽灵。",kw={"亚伯克隆比","夜色镇","递送线轴","暮色森林","幽灵的发丝","伊瓦夫人","乌鸦岭","乌鸦岭墓地","僵尸酒"},ang={["class:Priest"]="身为牧师，你通常会借助Light的神圣仪式，保护居所免受不得安息的亡灵侵扰。亚伯克隆比却依靠死者遗物织成的丝线，这指向了一条更黑暗的道路。",["faction:Alliance"]="身为联盟旅人，你从夜色镇出发，穿过危险的西部林地，将援助送到一位离群索居的隐士手中，而守夜人正竭力守卫边境。",["profession:Tailoring"]="将幽灵的头发纺成可用的丝线，是把针线手艺与民间通灵术结合在一起。这些丝线能缝合超越物质领域的存在。"},sec={{t="穿行黑暗",b="伊瓦夫人交给你一卷幽灵的发丝，是用从幽灵盲眼玛丽那里收集的头发纺成的。你带着它向西穿过暮色森林，那里到处游荡着蜘蛛和亡灵。亚伯克隆比在乌鸦岭墓地正北方的破旧小屋里等候。"},{t="生死之线",b="亚伯克隆比说，他会将幽灵的发丝布在窗户和门框四周，阻挡乌鸦岭那些哀嚎的亡灵。伊瓦夫人说，幽灵的发丝用途很多，既能束缚恶灵，也能为死物和没有生命的物质缝入一丝生命的假象。亚伯克隆比欣喜地收下这卷线，开始施展他隐秘的技艺。"}},faq={{q="幽灵的发丝是什么？",a="幽灵的发丝是伊瓦夫人在夜色镇用从幽灵盲眼玛丽那里收集的头发纺成的一卷魔法丝线。她说，它能束缚幽灵，也能将生命缝入没有生命的物体。",al={"幽灵头发","丝线是什么","幽灵的发丝"}},{q="亚伯克隆比是谁？",a="亚伯克隆比是一位隐居的老人，住在乌鸦岭墓地正北方一间孤零零的小屋里。他看上去虚弱无害，自称害怕家附近的亡灵。",al={"隐士","亚伯克隆比是谁","小屋里的人"}},{q="亚伯克隆比声称需要这些丝线做什么？",a="亚伯克隆比说，他会沿着窗户和门口拉起幽灵的发丝，抵御游荡在暮色森林的食尸鬼和幽灵。",al={"为何需要丝线","亚伯克隆比的借口","抵御幽灵"}},{q="亚伯克隆比在哪里？",a="亚伯克隆比住在乌鸦岭墓地主要墓区以北一间偏僻的木屋里，就在穿过暮色森林西部的道路旁。",al={"亚伯克隆比的位置","小屋在哪里","隐士的小屋"}},{q="把丝线交给亚伯克隆比后会发生什么？",a="亚伯克隆比收到丝线后，会给你报酬，又抱怨自己还有其他急需的东西。他派旅人去寻找稀奇古怪的炼金材料，比如僵尸酒。",al={"下一个任务","后续是什么","交付丝线之后"}},{q="伊瓦夫人知道亚伯克隆比在做什么吗？",a="伊瓦夫人并未指责亚伯克隆比图谋不轨。她提到幽灵的发丝能将生命缝入没有生命的物体，表明她知道它在通灵术上的潜力，却仍毫无异议地满足了他的请求。",al={"伊瓦夫人是否知情","伊瓦夫人是否同谋","伊瓦夫人的警告"}}},fp="18,179,22.245.0,25.326.1,26.180.0,19.162.0,47.133.0,29.134.0,52.166.0,47.215.0"}
P.entries["quest:1578"] = {n="前线的补给",s="在洛克莫丹，穴居人的袭击威胁着巡山人的防线，他们急需新的武器。托姆斯·深炉派遣锻造学徒向东前往，为他们提供补给。",h="在洛克莫丹，穴居人的袭击威胁着巡山人的防线，他们急需新的武器。托姆斯·深炉派遣锻造学徒向东前往，为他们提供补给。",kw={"锻造","铜斧","铜质链甲腰带","铁炉堡","洛克莫丹","供应前线","塞尔萨玛","索瓦尔德·深炉","托姆斯·深炉","穴居人"},ang={["faction:Alliance"]="作为联盟的一员，你帮助守卫卡兹莫丹的边境道路，这些道路连接着铁炉堡、暴风城和联盟在南方的行动区域。",["profession:Blacksmithing"]="作为一名铁匠，你通过制作可靠的军用铜制武器和护甲来证明自己的技艺。",["race:Dwarf"]="作为一名矮人，你凭借自己的手艺，与手持火枪的Mountaineers一同保卫洛克莫丹。"},sec={{t="武装巡山人",b="挖掘工作揭开了边境另一侧各处的遗迹和洞穴。如今，穴居人毫无预兆地袭击巡山人。他们的防线需要新的刀剑、腰带和配件，才能抵挡这些攻击。"},{t="深炉的亲缘",b="托姆斯派遣学徒东行，老练的铁匠则留在铁炉堡的城内熔炉旁。他的同僚索瓦尔德·深炉在南部哨塔管理着一座战地军械库。在那里，结实的铜斧和铜质链甲腰带能证明铁匠的手艺可靠，并让他们学到更高深的锻造技艺。"}},faq={{q="谁提供这个任务，有什么要求？",a="托姆斯·深炉是铁炉堡大锻炉的一名铁匠，他将这项工作交给锻造技能至少达到三十的学徒。你需要制作六把铜斧和六条铜质链甲腰带。",al={"谁提供供应前线","任务起始者","锻造任务要求"}},{q="索瓦尔德·深炉在哪里？",a="索瓦尔德·深炉就在洛克莫丹的南部哨塔内。沿着大路向南，经过塞尔萨玛，朝荒芜之地边境前进。哨塔就矗立在山口旁。",al={"索瓦尔德在哪里","索瓦尔德位置","洛克莫丹南部哨塔"}},{q="为什么巡山人需要这么多铜制补给？",a="洛克莫丹的巡山人不断与凶暴的穴居人交战。战斗很快就会让他们的装备出现缺口、变钝或损坏，因此他们需要源源不断的基础武器和链甲补给。",al={"为什么需要斧头","铜的用途"}},{q="索瓦尔德与托姆斯是什么关系？",a="托姆斯称索瓦尔德为自己的同僚。他们同属深炉氏族，将铁炉堡的锻造力量与前线的防御联系在一起。",al={"索瓦尔德和托姆斯有亲缘关系吗","托姆斯的同僚"}},{q="索瓦尔德会提供什么奖励？",a="索瓦尔德会提供新护甲的设计图，感谢你缓解南部哨塔的补给压力。",al={"任务奖励","索瓦尔德传授什么"}},{q="为什么穴居人如今在洛克莫丹造成了如此严重的麻烦？",a="矮人的挖掘工作打开了卡兹莫丹各处的地下密室和洞穴。这些工作意外惊醒并挖出了成群凶暴的穴居人。如今，它们威胁着附近的定居点和哨塔。",al={"穴居人为何袭击","洛克莫丹穴居人问题"}}},fx={["0062256f"]={q="托姆斯·深炉为什么需要更多铜斧？",a="在洛克莫丹作战的铁炉堡巡山人正与穴居人进行无休止的交战。接连不断的战斗让武器很快损坏，索瓦尔德·深炉急需新的军备，确保守军能够稳住前线。",al={"铜斧有什么用","补给前线铜斧的用途","为什么需要铜斧"}},c19cb0c2={q="索瓦尔德为什么需要铜质链甲腰带？",a="穴居人的攻势凶猛而且毫不停歇，巡山人修补护具的速度几乎赶不上损耗。索瓦尔德依赖源源不断送来的耐用护甲，例如铜质链甲腰带，来确保南部隘口的矮人哨兵得到充分保护。",al={"铜质链甲腰带有什么用","铜质链甲腰带的用途","为什么需要铜质链甲腰带"}},f96d051f={q="托姆斯·深炉为什么请冒险者帮忙补给前线？",a="索瓦尔德忙于前线的修理工作，已经应接不暇，而托姆斯也无法离开自己在铁炉堡的铁砧。作为一名初出茅庐的铁匠，锻造装备并穿过隧道将其送往东边，既能考验你的手艺，也能直接减轻山地守卫的压力。",al={"补给前线为什么选我","托姆斯为什么需要我","为什么派冒险者去找索瓦尔德"}}},fp="19,147,23.192.0,21.286.0,43.193.0,36.178.0,53.197.0,36.131.0,40.103.0,57.210.0"}
P.entries["quest:1579"] = {n="小齿轮",s="在奥伯丁，维兹班恩·曲针需要找回他丢失的小齿轮。这位侏儒发明家从铁炉堡乘船而来，途中把一箱五金零件扔进了海里，垂钓者可以沿着黑海岸的海岸寻找。",h="在奥伯丁，维兹班恩·曲针需要找回他丢失的小齿轮。这位侏儒发明家从铁炉堡乘船而来，途中把一箱五金零件扔进了海里，垂钓者可以沿着黑海岸的海岸寻找。",kw={"奥伯丁","黑海岸","导电器","钓鱼","小齿轮","铁炉堡","维兹班恩·曲针"},ang={["profession:Engineering"]="身为工程师，你知道，校准精密装置时偏偏缺了某个不常见的零件，是多么令人抓狂。",["race:Gnome"]="身为侏儒，你熟知工匠们那种闲不住的古怪性情。维兹班恩一边摆弄精密组件，一边酗酒，或许连你都会看得心惊。",["race:NightElf"]="身为暗夜精灵，你知道黑海岸的森林宁静而神圣。对奥伯丁的哨兵来说，一个吵闹又宿醉未醒的侏儒发明家，实在是个古怪的景象。"},sec={{t="静谧港湾里的纷乱思绪",b="维兹班恩·曲针从铁炉堡出发，横渡无尽之海，来到黑海岸寻求清静。这位侏儒发明家在航途中喝得太多。他醉醺醺地俯身探出船舷时，把一箱名为小齿轮的专用金属零件掉进了奥伯丁附近的水里。"},{t="调校齿轮",b="维兹班恩说，小齿轮是不可或缺的精密工具。没有它们，他就无法妥善调校自己的齿轮，也无法继续进行精细的机械修整。他不愿亲自涉入冰冷的海水，便请当地的垂钓者沿着黑海岸的岸边抛竿，钓起散落的零件。"}},faq={{q="小齿轮是什么？",a="小齿轮是侏儒制造的小型机械紧固件和组件。维兹班恩·曲针说，他需要用它们来调校自己的栓钉。",al={"小齿轮是什么","小齿轮用途","小齿轮物品"}},{q="小齿轮是怎么掉进海里的？",a="维兹班恩·曲针从东部王国乘船前往卡利姆多时喝得太多。他在船上醉酒时，把自己的补给箱掉进了黑海岸附近的海里。",al={"他怎么弄丢的","为什么在水里","为什么要钓小齿轮"}},{q="维兹班恩·曲针为什么在奥伯丁，而不是铁炉堡？",a="维兹班恩为了清静而来到奥伯丁。铁炉堡里接连不断的叮当声和喧闹的工坊令他不堪其扰，尤其是在他宿醉未消的时候。",al={"维兹班恩为什么在奥伯丁","维兹班恩为什么离开铁炉堡"}},{q="在哪里能钓起丢失的小齿轮？",a="垂钓者可以在奥伯丁附近黑海岸沿岸的开阔海水中钓到小齿轮。普通抛竿也能钓到它们，并非只有鱼群里才有。",al={"哪里能钓小齿轮","小齿轮位置"}},{q="找回小齿轮后会发生什么？",a="维兹班恩拿回小齿轮来调校自己的栓钉后，又说他还把导电器丢在了黑海岸的河流和湖泊里。那些也得钓上来。",al={"找回小齿轮后做什么","小齿轮后续任务"}},{q="维兹班恩为什么需要冒险者帮忙，而不自己去找？",a="维兹班恩宿醉后头痛欲裂，也没有海钓装备。他待在奥伯丁的码头上，不肯下水，把打捞的活留给任何带着鱼竿的人。",al={"维兹班恩为什么不能自己找","维兹班恩为什么不钓鱼"}}},fp="12,183,33.269.0,23.273.0,22.124.0,43.162.0,61.144.0,45.150.0,47.159.1,69.147.0"}
P.entries["quest:158"] = {n="僵尸酒",s="亚伯克隆比住在暮色森林一间偏僻的小屋里，差遣旅人前往夜色镇取回僵尸酒。他说，夜里的寒气让他浑身冰冷。",h="亚伯克隆比住在暮色森林一间偏僻的小屋里，差遣旅人前往夜色镇取回僵尸酒。他说，夜里的寒气让他浑身冰冷。",kw={"亚伯克隆比","夜色镇","暮色森林","烈酒","血鸦旅店","旅店老板斯密茨","僵尸酒"},ang={["faction:Alliance"]="身为联盟冒险者，你可能会沿着暮色森林危机四伏的道路，为那些古怪的隐士传递消息，同时支援饱受战火侵扰的夜色镇前哨。"},sec={{t="驱寒的请求",b="亚伯克隆比独自住在暮色森林阴暗的林地中，与恐怖之物为邻，时常请心怀同情的旅人替他办些古怪的差事。他说，渐浓的暮色正在夺走他的温暖与活力，随后请你向东前往夜色镇。在血鸦旅店，旅店老板斯密茨出售亚伯克隆比想要的烈酒。这酒有个不祥的名字，叫作僵尸酒，亚伯克隆比说它能让自己的血液重新燃烧起来。"},{t="在血鸦旅店",b="旅店老板斯密茨在夜色镇的旅店里招待疲惫的卫兵和惊恐的镇民，但很少有人点僵尸酒。这酒以猛烈得危险的酒劲闻名，斯密茨也认得这种酒。在这片遭受亡灵围困的土地上，亚伯克隆比对如此阴森的酒情有独钟，难免让人暗自诧异。"}},faq={{q="僵尸酒是什么？",a="僵尸酒是一种名字阴森、酒劲极强的烈酒，由夜色镇血鸦旅店的旅店老板斯密茨出售。普通客人很少点这种酒。",al={"僵尸酒饮品","是什么烈酒","僵尸酒背景故事"}},{q="谁派你去取僵尸酒？",a="隐士亚伯克隆比派你去取僵尸酒。他独自住在暮色森林西部的一间小屋里，说这种酒能暖暖他冰冷的身子。",al={"谁发布僵尸酒任务","亚伯克隆比任务饮品","隐士求酒"}},{q="在哪里交任务？",a="你要在血鸦旅店内与旅店老板斯密茨交谈，这家旅店位于暮色森林东部的夜色镇中心。",al={"斯密茨在哪里","交付僵尸酒","斯密茨位置"}},{q="亚伯克隆比为什么想要这种酒？",a="亚伯克隆比说，暮色森林阴沉昏暗的夜晚让他瑟瑟发抖，他需要这种烈酒来温暖自己的血液。",al={"亚伯克隆比为什么需要酒","亚伯克隆比怕冷","他为什么喝僵尸酒"}},{q="旅店老板斯密茨对有人点这种酒感到惊讶吗？",a="是的。斯密茨说，僵尸酒的酒劲格外猛烈，他的常客很少点这种酒。",al={"斯密茨的反应","斯密茨有僵尸酒吗","斯密茨对话"}},{q="这个任务需要与怪物战斗吗？",a="不需要。你沿着道路从亚伯克隆比僻静的小屋前往夜色镇，与旅店老板斯密茨交谈。暮色森林的道路上也有游荡的野兽和亡灵，危机四伏。",al={"僵尸酒战斗","僵尸酒危险吗","僵尸酒怪物"}}},fp="12,137,16.399.0,20.309.0,21.170.0,36.146.0,31.112.0,29.122.0,44.101.0,46.180.0"}
P.entries["quest:1580"] = {n="导电器",s="在黑海岸，维兹班恩·曲针请垂钓者找回他遗失的 导电器。他的爆炸诱饵鸭出了意外，原型零件也随之掉进了淡水溪流。",h="在黑海岸，维兹班恩·曲针请垂钓者找回他遗失的 导电器。他的爆炸诱饵鸭出了意外，原型零件也随之掉进了淡水溪流。",kw={"奥伯丁","壁泉河","黑海岸","诱饵鸭","导电器","钓鱼","急弯河","维兹班恩·曲针"},ang={["profession:Engineering"]="身为工程师，你可以将 electropellers 看作侏儒微型推进技术的奇妙范例，它们用于驱动机械诱饵，随后便会猛烈燃烧。",["race:Gnome"]="身为侏儒，你或许能理解维兹班恩制造爆炸诱饵鸭的狂乱雄心，尽管把昂贵零件丢在精灵守护的河里实在令人难堪。",["race:NightElf"]="身为暗夜精灵，面对维兹班恩那些喧闹冒烟的发明，以及把零件散落河中的意外，你或许会默默表示不满。黑海岸的溪流应当保持天然。"},sec={{t="醉后的发明",b="维兹班恩·曲针花了一个晚上，在黑海岸内陆寻找测试最新发明的地方。这位驻留奥伯丁的侏儒工匠造出了一只能够自行推进的爆炸诱饵鸭。他喝得太多，失去了意识，几个小时后醒来时已回到镇上，头发烧焦，背包空空。他那袋 导电器 掉进了沿海的一条河里。"},{t="水中打捞",b="维兹班恩请当地渔夫打捞黑海岸的淡水溪流，因为他不愿亲自冒险进入荒野。在急弯河和壁泉河垂钓的人，除了当地的鱼，也能钓到这些能浮在水上的金属零件。找回零件后，这位侏儒就能继续他那些古怪的水禽实验了。"}},faq={{q="在哪里能找到 导电器？",a="在黑海岸的淡水河流和湖泊中垂钓，包括壁泉河和急弯河。沿岸的海水中找不到 导电器。",al={"导电器 在哪里","如何获得 导电器","导电器 位置"}},{q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一位住在奥伯丁的古怪侏儒工程师。他制造各种稀奇古怪、会爆炸的发明，并依靠旅行者为他的实验搜集遗失的零件和奇物。",al={"谁提供 导电器","维兹班恩·曲针"}},{q="维兹班恩想造什么？",a="维兹班恩正在制造一只能够自行推进的爆炸诱饵鸭。他喝得太多，意外引爆了早期原型，烧焦了头发，还把一袋零件丢进了水里。",al={"爆炸诱饵鸭","维兹班恩的项目"}},{q="鱼群里能钓到 导电器 吗？",a="不能。导电器 要在普通淡水水域抛竿钓取，不能从 次级 黑口鱼这类特殊鱼群中钓到。",al={"鱼群 导电器","能否在鱼群中钓取"}},{q="这个任务的前置任务是什么？",a="先完成小齿轮。这是维兹班恩先前交给你的钓鱼任务，用来考验你在当地水域垂钓的运气。",al={"电驱动装置 前置任务","电驱动装置 前置条件"}},{q="怪物会掉落 导电器 吗？",a="不会。敌人和地面上的容器都不会提供 导电器；你必须用鱼竿从河里把它们钓上来。",al={"怪物是否掉落 电驱动装置","谁掉落 电驱动装置"}}},fp="14,160,17.351.0,19.303.0,35.157.0,27.199.0,33.195.0,44.109.0,29.102.0,39.109.0"}
P.entries["quest:1581"] = {n="刃叶的药剂",s="塞拉尔·刃叶正在寻求帮助，为家人在多兰纳尔日益繁忙的生意补充货源。她的丈夫几乎把所有时间都花在配制药剂上，新配好的药剂能减轻他的负担，也能让配制者换得不常见的草药。",h="塞拉尔·刃叶正在寻求帮助，为家人在多兰纳尔日益繁忙的生意补充货源。她的丈夫几乎把所有时间都花在配制药剂上，新配好的药剂能减轻他的负担，也能让配制者换得不常见的草药。",kw={"炼金术","多兰纳尔","地根草","狮王之力药剂","初级防御药剂","给 刃叶 的药剂","银叶草","塞拉尔·刃叶","泰达希尔"},ang={["faction:Alliance"]="身为联盟的一员，你可以帮助多兰纳尔补充恢复与防护药剂，供守卫和过往盟友应对林中的威胁。",["profession:Herbalism"]="泰达希尔肥沃的土壤滋养着 Silverleaf 和 Earthroot，你可以采集这些草药原料，完成塞拉尔店铺的订单。",["race:NightElf"]="身为暗夜精灵，你知道刃叶一家的生意是泰达希尔树冠下多兰纳尔生活的一部分。"},sec={{t="生意兴隆的重担",b="多兰纳尔吸引着往来于泰达希尔的旅人、哨兵和德鲁伊。塞拉尔·刃叶和她的丈夫经营着兴隆的草药与炼金生意，为这些人提供所需。为了满足需求，她的丈夫几乎整天埋首于药瓶和坩埚之间，夫妻二人很少有时间相伴。"},{t="商人的交换",b="塞拉尔向路过的草药师和药剂师寻求帮助，以减轻丈夫的负担。她需要狮王之力药剂和初级防御，愿意用新采集的不常见草药交换。对于在 大树 下磨炼技艺的炼金新手来说，这笔交换既能带来一捆草药，也让他们有机会用林中常见的植物换得当地备受追捧的草药。"}},faq={{q="塞拉尔·刃叶为什么需要这些药水？",a="塞拉尔·刃叶在多兰纳尔经营的家庭店铺生意日渐繁忙，她的丈夫几乎把所有时间都花在配制药剂上，以满足需求。请别人帮忙配制药剂，能让他得到急需的休息。",al={"为何需要药剂","塞拉尔·刃叶的动机","刃叶 店铺的问题"}},{q="这项任务需要哪些药水？",a="塞拉尔需要六瓶狮王之力药剂和两瓶初级防御药剂。泰达希尔的冒险者和当地哨兵经常购买这两种药剂。",al={"哪些药剂","配制所需物品","所需药水"}},{q="配制所需的药剂需要哪些草药？",a="配制这批药剂需要 银叶草、地根草 和标准的 水晶瓶。银叶草 和 地根草 遍布泰达希尔的林地。",al={"所需原料","药剂材料","需采集的草药"}},{q="谁能承接这项委托？",a="掌握基础技艺的炼金师可以承接这项委托。塞拉尔希望为店铺备好品质可靠、调配得当的药剂。",al={"等级要求","专业要求","是否人人都能接此任务"}},{q="塞拉尔会用什么交换这些药剂？",a="塞拉尔会提供一捆新采集的不常见草药，沿着泰达希尔的林间小径随意寻找，很难找到这些草药。",al={"奖励背景","塞拉尔 提供什么","刃叶 交易奖励"}},{q="塞拉尔·刃叶在哪里？",a="塞拉尔·刃叶就在多兰纳尔北面建筑的外面，靠近穿过这座林间村落的中央道路。",al={"塞拉尔 在哪里","刃叶 的位置","交任务地点"}}},fp="26,197,22.281.0,19.336.0,44.192.0,39.147.0,51.136.0,31.122.0,50.146.0,33.108.0"}
P.entries["quest:1582"] = {n="月光外衣",s="在达纳苏斯，洛瑟里亚斯需要皮甲，为即将踏上卡利姆多旅途的年轻冒险者提供装备。她以月光外衣的图样作为回报，换取成批的雕花皮制品。",h="在达纳苏斯，洛瑟里亚斯需要皮甲，为即将踏上卡利姆多旅途的年轻冒险者提供装备。她以月光外衣的图样作为回报，换取成批的雕花皮制品。",kw={"制作","达纳苏斯","雕花皮革","卡多雷","制皮","洛瑟里亚斯","月光外衣","泰达希尔"},ang={["faction:Alliance"]="作为联盟工匠，你帮助达纳苏斯的新兵配备装备。在卡利姆多北部，面对日益增多的荒野危险和敌对威胁，联盟在这里的立足之地仍不稳固。",["race:NightElf"]="作为暗夜精灵，你能从月光外衣上看到泰达希尔精湛的制皮技艺，它为林冠下的斥候和哨兵提供防护，同时让他们保持灵活。"},sec={{t="武装卡多雷",b="在达纳苏斯，制皮匠为哨兵和年轻斥候制作装备。暗夜精灵和盟友中的旅者离开泰达希尔，前往卡利姆多的荒野，那里对坚固护甲的需求很大。洛瑟里亚斯是为他们供应装备的制皮大师之一。"},{t="精进技艺",b="洛瑟里亚斯要求学徒带来配套的雕花手套、靴子和披风，以证明自己的技艺。完成她的订单便能赢得她的信任，她会传授暗夜精灵的月光外衣图样，这件护甲既能提供防护，又能让穿戴者行动自如。"}},faq={{q="洛瑟里亚斯是谁？",a="洛瑟里亚斯是达纳苏斯的一位暗夜精灵制皮训练师。她传授制皮技艺，也向证明了自身技艺的制皮匠提供进阶图样。",al={"洛瑟里亚斯 达纳苏斯","谁提供月光外衣"}},{q="洛瑟里亚斯为什么需要这么多皮制品？",a="洛瑟里亚斯需要雕花皮甲，为准备离开达纳苏斯、前往外地的年轻冒险者提供装备。她要求学徒供应这些常规服装。",al={"为什么需要这么多靴子","为什么制作雕花皮制品"}},{q="月光外衣是什么？",a="月光外衣是一种皮甲图样，只有证明你能批量制作雕花皮制品后，洛瑟里亚斯才会传授给你。",al={"月光外衣图样","能获得什么"}},{q="完成这项任务需要哪些材料？",a="给洛瑟里亚斯带去一副雕花皮手套、五双雕花皮靴和五件雕花皮质披风。你必须亲手制作每一件物品，并交给她。",al={"需要什么","月光外衣所需物品"}},{q="部落制皮匠能在这里学习这张图样吗？",a="不能。洛瑟里亚斯在达纳苏斯训练联盟工匠。部落制皮匠需要在卡利姆多和东部王国寻找自己的训练师。",al={"部落能做吗","月光外衣是否仅限联盟"}},{q="这个任务对专业技能等级有要求吗？",a="有。你的制皮技能至少要达到七十点，洛瑟里亚斯才会认为你有足够的技艺完成订单，并学习这张护甲图样。",al={"所需制皮等级","何时能获得月光外衣"}}},fp="13,178,22.229.0,19.236.0,17.155.0,46.151.0,26.120.0,50.164.0,49.146.0,53.142.0"}
P.entries["quest:159"] = {n="僵尸酒",s="在夜色镇，你带着一瓶烈酒向西出发，惹来旁人疑惑的目光。旅店老板斯密茨托你将僵尸酒送给亚伯克隆比，一位住在暮色森林西部边缘的隐士。这酒本是给瑟瑟发抖的老人暖身用的，但它那异乎寻常的烈性令人心生疑虑。",h="在夜色镇，你带着一瓶烈酒向西出发，惹来旁人疑惑的目光。旅店老板斯密茨托你将僵尸酒送给亚伯克隆比，一位住在暮色森林西部边缘的隐士。这酒本是给瑟瑟发抖的老人暖身用的，但它那异乎寻常的烈性令人心生疑虑。",kw={"亚伯克隆比","夜色镇","暮色森林","果汁配送","血鸦旅店","旅店老板斯密茨","僵尸酒"},ang={["faction:Alliance"]="身为联盟的信使，你为夜色镇的居民奔走，冒险踏上暮色森林危机四伏的道路。轻信林中的每一位隐士，都可能招来意想不到的麻烦。",["profession:Cooking"]="身为厨师，你看得出旅店老板斯密茨的僵尸酒配方用料刺鼻而古怪，也在挑战酒馆饮品的用料界限。"},sec={{t="可疑的烈酒",b="夜色镇的旅店老板斯密茨酿制了一种名叫僵尸酒的传奇烈酒。酒酿好后，他将酒瓶交给你，叮嘱你轻拿轻放，还说这酒烈得足以让死人复生。你带着这瓶烈酒穿过闹鬼的森林，送给一个古怪的独居者，看起来只是一次简单的善举。"},{t="隐士的口误",b="亚伯克隆比住在林边的一间小屋里，你将这瓶性质不稳定的烈酒送到了他手中。这位虚弱的隐士声称，暮色森林的夜晚严寒刺骨、浓雾弥漫，他需要用酒温暖酸痛的筋骨。接过酒瓶时，亚伯克隆比差点开口感谢你的“愚蠢”，随即赶忙改口，称赞你的“善良”。这次口误暗示，他对这瓶酒另有打算，并非只想在晚上喝上一杯。"}},faq={{q="僵尸酒是什么？",a="僵尸酒是旅店老板斯密茨在夜色镇的血鸦旅店酿制的一种极烈的酒。他说这酒烈得足以唤醒死者，远胜寻常烈酒。",al={"僵尸酒 背景故事","旅店老板斯密茨的酒是什么","亚伯克隆比的酒"}},{q="谁订了僵尸酒？",a="亚伯克隆比想要僵尸酒，他是个古怪的老隐士，独自住在暮色森林西部边界附近的一间小屋里。",al={"谁想要这酒","送酒 是给谁送酒"}},{q="亚伯克隆比为什么想要这酒？",a="亚伯克隆比声称，暮色森林的夜晚阴冷潮湿，他需要喝酒取暖。他收到酒时的一次口误，暗示他打算用这酒实施某种险恶的计划。",al={"亚伯克隆比为什么需要酒","亚伯克隆比怕冷"}},{q="谁酿制了僵尸酒？",a="旅店老板斯密茨在夜色镇中心经营着血鸦旅店，凑齐所需的刺鼻原料后，他便亲自酿制僵尸酒。",al={"谁酿制 僵尸酒","酒保旅店老板斯密茨"}},{q="亚伯克隆比的小屋在哪里？",a="亚伯克隆比的小屋孤零零地坐落在暮色森林西部，就在乌鸦岭墓地以北。",al={"亚伯克隆比位置","亚伯克隆比的小屋在哪里"}},{q="亚伯克隆比收到酒后会做什么？",a="拿到僵尸酒后，亚伯克隆比继续利用轻信他人的旅人。他派他们前往乌鸦岭墓地收集食尸鬼的肋骨，用来制作一具骇人的雕像，并声称它能驱赶亡灵。",al={"送酒 的后续任务","接下来会发生什么"}}},fp="14,212,20.307.0,17.418.1,21.189.0,28.127.0,36.182.0,27.145.0,29.89.0,56.201.0"}
P.entries["quest:1598"] = {n="失窃的典籍",s="在北郡修道院，杜希拉·拉萨雷想找回一本被盗的典籍，它就在葡萄园里的迪菲亚营地中。《虚空灵能》能帮助她授课，而将它带回也将证明你的本领。",h="在北郡修道院，杜希拉·拉萨雷想找回一本被盗的典籍，它就在葡萄园里的迪菲亚营地中。《虚空灵能》能帮助她授课，而将它带回也将证明你的本领。",kw={"迪菲亚潜行者","杜希拉·拉萨雷","北郡修道院","见习修士窃贼","虚空灵能","被盗的书","葡萄园","术士小鬼"},ang={["class:Warlock"]="身为术士，你要证明自己能毫不退缩地穿越险地。拿到典籍后，你将获授召唤第一个小鬼的仪式。",["faction:Alliance"]="身为联盟的一员，你在北郡的圣骑士和牧师身边谨慎行事，利用不法之徒的疏漏，获取受到严密管控的秘术知识。",["race:Human"]="身为人类，你看到了迪菲亚潜行者在北郡的影响，就连修道院的学生也会偷走神圣典籍，投身叛乱。"},sec={{t="禁忌之机",b="暴风城领地内的术士小心隐藏着自己的技艺和研究，避开窥探的目光。北郡修道院的档案室中保管着禁忌魔典。杜希拉不能冒着引起牧师和圣骑士怀疑的风险，亲自进入戒备森严的侧翼。她渴望得到《虚空灵能》，需要别人替她取回这本书。"},{t="迪菲亚趁虚而入",b="修道院的一名见习修士加入了迪菲亚潜行者，离开时偷走了几本珍贵的典籍。他逃到北郡农场，在迪菲亚营地附近藏身。盗贼们把赃物放在野外的一顶帐篷里，对书中黑暗法术的危险浑然不觉。"},{t="初次束缚",b="找回《虚空灵能》将考验你的胆量，并为你开启通往更黑暗知识的道路。归还典籍能满足杜希拉的野心，也能证明你已经准备好修习黑暗法术。作为奖赏，她会传授召唤并束缚小鬼的仪式，这是学徒最先学会驾驭的恶魔。"}},faq={{q="《虚空灵能》是什么？",a="《虚空灵能》是一本讲述黑暗魔法与位面掌控的禁忌魔典。北郡修道院图书馆戒备森严的侧翼中，藏着杜希拉·拉萨雷渴望用于研究和教学的知识。",al={"虚空灵能书籍","这本书是什么","见习修士偷了什么"}},{q="杜希拉·拉萨雷为什么不亲自偷走这本书？",a="杜希拉·拉萨雷必须保住自己在北郡修道院的地位。进入图书馆戒备森严的档案室会惊动牧师和圣骑士。当一名见习修士偷走典籍并加入迪菲亚后，她便有机会通过一名学徒得到它。",al={"杜希拉为何不亲自偷书","为何派我去"}},{q="被盗的典籍藏在哪里？",a="迪菲亚把典籍藏在北郡农场营地的一顶帐篷里，就在修道院东边。",al={"书在哪里","典籍位置","被盗典籍帐篷"}},{q="一名北郡见习修士为什么会加入迪菲亚潜行者？",a="王国各地的不满与纷争，驱使劳工、农民和教会学生加入迪菲亚潜行者。那名见习修士背弃誓言，从图书馆偷走了几本重要书籍，随后逃去投靠葡萄园里的匪徒。",al={"见习修士为何加入迪菲亚","修道院迪菲亚叛徒","谁偷了书"}},{q="术士取回典籍能得到什么奖励？",a="归还典籍证明你具备修习黑暗法术所需的胆量与韧性。杜希拉会传授召唤小鬼的知识作为奖赏，那将是你的第一个恶魔。",al={"能学到什么","术士任务奖励","为何做这个任务"}},{q="迪菲亚知道如何使用这本书吗？",a="匪徒们把偷来的书当作从修道院掠得的贵重赃物。虽然迪菲亚雇用了叛变的施法者，但那名见习修士和同伙只是把典籍塞进帐篷里的箱子，并未掌握其中的黑暗秘密。",al={"迪菲亚会使用典籍吗","迪菲亚拿书做什么"}}},fx={["1f0061ae"]={q="杜希拉·拉萨雷为什么想要虚空灵能？",a="杜希拉早就觊觎虚空灵能中封存的禁忌知识，但这本书一直存放在北郡修道院图书馆戒备严密的区域，她无法在不引起怀疑的情况下接近。一个误入歧途的见习修士偷走了它，给了她绝佳的机会，既能将其中的黑暗秘密据为己有，也能考验你是否有钻研术士法术的胆识。",al={"杜希拉为什么想要那本书","杜希拉·拉萨雷动机","为什么要偷典籍"}},a46315b9={q="为了找回典籍，你被派去对付谁？",a="你被派去对付驻扎在北郡农场的迪菲亚潜行者匪徒。一名误入歧途的修道院见习修士从严加看守的图书馆偷走了几本珍贵典籍，随后逃去加入他们的叛乱，并把那本典籍藏在了他们的帐篷间。",al={"谁拿走了书","农场里的迪菲亚潜行者","谁偷走了虚空灵能"}}},fp="15,184,23.309.0,18.261.0,17.293.0,31.203.0,52.248.0,32.99.0,56.231.0,55.162.0,39.219.0"}
P.entries["quest:1599"] = {n="开端",s="在丹莫罗，阿拉玛尔·格里姆会先考验联盟的术士学徒，再教他们召唤小鬼。首先，他们必须从霜鬃巨魔新兵身上夺取羽毛咒符。",h="在丹莫罗，阿拉玛尔·格里姆会先考验联盟的术士学徒，再教他们召唤小鬼。首先，他们必须从霜鬃巨魔新兵身上夺取羽毛咒符。",kw={"阿拉玛尔·格里姆","安威玛尔","起步","寒脊山谷","丹莫罗","羽毛咒符","霜鬃新兵","小鬼"},ang={["class:Warlock"]="作为丹莫罗的一名联盟术士，你的修行始于赢得格里姆的认可，并学会召唤自己的第一个恶魔仆从。",["race:Gnome"]="作为在寒脊山谷学习技艺的侏儒术士，你要智胜当地的霜鬃巨魔，证明自己的才智和对魔法的掌控。"},sec={{t="不情愿的导师",b="几位有影响力的人物注意到了一名颇有潜力的新秀，他们的关注让阿拉玛尔·格里姆暂时放下了秘术研究。这位术士虽不情愿，还是前来考察这名学徒。"},{t="黑暗魔法的火花",b="在传授奴役低等恶魔的方法之前，格里姆要求学徒证明自己的耐力和魔法天赋。霜鬃巨魔新兵在安威玛尔西南方的一处洞穴中，身上带着羽毛咒符。咒符中流淌着微弱的原始魔法，夺取它们便能证明学徒有能力战胜掌握魔法的敌人。这些奇特的样本也能用于格里姆的研究。"},{t="召唤小鬼",b="这些咒符让格里姆相信，学徒拥有求生的意志。他传授了召唤小鬼的方法，小鬼是术士最基础的仆从。它混乱的火焰魔法足以压倒缺乏自制力的主人。"}},faq={{q="谁会给予开端任务？",a="阿拉玛尔·格里姆会给予这项试炼。他在丹莫罗寒脊山谷的安威玛尔内训练术士。",al={"谁提供开端任务","开端任务给予者","阿拉玛尔·格里姆位置"}},{q="羽毛咒符有什么用途？",a="羽毛咒符能证明一名有志成为术士的学徒有能力面对并击败精通魔法的敌人。这些附有魔法的巨魔饰物也为阿拉玛尔·格里姆提供了奇特的研究样本。",al={"为什么需要羽毛咒符","羽毛咒符用途","霜鬃咒符"}},{q="霜鬃新兵在哪里？",a="霜鬃巨魔新兵聚集在寒脊山谷安威玛尔西南方的一处洞穴中。霜鬃巨魔已在那里站稳了脚跟。",al={"巨魔新兵在哪里","霜鬃洞穴位置","霜鬃新兵位置"}},{q="术士完成这项任务后能获得什么奖励？",a="这项试炼能让术士获得阿拉玛尔·格里姆的认可，并学会召唤小鬼，得到自己的第一个恶魔伙伴。",al={"开端传授什么","开端任务奖励","小鬼法术任务"}},{q="阿拉玛尔·格里姆为什么要教导术士新手？",a="几位有影响力的人物对这名初出茅庐的术士产生了兴趣。他们的关注促使格里姆暂时放下个人的秘术研究，考验并指导这名新秀。",al={"阿拉玛尔为何训练学徒","谁让阿拉玛尔训练学徒"}},{q="小鬼对术士新手来说危险吗？",a="是的。阿拉玛尔·格里姆警告说，小鬼虽体型矮小，却暗藏着狂暴的魔火和狡诈的心思。缺乏经验的召唤者很容易被它压倒。",al={"小鬼的危险","小鬼能杀死召唤者吗","关于小鬼的警告"}}},fx={["5dfeed0e"]={q="阿拉玛尔·格里姆为什么要做这件事？",a="一些显赫的资助者看中了你的潜力，因此阿拉玛尔·格里姆受劝暂时搁下自己的研究，转而训练你。在教你召唤第一个恶魔，也就是小鬼之前，他要求你证明自己具备足以活下来的魔法意志和身体素质。找回羽毛护符也能满足他的好奇心，让他研究其中奇特的巨魔魔法。",al={"阿拉玛尔·格里姆动机","为什么要羽毛护符","阿拉玛尔为什么要羽毛护符"}},f653bf22={q="你被派去对付的霜鬃初学者是什么人？",a="霜鬃初学者是一群年轻的冰霜巨魔，在安威玛尔西南方的洞穴里练习基础魔法。当地的霜鬃部族与铁炉堡矮人在丹莫罗各地交战，利用附近的洞穴重整队伍，训练刚入门的施法者。",al={"丹莫罗霜鬃初学者","霜鬃初学者是什么人","巨魔初学者洞穴"}}},fp="10,164,18.178.0,23.341.0,17.201.0,31.97.0,37.179.0,40.139.0,58.110.0,42.162.0,42.138.0"}
P.entries["quest:16"] = {n="葛拉德的饮料",s="在马科伦农场，葛拉德·提勒每天都要在田里劳作很久，需要新鲜的泉水。过路的旅人给他带来水，换取苹果。",h="在马科伦农场，葛拉德·提勒每天都要在田里劳作很久，需要新鲜的泉水。过路的旅人给他带来水，换取苹果。",kw={"苹果","以物易物","艾尔文森林","葛拉德·提勒","马科伦农场","清凉的泉水"},ang={["faction:Alliance"]="在王国抵御外敌之际，帮助马科伦农场等地的艾尔文森林农民，有助于为森林里的农户和驻军提供食物。",["race:Human"]="作为一名从北郡起步的人类，帮助葛拉德·提勒这样的邻居，体现了将艾尔文森林凝聚在一起的互助精神。"},sec={{t="葡萄田里的劳作与口渴",b="艾尔文森林的农场为暴风城的居民和驻军供应谷物、水果和蔬菜。在露天的田野里干活十分炎热。在马科伦农场，葛拉德·提勒照料作物、防治害虫，还要打理收成。他很少有时间去镇上的水井打水，只能靠路过的新兵带来干净的泉水，好继续劳作。"},{t="以物易物的生计",b="葛拉德用食物换水，而不用钱币。旅人若有多余的清凉的泉水，就能用它换取他果园里的新鲜苹果。王国竭力调配资源，维持秩序，供养军队。因此，在艾尔文森林的乡间，小农户与新兵之间以物易物，仍是一种切实可行的谋生方式。"}},faq={{q="葛拉德·提勒是谁？",a="葛拉德·提勒在艾尔文森林南部的马科伦农场务农。他照料着为当地居民供应食物的田地和果园。",al={"葛拉德·提勒","提勒是谁","葛拉德"}},{q="葛拉德为什么需要水？",a="整天顶着太阳在田里劳作，令人筋疲力尽。葛拉德依靠过路的旅人带来新鲜泉水，这样就能补充水分，又不必放下农活。",al={"为什么要泉水","葛拉德口渴","为什么需要饮水"}},{q="哪里能找到清凉的泉水？",a="艾尔文森林各处的食物和饮料商人以及旅店老板通常都出售清凉的泉水。丹尼尔修士在北郡修道院内出售这种泉水。",al={"哪里取水","泉水来源","如何获得水"}},{q="这项交易可以重复进行吗？",a="可以。葛拉德一直在田里劳作，你若还有多余的瓶装水，他就会继续用果园里的新鲜苹果来交换。",al={"可重复任务","能否再次完成","交更多水"}},{q="葛拉德会用什么来换取饮水？",a="葛拉德用一个新鲜的红苹果换取新鲜泉水。",al={"葛拉德奖励","能获得什么","交易奖励"}},{q="葛拉德在哪里？",a="葛拉德就在艾尔文森林南部的马科伦农场，谷仓外面。",al={"葛拉德·提勒位置","葛拉德在哪里","农场在哪里"}}},fx={d51fec31={q="清凉的泉水有什么用？",a="照料马科伦农场的田地十分辛苦，葛拉德·提勒只是需要稳定供应的新鲜净水，好在烈日下劳作时解渴。他不愿丢下庄稼无人照看，自己跑去找水，因此很乐意与带有多余饮水的过路旅者以物易物。",al={"清凉的泉水用途","为什么要泉水","葛拉德泉水"}}},fp="19,154,35.353.0,21.323.0,21.133.0,27.168.0,43.149.0,25.109.0,47.48.0,24.78.0"}
P.entries["quest:160"] = {n="给镇长的信",s="亚伯克隆比从暮色森林西部捎信到夜色镇，那里的镇长正等待一份意想不到的来物。他自称是镇长艾尔罗·埃伯洛克公爵的老朋友，但这封信却令人起疑。",h="亚伯克隆比从暮色森林西部捎信到夜色镇，那里的镇长正等待一份意想不到的来物。他自称是镇长艾尔罗·埃伯洛克公爵的老朋友，但这封信却令人起疑。",kw={"亚伯克隆比","夜色镇","暮色森林","埃伯洛克","信件","镇长","给镇长的信"},ang={["faction:Alliance"]="夜色镇的安危取决于能否在异常骚动波及守夜人的警戒范围之前，查明其根源。这封可疑的信需要引起联盟探员的注意。",["race:Human"]="作为一名为守夜人和House of Ebonlocke效力的人类信使，你或许会发现，暮色森林边缘的那位老隐士并不像表面上那么简单。"},sec={{t="友善的口信？",b="你从沃古尔食人魔山的食人魔手中找回亚伯克隆比被偷的箱子后，这位隐士便让你沿着雾气弥漫的道路前往镇上。他欣喜地笑着，说自己和镇长艾尔罗·埃伯洛克公爵是老朋友。亚伯克隆比坚称，镇长得知你所做的事后，也会和他一样激动。"},{t="镇长的困惑",b="在夜色镇的镇政厅里，镇长艾尔罗·埃伯洛克公爵说，他从未听说过亚伯克隆比。羊皮纸上没有一句他能读懂的问候。上面古老的文字让镇长困惑不已。"}},faq={{q="谁送出了给镇长的信？",a="你从当地食人魔手中找回亚伯克隆比被偷的财物后，他便将信交给你。他独自住在暮色森林西缘的一间棚屋里。",al={"谁给予给镇长的信","谁开启给镇长的信","亚伯克隆比信件寄信人"}},{q="亚伯克隆比和埃伯洛克镇长真的是朋友吗？",a="不是。亚伯克隆比说他们是老相识，但镇长艾尔罗·埃伯洛克公爵从未听说过他，也对这封信感到困惑。",al={"他们互相认识吗","亚伯克隆比是镇长的朋友吗","亚伯克隆比与埃伯洛克的关系"}},{q="信上写了什么？",a="这封信是用一种古老而晦涩的语言写成的。你和埃伯洛克镇长都无法解读，因此他请求协助翻译。",al={"亚伯克隆比的信写了什么","艾尔罗能读懂信吗","信是什么语言"}},{q="艾尔罗·埃伯洛克公爵在哪里？",a="镇长艾尔罗·埃伯洛克公爵在夜色镇大厅内，这座建筑位于暮色森林的镇子东侧，紧邻主路。",al={"镇长在哪里","艾尔罗·埃伯洛克位置","给镇长的信交付地点"}},{q="埃伯洛克镇长收到信后会发生什么？",a="埃伯洛克领主无法读懂这些神秘的文字，便请你找一个能解读它们的人。他派你去翻译亚伯克隆比的信。",al={"给镇长的信之后的任务","给镇长的信后续"}},{q="亚伯克隆比给你信时为什么在笑？",a="亚伯克隆比将信交给你时欣喜地笑着，但文本并未进一步说明原因。他声称自己与镇长是朋友，这让夜色镇的镇长困惑不已。",al={"亚伯克隆比为什么笑","亚伯克隆比是邪恶的吗","亚伯克隆比笑声信件"}}},fp="17,201,19.290.0,18.184.1,32.151.0,53.136.0,28.141.0,37.115.0,55.153.0,57.155.1"}
P.entries["quest:161"] = {n="水坝危机",s="在巨石水坝，主工程师辛德维尔七世怀疑有人蓄意破坏，于是将一份粉末样本送往北方检验。一名信使必须携带样本穿过湿地，交给丹莫德的爆破专家阿什兰·暗石。",h="在巨石水坝，主工程师辛德维尔七世怀疑有人蓄意破坏，于是将一份粉末样本送往北方检验。一名信使必须携带样本穿过湿地，交给丹莫德的爆破专家阿什兰·暗石。",kw={"阿什兰·暗石","黑暗威胁","丹莫德","爆炸粉末","辛德维尔七世","巨石水坝","萨多尔大桥","湿地"},ang={["faction:Alliance"]="穿过洛克莫丹和湿地的大道，是连接铁炉堡与萨多尔大桥另一端联盟北方领地的重要军事命脉。",["profession:Engineering"]="辨识高品质炸药的残留物，需要工兵经验老到的眼光。即使是普通粉末，也能透露出敌方破坏者的技术水平。",["race:Dwarf"]="巨石水坝是铜须工程技艺最辉煌的杰作之一。炸毁其石砌坝体的阴谋，威胁着整个卡兹莫丹的荣耀与安全。"},sec={{t="心怀恶意的粉末",b="水坝东侧坡道附近的一个可疑木桶里，装着怪味粉末。辛德维尔七世曾在附近见过黑铁工兵，怀疑这种粉末是用来炸毁矮人石砌建筑的精制炸药。水坝没有检验它的专用设备。要确定这一点，他需要一名军队爆破专家来检查样本。"},{t="北上的道路",b="道路穿过奥加兹大门，向下通往湿地潮湿的低地。凶猛的野兽、好斗的龙类和黑铁渗透者让这条路危机四伏。辛德维尔七世敦促信使沿着石铺道路前往丹莫德。这座遭到洗劫的矮人城镇位于萨多尔大桥的南侧入口，一支铁炉堡军团仍在那里驻守。"},{t="丹莫德的爆破专家",b="在丹莫德，阿什兰·暗石是军团中精通烈性炸药的专家。数十年来爆炸的冲击让他几乎失聪。他凭借敏锐的目光和嗅觉，确认这种粉末是专用爆破炸药。它的出现表明，有人正策划一场针对矮人工程核心的阴谋。"}},faq={{q="怪味粉末是什么？",a="怪味粉末是在巨石水坝附近收集到的一种炼金炸药。主工程师辛德维尔七世怀疑，破坏者打算用它炸开坝墙。",al={"粉末是什么","辛德维尔七世 粉末","怪味粉末"}},{q="为什么要把粉末一路送到丹莫德？",a="守卫萨多尔大桥的铁炉堡驻军就驻扎在丹莫德，阿什兰·暗石也在其中。他是一位经验丰富的炸药专家，具备辨识专用爆破化合物所需的专业知识。",al={"为什么去丹莫德","为什么找阿什兰·暗石","为什么去湿地"}},{q="阿什兰·暗石在哪里？",a="阿什兰·暗石驻扎在丹莫德的军营，位于湿地最北端、萨多尔大桥以南。",al={"暗石 在哪里","寻找 阿什兰","暗石 位置"}},{q="辛德维尔七世为什么警告信使要沿着道路走？",a="辛德维尔七世警告信使，从奥加兹大门下行时要沿着道路走，因为凶猛的野兽、迅猛龙、豺狼人和黑铁破坏者在湿地四处游荡。离开道路行进极其危险。",al={"为什么沿着道路走","湿地的危险","通往湿地的道路"}},{q="是谁在破坏巨石水坝？",a="这些炸药属于黑铁矮人，他们企图破坏铜须的基础设施，炸塌巨石水坝，淹没下方的山谷。",al={"谁制造了粉末","水坝破坏者","黑暗威胁的元凶"}},{q="阿什兰·暗石为什么听力不好？",a="阿什兰作为军队工兵和炸药专家在前线工作，爆炸冲击使他长期耳鸣，听力严重受损。",al={"暗石 失聪","阿什兰 为什么听不见"}}},fx={["4fa83212"]={q="主工程师辛德维尔七世为什么要做这件事？",a="主工程师辛德维尔负责确保巨石水坝结构完好，这座大坝是卡兹莫丹最伟大的工程奇迹之一。他怀疑附近发现的奇怪粉末是用来破坏大坝的炸药，因此需要专家进行分析，在灾难发生前弄清大坝究竟面临什么威胁。",al={"辛德维尔为什么需要这个","辛德维尔动机","为什么要送粉末"}}},fp="19,222,22.340.0,14.371.0,28.294.1,36.181.0,44.210.0,35.122.0,46.204.0,39.155.1,41.158.0"}
P.entries["quest:1618"] = {n="赤脊山的补给",s="湖畔镇遭到围攻，驻军急需来自铁炉堡的坚固铜制装备。托姆斯·深炉请有志于锻造的联盟铁匠打造这些装备，帮助当地铁匠弗纳·奥斯古抵御敌对的兽人和豺狼人，保卫这片地区。",h="湖畔镇遭到围攻，驻军急需来自铁炉堡的坚固铜制装备。托姆斯·深炉请有志于锻造的联盟铁匠打造这些装备，帮助当地铁匠弗纳·奥斯古抵御敌对的兽人和豺狼人，保卫这片地区。",kw={"黑石兽人","锻造","豺狼人","重型铜质牢固的木槌","湖畔镇","赤脊山","铜质符文腰带","石堡","托姆斯·深炉","弗纳·奥斯古"},ang={["faction:Alliance"]="作为联盟的一员，你将铁炉堡的援助送往南方饱受围困的人类城镇，暴风城的领导层因内部分歧而迟迟未能采取行动。",["profession:Blacksmithing"]="作为铁匠，你证明了自己能够为交战中的前线批量打造耐用的武器和防护坚实的护甲。",["race:Dwarf"]="作为矮人，你运用的技艺支撑着联盟的战事，而托姆斯指派铁炉堡最优秀的铁匠援助陷入困境的盟友。",["race:Human"]="作为南方诸国的人类，你收到来自卡兹莫丹的金属制品，帮助抵御咄咄逼人的黑石残部。"},sec={{t="跨越王国的求援",b="在铁炉堡的大锻炉，矮人铁匠们知道，联盟前线的困境远不止于丹莫罗。在赤脊山，湖畔镇屡遭从石堡要塞进军的黑石兽人和游荡于北部山脊的豺狼人袭击。暴风城的王国援军迟迟未至，当地物资也已匮乏到危险的地步。"},{t="湖畔镇的铁砧",b="湖畔镇的当地铁匠弗纳·奥斯古几乎独自在露天熔炉旁劳作，修补破损的护甲，替换断裂的武器。看到这位人类同行承受的重压，托姆斯·深炉请正在磨炼技艺的铁匠将四条铜质符文腰带和四把铜质大锤送往湖畔镇。作为补充民兵防御储备的回报，弗纳向远道而来的工匠传授更精湛的技艺。"}},faq={{q="谁提供赤脊山的补给任务？",a="托姆斯·深炉是铁炉堡大锻炉的一位矮人铁匠，他将这份工作交给锻造技艺达到要求的联盟铁匠。",al={"赤脊山的补给任务给予者","谁提供赤脊山的补给","托姆斯任务"}},{q="湖畔镇为什么需要铁炉堡提供武器和护甲？",a="占据石堡要塞的黑石兽人和北部山脊上凶悍的豺狼人不断袭击湖畔镇。镇上唯一的铁匠弗纳·奥斯古独自为民兵修补武器和护甲，早已不堪重负。",al={"赤脊山为何需要装备","湖畔镇为何需要武器","赤脊山物资短缺"}},{q="谁在赤脊山接收这批货物？",a="湖畔镇的当地铁匠弗纳·奥斯古会在这座湖滨小镇的熔炉附近接收货物。",al={"赤脊山的补给交任务地点","弗纳·奥斯古位置","赤脊山铁匠交任务"}},{q="这项任务需要锻造什么装备？",a="你需要制作四条铜质符文腰带和四把铜质大锤。这些装备共同展现了你制作防护甲片和重型打击武器的技艺。",al={"赤脊山的补给所需物品","赤脊山的补给所需材料","为托姆斯制作什么"}},{q="此时有哪些威胁困扰着赤脊山？",a="黑石兽人占据着石堡要塞，凶暴的豺狼人群则在湖畔镇周围的北部山麓游荡。",al={"赤脊山敌人","谁在攻击湖畔镇","赤脊山威胁"}},{q="弗纳·奥斯古会提供什么回报？",a="摆脱了为每一位卫兵从头打造装备的繁重压力后，弗纳会向你传授更精湛的锻造技艺。",al={"弗纳·奥斯古训练","赤脊山的补给奖励","能获得什么"}}},fp="16,219,22.337.0,23.408.0,38.110.0,57.200.0,38.103.0,43.136.0,49.109.0,47.113.0"}
P.entries["quest:162"] = {n="异种蝎的威胁",s="高级勘探员菲兹杜瑟派你前往达纳苏斯，将一份报告交给暗夜精灵学者兼历史学家格拉希娜·灵风。",h="高级勘探员菲兹杜瑟派你前往达纳苏斯，将一份报告交给暗夜精灵学者兼历史学家格拉希娜·灵风。",kw={"达纳苏斯","菲兹杜瑟","格拉希娜","昆虫分析","异种蝎","灵魂之力","塔纳利斯","月神殿"},sec={{t="达纳苏斯的学者",b="高级勘探员菲兹杜瑟希望将报告交到了解此类事务的人手中。格拉希娜·灵风是一位暗夜精灵学者兼历史学家。她花了许多时间研究艾泽拉斯生态中特有的生命形态。菲兹杜瑟希望她能判断危险的程度，并找到阻止它的办法。根据菲兹杜瑟最后掌握的消息，格拉希娜住在达纳苏斯的月神殿。"},{t="格拉希娜的答复",b="格拉希娜·灵风说，暗夜精灵知道报告中描述的恐怖。她认为菲兹杜瑟将报告和你一同送来，是明智的选择。异种蝎将迅速吞噬塔纳利斯的沙漠，成为所有人都将面对的最大威胁之一。它们是某个可怕势力的工具，而这个势力是部落与联盟共同面对的最严重威胁之一。格拉希娜叹息，竟然没有人更早察觉到危险。"}},faq={{q="格拉希娜·灵风是谁？",a="格拉希娜·灵风是一位暗夜精灵学者兼历史学家，花了许多时间研究艾泽拉斯生态中特有的生命形态。",al={"格拉希娜·灵风背景故事","格拉希娜是谁","月神殿学者"}},{q="是谁派你去找格拉希娜的？",a="高级勘探员菲兹杜瑟将昆虫分析报告交给你，请你把它带给格拉希娜·灵风。",al={"报告来自哪里","昆虫分析报告来源"}},{q="在哪里能找到格拉希娜·灵风？",a="根据菲兹杜瑟最后掌握的消息，格拉希娜·灵风住在达纳苏斯的月神殿。",al={"格拉希娜在哪里","格拉希娜·灵风位置","寻找格拉希娜·灵风"}},{q="前往达纳苏斯之前是什么任务？",a="前往达纳苏斯之前的任务是昆虫研究。",al={"前置任务","异种蝎的崛起的前置任务","找格拉希娜之前的任务"}}},fp="20,125,22.378.0,16.383.1,27.129.0,25.113.0,39.94.0,43.60.0"}
P.entries["quest:163"] = {n="乌鸦岭",s="在暮色森林西部，暗影在乌鸦岭中游移，一扇破败的窗户里闪着微光。艾莱尼·卡尔文派旅行者从夜色镇前去查明，究竟是什么藏身于此。",h="在暮色森林西部，暗影在乌鸦岭中游移，一扇破败的窗户里闪着微光。艾莱尼·卡尔文派旅行者从夜色镇前去查明，究竟是什么藏身于此。",kw={"卡洛尔","夜色镇","暮色森林","艾莱尼·卡尔文","基特斯","守夜人","乌鸦岭"},ang={["class:Paladin"]="身为圣骑士，你受过训练，要在邻近的墓地中猎杀不得安息的亡灵。发现浑身发抖、有血有肉的基特斯，或许会让你感到意外。",["faction:Alliance"]="守夜人几乎得不到暴风城驻军的援助，甚至完全孤立无援。身为联盟的英雄，你可能会受命调查暮色森林那些残破角落中的威胁。"},sec={{t="西边的动静",b="守夜人早已将暮色森林最西端留给了亡者与荒野。然而，那里出现的生命迹象不容忽视。卡洛尔在阴暗的道路上巡逻，连续两个夜晚看见乌鸦岭寂静的房屋间有东西在移动。一扇窗户里闪着灯笼的光。食尸鬼、骷髅和野兽遍布这片土地，守夜人不能对废墟中的动静置之不理。"},{t="惊恐的隐士",b="在乌鸦岭内，黑暗中的每一声响动都会让基特斯浑身发抖。这个流浪汉蜷缩在残破的建筑之间，坚持说这里没有危险，只有无害的基特斯。他惊慌失措的胡言乱语暗示，对于吞噬暮色森林的噩梦，他知道的比敢说出口的更多。"}},faq={{q="是谁派你调查乌鸦岭？",a="艾莱尼·卡尔文住在夜色镇，协助守夜人。她请关心暮色森林安危的旅行者前去调查西边传来的不安消息。",al={"谁发布乌鸦岭任务","乌鸦岭任务发布者","艾莱尼·卡尔文任务"}},{q="卡洛尔在乌鸦岭究竟看见了什么？",a="卡洛尔连续两个夜晚看见暗影在乌鸦岭荒废的村落中移动。前一晚，他还看见一栋建筑的窗户里亮着灯笼或蜡烛的光。",al={"卡洛尔看见了什么","卡洛尔乌鸦岭目击","乌鸦岭的暗影"}},{q="是什么怪物在废墟中出没？",a="你受命查明是什么在乌鸦岭出没。卡洛尔看见了移动的暗影和窗户中的光，但只有亲自走进那些残破的建筑，才能揭开潜藏其中的秘密。",al={"谁在乌鸦岭出没","乌鸦岭里有什么","乌鸦岭的怪物是真的吗"}},{q="基特斯是谁？",a="基特斯是一个住在暮色森林西部的流浪汉，疑神疑鬼，时刻处于惊恐的边缘。他自称无害，但他的愧疚和惊慌失措的胡言乱语，暗示他与这片地区更黑暗的谜团有所关联。",al={"基特斯背景故事","暮色森林的基特斯是谁","基特斯为何躲藏"}},{q="乌鸦岭位于何处？",a="乌鸦岭位于暮色森林最西端，就在那座亡灵盘踞的同名大墓地南边。",al={"乌鸦岭位置","乌鸦岭在哪里","乌鸦岭地图"}},{q="守夜人为何如此在意移动的暗影？",a="骷髅的暴动、凶暴的狼人和潜伏的蜘蛛，已让夜色镇的守卫疲于应付。荒废的西部若有陌生住民，或出现有组织的行动，都可能威胁到幸存者的聚居地。",al={"为何关注乌鸦岭","守夜人乌鸦岭"}}},fp="10,160,16.375.0,16.274.1,40.165.0,42.164.0,35.168.1,15.199.1,28.111.0,57.213.0"}
P.entries["quest:1638"] = {n="战士的训练",s="里瑞亚·杜拉克将闪金镇的年轻战士送往暴风城，学习如何在战场上坚持更久。在旧城区的猪和哨声旅店，老兵哈里·伯加德凭借丰富的实战经验指导他们。",h="里瑞亚·杜拉克将闪金镇的年轻战士送往暴风城，学习如何在战场上坚持更久。在旧城区的猪和哨声旅店，老兵哈里·伯加德凭借丰富的实战经验指导他们。",kw={"巴特莱比","闪金镇","哈里·伯加德","里瑞亚·杜拉克","旧城区","猪和哨声旅店","暴风城","训练","战士"},ang={["class:Warrior"]="身为战士，这场试炼标志着你从当地民兵的新兵，成长为联盟正式认可的士兵。它为你开启了学习进阶姿态与防御技巧的道路。",["faction:Alliance"]="身为联盟新兵，你可以将哈里·伯加德这样的老兵传授的实用搏斗经验，与书本上学到的战术一同带往纷争不断的边境。",["race:Human"]="身为人类战士，你的道路从艾尔文田园间的防御战事延伸至旧城区，那里是暴风城尚武传统的古老发源地，也是劳动者的家园。"},sec={{t="从艾尔文到旧城区",b="当你在应对艾尔文森林各处的威胁时证明了自己的身手，闪金镇的训练师就没有多少东西能再教给你了。于是，里瑞亚·杜拉克派你前往暴风城，去往民风粗犷的旧城区。经验丰富的战士聚集在那里，分享战斗教给他们的本领，远离皇家驻军的刻板规矩。"},{t="老兵的教诲",b="哈里·伯加德是一位年迈的战场老兵，住在猪和哨声旅店。他用饮酒和实际的耐力考验来检验你的毅力，而非操练场上的演练。在传授应对凶险战事的防御招式之前，哈里要你先在酒量上与他一较高下，再迎战酒馆里常来斗殴的当地人。"}},faq={{q="谁给予这个任务？",a="里瑞亚·杜拉克是闪金镇铁匠铺后方的战士训练师，在你初步证明自己的战斗本领后，她便会提供这项训练。",al={"任务给予者","谁提供战士的训练","里瑞亚·杜拉克任务"}},{q="在哪里能找到哈里·伯加德？",a="哈里·伯加德就在暴风城旧城区区的猪和哨声旅店内。",al={"哈里·伯加德在哪","哈里·伯加德位置","猪和哨声旅店"}},{q="哈里·伯加德传授什么？",a="哈里传授实用的招式和姿态，帮助战士在野外坚持更久。他的课程从耐力考验开始。",al={"能学到什么","十级战士任务奖励","哈里·伯加德的课程"}},{q="为什么在酒馆而不是兵营里训练？",a="旧城区是暴风城古老而粗犷的核心地带，退役士兵和身经百战的老兵都聚集于此。哈里一边喝着麦酒，一边用赤手空拳的较量磨炼学徒，远离兵营里正规的军事训练方式。",al={"为什么是猪和哨声旅店","为什么在酒馆训练","暴风城兵营"}},{q="与哈里交谈后要做什么？",a="与哈里交谈后，你要迎战当地的斗殴者酒鬼巴特莱比。在训练完成之前，这场挑战会考验你身体的承受能力。",al={"下一个任务是什么","战士的训练之后","下一步"}},{q="其他职业能接到这个任务吗？",a="只有战士才能接受这项训练。它属于战士专属的训练任务线。",al={"是否仅限战士","圣骑士能否完成","战士职业任务"}}},fx={["7596c61a"]={q="里瑞亚·杜拉克为什么让你去找哈里·伯加德？",a="里瑞亚·杜拉克认可你已经证明了自己是一名能干的战士，但她明白，在战场上，仅凭一腔热血走不了多远。为了让你能在更致命的威胁面前活下来，她指引你去找哈里·伯加德。哈里是一位久经沙场的老兵，掌握着老练的战斗技巧和实用的战场经验，新兵若想保住性命，就迫切需要这些本领。",al={"里瑞亚为什么要这样做","里瑞亚·杜拉克的动机","为什么派去找哈里·伯加德"}}},fp="20,206,23.301.0,22.331.0,21.131.0,35.101.0,32.127.0,57.205.0,35.151.1,36.91.0"}
P.entries["quest:1639"] = {n="醉鬼巴特莱比",s="在猪和哨声旅店，酒鬼巴特莱比面临哈里·伯加德的考验。一名有志进取的联盟战士必须夺走巴特莱比珍爱的酒杯，哈里才会传授更高深的战斗技巧。",h="在猪和哨声旅店，酒鬼巴特莱比面临哈里·伯加德的考验。一名有志进取的联盟战士必须夺走巴特莱比珍爱的酒杯，哈里才会传授更高深的战斗技巧。",kw={"巴特莱比","酒鬼","哈里·伯加德","酒杯","旧城区","猪和哨声旅店","暴风城","训练","战士"},ang={["class:Warrior"]="身为战士，你必须先接受暴风城训练师的实战考验，他们才会传授防御战术和驾驭姿态的技巧。",["faction:Alliance"]="身为联盟旅人，你会在远离Keep王室宫廷的暴风城旧城区，见到这座城市粗犷而平凡的一面。"},sec={{t="酒馆里的考验",b="在猪和哨声旅店，哈里·伯加德要求你先证明自己的胆量，才肯传授更高深的战斗技巧。房间另一头，巴特莱比正坐在吧台尽头，慢慢喝着酒。哈里要你夺走这个人的酒杯，因为他知道巴特莱比宁可动手，也不愿交出自己的麦酒。这项挑战考验的是你的决心。"},{t="旧城区的规矩",b="猪和哨声旅店里挤满了士兵、劳工和粗鲁的当地人，彬彬有礼在这里没什么用。巴特莱比不会客气地回应新来的人，而是嘲笑他们太过娇气，经不起酒馆里的一场斗殴。几句话下来，双方就在木地板上打了起来。在暴风城，战士的训练从一场最基本的酒馆斗殴考验开始。"}},faq={{q="巴特莱比是谁？",a="巴特莱比是暴风城旧城区的猪和哨声旅店里一位固执又嗜酒的常客，总待在吧台边。",al={"巴特莱比是谁","巴特莱比非玩家角色","酒鬼巴特莱比"}},{q="哈里·伯加德为什么派我去找巴特莱比？",a="哈里·伯加德想先看看你有什么本事，再传授高阶战士技巧。夺走巴特莱比的酒杯必然会引发一场打斗，也能考验你能否挨得住拳头、站稳脚跟。",al={"为什么要和巴特莱比打架","哈里·伯加德的考验","为什么要拿酒杯"}},{q="这场遭遇发生在哪里？",a="这场遭遇发生在暴风城东侧旧城区的猪和哨声旅店内。",al={"巴特莱比在哪里","猪和哨声旅店位置"}},{q="与巴特莱比交谈会发生什么？",a="巴特莱比会嘲讽你花哨又娇气，然后警告你别在猪和哨声旅店弄断了指甲。他的话很快就引发了一场打斗。",al={"巴特莱比说什么","巴特莱比对话"}},{q="与巴特莱比交谈后会发生什么？",a="与巴特莱比交谈后，一场酒馆斗殴便开始了。你必须击败他，拿到他的酒杯，再交给哈里·伯加德。",al={"巴特莱比之后的任务","酒鬼巴特莱比后续"}},{q="任何职业都能接取这个任务吗？",a="不能。这项职业训练仅限达到十级的联盟战士。",al={"谁都能做巴特莱比任务吗","仅限战士"}}},fx={["1d302574"]={q="哈里·伯加德为什么派你去，而不亲自对付巴特莱比？",a="哈里·伯加德和当地这个酒鬼没有私人恩怨要了结，他是战士训练师，正在考验你的胆识。在花时间教你高深的战斗技巧之前，他想先看看，你有没有在一场粗野斗殴中应付自如的胆量。让你从一个顽固的酒馆醉汉手里抢走酒杯，只是他安排的一场实际的入门考验。",al={"为什么选我","为什么派我去找巴特莱比","哈里为什么不和巴特莱比打"}}},fp="18,187,18.327.0,18.327.0,16.116.0,45.197.0,37.111.0,40.133.0,37.122.0,37.82.0"}
P.entries["quest:164"] = {n="斯温的货物",s="在夜色镇，艾莱尼·卡尔文向斯温·约根位于暮色森林西北部的营地送去援助。斯温和为数不多的追随者正与这片枯萎林地中的种种危险抗争。",h="在夜色镇，艾莱尼·卡尔文向斯温·约根位于暮色森林西北部的营地送去援助。斯温和为数不多的追随者正与这片枯萎林地中的种种危险抗争。",kw={"卡尔文","夜色镇","暮色森林","艾莱尼·卡尔文","圣光","斯温的货物","斯温·约根"},ang={["class:Paladin"]="艾莱尼认为斯温是在践行Light的使命。身为圣骑士，你可以帮助这位身陷围困的战友。",["faction:Alliance"]="斯温这样驻守边远地区的哨兵，显露出联盟在暮色森林的掌控已衰弱到何种地步。当地的补给依靠自愿奔走的信使运送，而非驻军的常规补给线。",["race:Human"]="卡尔文家族和斯温的追随者展现了暴风城乡间民众的坚韧。身为人类，你知道，即使暮色森林笼罩在阴霾之中，他们也不肯放弃这片土地。"},sec={{t="通往荒野的生命线",b="斯温·约根和几名同伴在暮色森林的西北边陲驻营。夜色镇面临狼群、蜘蛛和躁动亡者的威胁，而斯温一行人仍在镇墙之外坚守。危险接踵而至，他们无法抽出人手，冒险回镇补给。艾莱尼·卡尔文安排旅者运送物资，让这些战士能够继续战斗。"},{t="卡尔文家族的援手",b="卡尔文家族敬重斯温，认为他的坚守体现了对圣光的虔诚。艾莱尼筹集并送出物资，支援他的营地。斯温收到箱子时，便明白这是卡尔文家族的支持，但他的心思仍在眼前的战斗上。"}},faq={{q="斯温·约根是谁？",a="斯温·约根是一名拓荒者，在暮色森林的西北边缘守着一处武装营地。艾莱尼·卡尔文视他为侍奉圣光的正直战士，他和手下的小队正面对周围林地中的恐怖威胁。",al={"斯温是谁","斯温的故事","斯温·约根资料"}},{q="为什么斯温需要别人运送补给？",a="斯温的小队必须时刻提防周围的危险。他们无法抽出人手，冒险往返夜色镇，因此只能依靠镇民和过路的信使运送补给。",al={"斯温为何无法获取补给","斯温的补给","为何运送补给"}},{q="谁提供补给？",a="艾莱尼·卡尔文从夜色镇提供补给。她的家族敬重斯温的虔诚，并为他的营地安排援助。",al={"谁送出补给","艾莱尼·卡尔文","卡尔文家族"}},{q="斯温的营地在哪里？",a="斯温的营地背靠暮色森林西北部的群山，远离道路，位于枯萎农田以北的荒野边缘。",al={"斯温在哪里","斯温的位置","斯温的营地"}},{q="必须先完成这次运送，才能继续帮助斯温吗？",a="不必。自行找到斯温营地的旅者，即使没有携带艾莱尼的箱子，也能帮助他。",al={"斯温的货物是否必做","是否需要完成斯温的货物","运送补给前置条件"}},{q="斯温收到补给后会做什么？",a="斯温感谢卡尔文家族的支持，随后便将注意力转回营地面临的威胁和家族的往事。他正在寻找能帮助他复仇的战士。",al={"接下来会发生什么","斯温的货物之后","斯温的后续任务"}}},fp="18,158,28.371.0,22.246.0,19.211.0,43.204.0,26.115.0,29.144.0,55.93.0,47.160.0"}
P.entries["quest:1640"] = {n="击败巴特莱比",s="在暴风城，击败巴特莱比保管着一只来自战士训练师的珍贵酒杯。他不肯交出酒杯，新兵只能在斗殴中将它赢来。",h="在暴风城，击败巴特莱比保管着一只来自战士训练师的珍贵酒杯。他不肯交出酒杯，新兵只能在斗殴中将它赢来。",kw={"巴特莱比","斗殴","醉汉","酒杯","暴风城","训练","试炼","战士"},ang={["class:Warrior"]="作为一名联盟战士，你早早就要经历一场酒馆斗殴，并从中明白，当交涉无果时，坚定的意志和有力的拳头也能平息争端。",["faction:Alliance"]="走在暴风城这座都城的街头，你会在庄严的石墙之外，瞥见城中粗野阴暗的一面。"},sec={{t="斗殴者的挑战",b="战士训练师从不声称战斗有多么高尚或伟大。巴特莱比发誓，除非从他冰冷僵硬的手指间硬掰，否则谁也别想拿走他珍爱的酒杯。于是，你用拳头解决这件事。对于初出茅庐的战士来说，言语让位于一场斗殴。"},{t="醉汉的教训",b="巴特莱比夸口说要战斗至死，但一顿痛打就让他清醒了。见识到你的力量后，鼻青脸肿的他收起狂言，心生敬佩，乖乖认输。你可以把酒杯带回训练大厅，完成试炼。"}},faq={{q="巴特莱比是谁？",a="巴特莱比是个好勇斗狠的酒鬼，经常在暴风城出没。他紧攥着心爱的酒杯，考验那些被派来证明自身力量与决心的战士新手。",al={"巴特莱比","巴特莱比是谁","巴特莱比非玩家角色"}},{q="为什么我必须和巴特莱比打架？",a="联盟的战士训练师派新兵去取回巴特莱比手中的一只酒杯。他不肯轻易交出来，非要打一架，所以你必须赤手空拳击败他，才能拿到酒杯。",al={"为什么和巴特莱比打架","击败巴特莱比的原因","为什么打他"}},{q="在这个任务中，我真的会杀死巴特莱比吗？",a="不会。巴特莱比夸口说，你得从他冰冷僵硬的手指间掰走酒杯，但被打败后，他就会投降，并承认你比他预想的更厉害。",al={"巴特莱比会死吗","杀死巴特莱比","巴特莱比死了吗"}},{q="这个任务发生在哪里？",a="这场冲突发生在暴风城，巴特莱比平日就在这里喝酒闲逛。",al={"击败巴特莱比的地点","巴特莱比在哪里","巴特莱比的位置"}},{q="击败他之后会发生什么？",a="被你打败后，巴特莱比会认输，并友善地与你交谈。你可以把他的酒杯带回战士训练师那里，完成入门试炼。",al={"击败巴特莱比之后","巴特莱比后续"}},{q="这场试炼属于哪个训练阶段？",a="对于历练了约十个寒暑、初出茅庐的战士来说，这场斗殴是早期的一道关卡。它考验的是徒手搏斗中的基本耐力。",al={"巴特莱比任务等级","什么时候和巴特莱比打架"}}},fx={["14f26138"]={q="巴特莱比为什么和你打架？",a="巴特莱比原本根本不想打这场架，是你索要他的酒杯，挑起了争斗。他固执、醉醺醺，又舍不得自己的酒，绝不肯乖乖交出杯子，还扬言你只能从他冰冷僵硬的手指间把它掰走。对巴特莱比来说，和你打架纯粹是酒后的意气之争，也是为了保住自己的麦酒。",al={"巴特莱比为什么攻击","巴特莱比的动机","巴特莱比为什么打架"}}},fp="13,137,21.257.0,16.246.0,16.167.0,32.163.0,42.149.0,33.78.0,32.143.0,49.145.0"}
P.entries["quest:1641"] = {n="圣洁之书",s="在暴风城的光明大教堂，达索瑞恩·拉尔引导你完成一项面向年轻圣骑士的庄严仪式。仪式中的教诲考验着你的美德与对圣光的虔诚。",h="在暴风城的光明大教堂，达索瑞恩·拉尔引导你完成一项面向年轻圣骑士的庄严仪式。仪式中的教诲考验着你的美德与对圣光的虔诚。",kw={"圣洁之书","威尔海姆修士","光明大教堂","达索瑞恩·拉尔","圣光","圣骑士","暴风城","美德"},ang={["class:Paladin"]="身为圣骑士，这项仪式标志着你从武艺学徒成长为圣光的仆从。它教导你领会骑士团的核心精神：牺牲与仁慈。",["faction:Alliance"]="身为联盟的一员，你的训练巩固了暴风城这一核心，也让城中的圣骑士做好准备，保护联盟免受日益强大的黑暗侵袭。",["race:Human"]="身为暴风城的人类，你向洛丹伦阵亡的骑士致敬，并在南方的王国延续白银之手的光荣传统。"},sec={{t="圣骑士的使命",b="如今，你的训练已不再局限于武艺和骑士团的仪式。达索瑞恩的试炼要求你思考圣骑士的道德责任，领会这份使命所要求的更深层的承诺。依靠圣光的人们需要明白这份责任意味着什么的守护者。"},{t="美德之路",b="圣洁之书要求你奉献自己，为他人牺牲。达索瑞恩让你研读其中的神圣经文，了解圣光对其守护者的要求。书中的教诲让你做好准备，抵御天灾军团悄然蔓延的恐怖，保护平民。美德与怜悯必须指引你的力量。"}},faq={{q="圣洁之书的目的是什么？",a="圣洁之书考验新晋圣骑士是否理解神圣的准则。在获授更强大的神圣能力之前，初学者的力量除了要有武艺支撑，还必须以虔诚和美德为根基。",al={"为何需要圣洁之书","圣洁之书是什么","圣骑士书籍任务"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城光明大教堂的一位资深圣骑士训练师。他指引新晋圣骑士，将圣洁之书交给他们，并安排他们在王国各地接受试炼。",al={"达索瑞恩·拉尔","暴风城圣骑士训练师","达索瑞恩是谁"}},{q="这项试炼在哪里进行？",a="试炼始于暴风城教堂广场内的光明大教堂。初学者在闪金镇等外围城镇完成初步任务后，便会向达索瑞恩·拉尔报到。",al={"达索瑞恩在哪","光明大教堂任务","圣洁之书在哪开始"}},{q="为什么暴风城的教诲会提到天灾军团？",a="天灾军团摧毁了北方的洛丹伦，但其麾下的亡灵仍在威胁所有活着的凡人。暴风城的圣骑士学习辨识并对抗天灾军团的邪恶腐化，无论它出现在艾泽拉斯的何处。",al={"天灾军团对暴风城的威胁","为何这里有天灾军团","圣骑士对抗天灾军团"}},{q="读完圣洁之书之后要做什么？",a="阅读圣洁之书只是第一步。达索瑞恩·拉尔会派你去帮助急需援助的人，以此考验你是否将书中的教诲铭记于心。在那里，你必须以行动证明自己的怜悯与坚韧。",al={"圣洁之书下一步","读完书之后","达索瑞恩接下来要求什么"}},{q="通常由谁指引候选者去找达索瑞恩·拉尔？",a="艾尔文外围定居点的当地训练师和神职人员可以指引候选者去找达索瑞恩·拉尔。闪金镇的威尔海姆修士就是这样的引路人之一，待初学者准备好接受正式试炼时，他便会派他们前往首都。",al={"谁派我去找达索瑞恩","圣洁之书前置任务","威尔海姆修士"}}},fx={f1eda7dc={q="达索瑞恩·拉尔为什么要你接受这项试炼？",a="达索瑞恩·拉尔在暴风城肩负着引导初出茅庐的圣骑士追求真正美德、献身圣光的职责。艾泽拉斯受到天灾军团和无数其他危机的威胁，骑士团需要信仰坚定、实力可靠的卫士。他将圣洁之书交给你，是为了考验你对圣骑士神圣誓言的理解，确保你具备必要的精神根基，再赐予你更强大的神圣祝福。",al={"达索瑞恩·拉尔为什么要完成此事","达索瑞恩·拉尔的动机","为什么研读圣洁之书"}},e0af06a7={q="达索瑞恩·拉尔为什么选择你来完成这项任务？",a="这项试炼是一场内在的精神历练，唯有你自己才能走完。普通守卫或资深骑士都无法代你研习圣光的教义。达索瑞恩·拉尔负责引导你这位圣骑士新人的成长；要赢得骑士团的荣誉与力量，你必须亲自证明自己的虔诚，以及承担前方神圣职责的准备。",al={"达索瑞恩·拉尔为什么选我","达索瑞恩为什么选中冒险者","为什么不派守卫"}}},fp="20,165,19.259.0,18.289.0,44.213.0,22.179.0,33.183.0,54.214.0,46.214.0,50.222.0"}
P.entries["quest:1642"] = {n="圣洁之书",s="在暴风城，圣洁之书指引着圣骑士训练的最初几步。书中的教诲要求圣光的勇士怀有谦卑、怜悯与耐心，而非追求成神或单纯的力量。",h="在暴风城，圣洁之书指引着圣骑士训练的最初几步。书中的教诲要求圣光的勇士怀有谦卑、怜悯与耐心，而非追求成神或单纯的力量。",kw={"光明大教堂","怜悯","神圣","达索瑞恩·拉尔","圣光","圣骑士","耐心","暴风城","圣洁之书"},ang={["class:Paladin"]="对圣骑士而言，圣洁之书阐明了这一使命的道德核心：怜悯与耐心和随时准备战斗同样重要。",["faction:Alliance"]="暴风城的圣骑士是联盟在精神与军事上的中坚。他们以正直的品行和对普通民众的谦卑奉献，筑牢王国防御的根基。",["race:Human"]="对暴风城的人类而言，研读这部神圣典籍是一项神圣的成长仪式，能加深他们身为公民的责任感，以及对圣光的虔诚。"},sec={{t="神圣的本质",b="圣洁之书中的经文教导初入门的圣骑士，侍奉圣光意味着什么。神圣既不意味着追求成神，也不意味着自居于他人之上、统治他人。相反，勇士应当心怀纯正的意念，在每一次行动中行善，映照出圣光的恩泽。圣骑士拿起武器对抗邪恶，但缺乏道德宗旨的力量并没有多少意义。他们真正的不同之处，在于如何对待艾泽拉斯各地的普通人，让力量始终受正义与谦卑约束。"},{t="怜悯与耐心的试炼",b="研读经文只是圣骑士侍奉之路的起点。初学者读过圣洁之书后，暴风城的达索瑞恩·拉尔会考验书中的教诲是否已在其心中扎根。圣光的要求不止于斩杀野兽。它还要求耐心、勇气与理解。\n\n在城中及周边地区，人们饱受苦难，卑微的差事也得不到荣耀。初学者通过帮助不幸之人、抚慰绝望之人，证明自己心智健全、无私奉献，能够负责任地承受圣光的祝福。"}},faq={{q="圣洁之书是什么？",a="暴风城的圣骑士研读圣洁之书，将其奉为指引自身使命的神圣典籍。书中的教诲摒弃成神与个人荣耀，敦促他们以善行、怜悯和耐心映照圣光。",al={"什么是圣洁之书","圣洁之书任务","圣骑士圣洁之书"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城的一位圣骑士领袖，指导年轻圣骑士研读圣洁之书。他负责监督他们在精神与武艺上的试炼，通过为王国及其人民提供实际服务，考验他们的决心。",al={"达索瑞恩·拉尔是谁","达索瑞恩·拉尔位置","暴风城达索瑞恩·拉尔"}},{q="圣洁之书强调哪些美德？",a="圣洁之书教导神圣的战士，怜悯、耐心与勇气和战斗技巧同样重要。圣骑士必须惩击邪恶，但他们的高贵在于扶助弱者，映照圣光的仁慈。",al={"圣骑士美德圣洁之书","典籍教导什么","圣光的美德"}},{q="达索瑞恩·拉尔为何考验立志成为圣骑士的人？",a="达索瑞恩·拉尔考验初学者，是为了确认他们是否真正将圣洁之书的教诲铭记于心。他们必须在帮助不幸之人时展现出明智的判断与耐心，证明自己的虔诚源于奉献，而非骄傲。",al={"达索瑞恩为何考验圣骑士","达索瑞恩·拉尔的试炼","圣骑士试炼的目的"}},{q="圣洁之书教导圣骑士追求成神吗？",a="不。圣洁之书反对追求成神，教导圣骑士在每一次行动中力求行善。圣光赐予他们力量，是为了保护和扶助他人，而非让他们凌驾于其他凡人之上。",al={"圣骑士追求成神吗","圣骑士追求成神","圣骑士神圣的含义"}},{q="这个任务在哪里进行？",a="这些试炼在人类王国暴风城进行。初学者研习神圣的教诲，向城中的达索瑞恩·拉尔报到，随后在街巷与周边地区接受慈善、耐心和英勇的试炼。",al={"圣洁之书任务在哪里","圣洁之书暴风城位置","圣洁之书在哪里交任务"}},{q="为何耐心对侍奉圣光的圣骑士如此重要？",a="耐心表明一名神圣的战士严于律己、心怀谦卑且心智健全。为受苦受难之人服务，往往意味着承担卑微、艰难或默默无闻的差事，这既需要战场上的勇气，也需要坚定的心志与真切的同理心。",al={"圣骑士为何需要耐心","耐心对圣光的重要性","圣骑士耐心考验"}}},fp="20,195,22.474.0,33.575.0,29.215.0,22.234.0,49.243.0,47.245.0,57.216.0,33.232.0,56.253.0"}
P.entries["quest:1643"] = {n="圣洁之书",s="在暴风城，圣光的初学者受命去帮助有需要的人。他们寻找心地纯洁、动机高尚的市民，在贸易区找到了斯蒂芬妮·特纳。",h="在暴风城，圣光的初学者受命去帮助有需要的人。他们寻找心地纯洁、动机高尚的市民，在贸易区找到了斯蒂芬妮·特纳。",kw={"圣光","铁炉堡","孤儿院","圣骑士","斯蒂芬妮·特纳","暴风城","圣洁之书","贸易区"},ang={["class:Paladin"]="作为一名学习侍奉圣光的圣骑士，你从谦卑的善举做起，而非追求战斗的荣耀。",["faction:Alliance"]="作为联盟的市民，你看到暴风城在供养孤儿方面面临的困境，也看到人们在生计艰难时寻求援助，由此维系着与铁炉堡的联系。"},sec={{t="谦卑与奉献的一课",b="圣光的初学者走上暴风城的街头，开始这场神圣的试炼。他们寻找心怀善意、动机纯洁，并且需要依靠陌生人善心相助的人。在深入学习神圣职责之前，他们先要明白，帮助弱者比在战斗中赢得荣耀更为重要。"},{t="贸易区的援助",b="在暴风城的贸易区，斯蒂芬妮·特纳与丈夫一起为城里孤儿院的孩子们缝制衣服。更多商人来到城里，布料和皮革的争夺日益激烈，捐赠也变得更难募集。她的丈夫已经前往铁炉堡寻求支持。斯蒂芬妮留在暴风城，继续着他们的工作。"}},faq={{q="圣洁之书试炼的目的是什么？",a="这场试炼教导有志成为圣骑士的人，通过谦卑的援助侍奉圣光。初学者要在暴风城寻找心地纯洁、需要帮助的人，而不是通过战斗或壮举证明自己。",al={"什么是圣洁之书","圣洁之书的目的","为什么要做圣洁之书"}},{q="斯蒂芬妮·特纳是谁？",a="斯蒂芬妮·特纳住在暴风城的贸易区，为城里孤儿院的孩子们缝制衣服。她依靠捐赠的布料和皮革，为孩子们提供衣物。",al={"斯蒂芬妮·特纳是谁","斯蒂芬妮·特纳 暴风城","斯蒂芬妮·特纳在哪里"}},{q="斯蒂芬妮·特纳的丈夫为什么去了铁炉堡？",a="斯蒂芬妮·特纳的丈夫前往铁炉堡，为他们在孤儿院的工作寻求支持。他不在期间，她在暴风城收集物资、缝制衣服。",al={"斯蒂芬妮·特纳的丈夫","斯蒂芬妮的丈夫是谁","在铁炉堡的丈夫"}},{q="斯蒂芬妮·特纳面临着什么困难？",a="暴风城的商人增多，对布料和皮革的争夺也更加激烈。愿意捐赠这些材料的人越来越少，斯蒂芬妮很难凑齐为孤儿们缝制衣服所需的材料。",al={"斯蒂芬妮为何陷入困境","暴风城布料短缺","孤儿院衣物问题"}},{q="这场试炼为什么特意指引初学者去找斯蒂芬妮·特纳？",a="斯蒂芬妮·特纳心怀善意、心地纯洁，也确实需要帮助。帮助她，能让初学者有机会为一位致力于照顾他人的人效劳。",al={"为什么帮助斯蒂芬妮·特纳","任务为何指引前往斯蒂芬妮处"}},{q="这场试炼向圣光的仆从传授了什么？",a="这场试炼教导圣光的仆从心怀怜悯、帮助弱者。在战斗中运用神圣力量之前，他们必须先学会善待需要帮助的市民。",al={"圣光在这里传授什么","圣洁之书的教诲"}}},fp="20,171,32.291.0,25.339.0,50.217.0,24.176.0,53.173.0,45.200.0,70.159.0,60.167.0"}
P.entries["quest:1644"] = {n="圣洁之书",s="暴风城的斯蒂芬妮·特纳需要帮助，为因天灾军团而失去父母的孩子们置办衣物。她的丈夫约翰正在收集物资，一位立志成为圣骑士的人则将亚麻布送到她家中。",h="暴风城的斯蒂芬妮·特纳需要帮助，为因天灾军团而失去父母的孩子们置办衣物。她的丈夫约翰正在收集物资，一位立志成为圣骑士的人则将亚麻布送到她家中。",kw={"慈善","约翰·特纳","亚麻布","孤儿","圣骑士","天灾军团","斯蒂芬妮·特纳","暴风城","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你在暴风城照料弱者、施以援手，以此展现怜悯之心和对Light的虔诚。",["faction:Alliance"]="暴风城的战争孤儿，让人看到了近来Scourge袭击北方联盟诸国所造成的苦难。",["profession:Tailoring"]="斯蒂芬妮·特纳用成卷的亚麻布为孤儿们缝制衬衣和长裤。"},sec={{t="战争孤儿",b="斯蒂芬妮·特纳照料着一群孩子，他们的家人在过去十年间于北方丧生在天灾军团手中。她的丈夫约翰外出收集物资。因此，斯蒂芬妮既要让孩子们吃饱穿暖、有处栖身，还得抽空为他们缝制衣物。"},{t="怜悯的试炼",b="一位立志成为圣骑士的人将亚麻布交给斯蒂芬妮，以此证明自己的怜悯之心。有了这些布料，她便能在照料孩子们的饮食和住处之余，为他们缝制衬衣和长裤。这般微小的援助，体现了圣光的守护者如何庇护弱者。"},{t="都城的重负",b="斯蒂芬妮说，今年的日子越发艰难。为了收集物资，约翰必须踏上漫长而艰辛的旅程，最远要去铁炉堡。即便身处暴风城高大的石墙之内，人们仍能感受到北方近来的悲剧所带来的伤痛。"}},faq={{q="斯蒂芬妮·特纳是谁？",a="斯蒂芬妮·特纳住在暴风城，照料着因天灾军团而失去父母的孩子们。她靠着他人的施舍和丈夫约翰的帮助，努力为他们提供食物、衣物和住处。",al={"斯蒂芬妮·特纳是谁","斯蒂芬妮·特纳 暴风城","孤儿院看护人"}},{q="斯蒂芬妮·特纳为什么需要亚麻布？",a="斯蒂芬妮需要亚麻布，为孤儿们缝制衬衣和长裤。她还要照料他们的饮食和住处，几乎没有时间亲自收集材料。",al={"为什么需要亚麻布","亚麻布的用途","给斯蒂芬妮的布料"}},{q="约翰是谁，他去了哪里？",a="约翰是斯蒂芬妮·特纳的丈夫。他从暴风城出发，四处收集物资，最远会去铁炉堡，尽管他并不愿意离开家人。",al={"约翰是谁","约翰在哪里","斯蒂芬妮·特纳的丈夫"}},{q="暴风城为什么有这么多孤儿？",a="斯蒂芬妮照料的孩子大多在过去十年间，因天灾军团对北方诸王国的袭击而失去了家人。难民和幸存者将其中许多孩子带到了南方的暴风城。",al={"暴风城为什么有孤儿","天灾军团 孤儿 暴风城","孩子们的父母遭遇了什么"}},{q="帮助斯蒂芬妮与圣洁之书有什么关系？",a="圣洁之书考验着立志成为圣骑士之人的美德，尤其是慷慨与怜悯。向照料孩子的人提供基本物资，表明圣光的仆从既会对抗怪物，也会保护卑微之人。",al={"圣洁之书的含义","为什么这是圣骑士任务","圣骑士慈善任务"}},{q="斯蒂芬妮说的“空气中似乎有什么异样”是什么意思？",a="斯蒂芬妮说，今年感觉比往年更加艰难，仿佛空气中的某种异样预示着一场巨变。她说不清那究竟是什么。",al={"暴风城艰难的一年","空气中的异样","暴风城的困境"}}},fp="20,177,18.266.0,21.243.0,22.222.0,24.173.0,43.160.0,34.155.0,53.194.0,58.208.0,54.136.0"}
P.entries["quest:1645"] = {n="圣洁之书",s="在铁炉堡，蒂萨·热炉将圣洁之书交到一名矮人圣骑士手中。书中的教诲开启了一系列试炼，考验他们对圣光的虔诚，以及抵御天灾军团等黑暗势力、保卫艾泽拉斯的准备。",h="在铁炉堡，蒂萨·热炉将圣洁之书交到一名矮人圣骑士手中。书中的教诲开启了一系列试炼，考验他们对圣光的虔诚，以及抵御天灾军团等黑暗势力、保卫艾泽拉斯的准备。",kw={"圣洁之书","秘法大厅","圣光","铁炉堡","圣骑士","救赎","天灾军团","蒂萨·热炉"},ang={["class:Paladin"]="身为圣骑士，这项仪式将引领你从武艺训练走向圣光更深层的美德，迈向救赎与复活的力量。",["race:Dwarf"]="身为矮人，接过圣洁之书会加深铜须王国与白银之手人类骑士之间的信仰纽带。"},sec={{t="美德的召唤",b="来自东部王国各地、前途可期的圣骑士新兵，在掌握武艺和精神修行的基础后，来到铁炉堡的秘法大厅。在那里，年轻的矮人圣骑士学习圣光的勇士与普通战士有何不同。接受这份召唤，就意味着立誓终生恪守职责、牺牲自我，并坚持精神修行。"},{t="神圣之书",b="新兵会获授圣洁之书，以此指引自己履行职责、践行美德并领悟精神教诲。书中的文字阐明了如何运用神圣力量对抗邪恶威胁。然而，研读只是第一步。新兵必须走遍卡兹莫丹乃至更远的地方，将这些教诲化为信仰的行动。"}},faq={{q="圣洁之书任务的目的是什么？",a="圣洁之书开启了矮人圣骑士的进阶训练。蒂萨·热炉会交给新兵一本圣书，并派他们接受试炼，证明自己的美德，学习将死去的盟友唤回人世。",al={"圣洁之书的作用","圣洁之书的目的","为何完成此任务"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉在铁炉堡的秘法区训练圣骑士。她引导矮人圣骑士追求更高的美德，考验他们对圣光的虔诚，并让他们做好准备，面对天灾军团等威胁。",al={"蒂萨·热炉","铁炉堡的圣骑士训练师是谁","谁给予圣洁之书"}},{q="新兵为什么必须研读圣洁之书？",a="圣洁之书教导圣光所要求的职责与美德。书中的教诲让新兵做好准备，接受运用神圣力量所需的精神修行。",al={"圣洁之书是什么","为何读这本书","圣洁之书的故事"}},{q="矮人圣骑士正准备对抗哪些主要威胁？",a="矮人圣骑士准备保卫艾泽拉斯，抵御各地的危险，尤其是步步逼近的天灾军团亡灵威胁。",al={"圣骑士与谁作战","为何在铁炉堡训练圣骑士","圣骑士的使命"}},{q="训练在哪里进行？",a="训练始于铁炉堡北部城区的秘法大厅。学者、牧师、法师和圣骑士聚集于此，祈祷研习。",al={"蒂萨·热炉在哪里","铁炉堡圣骑士位置","秘法大厅圣骑士"}},{q="收到书后，接下来要做什么？",a="研读并思索圣洁之书之后，新兵将面对蒂萨·热炉安排的实践试炼。这些试炼要求他们走出城门，践行怜悯、职责与牺牲。",al={"接下来会发生什么","圣洁之书后续任务","拿到书后去哪里"}}},fx={b6d4c081={q="蒂萨·热炉为什么要你研读圣洁之书？",a="蒂萨·热炉负责铁炉堡的圣骑士训练。她将引导新人追求真正的美德、献身圣光视为自己庄严的职责。天灾军团的威胁日益逼近，其他危机也在威胁着艾泽拉斯，她希望确保自己训练的每一位卫士都明白自身的精神责任，并已准备好运用更强大的神圣力量保卫国土。",al={"蒂萨为什么要完成此事","蒂萨·热炉的动机","为什么研读圣洁之书"}},a71115f0={q="蒂萨·热炉为什么让你接受这项试炼，而不亲自完成？",a="蒂萨无法代你走上美德之路。身为圣光的导师，她的职责是引导与教导，但真正的圣骑士所需的虔诚、领悟和内心力量，必须来自新人自身。要获得圣光的祝福与力量，你必须通过研习与服务，亲自证明自己的能力与奉献之心。",al={"圣洁之书为什么选我","蒂萨为什么不亲自做","为什么必须研读典籍"}}},fp="20,210,19.352.0,20.292.0,50.208.0,24.207.0,46.171.0,59.129.0,36.160.0,41.182.0"}
P.entries["quest:1646"] = {n="圣洁之书",s="在铁炉堡，蒂萨·热炉教导年轻的圣骑士，圣光对他们有何要求。《圣洁之书》指出，虔诚不仅需要武力，还需要耐心、怜悯，以及谦卑地为困苦之人效劳。",h="在铁炉堡，蒂萨·热炉教导年轻的圣骑士，圣光对他们有何要求。《圣洁之书》指出，虔诚不仅需要武力，还需要耐心、怜悯，以及谦卑地为困苦之人效劳。",kw={"怜悯","圣光","铁炉堡","圣骑士","耐心","圣洁之书","蒂萨·热炉"},ang={["class:Paladin"]="身为圣骑士，你会明白，怜悯与奉献和武艺同样重要。",["race:Dwarf"]="身为矮人，你会在铁炉堡接受蒂萨·热炉等导师的教诲，学习以耐心和美德引导力量。"},sec={{t="神圣的尺度",b="对圣骑士而言，战斗中的力量必须服务于更崇高的目标。铁炉堡的蒂萨·热炉将《圣洁之书》交给新入门的圣骑士，教导他们为何而战。这本书引导他们远离统治与成神的念头，转而追求道德上的良善。圣骑士的使命，是成为圣光坚定的践行者。"},{t="奉献与怜悯的试炼",b="这本书教导他们，仅仅惩戒邪恶，还不足以成为圣骑士。怜悯、耐心与谦逊，使这些战士有别于普通的战斗者。研读书中的教诲后，新入门的圣骑士会在铁炉堡及周边地区接受试炼。他们通过施舍与服务，展现明智的判断和坚定不移的虔诚。"}},faq={{q="什么是《圣洁之书》？",a="《圣洁之书》教导初入门的圣骑士，神圣意味着努力行善、扶助不幸之人，并展现怜悯、耐心与勇气，而非追求成神。",al={"什么是圣洁之书","圣洁之书 圣骑士","这本书教导什么"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是铁炉堡的一位圣骑士导师。她引导新手完成最初的试炼，教导他们兼顾正义的战斗与无私的奉献。",al={"蒂萨·热炉是谁","蒂萨·热炉位置","蒂萨在哪里"}},{q="圣骑士为何必须学习耐心与怜悯？",a="圣骑士的力量体现着圣光，因此仅有战斗的力量还不够。耐心与怜悯能帮助圣骑士保护他人，并给予他们支持。",al={"为何阅读这本书","圣骑士美德","为何需要耐心与怜悯"}},{q="读完这本书后会有哪些考验？",a="读完这本书后，圣骑士会通过实际的试炼展现自己的美德。导师们派他们前往铁炉堡各处及周边地区，帮助困苦之人，证明自己对圣光的虔诚。",al={"读完这本书后会发生什么","圣洁之书 试炼","读完后的下一场试炼"}},{q="这场试炼在哪里进行？",a="研读这本书后，圣骑士会回到矮人都城铁炉堡，向蒂萨·热炉复命。",al={"这个任务在哪里交","铁炉堡圣骑士任务"}},{q="追求神圣意味着什么？",a="追求神圣意味着凡事选择行善，而非寻求成神。圣骑士运用圣光，扶助并保护艾泽拉斯的人民。",al={"追求神圣意味着什么","圣骑士成神"}}},fp="20,210,23.312.0,32.314.0,29.181.0,24.164.0,48.141.0,35.193.0,33.95.0,41.152.0"}
P.entries["quest:1647"] = {n="圣洁之书",s="在铁炉堡的神殿里，一名新兵通过助人来领悟圣光的教诲。导师派你前往外环，寻找一位心怀善意、确实需要帮助的人。在那里，约翰·特纳让你明白，怜悯与无私的劳作也是圣光之道的一部分。",h="在铁炉堡的神殿里，一名新兵通过助人来领悟圣光的教诲。导师派你前往外环，寻找一位心怀善意、确实需要帮助的人。在那里，约翰·特纳让你明白，怜悯与无私的劳作也是圣光之道的一部分。",kw={"铁炉堡","约翰·特纳","圣光","孤儿院","圣骑士","神殿","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你会明白，对圣光的虔诚始于无私地帮助有需要的普通人。",["faction:Alliance"]="身为联盟的一员，你会看到，在铁炉堡这样的城市里，怜悯、慈善与关怀弱者都是受到推崇的美德。",["race:Dwarf"]="身为矮人，你在自己的都城铁炉堡接受这场试炼，置身于故乡的厅堂之间。"},sec={{t="怜悯的教诲",b="驻守铁炉堡的圣光新兵面临着一场怜悯的试炼。导师派他们深入这座矮人城市，寻找真正需要援助的人。这番寻访考验着你的判断力：你必须认出纯洁的心灵、高尚的动机，以及真正需要善意的困境。谦卑地帮助他人，正是这一使命的核心。"},{t="约翰·特纳的重担",b="在铁炉堡的外环，一位名叫约翰·特纳的普通工人正忙着干活。你的到来让他吃了一惊，他高声提起暴风城的孤儿院，随后向你讲述自己如此辛劳的原因。长时间的劳作让特纳无法与心爱的妻子相聚，但他仍然辛勤工作，只为让孤儿们有衣穿、有饭吃。帮助他，然后返回神殿，继续你的圣光之旅。"}},faq={{q="圣洁之书是什么任务？",a="圣洁之书是铁炉堡为立志侍奉圣光的人设下的神圣试炼。你要找到并帮助一位心灵纯洁、动机高尚的人，然后继续接受精神上的教导。",al={"圣洁之书是什么","圣洁之书的目的","这是什么任务"}},{q="约翰·特纳是谁？",a="约翰·特纳是铁炉堡外环的一位勤劳工人，在那里忙于自己的营生。他长时间在外劳作，无法陪伴心爱的妻子，只为筹集物资，让孤儿们有饭吃、有衣穿。",al={"约翰·特纳是谁","约翰·特纳 铁炉堡","约翰·特纳在哪里"}},{q="导师为何派你寻找需要帮助的人？",a="导师派你去，是为了考验你对怜悯与助人的理解。你会学着辨认高尚的动机，施以善意，并指引那些默默为他人劳作的人。",al={"为何寻找需要帮助的人","帮助约翰·特纳的目的","为何接受这场考验"}},{q="约翰·特纳在铁炉堡的什么地方？",a="约翰·特纳沿着铁炉堡的外环行走，每天为孤儿院忙碌奔波。",al={"哪里能找到约翰·特纳","约翰·特纳的位置","如何找到约翰·特纳"}},{q="与约翰·特纳交谈后会发生什么？",a="听完约翰·特纳的难处后，你返回神殿，回到导师身边。在那里，你思索追随圣光的意义，并为履行使命的下一步做好准备。",al={"找到约翰·特纳之后会发生什么","返回圣光神殿","圣洁之书下一步"}},{q="约翰·特纳为何高声提起孤儿院？",a="初次有人走近时，约翰·特纳会高声提起暴风城的孤儿院，随后回过神来并道歉。他辛勤工作，为那些依靠慈善救济的孤儿提供食物和衣物。",al={"约翰·特纳高声提起的是哪家孤儿院","暴风城孤儿院 铁炉堡","约翰·特纳为何喊叫"}}},fp="20,268,22.318.0,25.380.0,35.192.0,19.181.0,53.173.0,42.107.0,45.178.0,48.197.0"}
P.entries["quest:1648"] = {n="圣洁之书",s="在铁炉堡，圣洁之书号召圣光的仆从展现怜悯之心。约翰·特纳为他与妻子共同经营的暴风城孤儿院寻求援助，那里收留了因天灾军团而失去父母的孩子。这项试炼要求初学者选择慈善，而非战功。",h="在铁炉堡，圣洁之书号召圣光的仆从展现怜悯之心。约翰·特纳为他与妻子共同经营的暴风城孤儿院寻求援助，那里收留了因天灾军团而失去父母的孩子。这项试炼要求初学者选择慈善，而非战功。",kw={"圣光","铁炉堡","约翰·特纳","亚麻布","圣骑士","天灾军团造成的孤儿","暴风城孤儿院","圣洁之书"},ang={["class:Paladin"]="圣骑士要通过无私帮助无辜者来完成这项试炼，而非依靠刀剑或战斗。这样的怜悯之心，是圣光所珍视的美德。",["faction:Alliance"]="对联盟而言，这揭示了Scourge给人类家庭留下的深重创伤，以及暴风城与铁炉堡之间的相互依存。"},sec={{t="大锻炉的善举",b="对于踏上圣光之路的初学者，铁炉堡的试炼要求的是行善，而非动武。约翰·特纳来到矮人的厅堂寻求帮助。他和妻子在暴风城经营着一所孤儿院，照料那些在过去十年间因天灾军团肆虐而失去父母的孩子。他前往铁炉堡求助，道出了联盟平民共同承受的艰辛。"},{t="天灾军团留下的创伤",b="跨越边境筹集物资并非易事。越来越多的工匠前往艾泽拉斯各地谋生，当地的物资也日渐匮乏。约翰·特纳已在铁炉堡奔走数周，向当地团体和市民求助，却收效甚微。他的妻子需要亚麻布为孩子们缝制衣服。无偿捐出布料，正体现了圣光仆从心中无私奉献的精神。"}},faq={{q="约翰·特纳是谁？",a="约翰·特纳是一名人类看护者，与妻子共同经营着暴风城的一所孤儿院。他大约每月前往铁炉堡一次，向矮人市民和商人公会募集物资与善款，帮助因战争而失去父母的孩子。",al={"约翰·特纳是谁","约翰·特纳的故事","铁炉堡特纳夫妇"}},{q="约翰·特纳为什么需要亚麻布？",a="约翰·特纳需要亚麻布，好让他在暴风城的妻子为孤儿缝制御寒的衣服。艾泽拉斯各地工匠增多，加上贸易的变化，使基本的布料也变得稀缺难寻。",al={"为什么需要亚麻布","约翰·特纳为什么需要布料","孤儿院用的亚麻布"}},{q="暴风城为什么有这么多孤儿？",a="特纳夫妇照料的孩子，在过去十年间天灾军团毁灭性的袭击中失去了父母。第三次大战使人类诸国的家庭支离破碎，让许多孩子无家可归。",al={"暴风城孤儿院的孤儿","为什么会有孤儿","天灾军团造成的孤儿"}},{q="约翰·特纳为什么前往铁炉堡？",a="约翰·特纳翻山越岭前往铁炉堡，向矮人市民和贸易团体募集捐赠，以及在暴风城难以找到的物资。",al={"约翰·特纳为什么在铁炉堡","为什么为暴风城孤儿院去铁炉堡求助"}},{q="帮助孤儿院与圣光有什么关系？",a="圣光要求人们无私、仁慈，并帮助身处绝望的人。帮助一位疲惫的看护者供养战争孤儿，考验着一名立志成为圣骑士的人是否心怀谦卑与慈善。",al={"这与圣光有什么关系","与圣骑士的关系","圣骑士为什么要做这个任务"}},{q="约翰·特纳的铁炉堡之行为什么如此艰难？",a="由于物资匮乏，愿意伸出援手的团体又寥寥无几，约翰·特纳此行进展缓慢，收效甚微。在筹到一批物资之前，他无法回家。",al={"约翰·特纳被困住了吗","为什么行程进展缓慢"}}},fp="20,272,26.397.0,24.387.0,19.223.0,38.198.0,43.213.0,40.157.0,55.178.0,58.162.0"}
P.entries["quest:1649"] = {n="勇气之书",s="在暴风城，《勇气之书》召唤圣骑士证明自己的信仰与勇气。达索瑞恩·拉尔正等待着那些准备向教会提出申请的人。",h="在暴风城，《勇气之书》召唤圣骑士证明自己的信仰与勇气。达索瑞恩·拉尔正等待着那些准备向教会提出申请的人。",kw={"光明大教堂","圣光教会","达索瑞恩·拉尔","信仰","圣骑士","暴风城","勇气之书","勇气"},ang={["class:Paladin"]="身为圣骑士，这场试炼是你成长道路上的关键一步。它将你的武艺与恪守信仰、无私奉献的精神结合在一起。",["faction:Alliance"]="身为联盟的一员，在动荡的岁月里，你也分享着暴风城这些试炼所维系的力量，无论是在防御上，还是在精神上。"},sec={{t="精神的磨砺",b="书中教导，勇气是在苦难中铸就的。神圣的经文将美德比作珍贵的矿石，发现时便价值不菲，经过淬炼才能经久不衰。通过艰苦的试炼与真诚的奉献，圣骑士将信仰、怜悯与勇气凝聚为力量，对抗威胁艾泽拉斯的邪恶。"},{t="向教会申请",b="读完此书后，你被指引去寻找达索瑞恩·拉尔，他是暴风城光明大教堂中备受尊敬的圣骑士领袖。他受理那些寻求勇气试炼之人的申请。这些考验绝非只是仪式。保护无辜者、捍卫教会，可能会让你付出生命的代价，唯有意志坚定者才能获得骑士团的认可。"}},faq={{q="这个任务的目的是什么？",a="《勇气之书》引导初学者从神圣的教义走向危险的试炼。读完此书后，有志于圣骑士之道的人便会前往光明大教堂，向达索瑞恩·拉尔申请接受信仰与勇气的考验。",al={"勇气之书是什么任务","为什么需要这个任务","勇气之书的目的"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城光明大教堂中的高阶圣骑士，也是一位导师。他负责训练有潜力的守护者，并主持试炼，让初学者向教会证明自身的价值。",al={"达索瑞恩·拉尔是谁","达索瑞恩·拉尔的故事","大教堂圣骑士训练师"}},{q="教会为何如此严厉地考验圣骑士？",a="圣光教会考验圣骑士，是为了让他们在绝望与暴力面前屹立不倒。意志不坚或信仰脆弱，都可能在战斗中葬送生命，因此导师们会在重要的神圣使命开始前，考验并磨砺每一位初学者。",al={"圣骑士试炼为何危险","为何考验勇气"}},{q="这场试炼在哪里进行？",a="你要前往暴风城教堂广场中心的光明大教堂，向达索瑞恩·拉尔提出申请。",al={"勇气之书在哪里交任务","达索瑞恩·拉尔的位置"}}},fx={["5e1febd2"]={q="勇气之书为什么指引你去找达索瑞恩·拉尔？",a="勇气之书中的文字是精神与道德上的指引，强调信仰和勇气等美德必须经受切实的考验，才能铸成不可动摇的决心。它让你去暴风城找达索瑞恩·拉尔，是因为试炼不能只靠阅读来完成；有志成为圣骑士的人必须亲自向光明大教堂的领导者请命，证明自己的虔诚经得起付出生命的考验。",al={"为什么必须与达索瑞恩·拉尔交谈","勇气之书为什么找达索瑞恩·拉尔","为什么派我去找拉尔"}}},fp="17,138,20.288.0,22.332.0,34.197.0,22.196.0,50.230.0,33.120.0"}
P.entries["quest:165"] = {n="隐士",s="夜色镇的艾莱尼·卡尔文派你去探望亚伯克隆比，这位年迈的隐士已经有些日子没来镇上采购补给了。他住在乌鸦岭墓地边缘一间摇摇欲坠的小屋里。",h="夜色镇的艾莱尼·卡尔文派你去探望亚伯克隆比，这位年迈的隐士已经有些日子没来镇上采购补给了。他住在乌鸦岭墓地边缘一间摇摇欲坠的小屋里。",kw={"亚伯克隆比","夜色镇","暮色森林","艾莱尼·卡尔文","乌鸦岭墓地","小屋","隐士"},ang={["faction:Alliance"]="守夜人艰难地守护着夜色镇与乌鸦岭之间的道路，亚伯克隆比这样的隐居者因此无法前往镇上寻求庇护。",["race:Human"]="身为人类，你了解 Carevin 一家与邻里之间的情谊。即使阴影笼罩着暮色森林，他们依然关照着这里的老人。"},sec={{t="邻里的关怀",b="艾莱尼·卡尔文记得，一位老人曾常来夜色镇采购补给，后来却不再露面。暮色森林的道路危机四伏，她请你去乌鸦岭墓地旁的小屋探望他，看看他是否平安。"},{t="乌鸦岭的隐士",b="来到小屋，你发现亚伯克隆比还活着。他对克尔文一家的担忧报以轻笑，说自己年事已高，林中又有怪物，才没再去镇上。见到一位能干的旅者登门，他很是高兴，很快便请你帮忙跑几趟腿。"}},faq={{q="这趟差事由谁发起？",a="住在夜色镇的艾莱尼·卡尔文请你探望一位老隐士，他过去常来镇上采购补给。",al={"隐士任务由谁提供","隐士任务在哪里接","艾莱尼·卡尔文任务"}},{q="隐士住在哪里？",a="亚伯克隆比住在暮色森林西部、乌鸦岭墓地北缘的一间木屋里。",al={"亚伯克隆比在哪里","暮色森林隐士位置","乌鸦岭附近的小屋"}},{q="艾莱尼·卡尔文为什么担心他？",a="亚伯克隆比过去常来夜色镇采购补给，后来却不再来了。道路上有野兽和亡灵出没，艾莱尼担心他已经丧命。",al={"为什么探望亚伯克隆比","艾莱尼为什么担心","老人出了什么事"}},{q="找到亚伯克隆比时，他真的身处险境吗？",a="没有。你抵达小屋时，亚伯克隆比还活着。他说自己年事已高，道路又危险，出门实在太过吃力。",al={"亚伯克隆比平安吗","隐士快死了吗","隐士遭到袭击了吗"}},{q="为什么有人会选择紧挨着乌鸦岭墓地居住？",a="亚伯克隆比说，他喜欢清静。他的住处紧邻东部王国受死灵法术腐化最深的墓地之一，令许多旅者感到不安。",al={"为什么住在乌鸦岭旁","亚伯克隆比墓地小屋","隐士为什么住在墓地附近"}},{q="你抵达后，亚伯克隆比提出了什么请求？",a="亚伯克隆比很快便请你帮忙跑腿，处理林中的一些事务。",al={"亚伯克隆比想要什么","隐士后续任务","隐士之后是什么任务"}}},fp="10,181,21.223.0,25.236.0,23.110.0,28.100.0,41.133.0,52.110.0,66.157.0,49.73.0"}
P.entries["quest:1650"] = {n="勇气之书",s="达索瑞恩·拉尔派你前往西部荒野偏远的海岸，保护达芙妮·斯迪威尔。她的丈夫外出未归，迪菲亚匪徒正威胁着他们的家园。",h="达索瑞恩·拉尔派你前往西部荒野偏远的海岸，保护达芙妮·斯迪威尔。她的丈夫外出未归，迪菲亚匪徒正威胁着他们的家园。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","达索瑞恩·拉尔","乔丹·斯迪威尔","长滩","暴风城","勇气之书","西部荒野"},ang={["class:Paladin"]="身为圣骑士，你离开暴风城大教堂的庇护，去保护无力自保的人，证明自己的勇气。",["faction:Alliance"]="斯迪威尔一家的处境表明，西部荒野已在多大程度上失去了暴风城的庇护。乡间居民只能独自面对迪菲亚。"},sec={{t="征召令",b="在暴风城的光明大教堂，达索瑞恩·拉尔考验着那些立志成为圣骑士的人。他要求他们保卫王国的人民。如今，你已肩负起勇气的使命，必须前往法律与权威无力维系秩序的地方，将这些理想付诸行动。"},{t="长滩危机",b="达芙妮·斯迪威尔和她的丈夫乔丹在西部荒野偏僻的长滩守着一处哨站。乔丹远赴铁炉堡，向矮人铁匠请教，而迪菲亚潜行者的活动愈发猖獗。于是，达索瑞恩派你西行，在盗贼攻陷达芙妮的家园之前保护她。"}},faq={{q="达芙妮·斯迪威尔为何独自留在西部荒野？",a="她的丈夫乔丹·斯迪威尔前往铁炉堡，向铁匠同行请教。他不在的这段时间里，达芙妮独自守着海边的家产，面对迪菲亚日益频繁的袭击。",al={"达芙妮的丈夫在哪里","乔丹·斯迪威尔为何外出","达芙妮·斯迪威尔独自一人"}},{q="是谁向圣骑士指派了这项任务？",a="是达索瑞恩·拉尔。他在暴风城的光明大教堂训练圣骑士，等你证明自己已准备好接受勇气的试炼，便会下达这道命令。",al={"谁发布勇气之书1650","勇气之书任务发布者","达索瑞恩·拉尔任务"}},{q="在哪里可以找到达芙妮·斯迪威尔？",a="达芙妮住在长滩最南端的一间小屋里，就在西部荒野西南部的海岸边。",al={"达芙妮·斯迪威尔在哪里","达芙妮·斯迪威尔位置","寻找达芙妮·斯迪威尔"}},{q="你抵达时，达芙妮完全无力自保吗？",a="不是。当你走到她的门廊前时，达芙妮已经用自己的武器杀死了六名迪菲亚匪徒，守住了家园。",al={"达芙妮能否战斗","达芙妮是否无力自保","达芙妮·斯迪威尔战斗"}},{q="什么威胁正逼近斯迪威尔一家？",a="迪菲亚潜行者威胁着斯迪威尔一家。这个组织已占据西部荒野的大片土地，仍在不断侵扰这处偏僻的海边家园，企图夺取土地，掠走剩下的财物。",al={"谁在袭击达芙妮","西部荒野的迪菲亚","斯迪威尔农场的敌人"}},{q="这项任务在勇气之书系列任务中有何意义？",a="衡量圣骑士勇气的，是牺牲精神和保护无力自保者的行动。保护达芙妮免遭匪徒劫掠，就是将正义付诸行动。",al={"为何必须帮助达芙妮","勇气之书试炼目的","这项任务的意义"}}},fx={ef242344={q="达索瑞恩·拉尔为什么派你去找达芙妮·斯迪威尔？",a="达索瑞恩·拉尔想考验你的决心，以及你对圣光美德的忠诚。达芙妮·斯迪威尔的丈夫乔丹前往铁炉堡交流锻造技艺，她独自留在西部荒野，而迪菲亚潜行者此时正横行于海岸。派你去保护一位无人守护的平民，既是在履行正义的职责，也是真正的勇气试炼。",al={"达索瑞恩·拉尔为什么要这样做","达索瑞恩·拉尔的动机","为什么派圣骑士去找达芙妮"}},["49096f91"]={q="达索瑞恩·拉尔为什么需要你，而不找暴风城的卫兵？",a="西部荒野远在暴风城城墙的庇护之外，遭到王室忽视，盗匪横行。城中的卫兵忙于保卫艾尔文和应对城内的动乱，人手捉襟见肘。对圣光教会而言，保护无力自卫的农户是圣骑士庄严的使命，因此，这项危险的任务正是证明你配得上勇气之书的理想考验。",al={"达索瑞恩·拉尔为什么选我","为什么不派守卫去找达芙妮","为什么派新人"}}},fp="17,146,14.254.0,22.285.0,41.169.0,37.148.0,35.104.0,46.141.0,42.200.0,52.153.0"}
P.entries["quest:1651"] = {n="勇气之书",s="迪菲亚潜行者步步逼近，达芙妮·斯迪威尔在西部荒野的农场中呼唤援助。一名圣骑士必须回应她的请求。",h="迪菲亚潜行者步步逼近，达芙妮·斯迪威尔在西部荒野的农场中呼唤援助。一名圣骑士必须回应她的请求。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","迪菲亚劫掠者","圣骑士试炼","勇气之书","西部荒野"},ang={["class:Paladin"]="作为圣骑士，你要接受考验，证明自己是一名坚定的守护者。在达芙妮身旁坚守阵线，保护无辜者免受伤害，就是以行动践行勇气。",["faction:Alliance"]="暴风城的驻军兵力分散，无力守卫乡间的农庄。保卫西部荒野忠诚居民的重任，便落在了各位英雄肩上。"},sec={{t="尘土中的坚守",b="迪菲亚潜行者仍在争夺达芙妮家园周围的土地。此前的交锋并未消除危险，新一轮进攻即将到来。你受命在她的屋旁坚守阵地。没有退路。你遵循《勇气之书》美德的道路，如今迎来了一场勇气的考验。"},{t="勇气的试炼",b="达芙妮只有手中的火枪，而你可以祈求圣光的祝福。迪菲亚劫掠者一波接一波地袭来，这场战斗考验着你能否在重压之下保护弱者。真正的勇气，是挡在无辜平民与残暴的攻击之间，即使危险正向你逼近。"}},faq={{q="达芙妮·斯迪威尔是谁？",a="达芙妮·斯迪威尔是一名人类农妇，在西部荒野的草原上经营着自己的家园。迪菲亚潜行者时常侵入她的土地，但她拒绝离开，奋力反抗他们的劫掠。",al={"达芙妮·斯迪威尔","达芙妮是谁","斯迪威尔 西部荒野"}},{q="迪菲亚为何偏偏袭击这座农场？",a="迪菲亚潜行者占据了西部荒野的大部分乡间土地，将农民赶走，或迫使他们屈服。达芙妮的丈夫乔丹远在铁炉堡，留下她独自一人，无人保护。迪菲亚想要夺走她的土地。",al={"迪菲亚为何进攻","迪菲亚袭击达芙妮","为何袭击斯迪威尔"}},{q="《勇气之书》是什么？",a="《勇气之书》是圣光教会用来指引年轻圣骑士的神圣典籍。见习骑士要在王国各地接受肉体与精神的试炼，以践行书中的美德。",al={"勇气之书是什么","勇气之书任务","圣骑士勇气之书"}},{q="如果达芙妮在战斗中倒下，会怎样？",a="如果达芙妮·斯迪威尔在战斗中倒下，试炼就会失败。勇气要求你在强盗的袭击中，既要保护自己，也要保护她的生命。",al={"达芙妮会死吗","达芙妮·斯迪威尔死亡"}},{q="这场袭击发生在哪里？",a="这场袭击发生在达芙妮·斯迪威尔的农舍外。她的小农场坐落在匕首岭，俯瞰着西部荒野南部的长滩。",al={"达芙妮·斯迪威尔位置","农场在哪里"}},{q="守住农场之后会怎样？",a="当你证明自己的勇气并击退迪菲亚劫掠者后，达芙妮会认可你的奉献。她会指引你进入圣骑士试炼的下一阶段。",al={"勇气之书后续任务","保护达芙妮之后"}}},fx={dca50aad={q="达芙妮·斯迪威尔为什么需要你帮助保卫农场？",a="暴风城的军队大多已经撤离西部荒野，农户只能独自抵御日益猖獗的匪徒。达芙妮虽然决心保卫家园，屋里也有一支火枪，却无法独自抵挡有组织的进攻。先前的一波袭击已经让她领教了敌人的厉害，她知道，下一次来袭的匪徒会更多，远非一个孤身定居者所能抵挡。",al={"为什么帮助达芙妮·斯迪威尔","达芙妮为什么无法自卫","达芙妮·斯迪威尔为什么需要帮助"}},["3da31dda"]={q="达芙妮·斯迪威尔为什么要坚守阵地？",a="这座农场是达芙妮·斯迪威尔的生计所在，也承载着她不肯被匪徒赶走的执拗。面对横行西部荒野的强盗，她选择坚守，而不是逃离或交出土地。守住家园关乎生存，也关乎尊严；如果在这里退让，她就会失去亲手建立的一切。",al={"达芙妮·斯迪威尔的动机","达芙妮为什么对抗迪菲亚","达芙妮为什么想留下"}},["7af5f29f"]={q="袭击达芙妮·斯迪威尔农场的迪菲亚袭击者是什么人？",a="这些袭击者是迪菲亚劫掠者，属于那个势力遍布各地、在西部荒野制造恐慌的犯罪兄弟会。他们在整个地区活动，侵占废弃的农庄，勒索居民，并强行赶走所有敢于反抗他们的人。达芙妮不肯放弃家园，使她的农庄成了有组织袭击的首要目标，他们要借此粉碎平民残存的抵抗。",al={"袭击者是谁","迪菲亚劫掠者是什么人","迪菲亚袭击斯迪威尔农场"}}},fp="17,120,19.298.0,18.330.0,23.177.0,48.221.0,26.191.0,47.132.0,34.148.0,36.159.0"}
P.entries["quest:1652"] = {n="勇气之书",s="在暴风城的光明大教堂，你向达索瑞恩·拉尔报告，你已守住达芙妮·斯迪威尔在西部荒野的家园，她如今安然无恙。你的勇气让你通过了教会的勇气试炼，也履行了不顾自身安危、保护无辜者的使命。",h="在暴风城的光明大教堂，你向达索瑞恩·拉尔报告，你已守住达芙妮·斯迪威尔在西部荒野的家园，她如今安然无恙。你的勇气让你通过了教会的勇气试炼，也履行了不顾自身安危、保护无辜者的使命。",kw={"光明大教堂","达芙妮·斯迪威尔","达索瑞恩·拉尔","铁炉堡","乔丹·斯迪威尔","暴风城","勇气之书","西部荒野"},ang={["class:Paladin"]="作为一名圣骑士，向达索瑞恩·拉尔复命便完成了你的勇气课程，也展现出联盟神圣守护者应有的无私精神。",["faction:Alliance"]="作为联盟的一员，你能看到斯迪威尔一家的困境如何将西部荒野的人类农田与铁炉堡的矮人工坊联系起来。他们的故事展现了联盟如何依靠相隔遥远的各地彼此援助。"},sec={{t="神圣之盾",b="你守住了家园，证明自己能够挺身而出，为无力自保的人抵挡危险，这正是教会对立志成为圣骑士之人的期望。家园屹立不倒，达芙妮也已安全，不再受到那些匪徒的威胁。"},{t="王国之间的纽带",b="达芙妮的丈夫乔丹·斯迪威尔仍留在铁炉堡，以他闻名遐迩的手艺为联盟效力。达索瑞恩·拉尔准备向北方传递消息，让乔丹知道家人受到保护，可以安心工作。"}},faq={{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城光明大教堂的一位资深圣骑士训练师。他引导年轻的圣骑士经历精神与武艺的试炼，教导他们勇气、正义与谦逊。",al={"达索瑞恩·拉尔","达索瑞恩是谁","暴风城圣骑士训练师"}},{q="达芙妮·斯迪威尔为何身陷险境？",a="匪徒围攻了达芙妮·斯迪威尔位于西部荒野的偏僻农场。她的丈夫乔丹当时远在铁炉堡工作。",al={"达芙妮·斯迪威尔","斯迪威尔农场","谁袭击了达芙妮"}},{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是达芙妮的丈夫，也是一位技艺精湛的铁匠和工匠。他正在铁炉堡以自己的手艺援助联盟，而教会则保护他留在家中的妻子。",al={"乔丹·斯迪威尔","达芙妮的丈夫","乔丹铁炉堡"}},{q="勇气之书是什么？",a="勇气之书是一部神圣的典籍，其中的教诲与光明大教堂布置的实践试炼相联系。在这些试炼中，圣骑士直面黑暗，冒着自身的危险保护弱者，以此证明自己的勇气。",al={"勇气之书的含义","勇气之书是什么"}},{q="完成这场试炼后会怎样？",a="达索瑞恩·拉尔认可你保护达芙妮·斯迪威尔的表现后，会指引你接受正义试炼，在精神与武艺的修行上迈出下一步。",al={"勇气之书之后的任务","接下来是什么"}},{q="教会为何关心斯迪威尔家的家园？",a="教会关心斯迪威尔家的家园，是因为达芙妮和乔丹一直以忠诚的服务和精湛的手艺帮助教会。在乔丹外出期间保护达芙妮，正是教会履行照顾自己人的承诺。",al={"教会为何帮助达芙妮","教会与斯迪威尔一家"}}},fx={["9332b34b"]={q="达芙妮·斯迪威尔为什么要你回去向达索瑞恩·拉尔报告？",a="达芙妮想让达索瑞恩·拉尔知道，她平安无事，农庄也挺过了袭击，但她最牵挂的还是丈夫乔丹。乔丹远在铁炉堡工作，达芙妮知道，在收到家中的消息之前，他会一直担忧。你回到暴风城的圣光大教堂报告后，达索瑞恩就能传话到铁炉堡，让乔丹放心，知道妻子和家园都安然无恙。",al={"为什么派去找达索瑞恩","达芙妮·斯迪威尔的动机","为什么与达索瑞恩·拉尔交谈"}}},fp="17,251,15.196.0,21.217.0,22.185.0,34.110.0,23.171.0,26.211.0,39.171.0,54.217.0"}
P.entries["quest:1653"] = {n="正义试炼",s="在教堂广场，达索瑞恩·拉尔派你前往铁炉堡，给乔丹·斯迪威尔捎去消息。他的妻子达芙妮在西部荒野遭到迪菲亚潜行者袭击后幸存了下来。",h="在教堂广场，达索瑞恩·拉尔派你前往铁炉堡，给乔丹·斯迪威尔捎去消息。他的妻子达芙妮在西部荒野遭到迪菲亚潜行者袭击后幸存了下来。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","丹莫罗","达索瑞恩·拉尔","铁炉堡","乔丹·斯迪威尔","暴风城","正义试炼"},ang={["class:Paladin"]="身为圣骑士，你从保护弱者，走向锻造神圣武器，以扫除联盟领土上的邪恶。",["faction:Alliance"]="身为联盟的一员，你看到西部荒野的平民奋力对抗迪菲亚潜行者，而暴风城的王室顾问却迟迟不采取行动。",["profession:Blacksmithing"]="身为铁匠，你能从乔丹在铁砧旁的劳作中看出他的虔诚，正如从战场上挥舞的祝圣之刃中一样。"},sec={{t="报喜的信使",b="迪菲亚潜行者的歹徒来袭时，你在西部荒野的农庄守护了达芙妮·斯迪威尔，她得以幸存。她的丈夫担心家人身处险境，已经动身前往铁炉堡。如今，拉尔派你亲自向乔丹报信，让他知道达芙妮的遭遇。"},{t="丹莫罗的铁匠",b="乔丹·斯迪威尔曾希望成为圣骑士，但最终选择继承父亲的手艺，成为一名铸剑大师。他在铁炉堡城门外的铁砧旁工作，锻造武器时也始终坚守着信仰。当你告诉他达芙妮幸存的消息后，他心怀感激，愿意帮助你锻造一件受祝福的正义武器。"}},faq={{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是一名虔诚的武器锻造师，在铁炉堡城门外工作。他曾与圣骑士一同研习圣光之道，后来选择继承父亲的手艺。",al={"乔丹·斯迪威尔","乔丹是谁","铁炉堡的铁匠"}},{q="乔丹的妻子为何身处险境？",a="达芙妮·斯迪威尔住在西部荒野的一座农庄里，那里的民众受到迪菲亚潜行者歹徒的威胁。乔丹动身前往铁炉堡时，就担心会有人来袭。强盗果然冲进了农庄，但圣骑士新兵将他们击退了。",al={"达芙妮·斯迪威尔的危险","乔丹的妻子遭遇了什么","迪菲亚潜行者为何袭击"}},{q="在哪里能找到乔丹·斯迪威尔？",a="乔丹·斯迪威尔在丹莫罗的铁炉堡正门外工作。比起城内的大锻炉，他更喜欢山间的空气。",al={"乔丹·斯迪威尔在哪里","斯迪威尔的位置","乔丹在铁炉堡的位置"}},{q="达索瑞恩·拉尔为何派玩家前往铁炉堡？",a="达索瑞恩·拉尔派你去告诉乔丹，达芙妮在迪菲亚潜行者的袭击中幸存了下来。这趟旅程让你结识了一位锻造大师，他能指引你制作一件神圣的圣骑士武器。",al={"为何前往铁炉堡","达索瑞恩·拉尔的差事","传信的原因"}},{q="与乔丹交谈后，接下来要做什么？",a="听到消息后，乔丹愿意帮助你锻造一柄神圣的战锤。他请你前往遥远的土地，收集稀有材料和经过祝圣的圣物。",al={"正义试炼下一步","乔丹需要什么","与乔丹交谈之后"}},{q="乔丹如何看待迪菲亚潜行者的威胁？",a="乔丹对暴风城议会及其疏于职守的态度感到愤怒。迪菲亚潜行者已经为祸西部荒野许久。他希望那些本分人家的农庄遭袭一事，能迫使年幼国王的摄政者正视这场危机。",al={"乔丹对迪菲亚潜行者的看法","斯迪威尔与国王顾问","西部荒野的迪菲亚潜行者"}}},fx={c7e3478b={q="达索瑞恩·拉尔为什么派你去找乔丹·斯迪威尔？",a="乔丹·斯迪威尔动身前往铁炉堡，并不知道妻子和家园是否挺过了迪菲亚在西部荒野的猛攻。你保护了他的家人，证明了自己的勇气，达索瑞恩·拉尔也希望能让这位铁匠安心。派你前去，就能让他直接从响应求援的圣骑士口中听到这个喜讯。",al={"为什么派我去找乔丹","达索瑞恩·拉尔的动机","为什么拜访乔丹·斯迪威尔"}},["26f62cea"]={q="达索瑞恩·拉尔为什么选你跑这一趟，而不派普通信使？",a="真正击退迪菲亚、救下乔丹妻子的人正是你。达索瑞恩认为，乔丹理应亲耳听到家人的救命恩人带来的喜讯，而不是让一位素不相识的信使转告，也让你在一位深切理解圣骑士团的盟友身边，继续接受圣光的教导。",al={"为什么派我而不派信使","为什么由我传信","正义试炼为什么选我"}}},fp="25,145,24.257.0,23.314.0,23.165.0,32.219.0,35.131.0,53.173.0,38.152.1,45.210.0"}
P.entries["quest:1654"] = {n="正义试炼",s="乔丹·斯迪威尔打算为一位无愧于圣光的圣骑士打造一件神圣武器。这位铁炉堡铁匠需要来自遥远之地的稀有材料，其中还包括他遗失的祖传铁锤。",h="乔丹·斯迪威尔打算为一位无愧于圣光的圣骑士打造一件神圣武器。这位铁炉堡铁匠需要来自遥远之地的稀有材料，其中还包括他遗失的祖传铁锤。",kw={"白洛尔的矿石","丹莫罗","铁炉堡","乔丹·斯迪威尔","科尔宝石","圣骑士武器","正义试炼","白石橡木"},ang={["class:Paladin"]="身为圣骑士，你要经受奉献与牺牲的试炼，才能获得一件为引导圣光而锻造的武器。",["faction:Alliance"]="身为联盟的一员，你依靠人类的锻造技艺，以及联盟在卡兹莫丹乃至更远之地的据点，为抵御日益严峻的黑暗威胁的守卫者配备武器。",["profession:Blacksmithing"]="身为铁匠，你见证乔丹·斯迪威尔用寻回的祖传工具，将净化过的奥术材料与矿物材料结合，打造一件神圣遗物。"},sec={{t="神圣的委托",b="在铁炉堡大门外，乔丹·斯迪威尔无法独自完成圣骑士武器的锻造。你要收集他锻造所需的材料。"},{t="祝圣的材料",b="乔丹·斯迪威尔需要四样东西来打造这件武器：白石橡木、勘探大师提供的精炼矿石、净化过的科尔宝石，以及他的铁锤。他逃离影牙城堡时，将铁锤遗落在那里。要找齐这四样东西，就得面对遍布东部王国乃至更远之地的危险。"},{t="铁匠的传承",b="乔丹·斯迪威尔需要父亲的铁锤来完成这项工作。这件传家宝承载着他的技艺与家族传承。找回铁锤，再净化一颗稀有的科尔宝石，乔丹就能实现酝酿多年的构想，锻造一件伸张正义的利器。"}},faq={{q="这个任务的目的是什么？",a="乔丹·斯迪威尔需要来自各地的稀有材料，为初露头角的圣骑士打造神圣武器。收集这些材料，将考验他们的奉献与牺牲精神。",al={"这个任务有什么作用","为什么要做正义试炼","正义试炼目标"}},{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是一位人类武器锻造师，在丹莫罗的铁炉堡大门外工作。他计划为圣骑士打造一件神圣武器，并在寻找父亲遗失的铁锤。",al={"乔丹·斯迪威尔的故事","铁炉堡外的铁匠是谁","斯迪威尔的背景"}},{q="锻造这件武器需要哪些材料？",a="乔丹需要乔丹的铁锤、白石橡木、精炼矿石和净化过的科尔宝石。",al={"需要哪些物品","乔丹·斯迪威尔所需材料","正义试炼所需材料"}},{q="为什么乔丹的铁锤对他如此重要？",a="乔丹的铁锤曾属于他的父亲。找回这件传家宝，就能让它重返乔丹的熔炉，让他重新拥有这件承载着自身技艺与家族传承的工具。",al={"为什么需要父亲的铁锤","乔丹的铁锤的故事","斯迪威尔的铁锤的历史"}},{q="科尔宝石是什么？",a="科尔宝石是一种稀有而强大的宝石。净化其中的腐化影响后，它就能汇聚为神圣武器祝圣所需的力量。",al={"科尔宝石的故事","科尔宝石是什么","净化过的科尔宝石"}},{q="乔丹·斯迪威尔在哪里打造这件武器？",a="乔丹·斯迪威尔在丹莫罗群山之中、铁炉堡覆雪的大门外工作。",al={"乔丹·斯迪威尔的位置","乔丹在哪里","在哪里交任务"}}},fx={c050f299={q="乔丹·斯迪威尔为什么想完成这件事？",a="乔丹早已构思好一把强大的正义之器，但他既缺少稀有材料，也无力远行到世界各地去收集它们。与你合作，让他终于有机会找回家族遗失的铁锤，打造出自己迄今最出色的杰作，同时酬谢一位圣光的勇士。",al={"乔丹·斯迪威尔的动机","乔丹为什么要这些物品","乔丹·斯迪威尔为什么"}},["4a2d94b4"]={q="乔丹的铁锤有什么用？",a="乔丹的铁锤是乔丹·斯迪威尔的父亲传给他的传家之物。只有拿起这件熟悉而可靠的工具，乔丹才能着手进行繁复而精细的锻造，为你打造神圣的武器。",al={"乔丹的铁锤是什么","乔丹的铁锤的用途","为什么需要乔丹的铁锤"}},deb75c2f={q="乔丹的精炼矿石有什么用？",a="这批精炼矿石能提供锻造武器锤头所需的淬炼金属。普通的铁无法传导圣骑士的神圣能量，因此必须使用高品质的精炼矿石，才能同时承受激烈的战斗与圣光本身的力量。",al={"乔丹的精炼矿石的用途","精炼矿石有什么用","乔丹的矿石货物"}},a71ac5b5={q="白石橡木有什么用？",a="白石橡木质地致密，极为耐用，是制作坚韧武器柄的珍贵木材。乔丹需要用这种木材削制结实的锤柄，让它既能支撑沉重的锻造锤头，又不会在强大的神圣力量下碎裂。",al={"白石橡木的用途","为什么要白石橡木"}},ab9031e0={q="净化过的科尔宝石有什么用？",a="科尔宝石天生适合传导魔法与精神力量。清除黑暗污染并完成净化后，这颗宝石就能镶入武器，成为神圣的聚焦核心，让你在挥击时驾驭并释放圣光。",al={"净化过的科尔宝石的用途","科尔宝石有什么用","为什么要净化过的科尔宝石"}},c2f50c47={q="乔丹·斯迪威尔为什么需要你收集材料？",a="乔丹只是个守着铁炉堡外熔炉的普通铁匠，既缺乏战斗训练，也无法脱身前往艾泽拉斯各地的险境。所需物品散落在遥远而危险的地方，只有技艺娴熟的圣光圣骑士才能冒险将它们取回。",al={"乔丹·斯迪威尔为什么选我","乔丹为什么需要帮助","乔丹为什么不能自己取矿石"}}},fp="25,173,19.132.0,26.290.0,20.247.1,34.153.0,23.162.0,46.116.0,43.152.0,18.126.0,45.90.0"}
P.entries["quest:1655"] = {n="白洛尔的矿石",s="在洛克莫丹，白洛尔的矿石这批货物将用于铸造乔丹·斯迪威尔的神圣武器。莫格罗什食人魔在从湿地出发的路上劫走了这批合金。",h="在洛克莫丹，白洛尔的矿石这批货物将用于铸造乔丹·斯迪威尔的神圣武器。莫格罗什食人魔在从湿地出发的路上劫走了这批合金。",kw={"白洛尔","乔丹·斯迪威尔","洛克莫丹","莫格罗什","食人魔","矿石","货物","石手","正义试炼"},ang={["class:Paladin"]="身为圣骑士，你在正义试炼考验中迎战危险的蛮横敌人，为自己的神圣战锤找回材料。",["faction:Alliance"]="洛克莫丹东北部的莫格罗什食人魔威胁着补给线，以及途经湿地山口的商队。",["profession:Blacksmithing"]="白洛尔的特制合金符合乔丹·斯迪威尔为其传奇武器设定的严苛金属加工要求。"},sec={{t="遇袭的商队",b="乔丹·斯迪威尔正等待老友白洛尔·石手精炼的矿石，但这批货物始终没有抵达铁炉堡。商队从湿地南下进入洛克莫丹时，遭到莫格罗什食人魔伏击，护卫惨遭屠杀。一名受伤的护卫抵达了一处营地，却很快伤重身亡。货物就此落在了食人魔的领地里。"},{t="夺回合金",b="白洛尔·石手在洛克莫丹扎营，并派遣圣骑士渡过洛克湖，前往东北方的丘陵。那箱被抢走的合金被遗弃在莫格罗什的营地之间。要找回它，就必须深入敌人的领地，而这也能让白洛尔履行与乔丹·斯迪威尔的约定。"}},faq={{q="白洛尔·石手是谁？",a="白洛尔·石手是一位在洛克莫丹工作的矮人工匠，也是乔丹·斯迪威尔的老朋友。他负责制备并供应乔丹锻造所需的特制合金。",al={"白洛尔·石手","白洛尔是谁","白洛尔"}},{q="谁抢走了乔丹的矿石？",a="莫格罗什食人魔在商队从湿地前往洛克莫丹的途中发动了伏击。他们杀死了护卫，把货物搬回了自己的营地。",al={"谁偷走了矿石","谁拿走了货物","矿石窃贼"}},{q="伏击发生在哪里？",a="商队在从湿地通往洛克莫丹的山路上遭到伏击，当时还没有抵达当地的定居点。",al={"伏击地点","商队遇袭地点"}},{q="莫格罗什食人魔在哪里？",a="莫格罗什食人魔在洛克湖东北方崎岖的丘陵中建有设防的营地，与西岸的定居点隔水相望。",al={"莫格罗什在哪里","食人魔营地位置","货物在哪里"}},{q="为什么需要这批货物？",a="乔丹·斯迪威尔需要这批合金，为接受正义试炼考验的圣骑士锻造神圣武器。",al={"为什么需要矿石","货物有什么用途","矿石用途"}},{q="商队的护卫遭遇了什么？",a="几乎所有护卫都死于伏击。唯一找到援助的护卫也在几天后身亡，治疗者没能来得及救下他。",al={"商队护卫","商队幸存者"}}},fx={f726d253={q="白洛尔·石手为什么想完成这件事？",a="白洛尔与老朋友乔丹·斯迪威尔订下约定，要提供一批特殊的精炼合金。运送合金离开湿地的商队遭到伏击，白洛尔丢失了货物，唯一幸存的护卫也因伤重而死。白洛尔一向以信守约定为傲，但如今运输工具已毁，合金又落入食人魔手中，他需要有人夺回被抢走的货物，让乔丹收到约定的东西。",al={"为什么帮助白洛尔","白洛尔的动机","白洛尔为什么要矿石"}},["8c6c3897"]={q="莫格罗什食人魔是什么人？",a="莫格罗什是一个野蛮的食人魔氏族，他们侵入洛克莫丹东北部的高地，在那里建立了莫格罗什要塞。他们凶狠而善于乘虚而入，经常袭击连接洛克莫丹与湿地的山口和商路，屠杀旅人，劫掠补给车上的原料、武器和食物。",al={"莫格罗什食人魔","谁抢走了矿石","洛克莫丹的食人魔"}},["6bcba9e0"]={q="白洛尔为什么需要冒险者，而不是当地的守卫？",a="当地的矮人守卫和巡山人既要抵御穴居人的暴动，又要维持洛克湖一带的防线，人手早已捉襟见肘。负责护送白洛尔合金的商队护卫在伏击中全军覆没，唯一的幸存者也在援兵赶到前死去。白洛尔既没有多余的兵力，也没有独自攻入食人魔要塞的本事，只能求助于有能力的冒险者。",al={"白洛尔为什么不派守卫","白洛尔为什么选我","为什么不派铁炉堡守卫"}}},fp="21,152,19.323.0,20.278.0,24.174.0,32.147.0,32.120.0,37.125.0,28.106.0,36.128.0"}
P.entries["quest:1656"] = {n="未完的任务",s="未完的任务是一个简单的送货任务，展现了年轻牛头人在红云台地接受成年试炼时承受的压力。试炼的重担加上父亲交代的差事，让一名年轻人疲惫不堪，于是请求路过的旅者将一捆毛皮送到台地下方血蹄村的旅店老板考乌斯手中。",h="未完的任务是一个简单的送货任务，展现了年轻牛头人在红云台地接受成年试炼时承受的压力。试炼的重担加上父亲交代的差事，让一名年轻人疲惫不堪，于是请求路过的旅者将一捆毛皮送到台地下方血蹄村的旅店老板考乌斯手中。",kw={"未完的任务","血蹄村","一捆毛皮","旅店老板考乌斯","莫高雷","红云台地","力量仪祭","牛头人"},ang={["faction:Horde"]="血蹄村是莫高雷旅者的重要聚集地，为穿越平原的部落成员提供温馨的庇护所和温暖的炉火。",["race:Tauren"]="年轻牛头人在红云台地接受艰苦的试炼，以证明自己的成熟与力量，而部族和家庭的责任往往与仪式中的挑战一样，考验着他们的耐力。"},sec={{t="台地上的试炼",b="在高高的红云台地上，年轻牛头人接受严苛的成年试炼，证明自己已准备好走向更广阔的世界。在传统仪式与部族日常杂务之间奔忙，足以让年轻人筋疲力尽。面对尚未完成的力量仪祭和父亲交代的一件急事，一名年轻牛头人向路过的旅者求助，请其帮忙将一捆毛皮送下台地。"},{t="炉火与庇护",b="这捆毛皮的目的地是血蹄村，那是坐落在下方开阔平原上的一处温馨港湾。旅店老板考乌斯热切地收下了送来的毛皮，打算将它们制成温暖的毯子，供疲惫的旅人使用。这趟差事既展现了平原牛头人的热情好客，也体现了休息的重要，表明每一场独自面对的力量试炼，都有族群的支持作为后盾。"}},faq={{q="未完的任务是什么任务？",a="未完的任务是红云台地上一名疲惫的年轻牛头人交托的差事。力量仪祭中接连不断的考验让这名年轻人不堪重负，于是请求路过的旅者代为将一捆毛皮送到血蹄村的旅店老板手中。",al={"未完的任务是什么","未完的任务任务信息","谁提供未完的任务任务"}},{q="旅店老板考乌斯是谁？",a="旅店老板考乌斯在莫高雷的血蹄村经营当地的旅店。他为那些从高耸台地走下、穿越平原的疲惫旅者提供温馨的歇脚处、温暖的毯子和热情的款待。",al={"旅店老板考乌斯是谁","考乌斯在哪里","血蹄村旅店老板"}},{q="为什么要把毛皮送到旅店？",a="这捆毛皮是年轻牛头人的父亲嘱咐送给旅店老板考乌斯的。考乌斯将这些结实的毛皮当作温暖的毯子，供前来血蹄村旅店寻求庇护和休息的客人使用。",al={"为什么要送毛皮","毛皮有什么用","莫高雷的一捆毛皮"}},{q="年轻牛头人为什么不能亲自送去毛皮？",a="这名年轻牛头人正在红云台地接受力量仪祭。试炼耗费了大量体力，使其疲惫不堪，若要一路走到下方的血蹄村，就可能无法完成神圣的仪式，或因疲劳而倒下。",al={"任务委托者为什么不能亲自送毛皮","年轻人为什么需要帮助"}},{q="力量仪祭是什么？",a="力量仪祭是台地上年轻牛头人的基础成年试炼之一。它考验这些未来部族守护者的体力、韧性与能力。",al={"力量仪祭是什么","力量仪祭牛头人试炼"}},{q="血蹄村坐落在哪里？",a="血蹄村是莫高雷草海平原上的一处主要聚居地，位于红云台地受庇护的高地之下。村中设有部族的重要设施，包括对外开放的旅店、制作物资供应处和贸易哨站。",al={"血蹄村在哪里","血蹄村位置"}}},fp="17,203,18.319.0,18.256.0,36.156.0,23.171.0,44.195.0,58.212.0,29.175.0,36.182.0"}
P.entries["quest:166"] = {n="迪菲亚兄弟会",s="在西部荒野，迪菲亚潜行者仍让农田笼罩在恐惧之中。格里安·斯托曼已在月溪镇地下找到他们的据点，号召对他们的首领发动最后一击。",h="在西部荒野，迪菲亚潜行者仍让农田笼罩在恐惧之中。格里安·斯托曼已在月溪镇地下找到他们的据点，号召对他们的首领发动最后一击。",kw={"死亡矿井","首级","重型战舰","民兵","月溪镇","石匠","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="身为潜行者，你将在范克里夫的腹地迎战这位著名的潜行者与工匠大师。这场交锋考验着每一位潜行者的训练成果。",["faction:Alliance"]="身为联盟的一员，你在暴风城王室无暇抽调自身军队之际，率先出击，保卫西部荒野这片粮仓。",["race:Human"]="身为王国的人类子民，范克里夫之死让你直面一场苦涩的悲剧：这位工匠曾从灰烬中重建你的都城。"},sec={{t="判决已下",b="格里安·斯托曼与人民军已在西部荒野各地同迪菲亚潜行者交战数月。如今，这伙盗贼藏在月溪镇地下的据点已经暴露。斯托曼下令刺杀艾德温·范克里夫，相信他的死能彻底平息这场叛乱。"},{t="深入迷宫",b="你将面对死亡矿井深处蜿蜒的矿道，叛变的石匠、地精工程师和厚重的钢铁防爆门守住了去路。在中央干船坞，范克里夫正监督他那艘巨大战舰的最后建造工作。他一死，维系整个匪徒网络的指挥体系便会瓦解。"},{t="更大阴谋的暗影",b="格里安·斯托曼相信，范克里夫之死将成为兄弟会覆灭的开端。然而，这位倒下的公会首领身上还留着一封未寄出的信。信中暗示，西部荒野的起义牵涉一张更庞大的关系网，其触角已伸入暴风城的贵族阶层。"}},faq={{q="这个任务的目标是什么？",a="格里安·斯托曼要求你进入月溪镇地下的死亡矿井，杀死艾德温·范克里夫，并将他的首级带回哨兵岭。",al={"任务目标","要做什么","这是什么任务"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫曾任石匠行会的首席石匠，并在兽人于第一次兽人战争中夷平暴风城后，领导了这座城市的重建工作。因报酬问题与贵族发生激烈争执后，他建立了迪菲亚潜行者，向王国复仇。",al={"范克里夫是谁","范克里夫身份","艾德温·范克里夫背景故事"}},{q="格里安·斯托曼为何下令刺杀？",a="人民军缺少来自暴风城的正规军增援，无力支撑长期战争。斯托曼认为，铲除兄弟会的首领，是西部荒野摆脱这个犯罪集团对农田控制的唯一现实机会。",al={"为何杀死范克里夫","斯托曼的动机","为何判处死刑"}},{q="在哪里可以找到艾德温·范克里夫？",a="艾德温·范克里夫藏身于月溪镇地下的死亡矿井深处。格里安·斯托曼要求你进入藏身处，找到他。",al={"范克里夫位置","艾德温·范克里夫在哪里","死亡矿井首领位置"}},{q="杀死范克里夫就能彻底消灭迪菲亚吗？",a="斯托曼希望范克里夫之死能打破兄弟会对西部荒野的控制。结果如何，以及是否还有进一步的发现，都有待这次进攻揭晓。",al={"迪菲亚被击败了吗","迪菲亚消失了吗","兄弟会的终结"}},{q="击败范克里夫后，会在他身上发现什么值得注意的物品？",a="斯托曼要求带回范克里夫的首级作为凭证。藏身处内的其他发现，要等到进攻时才能知晓。",al={"范克里夫掉落","未寄出的信","范克里夫掉落什么"}}},fp="22,178,17.250.0,18.274.1,31.236.1,31.134.0,22.274.0,50.230.0,34.127.0,52.140.1,55.107.1"}
P.entries["quest:1665"] = {n="巴特莱比的酒杯",s="在暴风城的猪和哨声旅店，巴特莱比要迎战一位接受试炼的年轻战士。击败他后，你将他的酒杯带给你的训练师哈里·伯加德。",h="在暴风城的猪和哨声旅店，巴特莱比要迎战一位接受试炼的年轻战士。击败他后，你将他的酒杯带给你的训练师哈里·伯加德。",kw={"巴特莱比","伯加德","酒杯","旧城区","猪和哨声旅店","暴风城","战士"},ang={["class:Warrior"]="作为暴风城的一名战士，你通过夺取巴特莱比的酒杯，证明自己能够应对桀骜不驯的敌人。",["faction:Alliance"]="作为联盟的一员，你知道旧城区那些不守规矩的酒客经常给暴风城的战斗训练师添麻烦。"},sec={{t="酒馆斗殴的战利品",b="在旧城区，哈里·伯加德用一场斗殴考验年轻的战士。他派你去挑战巴特莱比，一个守在猪和哨声旅店吧台边的顽固酒鬼。被制服后，巴特莱比不情愿地交出自己珍爱的酒杯。不过在那之前，他还要最后喝上一大口，把杯底的残酒喝光。"},{t="迈向精通的一步",b="当你带回酒杯时，哈里·伯加德收下它，作为你通过新手试炼的证明。他看到你能用武力让他人服从，认定你已经可以学习防御技巧。随后，他指引你去找艾尔文森林身经百战的老兵治安官哈迦德，接受进一步的战场指导。"}},faq={{q="哈里·伯加德为什么想要巴特莱比的酒杯？",a="哈里·伯加德想要巴特莱比的酒杯，以证明你与他交过手并战胜了他。巴特莱比嗜酒如命，肯交出自己的酒杯，就说明他输得心服口服。",al={"为什么要巴特莱比的酒杯","伯加德酒杯用途","击败巴特莱比的证明"}},{q="巴特莱比是谁？",a="巴特莱比是暴风城旧城区的猪和哨声旅店吧台边一个不守规矩的常客。他醉醺醺的，脾气暴躁，让当地的战士训练师有了一个考验新秀的非正式途径。",al={"巴特莱比背景故事","酒鬼巴特莱比是谁","巴特莱比旧城区"}},{q="这场打斗发生在哪里？",a="这场斗殴发生在暴风城旧城区的猪和哨声旅店内。",al={"巴特莱比在哪里","巴特莱比位置","猪和哨声旅店打斗"}},{q="把酒杯交还给伯加德后，接下来要做什么？",a="伯加德检查酒杯、确认你获胜后，会教你更高深的防御战斗姿态。随后，他会派你走出城门，去艾尔文森林寻找治安官哈迦德。",al={"巴特莱比的酒杯之后做什么","巴特莱比的酒杯后续任务","哈迦德任务"}},{q="巴特莱比会在斗殴中受到永久伤害吗？",a="不会。这场斗殴并不是要杀死巴特莱比。他会认输，喝完酒，交出酒杯，带着淤伤和受挫的自尊继续留在酒馆里。",al={"巴特莱比死了吗","巴特莱比有没有死","巴特莱比活下来了"}},{q="联盟的任何职业都能做这个任务吗？",a="只有联盟战士会接受这场试炼，这是他们十级时学习战斗姿态和防御技巧的训练内容。",al={"巴特莱比的酒杯仅限战士吗","谁能做巴特莱比任务","酒杯任务职业"}}},fx={["2bbd1f99"]={q="巴特莱比为什么交出他的酒杯？",a="巴特莱比肯交出心爱的酒杯，只因为你在酒馆斗殴中堂堂正正地打败了他。他原本不愿主动割爱，但既然已经被打得服输，也就信守约定认了输——不过在那之前，他还不忘匆忙喝光杯里的剩酒。",al={"巴特莱比为什么交出酒杯","巴特莱比的动机","为什么交出酒杯"}}},fp="14,158,24.272.0,21.305.0,45.178.0,16.184.0,33.80.0,48.191.0,48.151.0,37.122.0"}
P.entries["quest:1666"] = {n="治安官哈迦德",s="在东谷，治安官哈迦德保管着他戎马一生收集的武器。哈里·伯加德让暴风城的新手战士前去拜访这位退役元帅，寻求更好的武器。",h="在东谷，治安官哈迦德保管着他戎马一生收集的武器。哈里·伯加德让暴风城的新手战士前去拜访这位退役元帅，寻求更好的武器。",kw={"东谷","东谷伐木场","艾尔文森林","哈里·伯加德","治安官哈迦德","暴风城","战士"},ang={["class:Warrior"]="身为联盟战士，你离开暴风城的正规训练场，踏入荒野寻找武器。",["faction:Alliance"]="身为联盟战士，你沿袭暴风城的做法，依靠退役老兵和他们的私人储备，为成为新一代守卫者做好准备。"},sec={{t="老兵的武库",b="暴风城的新手战士要面对城外的危险，光有技巧还不够。哈里·伯加德让有潜力的战士向东穿过艾尔文森林，去拜访治安官哈迦德，一位为王国效力多年的退役军官。哈迦德在漫长的征战岁月中积攒了一座私人武库。他在东谷伐木场附近的家中存放着武器，可供年轻战士寻求更好的装备。"},{t="东谷的退隐生活",b="治安官哈迦德住在东谷伐木场附近一座僻静的庄园里。多年的军旅生涯使他的视力衰退，他有时会将走近的旅人误认成四处游荡的河爪豺狼人。年迈的他留在了艾尔文东部这个安静的角落。即便如此，暴风城的卫兵和训练师依然敬重这位老元帅。"}},faq={{q="这个任务由谁发起？",a="暴风城的战士训练师哈里·伯加德会让有潜力的年轻战士前去拜访治安官哈迦德。",al={"哪里接治安官哈迦德任务","谁提供治安官哈迦德任务","治安官哈迦德任务给予者"}},{q="治安官哈迦德在哪里？",a="治安官哈迦德住在东谷伐木场东边不远的一座庄园里，那里位于艾尔文森林最东部，靠近赤脊山边界。",al={"治安官哈迦德位置","哈迦德在哪里","东谷伐木场庄园"}},{q="哈里·伯加德为什么让你去找哈迦德？",a="哈里·伯加德让你去找治安官哈迦德，是因为年轻战士需要比训练用剑更好的武器。哈迦德在漫长的军旅生涯中收集了许多武器和护甲，或许会将它们分给那些证明了自身价值的人。",al={"为什么找治安官哈迦德","战士为什么去东谷","治安官哈迦德任务目的"}},{q="哈迦德为什么会把访客误认成豺狼人？",a="治安官哈迦德的视力随着年岁增长而衰退。豺狼人不断袭扰艾尔文森林东部的伐木作业和边远地带，让这位老兵对突然到来的访客心存戒备。",al={"哈迦德视力","哈迦德失明了吗","哈迦德豺狼人对话"}},{q="完成这个任务后会发生什么？",a="你向治安官哈迦德问候后，他会派你去对付蛀牙杰克，以此考验你的勇气，然后才会考虑将库存中的武器分给你。",al={"治安官哈迦德下一个任务","治安官哈迦德后续任务"}},{q="战士以外的职业也能接取这个任务吗？",a="不能。这条任务路线专为战士设置，是他们在十级左右接受训练的一部分，也是为应对艾尔文森林之外的危险做准备。",al={"圣骑士能做治安官哈迦德任务吗","战士专属任务哈迦德"}}},fp="15,194,18.383.0,22.319.0,22.104.0,33.137.0,45.223.0,45.169.0,39.150.1,55.129.0"}
P.entries["quest:1667"] = {n="蛀牙杰克",s="在艾尔文森林东部，退休的治安官哈迦德需要你的帮助：蛀牙杰克骗走了他的徽章。杰克身穿暴风城战袍，假扮成治安官杜汉。哈迦德担心迪菲亚潜行者会利用这枚徽章冒充暴风城官员。",h="在艾尔文森林东部，退休的治安官哈迦德需要你的帮助：蛀牙杰克骗走了他的徽章。杰克身穿暴风城战袍，假扮成治安官杜汉。哈迦德担心迪菲亚潜行者会利用这枚徽章冒充暴风城官员。",kw={"徽章","蛀牙杰克","迪菲亚","艾尔文森林","卫兵伯加德","冒充身份","治安官杜汉","治安官哈迦德","保险箱"},ang={["class:Rogue"]="身为盗贼，你能看出蛀牙杰克的这场勾当，既靠粗暴的拦路抢劫，也同样靠伪装、欺骗和厚颜无耻。",["class:Warrior"]="治安官哈迦德曾是一位久经沙场的前线战士。身为战士，你可以赢得他的感谢，并从他服役多年留下的备用武器中挑选一件。",["race:Human"]="身为暴风城的人类，你能看出王国乡间的边境多么容易遭到迪菲亚渗透者的侵袭。他们穿着王国自己的战袍，欺骗退休老兵。"},sec={{t="夜色中的骗局",b="夜里，一个身穿暴风城战袍的人来到哈迦德位于艾尔文东部山脊上的偏僻小屋。这个陌生人声称前来办理公务，索要哈迦德从前的治安官徽章。哈迦德以为自己是在把徽章交给一位同僚，便将它交了出去。那人放声大笑，随后消失在树林中。他是一名叫作蛀牙杰克的迪菲亚盗贼。"},{t="冒用职权的威胁",b="治安官哈迦德虽然已经退休，但他的徽章仍代表着暴风城的法定权力。迪菲亚匪徒正悄悄渗入艾尔文、西部荒野和赤脊山。有了这枚徽章，他们就能通过卫兵的哨卡、调动巡逻队，或是接管物资。杰克退回南边的一处营地，把徽章锁进了保险箱。哈迦德必须在迪菲亚造成严重危害之前拿回徽章。"}},faq={{q="蛀牙杰克是谁？",a="蛀牙杰克是在艾尔文森林东部活动的一名迪菲亚成员。他趁着夜色假扮治安官杜汉，骗退休的治安官哈迦德交出了代表暴风城官方身份的徽章。",al={"蛀牙杰克","蛀牙是谁","蛀牙杰克背景故事"}},{q="治安官哈迦德为什么需要拿回徽章？",a="治安官哈迦德需要拿回徽章，因为它是代表暴风城权力的真正凭证。他担心迪菲亚会利用它冒充官员、避开军队巡逻，在王国各地制造混乱。",al={"为何找回徽章","哈迦德的徽章","徽章为何重要"}},{q="杰克是怎么骗过治安官哈迦德的？",a="杰克身穿暴风城战袍，在夜里来到哈迦德的小屋。昏暗中，哈迦德把他错认成了闪金镇的治安官杜汉，以为自己是在帮助同僚，便把徽章交给了他。",al={"他如何骗过哈迦德","哈迦德受骗","哈迦德为何交出徽章"}},{q="杰克把偷来的徽章藏在哪里？",a="杰克把偷来的徽章锁在匪徒营地的保险箱里，营地就在治安官哈迦德的房子南边。钥匙由他随身携带。",al={"徽章位置","徽章在哪里","蛀牙营地"}},{q="最初是谁派你去找治安官哈迦德的？",a="哈里·伯加德是一位经验丰富的战士，常去暴风城的猪和哨声旅店，他会指引冒险者去找治安官哈迦德。他知道这位退休的治安官或许愿意拿备用武器换取帮助。",al={"谁指引来此","伯加德","起始任务给予者"}},{q="归还徽章后会发生什么？",a="治安官哈迦德终于大大松了口气，迪菲亚再也无法利用他的身份或军衔危害王国了。他向你敬礼致谢，并让你从他服役多年留下的军用武器中挑选一件，这些武器都保养得很好。",al={"交付任务","哈迦德的反应","归还徽章"}}},fx={["5b8b35d8"]={q="治安官哈迦德的徽章有什么用？",a="治安官哈迦德的徽章曾是暴风城军队中高级职权的象征，如今已随主人退役。在正直的人手中，它是哈迦德服役多年留下的珍贵传家之物。然而，落入迪菲亚潜行者手中后，这枚正式的治安官徽章就能让盗贼和强盗冒充暴风城军官，混过关卡，在王国各地策划危险的骗局。",al={"哈迦德的徽章的用途","徽章有什么用","徽章为什么危险"}},["55355d07"]={q="治安官哈迦德为什么需要你找回徽章？",a="哈迦德早已退役，住在偏僻的小屋里，被一名潜行者趁黑骗了，让他觉得很难堪。向镇上的驻军或治安官杜汉求助，就意味着承认自己把正式徽章亲手交给了一名迪菲亚盗贼，而暴风城的守卫光是保卫城镇就已人手不足。你来找他索取备用武器，正好让他有了一位既有本事又能保守秘密的帮手，替他讨回这笔账。",al={"哈迦德为什么需要我","哈迦德为什么不自己取回","为什么不找守卫"}}},fp="15,277,17.370.0,29.385.0,23.184.0,45.209.0,44.205.0,38.136.0,51.191.0,40.215.1"}
P.entries["quest:167"] = {n="我的兄弟……",s="月溪镇地下发生塌方后，维尔德·蓟草在暴风城等候。他请你到矿井里寻找他的兄弟工头希斯耐特，或找回这位矮人的探险者协会徽章。",h="月溪镇地下发生塌方后，维尔德·蓟草在暴风城等候。他请你到矿井里寻找他的兄弟工头希斯耐特，或找回这位矮人的探险者协会徽章。",kw={"徽章","死亡矿井","探险者协会","月溪镇","暴风城","蓟草","亡灵","西部荒野","维尔德"},ang={["faction:Alliance"]="作为联盟的旅人，你可以看到迪菲亚和地下的恐怖之物如何伤害暴风城附近的无辜民众。",["race:Dwarf"]="作为矮人，一位探险者协会工头在人类领地的殒命，会让你想到兄弟情谊、凿石技艺，以及League孜孜不倦的工作。"},sec={{t="受困的探险队",b="维尔德·蓟草和他的兄弟曾在月溪镇地下的坑道里为一家采矿公司工作。盗贼涌入矿井，随后一场塌方封死了下层通道。维尔德逃到了暴风城，但他的兄弟和其余矿工仍被困在碎石后面。"},{t="工头希斯耐特的悲惨命运",b="工头希斯耐特被困在碎石之下，未能生还。废弃矿井中的黑暗能量将这位矮人复生为一具亡灵躯壳。他与其他不得安息的尸体一同在坑道里游荡，身上带着探险者协会徽章，那是他生前身份最后的信物。"}},faq={{q="在哪里接取任务“我的兄弟. . .”？",a="维尔德·蓟草在暴风城的矮人区交付这项搜寻任务。",al={"我的兄弟任务给予者","谁给予我的兄弟任务","哪里接我的兄弟任务"}},{q="工头希斯耐特在哪里？",a="工头希斯耐特在西部荒野月溪镇地下的矿井外围通道里游荡，就在通往传送门的坑道沿途某处。",al={"工头希斯耐特位置","蓟草在哪里","兄弟在哪里"}},{q="工头希斯耐特遭遇了什么？",a="一场塌方将工头希斯耐特和他的采矿队困在洞穴里，此后他们便杳无音信。维尔德需要找到他的兄弟，或至少找回他的徽章，才能弄清发生了什么。",al={"蓟草还活着吗","兄弟遭遇了什么","蓟草背景故事"}},{q="需要取回什么物品？",a="你需要取回工头希斯耐特一直随身携带的探险者协会徽章。在死亡矿井的坑道深处找到他，徽章就在他身上。",al={"我的兄弟任务物品","我的兄弟任务掉落什么"}},{q="探险队在月溪镇做什么？",a="蓟草兄弟原本在月溪镇地下为一家采矿公司工作，后来遭到迪菲亚强盗伏击，一场突如其来的塌方又将他们分隔两地。",al={"矮人为何在西部荒野","探险者协会死亡矿井","他们为何在月溪镇"}},{q="这个任务是在死亡矿井副本内完成的吗？",a="不是。你可以在通往传送门、争夺不断的矿井坑道里找到工头希斯耐特，无须进入副本。他是一个精英敌人。",al={"我的兄弟是否在死亡矿井副本内","是否需要副本队伍"}}},fp="15,259,20.273.0,38.257.1,45.76.0,39.136.0,39.189.1,32.154.1,43.142.0,62.141.0"}
P.entries["quest:1678"] = {n="维吉雷克",s="在霜鬃巨魔要塞以南的山麓，你要迎战维吉雷克，证明自己的实力。穆伦·雷矛想要证据，证明你能应付真正的敌人。通过考验后，你将开始学习如何进行坚实的防御。",h="在霜鬃巨魔要塞以南的山麓，你要迎战维吉雷克，证明自己的实力。穆伦·雷矛想要证据，证明你能应付真正的敌人。通过考验后，你将开始学习如何进行坚实的防御。",kw={"霜鬃巨魔要塞","铁炉堡","实力","穆伦·雷矛","坚实的防御","巨魔","维吉雷克"},sec={{t="实力的考验",b="穆伦·雷矛说，你得足够坚韧，他才能教你新的招式。维吉雷克是这一带最强悍的巨魔，他的小屋位于霜鬃巨魔要塞以南的山麓。穆伦要你带回维吉雷克的头颅，证明你能应付真正的敌人。"},{t="防御的教导",b="穆伦收下维吉雷克的头颅，说你具备所需的实力。他已准备好教你如何进行坚实的防御，让你面对足以击倒他人的敌人时仍能屹立不倒，并支援盟友。"}},faq={{q="维吉雷克是谁？",a="据说维吉雷克是这一带最强悍的巨魔。他的小屋位于霜鬃巨魔要塞以南的山麓。",al={"维吉雷克是谁","巨魔维吉雷克","那个巨魔"}},{q="穆伦为什么派我去对付维吉雷克？",a="穆伦想先得到你能应付真正敌人的证据，再教你新的招式。",al={"为什么杀维吉雷克","穆伦的考验","证明实力"}},{q="维吉雷克的小屋在哪里？",a="维吉雷克的小屋位于霜鬃巨魔要塞以南的山麓。",al={"维吉雷克的位置","他的小屋在哪里","山麓的巨魔"}},{q="穆伦要我带回什么？",a="穆伦要你带回维吉雷克的头颅，作为你实力的证明。",al={"维吉雷克的头颅","带回什么","穆伦要什么"}},{q="通过考验后，穆伦会教什么？",a="穆伦收下维吉雷克的头颅后，便开始教你如何进行坚实的防御。他会讲解这种防御如何帮助你在面对敌人时屹立不倒。",al={"穆伦的教导","教什么","坚实的防御"}}},fp="6,181,16.258.0,10.195.1,14.112.0,36.80.0,22.59.0,34.69.0,37.132.0"}
P.entries["quest:1679"] = {n="穆伦·雷矛",s="在铁炉堡，穆伦·雷矛等待着从卡拉诺斯前来接受正规训练的战士。格兰尼斯·快斧将那些在丹莫罗证明了自身勇气与实力的新兵派往城中的军事区。",h="在铁炉堡，穆伦·雷矛等待着从卡拉诺斯前来接受正规训练的战士。格兰尼斯·快斧将那些在丹莫罗证明了自身勇气与实力的新兵派往城中的军事区。",kw={"防御姿态","格兰尼斯·快斧","武器大厅","铁炉堡","卡拉诺斯","军事区","穆伦·雷矛","战士训练师"},ang={["class:Warrior"]="身为战士，这次召唤标志着你从新兵成长为纪律严明的士兵，准备坚守战线、保护盟友。",["race:Dwarf"]="身为矮人战士，前往武器大厅报到，将使你接触到山地氏族的尚武传统与战术纪律。",["race:Gnome"]="身为侏儒战士，在诺莫瑞根陷落、族人被迫迁往丹莫罗之后，你依靠铁炉堡的武器大厅学习传统的前线重装作战技艺。"},sec={{t="铁炉堡的召唤",b="格兰尼斯·快斧会将那些在丹莫罗应对过当地威胁、展现出潜力的战士从卡拉诺斯派往铁炉堡。他知道，零星的遭遇战能教会他们的终究有限。在军事区，资深战士负责指导正规训练，为即将奔赴战场的人做好准备。"},{t="武器大师",b="在武器大厅，你会见到穆伦·雷矛，一位出身于传奇矮人氏族的老兵。他希望看到证据，证明新来的学员能够经受实战，而非只会在酒馆里吹嘘。向他报到后，你便能开始学习防御技巧、掌控敌人的仇恨，并赢得用于前线作战的钢铁武器。"}},faq={{q="谁派你去找穆伦·雷矛？",a="在你于丹莫罗证明自己掌握了基本战斗技巧后，卡拉诺斯的战士训练师格兰尼斯·快斧会派你前去。",al={"谁发布 穆伦·雷矛 任务","哪里接取 穆伦·雷矛","穆伦·雷矛 任务发布者"}},{q="穆伦·雷矛在哪里？",a="穆伦·雷矛位于铁炉堡东侧军事区的武器大厅。",al={"穆伦·雷矛 在哪里","穆伦·雷矛 位置","如何找到 穆伦"}},{q="这个任务为何对战士很重要？",a="向穆伦报到意味着开始接受进阶战士训练。此后，你将学习 防御姿态 和 嘲讽，并获得一件适合初期使用的可靠武器。",al={"穆伦·雷矛 解锁什么","为何做 穆伦·雷矛","穆伦·雷矛 奖励"}},{q="穆伦·雷矛是谁？",a="穆伦·雷矛是铁炉堡一位经验丰富的战斗教官，也是雷矛氏族的一员，这个矮人家族以战士和远征工程师闻名。",al={"穆伦 是谁","穆伦·雷矛 背景故事","穆伦 属于 雷矛 氏族吗"}},{q="任何职业都能接取这个任务吗？",a="不能。只有准备好接受专门战斗训练的战士新兵才能接取。",al={"非战士能做 穆伦·雷矛 吗","穆伦·雷矛 仅限战士吗","穆伦·雷矛 职业"}},{q="向穆伦报到后会发生什么？",a="与穆伦交谈后，他会派你参加对抗维吉雷克的战斗试炼，以考验你的决心。",al={"穆伦·雷矛 之后做什么","穆伦·雷矛 后续任务","维吉雷克 任务"}}},fx={["61377fd6"]={q="格兰尼斯·快斧为什么派你去找穆伦·雷矛？",a="格兰尼斯·快斧看出你的战斗本领很有潜力，但卡拉诺斯只能教给你基础。为了让你继续磨炼武艺，明白成为战士的真正含义，他推荐你去找穆伦·雷矛，那是一位驻守在铁炉堡武器大厅的老兵。",al={"格兰尼斯·快斧的动机","为什么派去找穆伦","为什么与穆伦·雷矛交谈"}}},fp="15,188,22.252.0,18.287.0,38.116.0,33.89.0,41.143.0,23.162.0,30.76.0,38.100.0"}
P.entries["quest:168"] = {n="收集记忆",s="在暴风城，维尔德·蓟草请你铭记那些在月溪镇地下遇难的矿工。他希望找回他们的矿业工会会员卡，交还给悲痛的家属。",h="在暴风城，维尔德·蓟草请你铭记那些在月溪镇地下遇难的矿工。他希望找回他们的矿业工会会员卡，交还给悲痛的家属。",kw={"收集记忆","死亡矿井","矿业工会会员卡","月溪镇","暴风城","亡灵矿工","维尔德·蓟草"},ang={["faction:Alliance"]="身为联盟的一员，你可以帮助西部荒野工人悲痛的家属，他们在暴风城的城墙内艰难度日。",["profession:Mining"]="身为矿工，你深知矿井塌方有多么可怕。找回遗失的工会卡片，让这份恐惧多了一层沉重与肃穆。",["race:Dwarf"]="身为矮人，你深知在地下结成的情谊，也明白应当如何尊重逝去的同胞。维尔德·蓟草的恳求令你感同身受。"},sec={{t="塌方惨剧",b="在月溪镇陷入混乱、迪菲亚潜行者盘踞此地之前，西部荒野的矿井养活了许多工人家庭。一次塌方掩埋了一侧的矿道，维尔德·蓟草侥幸生还。他的许多朋友和矿工同伴死在地下，救援人员无法抵达那里。他们在暴风城的家属始终未能确知他们的下落。"},{t="不得安息的亡骸",b="在塌方中丧生的矿工如今化为亡灵，在主要冶铁设施外围的矿道中游荡。你在这些闹鬼的通道中寻找矿业工会会员卡，面对那些曾与维尔德·蓟草并肩劳作的人的亡骸。将这些卡片带回暴风城，就能让他们的家属得知真相，也让维尔德·蓟草悼念逝去的同伴。"}},faq={{q="维尔德·蓟草是谁？",a="维尔德·蓟草是暴风城的一名矮人矿工。他在西部荒野地下的一次塌方中幸存，与他关系密切的工友却不幸遇难，他希望让他们的家属得知确切的消息，获得安宁。",al={"维尔德·蓟草","任务给予者","谁给予收集记忆任务"}},{q="死亡矿井的矿工遭遇了什么？",a="一次塌方将一队矿工困在月溪镇挖掘场一侧的矿道中，导致他们丧生。他们的躯体和灵魂如今化为亡灵，在废弃的通道中徘徊。",al={"为什么会有亡灵矿工","矿井塌方","死亡矿井塌方"}},{q="维尔德·蓟草为什么想找回他们的矿业工会会员卡？",a="矿业工会会员卡可以确认在塌方中遇难的工人的身份。由于他们的遗体始终未能寻回，维尔德·蓟草希望归还这些卡片，让他们在暴风城的家属得知事情的经过。",al={"工会卡片有什么用","矿业工会会员卡"}},{q="在哪里能找到工会卡片？",a="这些卡片散落在月溪镇地下闹鬼的外围矿道中，就在通往死亡矿井内部、有人把守的入口前的走廊里。",al={"在哪里找卡片","死亡矿井亡灵位置","遇难矿工在哪里"}},{q="塌方是迪菲亚潜行者造成的吗？",a="维尔德·蓟草记得那是一场可怕的采矿事故和塌方。迪菲亚潜行者如今控制着深处的通道，但那次塌方似乎是一场将矿工困住的生产事故。",al={"塌方是迪菲亚潜行者造成的吗","谁导致矿井塌方"}},{q="这些矿工算是迪菲亚潜行者的成员吗？",a="不是。塌方发生时，他们只是普通的工会劳工。他们化为亡灵的遗骸在洞穴边缘游荡，与更深处艾德温·范克里夫麾下有组织的迪菲亚潜行者部队并无关联。",al={"遇难矿工是迪菲亚潜行者吗","亡灵矿工与迪菲亚潜行者是一伙的吗"}}},fp="19,167,17.348.0,16.333.0,28.194.0,45.152.0,47.198.0,32.131.0,45.194.0,57.175.0"}
P.entries["quest:1680"] = {n="托姆斯·深炉",s="在铁炉堡，托姆斯·深炉等待着穆伦·雷矛派来的战士。在为他们锻造武器之前，他要求他们接受一场危险的试炼。",h="在铁炉堡，托姆斯·深炉等待着穆伦·雷矛派来的战士。在为他们锻造武器之前，他要求他们接受一场危险的试炼。",kw={"矮人铁匠","大锻炉","铁炉堡","穆伦·雷矛","托姆斯·深炉","战士任务","武器锻造师"},ang={["class:Warrior"]="穆伦·雷矛将前途可期的战士派往铁炉堡，去找托姆斯·深炉。在那里，他们证明自己的胆识，寻求一把为战士之道而锻造的武器。",["faction:Alliance"]="铁炉堡的锻造大师会先用危险的任务考验前途可期的联盟战士，再为他们锻造精良的武器。"},sec={{t="铁匠的铁砧",b="托姆斯·深炉是铁炉堡的一位矮人武器锻造大师。向穆伦·雷矛展现出日益精进的技艺后，战士们便会被派往城中另一头，向他请教。托姆斯以锻造坚固强力的武器闻名，但他不会为每个过路人提供精良的刀剑或钝器。战士必须用行动赢得他亲手锻造的武器。"},{t="危险的试炼",b="在答应锻造武器之前，托姆斯会要求冒险者答应帮他一个忙。他直言前路的危险，并警告说，这件事可能让人丧命。在他看来，危险不是退缩的理由。这正是考验战士胆识的恰当方式。"}},faq={{q="托姆斯·深炉是谁？",a="托姆斯·深炉是铁炉堡一位技艺精湛的武器锻造师。他能为那些通过危险行动证明自身勇气与能力的战士锻造非凡的武器。",al={"托姆斯是谁","托姆斯·深炉 铁炉堡","托姆斯·深炉是谁"}},{q="是谁派你去找托姆斯·深炉交谈的？",a="当那些前途可期的战士武艺日益精进，需要一把相称的武器时，穆伦·雷矛便会派他们去找托姆斯·深炉。",al={"谁派我去找托姆斯","为什么要和托姆斯交谈","穆伦·雷矛引荐"}},{q="托姆斯·深炉要求什么作为锻造武器的回报？",a="托姆斯会在冒险者帮他一个忙后，答应锻造一把精良的武器。他要求冒险者承担一项可能致命的危险任务，在他看来，这正是有志成为勇士的人所追求的挑战。",al={"帮托姆斯的忙","托姆斯会打造什么武器","托姆斯想要什么"}},{q="托姆斯为什么强调这项差事很危险？",a="托姆斯警告说，这项任务十分危险，因为它可能让人丧命。他认为，对于任何配得上他手艺的人，危险都是恰当的考验。",al={"托姆斯·深炉危险吗","托姆斯的任务是什么","铁炉堡 战士任务 托姆斯"}},{q="在哪里可以找到托姆斯·深炉？",a="托姆斯·深炉在铁炉堡的大锻炉附近工作。他的周围是其他铁匠、铁砧和轰鸣的熔炉。",al={"托姆斯在哪里","托姆斯·深炉位置"}},{q="托姆斯·深炉会与哪些冒险者打交道？",a="托姆斯会与训练师派来的战士打交道。他寻找的是有勇气和决心面对致命危险的战士。",al={"哪个职业能接托姆斯的任务","托姆斯只接待战士吗"}}},fp="16,149,22.311.0,16.250.0,24.168.0,45.132.0,61.194.0,52.145.0,36.115.0,50.128.0"}
P.entries["quest:1681"] = {n="铁环营地",s="在铁环营地，托姆斯·深炉寻求为遇害的导师斯塔基·铁环复仇。稀有的暗影矿石将黑铁矮人引到了这座前哨，并招致了它的覆灭。",h="在铁环营地，托姆斯·深炉寻求为遇害的导师斯塔基·铁环复仇。稀有的暗影矿石将黑铁矮人引到了这座前哨，并招致了它的覆灭。",kw={"锻造","黑铁","丹莫罗","盔枕湖","铁环营地","斯塔基·铁环","托姆斯·深炉","暗影矿石"},ang={["profession:Blacksmithing"]="斯塔基·铁环的命运表明，未经试验的矿石可能给锻造坊带来危险。",["race:Dwarf"]="铁环的前哨遭到袭击，反映出铁炉堡的铜须矮人与他们的黑铁同族之间刻骨的仇恨。"},sec={{t="大师之殇",b="在盔枕湖南面的营地里，斯塔基·铁环传授着锻造技艺，远离大锻炉那些拥挤的铁砧。满怀前途的学徒们来到这里，向这位全铁炉堡公认无人能及的名师求教。后来，一名学生得到了一种陌生的矿物，名为暗影矿石，斯塔基决定用它进行试验。他并不知道，这种矿物的出现已为他的学堂招来了灭顶之灾。"},{t="黑铁的突袭",b="暗影矿石运抵后不久，黑铁矮人袭击了营地。他们杀死了斯塔基·铁环和他教导的所有学徒，随后占据了这里。托姆斯·深炉是铁环留在都城、幸免于难的弟子之一，他决不肯让这场屠杀就此不了了之。他派遣联盟旅人为老师复仇，并取回给这座前哨带来毁灭的矿石。"}},faq={{q="铁环营地位于何处？",a="铁环营地位于丹莫罗东部，盔枕湖以南。",al={"铁环位置","营地在哪","寻找铁环营地"}},{q="斯塔基·铁环是谁？",a="斯塔基·铁环是一位著名的矮人锻造大师，在铁炉堡外的一处营地传授高深的金属加工技艺。黑铁矮人在一次突袭中杀害了他。",al={"铁环是谁","斯塔基·铁环背景","斯塔基是谁"}},{q="黑铁矮人为何袭击营地？",a="铁环的一名学生将暗影矿石带到了营地，引来了黑铁矮人。矿石运抵后不久，他们便发动袭击，杀死了在场的所有人，并控制了这里。",al={"为何袭击","黑铁为何突袭","黑铁动机"}},{q="暗影矿石是什么？",a="暗影矿石是一种罕见而神秘的矿物，引起了铁环大师的兴趣。它的到来引来了黑铁氏族的致命关注。",al={"暗影矿石背景","暗影是什么","奇怪的矿石"}},{q="托姆斯·深炉是谁？",a="托姆斯·深炉是铁炉堡的一名铁匠，曾是斯塔基·铁环的学徒。他悲痛于老师的死，派遣旅人惩治黑铁入侵者并取回矿石。",al={"铁环营地任务由谁提供","托姆斯·深炉背景","深炉是谁"}},{q="托姆斯希望从营地取回什么？",a="托姆斯希望旅人赶走黑铁袭击者，为铁环复仇，并取回那批招致灾难的暗影矿石。",al={"取回什么","营地任务目标","交付任务"}}},fp="19,174,15.393.0,18.392.0,37.73.0,24.162.0,50.191.0,19.146.0,24.190.0,50.147.0"}
P.entries["quest:1683"] = {n="沃鲁斯·邪蹄",s="在达纳苏斯，年轻的暗夜精灵战士要接受艾兰娜瑞设下的试炼。他们必须猎杀一只萨特，它玷污了班奈希尔兽穴附近一处隐秘的月亮井。",h="在达纳苏斯，年轻的暗夜精灵战士要接受艾兰娜瑞设下的试炼。他们必须猎杀一只萨特，它玷污了班奈希尔兽穴附近一处隐秘的月亮井。",kw={"班奈希尔","达纳苏斯","艾兰娜瑞","沃鲁斯的角","月亮井","萨特","泰达希尔","沃鲁斯·邪蹄","战士任务"},ang={["class:Warrior"]="作为战士，猎杀沃鲁斯是你接受高深战斗训练的开端。这证明你的利刃守护着卡多雷的土地与女神的圣洁。",["faction:Alliance"]="作为联盟的一员，你帮助清除泰达希尔腹地潜伏的恶魔余孽，让达纳苏斯继续成为联盟在卡利姆多北部的坚固堡垒。",["race:NightElf"]="作为暗夜精灵，你深知月亮井映照着Elune的纯洁，也是卡多雷精神信仰的命脉。一只萨特在井水中沐浴，是对所有暗夜精灵的侮辱。"},sec={{t="决心的考验",b="艾兰娜瑞要求你先证明自己的奉献精神与自律，才会传授高深的战斗技巧。对于保卫卡利姆多的人，她要看到的不只是言辞。守护者必须直面腐化，净化泰达希尔的神圣枝干。"},{t="亵渎圣水",b="你的试炼目标是沃鲁斯·邪蹄，一只藏身于班奈希尔兽穴东南方群山中一处月亮井的萨特。萨特曾是上古时期的背叛者，受到恶魔力量的影响而扭曲，憎恨卡多雷的神圣遗物。沃鲁斯在月亮井中沐浴，污染受祝福的井水，嘲弄艾露恩的恩典。"},{t="取下萨特之角",b="瘤背熊怪守着一条隐蔽的山路，通往沃鲁斯的藏身之处。在被污染的泉水旁，你将与这只萨特交战。将他的角带回达纳苏斯的战士区，作为他已死的证明。林间空地的圣洁便能恢复，你也将获得研习专门战斗武器的机会。"}},faq={{q="沃鲁斯·邪蹄是谁？",a="沃鲁斯·邪蹄是一只栖居在泰达希尔的堕落萨特。他在班奈希尔兽穴东南方找到了一处僻静的月亮井，开始在圣水中沐浴，将其玷污。",al={"沃鲁斯·邪蹄背景故事","沃鲁斯是谁","萨特沃鲁斯"}},{q="艾兰娜瑞为何派战士追杀沃鲁斯？",a="艾兰娜瑞派你追杀沃鲁斯，是为了考验有潜力的战士。击败这个危险而堕落的恶徒，能证明你具备所需的专注、勇气与决心，她才会传授高深的战斗技巧，或指导你锻造专门的武器。",al={"为何杀死沃鲁斯","艾兰娜瑞任务缘由","沃鲁斯·邪蹄任务目的"}},{q="隐秘的月亮井在哪里？",a="隐秘的月亮井位于班奈希尔兽穴东南方的山岭中。在兽穴东面的瘤背熊怪营地后方，可以找到一条不起眼的山路，沿途点着火把。",al={"沃鲁斯位置","如何找到沃鲁斯","隐秘月亮井路径"}},{q="月亮井是什么，他的存在为何如此严重？",a="月亮井是盛有受祝福之水的神圣水池，传导艾露恩的光辉，维系自然的生机。带有恶魔力量的萨特在其中沐浴，既亵渎了卡多雷的信仰，也给泰达希尔带来了危险的腐化之源。",al={"月亮井为何重要","月亮井遭亵渎","暗夜精灵月亮井"}},{q="击败沃鲁斯·邪蹄之后会怎样？",a="当你带回从沃鲁斯身上砍下的角后，艾兰娜瑞便会满意，确认你已准备就绪。她会指引你继续追寻传说中的月神武器，首先要找到艾鲁拉的阴影。",al={"沃鲁斯后续任务","接下来会怎样","艾鲁拉的阴影任务"}},{q="泰达希尔还有其他萨特吗？",a="有。萨特潜伏在泰达希尔各处，包括地狱石和零散的腐化谷地，企图用恶魔的污秽侵染世界之树。",al={"泰达希尔的萨特","泰达希尔萨特威胁"}}},fp="15,142,17.236.0,26.296.0,17.278.1,23.187.0,45.234.0,37.186.0,53.218.0,43.168.1,37.142.0"}
P.entries["quest:1685"] = {n="加科因的召唤",s="在暴风城，加科因的召唤将有潜力的术士召至已宰的羔羊地下。雷门·玛考特带来黑暗缚灵者加科因的口信，指引初入门的术士前往法师区酒馆下的墓穴，接受更深入的秘术训练。",h="在暴风城，加科因的召唤将有潜力的术士召至已宰的羔羊地下。雷门·玛考特带来黑暗缚灵者加科因的口信，指引初入门的术士前往法师区酒馆下的墓穴，接受更深入的秘术训练。",kw={"恶魔学","黑暗缚灵者加科因","法师区","雷门·玛考特","已宰的羔羊","暴风城","虚空行者","术士"},ang={["class:Warlock"]="身为术士，你正逐渐超越那些雕虫小技和弱小的小鬼。前方的试炼将让你做好准备，奴役一只虚空行者，在战斗中为你抵挡攻击。",["faction:Alliance"]="身为联盟的一员，你知道暴风城容忍着一个暗中操纵暗影的秘密团体。他们对邪能的精通，让联盟在对抗敌人时占据优势。"},sec={{t="一则秘密口信",b="暴风城的居民区禁止研习恶魔学，但研习者就在城市卫兵附近活动。当一名术士展现出操控初级小鬼的本领时，消息便会秘密传到资深术士耳中。雷门·玛考特悄悄传达他们的口信，叮嘱新入门者前往法师区地下时，务必对会面地点保密。"},{t="已宰的羔羊的墓穴",b="已宰的羔羊朴素的门面后，藏着地窖和隐秘的地下墓穴。黑暗缚灵者加科因在那里教导暴风城的术士，避开肯瑞托法师和大教堂审判官的耳目。在他的指导下，术士们学习如何控制虚空行者。这项仪式需要危险的窃取而来的施法材料，还要使用凶险的召唤法阵。"}},faq={{q="黑暗缚灵者加科因为何召集术士？",a="初出茅庐的术士积累了足够的经验后，加科因便会召见他们。他认为未经训练的术士十分危险，随时可能丢掉性命，因此教他们施行复杂的仪式，束缚虚空行者为自己效力。",al={"加科因为何召集术士","加科因的召唤的用途","虚空行者任务起点"}},{q="黑暗缚灵者加科因在哪里？",a="加科因藏身于已宰的羔羊下方深处的墓穴中，这家酒馆位于暴风城的法师区。",al={"加科因在哪里","加科因的位置","已宰的羔羊地下室"}},{q="雷门·玛考特是谁？",a="雷门·玛考特是暴风城术士秘会的同伙。他待在闪金镇狮王之傲旅店的地窖里，寻找有潜力的人选，悄悄引导他们前往加科因的隐秘据点。",al={"雷门·玛考特","谁发起加科因的召唤"}},{q="为何必须对地点保密？",a="暴风城王国禁止使用邪能魔法和召唤恶魔。白银之手、光明大教堂或城市卫兵都有可能发现这个秘会，届时成员便会面临监禁或处决。",al={"为何保密","暴风城术士为何保密"}},{q="响应加科因的召唤后会发生什么？",a="向加科因报到后，他会派你前往艾尔文森林的布莱克威尔南瓜田。在那里，你需要从苏伦娜·凯尔东手中取回血石颈环，这是束缚虚空行者的仪式不可或缺的物品。",al={"加科因的召唤的后续任务","接下来会发生什么"}},{q="术士以外的人也能收到这份召唤吗？",a="不能。只有掌握了操控基础小鬼伙伴本领的术士，才能收到召唤，接受进阶秘术指导。",al={"法师能接吗","谁能做加科因的召唤"}}},fx={["0d517c2f"]={q="雷门·玛考特为什么要你去见加科因？",a="雷门·玛考特完全是在奉黑暗缚灵者加科因大师之命行事。他整整一天都在城里四处寻找你，为此已经烦透了。他只想完成差事，好不再追着你跑，回去处理自己的事情；他还警告你尽快去报到，免得你的师父失去耐心。",al={"雷门为什么派你去找加科因","雷门·玛考特的动机","雷门为什么在找你"}}},fp="15,248,18.350.0,34.337.0,46.213.0,38.98.0,20.200.0,37.194.0,43.199.1,38.114.0"}
P.entries["quest:1686"] = {n="艾鲁拉的阴影",s="在奥伯丁，艾鲁拉的幽魂守护着一艘沉船和船上的月神矿石。艾兰娜瑞派年轻的暗夜精灵战士潜入水中，让这位船长安息，并取回她的徽章和矿石，交给铁匠玛希尔锻造武器。",h="在奥伯丁，艾鲁拉的幽魂守护着一艘沉船和船上的月神矿石。艾兰娜瑞派年轻的暗夜精灵战士潜入水中，让这位船长安息，并取回她的徽章和矿石，交给铁匠玛希尔锻造武器。",kw={"奥伯丁","黑海岸","达纳苏斯","艾兰娜瑞","月神矿石","艾鲁拉","艾鲁拉的阴影","铁匠玛希尔","月神武器"},ang={["class:Warrior"]="身为暗夜精灵战士，你在试炼中证明自己在水中的坚韧和战斗中的自律，赢得一件锻造的Elunite武器。",["profession:Blacksmithing"]="身为铁匠，你从暗夜精灵用受祝福的Elunite材料打造的强大兵器中，看到了他们的冶金传统。",["race:NightElf"]="身为暗夜精灵，你让艾鲁拉的幽魂安息，以此向一位kaldorei同胞致敬，她的责任感曾将她束缚在波涛之下，历经数代。"},sec={{t="船长的永恒守望",b="很久以前，一艘载着稀有月神矿石的船在奥伯丁灯塔附近撞上了嶙峋的海岸礁石，沉入海底。船长艾鲁拉在绝望与矢志不渝的责任感驱使下，诅咒了自己的灵魂。她的幽魂被束缚在波涛之下的残骸中，守护着遗失的货物，不让任何人惊扰。"},{t="月神武器",b="艾兰娜瑞派年轻的暗夜精灵战士踏入黑海岸的浪涛，击败艾鲁拉，取回她的徽章，并打捞矿石。他们需要集齐徽章和矿石，才能让船长安息，并将这些金属送到铁匠玛希尔的熔炉。这项任务考验他们的战斗技艺和对逝者的敬意，也为锻造武器提供矿石。"}},faq={{q="艾鲁拉的阴影是谁？",a="艾鲁拉曾是一艘精灵船只的船长，那艘船在奥伯丁灯塔附近的浅滩失事。她诅咒了自己，守护着沉入海底的月神矿石货物。",al={"艾鲁拉幽魂的故事","艾鲁拉是谁","船长艾鲁拉"}},{q="艾兰娜瑞为什么派战士去对付艾鲁拉？",a="艾兰娜瑞派战士击败艾鲁拉，取回她的徽章和矿石，让她的灵魂安息。这场试炼考验他们的武艺，也为锻造武器提供材料。",al={"为什么要杀死艾鲁拉","艾兰娜瑞任务目的"}},{q="船只在哪里失事？",a="沉船位于黑海岸的奥伯丁近海水下，靠近灯塔，就在主港码头南面。",al={"沉船在哪里","艾鲁拉船只位置"}},{q="月神矿石有什么用途？",a="暗夜精灵铁匠用稀有的月神矿石锻造武器。打捞上来的货箱会送到达纳苏斯的铁匠玛希尔手中，由他为有潜力的战士量身打造军用武器。",al={"月神矿石是什么","月神矿石用途"}},{q="击败幽魂会对艾鲁拉造成永久伤害吗？",a="击败艾鲁拉会解除将她的灵魂束缚在海底的诅咒。艾兰娜瑞说，在战斗中战胜这位船长，便能让她在漫长的守望之后获得安宁。",al={"艾鲁拉死了吗","艾鲁拉获救了吗"}},{q="收集矿石后，由谁锻造武器？",a="艾兰娜瑞收到矿石和徽章后，会派战士前往达纳苏斯的战士区，寻找铁匠玛希尔。他会将这些金属打造成一件出色的武器。",al={"谁打造月神武器","艾鲁拉之后的任务"}}},fp="18,166,25.278.0,18.308.0,26.177.0,44.162.0,27.128.0,29.169.0,48.148.0,48.166.0"}
P.entries["quest:1688"] = {n="苏伦娜·凯尔东",s="在暴风城的已宰的羔羊地下，加科因正寻找他昔日的学生，以及她带走的血石颈环。他派出一名新学徒，追寻背叛他并加入迪菲亚潜行者的苏伦娜·凯尔东。",h="在暴风城的已宰的羔羊地下，加科因正寻找他昔日的学生，以及她带走的血石颈环。他派出一名新学徒，追寻背叛他并加入迪菲亚潜行者的苏伦娜·凯尔东。",kw={"血石颈环","布莱克威尔南瓜田","迪菲亚","埃尔兰·杜德摩尔","黑暗缚灵者加科因","已宰的羔羊","苏伦娜·凯尔东","虚空行者"},ang={["class:Warlock"]="身为术士，追寻苏伦娜·凯尔东是你证明自己的试炼。加科因的教诲是，背叛要付出生命的代价，而黑暗法术容不下私情。",["race:Human"]="身为人类，你看到了迪菲亚潜行者如何继续诱惑那些对暴风城王国心怀不满的民众。"},sec={{t="怨恨的导师",b="在暴风城法师区的已宰的羔羊地下，黑暗缚灵者加科因向初学者传授邪能召唤的禁忌法术。他曾收苏伦娜·凯尔东为学生。他欣赏她与生俱来的魔法天赋和美貌。但苏伦娜放弃了学业，也舍弃了加科因的宠爱，随后与情人埃尔兰·杜德摩尔逃离暴风城，加入了迪菲亚潜行者。"},{t="被盗的血石",b="加科因毫不在乎苏伦娜的死活。他只想拿回她当学徒时，他送给她的血石颈环。于是，他派最新收下的学徒前往东南方，来到艾尔文森林的布莱克威尔南瓜田，那座农庄已被迪菲亚匪徒占据。学徒必须不择手段，从苏伦娜手中夺回宝石。这块血石将成为下一场试炼的魔法催化剂：召唤并束缚一只虚空行者。"}},faq={{q="苏伦娜·凯尔东是谁？",a="苏伦娜·凯尔东曾是暴风城的黑暗缚灵者加科因的学徒。她天赋出众，曾赢得他的宠爱和馈赠，后来却放弃学业，与迪菲亚匪徒埃尔兰·杜德摩尔一同出逃。",al={"苏伦娜的故事","苏伦娜是谁","苏伦娜·凯尔东的背景故事"}},{q="加科因为什么要拿回她的颈环？",a="加科因在苏伦娜当学徒时将颈环送给了她，如今他想要取回其中珍贵的血石。他痛恨她的背叛，也需要这块石头作为仪式材料，帮助新学徒束缚一只虚空行者。",al={"为何取回颈环","血石颈环的重要性"}},{q="在哪里能找到苏伦娜·凯尔东？",a="你可以在布莱克威尔南瓜田找到苏伦娜和她的迪菲亚同伙，那是一座位于艾尔文森林东南部的废弃农庄。",al={"苏伦娜的位置","苏伦娜在哪里","南瓜田在哪里"}},{q="取回颈环后会发生什么？",a="当你将血石颈环交还给加科因，试炼便完成了。接下来，你要进入已宰的羔羊地下墓穴中的召唤法阵，束缚一只来自扭曲虚空的虚空行者。",al={"接下来是什么","苏伦娜之后的任务"}},{q="埃尔兰·杜德摩尔是谁？",a="埃尔兰·杜德摩尔是迪菲亚潜行者的一名盗贼。他引诱了苏伦娜·凯尔东，劝她放弃术士训练，逃离暴风城，与匪徒为伍。",al={"埃尔兰的故事","埃尔兰·杜德摩尔是谁"}},{q="加科因对苏伦娜的命运有丝毫愧疚吗？",a="加科因对苏伦娜的命运毫无愧疚。他说她的性命对他毫无意义，浪费她的魔法天赋固然可惜，但她的背叛使他必须除掉她。",al={"加科因是否在乎","加科因对苏伦娜的反应"}}},fx={["8bc53c35"]={q="苏伦娜的项圈有什么用？",a="这条项圈是一件附有魔法的血石首饰，是黑暗缚灵者加科因当初糊涂地送给前学徒的礼物。对术士而言，血石蕴藏着原始的奥术与召唤之力。加科因需要借助这件物品残留的力量，在已宰的羔羊下方布置仪式法阵，让你能够召唤虚空行者，并使其服从你的意志。",al={"苏伦娜的项圈的用途","为何需要血石颈环","项圈有什么用"}},["703ff238"]={q="加科因为什么派学徒去，而不亲自处理苏伦娜？",a="暴风城的术士在已宰的羔羊下方极其隐秘地活动，王国的法律禁止他们的行径，一旦暴露便会遭到追捕。加科因既不能请卫兵从迪菲亚匪徒手中取回一件非法的魔法传家宝，也不能抛下自己的密室，去解决这桩令他难堪的私事。派你前去，既能考验你是否心狠手辣，也能证明你是否具备掌握黑暗法术所需的胆识。",al={"为何派我处理苏伦娜","加科因为何不能取回项圈","加科因为何不亲自去"}}},fp="14,210,15.361.0,21.418.1,22.198.0,36.203.0,34.128.0,41.198.1,24.176.0,47.178.0"}
P.entries["quest:1689"] = {n="誓缚",s="在暴风城地下，黑暗缚灵者加科因为你设下了最后的试炼。借助找回的血石颈环，你将一只虚空行者引入隐秘的法阵，迫使它屈服。",h="在暴风城地下，黑暗缚灵者加科因为你设下了最后的试炼。借助找回的血石颈环，你将一只虚空行者引入隐秘的法阵，迫使它屈服。",kw={"束缚","血石颈环","黑暗缚灵者加科因","法师区","已宰的羔羊","暴风城","召唤法阵","虚空行者"},ang={["class:Warlock"]="身为术士，你获得了一只保护你的虚空行者。这场仪式标志着你从初学的召唤者，成长为能够号令异界生物的主人。",["faction:Alliance"]="身为联盟的一员，你为崇尚圣光与奥术秩序的事业效力。在危难之际，务实的领袖们对法师区地下的黑暗施法者睁一只眼闭一只眼。",["race:Gnome"]="身为侏儒术士，你以严谨而充满好奇的头脑钻研黑暗召唤术。在加科因的指导下，你将征服虚空生物视作一场形而上学实验来研究。",["race:Human"]="身为人类术士，你受到暴风城祭司们的严密审视。你在暗影中驾驭危险的生物，并向上方的城市隐瞒自己的力量。"},sec={{t="地下墓穴中的征服",b="暴风城法师区的已宰的羔羊下方有一片地下墓穴，白银之手和肯瑞托的执法官无法监视到这里。加科因教导你，驾驭黑暗魔法，光有力量还不够。你还必须掌控来自这个世界之外的生物。你从苏伦娜·凯尔东手中找回了他被盗的血石颈环。现在，他要你在酒馆地下召唤一只虚空行者。"},{t="以意志驾驭虚空",b="虚空行者不会与你讨价还价。血石颈环撕开一道裂隙，将这个暗影生物引入凡人的世界。你用魔法和力量不断攻击它，直到它的意志崩溃。随后，它的精华便与你绑定，成为坚韧的暗影护卫，在今后的战斗中为你承受伤害。"}},faq={{q="召唤法阵在哪里？",a="召唤法阵位于暴风城法师区的已宰的羔羊下方，在地下墓穴深处。从黑暗缚灵者加科因身旁沿楼梯进入地下通道，再下到最底层的墓室。石地板上有一道发着紫光的仪式符文。",al={"召唤法阵位置","在哪里召唤虚空行者","法阵在哪里"}},{q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一位术士训练师，身处暴风城已宰的羔羊的地下。他避开城市卫兵和教会当局，秘密教导有潜力的人类和侏儒施法者召唤并控制恶魔与受虚空影响的生物。",al={"加科因是谁","黑暗缚灵者加科因的故事","加科因"}},{q="血石颈环有什么用途？",a="苏伦娜·凯尔东偷走了血石颈环，而你为加科因找回了它。颈环汇聚的魔力能帮助初学的术士突破帷幕，将一只虚空行者引入召唤法阵。",al={"血石颈环用途","为什么需要颈环","颈环"}},{q="术士为什么必须先与恶魔战斗，才能束缚它们？",a="恶魔和虚空生物不会心甘情愿地为凡人主人效劳。术士必须先在战斗中凭借力量和意志使其屈服，才能将其束缚，为自己效力。",al={"为什么要与虚空行者战斗","为什么要征服恶魔","征服恶魔"}},{q="完成仪式后会怎样？",a="击败这个生物并将颈环交还给加科因后，你便掌握了召唤和指挥忠诚的虚空行者所需的知识与技巧。它能在旅途中保护你。",al={"能获得什么奖励","虚空行者法术","束缚之后"}},{q="为什么要在酒馆地下秘密举行这个仪式？",a="恶魔学识和虚空魔法都是禁忌。圣光教会和联盟的法师都对它们抱有敌意。暴风城的术士避开当局，在隐蔽的地下室和地下墓穴中修习。",al={"为什么藏在酒馆地下","邪能魔法是否违法","已宰的羔羊地下室"}}},fx={bc8c924d={q="黑暗缚灵者加科因为什么要你束缚虚空行者？",a="你取回血石颈环后，加科因看到了你的潜力，但他认为你的魔法训练尚未完成。真正的术士不能只会引导暗影能量，还必须具备支配虚空生物的意志。在他教你如何在战斗中正确指挥虚空行者之前，你必须凭自己的力量战胜一只虚空行者，证明你的主宰地位。",al={"加科因为何要这样做","加科因的动机","为何束缚虚空行者"}},["8fb1392b"]={q="你召唤的虚空行者是什么？",a="你要把一个来自扭曲虚空的敌对生物召入酒馆下方的召唤法阵。虚空行者是坚韧的暗影生物，受混乱的恶意驱使。血石颈环的力量将它引过界限后，它会立即发动攻击，企图消灭召唤者，除非你以武力和魔法将它制服。",al={"虚空行者是什么","与谁战斗","召唤出的虚空行者"}},b41bc1ad={q="加科因为什么让你亲自召唤虚空行者？",a="术士不能借他人之手束缚恶魔。如果由加科因或助手驯服这头野兽，它就只会听命于他们。要获得虚空行者的力量与保护，你必须亲自将它引入法阵，摧垮它的意志。只有亲手压倒它，你才能建立起日后召唤并指挥它所需的神秘纽带。",al={"为何必须亲自召唤","加科因为何不能代劳","为何派我对付虚空行者"}}},fp="11,168,25.362.0,28.304.0,38.268.0,28.248.0,39.181.0,56.153.0,41.175.0,56.211.0"}
P.entries["quest:169"] = {n="通缉：加塞尔佐格",s="在赤脊山，所罗门镇长悬赏重金，缉拿率领黑石入侵石堡的军阀。任何人只要攻入沦陷的要塞，带回这名指挥官的首级，就能领取赏金。",h="在赤脊山，所罗门镇长悬赏重金，缉拿率领黑石入侵石堡的军阀。任何人只要攻入沦陷的要塞，带回这名指挥官的首级，就能领取赏金。",kw={"黑石","悬赏","加塞尔佐格","湖畔镇","所罗门镇长","赤脊山","石堡","通缉告示"},ang={["class:Warrior"]="在石堡要塞顶端，你将面对Dark Horde前线指挥部身经百战的老兵与蛮横的武力。",["faction:Alliance"]="击杀加塞尔佐格，就能消除王国东部边境最迫切的军事威胁之一，为湖畔镇居民争取宝贵的喘息之机。",["race:Human"]="对暴风城的人民来说，石堡要塞来之不易。要塞陷落时，加塞尔佐格屠杀了无辜者，使这份悬赏承载了刻骨的复仇之意。"},sec={{t="石堡的军阀",b="加塞尔佐格指挥黑石在赤脊山各地发动袭击。他麾下的兽人攻占了石堡要塞，将这座昔日的人类堡垒变成了进攻附近定居点的坚固据点。他在要塞最高处的城墙上策划进一步入侵湖畔镇，企图切断赤脊山与王国其他地区的联系。"},{t="濒临绝境的城镇",b="暴风城的皇家军队迟迟未向边境地区派出援军，所罗门镇长只得亲自采取行动。湖畔镇没有足够的兵力强行夺回石堡要塞。所罗门镇长公开悬赏缉拿加塞尔佐格，希望借此瓦解黑石的指挥体系，着手为王室收复要塞。"}},faq={{q="加塞尔佐格是谁？",a="加塞尔佐格是一名兽人军阀，统率着占据石堡的黑石部队。他指挥部队攻陷了要塞，并频繁袭击湖畔镇的人类居民，造成大量伤亡。",al={"加塞尔佐格背景故事","加塞尔佐格是谁","赤脊山黑石首领"}},{q="在哪里能找到加塞尔佐格？",a="加塞尔佐格盘踞在石堡要塞顶端，那里位于赤脊山东部的峭壁间。黑石的勇士和卫兵守护着他。",al={"加塞尔佐格位置","加塞尔佐格在哪里","石堡首领位置"}},{q="所罗门镇长为什么悬赏，而不派出士兵？",a="湖畔镇的卫兵已疲于应付，而暴风城王室始终没有派兵驰援这一地区。所罗门镇长只能依靠雇佣兵和独立的冒险者应对重大威胁。",al={"为何悬赏","暴风城士兵在哪里","湖畔镇卫兵求援"}},{q="加塞尔佐格被杀后会怎样？",a="所罗门镇长认为，杀死加塞尔佐格是肃清兽人的第一步，最终目的是为暴风城王国收复石堡要塞。黑石在这一地区仍驻有重兵。",al={"石堡收复了吗","击杀加塞尔佐格之后"}},{q="黑石兽人为什么入侵石堡要塞？",a="黑石氏族将赤脊山高处的石堡要塞用作坚固的前沿基地。他们从那里控制山口，并向人类定居点发动袭击。",al={"黑石为何在赤脊山","石堡为何被攻占"}},{q="加塞尔佐格死后，该找谁领取赏金？",a="将加塞尔佐格的首级带到湖畔镇的城镇大厅，交给所罗门镇长，作为击败他的证明。",al={"加塞尔佐格任务交给谁","加塞尔佐格任务交付"}}},fp="19,215,25.311.0,26.299.0,19.195.0,31.150.0,72.197.0,41.207.0,50.169.0,47.95.0"}
P.entries["quest:1690"] = {n="废土的公正",s="加基森自来水公司的首席工程师沙克斯·比格维兹说，废土游牧民如今占据了塔纳利斯沙漠中几乎所有的水井。你被派往加基森以东，惩治废土强盗和废土窃贼。",h="加基森自来水公司的首席工程师沙克斯·比格维兹说，废土游牧民如今占据了塔纳利斯沙漠中几乎所有的水井。你被派往加基森以东，惩治废土强盗和废土窃贼。",kw={"强盗","比格维兹","加基森","塔纳利斯","窃贼","废土","供水公司","水井"},sec={{t="为水井伸张正义",b="在塔纳利斯沙漠中，废土游牧民如今占据了几乎所有的水井，无法使用这些水井，加基森的水源很快就会枯竭。首席工程师沙克斯·比格维兹喜欢用地精的方式伸张正义，他要你到城东击杀十名废土强盗和废土窃贼，然后立刻回来汇报。"},{t="远未结束",b="比格维兹对办事的速度很满意。游牧民的数量已经减少，公司可以开始考虑夺回水井了，不过，对付这些可恶游牧民的行动还远未结束，公司还有进一步的打算。"}},faq={{q="首席工程师沙克斯·比格维兹是谁？",a="他是加基森水业公司的一位首席工程师，身在加基森。",al={"比格维兹","谁提供废土的公正","加基森水业公司工程师"}},{q="加基森水业公司为什么要对付废土游荡者？",a="废土游牧民占据了沙漠中几乎所有的水井，无法使用这些水井，加基森的水源就会枯竭。",al={"为什么要杀废土强盗","废土的公正的缘由","为什么要攻击塔纳利斯的游牧民"}},{q="废土强盗和窃贼在哪里？",a="在加基森以东的沙漠中。",al={"哪里能找到废土强盗","废土强盗的位置","塔纳利斯窃贼的位置"}}},fp="19,200,21.279.0,13.219.1,35.79.0,64.129.0,54.72.0"}
P.entries["quest:1691"] = {n="废土的公正",s="加基森的首席工程师沙克斯·比格维兹如今将目标转向了更强悍的废土游牧民：他们的盗贼、刺客和暗影法师，出没于城镇东面和东南面。剩下的游牧民越少，夺回水井就越容易。",h="加基森的首席工程师沙克斯·比格维兹如今将目标转向了更强悍的废土游牧民：他们的盗贼、刺客和暗影法师，出没于城镇东面和东南面。剩下的游牧民越少，夺回水井就越容易。",kw={"刺客","比格维兹","加基森","暗影法师","塔纳利斯","废土","水业公司"},sec={{t="更强悍的敌人",b="在比格维兹看来，你目前干得不错，但要夺回水井，最好让游牧民的数量尽可能少。现在的目标是游牧民中的盗贼、刺客和暗影法师，他们出没于加基森东面和东南面。比格维兹承认这帮家伙很难对付，但他说那些水井理应归公司所有。"},{t="主动出击",b="游牧民的数量如今已经减少到足以让公司主动出击。比格维兹建议你去找镇上的操作员鲁格伦克，你在对付游牧民时得到的任何废土水袋，都可以交给他换取赏金。"}},faq={{q="是谁提出了这项请求？",a="加基森的首席工程师沙克斯·比格维兹，他隶属于加基森水业公司。",al={"谁提供更多 废土的公正","任务给予者"}},{q="加基森水业公司为什么要清除这些游牧民？",a="公司打算夺回水井，而游牧民的数量越少，这件事就越容易。",al={"为什么要杀废土","比格维兹的动机"}},{q="在哪里能找到目标游牧民？",a="在加基森东面和东南面，游牧民就出没在那里。",al={"废土盗贼在哪里","哪里有暗影法师"}},{q="这一步之前要做什么？",a="这一步接在废土的公正之后。",al={"前置条件","前置任务"}}},fp="24,183,18.300.0,24.246.1,18.81.0,63.85.0,39.56.0,28.33.0"}
P.entries["quest:1692"] = {n="铁匠玛希尔",s="在达纳苏斯，神圣的矿石正被送往熔炉。你从奥伯丁近海的沉船中找回月神矿石后，艾兰娜瑞派你去找玛希尔，将它锻造成一件供卡多雷使用的武器。",h="在达纳苏斯，神圣的矿石正被送往熔炉。你从奥伯丁近海的沉船中找回月神矿石后，艾兰娜瑞派你去找玛希尔，将它锻造成一件供卡多雷使用的武器。",kw={"战士区","达纳苏斯","艾兰娜瑞","月神矿","玛希尔","铁匠","战士"},ang={["class:Warrior"]="作为一名年轻的Kaldorei战士，将elunite交给玛希尔，意味着你将告别训练用剑，获得一件受到月之女神祝福的定制武器。",["profession:Blacksmithing"]="作为一名铁匠，玛希尔对elunite的敬意展现了Kaldorei铁匠如何在炉火与锤击之间，将神圣的祝福融入锻造技艺。",["race:NightElf"]="作为一名暗夜精灵，elunite的锻造让你族人的技艺与对Elune的虔诚融为一体，让武力与信仰在此交汇。"},sec={{t="神圣的交付",b="艾兰娜瑞让你带着从奥伯丁近海闹鬼的沉船中找回的月神矿石，穿过达纳苏斯的战士区。这位战士训练师将矿石装进一个坚固的箱子，指引你去找玛希尔，他是这座都城最出色的铁匠之一。他能将这种金属锻造成一件配得上你所肩负使命的武器。"},{t="月神矿石的祝福",b="玛希尔将锻造视为一门表达虔诚的技艺。月神矿石承载着月之女神艾露恩的神圣祝福，他以接过这只箱子为荣。他将把这种神圣的金属锻造成兵器，守护泰达希尔幼嫩的枝干。"}},faq={{q="铁匠玛希尔是谁？",a="玛希尔是一位技艺精湛的暗夜精灵铁匠，在达纳苏斯的战士区工作。他打造专用兵器，也为城中的守卫者定制装备。",al={"玛希尔是谁","铁匠玛希尔","玛希尔在哪里"}},{q="月神矿石有什么特别之处？",a="暗夜精灵将月神矿石奉为受到艾露恩祝福的稀有金属。玛希尔认为，将它锻造成强大的武器是一种莫大的荣耀。",al={"月神矿石是什么","月神矿石有魔力吗","月神矿石背景故事"}},{q="谁派你去找玛希尔？",a="达纳苏斯战士区的战士训练师艾兰娜瑞会将你找回的矿石装箱，派你穿过战士区去找玛希尔。",al={"谁提供铁匠玛希尔任务","铁匠玛希尔任务给予者"}},{q="这个任务只有战士才能接取吗？",a="是的。这是十级战士职业故事的一部分，旨在让年轻的战士获得自己的第一件专用武器。",al={"战士专属","其他职业能做铁匠玛希尔吗"}},{q="在达纳苏斯的哪里可以找到玛希尔？",a="玛希尔在达纳苏斯的战士区工作，从艾兰娜瑞所在的位置向南穿过建筑就能找到他。",al={"玛希尔位置","寻找玛希尔"}},{q="将矿石交给玛希尔后会发生什么？",a="你交付矿石后，玛希尔便开始锻造，并让你选择适合自己战斗风格的月神武器。",al={"铁匠玛希尔之后是什么","铁匠玛希尔的后续任务"}}},fp="13,197,17.308.0,23.226.0,21.159.0,34.123.0,25.133.0,41.120.0,40.94.0,50.127.0"}
P.entries["quest:1693"] = {n="月神武器",s="在达纳苏斯，月神武器为一名年轻战士早期的成长试炼画上句点。找回受 艾露恩 祝福的矿石后，你将它交给玛希尔，为卡利姆多的守护者打造武器。",h="在达纳苏斯，月神武器为一名年轻战士早期的成长试炼画上句点。找回受 艾露恩 祝福的矿石后，你将它交给玛希尔，为卡利姆多的守护者打造武器。",kw={"达纳苏斯","艾露恩","月神矿","卡多雷","玛希尔","泰达希尔","战士","武器锻造师"},ang={["class:Warrior"]="身为一名年轻的 kaldorei 战士，你完成了早期的一场从军试炼，并获得受 Elune 祝福的可靠武器。",["profession:Blacksmithing"]="身为一名铁匠，你看到玛希尔如何将日常的锻造技艺与塑造神圣 elunite 所需的细致用心相结合。",["race:NightElf"]="身为一名暗夜精灵，你看到对月亮女神的敬意与战争和防御所需的实用技艺融为一体。"},sec={{t="神圣的熔炉",b="暗夜精灵战士守护着泰达希尔和 卡多雷 人民。前途可期的年轻战士会收集 月神矿石，这种矿物受过月亮女神的祝福，让他们不必仅仅依靠普通的钢铁。这种矿石需要交给一位精通锻造、又珍视 艾露恩 恩赐的铁匠。"},{t="玛希尔的技艺",b="铁匠玛希尔在达纳苏斯工作，将受过祝福的 月神矿石 锻造成作战兵器。他视这项工作为荣耀，而非寻常的锻造差事。当你将矿石交给他时，他会打造适合你战斗风格的武器，以这些受你所信奉的女神祝福的兵器，回报你的付出。"}},faq={{q="这个任务的目的是什么？",a="当你把 月神 矿石交给铁匠玛希尔时，达纳苏斯年轻战士的这场成长试炼便告结束。他会锻造受 艾露恩 祝福的武器，助你踏上穿越卡利姆多的旅程。",al={"月神武器 任务","为什么做这个任务","战士十级达纳苏斯"}},{q="玛希尔是谁？",a="玛希尔是一位居住在达纳苏斯的暗夜精灵巧匠。他懂得如何将 月神矿石 锻造成配重均衡的武器，供城中的守卫使用。",al={"铁匠玛希尔","玛希尔 是谁","达纳苏斯铁匠"}},{q="月神矿石 是什么？",a="月神矿石 是暗夜精灵视为圣物的一种稀有矿物，据说蕴含着 艾露恩 的光辉与眷顾。对铁匠而言，将它锻造成武器是一份庄严的荣耀。",al={"月神矿石是什么","月神矿石 背景故事"}},{q="谁能接受这个任务？",a="这项任务面向在达纳苏斯附近受训的联盟战士，他们需要先完成为铁匠玛希尔寻找并收集 月神矿石 的前期工作。",al={"谁能接 月神武器","是否仅限战士"}},{q="这个任务在哪里进行？",a="你要将矿石交给达纳苏斯的铁匠玛希尔，这座暗夜精灵的都城高踞于泰达希尔的枝干之间。",al={"月神武器 位置","玛希尔 在哪里"}},{q="玛希尔为什么感谢冒险者？",a="玛希尔感谢你，是因为锻造 月神矿石 既是神圣的荣耀，也是他个人的乐趣。很少有铁匠能有幸锻造与 艾露恩 有关的矿石，因此你送来的矿石对他而言是一份厚礼。",al={"玛希尔 为什么感到荣幸","玛希尔 对话"}}},fp="18,180,14.255.0,15.250.0,34.168.0,15.126.0,16.156.0,29.115.0,33.104.0,38.185.0"}
P.entries["quest:1698"] = {n="犹鲁斯·麦酒",s="在湖畔镇旅店，犹鲁斯·麦酒正等待勇敢的联盟战士前来接受一项古怪的挑战。联盟各主城的训练师将经验丰富的战士从暴风城派往赤脊山边疆，去见这位矮人，接受他的武艺考验。",h="在湖畔镇旅店，犹鲁斯·麦酒正等待勇敢的联盟战士前来接受一项古怪的挑战。联盟各主城的训练师将经验丰富的战士从暴风城派往赤脊山边疆，去见这位矮人，接受他的武艺考验。",kw={"凯夫·重锤","湖畔镇","湖畔镇旅店","赤脊山","瑞斯班","暴风城","战士","武神","犹鲁斯·麦酒"},ang={["class:Warrior"]="作为联盟战士，你将经历一场成长的试炼，从入门训练迈向赤脊山边疆的危险考验。",["faction:Alliance"]="作为联盟新兵，你可能会被派往湖畔镇，这个防御薄弱的聚居地正遭受豺狼人和黑石兽人的围攻。"},sec={{t="强者的召唤",b="在联盟各主城，战士训练师看着战士们逐渐超越入门训练的水平。当学徒在第二十个历练年头前后证明了自己的实力，凯夫·重锤、武神和达纳斯·刃歌便会向他们传达犹鲁斯·麦酒的消息。这位矮人并未下达常规的军令。他公开设下赌约，向任何敢于应战的联盟战士发出武艺挑战。"},{t="湖畔镇的等待",b="犹鲁斯·麦酒在湖畔镇的酒馆里等候，这里正处于赤脊山抵御豺狼人和黑石兽人入侵的前线。找到他的人会见到一位自夸的矮人，手握美酒，随时准备评判任何自称拥有真正斗志的挑战者。对于那些想走出主城安全的石板街道、证明自己的战士，他的试炼将通向边疆更为残酷的战斗。"}},faq={{q="犹鲁斯·麦酒是谁？",a="犹鲁斯·麦酒出身于著名的麦酒酿酒家族，向联盟战士发出了公开的武艺挑战。他在湖畔镇旅店等候，考验那些自认已准备好面对赤脊山残酷边疆的战士。",al={"犹鲁斯·麦酒","麦酒是谁","湖畔镇旅店里的矮人"}},{q="训练师为何派战士前往赤脊山？",a="当战士在暴风城练就足够的本领后，当地的武器大师便会派他们投身凶险的实战。犹鲁斯·麦酒的试炼将学徒带出城墙，让他们面对荒野中真正的威胁，证明自己的耐力。",al={"为何前往湖畔镇","战士训练师任务赤脊山","为何去找犹鲁斯"}},{q="在哪里可以找到犹鲁斯·麦酒？",a="犹鲁斯·麦酒在赤脊山湖畔镇的湖畔镇旅店里等候，就在艾尔文森林东面。",al={"犹鲁斯·麦酒的位置","犹鲁斯在哪里","寻找麦酒"}},{q="与犹鲁斯交谈后会发生什么？",a="与犹鲁斯交谈后，便会开始他的武艺试炼往返瑞斯班洞穴。这是一场危险的考验，需要对抗周围山丘中的凶恶野兽和豺狼人。",al={"见过犹鲁斯之后","麦酒的试炼","下一个任务"}},{q="谁会提供寻找他的任务？",a="联盟的战士训练师，包括凯夫·重锤、武神和达纳斯·刃歌，会在战士证明自己掌握了基本本领后，派他们去寻找犹鲁斯。",al={"谁提供任务","任务起始者","指引前往犹鲁斯的训练师"}},{q="其他职业也能参加这项试炼吗？",a="不能。犹鲁斯·麦酒只向依靠体力和武器作战的战士提供这项挑战。",al={"圣骑士能否参加","是否仅限战士","职业限制"}}},fx={f43b4090={q="训练师为什么派你去找犹鲁斯·麦酒？",a="你的训练师看出，基础操练已不足以让你继续成长，你需要在实战中检验自己的胆识。犹鲁斯·麦酒专门向有本领的联盟战士公开发出挑战，承诺给予能够通过考验的人丰厚的奖励。导师们不再让你待在都城训练大厅的庇护之下，而是派你前往赤脊山，在真正的考验中证明自己的实力。",al={"为何派我去找犹鲁斯","犹鲁斯·麦酒为何选我","为何让战士在赤脊山试炼"}}},fp="16,246,20.391.0,20.414.0,24.247.0,46.254.0,34.128.0,39.153.0,33.156.0,50.101.0"}
P.entries["quest:1699"] = {n="往返瑞斯班洞穴",s="在湖畔镇，犹鲁斯·麦酒让挑战者踏上一段向北进发再折返的险途。他们要喝下他家族酿制的烈酒热麦酒，抵达瑞斯班洞穴，并在一小时内返回。",h="在湖畔镇，犹鲁斯·麦酒让挑战者踏上一段向北进发再折返的险途。他们要喝下他家族酿制的烈酒热麦酒，抵达瑞斯班洞穴，并在一小时内返回。",kw={"热麦酒","豺狼人","湖畔镇","赤脊山","瑞斯班洞穴","瑞斯班挑战","限时奔跑","犹鲁斯·麦酒"},ang={["faction:Alliance"]="身为联盟的旅人，你可以勇闯这段险途，削减北部洞穴附近的敌方巡逻队，帮助湖畔镇应对豺狼人的威胁。",["race:Dwarf"]="身为矮人，你或许很熟悉犹鲁斯这种豪放的取乐方式：喝下自家烈酒，再来一场危险的山间疾跑。"},sec={{t="矮人的挑战",b="在湖畔镇的旅店里，人们谈论的尽是豺狼人袭击和镇上卫兵失踪的沉重消息。矮人犹鲁斯·麦酒提供了另一种消遣：一场考验速度、勇气和耐力的挑战。挑战者徒步前往北部山麓之前，要先喝上一口他家族酿制的热麦酒。"},{t="奔越荒野山丘",b="赤脊山豺狼人游荡在湖畔镇与瑞斯班洞穴之间的山丘上。奔跑者必须击退或避开成群的豺狼人，抵达漆黑洞道内的第一个岔路口，再赶在一小时内返回犹鲁斯身边。这烈酒让奔跑更加艰难，挑战者穿行山丘时，脚步踉踉跄跄。"}},faq={{q="谁发起了往返瑞斯班洞穴？",a="住在湖畔镇的矮人酿酒师犹鲁斯·麦酒向旅人发出挑战，让他们跑完这段险途，考验自己的毅力，也试试他的酒力。",al={"谁提供往返瑞斯班洞穴","犹鲁斯·麦酒任务","谁发起这项挑战"}},{q="这项挑战为何格外艰难？",a="奔跑者要面对赤脊山山麓成群的豺狼人，而且只有一小时。他们还得先喝下热麦酒，喝得酩酊大醉，连保持平衡都很困难。",al={"往返瑞斯班洞穴为何困难","热麦酒效果"}},{q="瑞斯班洞穴位于何处？",a="瑞斯班洞穴位于赤脊山北部的山麓，在湖畔镇西北方。小路向北延伸，经过当地的农庄，通往豺狼人成群盘踞的峭壁。",al={"瑞斯班洞穴位置","瑞斯班在哪里","如何前往瑞斯班洞穴"}},{q="奔跑者必须深入洞穴多远？",a="挑战者只需抵达洞穴内的第一个岔路口，然后折返，全速赶回湖畔镇。",al={"瑞斯班洞穴任务目标","深入瑞斯班多远"}},{q="沿途的山丘和洞穴里盘踞着谁？",a="敌对的赤脊山豺狼人遍布路线周边和洞穴一带。奔跑者需要潜行避敌，或迅速解决战斗，才能活着走完这段路。",al={"瑞斯班有哪些敌人","瑞斯班洞穴里有什么"}},{q="这项挑战之后会通向何处？",a="活着完成这项挑战，就能向犹鲁斯·麦酒证明你的耐力，并开启这一带的后续任务，例如前往暴风城寻找铸盾师弗伦·长须。",al={"往返瑞斯班洞穴后续","往返瑞斯班洞穴后续任务"}}},fp="20,169,14.286.0,22.286.0,32.134.0,49.187.0,38.173.0,40.100.0,51.132.0,36.174.0"}
P.entries["quest:170"] = {n="新的威胁",s="石腭穴居人涌入寒脊山谷，威胁着当地的聚落和营地，巴尔林·霜锤为此发出了求援。",h="石腭穴居人涌入寒脊山谷，威胁着当地的聚落和营地，巴尔林·霜锤为此发出了求援。",kw={"新的威胁","安威玛尔","巴尔林·霜锤","魁梧的石腭怪","寒脊山谷","丹莫罗","石腭穴居人"},ang={["faction:Alliance"]="作为联盟的新兵，你协助遏制寒脊山谷来自地下的威胁。这让铁炉堡的训练场得以继续使用，也保障了南部山门的安全。",["race:Dwarf"]="作为一名离开安威玛尔的年轻铜须矮人，你有责任击退穴居人，保护丹莫罗的神圣土地和隧道。"},sec={{t="寒脊山谷遭到入侵",b="越来越多的石腭穴居人从地下破土而出。安威玛尔收到报告，称穴居人正成群涌向冰封的湖面和附近的山麓。它们袭扰巡逻队，切断了穿过山谷隘口的补给路线。对年轻的矮人战士和巡山人来说，这片山谷一直是训练之地。如今，威胁已蔓延至此。"},{t="营地沦陷",b="穴居人发动了一次协同进攻，攻占了山谷西边的一处矮人营地。巡山人撤退了，放弃了他们的哨位。铁炉堡无法抽调整编作战部队，因此巴尔林·霜锤号召新招募的冒险者，杀入石腭的阵中。必须在这些生物抵达安威玛尔之前，确保山丘一带的安全。"}},faq={{q="巴尔林·霜锤是谁？",a="巴尔林·霜锤是一位经验丰富的矮人巡山人，驻守在寒脊山谷的安威玛尔外。他负责组织防御，抵御威胁当地新兵的野兽和穴居人。",al={"巴尔林·霜锤","新的威胁任务发布者","霜锤 安威玛尔"}},{q="为什么穴居人突然出现在寒脊山谷？",a="石腭穴居人正从丹莫罗各处的深层裂隙向上挖掘隧道。当这些生物破土而出、攻占地表营地时，寒脊山谷是最早遭到袭击的有人居住的山谷之一。",al={"穴居人来自哪里","穴居人为何进攻","穴居人入侵"}},{q="穴居人攻占了哪处营地？",a="穴居人攻占了寒脊山谷西部的一处矮人巡山人营地。幸存者向安威玛尔撤退。",al={"沦陷的营地","西部营地","穴居人袭击了哪里"}},{q="威胁山谷的是哪种穴居人？",a="进攻者属于石腭部族。普通的石腭穴居人和体型更大、更强壮的壮实的石腭怪，在冰封的湖面和山麓一带带头推进。",al={"石腭穴居人","哪种穴居人","壮实的石腭怪"}},{q="麦格尼国王知道穴居人的问题吗？",a="当地守卫希望国王麦格尼·铜须和铁炉堡参议院正在筹备更大规模的应对行动。目前，寒脊山谷这样的边境哨站仍在独自抵御一波波攻势。",al={"麦格尼是否知情","铁炉堡如何应对穴居人","铁炉堡参议院 穴居人"}},{q="清剿这些穴居人之后会怎样？",a="削减穴居人的数量，有助于稳定安威玛尔周边的局势。巴尔林和其他矮人军官继续组织反击，夺回西部营地，并将穴居人赶回地下。",al={"后续任务","新的威胁之后","寒脊穴居人任务线"}}},fx={["54af52f4"]={q="巴尔林·霜锤为什么要削减穴居人的数量？",a="寒脊山谷正遭受迫在眉睫的围攻。穴居人不仅占据了南部丘陵和冰封的湖泊，还在几夜前猛攻并占领了西边的矮人营地。巴尔林需要削减它们的数量，以免这些野蛮生物进一步深入山谷，彻底攻陷安威玛尔。",al={"为何杀死穴居人","巴尔林·霜锤的动机","巴尔林为何要杀死穴居人"}},["3d273126"]={q="巴尔林·霜锤为什么需要你的帮助，而不找当地卫兵？",a="安威玛尔的守军人手严重不足。最近西部营地遭到突袭，部队被打散，驻军为了守住定居点外围，已经捉襟见肘。没有多余的士兵可以投入反攻，巴尔林只能招募每一个来到这里、身强体健的冒险者。",al={"巴尔林为何选我","为何不派卫兵","巴尔林为何需要我"}}},fp="12,120,26.317.0,14.325.0,25.182.0,44.188.0,36.130.0,47.163.0,41.176.0,40.198.0"}
P.entries["quest:1700"] = {n="格瑞曼德·艾尔默",s="在暴风城，格瑞曼德·艾尔默收到了弗伦·长须的技术笔记。这番简短的交流，让精深的研究成果在两位同住一城、性格倔强的武器锻造师之间传递。",h="在暴风城，格瑞曼德·艾尔默收到了弗伦·长须的技术笔记。这番简短的交流，让精深的研究成果在两位同住一城、性格倔强的武器锻造师之间传递。",kw={"锻造","矮人区","弗伦的铠甲","弗伦·长须","弗伦的笔记","格瑞曼德·艾尔默","暴风城"},ang={["class:Warrior"]="身为战士，你从为自己打造护甲，逐渐转向用同样的元素实验锻造作战武器。",["profession:Blacksmithing"]="身为铁匠，你能从弗伦与格瑞曼德的交流中，看到金属锻造大师之间常见的激烈竞争与技艺秘传的分享。",["race:Dwarf"]="身为矮人，你能从格瑞曼德与弗伦充满傲气的打趣中，听出卡兹莫丹锻造文化中既竞争又合作的传统。"},sec={{t="街区间的传信",b="弗伦·长须锻造了特制的弗伦的铠甲，并从中发现了精细的热处理技法和元素原理。他将研究成果记在羊皮纸上，然后请你直接送给格瑞曼德·艾尔默，一位在附近武器店工作的资深工匠。"},{t="匠人的骄傲与好奇",b="格瑞曼德·艾尔默对这份手稿很不服气。他坚称，弗伦这个年轻矮人的本事全是自己教的，一想到昔日的徒弟竟能反过来教自己，他的自尊就受到了伤害。然而，格瑞曼德还是忍不住读起了笔记。很快，他就发现了一个有趣的想法，迫不及待地想亲手试试。"}},faq={{q="格瑞曼德·艾尔默是谁？",a="格瑞曼德·艾尔默是一位备受尊敬的武器锻造师，在暴风城的矮人区开着一家店。他曾向当地的铁匠传授技艺，弗伦·长须也在其中，而他对自己的手艺深感自豪。",al={"格瑞曼德·艾尔默","格瑞曼德是谁","艾尔默 暴风城"}},{q="弗伦为什么要给格瑞曼德送笔记？",a="弗伦在制作弗伦的铠甲时发现了新的技法，并将自己的方法记成了技术笔记。他把研究成果分享给格瑞曼德，不过，这位年长矮人的火暴脾气和倔强自尊，可能会让他对别人传授新本事感到不服气。",al={"为什么送笔记","弗伦的笔记","弗伦给格瑞曼德传信"}},{q="在哪里能找到格瑞曼德·艾尔默？",a="格瑞曼德·艾尔默在暴风城矮人区的一家武器店工作，从弗伦·长须的熔炉走过去只需一小段路。",al={"格瑞曼德在哪里","格瑞曼德的位置","格瑞曼德·艾尔默的店"}},{q="格瑞曼德对笔记有什么反应？",a="格瑞曼德起初很不服气，坚称弗伦这个年轻矮人的本事全是自己教的。随后，这位锻造大师发现了一种有趣的技法，好奇心便占了上风，让他想要亲手试试。",al={"格瑞曼德的反应","格瑞曼德生气了吗"}},{q="格瑞曼德读完笔记后发生了什么？",a="弗伦用火焰淬炼金属的研究引起了格瑞曼德的兴趣，他由此着手开展一项雄心勃勃的锻造计划。后续任务需要带有元素热力的稀有材料。",al={"格瑞曼德后续","格瑞曼德·艾尔默任务之后"}},{q="弗伦为什么提醒交笔记时要低头躲闪？",a="弗伦亲身领教过格瑞曼德的火暴脾气和自尊心。他料想，一想到徒弟竟能教给师傅一种新技法，格瑞曼德就可能大发雷霆，甚至扔出东西。",al={"为什么要低头躲闪","弗伦的躲闪提醒"}}},fx={["7d98159c"]={q="弗伦为什么派你去找格瑞曼德，而不是亲自前往？",a="弗伦太了解格瑞曼德·艾尔默那易怒的脾气了。格瑞曼德声称自己把毕生所学都教给了弗伦。要是这位昔日学生径直走进他的铺子，向他讲授新的锻造技艺，肯定会引发激烈争吵。让你代为递交笔记，弗伦就能避免正面冲突，也能让这位固执的导师私下咽下这口气。",al={"为什么派我去找 格瑞曼德·艾尔默","弗伦为什么不亲自送笔记","弗伦为什么需要我"}}},fp="14,181,29.272.0,32.288.0,22.197.0,37.260.0,34.118.0,36.186.0,43.158.1,56.181.0"}
P.entries["quest:1701"] = {n="弗伦的铠甲",s="在暴风城，弗伦·长须向一名联盟战士提出了打造弗伦的铠甲的新设计。只要你带来两片大陆上的稀有材料，他就会为你锻造。",h="在暴风城，弗伦·长须向一名联盟战士提出了打造弗伦的铠甲的新设计。只要你带来两片大陆上的稀有材料，他就会为你锻造。",kw={"烧焦的奇美拉角","弗伦的铠甲","弗伦·长须","光滑的奇美拉角","燃素","剃刀沼泽","鲁古格","烧焦的蜘蛛牙","石爪山","湿地"},ang={["class:Warrior"]="身为战士，你勇闯卡利姆多的荒野与幽深的地下城，证明自己的勇气，赢得一件大师打造的护甲。",["faction:Alliance"]="身为联盟士兵，你深入贫瘠之地和石爪山脉，部落正在那里争夺土地。",["race:Dwarf"]="身为矮人，你知道真正的护甲需要坚韧不屈的材料，而这些材料就取自大自然中最凶猛的掠食者。"},sec={{t="护甲大师的雄心",b="弗伦·长须已经为你锻造了一面出色的圆盾。如今，这位矮人护甲师提出了更宏大的构想：打造能够抵挡猛烈打击的锁甲。他的工艺所需的不只是铁或钢。他需要蕴含元素热力与天然韧性的稀有材料。弗伦无法离开他在暴风城的熔炉，因此你必须前去收集这些危险的材料。"},{t="横跨大陆的远征",b="弗伦派你前往遥远的荒野和危险的深处寻找材料。配方需要湿地潮湿裂隙中毒蜘蛛的尖牙。还需要石爪山脉凶猛奇美拉身上焦灼和带电的角。为了将这些野兽材料结合并淬炼成锁甲，弗伦需要易挥发的燃素，它来自鲁古格，一名藏身于贫瘠之地剃刀沼泽荆棘迷宫深处的地卜师。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是暴风城矮人区一位经验丰富的矮人护甲师兼铸盾师。他为那些前途无量、愿意帮助他的战士量身打造防具。",al={"弗伦","谁提供弗伦的铠甲","铁匠是谁"}},{q="弗伦为什么需要如此奇怪的材料？",a="弗伦需要用特殊材料淬炼金属，超越矮人的常规工艺。他的秘传工艺将经过天然毒液、山风和吐息淬炼的有机材料，与易挥发的燃素结合使用。",al={"为什么需要蜘蛛尖牙","为什么需要角","燃素是什么"}},{q="奇美拉角从哪里来？",a="焦灼和带电的角来自卡利姆多石爪山脉的奇美拉。较年轻的奇美拉和统领它们的强大雌奇美拉身上都有这些角。",al={"哪里能找到奇美拉角","烧焦的奇美拉角位置","光滑的奇美拉角"}},{q="在哪里能找到燃素？",a="野猪人地卜师鲁古格身上带着一瓶燃素，他的巢穴位于卡利姆多贫瘠之地南端附近的剃刀沼泽。",al={"燃素","谁掉落燃素","鲁古格"}},{q="哪些蜘蛛身上有烧焦的蜘蛛牙？",a="吸血潜猎者和洞穴潜猎者身上有烧焦的蜘蛛牙。这些巨型蛛类潜伏在东部王国湿地的沼泽与洞穴中。",al={"烧焦的蜘蛛牙","蜘蛛在哪里","湿地蜘蛛"}},{q="收集齐所有材料后会发生什么？",a="弗伦收到尖牙、角和燃素后，就会开始为你锻造一件量身定制的胸甲。他会在自己的熔炉中打造这件胸甲，这是弗伦的铠甲的一部分。",al={"接下来是什么","弗伦的铠甲后续","奖励"}}},fx={cecd81db={q="弗伦·长须为什么要做这件事？",a="弗伦对自己的锻造手艺极为自豪。他已经为你打造了盾牌，如今想锻造一套格外坚固的锁甲，证明自己的造诣。他掌握着加工这些经过烈火淬炼的奇异材料所需的秘法，愿意为你打造锁甲，只为亲眼见证如此非凡的护甲问世——前提是你愿意冒险收集所需的部件。",al={"弗伦·长须的动机","为何制作弗伦的铠甲","弗伦为何需要材料"}}},fp="18,160,27.349.0,30.410.0,23.168.0,48.221.0,38.178.0,30.139.0,42.154.0,50.152.0"}
P.entries["quest:1702"] = {n="铸盾师",s="在暴风城，犹鲁斯·麦酒派战士们去领取他承诺的盾牌。他们已经通过了赤脊山的艰苦试炼，一桶热麦酒也将送到弗伦·长须手中，由这位铁匠为他们打造盾牌。",h="在暴风城，犹鲁斯·麦酒派战士们去领取他承诺的盾牌。他们已经通过了赤脊山的艰苦试炼，一桶热麦酒也将送到弗伦·长须手中，由这位铁匠为他们打造盾牌。",kw={"热麦酒","酒桶","矮人区","弗伦·长须","瑞斯班","铸盾师","暴风城","战士","犹鲁斯·麦酒"},ang={["class:Warrior"]="身为战士，你将赤脊山磨炼出的坚韧带到暴风城，证明自己配得上著名矮人护甲匠锻造的盾牌。",["profession:Blacksmithing"]="身为铁匠，你结识了弗伦·长须，他打造防御护甲的技艺闻名于整个联盟。",["race:Dwarf"]="身为矮人，你熟悉这笔买卖：在暴风城的矮人区，用一桶上好的麦酒麦酒换取锻好的铁器。"},sec={{t="兑现承诺",b="你已经直面 瑞斯班挑战 的豺狼人和种种危险，犹鲁斯·麦酒也信守约定。湖畔镇无法提供他承诺的盾牌，于是他让通过考验的战士返回暴风城。在那里，一位矮人护甲匠正准备偿还一份人情。"},{t="麦酒的佳酿",b="犹鲁斯交给你一桶沉甸甸的热麦酒，用它代替信用凭证。把它带给暴风城矮人区的弗伦·长须。这位经验丰富的铁匠知道这桶酒背后是谁的名号，也愿意施展手艺，为寻求坚固盾牌的战士效劳。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是暴风城矮人区的矮人护甲大师。联盟的战士都知道他的手艺，而那些赢得他尊重的老练战士，可以请他打造专门的防御装备。",al={"弗伦·长须","弗伦是谁","铸盾师是谁"}},{q="犹鲁斯为什么派你去暴风城？",a="犹鲁斯·麦酒派你去暴风城，是因为他答应给你一面战斗用的盾牌，自己却无法锻造。他的朋友弗伦·长须欠他一份很大的人情。",al={"为什么去暴风城","为什么是暴风城","犹鲁斯 奖励地点"}},{q="热麦酒是什么？",a="热麦酒是麦酒家族酿制的一种矮人烈酒。犹鲁斯给弗伦·长须送去一桶新酒，为这位铁匠解渴，也履行他们之间的约定。",al={"一桶热酒","热麦酒","热麦酒 是什么"}},{q="在哪里能找到弗伦·长须？",a="弗伦·长须在暴风城矮人区照看着自己的熔炉，周围都是矮人工匠的作坊。",al={"弗伦位置","弗伦·长须在哪里","寻找弗伦"}},{q="把酒桶交给弗伦之后会怎样？",a="这桶酒让弗伦知道，你是犹鲁斯派来的。弗伦承认自己欠下的人情，并愿意为你制作适合久经沙场的战士使用的防御护甲，由此开启获取经过烈火淬炼的装备之路。",al={"接下来是什么","弗伦后续任务"}},{q="这趟差事为什么对联盟战士很重要？",a="这次送货让联盟战士结识了王国最出色的护甲匠之一，也为其获取量身打造的战斗装备、接受进一步的防御战术指导开辟了道路。",al={"战士任务的重要性","为何对战士重要"}}},fx={["23250e3d"]={q="犹鲁斯·麦酒为什么让你送货，而不找信使？",a="你闯过瑞斯班挑战后，犹鲁斯正在兑现他的承诺。他并非让你完成一次普通的送货，而是派你亲自去领取应得的奖励。他答应给你的盾牌放在暴风城的朋友弗伦·长须那里，因此，让你捎上一桶他著名的热麦酒，既能履行诺言，也能直接替你讨回一份旧人情。",al={"为何派我去找铸盾师","犹鲁斯为何派我去","犹鲁斯·麦酒为何选我"}}},fp="15,235,14.260.0,19.261.0,23.200.0,37.157.0,27.173.0,35.110.0,41.173.0,51.169.0"}
P.entries["quest:1703"] = {n="玛希尔",s="弗伦·长须将锻造笔记送往大洋彼岸，交给达纳苏斯的玛希尔。这位暗夜精灵铁匠在战士区工作，矮人的锁甲锻造技艺或将在他手中传承。",h="弗伦·长须将锻造笔记送往大洋彼岸，交给达纳苏斯的玛希尔。这位暗夜精灵铁匠在战士区工作，矮人的锁甲锻造技艺或将在他手中传承。",kw={"铁匠","达纳苏斯","火焰淬炼锁甲","弗伦·长须","弗伦的笔记","玛希尔","泰达希尔","战士区"},ang={["class:Warrior"]="身为战士，运送弗伦的笔记让你从东部王国的铁匠铺来到达纳苏斯的试炼场，并在途中增进护甲锻造知识。",["profession:Blacksmithing"]="身为铁匠，你会看到锻造大师如何分享技艺，让图解和热处理方法在相隔遥远的熔炉之间流传。",["race:Dwarf"]="身为矮人，与暗夜精灵分享弗伦的发现，也让你族人引以为傲的锻造技艺远渡重洋。",["race:NightElf"]="身为暗夜精灵，你能看到玛希尔对矮人锻造技艺的兴趣，以及这门技艺如何与kaldorei的护甲锻造工艺并存。"},sec={{t="跨海信使",b="弗伦·长须已经掌握了火焰淬炼护甲的锻造技艺，并决定与联盟的其他工匠分享自己的心得。他抄录了技术图解，派你跨越大陆，前往泰达希尔寻找铁匠玛希尔。"},{t="卡多雷的钢铁与矮人的技艺",b="在达纳苏斯的战士区，玛希尔照料着一座熔炉，为哨兵和其他保卫暗夜精灵首都的战士打造装备。弗伦的笔记将矮人的技艺从卡兹莫丹的地下熔炉带到了卡多雷护甲匠手中，而他们的工艺深受自身与自然之间纽带的影响。"}},faq={{q="玛希尔是谁？",a="玛希尔是达纳苏斯战士区的一位暗夜精灵铁匠。他为首都的守卫打造装备，并与联盟各地的铁匠保持通信。",al={"玛希尔背景故事","达纳苏斯的玛希尔是谁"}},{q="弗伦为什么派你去达纳苏斯？",a="弗伦·长须希望联盟的其他工匠也能从他研究火焰淬炼护甲的成果中获益。他派你把锻造笔记送给玛希尔，这位同行有能力研究其中的技艺。",al={"为什么给玛希尔送笔记","弗伦的笔记缘由"}},{q="在达纳苏斯哪里可以找到玛希尔？",a="玛希尔在达纳苏斯战士区的熔炉旁工作，那里位于主城门附近的东部城区，是战士和哨兵训练的地方。",al={"玛希尔位置","玛希尔在哪里"}},{q="把笔记交给玛希尔之后会发生什么？",a="收到弗伦的笔记后，玛希尔对其中的发现深感钦佩，并着手在矮人技艺的基础上继续钻研。他派你前往卡利姆多的荒野，收集包括晒焦的甲壳在内的稀有材料。",al={"玛希尔之后的任务","玛希尔后续"}},{q="送去的是怎样的笔记？",a="笔记记载了弗伦为制作强化锁甲，使用烧焦的蜘蛛牙、奇美拉的角和燃素进行实验时的观察结果与锻造方法。",al={"弗伦的笔记内容","弗伦的笔记是什么"}},{q="这个任务仅限战士接取吗？",a="是的。这次送信是联盟战士试炼与训练的一部分，旨在磨炼武艺，增进护甲锻造知识。",al={"战士任务玛希尔","其他职业能做玛希尔任务吗"}}},fp="7,184,24.217.0,32.267.0,15.163.0,37.190.0,38.138.0,44.215.1,39.170.0,37.132.0"}
P.entries["quest:1704"] = {n="科罗莫特·钢尺",s="在侏儒区，弗伦·长须研究火焰淬炼锁甲的成果传到了科罗莫特·钢尺手中。这位矮人铁匠相信，他的侏儒同僚能发掘这些新技艺的潜力。",h="在侏儒区，弗伦·长须研究火焰淬炼锁甲的成果传到了科罗莫特·钢尺手中。这位矮人铁匠相信，他的侏儒同僚能发掘这些新技艺的潜力。",kw={"铁匠","火焰淬炼","弗伦","铁炉堡","科罗莫特","长须","笔记","钢尺","侏儒区"},ang={["class:Warrior"]="身为战士，你为了获得坚固耐用的战斗装备，从矮人的炉火旁一路走向侏儒的发明创造。你赢得了侏儒区顶尖工匠的关注。",["profession:Blacksmithing"]="身为铁匠，你携带弗伦的笔记，参与铁炉堡工艺大师之间的高深锻造技艺交流。",["race:Gnome"]="身为侏儒，你看到科罗莫特在侏儒区将矮人的金属加工技艺与侏儒的试验精神融为一体。"},sec={{t="侏儒区的同僚",b="你带着弗伦的笔记从暴风城来到铁炉堡，再前往侏儒区。科罗莫特·钢尺在那里担任铁匠，可以在自己的锻造工作中验证这些发现。"},{t="侏儒的热情",b="在矮人的家园中，侏儒铁匠并不多见。科罗莫特渴望突破传统金属加工技艺，而笔记中预示的突破让他兴奋不已。他已准备好在自己那些不同寻常的锻造项目中尝试这些火焰技艺。"}},faq={{q="科罗莫特·钢尺是谁？",a="科罗莫特·钢尺是铁炉堡侏儒区的一名侏儒铁匠。他与弗伦·长须等矮人铁匠共同钻研金属加工技艺。",al={"科罗莫特·钢尺","科罗莫特是谁","铁炉堡侏儒铁匠"}},{q="弗伦·长须为什么派你去找科罗莫特？",a="弗伦·长须将自己制作火焰淬炼锁甲时的发现记录下来。他派你去找科罗莫特，是因为这位侏儒热衷于发明，能够用弗伦的研究成果进行试验。",al={"为什么递送笔记","弗伦的笔记","弗伦·长须 科罗莫特"}},{q="在哪里可以找到科罗莫特·钢尺？",a="你可以在铁炉堡东部的侏儒区侏儒区找到科罗莫特·钢尺。他在那里的工作台和机械之间工作。",al={"科罗莫特的位置","科罗莫特在哪里","科罗莫特 铁炉堡"}},{q="把笔记交给科罗莫特后会发生什么？",a="弗伦的突破让科罗莫特兴奋不已，他开始筹划自己的金属加工项目。他派你去收集铁珊瑚等不寻常的材料。",al={"后续任务","找过科罗莫特后做什么","铁珊瑚任务"}},{q="这个任务仅限战士吗？",a="是的。这次递送任务属于一条护甲制作任务线，面向那些在资深武器和护甲大师指导下接受训练的联盟战士。",al={"仅限战士","这个任务谁都能做吗","职业要求"}},{q="科罗莫特为什么说自己分不清白天黑夜？",a="铁炉堡位于丹莫罗的群山之下。在侏儒区，石砌的穹顶和明亮的灯火让工匠们看不到太阳或天空。",al={"科罗莫特白天黑夜对话","在这地下深处对话"}}},fp="21,178,25.173.0,18.242.0,29.159.0,47.184.0,39.136.0,46.154.1,34.124.0,53.140.0"}
P.entries["quest:1705"] = {n="燃烧之血",s="在暴风城，格瑞曼德·艾尔默正在检验弗伦·长须的锻造方法。为了在自己的熔炉旁试用这些方法，他需要暮色森林中燃烧的血液和燃烧之石。",h="在暴风城，格瑞曼德·艾尔默正在检验弗伦·长须的锻造方法。为了在自己的熔炉旁试用这些方法，他需要暮色森林中燃烧的血液和燃烧之石。",kw={"燃烧的血液","燃烧之石","暮色森林","弗伦·长须","格瑞曼德·艾尔默","加特斯比尔","夜行 狼人","罗兰之墓"},ang={["class:Warrior"]="身为战士，你可以为了格瑞曼德的试验，迎战暮色森林中受诅咒的野兽，赢得以独特方式淬炼、专为前线打造的护甲。",["faction:Alliance"]="身为联盟的一员，你可以从罗兰之墓取回材料，帮助遏制暮色森林的狼人威胁，并为暴风城的军械库带来新的防护工艺。",["profession:Blacksmithing"]="身为铁匠，你可以观看格瑞曼德如何使用稀有金属和淬火剂，检验他昔日学生弗伦的方法。"},sec={{t="勉为其难的试验",b="格瑞曼德·艾尔默是联盟最出色的护甲匠之一。他很少相信其他铁匠的方法能胜过自己。然而，弗伦·长须的非凡发现激起了他身为工匠的好奇心，格瑞曼德同意用这些方法制作一件护甲。\n\n为此，他需要来自南方幽暗之地的奇异材料，它们的性质极不稳定。这些材料将用于金属的淬火和回火，使其完全符合他的要求。普通的水和寻常的煤炭都无法胜任。"},{t="罗兰之墓的恐怖",b="格瑞曼德派你前往罗兰之墓，那是暮色森林中的一座废弃矿井。凶残的夜行狼人占据了矿道，燃烧的脓血在它们受诅咒的血管中涌动。\n\n他需要几瓶它们燃烧的血液，以及一种名为燃烧之石的稀有烈焰核心。狼群首领加特斯比尔随身带着这块石头。把这两种灼热的材料带回来，让格瑞曼德能在熔炉旁检验弗伦的方法。"}},faq={{q="格瑞曼德·艾尔默是谁？",a="格瑞曼德·艾尔默是暴风城矮人区一位备受尊敬的护甲大师。他与其他工匠一同为城市的守卫打造装备，也教导立志成为战士的人认识真正战斗板甲的分量与强度。",al={"格瑞曼德","格瑞曼德·艾尔默","暴风城护甲匠"}},{q="格瑞曼德为什么需要燃烧的血液和燃烧之石？",a="格瑞曼德想检验弗伦·长须开发的一种护甲制作技艺。燃烧的血液和燃烧之石能提供超自然的高温，用于锻造特殊的甲片并为其回火。",al={"为什么需要燃烧的血液","燃烧之石的用途","任务目的"}},{q="在哪里能找到携带这些材料的夜行狼人？",a="这些材料可以在罗兰之墓找到，那是暮色森林东南部、夜色镇西南方的一座废弃矿井。夜行狼人遍布矿道，它们身上有燃烧的血液。",al={"狼人在哪里","罗兰之墓位置","燃烧的血液在哪里"}},{q="谁持有燃烧之石？",a="加特斯比尔是夜行狼人中一位强大的首领，他在罗兰之墓深处，身上带着燃烧之石。",al={"谁有燃烧之石","加特斯比尔","加特斯比尔 位置"}},{q="格瑞曼德·艾尔默和弗伦·长须是什么关系？",a="弗伦·长须曾是格瑞曼德·艾尔默的学生。格瑞曼德通常对外来的想法持怀疑态度，但弗伦最新的护甲制作方法说服了他，让他决定亲自试验。",al={"格瑞曼德 和弗伦","弗伦·长须是谁"}},{q="交回血液和石头后会发生什么？",a="收到这些炽热的材料后，格瑞曼德便开始锻造护甲，检验弗伦的方法。他承诺将成品交给收集材料的冒险者。",al={"后续任务","奖励","格瑞曼德 制作什么"}}},fx={["50895b50"]={q="燃烧之血有什么用？",a="格瑞曼德·艾尔默需要这些燃烧之血，来试验一种由他昔日的学生弗伦·长须开创的特殊锻造技法。格瑞曼德打算借助暮色森林狼人血脉中流淌的异常炽热，淬炼一套特制护甲，看看弗伦的冶金术是否真有价值。",al={"燃烧之血任务物品","燃烧之血有什么用途","为何需要燃烧之血"}},["8a0ab7ce"]={q="燃烧之石有什么用？",a="格瑞曼德需要燃烧之石这一关键材料，来试验弗伦·长须的护甲锻造方法。这块滚烫的石头来自罗兰之墓深处的狼人首领加特斯比尔，能提供锻造淬火头盔所需的原始元素热力与奥术特性。",al={"燃烧之石的用途","为何需要燃烧之石","格瑞曼德用燃烧之石做什么"}},["0438723a"]={q="暮色森林的夜行狼人是什么来历？",a="夜行是一群野性难驯、形似狼的类人生物，出没于暮色森林的幽暗林地。其中一支躲进了罗兰之墓的废弃矿井，由可怕的加特斯比尔统领。它们异常灼热的血液和炽热的珍宝，让格瑞曼德这样雄心勃勃的铸甲师盯上了它们。",al={"夜行狼人是谁","罗兰之墓狼人","夜行罗兰之墓"}}},fp="13,170,22.455.0,28.382.0,22.221.0,55.196.0,62.177.0,27.109.0,68.186.0,48.168.0"}
P.entries["quest:1706"] = {n="格瑞曼德的铠甲",s="格瑞曼德·艾尔默如今为你提供了一顶用稀有材料打造的罩帽。它检验了弗伦·长须的锻造方法，能够承受沉重的打击，是你作为联盟战士在训练中艰难取得的一项成果。",h="格瑞曼德·艾尔默如今为你提供了一顶用稀有材料打造的罩帽。它检验了弗伦·长须的锻造方法，能够承受沉重的打击，是你作为联盟战士在训练中艰难取得的一项成果。",kw={"护甲","罩帽","燃烧之血","矮人区","弗伦·长须","格瑞曼德·艾尔默","暴风城","战士任务"},ang={["class:Warrior"]="作为一名联盟战士，你的训练迎来了关键一步：获得一顶坚韧的罩帽，足以承受前线战斗中的沉重打击。",["faction:Alliance"]="格瑞曼德·艾尔默采用了弗伦·长须的设计，暴风城矮人区的矮人铁匠们则汇集各自的发现，为联盟战士打造装备。",["profession:Blacksmithing"]="这次交付将暴风城矮人区的两位矮人铁匠联系在一起，借助不寻常的材料对金属进行回火。"},sec={{t="大师革新得以验证",b="这顶罩帽证明，弗伦·长须大胆的锻造方法能让护甲更好地抵御重击。格瑞曼德·艾尔默用你在敌对地区收集的稀有元素材料和野兽材料将其锻造而成，检验了这位矮人护甲大师的理论。"},{t="锻造坚甲",b="格瑞曼德·艾尔默对金属进行处理，使其能够承受足以令普通钢铁变形的压力和打击。随后，他将完工的罩帽交给你。它的坚固体现了弗伦·长须的精湛技艺和你的决心，也许能帮助你在前线抵御艾泽拉斯最强大的威胁。"}},faq={{q="这个任务的目的是什么？",a="格瑞曼德·艾尔默用你收集的稀有材料完成一顶经过特殊处理的罩帽，以此检验弗伦·长须的实验性锻造方法。这是一条重要战士训练任务线的最后交付环节。",al={"格瑞曼德护甲用途","为何做格瑞曼德的铠甲","格瑞曼德给予什么"}},{q="格瑞曼德·艾尔默是谁？",a="格瑞曼德·艾尔默是暴风城矮人区一位技艺精湛的矮人武器锻造师。他与铁炉堡的同行合作，帮助成长中的战士获得专门打造的护甲。",al={"格瑞曼德是谁","格瑞曼德·艾尔默职责","格瑞曼德在哪里"}},{q="弗伦·长须是谁，为什么会提到他？",a="弗伦·长须是暴风城矮人区的一位矮人护甲大师。他设计了一种强化护甲的方法，使其能够承受巨大的压力，但格瑞曼德一直对此心存疑虑，直到你带来材料加以验证。",al={"弗伦是谁","弗伦的技法","弗伦·长须"}},{q="这个任务的直接前置任务是什么？",a="这个任务接在“燃烧之血”之后。在那个任务中，你将最后一种稀有材料交给格瑞曼德，那就是来自暮色森林罗兰之墓的夜行狼人的燃烧之血，以便他为金属淬火和回火。",al={"格瑞曼德的铠甲前置任务","燃烧之血任务","前置任务是什么"}},{q="任何职业都能完成这个任务吗？",a="不能。这条任务链面向三十级左右的联盟战士，是他们迈向耐用锁甲的一场试炼。",al={"格瑞曼德的铠甲是否仅限战士","谁能做格瑞曼德的铠甲"}},{q="这个任务在哪里交付？",a="你将罩帽带到暴风城矮人区，交给铁砧旁的格瑞曼德·艾尔默。",al={"格瑞曼德的铠甲交付地点","格瑞曼德暴风城位置"}}},fx={c92a0d61={q="格瑞曼德·艾尔默为什么要做这件事？",a="格瑞曼德·艾尔默正在对弗伦·长须大胆创新的锻造技艺进行最终检验。起初，格瑞曼德怀疑弗伦的方法能否打造出更好的成品，因此需要稀有而强效的材料，亲手锻造这套护甲。完成护甲并证明它能承受猛烈打击，既能证实这位锻造同行取得的突破，也能为一名技艺娴熟的战士提供战斗装备。",al={"为何制作格瑞曼德的护甲","格瑞曼德·艾尔默的动机","为何锻造护甲"}}},fp="15,202,28.259.0,17.261.0,34.201.0,22.168.0,47.208.0,40.187.0,34.124.0,35.87.0"}
P.entries["quest:1707"] = {n="收集水袋",s="加基森的操作员鲁格伦克想要那些被游民偷走的废土水袋，无论你在沙漠何处找到它们。每交回五个，加基森水业公司就会提供一份官方补给包作为回报。",h="加基森的操作员鲁格伦克想要那些被游民偷走的废土水袋，无论你在沙漠何处找到它们。每交回五个，加基森水业公司就会提供一份官方补给包作为回报。",kw={"加基森","鲁古克","塔纳利斯","废土","自来水公司","水袋"},sec={{t="属于加基森的水",b="鲁格伦克是一位经验丰富的水阀操作员，他最希望收到的就是你在沙漠中找到的废土水袋。这些水原本就属于加基森，只是被那些游民偷走了。每交回五个水袋，加基森水业公司就会提供一份官方补给包，而你也在帮助加基森自救。"},{t="继续送来",b="每收回一个水袋，鲁格伦克都很高兴，因为每一个水袋都能让大家离灾难更远一些。鲁格伦克承诺，你每送来五个水袋，他都会给你相应的回报。"}},faq={{q="操作员鲁格伦克是谁？",a="他是加基森一位经验丰富的水阀操作员，正在收集废土水袋。",al={"鲁格伦克是谁","鲁格伦克的职责","水阀操作员"}},{q="鲁格兰克为什么想要废土水袋？",a="这些水本就属于加基森，却被那些游民偷走了。",al={"为什么收集水袋","为什么杀死废土","废土水的背景故事"}},{q="在哪里能找到废土水袋？",a="在沙漠里，就在偷走水袋的废土游民手中。",al={"哪里能找到水袋","废土水袋位置","谁掉落水袋"}},{q="加基森水业公司会用什么来交换水袋？",a="每五个水袋可换取一份官方补给包。",al={"补给包","水袋能换什么"}}},fp="18,236,31.288.0,16.153.1,33.118.0,50.61.0,45.87.0,60.83.0"}
P.entries["quest:1708"] = {n="铁珊瑚",s="在侏儒区，科罗莫特·钢尺正为一套新护甲寻找灼热珊瑚。这位侏儒铁匠希望用湿地海岸的这种稀有海洋材料试验新的锻造方法。",h="在侏儒区，科罗莫特·钢尺正为一套新护甲寻找灼热珊瑚。这位侏儒铁匠希望用湿地海岸的这种稀有海洋材料试验新的锻造方法。",kw={"护甲熔炼","弗伦·长须","铁珊瑚","铁炉堡","科罗莫特·钢尺","米奈希尔港","灼热珊瑚","湿地"},ang={["profession:Blacksmithing"]="身为铁匠，你能理解Klockmort将海洋沉积物熔炼成坚硬护甲板的尝试。",["profession:Engineering"]="身为工程师，你能认识到试验特殊材料以打造更好防护装备的价值。",["race:Dwarf"]="身为矮人，你能在侏儒区的这次侏儒与矮人合作中，看到锻造大师弗伦·长须的冶金发现得到运用。",["race:Gnome"]="身为侏儒，你能看出Klockmort寻找奇异海岸矿物的用意，是通过试验改进传统工艺。"},sec={{t="技艺的融合",b="科罗莫特·钢尺曾与矮人锻造大师弗伦·长须交流彼此的发现。如今，他希望将弗伦·长须的冶金技艺与自己的机械技艺结合起来。仅凭山中的矿石，无法打造出他所追求的坚韧护甲。因此，他需要灼热珊瑚，一种经海水淬炼而变得坚硬的材料。"},{t="潜入湿地近海",b="灼热珊瑚生长在米奈希尔港以南、湿地海岸外的水下。你需要带回二十簇珊瑚，而水中的掠食者就在下方游弋。然后将收获带到铁炉堡。克罗莫计划将珊瑚熔炼并锤打成试验性的护甲板。"}},faq={{q="科罗莫特·钢尺是谁？",a="科罗莫特·钢尺是铁炉堡侏儒区的一位技艺精湛的侏儒铁匠。他热衷于钻研机械和新的冶金方法，并与矮人工匠合作研究护甲制作工艺。",al={"克洛科莫特","谁提供铁珊瑚任务","铁珊瑚任务给予者"}},{q="什么是灼热珊瑚？",a="灼热珊瑚是一种稀有的海洋生物，生长在湿地米奈希尔港以南的海床上。由于它具有不同寻常的化学和物理特性，富有创造力的铁匠可以将其熔炼并锤打成护甲加固材料。",al={"灼热珊瑚背景故事","灼热珊瑚的用途"}},{q="在哪里能找到灼热珊瑚？",a="在米奈希尔港以南的湿地沿岸水下寻找。潜水者必须将富含矿物质的珊瑚枝从海床上撬下来。",al={"灼热珊瑚位置","铁珊瑚在哪里","湿地珊瑚位置"}},{q="科罗莫特为什么需要灼热珊瑚而非金属矿石？",a="科罗莫特希望灼热珊瑚能让护甲比仅用铁炉堡矿石打造的护甲更轻、更耐用。他正在改进从矮人弗伦·长须那里学来的锻造技艺。",al={"为什么用珊瑚制作护甲","珊瑚冶金"}},{q="弗伦·长须与这项任务有什么关系？",a="弗伦·长须在你的帮助下开发了新的护甲制作技艺。为了感谢你的帮助，他将自己的行业秘诀分享给了科罗莫特，为这位侏儒的防护装备设计带来了灵感。",al={"与弗伦·长须的关系","弗伦·长须 铁珊瑚"}},{q="将珊瑚交给科罗莫特后会发生什么？",a="拿到二十份灼热珊瑚后，科罗莫特便开始在工作台上熔炼、锤打这些材料。他的工作将在科罗莫特的成果中造就试验性装备。",al={"铁珊瑚后续","铁珊瑚下一任务"}}},fx={f5cb4716={q="科罗莫特·钢尺为什么要收集灼热珊瑚？",a="科罗莫特是一位热衷于试验的侏儒发明家。他从弗伦·长须那里学到了创新的锻造技艺，希望将弗伦的方法与自己的工程学知识结合，打造一套格外坚固的护甲。要制作这套护甲，他特别需要采自湿地海岸的灼热珊瑚所具有的独特性质。",al={"克劳莫特为何需要珊瑚","克劳莫特的动机 铁珊瑚","为何制作铁珊瑚护甲"}}},fp="10,189,18.290.0,25.272.0,29.199.0,22.216.0,34.133.0,59.187.0,45.180.0,51.157.1"}
P.entries["quest:1709"] = {n="科罗莫特的成果",s="在侏儒区，科罗莫特·钢尺将弗伦·长须的锻造方法用于稀有材料。由此制成的护甲坚韧耐用。",h="在侏儒区，科罗莫特·钢尺将弗伦·长须的锻造方法用于稀有材料。由此制成的护甲坚韧耐用。",kw={"弗伦·长须","铁珊瑚","铁炉堡","科罗莫特","攻城战车","钢尺","侏儒区","战士护甲"},ang={["class:Warrior"]="身为联盟战士，获得这副护手标志着你迈过了一个重要的里程碑，它经过专门淬炼，足以承受前线战斗中的猛烈重击。",["profession:Blacksmithing"]="身为铁匠，你能看出用海中的稀有材料试验非常规淬炼方法的价值。",["race:Gnome"]="身为侏儒，你能看出族人的智慧如何将机械的精密与矮人的工艺结合，助力重型护甲的制作。"},sec={{t="技艺交融",b="克罗莫运用弗伦·长须的方法，在侏儒区制成了一副护手。矮人的金属加工技艺与侏儒的机械技术融为一体，让这副护手足以承受压垮普通钢铁的重击。"},{t="无可比拟的韧性",b="克罗莫说，即使攻城战车从这副护甲上碾过，也不会留下永久的变形。经过特殊处理的稀有部件赋予了它韧性。矮人的锻造技艺与侏儒的奇思妙想相结合，造就了足以抵御前线最猛烈战斗的护甲。"}},faq={{q="科罗莫特·钢尺是谁？",a="科罗莫特·钢尺是铁炉堡侏儒区的一位技艺精湛的侏儒铁匠。他参与精密的机械制作，并与弗伦·长须等矮人工匠合作，打造独特而耐用的装备。",al={"克劳莫特","克劳莫特是谁","侏儒区的侏儒"}},{q="制作这副护甲的工艺是谁设计的？",a="弗伦·长须是一位技艺高超的矮人护甲锻造师，这套锻造工艺正是出自他手。科罗莫特严格遵循弗伦的方法处理材料，完成了这副护甲。",al={"谁设计了工艺","弗伦·长须的护甲","弗伦的方法"}},{q="为什么这副护甲由一位侏儒铁匠打造？",a="科罗莫特想用弗伦·长须的新技法打造自己的护甲。由于你曾帮助过弗伦，科罗莫特便提出，只要你收集到他需要的灼热珊瑚，他就将制成的护甲交给你作为回报。",al={"为什么是侏儒","侏儒锻造","工程护甲"}},{q="与普通板甲相比，这副护甲有何特别之处？",a="科罗莫特说，制成的护甲既有非凡的回弹力和弹性，又坚固耐用。他声称，即使沉重的攻城战车将它压扁，金属也会弹回原来的形状。",al={"有多坚固","攻城战车护甲","护甲耐用性"}},{q="这副护甲在战士的训练历程中处于什么位置？",a="这副护甲属于一系列任务，面向那些前途可期、希望获得由铁炉堡最杰出的工匠量身锻造的坚韧装备的联盟战士。",al={"战士任务护甲","为什么做这个任务","战士奖励"}},{q="在哪里能找到科罗莫特？",a="科罗莫特·钢尺在侏儒区工作，那是铁炉堡的侏儒区，遍布工坊、咔嗒作响的齿轮和蒸汽喷口。",al={"克劳莫特的位置","钢尺在哪里"}}},fx={fd9fc5fd={q="科罗莫特·钢尺为什么要帮忙制作这套护甲？",a="科罗莫特·钢尺接下这项工作，是为了检验弗伦·长须大胆创新的制造理论。矮人的锻造技艺很少依赖精密的侏儒工程学，因此制作这副护手让科罗莫特有机会证明，将弗伦的方法与侏儒机械技术结合，能够造出足以承受攻城器械打击的护甲。",al={"克劳莫特为何帮忙","克劳莫特·钢尺的动机","克劳莫特为何锻造这件装备"}}},fp="20,138,23.232.0,20.248.0,29.208.0,44.167.0,43.198.0,57.207.0,62.136.0,25.125.0"}
P.entries["quest:1710"] = {n="晒焦的蛋壳",s="在达纳苏斯，玛希尔正寻求双足飞龙的蛋壳，以改进一种新的锁甲制作技艺。这位护甲匠与矮人铁匠弗伦·长须合作，派遣战士前往千针石林的风巢收集蛋壳。",h="在达纳苏斯，玛希尔正寻求双足飞龙的蛋壳，以改进一种新的锁甲制作技艺。这位护甲匠与矮人铁匠弗伦·长须合作，派遣战士前往千针石林的风巢收集蛋壳。",kw={"蛋壳","弗伦·长须","风巢","漆料","锁甲","玛希尔","千针石林","双足飞龙"},ang={["class:Warrior"]="身为联盟战士，你可以帮助玛希尔测试一种制作坚韧锁甲的方法。",["faction:Alliance"]="你可以看到达纳苏斯的暗夜精灵工匠与暴风城的矮人护甲匠交流技艺。",["profession:Blacksmithing"]="你可以见识一种独特的锻造方法：取自野兽的材料被制成漆料，为金属链环提供保护。"},sec={{t="跨阵营的工艺合作",b="玛希尔在达纳苏斯的战士区工作，并将目光投向暗夜精灵传统之外的技艺。他与暴风城技艺精湛的矮人护甲匠弗伦·长须通信，借鉴弗伦·长须在金属加工和护甲锻造方面的发现。玛希尔希望用天然材料加固锁甲，使其能够承受巨大的压力。为了验证这个想法，他需要一些在泰达希尔附近无处可寻的材料。"},{t="风巢的险境",b="玛希尔的实验需要风巢的蛋壳，那里远在大海南面的千针石林峡谷之中。双足飞龙在盐碱平原与红色岩石台地的高处筑巢，承受着卡利姆多烈日的炙烤。长期处于高温和高海拔环境，使它们的蛋壳变得坚硬。玛希尔计划将烈日烤晒过的蛋壳碎片磨碎，制成富有韧性的漆料，再涂在锁甲的链环上，让护甲既能弯曲，又能承受极大的压力。"}},faq={{q="玛希尔是谁？",a="玛希尔是达纳苏斯战士区的一名暗夜精灵护甲匠。他借鉴矮人的工艺，与弗伦·长须合作，为久经考验的战士研制精良的锁甲。",al={"玛希尔","谁提供晒焦的蛋壳任务","玛希尔 达纳苏斯"}},{q="玛希尔为什么需要双足飞龙的蛋壳？",a="风巢双足飞龙的蛋壳在千针石林的烈日下变得坚硬。玛希尔计划将它们磨碎，熬制成涂在锁甲链环上的漆料，以增强护甲。",al={"为何需要双足飞龙蛋壳","晒焦的蛋壳用途","蛋壳有什么用"}},{q="风巢位于何处？",a="风巢是千针石林西部一座陡峭的台地，靠近菲拉斯边境。双足飞龙在这里的悬崖和台地上四处筑巢。",al={"风巢位置","风巢在哪里","如何找到风巢"}},{q="弗伦·长须与这个任务有什么关系？",a="弗伦·长须是暴风城的一位矮人护甲大师。玛希尔将他视为值得尊敬的同行，并从他在护甲制作方面的发现中汲取灵感。",al={"弗伦·长须的关联","弗伦 是谁"}},{q="达纳苏斯的精灵为什么需要千针石林的材料？",a="南方峡谷台地的干热环境赋予了双足飞龙蛋一种韧性，而这正是玛希尔所需要的。泰达希尔雾气缭绕的枝桠间无法重现那样的高温。",al={"为何是千针石林","达纳苏斯到千针石林"}},{q="把蛋壳交给玛希尔后会发生什么？",a="玛希尔收到二十块晒焦的蛋壳后，便会开始熬制漆料，为你量身打造一套锁甲，作为你奔波收集材料的回报。",al={"玛希尔 下一步","晒焦的蛋壳之后","玛希尔 后续"}}},fp="18,206,33.376.0,23.399.0,15.160.0,36.155.0,27.123.0,46.152.0,70.157.0,50.155.0"}
P.entries["quest:1711"] = {n="玛希尔的铠甲",s="在达纳苏斯的熔炉旁，玛希尔的铠甲融合了暗夜精灵与矮人的工艺。玛希尔在战士区工作，运用弗伦·长须创制的方法，将奇异的材料打造成供联盟战士使用的护甲。",h="在达纳苏斯的熔炉旁，玛希尔的铠甲融合了暗夜精灵与矮人的工艺。玛希尔在战士区工作，运用弗伦·长须创制的方法，将奇异的材料打造成供联盟战士使用的护甲。",kw={"工匠区","达纳苏斯","弗伦·长须","玛希尔","玛希尔的铠甲","晒焦的蛋壳","战士护甲"},ang={["class:Warrior"]="联盟战士可以通过这条任务线获得坚固的护腿，其中融合了暗夜精灵与矮人的锻造知识。",["faction:Alliance"]="玛希尔与弗伦的合作展现了联盟如何通过贸易和共同防御，将相隔遥远的各族联系起来，以满足军事需求。",["profession:Blacksmithing"]="矮人的淬火技法与暗夜精灵的锻造工艺在这件作品中融为一体。"},sec={{t="工艺交融",b="暗夜精灵护甲匠偏爱历经数千年磨炼的技法，他们的作品取法自然，采用柔韧的皮革和精心加工的金属。与东部王国的贸易让玛希尔这样的铁匠开始尝试新的方法。他将弗伦·长须创制的矮人技法与精灵工艺融为一体。"},{t="奇异的材料",b="玛希尔需要千针石林风巢双足飞龙巢穴中的晒焦蛋壳。他将被烈日晒硬的蛋壳制成漆料，再用弗伦的热处理配方锻造坚韧的护腿，供前线使用。"}},faq={{q="玛希尔是谁？",a="玛希尔是达纳苏斯战士区一位技艺精湛的暗夜精灵护甲匠。他与联盟的其他工匠合作，并试验弗伦·长须等盟友提出的构想。",al={"玛希尔","玛希尔是谁","达纳苏斯护甲匠"}},{q="弗伦·长须是谁？",a="弗伦·长须是一位居住在暴风城的矮人护甲大师。他创制了为特种护甲板淬火和锻造的方法，并与盟友中的铁匠分享制作说明和设计图。",al={"弗伦","弗伦·长须"}},{q="锻造这件护甲用了什么材料？",a="这件护甲使用了从千针石林风巢双足飞龙巢穴下方收集的晒焦蛋壳。玛希尔运用弗伦·长须的锻造方法，将这些蛋壳加固并塑形。",al={"护甲材料","玛希尔的铠甲用什么制成"}},{q="精灵为什么要使用矮人的技法？",a="联盟铁匠分享知识，为战士们打造装备，以应对日益加剧的威胁。玛希尔将矮人的硬化处理方法与暗夜精灵锻造工艺的精巧和耐用融为一体。",al={"为何采用矮人锻造技法","暗夜精灵与矮人合作"}},{q="这个任务在哪里进行？",a="这项工作始于泰达希尔岛上达纳苏斯战士区的熔炉旁，也在那里完成。",al={"玛希尔位置","玛希尔在哪里"}},{q="这条任务线的前置任务是什么？",a="这条任务线承接“晒焦的蛋壳”，冒险者在那个任务中前往卡利姆多的偏远地区，为玛希尔的制作工作收集坚硬的蛋壳。",al={"前置任务","玛希尔的铠甲前置任务"}}},fp="15,208,17.274.0,17.228.0,15.168.0,23.202.0,44.175.0,39.179.0,33.100.0,41.147.0"}
P.entries["quest:1712"] = {n="塞克隆尼亚",s="塞克隆尼亚是一位强大的风之领主，长久以来，一直有人寻求将他击败。要挑战他，勇士必须集齐召唤这名元素所需的材料，再将他击杀，夺取他的旋风之心。击败风之领主后，便可将这颗心脏的力量注入一件威力强大的武器。",h="塞克隆尼亚是一位强大的风之领主，长久以来，一直有人寻求将他击败。要挑战他，勇士必须集齐召唤这名元素所需的材料，再将他击杀，夺取他的旋风之心。击败风之领主后，便可将这颗心脏的力量注入一件威力强大的武器。",kw={"勇士","塞克隆尼亚","元素","召唤","旋风之心","风之领主"},ang={["class:Warrior"]="击败风之领主塞克隆尼亚是一场彰显实力的试炼，夺取他的旋风之心来锻造强大的武器，便是精湛武艺的证明。"},sec={{t="沉睡的风之领主",b="塞克隆尼亚是一位狂暴的风元素领主，他的存在令人心生敬畏，不敢掉以轻心。长久以来，一位警觉的守望者始终守在召唤地点，等待一名武艺足够高强的战士前来挑战并消灭这个狂风肆虐的存在。"},{t="召唤风暴",b="要唤出塞克隆尼亚，必须使用一张特殊羊皮纸上详列的稀有材料，举行召唤仪式。风之领主一旦现身，挑战者就必须与他正面交锋，证明自己究竟是真正的勇士，还是又一个葬身于呼啸狂风中的牺牲者。"},{t="旋风之心",b="挑战风之领主的最终目标，是夺取他的旋风之心。从被击败的元素身上取下这颗心脏后，便可束缚其中狂暴的元素能量，将其注入一件配得上卓越勇士的武器。"}},faq={{q="塞克隆尼亚是谁？",a="塞克隆尼亚是一位强大的风元素领主。他是一个极其危险的元素威胁，长久以来一直受到监视，而那些观察者始终在等待一位足够强大的勇士前来挑战并击败他。",al={"塞克隆尼亚是谁","塞克隆尼亚的故事","塞克隆尼亚是什么"}},{q="为什么必须召唤塞克隆尼亚？",a="召唤塞克隆尼亚，是为了让一位有资格的勇士挑战并击杀他。击败风之领主后，证明了自身实力的战士便可夺取他的旋风之心，再将其力量注入一件强大的武器。",al={"为何召唤塞克隆尼亚","塞克隆尼亚的用途","为何与塞克隆尼亚战斗"}},{q="旋风之心是什么？",a="旋风之心是风之领主塞克隆尼亚的核心精华。从被击败的元素身上扯下这颗心脏后，便可将其中的风暴能量直接熔铸进一件威力强大的武器。",al={"旋风之心是什么","塞克隆尼亚的心脏","旋风之心的用途"}},{q="谁一直在监视塞克隆尼亚？",a="奥特兰克山脉的捕风者巴斯拉长久以来一直守在此地，不懈地寻找一位真正的勇士，能够击败这位元素领主，并驾驭他那颗蕴含风暴之力的心脏。",al={"谁想杀死塞克隆尼亚","谁在监视塞克隆尼亚"}},{q="如何唤出塞克隆尼亚？",a="召唤塞克隆尼亚需要收集一张特殊羊皮纸上记载的特定稀有材料，用它们将风之领主引入这个世界，以便与他交战。",al={"如何召唤塞克隆尼亚","塞克隆尼亚的召唤材料"}},{q="击败塞克隆尼亚后能锻造什么武器？",a="勇士集齐所需材料、召唤塞克隆尼亚并将他击杀后，便能获得一件武器，其中注入了这名元素的旋风之心所蕴藏的狂怒之力。",al={"塞克隆尼亚的奖励","塞克隆尼亚能锻造什么武器"}}},fp="9,217,24.165.0,21.188.0,19.187.1,17.166.0,31.164.0,28.160.0,32.189.0,31.128.0,37.163.0"}
P.entries["quest:1713"] = {n="召唤",s="在捕风者巴斯拉的营地，一名战士将迎战风之领主塞克隆尼亚，接受试炼。杀死这个元素生物，夺取旋风之心，其中的风暴之力可以被束缚在武器之中。",h="在捕风者巴斯拉的营地，一名战士将迎战风之领主塞克隆尼亚，接受试炼。杀死这个元素生物，夺取旋风之心，其中的风暴之力可以被束缚在武器之中。",kw={"捕风者巴斯拉","巴斯拉","塞克隆尼亚","元素生物","召唤","战士任务","旋风之心","风之领主"},ang={["class:Warrior"]="身为战士，迎战塞克隆尼亚并夺取旋风之心，是对你的考验。完成这场试炼，你将获得一件灌注着风暴原始力量的武器。",["race:Troll"]="身为巨魔，你知道捕风者巴斯拉的原始秘术远远超出了文明的界限。他对风元素的掌控，体现了巨魔萨满祭司和巫医深厚的秘术传统。"},sec={{t="唤来风暴",b="捕风者巴斯拉已准备好一个古老的仪式，要将塞克隆尼亚召唤到凡人世界。这个可怕的元素生物被称为风之领主。面对这场风暴，没有交涉的余地。一位有实力的勇士必须在它成形之时立即将其击杀。"},{t="风暴之心",b="塞克隆尼亚的旋风之心维系着他的实体形态。风之领主倒下后，巴斯拉便扯出这颗心脏，驾驭其中的狂风。它狂暴不定的力量可以为武器注入风暴之力。"}},faq={{q="塞克隆尼亚是谁？",a="塞克隆尼亚是一个强大的元素生物，被称为风之领主。捕风者巴斯拉的仪式将他以猛烈风暴的形态召来，只有击败他，才能夺取封存在他核心中的精华。",al={"塞克隆尼亚是谁","塞克隆尼亚是什么","塞克隆尼亚的故事"}},{q="旋风之心是什么？",a="旋风之心是塞克隆尼亚的元素核心。捕风者巴斯拉需要用它，将风之领主回旋肆虐的毁灭之力束缚在武器之中。",al={"旋风之心是什么","为什么需要旋风之心","旋风之心的用途"}},{q="捕风者巴斯拉是谁？",a="捕风者巴斯拉是一位隐居荒野的巨魔秘术师，通晓召唤塞克隆尼亚的方法。他引导战士完成仪式，再用倒下的元素生物的心脏锻造强大的武器。",al={"巴斯拉是谁","捕风者巴斯拉","召唤任务给予者"}},{q="为什么要召唤塞克隆尼亚？",a="召唤塞克隆尼亚，是为了让一名战士迎战并杀死这位风之领主，夺取他的元素之心。其中的力量可以被束缚在武器之中。",al={"为什么召唤塞克隆尼亚","召唤的目的","召唤的原因"}},{q="击败塞克隆尼亚后会发生什么？",a="塞克隆尼亚倒下后，巴斯拉便能驾驭旋风之心中的元素之力，将塞克隆尼亚的风暴法术注入武器。",al={"击败塞克隆尼亚后会发生什么","塞克隆尼亚奖励的故事","召唤之后"}},{q="召唤仪式在哪里举行？",a="仪式在捕风者巴斯拉的营地举行。在那里，这位秘术师汇聚所需的原始能量，将塞克隆尼亚从元素领域引入物质世界。",al={"仪式在哪里举行","召唤地点"}}},fp="13,185,19.250.0,22.212.0,17.189.0,28.147.0,28.204.0,32.137.0,41.135.0,36.172.0"}
P.entries["quest:1714"] = {n="流放精华",s="在大熔炉旁，流放精华以诱人的蒸汽吸引旅人。符咒引发剧烈反应，使熔岩显现。",h="在大熔炉旁，流放精华以诱人的蒸汽吸引旅人。符咒引发剧烈反应，使熔岩显现。",kw={"气泡","大熔炉","符咒","流放精华","熔岩","转化","蒸汽"},ang={["class:Mage"]="炼金熔炉和元素转化可以借助不稳定的魔法，将不同的精华凝结成固体。",["class:Shaman"]="即使冒泡的熔炉中翻腾着熔岩，运用元素精华仍需理解其中起作用的原始力量。"},sec={{t="诱人的大熔炉",b="一座不断冒泡的大熔炉散出蒸汽，吸引旅人靠近其翻腾的深处。特定的魔法符咒会在炉内激起强烈反应。"},{t="熔岩坩埚",b="符咒缓缓沉入液体之中。随后，一个巨大的气泡升起并破裂，露出一团由这些材料融合而成、不断翻腾的熔岩。"}},faq={{q="什么是流放精华？",a="流放精华是在一座不断冒泡的大熔炉中进行的转化仪式。符咒引发剧烈反应，生成一团翻腾的熔岩。",al={"什么是 流放精华","流放精华 任务"}},{q="将符咒放入大熔炉后会发生什么？",a="大熔炉的蒸汽吸引旅人靠近。符咒沉入底部，随后一个巨大的气泡在液面破裂，留下熔岩。",al={"大熔炉中会发生什么","大熔炉如何运作"}},{q="大熔炉会产出什么？",a="当一个巨大的气泡在液面破裂时，大熔炉内便会显露出一团翻腾的熔岩。",al={"大熔炉产出什么","流放精华 能获得什么"}},{q="用于这一仪式的大熔炉在哪里？",a="仪式在一座沸腾的大熔炉中进行，灼热的蒸汽吸引着旅人。在那里，炉中的材料会发生转化。",al={"大熔炉位置","哪里能找到大熔炉"}},{q="为什么要将符咒放入大熔炉？",a="符咒在大熔炉深处作为施法材料被消耗。它们在滚烫的液体中帮助形成熔岩。",al={"符咒有什么用","为什么将符咒放入大熔炉"}},{q="为什么大熔炉一直在冒泡？",a="冒泡的液体和诱人的蒸汽表明，炉内的反应正在进行。无论什么进入炉底，它都已准备好将其转化。",al={"为什么一直冒泡","蒸汽是什么"}}},fp="20,140,20.150.0,19.157.0,33.158.0,52.144.0,31.106.0,43.122.0,40.125.0,40.136.0"}
P.entries["quest:1715"] = {n="已宰的羔羊",s="来自铁炉堡的侏儒术士如今前往暴风城寻求训练。已宰的羔羊为他们提供了向人类术士学习的地方，而国王麦格尼·铜须则在故土监视着修习黑暗法术的人。",h="来自铁炉堡的侏儒术士如今前往暴风城寻求训练。已宰的羔羊为他们提供了向人类术士学习的地方，而国王麦格尼·铜须则在故土监视着修习黑暗法术的人。",kw={"黑暗缚灵者加科因","诺莫瑞根","铁炉堡","拉戈·黑钳","法师区","已宰的羔羊","暴风城","术士"},ang={["class:Warlock"]="对年轻的联盟术士而言，这段旅程将他们带入了一个跨越种族界限的隐秘修习者网络。",["race:Dwarf"]="铁炉堡当局严密监视着恶魔法术的修习。矮人术士隐于暗影之中，将学生送往别处。",["race:Gnome"]="失去诺莫瑞根的学院后，流亡的侏儒挤进铁炉堡，并依赖人类的接纳。"},sec={{t="流亡与监视",b="诺莫瑞根沦陷之前，卡兹莫丹有志成为术士的人在这座科技之城里，跟随机械法师和恶魔学者学习。随后，灾难使这些学派四散，也迫使侏儒背井离乡。幸存者挤进铁炉堡的地下洞穴，受到国王麦格尼·铜须和矮人卫兵的监视。他们无法公开修习恶魔法术或举行危险的仪式，因此拉戈·黑钳这样的资深导师只得将学生送往别处。"},{t="法师区的秘密地窖",b="侏儒学徒从铁炉堡南下，前往暴风城法师区的已宰的羔羊。蜿蜒的石砌通道和阶梯从酒馆大厅向下延伸，通往人类术士聚集的隐秘密室。黑暗缚灵者加科因在那里管理着他们。在幽暗的房间里，导师们可以教新手召唤并束缚低等恶魔，而不会立刻招致城中治安官的怒火。"},{t="暗影中的重压",b="暴风城的术士团体欢迎有本事的人加入，但流亡而来的新手也带来了新的压力。人类导师本就冒着被城中圣骑士和当局发现的风险。随着越来越多的修习者从卡兹莫丹到来，加科因和同僚们发现，他们的庇护所愈发拥挤。从矮人山城不断涌来的人，可能会暴露他们的秘密集会。然而，无论是侏儒还是人类术士，都没有更轻松的选择。"}},faq={{q="为什么侏儒术士不能在铁炉堡接受训练？",a="国王麦格尼·铜须在铁炉堡严密监视着术士。自诺莫瑞根沦陷以来，流离失所的修习者便失去了私密的学院，而在矮人的山城里召唤恶魔又有被发现的风险。",al={"为何送往暴风城","铁炉堡术士训练","诺莫瑞根术士为何离开"}},{q="卡兹莫丹的术士过去在哪里接受训练？",a="诺莫瑞根沦陷之前，卡兹莫丹的术士在这座科技之城里，跟随机械法师和恶魔学者接受训练。那场灾难使这些学派四散，幸存者也流亡他乡。",al={"诺莫瑞根术士历史","卡兹莫丹 过去的术士训练"}},{q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一名人类术士，负责管理暴风城已宰的羔羊地下的隐秘密室。他教导学徒召唤并束缚恶魔，其中也包括来自铁炉堡的侏儒新手。",al={"加科因是谁","加科因的职责"}},{q="已宰的羔羊是什么地方？",a="已宰的羔羊是暴风城法师区的一家酒馆。它的地窖里藏着一处术士聚会场所，避开了城中当局的视线。",al={"已宰的羔羊 酒馆","已宰的羔羊 在哪里"}},{q="加科因为何对新来者感到不满？",a="加科因担心，大批流亡侏儒的到来会让暴风城隐秘的术士团体引起注意。地方和导师都很有限，术士活动过于频繁，可能会让他们暴露在当局眼前。",al={"加科因的抱怨","加科因为何生气"}},{q="拉戈·黑钳是谁？",a="拉戈·黑钳是一名侏儒术士训练师，住在铁炉堡的阴暗小巷里。他将有潜力的新手送往暴风城，继续接受训练。",al={"拉戈·黑钳","已宰的羔羊 任务给予者"}}},fx={["2a96a15b"]={q="拉戈·黑钳为什么要派你去暴风城？",a="要让你精进驾驭恶魔的技艺，拉戈·黑钳别无选择。自从诺莫瑞根的陷落迫使侏儒施法者逃入铁炉堡，国王麦格尼·铜须就始终以警惕而怀疑的目光，监视着山中要塞里的黑暗魔法。在矮人的监视下，流亡铁炉堡的术士无法设立正规的修习密室，只能放下骄傲，将有潜力的学徒送往南方，向人类大师求教。",al={"为何派往暴风城","黑钳的动机","为何去已宰的羔羊"}}},fp="20,211,18.450.0,32.393.0,29.416.0,44.195.0,46.178.0,28.205.0,29.146.0,43.193.0,24.149.0"}
P.entries["quest:1716"] = {n="噬魂者",s="一名联盟术士远渡重洋，向先知塔卡尔请教召唤魅魔的方法。黑暗缚灵者加科因将暴风城的学徒派往贫瘠之地，寻求他们所需的知识。",h="一名联盟术士远渡重洋，向先知塔卡尔请教召唤魅魔的方法。黑暗缚灵者加科因将暴风城的学徒派往贫瘠之地，寻求他们所需的知识。",kw={"陶拉祖营地","黑暗缚灵者加科因","同心树","已宰的羔羊","暴风城","魅魔","先知塔卡尔","贫瘠之地","术士任务"},ang={["class:Warlock"]="身为术士，束缚一只魅魔标志着你在掌握心智操控与魅惑法术的道路上迈出了一步。要取得奇异的仪式材料，还需要以身涉险的胆量。",["faction:Alliance"]="身为联盟施法者，你要跨越海洋与大陆，深入争夺中的部落领地。"},sec={{t="西行险途",b="在暴风城法师区的已宰的羔羊地下，黑暗缚灵者加科因指引有潜力的术士学习召唤魅魔。这种恶魔吞噬灵魂，摧毁心灵，支配意志，因此不能贸然将其召入艾泽拉斯。术士需要一件强有力的诱饵：一件与纯洁爱情相关的物品。这件信物会将魅魔从扭曲虚空引出，让术士有机会击败并束缚它。暴风城的术士集会无法告诉他们去哪里寻找这样的物品。"},{t="敌境中的先知",b="加科因派遣学徒横渡无尽之海，前往卡利姆多寻找所需的媒介。先知塔卡尔就在干旱的贫瘠之地，靠近部落聚居地陶拉祖营地。要见到他，联盟术士必须穿越敌对半人马、野猪人和部落战士巡逻的荒野。仪式尚未开始，这段旅程就已在考验召唤者能否活下来。"}},faq={{q="这个任务的目的是什么？",a="你从暴风城前往卡利姆多，学习如何召唤并束缚一只完全听命于你的魅魔。",al={"为什么做噬魂者","魅魔任务目标","术士魅魔任务线"}},{q="为什么必须大老远跑到贫瘠之地？",a="黑暗缚灵者加科因派你前往贫瘠之地，是因为先知塔卡尔掌握着你所需的神秘知识，能帮助你找到纯洁爱情的象征，也就是召唤魅魔所需的诱饵。",al={"为什么去卡利姆多","为什么去贫瘠之地","为什么派我去那么远"}},{q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一位召唤大师，在暴风城已宰的羔羊下方的地下墓穴中活动。他避开城市卫兵的耳目，向术士新手传授恶魔契约、束缚术与黑暗法术。",al={"黑暗缚灵者加科因背景","谁发布噬魂者任务"}},{q="先知塔卡尔是谁？",a="先知塔卡尔是一位居住在贫瘠之地中部的神秘学者，就在牛头人前哨陶拉祖营地外。他为远道而来的术士指明方向，寻找能够将恶魔诱入艾泽拉斯的遗物。",al={"先知塔卡尔在哪里","先知塔卡尔背景"}},{q="为什么召唤魅魔需要爱情的象征？",a="魅魔会被真挚而纯洁的感情吸引，并将其吞噬。正如加科因所说，这种恶魔腐蚀心灵，支配意志，因此一件承载爱情的遗物就能将它从扭曲虚空引出。",al={"为什么魅魔需要爱情","魅魔诱饵背景","魅魔的诱饵"}},{q="贫瘠之地对联盟角色来说安全吗？",a="不安全。贫瘠之地是部落领土，那里有敌对的野兽、野猪人部族，以及陶拉祖营地这样的聚居地。寻找塔卡尔时，要低调行事，避开卫兵。",al={"贫瘠之地危险吗","部落会在贫瘠之地攻击我吗"}}},fp="17,129,24.466.0,29.355.0,34.109.0,47.173.0,28.216.0,22.188.0,55.167.0,46.168.0"}
P.entries["quest:1717"] = {n="加科因的召唤",s="加科因的召唤指引有潜力的联盟术士从铁炉堡南下，前往暴风城。在法师区地下，黑暗缚灵者加科因正等待着他们，监督他们驾驭更强大恶魔的进展。",h="加科因的召唤指引有潜力的联盟术士从铁炉堡南下，前往暴风城。在法师区地下，黑暗缚灵者加科因正等待着他们，监督他们驾驭更强大恶魔的进展。",kw={"加科因","加科因的召唤","铁炉堡","拉戈·黑钳","法师区","已宰的羔羊","魅魔","术士"},ang={["class:Warlock"]="作为术士，你受命从铁炉堡返回暴风城，开始分为多个步骤的仪式，束缚你的魅魔仆从。",["faction:Alliance"]="作为联盟的一员，你会看到隐秘的术士网络如何在各座主城之间保持联系，同时让恶魔学识避开平民的视线。",["race:Gnome"]="作为在铁炉堡接受拉戈·黑钳训练的侏儒术士，你被派往暴风城的地下网络，学习更深奥的恶魔知识。"},sec={{t="来自地下的消息",b="在联盟各地，恶魔学识始终隐于暗处。在铁炉堡，拉戈·黑钳为暴风城的兄弟会暗中留意四处游历的术士。当一名术士掌握了控制最初几名仆从的本领，消息很快就会传开。拉戈传话，要其离开卡兹莫丹的雪山，立即南下报到。"},{t="重返已宰的羔羊",b="在暴风城法师区的已宰的羔羊地下，黑暗缚灵者加科因统筹着城中术士的事务。在他看来，每个有能力的学徒都是一笔宝贵却危险的投资。他的召唤意味着，学徒即将跨入真正束缚恶魔的门槛。如今，降服一名来自扭曲虚空的魅魔的试炼就要开始。"}},faq={{q="是谁向我发出了召唤？",a="铁炉堡的术士训练师拉戈·黑钳代黑暗缚灵者加科因传达了召唤，后者负责暴风城的恶魔学识教学。",al={"任务给予者","任务起始者","拉戈·黑钳"}},{q="在哪里能找到黑暗缚灵者加科因？",a="黑暗缚灵者加科因住在已宰的羔羊下方幽暗曲折的地下墓穴中，那是暴风城法师区的一家酒馆。",al={"加科因位置","加科因在哪里","已宰的羔羊位置"}},{q="加科因为什么召唤我？",a="你的技艺已有足够长进，可以进行召唤并降服魅魔的仪式，为麾下增添一名恶魔。",al={"任务目的","有什么用","召唤原因"}},{q="与加科因交谈后会发生什么？",a="与加科因交谈后，他会派你执行噬魂者。你将前往危险的地域，收集召唤并束缚魅魔所需的仪式材料。",al={"下一步","后续任务","任务链"}},{q="为什么铁炉堡的术士要听从暴风城的命令？",a="出于生存所需，联盟术士维系着一个隐秘的联络网。铁炉堡和暴风城的术士保持联系，并将有潜力的学徒引荐给加科因，他在已宰的羔羊地下备有专门的仪式器具和相关学识。",al={"铁炉堡术士","侏儒术士暴风城","术士组织"}},{q="如果想留在卡兹莫丹，可以不理会这次召唤吗？",a="你可以推迟前往暴风城，但要学会召唤魅魔，就必须完成加科因的试炼。对于任何有志于精进的术士来说，这趟旅程都不可或缺。",al={"是否必须完成","能否跳过","是否需要去暴风城"}}},fx={["27281f2a"]={q="拉戈·黑钳为什么要派你去暴风城？",a="拉戈·黑钳接到了暴风城同道的明确指示，要留意途经铁炉堡、有潜力的术士。这个秘社已经在你的黑暗技艺上投入了大量时间和资源，拉戈希望确保你不会在接受黑暗缚灵者加科因的教导、精进技艺之前迷失方向或丢掉性命。",al={"拉戈为何要做这件事","拉戈·黑钳的动机","拉戈为何派往暴风城"}}},fp="15,195,30.308.0,30.309.0,26.152.0,37.125.0,26.137.0,36.168.0,59.232.0,58.158.0"}
P.entries["quest:1718"] = {n="岛民",s="在勇士岛，来自艾泽拉斯各地的战士要接受同侪的考验。训练师将久经磨炼的战士送往那里，让他们继续深造。这座岛屿位于商旅海岸近海，首席战士克兰诺克·马克雷德在那里等待着他们。",h="在勇士岛，来自艾泽拉斯各地的战士要接受同侪的考验。训练师将久经磨炼的战士送往那里，让他们继续深造。这座岛屿位于商旅海岸近海，首席战士克兰诺克·马克雷德在那里等待着他们。",kw={"勇士岛","克兰诺克·马克雷德","商旅海岸","棘齿城","格斗考验","贫瘠之地","岛民","战士"},ang={["class:Warrior"]="身为战士，你将从基础招式逐步迈向老练战士的战斗姿态，掌握其中的凶猛力量与多变战术。",["faction:Alliance"]="身为联盟战士，你要横渡大海，或穿越卡利姆多的荒野，才能抵达勇士岛。在这片远离人类与矮人要塞的险峻边地，你将展现自己对武艺的执着。",["faction:Horde"]="身为部落战士，你从雷霆崖或奥格瑞玛出发，前往贫瘠之地。在那里，你将在酋长们的注视之外证明自己的力量。"},sec={{t="利刃云集",b="联盟与部落各主城的战士训练师，会派已掌握基础技艺的学员前去与同侪较量。战斗展现的是战士的长进，而非地位或忠诚。因此，这段旅程将带他们离开文明之地的练武场，前往无尽之海上一座崎岖的岛屿。"},{t="勇士岛与商旅海岸",b="勇士岛位于贫瘠之地商旅海岸以东，就在棘齿城南面。你可以游过淹没沙洲的浅水，抵达那里。阵营归属在岛上无关紧要。战士们聚集在岛上的首席战士克兰诺克·马克雷德面前，等待他选定的试炼。"}},faq={{q="勇士岛是什么地方？",a="勇士岛是贫瘠之地商旅海岸近海的一座岩岛，位于棘齿城南面。来自艾泽拉斯各地的战士聚集于此，远离世俗权力的管辖，磨炼技艺、切磋武艺，接受战斗试炼。",al={"勇士岛在哪里","勇士岛背景故事","勇士岛"}},{q="克兰诺克·马克雷德是谁？",a="克兰诺克·马克雷德是勇士岛的首席战士。他会评估远道而来的人，判断他们的意志与技艺是否值得在战士之路上获得进一步指引。",al={"克兰诺克是谁","克兰诺克·马克雷德的职责","马克雷德 战士"}},{q="为什么部落与联盟的训练师都派战士来这里？",a="部落与联盟的训练师都会派战士前来，在战斗中检验武艺。奥格瑞玛、暴风城、雷霆崖和铁炉堡的训练师都认可勇士岛，认为能经受住岛上挑战的战士可以在此证明自己。",al={"为何双方阵营都来这里","勇士岛是否中立","部落与联盟 勇士岛"}},{q="如何从大陆前往勇士岛？",a="从贫瘠之地的棘齿城出发，沿商旅海岸向南行进。到达岸边后，向东游过沙洲浅滩，前往勇士岛。",al={"如何前往勇士岛","勇士岛路线","寻找勇士岛"}},{q="见到克兰诺克·马克雷德之后会发生什么？",a="克兰诺克·马克雷德确认你的来意并衡量你的决心后，会邀请你参加格斗考验。这场连续的战斗将让你迎战一波又一波挑战者，考验你的耐力。",al={"岛民之后是什么","克兰诺克·马克雷德 后续任务"}}},fp="12,244,21.276.0,34.293.0,20.200.0,23.178.0,64.244.0,47.136.0,43.163.1"}
P.entries["quest:1719"] = {n="格斗考验",s="勇士之争是在贫瘠之地海岸外的勇士岛上举行的一场残酷武术考验。这项竞技场混战由克兰诺克·马克雷德主持，它将雄心勃勃的战士们投入到一波又一波岛上挑战者及其冠军的围攻中，以证明他们具备了接受进阶训练所需的勇气与实力。",h="勇士之争是在贫瘠之地海岸外的勇士岛上举行的一场残酷武术考验。这项竞技场混战由克兰诺克·马克雷德主持，它将雄心勃勃的战士们投入到一波又一波岛上挑战者及其冠军的围攻中，以证明他们具备了接受进阶训练所需的勇气与实力。",kw={"勇士之争","贫瘠之地","大个子威尔","勇士岛","克兰诺克·马克雷德","特威吉·平头","战士考验"},ang={["class:Warrior"]="勇士之争是资深战士决定性的成人礼，它是一个熔炉，让他们在此证明自己的战斗姿态和战场耐力，从而解锁更深奥的技艺。"},sec={{t="无尽之海上的试炼场",b="勇士岛远离大陆的纷争，是强悍的格斗者、流亡者和战斗导师们的避难所。克兰诺克·马克雷德并不会随随便便教导任何一个走下船的流浪者。若想获得他的指点，有志向的战士必须参加勇士之争，这是一场旨在将真正的战士与虚张声势的伪善者区分开来的武术耐力与战场意识的公开考验。"},{t="铁与血的圆环",b="勇士之争的规则既简单又冷酷。当战士踏上围观人群中央的铁栅栏时，即是向擂台主持特威吉·平头发出开始比赛的信号。挑战者将接连不断地进入擂台，考验初学者的耐力。那些在前期战斗者中幸存下来的人，将面对该岛的重量级冠军——大个子威尔。击败他，是赢得克兰诺克尊重的唯一条件。"}},faq={{q="什么是勇士之争？",a="勇士之争是在勇士岛上举行的一种竞技场式的考验。它旨在测试有志向的战士是否具备接受克兰诺克·马克雷德高级战斗训练所需的原始耐力和技巧。",al={"勇士之争考验","什么是勇士之争","勇士岛竞技场"}},{q="勇士之争在哪里举行？",a="它在勇士岛举行，这是一座位于无尽之海、贫瘠之地东海岸外的崎岖岛屿。",al={"勇士之争在哪里","勇士之争位置"}},{q="谁负责组织这项考验？",a="战士导师克兰诺克·马克雷德负责管理岛上的战士并主持这项考验，而特威吉·平头则在坑边指挥比赛。",al={"谁举办勇士之争","勇士之争组织者"}},{q="擂台上的战斗是如何进行的？",a="战士踏上中央的铁栅栏以示准备就绪。随后，特威吉·平头会将一波又一波的勇士之争挑战者送入坑中，最后才会放出岛上强壮的冠军——大个子威尔。",al={"战斗如何进行","勇士之争波数","开始勇士之争"}},{q="大个子威尔是谁？",a="大个子威尔是勇士岛格斗者中公认的冠军。在擂台上击败他是通过勇士之争的最终要求。",al={"大个子威尔","大个子威尔是谁","勇士岛冠军"}},{q="为什么战士必须完成这项考验？",a="克兰诺克·马克雷德拒绝将他的武术技巧传授给那些未能在鲜血与战斗中对抗多名对手、证明自己坚韧程度的人。",al={"为什么要进行勇士之争","勇士之争目的"}}},fp="10,163,33.314.0,28.304.0,19.154.0,33.89.0,24.144.0,37.173.0,16.121.0,38.120.0"}
P.entries["quest:173"] = {n="森林里的狼人",s="卡洛尔，一位驻扎在夜色镇、对现状感到失望的前卫兵，委托冒险者去猎杀潜伏在暮色森林中那些邪恶的夜行影织者。通过前往阳光树林和烂果园进行狩猎，外来者可以向乔纳森·卡尔文大师的怪物猎人小队证明自己的实力。",h="卡洛尔，一位驻扎在夜色镇、对现状感到失望的前卫兵，委托冒险者去猎杀潜伏在暮色森林中那些邪恶的夜行影织者。通过前往阳光树林和烂果园进行狩猎，外来者可以向乔纳森·卡尔文大师的怪物猎人小队证明自己的实力。",kw={"阳光树林","卡洛尔","卡尔文","夜色镇","暮色森林","夜行生物","烂果园","影织者","狼人"},ang={["class:Hunter"]="猎杀夜行生物是对追踪术和野兽知识的极限考验，因为狼人既不是天然的野生动物，也不是普通的人类歹徒，而是会施展暗影法术的双足恐怖生物。",["faction:Alliance"]="夜色镇感觉已经被暴风城的王座厅完全抛弃，这使得镇民和像卡洛尔这样的义勇军不得不招募任何能抵挡怪物的游荡联盟冒险者。",["race:Human"]="对于来自艾尔文森林或西部荒野的人类来说，目睹暮色森林中如烂果园般的农场遭受的悲惨破坏，是对未受遏制的黑暗魔法能对王国粮仓造成何种影响的严峻警告。"},sec={{t="私人守卫",b="守夜人始终在与不断逼近夜色镇边界的亡灵、蜘蛛和歹徒进行斗争。对于像卡洛尔这样的人来说，官方卫队不仅行动迟缓，而且在净化土地方面表现得过于安于现状。卡洛尔离开了守夜人，转而投靠乔纳森·卡尔文大师，誓要将自己的利剑挥向异端与腐化，将它们彻底根除。但卡尔文大师并不会随意接纳任何人加入他的圈子；那些想要协助他们的人，必须首先证明自己能在森林中最凶猛的恐惧面前幸存下来。"},{t="夜行潜伏者",b="试炼之地位于阳光树林和遭受重创的烂果园，被称为狼人的野性犬科生物在此盘踞。其中，夜行影织者能够驾驭黑暗魔法，在将受害者撕碎之前，先使其致盲并束缚住他们。卡洛尔派遣有志向的猎人去击杀这些会使用法术的野兽，既是为了考验外来者的决心，也是为了削减这一威胁，而这些怪物的起源至今仍让夜色镇的保卫者们感到极度不安。"},{t="凭空出现的怪物",b="虽然狼人在暮色森林中已成为一场无法逃避的噩梦，但它们的存在令人费解。卡洛尔指出，狼人似乎是凭空出现的，在该地区并无自然血缘。与那些贪婪的野狼或从当地墓穴中爬出的尸体不同，这些双足捕食者掌握着离奇而陌生的巫术。猎杀影织者可以展现战斗技巧，但这只是触及了这种在森林中扎根的非自然灾难的表面。"}},faq={{q="卡洛尔是谁？",a="卡洛尔是一名猎人，也是夜色镇守夜人的前成员。由于对镇民兵谨慎的官僚作风感到沮丧，他加入了乔纳森·卡尔文大师的麾下，积极猎杀威胁着暮色森林的邪恶生物。",al={"卡洛尔","卡洛尔 夜色镇","谁发布了林中的狼人任务"}},{q="卡洛尔为什么要猎杀夜行影织者？",a="卡洛尔将夜行影织者作为对他人的技巧和勇气的试炼。任何想要协助卡尔文大师任务的人，都必须证明自己能够猎杀危险的施法狼人，而不是只会空谈保卫小镇。",al={"为什么要击杀影织者","林中的狼人任务目标"}},{q="在哪里可以找到夜行影织者？",a="它们潜伏在夜色镇西部和西南部的两个主要区域：阳光树林那些扭曲的树木之间，以及废弃且杂草丛生的烂果园。",al={"夜行影织者在哪里","影织者位置"}},{q="暮色森林的狼人是从哪里来的？",a="对于暮色森林的人民来说，它们的突然出现是一个谜。正如卡洛尔所观察到的，这些野兽仿佛凭空显现，将黑暗的暗影魔法和贪婪的狂暴带入了一片本已濒临崩溃的森林。",al={"暮色森林狼人起源","为什么暮色森林有狼人","狼人从哪来"}},{q="卡尔文大师是谁？",a="乔纳森·卡尔文大师是一位驻扎在夜色镇的独立怪物猎人。他和他的追随者在守夜人的管辖范围之外行动，专注于彻底根除整个地区的邪恶、亡灵和奇异的怪物。",al={"卡尔文","卡尔文大师","卡尔文大师是谁"}},{q="卡洛尔为什么要离开守夜人？",a="卡洛尔对守夜人的消极和自满感到失望。当黑暗不断逼近时，比起在周边的围栏上驻守，他更倾向于卡尔文那种猎杀邪恶的主动方式。",al={"为什么卡洛尔离开守夜人","卡洛尔 守夜人"}}},fp="19,295,15.398.0,21.355.0,21.469.1,13.189.0,52.184.0,45.154.0,43.214.0,22.194.0,36.197.0"}
P.entries["quest:1738"] = {n="同心树",s="同心树是一项联盟术士任务，它派遣修行者深入灰谷，以寻回一颗古老而悲情的树木的枝条。术士们受隐士先知塔卡尔之托，代表黑暗缚灵者加科因寻找这一浪漫遗物，将其作为诱饵，在暴风城引诱并奴役一只魅魔。",h="同心树是一项联盟术士任务，它派遣修行者深入灰谷，以寻回一颗古老而悲情的树木的枝条。术士们受隐士先知塔卡尔之托，代表黑暗缚灵者加科因寻找这一浪漫遗物，将其作为诱饵，在暴风城引诱并奴役一只魅魔。",kw={"安娜瑟拉","灰谷","贫瘠之地","暗滩教派","黑暗缚灵者加科因","同心树","拉瑟里安","奥迪拉兰","魅魔","先知塔卡尔"},ang={["class:Warlock"]="获得同心树的一块碎片对于初出茅庐的术士来说是一个关键的里程碑，使他们能够召唤并奴役一只魅魔，在战场上操纵敌人的思想。",["faction:Alliance"]="前往卡利姆多会让年轻的联盟施法者暴露在充满争议的荒野、敌对的部落前哨以及古老的暗夜精灵废墟之中。",["race:Human"]="暴风城中隐藏的术士往往依赖像先知塔卡尔这样遥远的侦察兵，来定位那些人类奥术师从未记录过的旧卡利姆多遗物。"},sec={{t="悲剧爱情的纪念碑",b="根据先知塔卡尔的说法，同心树树生长的地方，是两名暗夜精灵恋人安娜瑟拉和拉瑟里安在万年前的上古之战中共同倒下的地方。在他们最后的呼吸和永恒的爱意滋养下，这棵树长成了纯洁不朽爱情的象征。对于凡人而言，它是一座神圣而悲伤的纪念碑，但对于黑暗艺术的修行者来说，集中的情感能量是强大的魔法燃料。"},{t="诱捕魅魔",b="魅魔以凡人的激情、欲望和情感折磨为食。塔卡尔意识到，与浸透了数千年纯粹、不朽爱意的神器相比，普通的诱惑显得苍白无力。同心树的一部分为黑暗缚灵者加科因提供了将这些狡猾的恶魔通过虚空，引诱到暴风城法师区的召唤仪式中所需的精确催化剂。"},{t="奥迪拉兰废墟",b="这棵树屹立在灰谷西北部的奥迪拉兰废墟中。然而，取回它不仅需要面对野生猛兽和敌对领土，还要应对占据了精灵废墟的暗滩教派邪教徒。一旦取回，就必须穿过海洋，带回暴风城的已宰的羔羊，以开启奴役仪式。"}},faq={{q="为什么术士需要同心树来召唤魅魔？",a="魅魔是被激情、欲望和强烈情感羁绊所吸引的恶魔。同心树发芽的地方是两名忠贞的暗夜精灵恋人在一万年前共同陨落之处。他们挥之不去的激情灌注到了木头中，创造了将魅魔通过虚空吸引过来的绝佳精神诱饵。",al={"为何需要同心树","魅魔诱饵","为何用木头召唤魅魔"}},{q="同心树树生长在哪里？",a="它位于灰谷西北部森林中的奥迪拉兰废墟，在黑海岸以南不远的地方。该地区已经落入了邪恶教派的手中。",al={"同心树位置","同心树在哪里","如何找到同心树"}},{q="安娜瑟拉和拉瑟里安是谁？",a="他们是两名在上古之战中并肩作战的暗夜精灵。当他们在战场上共同倒下时，同心树树在他们弥留之际呼出最后一口气的地方发芽，作为他们坚贞爱情的纪念碑。",al={"安娜瑟拉和拉瑟里安","那对恋人是谁","灰谷的恋人"}},{q="先知塔卡尔是谁？",a="塔卡尔是一位与暴风城术士结盟的天赋异禀的人类先知。他选择居住在南贫瘠之地陶拉祖营地附近的隐居处，利用他神秘的视力穿透时间的迷雾，为黑暗缚灵者加科因寻找被遗忘的遗物。",al={"塔卡尔是谁","先知塔卡尔","贫瘠之地的隐士"}},{q="联盟术士如何从贫瘠之地安全前往灰谷？",a="从贫瘠之地穿越的联盟旅行者必须避开莫尔杉壁垒中戒备森严的部落前哨。术士通常会滑过主门东侧栅栏上一处无人看守的缺口，走石爪山脉的高路，或者游过边界河流。",al={"如何前往灰谷","绕过莫尔杉","避开部落壁垒"}},{q="加科因收到同心树后会发生什么？",a="加科因利用这块木头在暴风城已宰的羔羊下方的地下墓穴中准备仪式。他画了一个召唤法阵，从扭曲虚空中拉出一只魅魔，并指派术士去击败并奴役她。",al={"获得同心树后做什么","加科因用同心树做什么"}}},fp="10,221,25.318.0,20.325.0,23.303.1,53.262.0,36.160.0,32.215.0,22.220.0,73.260.0,49.231.0"}
P.entries["quest:1739"] = {n="誓缚",s="在暴风城，术士们试图将魅魔束缚于自己的意志之下。在已宰的羔羊地下，一名学徒用附魔的同心树之核召唤恶魔，并在战斗中将其击败。",h="在暴风城，术士们试图将魅魔束缚于自己的意志之下。在已宰的羔羊地下，一名学徒用附魔的同心树之核召唤恶魔，并在战斗中将其击败。",kw={"束缚","墓穴","黑暗缚灵者","加科因","同心树","已宰的羔羊","暴风城","魅魔","召唤法阵"},ang={["class:Warlock"]="身为人类或侏儒术士，你将从驱使没有心智的小鬼和虚空行者，逐步成长到驾驭拥有智慧、精于算计的恶魔。",["faction:Alliance"]="身为联盟的一员，你会看到，尽管教会的教义不容许暗影魔法，暴风城仍默默容忍着隐秘角落中的这类法术。"},sec={{t="深入墓穴",b="在暴风城法师区的已宰的羔羊地下，一处墓穴为城中的术士提供庇护。他们在那里修习禁忌法术，避开城市卫兵和光明大教堂的耳目。石制召唤法阵引导虚空的力量，让学徒能够跨越世界之间的帷幕。"},{t="降服魅魔",b="术士需要一枚准备妥当的同心树之核来召唤魅魔。仪式会在召唤法阵处打开一道裂隙，但即使心志坚定，也可能遭到恶魔的腐蚀与压制。要驾驭它，术士必须在一对一的战斗中将其击败。它的实体会返回扭曲虚空，而真正束缚它的纽带则会牢牢确立。"},{t="加科因的秘密",b="召唤出的生物被杀死后，学徒会将耗尽力量的核心交还给黑暗缚灵者加科因。随后，加科因会传授跨越虚空召唤魅魔所需的知识。这场仪式标志着一名联盟术士已成长为熟练的施法者，获准驾驭那些反复无常、拥有智慧的恶魔。"}},faq={{q="召唤在何处进行？",a="召唤在已宰的羔羊下方的地下墓穴中进行，这家酒馆位于暴风城的法师区。沿着螺旋阶梯走过酒馆的地窖，便能抵达一处设有奥术召唤法阵的地下密室。",al={"召唤地点","魅魔召唤地点","墓穴位置"}},{q="同心树之核有什么用途？",a="同心树之核为召唤提供锚点与能量。它取自同心树，这棵树生长在灰谷，是两位暗夜精灵恋人在上古之战期间殒命之处长出的树木。它的灵性共鸣会打开一道裂隙，将一只魅魔从扭曲虚空的另一端引来。",al={"为何需要同心树之核","同心树的作用"}},{q="术士为何必须杀死魅魔？",a="术士必须杀死魅魔，才能确立对它的支配。魅魔擅长操纵与精神控制，任其现身却不将其击败，只会招致毁灭。在它返回虚空重新凝聚形体之前，战斗会将术士的权威烙印在它的灵魂之上。",al={"为何要与魅魔战斗","为何要杀死恶魔才能束缚它"}},{q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一名资深术士，住在已宰的羔羊，负责监督暴风城联盟术士的训练。他安排秘密获取恶魔学器物，并判断学徒是否具备驾驭恶魔的意志。",al={"加科因是谁","黑暗缚灵者加科因的故事"}},{q="加科因提到的苏伦娜是谁？",a="苏伦娜·凯尔东曾是加科因的学生。她跟着迪菲亚跑了，而你先前找回了她的颈饰。加科因带着讥诮猜测，她是否是派来扭曲他心智的伪装魅魔，随后又觉得自己太高看她了。",al={"提及苏伦娜","苏伦娜是谁"}},{q="魅魔可以在暴风城的街道上行走吗？",a="圣光教会和王国当局严禁公开研习恶魔学。被束缚的恶魔可以跟随术士穿行于城中，但这类活动仍藏在阴影、地下室，以及已宰的羔羊墓穴这样的隐秘密室中。",al={"卫兵能否看见魅魔","暴风城召唤恶魔是否合法"}}},fx={["69ec55c9"]={q="黑暗缚灵者加科因为什么要做这件事？",a="加科因正在考验你作为术士学徒的自律与技艺。他要确认你拥有足够的意志力，能够让恶魔之力听命于你，而不会屈服于它们的欺骗。证明你能在酒馆下方击败召唤出的恶魔，就表明你有资格学习如何永久束缚和控制一只魅魔。",al={"加科因为何需要这个","加科因的动机","为何召唤魅魔 加科因"}},["2be029b1"]={q="你奉命召唤的魅魔是什么？",a="你要召唤的是一只魅魔——来自扭曲虚空、充满诱惑而又狡诈的恶魔。魅魔以操纵欲望、压倒意志坚定者的心智而闻名。它并不天然栖居在暴风城；你的法术与同心树之核会在局部撕开一道裂隙，专门将它拉出来，让你击败它并奴役它的精魂。",al={"魅魔是什么","誓缚的目标是谁","召唤出的魅魔"}},f36093f2={q="加科因为什么让你召唤魅魔，而不亲自动手？",a="术士无法代替另一名术士束缚恶魔、令其效力；奴役契约要求召唤者亲自压服恶魔。加科因早已掌握了自己的黑暗技艺。要召来魅魔作为仆从，你就必须亲自面对危险，证明自己能够驾驭它的魅惑，并将它的意志束缚于你的意志之下。",al={"为何必须亲自召唤魅魔","为何选中自己 誓缚","加科因为何不能迎战魅魔"}}},fp="11,182,22.291.0,26.321.0,15.284.1,36.202.0,43.262.0,39.267.0,28.254.0,34.234.0,50.249.0"}
P.entries["quest:174"] = {n="仰望星空",s="“仰望星空”开启了维克托·安特拉斯探索暮色森林阴森树冠之外的尝试。维克托坚信，除了奥术迷信之外，还有某种科学解释能够说明这片森林的黑暗诅咒，因此他招募你来为他的一位侏儒伙伴所设计的望远镜收集部件。",h="“仰望星空”开启了维克托·安特拉斯探索暮色森林阴森树冠之外的尝试。维克托坚信，除了奥术迷信之外，还有某种科学解释能够说明这片森林的黑暗诅咒，因此他招募你来为他的一位侏儒伙伴所设计的望远镜收集部件。",kw={"青铜管","考格","夜色镇","暮色森林","仰望星空","望远镜","维克托·安特拉斯"},ang={["faction:Alliance"]="当夜色镇的守夜人巡逻队在道路上抵御恐怖威胁时，维克托的项目代表了小镇微小而顽固的希望，他们想要了解究竟是什么毒害了他们的家园。",["profession:Engineering"]="整个工程完全取决于侏儒的设计和精湛的金属工艺，这让修理匠们有机会直接参与并协助维克托的天文探索。",["race:Gnome"]="维克托依赖于他那位侏儒伙伴考格的独创性，这证明了侏儒的技艺是如何即使在王国最黑暗的角落也能带来秩序与理性的。"},sec={{t="探索天空",b="在笼罩着夜色镇的阴霾与恐惧之中，维克托·安特拉斯对暮色森林的厄运有着一种截然不同的看法。维克托并不认为这片土地的腐化完全归咎于黑魔法、诅咒或不安分的亡灵，他怀疑在树冠之上有着更伟大的真理。在侏儒伙伴考格所绘制的蓝图的帮助下，他着手制造一台能够窥探天穹的光学仪器。"},{t="工程学问题",b="为了开始组装这台观星装置，维克托需要一个坚固的框架。按照考格的规格说明，他请求旅者去获取一根机械青铜管。这一步直接依赖于凡人机械的独创性而非咒法，突显了维克托固执的坚持，即实用的工艺与观察也许能让那些神秘主义失效的地方重见光明。"}},faq={{q="维克托·安特拉斯是谁？",a="维克托·安特拉斯是夜色镇的一位学者。与许多被恐惧瘫痪或被迷信所吞噬的当地人不同，他试图通过研究星辰来为暮色森林所遭受的腐化寻找合理的解释。",al={"维克托","谁给予仰望星空任务","维克托·安特拉斯"}},{q="维克托为什么要制造望远镜？",a="维克托相信在魔法之外存在着某种有形的真理，可以解释暮色森林的奇异变化。他希望通过望远镜凝视天空，能够揭示当地传说和施法者们所忽略的见解。",al={"为什么要观测星辰","为什么暮色森林需要青铜管","夜色镇望远镜任务"}},{q="考格是谁？",a="考格是一位侏儒工程师，也是维克托的朋友。他绘制了建造这台观星装置所需的机械蓝图。",al={"侏儒考格","谁设计了望远镜"}},{q="在哪里可以获得青铜管？",a="青铜管通常由拥有中等经验的工程师制作。并非工程师的旅者通常可以通过交易、拍卖行，或者从偶尔携带存货的旅行工程学商贩那里获得。",al={"如何获得青铜管","青铜管位置","在哪里寻找青铜管"}},{q="这是长任务线的一部分吗？",a="是的。这项任务是在夜色镇组装和校准维克托观星装置的多阶段工作的第一步。",al={"仰望星空任务链","仰望星空有多少个任务"}},{q="为什么维克托要在暮色森林寻找自然层面的解释？",a="尽管森林中爬满了亡灵和黑暗魔法，但维克托相信某种基本的宇宙或自然法则可能仍在支配着这种转变，这驱使他在对星辰的研究中寻求答案。",al={"为什么在暮色森林寻找科学解释","暮色森林的魔法与科学"}}},fp="17,214,19.316.0,23.254.0,28.132.0,43.140.0,11.92.0,36.163.0,35.101.0,60.158.0"}
P.entries["quest:1740"] = {n="索兰鲁克宝珠",s="在南贫瘠之地，杜安·卡汉让术士们收集散落的索兰鲁克碎片。他们试图重铸一颗封存着失宠恶魔精华的宝珠。",h="在南贫瘠之地，杜安·卡汉让术士们收集散落的索兰鲁克碎片。他们试图重铸一颗封存着失宠恶魔精华的宝珠。",kw={"黑暗深渊","恶魔","杜安·卡汉","索兰鲁克宝珠","扎尔盖恩的宝珠","暗影之牙","索兰鲁克","术士"},ang={["class:Warlock"]="重铸索兰鲁克是你术士生涯中的一个重要里程碑。你将从中了解燃烧军团如何惩戒同类，以及如何将被束缚的恶魔用于实用的法器之中。",["faction:Horde"]="身为部落的一员，你可以在环境严酷的南贫瘠之地找到杜安·卡汉。四处游历的咒术师来到这片平原，寻求高深的黑暗知识。"},sec={{t="失宠者的容器",b="在燃烧军团中，失败意味着永恒的刑罚。当低阶恶魔失去主人的宠信，它们的灵魂就会被束缚在水晶宝珠之中。燃烧军团将这些牢笼交给凡人中的咒术师和术士，作为承载力量的容器，受恶魔控制。击碎宝珠并不能释放其中的囚徒；即便是碎片，也依然蕴含着强大的魔力。"},{t="散落两片大陆",b="索兰鲁克的宝珠碎片散落在两片大陆上。暮光之锤的教徒持有较小的碎片，藏身于灰谷黑暗深渊潮湿的洞穴中。一名巫师占有了较大且大致完好的另一半，身处银松森林中鬼魂出没的影牙城堡废墟。杜安·卡汉毕生研究燃烧军团的宝珠，曾经重组过扎尔甘宝珠。有了找回的碎片，他就能将索兰鲁克复原为一件可用的法器。"}},faq={{q="索兰鲁克宝珠是什么？",a="索兰鲁克曾是燃烧军团中一名失宠的恶魔。按照恶魔的惯例，它的灵魂被囚禁在一颗魔法宝珠中，交给凡人施法者使用。宝珠后来被击碎，但碎片依然保有这名恶魔的力量。",al={"索兰鲁克背景","索兰鲁克是什么","索兰鲁克曾是谁"}},{q="杜安·卡汉是谁？",a="杜安·卡汉是一名隐居在南贫瘠之地的术士，毕生致力于研究和重铸燃烧军团的宝珠。他曾花费多年重组扎尔甘宝珠，也会帮助初出茅庐的术士拼合索兰鲁克。",al={"杜安·卡汉是谁","杜安·卡汉的过往"}},{q="宝珠碎片为何分散在两座不同的地下城中？",a="宝珠被分成了两个主要部分。暮光之锤的教徒在黑暗深渊持有较小的碎片，而一名巫师在影牙城堡占有了较大的残片。",al={"碎片为何在黑暗深渊和影牙城堡","索兰鲁克碎片在哪"}},{q="谁能承担这项任务？",a="希望精进技艺、掌控以被囚禁的恶魔灵魂制成的法器的术士，可以参与这项仪式。",al={"谁能做这个任务","索兰鲁克宝珠是否仅限术士"}},{q="杜安·卡汉会如何处理找回的碎片？",a="杜安·卡汉会研究找回的碎片，以深入探索燃烧军团遗物，然后按照术士选择的形制，将碎片重铸成一件法器。",al={"收集碎片后会发生什么","重铸索兰鲁克"}},{q="扎尔甘宝珠是什么？",a="扎尔甘宝珠是一座牢笼，囚禁着燃烧军团中一名失宠的恶魔。杜安·卡汉找到了它，并花费多年将其重铸，供自己使用。",al={"扎尔甘宝珠","扎尔甘背景"}}},fp="20,161,24.287.0,27.433.0,29.240.0,19.243.0,52.173.0,28.120.0,54.166.0,27.159.0"}
P.entries["quest:175"] = {n="仰望星空",s="在夜色镇，维克托·安特拉斯正在按照Cog的蓝图制作望远镜，为此寻找一面镜子。他派你前往暮色森林南部寻找玛丽，人们记得她总是带着一面镜子。",h="在夜色镇，维克托·安特拉斯正在按照Cog的蓝图制作望远镜，为此寻找一面镜子。他派你前往暮色森林南部寻找玛丽，人们记得她总是带着一面镜子。",kw={"盲眼玛丽","夜色镇","暮色森林","仰望星空","镜子","玛丽","望远镜","静谧花园","维克托·安特拉斯"},ang={["faction:Alliance"]="帮助维克托制作望远镜，为这座被恐惧与腐朽吞噬的小镇带来了一丝难得的求知与进步之光。",["profession:Engineering"]="望远镜的组装遵循精密的光学设计，依照侏儒的蓝图反射并放大微弱的星光。"},sec={{t="反射镜面",b="维克托·安特拉斯已经有了制作望远镜的青铜管。按照Cog的蓝图，他现在需要一面镜子，在镜筒中引导并反射光线。夜色镇物资短缺，精良的镀银玻璃难以制作，于是维克托想起了当地一位名叫玛丽的女子，她因随身携带一面镜子而闻名于这一带。"},{t="南方寻踪",b="玛丽的旧居位于暮色森林南部深处，就在静谧花园墓场以北。要抵达那里，你必须离开守夜人巡逻守护的安全地带，进入枯败的林间，那里有饥饿的狼、凶野的蜘蛛和游荡的亡灵出没。"},{t="悲惨的住民",b="玛丽在南方的小屋揭示了维克托记忆中那位女子的遭遇。她就是盲眼玛丽，一个在旧居和墓场附近徘徊的幽灵，被生前的记忆与旧物束缚着。"}},faq={{q="维克托·安特拉斯正在制作什么？",a="维克托正在夜色镇山坡上的小屋里，按照工匠考格绘制的设计图制作一架天文望远镜。",al={"维克托 望远镜","仰望星空 计划","维克托 在制作什么"}},{q="维克托为什么需要一面镜子？",a="考格的蓝图要求用一面镜子在望远镜中反射并汇聚光线。维克托记得玛丽随身带着一面镜子，希望能用它来组装望远镜。",al={"为什么需要镜子","反射镜面 望远镜"}},{q="在哪里能找到玛丽？",a="玛丽破败的家位于暮色森林东南部，就在静谧花园墓场以北。",al={"玛丽 在哪里","玛丽 位置 暮色森林","寻找盲眼玛丽"}},{q="玛丽是谁？",a="在这片土地陷入受诅咒的黑暗之前，玛丽住在暮色森林南部，夜色镇一带的人都知道她总是带着一面镜子。你可以到静谧花园墓场附近的旧居，了解她后来的遭遇。",al={"盲眼玛丽是谁","盲眼玛丽的往事"}},{q="玛丽还留着她的镜子吗？",a="玛丽说她曾有过一面镜子，但如今已经不在她手中了。她只能告诉你镜子的去向。",al={"玛丽 有镜子吗","盲眼玛丽的镜子"}},{q="玛丽的小屋周围有哪些危险？",a="亡灵、凶野的夜行蝙蝠、毒网蜘蛛和狂暴的狼在东南部的树林与静谧花园墓场中徘徊，猎食那些冒险前往夜色镇以南的旅人。",al={"玛丽 附近的危险","静谧花园墓场的威胁"}}},fp="17,173,20.295.0,19.241.0,17.249.1,38.124.0,38.168.0,24.88.0,12.219.1,39.108.1,37.174.0"}
P.entries["quest:1758"] = {n="阴谋之书",s="在棘齿城上方，斯坦哈德·法尔杉派一名有志进取的联盟术士前往铁炉堡图书馆。地狱猎犬的饥渴足以压倒毫无准备的召唤者，而阴谋之书记载着召唤并束缚这种恶魔所需的知识。",h="在棘齿城上方，斯坦哈德·法尔杉派一名有志进取的联盟术士前往铁炉堡图书馆。地狱猎犬的饥渴足以压倒毫无准备的召唤者，而阴谋之书记载着召唤并束缚这种恶魔所需的知识。",kw={"地狱猎犬","探险者大厅","铁炉堡","克罗姆·粗臂","棘齿城","斯坦哈德·法尔杉","阴谋之书","术士"},ang={["class:Warlock"]="对术士而言，取得阴谋之书是迈向驾驭地狱猎犬的一场试炼，让你超越低阶仆从，踏入反魔法的恶魔学领域。",["faction:Alliance"]="身为联盟术士，你从卡利姆多的边陲返回铁炉堡的探险者大厅，寻找禁忌的黑暗典籍。",["race:Dwarf"]="身为矮人，你会发现，埋首于探险者大厅的人并非都在挖掘Titan遗物；克罗姆·粗臂就在私下编纂恶魔学识。"},sec={{t="吞噬魔法的野兽",b="小鬼、虚空行者或魅魔都能通过仪式降服，但地狱猎犬带来的是另一种危险。地狱猎犬为燃烧军团效力，追猎并吞噬奥术能量。普通的召唤法阵在它面前会土崩瓦解，束缚尚未生效，召唤者的魔力就已被吸干。斯坦哈德·法尔杉在贫瘠之地的据点俯瞰着棘齿城，他深知初学者绝不能毫无准备地尝试束缚这种恶魔。"},{t="最初的束缚",b="初学者需要借助阴谋之书中的奥术公式，才能安全地召出并束缚地狱猎犬。这份手稿出自最早在没有外力帮助的情况下成功驯服地狱猎犬的凡人术士结社之手。书中详细记载了抵御这种生物的饥渴所需的地卜术、材料和束缚符文。那本抄本早已遗失，斯坦哈德和他的同道也因此无缘这部杰作。"},{t="丹莫罗的藏书者",b="斯坦哈德无法亲自提供这部典籍，只得派联盟术士横渡无尽之海，前往铁炉堡的探险者大厅。四处游历的矮人术士克罗姆·粗臂就住在那里，晚年一直埋首于古老手稿和图书馆档案。如果东部王国的记载中还留有这本失落魔典的线索，它就藏在克罗姆精心编纂的目录里。"}},faq={{q="我为什么要寻找阴谋之书？",a="阴谋之书记载着最早在没有外力帮助的情况下召唤并降服地狱猎犬的凡人术士留下的精确指引。普通的召唤仪式无法困住一只会主动吞噬魔法能量的恶魔。",al={"阴谋之书是什么","为何寻找这本书","阴谋之书的用途"}},{q="克罗姆·粗臂是谁？",a="克罗姆·粗臂是一名四处游历的矮人术士，住在铁炉堡探险者大厅的图书馆里。他整日窝在尘封的典籍之间，编目整理古老的历史档案。",al={"克罗姆在哪里","克罗姆·粗臂是谁","克罗姆 铁炉堡"}},{q="斯坦哈德·法尔杉为什么会在贫瘠之地？",a="斯坦哈德·法尔杉是一位造诣深厚的人类术士，在棘齿城上方的峭壁上拥有一处幽静的中立据点。在肯瑞托和暴风城当局的监视之外，他向联盟和部落的术士传授强大的恶魔学识。",al={"斯坦哈德的位置","为何在棘齿城","斯坦哈德是谁"}},{q="与克罗姆·粗臂交谈之后会发生什么？",a="克罗姆·粗臂记得，旧编目簿中曾提及这部典籍。他让你追寻散失的部分，并找回重编这部魔典所需的稀有施法材料。",al={"后续任务","见过克罗姆之后","阴谋之书下一步"}},{q="部落术士能做这个任务吗？",a="这趟前往铁炉堡的旅程是为联盟术士准备的。斯坦哈德会交给部落术士一项对应的任务，派他们在部落领地内寻找知情者。",al={"部落版本","是否仅限联盟"}},{q="这条任务线会解锁哪种恶魔？",a="完成阴谋之书任务链时，术士要在仪式中与召唤出的地狱猎犬交战。术士由此学会召唤并束缚地狱猎犬，使其成为永久的仆从。",al={"哪种恶魔","地狱猎犬任务","能获得什么宠物"}}},fp="17,162,27.425.0,17.384.0,25.380.0,44.208.0,21.188.0,37.254.0,44.178.1,33.135.0,38.144.0"}
P.entries["quest:176"] = {n="通缉：霍格",s="在艾尔文森林西南部，霍格击退了当地所有试图将他铲除的人。联盟在闪金镇外张贴悬赏，征求这位体型庞大、生性凶残的豺狼人酋长的首级。",h="在艾尔文森林西南部，霍格击退了当地所有试图将他铲除的人。联盟在闪金镇外张贴悬赏，征求这位体型庞大、生性凶残的豺狼人酋长的首级。",kw={"悬赏","治安官杜汉","艾尔文森林","林边空地","豺狼人","闪金镇","霍格","通缉"},ang={["faction:Alliance"]="对联盟英雄而言，击败霍格是一场必经的试炼，他们在保卫暴风城腹地的战斗中证明自己的勇气与实力。",["race:Human"]="对艾尔文森林的人类而言，杀死霍格就能保住家园和道路上的商贸往来，豺狼人的伏击已让他们惶恐了数月。"},sec={{t="林中威胁",b="艾尔文森林饱受匪患和狗头人侵扰，而南部的豺狼人在霍格的残暴统领下，变得愈发猖獗，也更有组织。他比一般的河爪豺狼人更高大，在林边空地附近扎下了营地。他从那里出击，伏击过往行人，击溃前来制服他的当地民兵巡逻队。"},{t="闪金镇的困境",b="暴风城军队兵力吃紧，无法抽调正规部队维持首都郊外的治安。因此，治安官杜汉采取了不同寻常的举措，公开悬赏捉拿霍格。追猎他意味着深入充满敌意的豺狼人领地。他的凶残让艾尔文森林的冒险新手们闻风丧胆。"}},faq={{q="霍格是谁？",a="霍格是一名体型异常庞大、生性凶残的豺狼人首领，在艾尔文森林西南部肆虐。他统领着林边空地周围的豺狼人群，并以残暴的手段击退了暴风城卫兵此前所有试图抓捕或击杀他的行动。",al={"霍格是谁","霍格背景故事","霍格是什么"}},{q="在哪里可以找到霍格？",a="霍格在艾尔文森林西南部的豺狼人营地间游荡，活动范围靠近被称为林边空地的南部边缘。这片区域就在与西部荒野和暮色森林交界的河流北侧。",al={"霍格位置","霍格在哪里","寻找霍格"}},{q="为什么有人悬赏捉拿霍格？",a="霍格击溃了当地巡逻队，对过往行人构成致命威胁，促使暴风城军队悬赏捉拿他。王国各地的正规军兵力吃紧，治安官杜汉只得求助于独立行动的冒险者和赏金猎人，以消除这一威胁。",al={"为什么要杀霍格","霍格通缉告示","谁悬赏捉拿霍格"}},{q="谁负责接收霍格的死亡证明？",a="将霍格已死的证明，也就是他的巨大的豺狼人爪，直接交给治安官杜汉。他指挥着驻扎在闪金镇的当地守军。",al={"霍格交任务","霍格在哪里交任务","谁要霍格的爪子"}},{q="为什么霍格比其他豺狼人危险得多？",a="霍格比游荡在艾尔文森林的普通豺狼人体型大得多，也凶残得多。他的攻击更为猛烈，也能承受多得多的伤害，独自迎战又低估他的人往往会败在他手下。",al={"霍格强吗","霍格为什么是精英"}},{q="为什么暴风城卫兵不能自行对付霍格？",a="王国的军事资源已严重损耗，现有兵力又被牵制在重要边境的防御事务，或瓦里安·乌瑞恩国王失踪一事上。治安官杜汉在闪金镇率领的小股部队人手不足，无法安全地追猎这样一头顽强的怪物。",al={"治安官杜汉为什么不杀霍格","暴风城军队在哪里"}}},fx={fccb34f1={q="巨大的豺狼人爪有什么用？",a="巨大的豺狼人爪是霍格已死的确凿证据。这个蛮兽击退了所有抓捕行动，因此治安官杜汉和暴风城军队要求看到无可辩驳的实物证据，才会发放公告中的悬赏。",al={"巨大的豺狼人爪","为什么需要霍格的爪子","霍格的爪子有什么用"}}},fp="16,186,21.319.0,23.336.0,14.238.0,26.198.0,32.284.0,41.135.0,52.214.0,56.251.0"}
P.entries["quest:177"] = {n="仰望星空",s="维克托·安特拉斯需要盲眼玛丽的眼镜，用来制作他在夜色镇的望远镜。一个疯狂的食尸鬼把它带到了暮色森林南部的静谧花园墓场。",h="维克托·安特拉斯需要盲眼玛丽的眼镜，用来制作他在夜色镇的望远镜。一个疯狂的食尸鬼把它带到了暮色森林南部的静谧花园墓场。",kw={"盲眼玛丽","齿轮","夜色镇","疯狂的食尸鬼","仰望星空","玛丽的眼镜","望远镜","静谧花园墓场","维克托·安特拉斯"},ang={["class:Priest"]="身为牧师，你可以在静谧花园墓场见证暮色森林死者的悲惨命运，死去的村民已沦为疯狂的拾荒者。",["faction:Alliance"]="身为联盟的一员，你会看到暮色森林居民的悲惨命运：在暴风城王国危险的边境地带，镇上遗失的旧物落入了饥饿的亡灵手中。",["profession:Engineering"]="工程师能够领会维克托的巧思：他将普通的抛光手镜改造成了天文仪器的反射部件。"},sec={{t="旧日遗物",b="盲眼玛丽曾经十分珍爱一面华丽的镜子。一场变故夺走了她的视力和神智，让她成了哭泣的幽魂，此后她便把镜子扔到了自家谷仓后面的泥地里。如今，天文学家维克托·安特拉斯需要这面镜子，用来制作他在夜色镇的望远镜。早在他开始研究星空之前，镜子就已被拿走了。"},{t="墓地拾荒者",b="一个疯狂的食尸鬼从破败农舍后面捡走了镜子。永无止息的饥饿驱使这只亡灵生物向南游荡，将镜子带到了静谧花园墓场。它出没于杂草丛生的墓碑间一座废弃的礼拜堂里。你要面对南部林地中食人的恐怖生物，从它腐烂的利爪中夺回玛丽遗失的珍宝。"}},faq={{q="维克托为什么需要玛丽的眼镜？",a="维克托·安特拉斯正在夜色镇山坡上的小屋里组装望远镜，为此需要玛丽的眼镜。这面镜子的反射表面符合他这项发明的光学要求，能汇聚微弱的星光。",al={"维克托 镜子","为什么需要镜子","镜子有什么用"}},{q="偷走镜子的疯狂的食尸鬼是谁？",a="疯狂的食尸鬼是一个亡灵拾荒者，曾在玛丽家附近废弃的农舍中搜集小玩意儿。它向南逃到了静谧花园墓场中破败的礼拜堂。",al={"疯狂的食尸鬼 在哪里","镜子在谁手里","礼拜堂里的食尸鬼"}},{q="盲眼玛丽为什么扔掉了镜子？",a="一场变故夺走了盲眼玛丽的视力，摧毁了她的神智，将她束缚为不得安息的幽魂，此后她便扔掉了镜子。她无法忍受看着或拿着这面镜子，绝望地将它扔到了谷仓后面。",al={"玛丽 为什么扔掉它","盲眼玛丽 镜子","玛丽的眼镜 变故"}},{q="静谧花园墓场在哪里？",a="静谧花园墓场位于暮色森林东南部，在大路以南。这里曾是暮色森林居民安宁的安葬之地，如今却盘踞着凶暴的食尸鬼、骷髅和食腐野兽。",al={"静谧花园墓场位置","墓场在哪里"}},{q="考格是谁？",a="考格是一位住在夜色镇的侏儒工匠。维克托依靠考格的工程技艺，评估并协助制造观星装置的精密机关。",al={"科格 是谁","维克托 齿轮"}},{q="把镜子交还给维克托后会发生什么？",a="有了这面镜子，维克托离完成装置又近了一步。他开始进行望远镜组装的最后阶段，并请求再找来最后一个用于透镜系统的部件。",al={"仰望星空 后续任务","接下来是什么"}}},fp="17,164,22.350.0,23.330.0,43.192.0,46.172.0,48.173.0,39.207.0,11.167.0,51.173.1"}
P.entries["quest:1778"] = {n="圣洁之书",s="在铁炉堡，蒂萨·热炉教导新学徒，侍奉圣光需要付出什么。他们帮助有需要的人，再回来向她讲述自己如何为他人效劳。",h="在铁炉堡，蒂萨·热炉教导新学徒，侍奉圣光需要付出什么。他们帮助有需要的人，再回来向她讲述自己如何为他人效劳。",kw={"仁爱","圣光","铁炉堡","圣骑士试炼","斯蒂芬妮","暴风城","蒂萨·热炉","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你会学到，圣光要求你先做到无私、仁爱，并长久地为普通市民尽责，然后才是追求战功与荣耀。",["faction:Alliance"]="身为联盟的一员，你从往来于铁炉堡与暴风城的导师和旅人身上，看到了这两座伟大城市之间的紧密联系。",["race:Dwarf"]="身为矮人圣骑士，你在丹莫罗完成试炼后，会到铁炉堡向蒂萨·热炉述职。你向她讲述自己在更广阔的世界中的所作所为。"},sec={{t="圣光的教诲",b="圣骑士的试炼始于学习谦卑、责任与仁爱。蒂萨·热炉并不要求他们立下战功。圣光的仆从必须理解普通人面临的困境，并伸出援手，不求赞誉或回报。"},{t="在铁炉堡述职",b="帮助铁炉堡的人之后，立志成为圣骑士的学徒会回到蒂萨·热炉身边。学徒向她讲述离开期间做了什么，又帮助谁分担了重担。当蒂萨确信他们怀着仁爱之心、恪尽职责时，便会嘉许他们。追随圣光，意味着这样无私地为他人效劳。"}},faq={{q="什么是圣洁之书？",a="圣洁之书考验圣骑士新学徒的同情心、仁爱与自我牺牲精神。这些试炼对他们的要求远不止战斗中的力量。",al={"什么是圣洁之书","圣洁之书试炼","这个任务有什么作用"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是铁炉堡的一位圣骑士导师。她指引新学徒，并评判他们的行为是否遵循圣光的教诲。",al={"蒂萨·热炉是谁","蒂萨·热炉在哪里","铁炉堡圣骑士训练师"}},{q="斯蒂芬妮是谁？",a="斯蒂芬妮·特纳是约翰·特纳的妻子，住在暴风城。他们共同经营着一家孤儿院，约翰希望在铁炉堡筹集物资后回到她身边。",al={"斯蒂芬妮是谁","斯蒂芬妮 暴风城"}},{q="蒂萨·热炉对归来的新学徒有何要求？",a="蒂萨·热炉聆听归来的新学徒讲述自己如何为他人效劳。她会询问他们如何为崇高的事业出力、如何帮助普通市民，然后才给予祝福。",al={"蒂萨考验什么","蒂萨有何要求","圣骑士仁爱考验"}},{q="新学徒为何必须到铁炉堡述职？",a="新学徒回到铁炉堡，向蒂萨·热炉讲述自己的作为。他们帮助城中的约翰·特纳，以此展现同情心与无私精神。",al={"为何在铁炉堡与蒂萨交谈","铁炉堡圣洁之书"}},{q="为何自我牺牲是这场试炼的核心？",a="圣骑士的教诲将他人的福祉置于自身之上。蒂萨教导学徒，无私的牺牲终会得到回报。",al={"圣光如何回报牺牲","圣骑士牺牲"}}},fp="20,155,25.242.0,27.315.0,29.139.0,24.125.0,17.155.0,54.164.0,39.144.0,44.125.0"}
P.entries["quest:1779"] = {n="圣洁之书",s="在铁炉堡，圣洁之书考验圣骑士新兵的神圣力量与尚武之心。新兵受托保管生命符记，前去帮助穆里顿·热炉，他在与黑铁矮人的一场殊死交锋后身负重伤。",h="在铁炉堡，圣洁之书考验圣骑士新兵的神圣力量与尚武之心。新兵受托保管生命符记，前去帮助穆里顿·热炉，他在与黑铁矮人的一场殊死交锋后身负重伤。",kw={"黑铁","圣光","铁炉堡","穆里顿·热炉","纳姆","圣骑士","生命符记","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你携带生命符记去抚慰伤者。这场试炼让你为履行复活他人的神圣职责做好准备。",["race:Dwarf"]="身为矮人，你将在铁炉堡的中心接受这场试炼。它让人想起那些勇敢面对敌对黑铁氏族伏击的守卫者，以及他们之间紧密的情谊。"},sec={{t="信仰与力量的试炼",b="在铁炉堡，圣骑士新兵面临着武艺与神圣力量的试炼。他们已经展现了谦卑、耐心与仁爱。如今，他们受托保管生命符记，前往城中帮助那些因城门之外的冲突而受苦的人。"},{t="倒下的兄弟",b="穆里顿·热炉在与黑铁矮人的一场交锋后身负重伤，卧床不起。一位牧师正在处理他眼下的伤势，而他准备讲述自己的远征队和同伴 纳姆 的遭遇。新兵必须以 圣光 赐予的复苏之力回应这份求助。"}},faq={{q="圣洁之书是什么？",a="圣洁之书是年轻圣骑士研习圣光之道时必须经历的一场试炼。证明自己的仁爱与耐心后，新兵会获得生命符记，并被派去帮助铁炉堡的一名受伤矮人。",al={"这是什么任务","圣洁之书 的目的","这个任务有什么用"}},{q="生命符记是什么？",a="生命符记是圣骑士新兵在试炼期间受托保管的神圣信物。它蕴含着圣光的力量，能治愈并复苏那些为保卫族人而倒下的人。",al={"生命符记是什么","生命符记物品"}},{q="穆里顿·热炉是谁？",a="穆里顿·热炉是一名在与黑铁矮人的交锋中受伤的矮人战士。一位牧师在铁炉堡照料他，而他的妻子则派有潜力的圣骑士去听他讲述自己的遭遇。",al={"穆里顿·热炉 是谁","受伤的矮人是谁"}},{q="谁会给你生命符记？",a="穆里顿·热炉的妻子是铁炉堡的一位圣骑士导师，她会将生命符记交给你。见证你的仁爱与耐心后，她派你去帮助受伤的丈夫，考验你的力量、战斗准备以及助人的意愿。",al={"谁派人去找 穆里顿","谁提供这个任务"}},{q="穆里顿·热炉遭遇了什么？",a="穆里顿和同伴 纳姆 遭到了黑铁矮人的伏击。穆里顿逃脱后回到铁炉堡，伤势严重，身心都需要疗愈。",al={"谁袭击了 穆里顿","穆里顿 遭遇了什么"}},{q="纳姆 是谁？",a="纳姆 是穆里顿·热炉最好的朋友，也是一名圣骑士。他陪同穆里顿与黑铁矮人作战，却未能从那场交锋中脱身，仍需要一名圣骑士前去援助。",al={"纳姆 是谁","纳姆 遭遇了什么"}}},fp="20,235,26.261.0,16.263.0,29.224.0,27.187.0,28.174.0,33.240.0,38.172.0,12.209.0"}
P.entries["quest:178"] = {n="塞欧克瑞图斯的坠饰",s="在赤脊山，一名冒险者找到了一条豺狼人坠饰，并听到一个声音从中传来。那是阿祖拉之塔的大法师塞欧克瑞图斯，他截获了豺狼人的魔法通讯，急切地请求冒险者将坠饰带给他研究。",h="在赤脊山，一名冒险者找到了一条豺狼人坠饰，并听到一个声音从中传来。那是阿祖拉之塔的大法师塞欧克瑞图斯，他截获了豺狼人的魔法通讯，急切地请求冒险者将坠饰带给他研究。",kw={"艾尔文","豺狼人","莫甘斯","坠饰","赤脊山","暗皮","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="身为法师，你能从塞欧克瑞图斯的研究中看出防护与占卜法术的巧妙运用：他侵入另一位巫师的通讯网络，跨越遥远的距离传递反制法术。",["faction:Alliance"]="身为联盟的一员，你能看到艾尔文的阿祖拉之塔正与湖畔镇饱受围困的守军协作。暴风城的皇家军队未能为驻军配足人手，当地法师便出手填补了空缺。"},sec={{t="石中之声",b="在赤脊山各处，与凶残的暗皮豺狼人作战的旅人有时会找到一条暗皮坠饰。触碰这件附有魔法的小饰物，传来的并非吠叫或咒骂，而是一个平静而遥远的声音。说话的是塞欧克瑞图斯，一位驻守在边境另一侧、艾尔文森林中阿祖拉之塔的人类法师。他长期研究如何破解操纵豺狼人群的黑暗法术，这才得以传来这段讯息。"},{t="颠覆莫甘斯的通讯网络",b="暗皮豺狼人既听从自身的本能，也服从莫甘斯，一个藏身山中的叛变黑暗施法者。莫甘斯制作了附魔坠饰，用来向他的豺狼人追随者传达命令。塞欧克瑞图斯花了数月时间，破解莫甘斯传讯法术的频率。当你将失去光泽的坠饰带到阿祖拉之塔时，塞欧克瑞图斯确认，他的占卜法术已经触及了它。现在，他可以研究如何逆转这种魔法，让豺狼人失去行动能力。"}},faq={{q="塞欧克瑞图斯是谁？",a="塞欧克瑞图斯是联盟的大法师，驻守在艾尔文森林东部的阿祖拉之塔。他留意着这一带的威胁，并研究如何对抗从赤脊山蔓延而来的黑暗魔法。",al={"塞欧克瑞图斯背景故事","谁在通过坠饰说话","阿祖拉之塔法师"}},{q="暗皮豺狼人为什么带着魔法坠饰？",a="叛变巫师莫甘斯制作了这些坠饰，将它们用作魔法媒介。他通过坠饰传递精神指令，从远处指挥暗皮氏族。",al={"豺狼人为什么有坠饰","暗皮坠饰用途","豺狼人魔法物品"}},{q="塞欧克瑞图斯传来的声音为什么会延迟？",a="早在你找到这块石头的几周前，塞欧克瑞图斯就已发出讯息，起初还以为法术未能触及石头便已消散。突破莫甘斯的黑暗结界，并跨越如此遥远的距离建立联系，使讯息延迟了。",al={"延迟的讯息","塞欧克瑞图斯为什么用了几周","失去光泽的坠饰延迟"}},{q="塞欧克瑞图斯希望用取回的坠饰做什么？",a="塞欧克瑞图斯希望解读连接坠饰与莫甘斯的魔法频率，并逆转魔力的流向。他打算通过这个网络施放攻击法术，或许能让所有佩戴坠饰的豺狼人瞬间无法动弹。",al={"塞欧克瑞图斯的计划","塞欧克瑞图斯会做什么","为什么研究坠饰"}},{q="这条任务线接下来通向哪里？",a="将坠饰交给塞欧克瑞图斯，这项差事就完成了。他与莫甘斯的另一场斗争会在“法师的眼线”中继续，该任务会派你前往伊尔加拉之塔，侦察莫甘斯的据点。",al={"塞欧克瑞图斯的坠饰后续任务","莫甘斯任务线","接下来会发生什么"}}},fp="21,236,20.398.0,29.430.1,18.186.0,57.146.0,50.224.0,64.218.0,38.200.1"}
P.entries["quest:1780"] = {n="圣洁之书",s="在暴风城的光明大教堂，达索瑞恩·拉尔指引圣骑士接受考验，证明他们对圣光的虔诚。他们以仁爱、无私，以及保护困苦之人的责任心，证明自己的价值。",h="在暴风城的光明大教堂，达索瑞恩·拉尔指引圣骑士接受考验，证明他们对圣光的虔诚。他们以仁爱、无私，以及保护困苦之人的责任心，证明自己的价值。",kw={"光明大教堂","仁爱","达索瑞恩·拉尔","圣光","圣骑士试炼","暴风城","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你以仁爱之举和对平民的保护，证明自己对圣光的虔诚。圣洁之书考验你为他人服务的决心。",["faction:Alliance"]="身为联盟的守护者，你得到提醒：暴风城的精神力量，根植于对人民之中弱者的保护。"},sec={{t="美德的试炼",b="侍奉圣光的圣骑士，要在暴风城接受一场至关重要的试炼。在光明大教堂，达索瑞恩·拉尔派遣新人，以高尚的品行和为王国子民无私奉献的行动，证明自己的虔诚。仅有战功并不足够。"},{t="无私的美德",b="帮助弱者之后，新人们回到达索瑞恩·拉尔身边。他们为孩子们送去了急需的援助，赢得了孩子们由衷的感激。他们的导师看重将他人置于自身之前的品德。他教导他们，仁爱、怜悯以及对艾泽拉斯人民的责任，指引着圣光之路。"}},faq={{q="什么是圣洁之书？",a="圣洁之书是有志成为圣骑士的人要经历的一系列试炼。在暴风城光明大教堂的导师指引下，新人们帮助王国各地有需要的民众，展现自己的美德、仁爱与责任心。",al={"什么是圣洁之书","圣洁之书任务","圣骑士试炼任务"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城光明大教堂的一位资深圣骑士训练师。他指引初出茅庐的圣骑士修习信仰、接受品德考验，判断他们的行为是否恪守圣光的美德。",al={"达索瑞恩·拉尔是谁","暴风城圣骑士训练师","达索瑞恩·拉尔的职责"}},{q="这场试炼传授什么道理？",a="这场试炼教导人们，驾驭圣光需要谦卑、无私的牺牲，以及为他人服务的精神。它既重视武艺，也重视怜悯、仁爱，以及对艾泽拉斯人民应尽的道义责任。",al={"圣洁之书的目的","圣骑士为何接受试炼","这个任务传授什么道理"}},{q="这个任务在哪里进行？",a="这场试炼以暴风城的光明大教堂为中心。新人们外出帮助民众，随后返回大教堂，向达索瑞恩·拉尔汇报自己的行动。",al={"这个任务在哪里进行","在哪里交付圣洁之书","光明大教堂任务"}},{q="这个任务帮助了谁？",a="这场试炼为急需帮助的人送去援助，其中包括年幼的孩子。受助者由衷地表达感谢，也提醒暴风城的圣骑士，绝不能对无辜者和贫困者置之不理。",al={"这个任务帮助了谁","救助儿童任务","谁得到了援助"}},{q="达索瑞恩·拉尔为何强调仁爱？",a="达索瑞恩·拉尔强调仁爱，因为圣光要求人们慷慨相助，保护无辜者。他教导人们，圣骑士必须为他人作出牺牲，将他人的福祉置于自身之上。",al={"仁爱为何对圣骑士重要","圣骑士与穷人","仁爱与圣光"}}},fp="20,203,17.271.0,26.298.0,29.213.0,22.229.0,37.200.0,33.171.0,23.192.0,42.206.0"}
P.entries["quest:1781"] = {n="圣洁之书",s="在暴风城的光明大教堂，一场试炼正等待着圣骑士见习者：他们必须凝聚神圣的生命符记之力。证明自身品德的人会被派去帮助贾森·坦诺姆，他在艾尔文森林的英雄哨岗附近遭到迪菲亚伏击，勉强逃生。",h="在暴风城的光明大教堂，一场试炼正等待着圣骑士见习者：他们必须凝聚神圣的生命符记之力。证明自身品德的人会被派去帮助贾森·坦诺姆，他在艾尔文森林的英雄哨岗附近遭到迪菲亚伏击，勉强逃生。",kw={"光明大教堂","迪菲亚","达索瑞恩","达索瑞恩·拉尔","贾森·坦诺姆","亨兹","英雄哨岗","生命符记","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你在暴风城的训练迎来了一个重要关口。这场试炼将考验你是否拥有驾驭生命符记的精神力量。",["faction:Alliance"]="身为联盟的一员，你知道英雄哨岗附近的迪菲亚袭击威胁着艾尔文森林各处的旅人与居民。教会必须介入。"},sec={{t="虔诚的考验",b="在暴风城的光明大教堂，耐心而仁慈的圣骑士见习者会获得生命符记。达索瑞恩·拉尔将这件神圣的容器托付给他们，以考验他们对圣光的虔诚。唯有品德高尚的勇士，才能凝聚圣光最伟大的恩赐之一，让逝者重获生命。"},{t="英雄哨岗的伏击",b="贾森·坦诺姆的遭遇说明了为何需要这枚符记。他在艾尔文森林的英雄哨岗附近遭到迪菲亚匪徒袭击，随后爬回了暴风城。牧师们正在大教堂的祭坛旁为他治疗重伤。他的同伴亨兹仍在歹徒发动袭击的地方，身陷险境。"}},faq={{q="贾森·坦诺姆是谁？",a="贾森·坦诺姆是达索瑞恩·拉尔的同伴。他在艾尔文森林的英雄哨岗附近遭到迪菲亚伏击，勉强逃脱，随后身负重伤被送到了暴风城的光明大教堂。当地的牧师正在为他治疗。",al={"贾森·坦诺姆是谁","贾森 艾尔文森林 迪菲亚","暴风城祭坛受伤男子"}},{q="生命符记是什么？",a="生命符记是一件神圣的圣物，会被托付给耐心而仁慈的圣骑士见习者。它考验一位成长中的勇士是否拥有足够的精神专注与坚毅，来引导圣光最伟大的恩赐之一：让逝者重获生命。",al={"生命符记有什么作用","生命符记 圣骑士","圣骑士复活圣物"}},{q="英雄哨岗发生了什么？",a="在艾尔文森林的英雄哨岗，迪菲亚歹徒伏击了贾森·坦诺姆和他的同伴亨兹。贾森身负重伤逃到了暴风城，而亨兹仍身陷险境。",al={"英雄哨岗在哪里","英雄哨岗 艾尔文森林 迪菲亚","贾森 遇伏地点"}},{q="亨兹是谁？",a="亨兹是贾森·坦诺姆的同伴。迪菲亚匪徒在艾尔文森林的英雄哨岗附近袭击了他们，亨兹被留在了那里，而贾森则活着抵达了暴风城。",al={"亨兹是谁","亨兹·法奥克","贾森 朋友 迪菲亚"}},{q="是谁派你去与贾森·坦诺姆交谈？",a="达索瑞恩·拉尔派你去与贾森·坦诺姆交谈。他是暴风城光明大教堂的圣骑士领袖之一，会先确认见习者已展现出耐心与仁慈，再指引他们去祭坛旁找贾森。",al={"谁派人去找贾森","达索瑞恩·拉尔 圣洁之书","暴风城圣骑士训练师任务"}},{q="迪菲亚匪徒为何袭击英雄哨岗附近的旅人？",a="迪菲亚歹徒和拦路强盗在艾尔文森林各处伏击旅人，甚至出没于近在都城咫尺之遥的地方。贾森·坦诺姆遇袭一事表明，他们的行动已变得何等肆无忌惮，又何等致命。",al={"迪菲亚 威胁 艾尔文森林","迪菲亚为何在英雄哨岗附近","迪菲亚潜行者 暴风城"}}},fp="20,240,18.300.0,23.263.0,20.219.0,27.238.0,31.173.0,13.163.0,41.216.0,62.194.0"}
P.entries["quest:1782"] = {n="弗伦的铠甲",s="在暴风城，弗伦·长须正在测试新护甲。一位胸怀抱负的战士为他的试验收集蜘蛛的毒牙、奇美拉的角和燃素。随后，弗伦将淬火锁甲交给这位战士，并承诺与联盟的铁匠分享他的心得。",h="在暴风城，弗伦·长须正在测试新护甲。一位胸怀抱负的战士为他的试验收集蜘蛛的毒牙、奇美拉的角和燃素。随后，弗伦将淬火锁甲交给这位战士，并承诺与联盟的铁匠分享他的心得。",kw={"联盟战士","锻造","淬火锁甲","弗伦·长须","弗伦的护甲","锁甲","暴风城"},ang={["class:Warrior"]="作为一名联盟战士，你在开始奔赴前线时获得了弗伦专门淬炼的护甲。它能在早期的战役中为你提供防护。",["faction:Alliance"]="精良的武备有助于联盟部队在对抗迪菲亚、豺狼人和敌对元素力量时保全性命。",["profession:Blacksmithing"]="弗伦的试验展现了联盟铁匠如何分享冶金研究成果，精进暴风城和铁炉堡的锻造技艺。"},sec={{t="大师的突破",b="弗伦·长须是暴风城的一位矮人护甲匠，他希望为联盟打造更坚固的护甲。他测试护甲承受高温和重击的能力。为了进行这些试验，他请一位胸怀抱负的战士收集稀有材料。最终制成的锁甲经受住了考验，也提升了弗伦在联盟护甲匠中的地位。"},{t="技艺的传承",b="弗伦将完成的淬火锁甲交给了收集材料的战士。他很感激这份帮助，而这些试验也让他对护甲锻造有了更深的认识。如今，他打算将笔记和研究成果送给其他联盟铁匠，让他们也能运用这些新方法。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是暴风城的一位矮人护甲锻造大师。他与联盟的各个军事组织有着广泛合作，尤其常为寻求特制护甲的战士效力。",al={"弗伦是谁","弗伦·长须","暴风城铁匠弗伦"}},{q="弗伦打造了什么样的护甲？",a="弗伦打造了一件淬火锁甲，这件锁甲胸甲使用稀有的毒牙、角和燃素制成。它能抵御猛烈的攻击和极端的高温。",al={"弗伦打造什么护甲","淬火锁甲","弗伦的奖励"}},{q="弗伦·长须会将锻造研究成果送往何处？",a="弗伦承诺将研究成果和笔记送给联盟各地的铁匠同行。他与王国各处的铁匠铺分享经过验证的淬火方法。",al={"弗伦的笔记","谁会获得弗伦的设计","联盟铁匠"}},{q="为什么要请战士为弗伦收集材料？",a="弗伦需要稀有且性质不稳定的材料来测试新的锻造技艺。他无法离开熔炉，前往湿地猎杀蜘蛛，或到石爪山猎杀奇美拉，因此只能依靠一位胸怀抱负的战士来收集这些材料。",al={"为何为弗伦收集材料","淬火锁甲任务材料"}},{q="这件护甲在哪里锻造和交付？",a="弗伦在暴风城自己的铁匠铺中锻造并交付这件护甲。他在那里完成了这套锁甲。",al={"弗伦·长须在哪里","任务交付地点","弗伦的位置"}},{q="这项研究会让其他联盟战士受益吗？",a="会。弗伦计划与其他联盟护甲匠分享他的心得，希望他们能用这些方法为联盟士兵打造坚固的装备。",al={"联盟的收益","弗伦的突破"}}},fp="13,261,23.301.0,17.290.0,23.161.0,36.159.0,57.161.0,55.213.0,41.96.0,47.152.0"}
P.entries["quest:1783"] = {n="圣洁之书",s="《神圣之书》指引一名圣骑士新兵前往丹莫罗盔枕湖以南的冰冷湖岸。圣骑士携带着生命符记，必须找到并复活纳姆·福克，这名勇敢的侦察兵在抵御一伙黑铁矮人时不幸阵亡。",h="《神圣之书》指引一名圣骑士新兵前往丹莫罗盔枕湖以南的冰冷湖岸。圣骑士携带着生命符记，必须找到并复活纳姆·福克，这名勇敢的侦察兵在抵御一伙黑铁矮人时不幸阵亡。",kw={"黑铁矮人","丹莫罗","盔枕湖","穆里登","纳姆·福克","圣骑士","复活","生命符记","神圣之书"},ang={["class:Paladin"]="这项试炼标志着圣骑士对死亡本身的掌控，展示了通过生命符记引导圣光来复活阵亡盟友的能力。",["faction:Alliance"]="营救矮人侦察兵并找回神圣文书，使联盟的关键知识和防卫者免受黑铁矮人阴谋的伤害。",["race:Dwarf"]="这项试炼直接应对了盘踞在丹莫罗盔枕湖以南的黑铁矮人所带来的威胁。"},sec={{t="湖畔伏击",b="在盔枕湖以南的一次例行侦察任务中，侦察兵穆里登和纳姆·福克发现敌对的黑铁矮人正在加固防御，局势顿时变得危急起来。在发现敌方指挥官下达命令后，侦察兵试图击杀几名敌人并获取一份文书，但黑铁矮人以出人意料的凶猛攻势压倒了他们。穆里登逃离去寻求增援，而纳姆则负责阻击敌人。"},{t="信仰的试炼",b="携带生命符记的圣骑士新兵前往丹莫罗的雪地寻找纳姆·福克。虽然纳姆在黑铁矮人的猛攻下倒下了，但通过引导这件圣物的力量，圣骑士成功地在圣光即将完全拥抱纳姆之时将其灵魂拉了回来。这一举动巩固了圣骑士初生的使命感，以及复活阵亡者的能力。"}},faq={{q="这个任务的目的是什么？",a="《神圣之书》代表了年轻圣骑士的一项决定性试炼。在这一阶段，新兵会收到生命符记，并被派去营救一名阵亡的侦察兵，通过祈求圣光复活死者来证明自己的价值与虔诚。",al={"什么是神圣之书","神圣之书的目的","圣骑士复活任务"}},{q="纳姆·福克是谁？",a="纳姆·福克是一名联盟侦察兵，他在盔枕湖以南遭到黑铁矮人的伏击。他为了让同伴穆里登逃脱而放弃了逃生的机会，在战斗中阵亡，随后被圣光所复活。",al={"纳姆·福克是谁","纳姆在哪里","阵亡矮人纳姆"}},{q="穆里登是谁？",a="穆里登是在纳姆·福克的催促下从黑铁矮人伏击中逃脱的侦察兵。他返回寻求增援，并指引圣骑士使用生命符记拯救他那阵亡的战友。",al={"穆里登是谁","任务给予者穆里登","谁给予任务"}},{q="什么是生命符记？",a="生命符记是一件神圣的圣物，由提扎和穆里登交给圣骑士。由圣光的合格侍从引导，它拥有复活死者的力量。",al={"什么是生命符记","复活物品","生命符记背景"}},{q="纳姆和穆里登在盔枕湖附近做什么？",a="穆里登和纳姆·福克当时正在监视那些在盔枕湖以南加固防御的黑铁矮人。在侦察任务中，他们目睹了敌军首领正在发号施令，并试图在被压倒前夺回神圣的文书。",al={"他们在盔枕湖以南做什么","为什么要监视黑铁矮人","黑铁矮人 盔枕湖"}},{q="提扎是谁？",a="提扎是参与调派救援并与穆里登一起为营救任务准备生命符记的导师或协调员之一。",al={"提扎是谁","提扎 圣骑士"}}},fp="20,236,18.335.0,15.323.1,34.200.0,18.205.0,16.181.0,27.175.0,55.206.0,12.85.0"}
P.entries["quest:1784"] = {n="圣洁之书",s="《圣光的感召》是一项关键的圣骑士试炼，核心任务是揭露潜入丹莫罗的黑铁矮人阴谋。胸怀大志的圣骑士们需要去帮助受伤的斥候纳姆·法克和缪雷登·战锤，夺回至关重要的敌军命令，从而向铁炉堡中怀疑此事的议会证明近在咫尺的威胁。",h="《圣光的感召》是一项关键的圣骑士试炼，核心任务是揭露潜入丹莫罗的黑铁矮人阴谋。胸怀大志的圣骑士们需要去帮助受伤的斥候纳姆·法克和缪雷登·战锤，夺回至关重要的敌军命令，从而向铁炉堡中怀疑此事的议会证明近在咫尺的威胁。",kw={"黑铁矮人","黑铁手稿","丹莫罗","盔枕湖","铁炉堡","缪雷登·战锤","纳姆·法克","圣光的感召"},ang={["class:Paladin"]="该任务是矮人圣骑士通过《圣光的感召》进行的早期试炼中的关键一步，旨在通过保卫王国和营救受难战友来传授对圣光的无私奉献精神。",["faction:Alliance"]="揭露铁炉堡周边的黑铁破坏活动，保卫了矮人首都，并加强了联盟北部防御以应对隐秘威胁。",["race:Dwarf"]="在铁炉堡家门口揭露黑铁渗透对于矮人防御至关重要，这向固执的议员们证明了世仇已经入侵了丹莫罗。"},sec={{t="侍奉之试炼",b="《圣光的感召》指引着年轻的矮人圣骑士走上他们的精神修行之路。在这场试炼中，当一场针对隐秘黑铁特工的远征在盔枕湖附近遇挫时，初出茅庐的勇士被卷入了丹莫罗的防御战。纳姆·法克和缪雷登·战锤试图伏击敌方斥候，但在冲突中纳姆身负重伤，而缪雷登则撤回铁炉堡进行休整。"},{t="给议会的证明",b="尽管传言甚嚣尘上，铁炉堡统治议会的几位成员仍拒绝承认黑铁渗透者已经潜入了丹莫罗。通过追踪盔枕湖附近的间谍并回收他们队长传递的“黑铁手稿”，圣骑士获得了敌军动向无可辩驳的证据，并揭开了他们就在首都大门外酝酿的阴谋。"},{t="保卫家园",b="将截获的命令带回铁炉堡交给缪雷登·战锤令人深感宽慰。随着纳姆获救，回收的文件也被交给缪雷登的妻子呈递给议会，圣骑士展现出了无私的勇敢与对圣光的虔诚，保护了矮人王国免受隐藏的背叛之苦。"}},faq={{q="谁发布《圣光的感召》任务？",a="该任务由纳姆·法克发布，他是一位在盔枕湖附近与黑铁间谍战斗时受伤的矮人。他派遣你去取回敌军手稿，并向他在铁炉堡的同伴缪雷登·战锤报告。",al={"谁发布此任务","圣光的感召任务发布者","纳姆是谁"}},{q="缪雷登·战锤是谁？",a="缪雷登·战锤是一位驻扎在铁炉堡的矮人。他曾与纳姆·法克一起在盔枕湖附近侦察黑铁间谍，随后回到城中休养伤势。",al={"缪雷登·战锤是谁","缪雷登在哪里","缪雷登·战锤位置"}},{q="什么是黑铁手稿？",a="黑铁手稿包含了黑铁间谍与其队长在盔枕湖附近传递的书面命令。它提供了敌方渗透的实质性证据，可以用来展示给持怀疑态度的铁炉堡议会。",al={"什么是黑铁手稿","为什么要获取黑铁手稿","黑铁手稿用途"}},{q="为什么铁炉堡的议会需要黑铁矮人的证据？",a="铁炉堡的一些议会成员仍然怀疑黑铁矮人是否成功渗透了丹莫罗。回收的手稿证明了他们的活跃动向，并揭露了他们的秘密计划。",al={"为什么议会否认黑铁矮人","铁炉堡议会黑铁证据"}},{q="黑铁间谍位于何处？",a="盔枕湖位于丹莫罗东部，卡拉诺斯以东。黑铁间谍在附近的一间小屋旁活动，试图传递隐秘的作战命令。",al={"盔枕湖在哪里","盔枕湖的黑铁矮人","丹莫罗的黑铁位置"}},{q="这个任务对圣骑士有什么作用？",a="《圣光的感召》系列考验着一位胸怀大志的圣骑士在侍奉、同情心和勇气方面的品质。通过帮助纳姆这样的落难战友并保卫丹莫罗免受阴险敌人的侵害，圣骑士证明了自己有资格驾驭圣光。",al={"圣光的感召教导什么","圣骑士圣光的感召背景"}}},fp="20,162,18.251.0,21.312.0,19.277.1,37.199.0,28.168.0,29.193.0,63.159.0,38.149.0,44.192.0"}
P.entries["quest:1785"] = {n="圣洁之书",s="在铁炉堡，神圣的勇士们在蒂萨·热炉面前接受最后的试炼。圣洁之书将检验他们是否已准备好使用生命符记，让倒下的盟友重获生命。",h="在铁炉堡，神圣的勇士们在蒂萨·热炉面前接受最后的试炼。圣洁之书将检验他们是否已准备好使用生命符记，让倒下的盟友重获生命。",kw={"铁炉堡","圣骑士","救赎","复活","生命符记","圣洁之书","蒂萨·热炉"},ang={["class:Paladin"]="身为圣骑士，你在铁炉堡完成神圣仪式，获得Light赐予的力量，使倒下的人重获生命。",["faction:Alliance"]="身为联盟的勇士，你修习Light之道，迎战Scourge和黑铁氏族。",["race:Dwarf"]="身为矮人，你在铁炉堡接受这场试炼，并赢得Battleforge家族代表王国向你致以的感谢。"},sec={{t="铁炉堡的神圣仪式",b="你已通过王国的重重试炼，如今来到铁炉堡，拜见蒂萨·热炉。她是一位备受敬重的神圣法术导师。你走近时，她的丈夫自豪地望着你，热切期盼矮人同胞认可你已准备好接受圣光的考验。"},{t="复活的祝福",b="蒂萨·热炉最后的祝福将检验你的内心是否已准备好使用生命符记。唯有准备好引导圣光至高恩赐的人，才能得到这件圣物的回应。证明你的价值，蒂萨便会赐予你一张神圣卷轴，让你能将倒下的战友从死亡中唤回。铁炉堡需要这份力量来对抗天灾军团和黑铁氏族。"}},faq={{q="圣洁之书是什么？",a="圣洁之书是铁炉堡为神圣勇士设下的一场神圣试炼。证明你的心灵已做好准备，你便能学会引导圣光，让倒下的同伴重获生命。",al={"圣洁之书是什么","圣洁之书任务","这个任务有什么作用"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是铁炉堡一位备受敬重的矮人圣光导师。她为准备好掌握复活之力的勇士赐下最后的祝福。",al={"蒂萨·热炉是谁","蒂萨·热炉在哪里","寻找蒂萨·热炉"}},{q="是谁派你去见蒂萨·热炉？",a="你完成先前的野外试炼后，蒂萨·热炉的丈夫便会指引你去见她。他已在铁炉堡，满怀自豪与鼓励，派你前去拜见他的妻子。",al={"谁提供这个任务","蒂萨的丈夫","谁派我去见蒂萨"}},{q="生命符记是什么？",a="生命符记是圣骑士试炼中使用的一件神圣物品。只有虔诚之心足以使其配得上将倒下的盟友从死亡中唤回的勇士，才能得到它的回应。",al={"生命符记是什么","生命符记圣骑士","复活如何生效"}},{q="完成这个任务能学会什么技能？",a="你前去拜见蒂萨·热炉时，她会赐予你一张神圣卷轴，教会你救赎，让你获得使倒下的盟友重获生命的力量。",al={"能学会什么力量","复活法术任务","圣骑士复活任务"}},{q="铁炉堡为何需要圣光的勇士？",a="铁炉堡需要圣光的勇士来对抗天灾军团和黑铁矮人。他们的治疗与神圣防护有助于保卫王国。",al={"铁炉堡的敌人是谁","为何对抗黑铁矮人和天灾军团","战场敌人"}}},fp="20,187,26.262.0,28.351.0,29.181.0,24.156.0,34.179.0,27.163.0,53.152.0,51.140.0"}
P.entries["quest:1786"] = {n="圣洁之书",s="《神圣之书》是艾尔文森林圣骑士的一项关于信仰与牺牲的神圣试炼。在一次迪菲亚法师的伏击导致侦察兵亨兹·法奥克在英雄哨岗阵亡后，一位有抱负的神圣战士必须挥舞生命符记来复活他，并挫败迪菲亚潜行者日益逼近的阴谋。",h="《神圣之书》是艾尔文森林圣骑士的一项关于信仰与牺牲的神圣试炼。在一次迪菲亚法师的伏击导致侦察兵亨兹·法奥克在英雄哨岗阵亡后，一位有抱负的神圣战士必须挥舞生命符记来复活他，并挫败迪菲亚潜行者日益逼近的阴谋。",kw={"迪菲亚","达索瑞恩","贾森","亨兹·法奥克","英雄哨岗","圣骑士","复活","石碑湖","生命符记","《神圣之书》"},ang={["class:Paladin"]="这项任务代表了年轻圣骑士的一个重要里程碑，通过挥舞生命符记来复活倒下的盟友，证明他们的信仰以及与圣光的联系。",["faction:Alliance"]="在艾尔文森林东北部活动的迪菲亚施法者威胁着暴风城腹地的安全，这使得在英雄哨岗收集情报对联盟至关重要。"},sec={{t="英雄哨岗的伏击",b="亨兹·法奥克和他的搭档贾森在听说迪菲亚潜行者特工渗透边境的报告后，前往了艾尔文森林东北部石碑湖中央的一座岛屿——英雄哨岗。为了寻找呈交给国王皇家顾问的确凿证据，两名侦察兵试图伏击一对正在审查计划的阴谋分子。然而，当迪菲亚施法者加入战斗时，他们很快就被压制了。亨兹坚守阵地对抗敌对法师，牺牲了自己，为贾森争取了足够的时间逃脱并保住了性命。"},{t="复活的恩赐",b="从伏击中恢复过来需要的不仅仅是普通的药物；这需要圣光的力量。装备着生命符记，一位有抱负的圣骑士被派往石碑湖，在岛上寻找亨兹的遗体。通过这件神圣的圣物引导个人信仰，使亨兹起死回生，这标志着神圣战士的精神纽带和为暴风城的防御服务、侍奉圣光的准备情况的一次关键考验。"}},faq={{q="谁是亨兹·法奥克？",a="亨兹·法奥克是一位勇敢的防御者，他与贾森一起冒险前往石碑湖上的英雄哨岗，以获取迪菲亚渗透的证据。他阻挡了迪菲亚法师，让他的同伴得以逃脱，最终死于他们的奥术攻击，之后通过生命符记复活。",al={"亨兹·法奥克是谁","亨兹·法奥克","亨兹在哪里"}},{q="英雄哨岗在哪里？",a="英雄哨岗是位于艾尔文森林东北部石碑湖中央的一座岛屿。迪菲亚法师和潜行者在那里建立了一个前哨站，正在仔细研读秘密计划。",al={"英雄哨岗在哪里","英雄哨岗位置","英雄哨岗岛屿"}},{q="什么是生命符记？",a="生命符记是一件用于引导圣骑士信仰并复活阵亡者的圣物。它需要真正的精神信念来赋予力量，因此在亨兹·法奥克身上成功使用它，是对圣骑士使命感的一次考验。",al={"什么是生命符记","如何复活亨兹","生命符记的用途"}},{q="谁指引了对亨兹·法奥克的营救？",a="贾森·坦诺姆在岛上从迪菲亚手中逃脱，现在躺在暴风城光明大教堂的祭坛旁受伤，他请求帮助。他是达索瑞恩·拉尔的朋友，达索瑞恩·拉尔是将这位新兵派往他那里的圣骑士领袖。",al={"谁派我去寻找亨兹","达索瑞恩还是贾森","《神圣之书》任务发布者"}},{q="迪菲亚在英雄哨岗做什么？",a="迪菲亚特工渗透进艾尔文森林东北部，并聚集在英雄哨岗，审查文件并协调他们的行动。亨兹和贾森试图找回这些文件，作为给国王顾问们的证据。",al={"迪菲亚为何在英雄哨岗","迪菲亚在石碑湖做什么","迪菲亚在艾尔文的计划"}},{q="亨兹和贾森为什么去石碑湖？",a="亨兹·法奥克和贾森在听说有迪菲亚渗透者的报告后，前往了石碑湖。他们的目标是伏击阴谋分子，并找回他们的计划书面证据，呈交给暴风城的安度因国王的顾问们。",al={"亨兹和贾森为何在那儿","亨兹和贾森的任务"}}},fp="20,195,23.494.0,24.340.1,19.238.0,23.171.0,27.185.0,38.217.0,43.210.0,47.212.0"}
P.entries["quest:1787"] = {n="圣洁之书",s="你正在通过联盟圣骑士的试炼，证明自己对圣光的虔诚。在艾尔文森林帮助一名受伤的斥候后，你要迎战迪菲亚巫师，并寻找关乎王国安危的文件。",h="你正在通过联盟圣骑士的试炼，证明自己对圣光的虔诚。在艾尔文森林帮助一名受伤的斥候后，你要迎战迪菲亚巫师，并寻找关乎王国安危的文件。",kw={"迪菲亚巫师","迪菲亚手稿","艾尔文森林","贾森·坦诺姆","亨兹·法奥克","英雄哨岗","圣骑士任务","圣洁之书"},ang={["class:Paladin"]="作为圣骑士，你要面对一场考验虔诚与勇气的试炼。它考验你保护无辜者、捍卫圣光，对抗迪菲亚潜行者等威胁的决心。",["faction:Alliance"]="作为联盟的一员，你协助查明迪菲亚在艾尔文森林的动向，并搜集他们的文件。这些情报会送到暴风城的守卫者手中。"},sec={{t="圣骑士的试炼",b="作为一名见习圣骑士，你正在艾尔文森林接受考验。亨兹在一座岛上监视不法活动时受了伤。帮助他查明迪菲亚在那里的势力扩张到了何种程度。"},{t="艾尔文的渗透者",b="亨兹发现迪菲亚巫师正在岛上研读秘密文件，但伤势让他无法战斗。你受命击败这些叛逆的施法者，夺取他们的手稿。然后将情报安全送到暴风城的贾森·坦诺姆手中。"},{t="保卫王国",b="迪菲亚手稿证实，兄弟会威胁着附近的土地，英雄哨岗也在其中。将窃取的情报带到光明大教堂。你的归来证明了你对圣光的虔诚，也证明亨兹还活着。"}},faq={{q="这个任务涉及哪些人？",a="你会遇到亨兹·法奥克，他受伤倒在艾尔文森林的一座岛上。之后，前往暴风城的光明大教堂，向贾森·坦诺姆汇报。",al={"任务由谁发布","圣洁之书由谁发布","哪里接取圣洁之书"}},{q="亨兹是谁？",a="亨兹是圣骑士试炼中的一位盟友，他在监视迪菲亚的活动时受了伤。他无法战斗，便派你去取得兄弟会渗透此地的证据。",al={"亨兹是谁","亨兹·法奥克的背景故事","受伤的人是谁"}},{q="贾森·坦诺姆是谁？",a="贾森·坦诺姆是亨兹的朋友，也是达索瑞恩·拉尔的朋友。他就在暴风城光明大教堂的祭坛附近。他在英雄哨岗险些落入迪菲亚之手，希望得知亨兹平安无事。",al={"贾森·坦诺姆是谁","贾森·坦诺姆在哪里","贾森 暴风城"}},{q="迪菲亚巫师为什么在岛上活动？",a="迪菲亚潜行者在艾尔文森林各处都设有据点。其麾下的叛逆巫师研读计划，协调行动，他们的文件揭示了他们在这一带的意图。",al={"迪菲亚为何在艾尔文","迪菲亚巫师","迪菲亚手稿"}},{q="英雄哨岗是什么地方？",a="英雄哨岗位于艾尔文森林，正受到迪菲亚行动的威胁。贾森·坦诺姆希望，阻止附近的叛逆巫师并夺走他们的文件，能让那里免遭进一步的侵害。",al={"英雄哨岗是什么地方","英雄哨岗 艾尔文","英雄哨岗安全吗"}},{q="迪菲亚手稿是什么？",a="迪菲亚手稿是迪菲亚巫师随身携带的书面命令或信函。它证明了他们的渗透，并详细记载了他们近期在艾尔文森林的阴谋。",al={"迪菲亚手稿是什么","那些文件是什么","迪菲亚文件 艾尔文"}}},fp="20,201,17.181.0,22.251.1,21.219.1,30.143.0,13.167.0,20.207.0,53.176.0,22.187.0,26.169.0"}
P.entries["quest:1788"] = {n="圣洁之书",s="在暴风城，圣骑士在圣洁之书中接受信仰的考验。见习者通过复活一名倒下的盟友，证明自己已掌握生命符记的力量，随后获得达索瑞恩·拉尔的祝福，得以施展复活之力。",h="在暴风城，圣骑士在圣洁之书中接受信仰的考验。见习者通过复活一名倒下的盟友，证明自己已掌握生命符记的力量，随后获得达索瑞恩·拉尔的祝福，得以施展复活之力。",kw={"达索瑞恩","达索瑞恩·拉尔","亨兹","圣骑士","复活","暴风城","生命符记","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，这场试炼标志着你开始真正侍奉圣光。你将掌握让倒下的同伴重获生命的神圣力量。",["faction:Alliance"]="身为联盟的守卫者，你在光明大教堂与暴风城的圣骑士一同受训。他们的努力守护着联盟守卫者的生命，也巩固着王国的防御。"},sec={{t="返回大教堂",b="一名立志成为圣骑士的见习者在野外用生命符记复活了倒下的亨兹，随后返回暴风城的光明大教堂。从岛上找回的迪菲亚文件将通过贾森·坦诺姆转交给国王的顾问。首先，达索瑞恩·拉尔正等着见习者报告成功的消息。"},{t="复活的恩赐",b="祈求圣光使死者复生，是一份非同寻常的恩赐。达索瑞恩·拉尔认为，掌握生命符记的力量，便证明见习者拥有足够的信仰和精神力量，能够肩负圣骑士团最崇高的使命之一：复活死者。掌握这一神圣仪式后，圣骑士便能在王国各处的战场上守护盟友。"}},faq={{q="圣洁之书是什么？",a="圣洁之书是圣骑士学习驾驭圣光时的一项最终试炼。在这里，见习者证明自己能够引导圣光复活倒下的人之后，便向达索瑞恩·拉尔复命。",al={"圣洁之书","这是什么任务","圣洁之书 圣骑士"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城光明大教堂的一位高阶圣骑士训练师。他负责指导圣骑士见习者，并判断他们是否已准备好施行神圣仪式。",al={"达索瑞恩是谁","达索瑞恩·拉尔的职责","达索瑞恩在哪里"}},{q="生命符记是什么？",a="生命符记是一件神圣的法器，用于祈求圣光使死者复生。掌握它的力量，便证明见习者已准备好施展圣骑士的复活之力。",al={"生命符记的用途","生命符记做了什么"}},{q="亨兹是谁？",a="亨兹是一名在野外倒下的盟友，在一名见习者的试炼中被生命符记复活。这一壮举展现了这位圣骑士逆转死亡的决心与信仰。",al={"亨兹 是谁","亨兹 的故事","亨兹 圣骑士任务"}},{q="圣骑士如何获得复活之力？",a="复活死者是圣骑士最崇高的荣耀之一。凭借深厚的信仰与对圣光的感应，圣骑士学会将倒下的同伴从死亡边缘唤回。",al={"圣骑士复活之力的故事","圣骑士如何复活死者"}},{q="为什么要把这份文书交给国王的顾问？",a="这份文书就是从岛上取得的迪菲亚文件。待达索瑞恩·拉尔过目后，贾森·坦诺姆会将它们送交国王的顾问，作为迪菲亚已渗透艾尔文的证据。",al={"国王顾问的文书","送往暴风城的是什么文书"}}},fp="20,206,23.298.0,24.328.0,29.203.0,22.163.0,27.176.0,14.174.0,50.175.0,53.198.0"}
P.entries["quest:179"] = {n="矮人的交易",s="在寒脊山谷，斯登·粗臂向新兵提出了一桩交易。猎狼，带回坚韧的狼肉，他就提供结实的手套，帮助新兵抵御丹莫罗的严寒。",h="在寒脊山谷，斯登·粗臂向新兵提出了一桩交易。猎狼，带回坚韧的狼肉，他就提供结实的手套，帮助新兵抵御丹莫罗的严寒。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人的装备","冻伤","手套","斯登·粗臂","硬狼肉"},ang={["race:Dwarf"]="作为寒脊山谷中一名年轻的铜须矮人，你要学会为营地筹措物资，并敬畏山中的严寒。",["race:Gnome"]="作为在丹莫罗投靠矮人同胞的侏儒，除了敏锐的头脑，你还需要实用的山地衣物，才能抵御安威玛尔的严寒。"},sec={{t="寒脊的公平交易",b="寒意笼罩着寒脊山谷的每一条小路。在安威玛尔外，斯登·粗臂请新兵到积雪中猎狼，把坚韧的狼肉带回哨站。作为回报，他会给他们手套，让他们的双手免受寒冷侵袭。"},{t="靠山谷维生",b="狼威胁着在山谷中训练的矮人斥候和年轻侏儒。然而，它们也为安威玛尔的驻军提供食物。猎杀它们能让当地营地之间的小路稍微安全一些。粗臂的交易既考验新兵应对当地野兽的本领，也为即将到来的寒夜增添了食物储备。"}},faq={{q="斯登·粗臂是谁？",a="斯登·粗臂是驻守在寒脊山谷安威玛尔外的一名矮人。他照看初来乍到的新兵，并用实用的装备换取他们猎获的当地野味。",al={"斯登·粗臂","寒冬准备任务由谁提供","安威玛尔装备供应商"}},{q="斯登为什么需要狼肉？",a="安威玛尔的哨站依靠当地狩猎来维持补给。狼肉养活了居住在这片偏僻雪谷中的士兵和训练师。",al={"为什么需要狼肉","硬狼肉","狼肉的用途"}},{q="这项任务需要的狼在哪里？",a="狼游荡在寒脊山谷各处的雪地空地上，尤其是安威玛尔主庭院外，以及通往外围营地的小路沿线。",al={"狼在哪里","寒脊狼的位置","哪里获取狼肉"}},{q="斯登提供什么奖励？",a="斯登会给新兵一副保暖手套，保护他们的双手免受丹莫罗凛冽寒风的侵袭。",al={"寒冬准备奖励","能获得什么手套","任务奖励"}},{q="矮人觉得狼肉是好食物吗？",a="狼肉坚韧粗糙，难以嚼烂，但生活在丹莫罗严酷山地气候中的矮人，比起精致佳肴，更看重扎实管饱的食物。无论炖煮，还是架在营火上烤制，狼肉都能供驻军充饥。",al={"狼肉好吃吗","矮人狼肉","吃狼肉"}},{q="侏儒也能做这个任务吗？",a="可以。在寒脊山谷与矮人盟友一同训练的侏儒，也面对着同样刺骨的寒风，需要保暖的衣物。",al={"侏儒寒冬准备","侏儒能获得手套吗","侏儒寒冷天气"}}},fx={cf6e8786={q="寒脊山谷里的狼在做什么？",a="毛皮蓬乱的幼狼和森林狼是寒脊山谷本土的掠食者，在冰封的峭壁间游荡。它们是丹莫罗严酷山地生态的一部分，但在安威玛尔门外凶狠地徘徊，也让它们成了新兵们挥之不去的麻烦，同时又为哨站提供了便利的新鲜补给来源。",al={"这里为何有狼","寒脊山谷的狼","丹莫罗的狼群威胁"}}},fp="18,156,25.245.0,21.291.0,21.170.0,29.156.0,43.147.0,30.94.0,48.192.0,29.122.0"}
P.entries["quest:1791"] = {n="捕风者",s="“捕风者”是一项指引任务，指示经验丰富的战士去北方极远处寻找一位隐居的巨魔萨满。在“乱斗”试炼中证明了自己的实力并掌握了狂暴姿态后，战士们被指引去寻找一把与他们日益增长的怒火相匹配的武器。",h="“捕风者”是一项指引任务，指示经验丰富的战士去北方极远处寻找一位隐居的巨魔萨满。在“乱斗”试炼中证明了自己的实力并掌握了狂暴姿态后，战士们被指引去寻找一把与他们日益增长的怒火相匹配的武器。",kw={"奥特兰克山脉","捕风者巴斯拉","狂暴姿态","塞克隆尼亚","勇士岛","克兰诺克·马克雷德","塔伦米尔","乱斗","捕风者"},ang={["class:Warrior"]="这场成年礼将你在勇士岛上掌握的狂暴姿态与通过元素力量锻造传奇武器的追求联系在了一起。",["race:Troll"]="寻找巴斯拉证明了即使是在洛丹伦破碎的废墟深处，巨魔萨满和武器制造者所掌握的神秘知识也受到各族战士的敬仰。"},sec={{t="狂战士的武器",b="在勇士岛上幸存并通过残酷的“乱斗”试炼后，战士们便从克兰诺克·马克雷德那里获得了狂暴姿态的凶猛纪律。然而，纯粹的武技纪律还需要与之相称的武器。克兰诺克意识到了这一点，于是他让这些前途无量的战士离开贫瘠之地的海岸，指引他们跨越大陆，去寻找一位能够打造非凡武器的隐居工匠。"},{t="河岸上的隐士",b="任务指引旅行者深入洛丹伦北部的纷争山谷，具体来说是奥特兰克山脉和被瘟疫侵蚀的西瘟疫之地之间那片迷雾笼罩的边境地带。巨魔隐士捕风者巴斯拉独自居住在流经塔伦米尔北部的河岸边的石质废墟中。巴斯拉并非普通的隐士：他既是一位天赋异禀的武器制造者，又是一位强大的元素萨满，他正在等待那些决心打造出真正非凡之物的战士。"}},faq={{q="是谁让你去找捕风者的？",a="当你征服了“乱斗”并学会了狂暴姿态后，位于贫瘠之地东海岸外勇士岛上的战斗试炼大师克兰诺克·马克雷德就会派你踏上这段旅程。",al={"任务发布者","谁发布了捕风者任务","克兰诺克·马克雷德任务"}},{q="捕风者巴斯拉是谁？",a="巴斯拉是一位神秘的巨魔隐士、武器锻造大师和强大的萨满，他隐居在奥特兰克山脉和西瘟疫之地之间的荒野中。",al={"巴斯拉是谁","捕风者巴斯拉背景故事","巴斯拉的身份"}},{q="巴斯拉具体在哪里？",a="巴斯拉在流经塔伦米尔北部的河流东岸安营扎寨，就在奥特兰克和西瘟疫之地交界处的古代废墟附近。",al={"巴斯拉在哪里","巴斯拉的位置","寻找巴斯拉"}},{q="为什么克兰诺克要派战士去找巴斯拉？",a="克兰诺克认为，掌握了凶猛狂暴姿态的战士需要一把出色的武器来引导那股怒火，而巴斯拉拥有打造这种武器所必需的罕见元素和锻造知识。",al={"为什么要去见巴斯拉","这个任务的目的是什么","捕风者的目的"}},{q="与巴斯拉交谈后会发生什么？",a="与巴斯拉交谈后，将立即开启对抗狂暴元素生物塞克隆尼亚的任务，并收集稀有材料来制造一把强力的武器。",al={"捕风者之后是什么","塞克隆尼亚后续任务","捕风者任务后续"}},{q="对于从贫瘠之地出发的旅行者来说，这趟旅程安全吗？",a="这相当危险。旅程将带旅行者穿过希尔斯布莱德丘陵，进入辛迪加巢穴附近的北部纷争领土，那里有凶猛的山地掠食者，还有致命的西瘟疫之地瘟疫。",al={"这很危险吗","塔伦米尔河流的危险"}}},fp="15,172,24.223.0,27.334.0,38.107.0,32.154.0,34.157.0,43.170.0,40.114.1,60.218.0"}
P.entries["quest:1792"] = {n="旋风武器",s="战士选定的武器正等待承接塞克隆尼亚留下的风暴。旋风之心能将这个元素生物的狂怒束缚于锻造的容器之中。",h="战士选定的武器正等待承接塞克隆尼亚留下的风暴。旋风之心能将这个元素生物的狂怒束缚于锻造的容器之中。",kw={"塞克隆尼亚","元素生物","风暴","容器","战士武器","旋风之心","旋风武器"},ang={["class:Warrior"]="身为战士，你可以获得一件灌注了塞克隆尼亚猛烈风暴之力的武器。"},sec={{t="灌注风暴",b="塞克隆尼亚倒下、战士取得它的心脏后，工匠便着手准备一件武器，用来承载风暴之力。这颗心脏被融入选定的武器，使锻造的金属成为元素狂怒的载体。"},{t="塞克隆尼亚之力",b="塞克隆尼亚的心脏蕴藏着呼啸狂风与猛烈风暴的暴烈之力。被束缚于锻造的武器之后，它便为持有者的武艺增添了风暴鲜活的力量。每一次打击都带着那个被击败的元素生物的力量，如今，它的风暴在征服者手中肆虐。"}},faq={{q="旋风武器是什么任务？",a="战士可以将塞克隆尼亚的旋风之心束缚于选定的武器之中，让元素之力与自身的力量相结合。",al={"旋风武器是什么","旋风武器背景故事","这是什么任务"}},{q="塞克隆尼亚是谁？",a="塞克隆尼亚是狂风与风暴的元素化身。击败它便能取得旋风之心，将原始的风之能量束缚于实体武器之中。",al={"塞克隆尼亚是谁","塞克隆尼亚背景故事","塞克隆尼亚是什么"}},{q="旋风之心是什么？",a="旋风之心是塞克隆尼亚的核心，在这个元素生物被击败后便可取得。它蕴藏着风暴的狂怒，可以被束缚于战士选定的锻造容器之中。",al={"旋风之心是什么","塞克隆尼亚的心脏","塞克隆尼亚之心"}},{q="武器如何获得力量？",a="战士选定一件锻造的武器，再将塞克隆尼亚的旋风之心束缚其中。随后，元素的狂怒便在钢铁中奔涌。",al={"旋风武器如何制作","选定的容器","锻造旋风武器"}},{q="武器有哪些选择？",a="战士选择一件武器，用来承载塞克隆尼亚的风暴精华。",al={"可以选择哪件武器","旋风武器选择","有哪些武器可选"}},{q="为何人们渴求塞克隆尼亚的力量？",a="战士们寻求塞克隆尼亚的力量，以便通过武器驾驭鲜活狂风的怒威。",al={"战士为何想要旋风武器","旋风武器的重要性"}}},fp="16,137,18.211.0,22.301.0,35.131.0,17.155.0,28.169.0,28.139.0,40.73.0,38.91.0"}
P.entries["quest:1793"] = {n="勇气之书",s="在暴风城和铁炉堡，年轻的联盟圣骑士面临着勇气与责任的试炼。导师要求他们证明自己既能熟练作战，也能保护无辜者。",h="在暴风城和铁炉堡，年轻的联盟圣骑士面临着勇气与责任的试炼。导师要求他们证明自己既能熟练作战，也能保护无辜者。",kw={"光明大教堂","达索瑞恩·拉尔","圣光","铁炉堡","圣骑士试炼","白银之手","蒂萨·热炉","勇气之书"},ang={["class:Paladin"]="作为圣骑士，你要经历一场仪式，将对他人的责任置于自身安危之上，成为圣光值得信赖的守卫者。",["faction:Alliance"]="作为联盟的勇士，你准备保卫各处定居点，抵御从当地匪徒到凶残入侵者的种种威胁。",["race:Dwarf"]="作为矮人，你在铁炉堡接受训练，蒂萨·热炉等导师要求你证明，你的坚毅受到神圣使命的指引。",["race:Human"]="作为人类，你在光明大教堂中接受达索瑞恩·拉尔监督下的这场试炼。它承载着暴风城对白银之手创立理念的忠诚。"},sec={{t="圣骑士的衡量标准",b="暴风城和铁炉堡的年轻圣骑士必须直面可怕的危险，毫不退缩。他们的导师在光明大教堂和秘法大厅中考验他们的决心。巨龙和恶魔可能会威胁那些无力自卫的人。圣骑士必须守在他们身旁。"},{t="骑士团的美德",b="神圣的战士既需要武器和盾牌，也需要勇气。这场试炼教导圣骑士，若没有庇护无助者的坚定誓言，力量便没有多少意义。当危险威胁联盟时，联盟的守卫者必须坚守阵地，保护受他们照料的人。"}},faq={{q="勇气之书的目的是什么？",a="勇气之书考验联盟圣骑士是否拥有保护弱者的勇气与无私的决心。圣光的导师通过这场试炼，判断新成员是否已准备好在骑士团中晋升。",al={"什么是勇气之书","勇气之书的目的","为什么要做勇气之书"}},{q="谁指引圣骑士完成这场试炼？",a="联盟各主城的资深圣骑士指引新成员完成试炼。达索瑞恩·拉尔在暴风城的光明大教堂召唤他们，蒂萨·热炉则在铁炉堡的秘法大厅召唤他们。",al={"谁给予勇气之书","勇气之书任务给予者","谁开启勇气之书"}},{q="这场试炼会引向何方？",a="最初的召唤引出一系列考验圣骑士决心的试炼。这些试炼让新成员深入险境，保卫王国与无辜者。",al={"勇气之书之后是什么","勇气之书后续","勇气之书任务链"}},{q="为什么圣骑士如此重视勇气？",a="当恶魔或巨龙等恐怖威胁袭来时，勇气帮助圣骑士坚守信仰，保护他人。没有勇气，恐惧便可能击垮战士的意志。",al={"为何需要勇气","勇气为何对圣骑士重要"}},{q="矮人和人类圣骑士接受的是同样的考验吗？",a="人类圣骑士在暴风城的光明大教堂接受训练，矮人则在铁炉堡受训。这两种传统都教导圣骑士在圣光的指引下，心怀勇气、恪尽职守并保护无助者。",al={"矮人的试炼有何不同","铁炉堡勇气之书","暴风城勇气之书"}},{q="这场试炼阐明了哪些核心教诲？",a="这场试炼教导圣骑士勇敢面对危险，庇护弱者，并在恐怖降临时坚守信仰。",al={"勇气之书的教诲","这本书教导什么"}}},fx={["81822402"]={q="圣骑士导师为什么要你接受这场试炼？",a="恶魔和巨龙等邪恶威胁日益逼近，艾泽拉斯各地的局势愈发险恶。虽然你已经证明圣光会回应你的呼唤，但达索瑞恩·拉尔和蒂萨·热炉深知，仅有信仰还远远不够。他们需要在更大的危机降临你的家园之前，考验你身躯之下的胆魄，确认你拥有真正的圣骑士所必需的坚定勇气。",al={"为何接受试炼","达索瑞恩·拉尔的动机","蒂萨·热炉安排试炼的原因"}},f91e68e3={q="为什么必须由你接受这场试炼，而不是资深圣骑士或卫兵？",a="这趟旅程并非城镇卫兵或老练骑士可以替你完成的防卫差事。它是属于你个人的成长仪式。导师们必须看到你的意志在困境中的表现，考验你是否有能力保护弱者、坚守信仰，并在恐惧面前屹立不倒。",al={"勇气之书为何选我","勇气试炼为何派玩家前去","卫兵为何不能代劳"}}},fp="17,169,24.280.0,20.264.0,41.213.0,35.206.0,27.154.0,50.154.0,52.176.0,44.106.0"}
P.entries["quest:1795"] = {n="誓缚",s="“契约”是术士寻求驾驭地狱犬所必须完成的终极仪式。该仪式由隐居在棘齿城上方的神秘召唤师斯坦哈德·法尔杉监督，利用修复后的《秘法会之书》从扭曲虚空中撕裂出一只凶猛的恶魔掠食者，并通过战斗试炼迫使其臣服。",h="“契约”是术士寻求驾驭地狱犬所必须完成的终极仪式。该仪式由隐居在棘齿城上方的神秘召唤师斯坦哈德·法尔杉监督，利用修复后的《秘法会之书》从扭曲虚空中撕裂出一只凶猛的恶魔掠食者，并通过战斗试炼迫使其臣服。",kw={"贫瘠之地","地狱犬","棘齿城","斯坦哈德·法尔杉","召唤","契约仪式","秘法会之书","术士"},ang={["class:Warlock"]="制服地狱犬是任何术士的重要里程碑，为他们提供了一种专门的抗魔法掠食者，使其能够吞噬法术并压制敌对施法者。",["faction:Alliance"]="联盟术士会从安全的暴风城出发，跨越海洋来到崎岖的中立避风港棘齿城，在斯坦哈德的注视下完成他们危险的召唤仪式。",["faction:Horde"]="部落的修炼者则会深入贫瘠之地的中心，去证明他们对虚空的掌控，并在中立的土地上站在斯坦哈德面前完成猎犬的契约。"},sec={{t="秘法会之圆",b="斯坦哈德·法尔杉栖身于俯瞰地精港口棘齿城的悬崖之上，在此进行着卡利姆多最危险的恶魔学试炼。当术士收集齐拼凑古老《秘法会之书》所需的各种残片和试剂后，斯坦哈德便会准备契约之地。他会布置一个内圈的约束符文，同时他的忠诚侍僧们会通过附魔之杖引导能量来完成外圈，确保任何从中浮现的恐怖存在都被隔离在下方的定居点之外。"},{t="征服猎犬",b="受训者诵读《秘法会之书》中记载的咒语，打开了一道通往扭曲虚空的桥梁。地狱犬是贪婪的恶魔猎犬，它们天生渴求奥术力量，并以魔法能量为食。被召唤出的野兽绝非靠好言相劝或温和束缚就能控制；它必须在战斗中被暴力制服并击溃，才会承认术士为它真正的主人。在冲突中幸存下来，证明了召唤师已经做好准备，可以驱使这条猎犬对抗敌方施法者。"}},faq={{q="这个仪式的目的是什么？",a="该仪式允许术士召唤并契约一只地狱犬为己所用。通过在斯坦哈德·法尔杉的召唤法阵内诵读完整的《秘法会之书》，术士会将这只恶魔掠食者从虚空中引出，并在战斗中击败它，从而赢得该恶魔永久的服侍。",al={"为什么要完成这个任务","地狱犬任务目标","契约的目的"}},{q="谁是斯坦哈德·法尔杉？",a="斯坦哈德·法尔杉是一位造诣极高的术士，在贫瘠之地棘齿城上方的一座塔楼中运作。由于他掌握着渊博的黑暗召唤学知识，来自联盟和部落的导师们都会悄悄地将他们最有前途的学徒送去接受他的教导，学习进阶的契约仪式。",al={"谁是斯坦哈德","斯坦哈德·法尔杉背景故事","任务发放人斯坦哈德"}},{q="为什么术士必须杀死恶魔而不是直接奴役它？",a="地狱犬是一种极具侵略性、以魔法为食的掠食者，它们只尊重绝对的统治力。仪式要求修炼者在物理和魔法战斗中击败恶魔，以挫其锐气并将权威烙印在它的灵魂深处，确保它能服从未来的召唤。",al={"为什么要杀死地狱犬","我能直接奴役地狱犬吗","地狱犬战斗"}},{q="部落和联盟的术士都能在这里进行这个仪式吗？",a="是的。虽然重建《秘法会之书》的前置任务会根据阵营有所不同，但联盟和部落的术士最终都会被指引到棘齿城上方的斯坦哈德·法尔杉处进行最后的召唤。",al={"这是部落专属吗","这是联盟专属吗","谁能接到这个任务"}},{q="如果地狱犬击败了召唤师会发生什么？",a="如果召唤师落败，恶魔会被放逐回扭曲虚空，仪式即告失败。不过，斯坦哈德允许在失败中幸存的术士重新获取一份新的《秘法会之书》，并在做好充分准备后再次尝试召唤。",al={"如果我死了怎么办","契约仪式失败","我可以重试仪式吗"}},{q="地狱犬与其他恶魔相比有什么独特之处？",a="地狱犬是靠感知魔法散逸来捕猎的恶魔猎犬。它们不仅依靠蛮力或暗影法术，更擅长嗅出魔法痕迹、吞噬激活的附魔并干扰敌方施法者，这使它们成为对抗敌对施法者时不可多得的宝贵同伴。",al={"地狱犬有什么能力","地狱犬背景故事","为什么需要地狱犬"}}},fp="11,217,18.453.0,22.442.0,35.259.0,22.292.0,66.256.0,62.183.0,51.213.0,54.277.0"}
P.entries["quest:1796"] = {n="魔化金线血袍",s="在棘齿城，梅纳拉·沃伦德请术士寻找奥法之袍，用来承载强大的附魔。",h="在棘齿城，梅纳拉·沃伦德请术士寻找奥法之袍，用来承载强大的附魔。",kw={"贫瘠之地","血袍","魔化金线血袍","梅纳拉·沃伦德","奥法之袍","裁缝","术士任务"},ang={["class:Warlock"]="身为术士，制作魔化金线血袍能让你学会以坚实且精心准备的基础，打造强大的神器。",["profession:Tailoring"]="身为裁缝，你需要稀有的奥法之袍图样，还要掌握运用蜘蛛丝和大量优质丝绸卷的技艺。",["race:Orc"]="身为 Orc 术士，为精巧的长袍收集材料，让你得以用更隐秘的方式掌控邪能，远离窥探的目光，以及族群昔日与恶魔纠葛的阴影。",["race:Undead"]="身为被遗忘者，你或许会远赴烈日炙烤的贫瘠之地，向 Menara 求教，强化脆弱的凡躯，以承受自己难以驾驭的法术。"},sec={{t="奥术的容器",b="梅纳拉·沃伦德请追求更强力量的术士为她带来一件奥法之袍。她需要一件足以承载黑暗魔法的衣袍。一件魔法圣物的力量，取决于制作材料时投入的技艺、材料的稀有程度和付出的心血。普通的破布承受不住深厚的附魔，因此这件长袍必须制作精良，能够接受这些附魔。"},{t="技艺与野心",b="梅纳拉 欣赏能亲手织出长袍的术士，但比起自豪，她更看重野心。你可以亲手缝制丝绸，委托技艺精湛的工匠，或在市场上购买长袍。无论通过哪种方式获得，制成的衣袍都已准备好，成为掌控邪能的专用工具。"}},faq={{q="梅纳拉·沃伦德为什么特别需要奥法之袍？",a="强大的附魔需要以精湛技艺和稀有材料制成的衣袍。梅纳拉 将奥法之袍作为能够容纳力量的基础，准备把那些力量束缚其中。",al={"为何需要奥法之袍","为何需要这件长袍","长袍用途"}},{q="梅纳拉·沃伦德在哪里？",a="梅纳拉·沃伦德住在贫瘠之地的地精港口棘齿城。她指导那些希望精进技艺、制作专用装备的术士。",al={"梅纳拉·沃伦德位置","梅纳拉 在哪里","梅纳拉·沃伦德在哪里"}},{q="必须亲手裁制奥法之袍吗？",a="不必。梅纳拉 尊重亲手制作长袍的付出，但也接受通过交易获得或向其他工匠购买的长袍。你可以通过任何切实可行的方式取得它。",al={"是否需要裁缝","能否购买长袍","裁缝要求"}},{q="奥法之袍的图样从哪里获得？",a="这张图样十分稀有，可以从邪教徒和黑暗施法者身上找到。黑海岸奥萨拉克斯之塔的暗滩教派唤魔师，以及暮色森林的迪菲亚附魔师，都可能携带它。",al={"奥法之袍图样","如何获得图样","裁缝配方位置"}},{q="交出奥法之袍后会发生什么？",a="梅纳拉 会收下长袍，作为后续灌注仪式的材料。如果你穿着它去交付，她会立刻将它脱下，让你在完成后续步骤前没有胸甲可穿。",al={"是否会失去长袍","长袍消失","长袍会怎样"}},{q="魔化金线血袍是什么？",a="魔化金线血袍是为中阶术士制作的专用衣袍。黑暗材料和防护附魔增强了穿戴者的承受能力，也增加了其黑暗能量储备。",al={"血袍是什么","血袍背景","魔化金线血袍"}}},fp="43,102,18.345.0,18.279.0,61.164.0,35.149.0,47.174.0,53.189.0,58.211.0,37.187.0"}
P.entries["quest:1798"] = {n="寻找斯坦哈德",s="术士离开暴风城，前往棘齿城，斯坦哈德·法尔杉能在那里教他们召唤地狱猎犬。在这座地精港口的地下，他掌握的知识为术士开启了召唤更危险恶魔的道路。",h="术士离开暴风城，前往棘齿城，斯坦哈德·法尔杉能在那里教他们召唤地狱猎犬。在这座地精港口的地下，他掌握的知识为术士开启了召唤更危险恶魔的道路。",kw={"地狱猎犬","黑暗缚灵者加科因","棘齿城","寻找斯坦哈德","暴风城","斯坦哈德·法尔杉","贫瘠之地","术士"},ang={["class:Warlock"]="作为术士，当你不再局限于基础的魔仆和魅魔，开始学习召唤狡诈且能吸取魔法的地狱猎犬时，你便迈过了一道重要的门槛。",["faction:Alliance"]="作为联盟术士，你要跨越无尽之海，深入卡利姆多由部落主导的崎岖腹地，才能找到斯坦哈德。"},sec={{t="来自海另一端的召唤",b="黑暗缚灵者加科因派你离开暴风城，寻求召唤地狱猎犬的帮助。他在法师区下方的已宰的羔羊指导术士，但这些仪式所需的知识超出了他在那里所能传授的范围。你将跨越无尽之海，前往卡利姆多，那里或许有另一位术士知道方法。"},{t="棘齿城的隐士",b="斯坦哈德·法尔杉住在地精港口棘齿城上方的干旱丘陵中。他是一名人类术士，与加科因同属一个秘密结社，地位相当。在中立领地，斯坦哈德可以避开联盟治安官、教会审讯官和部落哨兵的耳目行事。术士们前来寻找他，希望掌握那些吸取法力的恶魔。"}},faq={{q="谁派你去寻找斯坦哈德？",a="当你准备好学习召唤地狱猎犬时，黑暗缚灵者加科因会从暴风城法师区的已宰的羔羊派你出发。",al={"谁给予寻找斯坦哈德任务","任务给予者","加科因"}},{q="斯坦哈德·法尔杉在哪里？",a="斯坦哈德·法尔杉住在贫瘠之地的一处高地上，俯瞰着地精港口棘齿城。",al={"斯坦哈德位置","斯坦哈德在哪里","寻找斯坦哈德"}},{q="为什么联盟术士必须远赴贫瘠之地？",a="加科因无法在暴风城提供召唤地狱猎犬的仪式所需的知识和材料。斯坦哈德·法尔杉掌握这些知识，并在棘齿城附近的中立领地活动，远离当地的监视。",al={"为什么去贫瘠之地","为什么去卡利姆多","为什么去棘齿城"}},{q="这个任务最终会解锁什么能力？",a="与斯坦哈德交谈会开启一系列任务，最终涉及阴谋之书，以及召唤地狱猎犬伙伴的束缚仪式。",al={"用于获得什么宠物","能获得什么","地狱猎犬任务"}},{q="斯坦哈德·法尔杉敌视部落吗？",a="不。斯坦哈德住在地精的中立领地，教导联盟和部落术士召唤地狱猎犬，同时与各个秘密结社保持联系。",al={"斯坦哈德是否仅限联盟","部落斯坦哈德"}},{q="与斯坦哈德交谈后会发生什么？",a="斯坦哈德会要求你收集束缚仪式所需的材料，由此开启一系列涉及阴谋之书的任务。",al={"后续任务","寻找斯坦哈德后续","阴谋之书"}}},fp="15,164,24.279.0,21.315.0,30.135.0,32.89.0,71.205.0,47.132.0,39.152.0,40.114.0"}
P.entries["quest:18"] = {n="潜行者兄弟会",s="在北郡东侧的河对岸，迪菲亚潜行者已开始侵扰山谷。维里副队长派新兵前去对付这些匪徒，他们佩戴的红色粗麻面罩，让暴风城首次清楚地察觉到这群人正有组织地活动。",h="在北郡东侧的河对岸，迪菲亚潜行者已开始侵扰山谷。维里副队长派新兵前去对付这些匪徒，他们佩戴的红色粗麻面罩，让暴风城首次清楚地察觉到这群人正有组织地活动。",kw={"面罩","盗贼兄弟会","迪菲亚","维里副队长","艾尔文","北郡","暴风城军队"},ang={["class:Rogue"]="对于初学乍练的潜行者来说，迪菲亚让他们得以窥见在人类腹地的阴影中运作的有组织犯罪网络。",["faction:Alliance"]="王国正规军人手吃紧，暴风城的官员只能依靠新近到来的联盟新兵维持北郡的安宁。",["race:Human"]="对于在北郡开始训练的人类来说，迪菲亚让他们看到，暴风城王国的安宁正从内部受到侵蚀。"},sec={{t="山谷中的匪徒",b="北郡山谷长久以来都是艾尔文森林中的一处避风港。暴风城守卫着这里，新兵和圣光的牧师也在此接受训练。然而近来，山谷的守备日渐薄弱。流浪者和窃贼渡过东侧的河流，藏身于树林附近。他们在修道院附近扎起小型营地。\n\n维里副队长维持着秩序，但卫兵无法看守山谷的每一个角落。他需要志愿者协助守住防线。"},{t="深红的标记",b="这些亡命之徒结伴行动，佩戴着相同的红色粗麻面罩。他们自称迪菲亚潜行者，以这块布料表明自己的归属。维里副队长派新兵击退匪徒，并收缴他们的面罩。他希望借此减缓他们的推进，并查明迪菲亚已渗入王国腹地多深。"}},faq={{q="迪菲亚潜行者是什么人？",a="迪菲亚潜行者是一伙有组织的匪徒和亡命之徒，活跃于艾尔文森林和西部荒野。起初，北郡的官员只把他们视为胆大妄为的窃贼，但这些匪徒佩戴着相同的红色粗麻面罩，并听从统一的指挥。",al={"迪菲亚是什么人","迪菲亚潜行者是什么","迪菲亚背景故事"}},{q="维里副队长为什么向新兵求助，而不动用暴风城军队？",a="暴风城军队和城市卫兵分散在王国各地，人手捉襟见肘。邻近地区的动荡日益加剧，暴风城的领导者也承受着压力。当地的副队长们只得求助于热心的志愿者和初出茅庐的新兵，抵御匪徒。",al={"维里为何需要帮助","暴风城卫兵在哪里","为何没有军队"}},{q="这些窃贼从哪里来？",a="窃贼聚集在修道院东侧的河对岸。他们在当地农庄边缘和葡萄园附近的营地周围潜行。",al={"匪徒在哪里","迪菲亚在北郡的位置"}},{q="窃贼为什么佩戴红色粗麻面罩？",a="红色粗麻面罩表明窃贼效忠于迪菲亚潜行者，也掩盖了他们的身份。它还向人类领地各处的其他亡命之徒表明这份归属。",al={"为何佩戴红色面罩","红色面罩的含义","红色粗麻"}},{q="完成这个任务后会发生什么？",a="维里副队长和当地居民很快发现，匪徒的威胁已深入北郡。随后，新兵帮助米莉·奥斯沃斯处理遭到破坏的收成，并追查一名叫加瑞克·帕德弗特的匪首。",al={"接下来是什么","盗贼兄弟会之后"}},{q="维里副队长知道谁在领导迪菲亚吗？",a="维里并不清楚这个组织的势力究竟有多大。他知道这些匪徒自称迪菲亚潜行者，并怀疑他们出现在修道院附近，对暴风城而言是不祥之兆。",al={"维里认识范克里夫吗","谁领导北郡的迪菲亚"}}},fx={e491bbee={q="维里副队长为什么要你对付那些盗贼？",a="维里副队长负责保护北郡修道院及周围的山谷。一伙自称迪菲亚潜行者的猖狂罪犯潜入了河对岸的东部树林，威胁着修道院和当地劳工的安全。维里希望立刻压制他们，以免他们站稳脚跟，或直接向山谷发起进攻。",al={"维里为何要求此事","维里的动机","为何在此阻止迪菲亚"}},["4db9a478"]={q="河对岸的盗贼是谁？",a="你被派去对付迪菲亚暴徒，他们是隶属于迪菲亚潜行者的亡命之徒，在北郡修道院以东的小河对岸树林中扎下了营地。他们聚集在葡萄园和周围的田地附近，侦察山谷、骚扰当地居民，同时就在暴风城的眼皮底下建立武装据点。",al={"盗贼是谁","我在与谁战斗","北郡的迪菲亚"}}},fp="22,232,21.429.0,17.331.0,31.244.0,82.243.0,36.135.0,44.181.0,41.205.0,45.186.0"}
P.entries["quest:180"] = {n="通缉：范高雷中尉",s="湖畔镇的一纸悬赏要取范高雷中尉的性命。所罗门镇长正在招募猎手，阻止暗皮豺狼人向赤脊山进逼。范高雷效命于叛变的巫师莫甘斯，他的死将打击莫甘斯的势力。",h="湖畔镇的一纸悬赏要取范高雷中尉的性命。所罗门镇长正在招募猎手，阻止暗皮豺狼人向赤脊山进逼。范高雷效命于叛变的巫师莫甘斯，他的死将打击莫甘斯的势力。",kw={"范高雷","豺狼人","湖畔镇","范高雷中尉","所罗门镇长","莫甘斯","赤脊山","暗皮"},ang={["faction:Alliance"]="对联盟而言，湖畔镇是赤脊山的一处重要据点。除掉范高雷，就能避免这处聚居地与外界失去联系。",["race:Human"]="身为人类，你在赤脊山亲身体会到了暴风城的漠视。迎战豺狼人酋长，关系着你家园的存亡。"},sec={{t="围困中的小镇",b="湖畔镇面临的危险与日俱增。暴风城的军队兵力捉襟见肘，瓦里安·乌瑞恩国王又神秘失踪。伯瓦尔·弗塔根公爵任由赤脊山这样的边境聚居地自行防卫。暗皮氏族劫掠商路，焚烧农庄，步步逼近小镇外围。所罗门镇长张贴悬赏，招募雇佣兵前往王国士兵不肯进军的地方。"},{t="莫甘斯的副官",b="范高雷中尉率领暗皮豺狼人，为莫甘斯执行命令。莫甘斯是一个藏身于赤脊山群山中的叛逃黑暗巫师。在范高雷的指挥下，豺狼人开始协同进攻，不再像四散的拾荒者那样各自为战。他们的袭击可能切断湖畔镇与艾尔文森林之间的联系。范高雷被砍下的爪子将向所罗门镇长证明，莫甘斯凶残的先锋部队已被击溃。"}},faq={{q="范高雷中尉是谁？",a="范高雷中尉率领赤脊山的暗皮豺狼人，协调他们的劫掠行动，并执行黑暗巫师莫甘斯的意志，而莫甘斯正威胁着湖畔镇。",al={"范高雷中尉","范高雷是谁","范高雷背景故事"}},{q="谁发布了对范高雷中尉的悬赏？",a="湖畔镇的领袖所罗门镇长发布了悬赏，以保护赤脊山外围，抵御敌对的豺狼人和黑暗施法者。",al={"谁发布了悬赏","谁想要范高雷死","所罗门镇长 范高雷"}},{q="暴风城为什么不派士兵对付豺狼人？",a="瓦里安·乌瑞恩国王突然失踪，加上内部动荡，让暴风城陷入瘫痪。伯瓦尔·弗塔根公爵和贵族拒绝向湖畔镇这样的偏远城镇派遣正规军分队，所罗门镇长只得雇用冒险者。",al={"为什么没有暴风城卫兵","暴风城士兵在哪里","军队为什么不援助"}},{q="领取赏金需要什么凭证？",a="所罗门镇长要求交出范高雷中尉被砍下的爪子，以证明这名暗皮军阀已被击杀。",al={"范高雷凭证","范高雷的爪子","交任务需要什么物品"}},{q="莫甘斯是谁，范高雷为什么追随他？",a="莫甘斯是一名叛逃的人类施法者，在赤脊山的一座高塔中研习黑暗魔法。他迫使暗皮豺狼人服从自己的意志，并让范高雷中尉为他执行命令，在乡间散布恐怖。",al={"莫甘斯是谁","豺狼人为什么追随莫甘斯","范高雷 摩根斯"}},{q="暗皮豺狼人是什么？",a="暗皮是一个凶猛的豺狼人氏族，盘踞在赤脊山的峭壁与森林之间。多年来，他们的侵袭和残暴伏击一直困扰着湖畔镇的定居者。",al={"暗皮氏族","赤脊山豺狼人","暗皮背景故事"}}},fp="26,257,18.402.0,21.382.0,26.162.0,45.146.0,57.268.0,43.113.0,48.221.0,31.175.0"}
P.entries["quest:1801"] = {n="阴谋之书",s="在贫瘠之地，斯坦哈德·法尔杉派部落术士前往东方，寻找一本失落的魔典。阴谋之书记载了召唤和束缚地狱猎犬的仪式，而寻书之旅要从幽暗城的制图师约拉·安尼森开始。",h="在贫瘠之地，斯坦哈德·法尔杉派部落术士前往东方，寻找一本失落的魔典。阴谋之书记载了召唤和束缚地狱猎犬的仪式，而寻书之旅要从幽暗城的制图师约拉·安尼森开始。",kw={"贫瘠之地","地狱猎犬","约拉·安尼森","棘齿城","斯坦哈德·法尔杉","阴谋之书","幽暗城","术士任务"},ang={["class:Warlock"]="作为部落术士，你必须完成这场试炼，才能驯服地狱猎犬。你要往返于卡利姆多和东部王国之间，收集被遗忘的仪式材料。",["faction:Horde"]="作为部落的一员，你会看到卡利姆多的黑暗施法者与被遗忘者的神秘学者在洛丹伦废墟之下携手合作。"},sec={{t="追寻古老知识",b="斯坦哈德·法尔杉说，召唤地狱猎犬，光靠寻常的邪能魔法还不够。这些捕食者以魔法能量为食，能抵抗普通的召唤法阵。初学者需要专门的法阵，以及一本名为阴谋之书的古老魔典。最早在没有外力协助的情况下束缚地狱猎犬的术士组织编写了这本书。书中的仪式和符印揭示了如何奴役这种危险的恶魔。"},{t="幽暗城的制图师",b="卡利姆多的术士早已失去了阴谋之书的抄本，因此斯坦哈德派学生渡海前往幽暗城，寻找约拉·安尼森。安尼森是一名皇家制图师，负责绘制洛丹伦的地图，却对古老晦涩的典籍颇有研究。他坦言自己厌恶绘制地图，渴求的是罕见的史书、神秘学记述和黑暗魔法论著。"}},faq={{q="阴谋之书是什么？",a="阴谋之书是一本罕见的神秘学魔典，由最早在没有外力帮助的情况下召唤并束缚地狱猎犬的术士编写。书中详尽的指引、结界和仪式，能让人将一只吞噬魔法的野兽安全地召唤到艾泽拉斯。",al={"阴谋之书背景故事","这本书是什么","阴谋之书"}},{q="斯坦哈德·法尔杉为什么派你去幽暗城？",a="斯坦哈德和他在贫瘠之地的学徒都没有阴谋之书的抄本。他派你去找约拉·安尼森，这位幽暗城的制图师也是研究珍稀古籍的学者，或许知道去哪里寻回这本魔典。",al={"为什么去幽暗城","斯坦哈德·法尔杉 幽暗城","为什么找约拉"}},{q="约拉·安尼森是谁？",a="约拉·安尼森是一位在幽暗城工作的被遗忘者学者。他的本职是绘制地图，但他热衷的是晦涩的典籍、通灵术论著和古代文献。",al={"约拉是谁","约拉·安尼森背景故事"}},{q="为什么召唤地狱猎犬需要一本特殊的书？",a="地狱猎犬以奥术和其他魔法能量为食，因此用普通的恶魔法阵召唤它们十分危险。阴谋之书详细记载了防护措施，能在它们吞噬召唤者之前将其束缚。",al={"地狱猎犬为什么需要书","地狱猎犬为什么难以召唤"}}},fp="17,208,28.379.0,29.377.0,30.249.0,50.201.0,21.175.0,51.203.0"}
P.entries["quest:1802"] = {n="阴谋之书",s="从铁炉堡出发，你对阴谋之书的追寻指向了一份遗失的手稿和一艘沉船。散落的书页记载着束缚地狱猎犬的仪式。",h="从铁炉堡出发，你对阴谋之书的追寻指向了一份遗失的手稿和一艘沉船。散落的书页记载着束缚地狱猎犬的仪式。",kw={"碧玉矿洞","地狱猎犬","铁炉堡","克罗姆·粗臂","发霉的书籍","裂蹄堡","斯坦哈德·法尔杉","破损的手稿","阴谋之书"},ang={["class:Warlock"]="对身为术士的你而言，寻回魔典被撕开的两半，是一场成长的试炼。书页中记载的召唤仪式，能让你从虚空召来一只地狱猎犬并将其奴役。",["faction:Alliance"]="身为联盟的施法者，你可以依靠克罗姆·粗臂这样的铁炉堡人脉，跨越大陆追查罕见的恶魔遗物，而不至于公然招来教会或王室的猜疑。"},sec={{t="残缺的魔典",b="阴谋之书从来只有一份抄本。它遭到暴力撕毁，书页被涂污，残篇流落到世界各地。一份破损的手稿漂洋过海来到卡利姆多，落入半人马氏族手中。另一半随船从洛丹伦驶向卡兹莫丹，但船只尚未抵港便沉没了。"},{t="跨越海洋与峡谷",b="两处险地藏着失落的书页。遗失在海上的那部分被冲上了希尔斯布莱德海岸，位于南海镇以西。碧玉矿洞附近的海岸鱼人拾走了浸水的遗物和船只残骸。干燥的另一半存放在千针石林裂蹄堡半人马洞穴深处的一只古老箱子里。残篇集齐后，克罗姆·粗臂可以先研究这部失落的典籍，再将它交还给斯坦哈德·法尔杉。"}},faq={{q="阴谋之书是什么？",a="阴谋之书是一部罕见的恶魔魔典，世上仅存一份。书中的奥术知识记载着术士从扭曲虚空召唤并降服地狱猎犬所需的咒语与束缚仪式。",al={"阴谋之书背景故事","这是什么书","阴谋之书"}},{q="克罗姆·粗臂是谁，他为何想要这部魔典？",a="克罗姆·粗臂是一位铁炉堡矮人，专门研究罕见且被遗忘的典籍。他向联盟术士指明魔典残篇的下落，只求在寻回后能研究一番。",al={"克罗姆·粗臂是谁","克罗姆为何想要这本书","克罗姆·粗臂铁炉堡"}},{q="这本书的两部分流落到了哪里？",a="发霉的书籍被冲上了南海镇以西、碧玉矿洞附近的希尔斯布莱德海岸，被海岸鱼人拾走。破损的手稿则藏在卡利姆多千针石林裂蹄堡的一处半人马洞穴深处，放在一只破旧的箱子里。",al={"魔典残篇在哪里","书籍位置","破损的手稿位置"}},{q="这部魔典最初为何会被撕毁？",a="阴谋之书从来只誊抄过一份。在它那段模糊不清的历史中，有人蓄意涂污了它，从装订处撕下大段书页，并将其带到了卡利姆多。余下的部分则在前往米奈希尔港的航程中遗失于海上。",al={"书为何被撕毁","谁毁坏了魔典"}},{q="斯坦哈德·法尔杉是谁，他与这个任务有什么关系？",a="斯坦哈德·法尔杉是一位经验丰富的术士，住在贫瘠之地的棘齿城附近。他指引有志于召唤之术的人寻回魔典，在他的教导下学习召唤和束缚地狱猎犬的仪式。",al={"斯坦哈德是谁","斯坦哈德·法尔杉","斯坦哈德的关联"}},{q="发霉的书籍为何沾满海中的污垢？",a="发霉的书籍原本装在一艘从洛丹伦海岸驶往米奈希尔港的船上，但那艘船始终未能抵达。船只残骸漂到了希尔斯布莱德近岸，碧玉矿洞附近的海岸鱼人收集了那些潮湿发霉的书页。",al={"发霉的书籍为何湿了","希尔斯布莱德魔典鱼人"}}},fx={["7c4e226c"]={q="发霉的书籍是什么？",a="发霉的书籍是阴谋之书主体装订部分被水浸泡后留下的残本。一艘驶向米奈希尔港的运输船沉没时，它遗失在希尔斯布莱德丘陵沿岸的海中。找回它，就能找回这本魔典中邪恶教义的核心。",al={"发霉的书籍","发霉的书籍是什么","为什么寻找发霉的书籍"}},aa350fa4={q="破损的手稿是什么？",a="破损的手稿是在阴谋之书遗失之前，从原书中撕下的一部分。它漂洋过海，最终落入千针石林的加拉克半人马手中，其中记载着补全整部典籍所需的缺失仪式。",al={"破损的手稿","破损的手稿是什么","半人马手稿"}}},fp="17,155,18.334.0,21.405.0,30.210.0,51.185.0,44.251.0,47.236.0,66.207.0,43.231.0"}
P.entries["quest:1803"] = {n="阴谋之书",s="在幽暗城，部落术士为约拉·安尼森寻找阴谋之书散落的两部分。这部魔典曾收藏于洛丹伦，后来被撕成两半，残卷散落在东部王国危机四伏的水域沿岸，以及卡利姆多半人马领地的深处。",h="在幽暗城，部落术士为约拉·安尼森寻找阴谋之书散落的两部分。这部魔典曾收藏于洛丹伦，后来被撕成两半，残卷散落在东部王国危机四伏的水域沿岸，以及卡利姆多半人马领地的深处。",kw={"加拉克","约拉·安尼森","洛丹伦","发霉的书籍","南海镇","裂蹄堡","破损的手稿","千针石林","阴谋之书","术士任务"},ang={["class:Warlock"]="身为术士，你找回阴谋之书，是完成一场中阶修习者的进阶仪式。书中失落的洛丹伦奥术知识能让你掌握更多召唤法术。",["faction:Horde"]="身为部落的一员，你穿行于千针石林的峡谷，追寻手稿的下落。乱风岗的部落军队与当地半人马常年交战。",["race:Undead"]="身为亡灵，你找回了一部在洛丹伦王国覆灭前收藏于此的魔典。它的归来，让你重获昔日身为人类时的秘术传承。"},sec={{t="分裂的传承",b="阴谋之书曾收藏在洛丹伦的图书馆里。有人损毁了这部邪恶的魔典，撕去了近半数书页，将它分成了两部分。剩下仍装订成册的部分被送往铁炉堡的矮人殿堂。然而，运送它的船只在南海镇以西的礁石海岸失事，如今书页在浅水中腐烂，鱼人在上方搜寻残骸。"},{t="散落两片大陆",b="另一半从洛丹伦辗转来到了卡利姆多南部。在千针石林的裂蹄堡深处，加拉克半人马粗陋地保管着这份手稿。你在希尔斯布莱德潮湿的海岸寻找发霉的书籍，再深入尘土飞扬、野蛮的半人马峡谷，寻找破损的手稿。当两份残卷都送到约拉·安尼森手中，这部传说中的黑暗典籍便能重新完整，供人阅读。"}},faq={{q="阴谋之书是什么？",a="阴谋之书是一部记载恶魔仪式的奥术魔典，曾收藏于洛丹伦的首都。有人将它损毁，分成两部分，随后它便散落在两片大陆上。",al={"阴谋之书背景故事","这本书是什么","阴谋之书"}},{q="为什么这本书的一部分会在南海镇附近？",a="魔典遭到破坏后，剩下仍装订成册的部分原本要送交铁炉堡的学者。运送它的船只在南海镇以西的海岸失事，书也因此流落到当地的鱼人之中。",al={"为何在南海镇","发霉的书籍来历","南海镇以西海岸"}},{q="书页是如何落到千针石林的半人马手中的？",a="原本的魔典在洛丹伦被撕去了大约一半书页，这些书页随后被偷偷运走。经过交易、劫掠，或是辗转流传，破损的手稿最终落到了裂蹄堡深处，加拉克半人马将它保存在一个箱子里。",al={"为何在半人马手中","千针石林书页","裂蹄堡书籍"}},{q="约拉·安尼森是谁？",a="约拉·安尼森是一名被遗忘者术士，身处幽暗城的魔法区。他指引成长中的部落术士找回被遗忘的禁忌知识，加深他们对恶魔力量的掌控。",al={"约拉·安尼森背景故事","约拉是谁"}},{q="最初是谁破坏了这部魔典？",a="破坏魔典的人至今身份不明。约拉·安尼森为魔典遭到损毁而痛惜，也疑惑究竟是谁会对一部蕴含如此强大秘术力量的典籍做出这种事。",al={"谁撕毁了书","谁偷走了书页","魔典破坏者"}},{q="将两部分都带回后，约拉会如何处理这本书？",a="当你带来发霉的书籍和破损的手稿后，约拉·安尼森会将它们合为一册，阅读其中的书页。他会为你接下来的恶魔仪式做好准备。",al={"交还后会发生什么","修复的魔典"}}},fp="17,258,16.353.0,27.374.1,30.177.0,44.194.0,62.240.0,21.187.0,43.151.0,64.187.0"}
P.entries["quest:1804"] = {n="阴谋之书",s="在贫瘠之地，斯坦哈德·法尔杉正等待一名术士为他带来阴谋之书和引导法杖。他们将一同为束缚一只地狱猎犬做好准备。",h="在贫瘠之地，斯坦哈德·法尔杉正等待一名术士为他带来阴谋之书和引导法杖。他们将一同为束缚一只地狱猎犬做好准备。",kw={"贫瘠之地","龙喉氏族","地狱猎犬","克罗姆·粗臂","棘齿城","引导法杖","斯坦哈德·法尔杉","阴谋之书","湿地"},ang={["class:Warlock"]="对术士而言，制服地狱猎犬意味着从与小鬼和虚空行者订立契约，迈向掌控天生以奥术魔法为食的凶猛恶魔。",["faction:Alliance"]="身为联盟的召唤者，你往返于铁炉堡、湿地雾气弥漫的沼泽，以及卡利姆多的中立地精港口棘齿城之间。",["race:Dwarf"]="身为矮人，你深知悉心保存古物的价值。在铁炉堡的探险者大厅，克罗姆·粗臂将破损的遗物重新拼合起来。"},sec={{t="不情愿的交接",b="在铁炉堡的探险者大厅，克罗姆·粗臂将阴谋之书破烂发霉的残页重新装订起来。这位矮人学者不情愿地交出这部罕见的黑暗学术著作，但先要求对方答应给他一份抄本。他还转交了斯坦哈德·法尔杉刚送来的信。书中记载着打通虚空的仪式，但仅凭羊皮纸无法完成仪式。"},{t="夺取龙喉氏族的遗物",b="斯坦哈德的侍从需要聚焦器具，稳定为束缚地狱猎犬而召来的能量。克罗姆派术士前往湿地，那里的龙喉氏族施法者携带着引导法杖。从这些敌对兽人手中夺取法杖，就能为斯坦哈德和他的侍从提供所需的媒介，用来控制裂隙并稳定召来的能量。"},{t="重返贫瘠之地",b="在棘齿城上方高处的斯坦哈德之塔，翻修过的书籍和引导法杖终于凑齐，艰辛的筹备就此完成。器具已经备妥，文字也已译出，斯坦哈德开始准备危险的束缚仪式。召唤者将与一只燃烧军团的猎犬较量，意志力将受到考验。"}},faq={{q="斯坦哈德为什么需要导能魔棒？",a="斯坦哈德的侍从用这些法杖汇聚并稳定召唤和束缚地狱猎犬所需的能量。他们的工作有助于防止传送门崩塌或失控。",al={"为什么需要导能魔棒","导能魔棒的用途","法杖有什么用"}},{q="在哪里能找到导能魔棒？",a="湿地的龙喉氏族兽人施法者持有导能魔棒，尤其是在他们占据的沼泽和废墟一带。",al={"哪里获取导能魔棒","谁掉落导能魔棒","导能魔棒的位置"}},{q="克罗姆·粗臂为什么会参与术士的仪式？",a="克罗姆·粗臂是铁炉堡的一位研究大师，擅长翻译、保存和修复受损的古代手稿。出于对稀有古物的兴趣，他修复了阴谋之书中腐坏的书页。",al={"为什么找克罗姆","铁炉堡矮人为什么帮助术士","克罗姆·粗臂 术士"}},{q="把书和法杖交给斯坦哈德后会发生什么？",a="你将书和法杖交给斯坦哈德后，他便会在塔顶开始束缚仪式。你要面对召唤出的地狱猎犬，并尝试将它制服。",al={"接下来会发生什么","阴谋之书第三步的后续任务","斯坦哈德会做什么"}},{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉是一位强大的术士，住在贫瘠之地棘齿城上方悬崖上的一座孤塔中。卡利姆多和东部王国各地经验丰富的术士，都敬服他在恶魔学上的造诣。",al={"斯坦哈德·法尔杉的故事","斯坦哈德是谁","棘齿城上方的人"}},{q="部落也会使用阴谋之书吗？",a="部落术士遵循自己的阴谋之书仪式，沿着线索寻找卡利姆多各地和幽暗城的其他联络人，而非铁炉堡的克罗姆·粗臂。",al={"部落阴谋之书","兽人也做这个任务吗"}}},fp="17,143,19.338.0,30.322.0,19.270.1,41.163.0,39.125.0,51.223.0,55.138.1,22.203.0,51.163.0"}
P.entries["quest:1805"] = {n="阴谋之书",s="这个任务标志着部落术士学习召唤并奴役地狱犬旅程中最后的准备阶段。在帮助约拉·安尼森修复古老的“秘法会之书”后，修习者必须前往敌对领土夺取三根通道法杖，然后将这些组件带给位于棘齿城的斯坦哈德·法尔杉。",h="这个任务标志着部落术士学习召唤并奴役地狱犬旅程中最后的准备阶段。在帮助约拉·安尼森修复古老的“秘法会之书”后，修习者必须前往敌对领土夺取三根通道法杖，然后将这些组件带给位于棘齿城的斯坦哈德·法尔杉。",kw={"怒牙营地","龙喉氏族","地狱犬","约拉·安尼森","棘齿城","导能魔棒","斯坦哈德·法尔杉","秘法会之书","湿地"},ang={["class:Warlock"]="这项试炼考验你从敌对土地获取危险仪式试剂的决心，证明你拥有知识和胆识，能将掠食性的地狱犬束缚并为你所用。",["faction:Horde"]="湿地中的龙喉叛军仍然是萨尔部落的死敌，因此暴力夺回他们的通道法杖对部落的利益来说是一次双重胜利。",["race:Orc"]="击溃湿地中龙喉氏族的流氓成员，是对部落极力想要摆脱的黑暗、不知悔改之路的一次严厉提醒。",["race:Undead"]="约拉·安尼森在幽暗城的学术工作反映了被遗忘者术士剖析禁忌奥术文献以获取实际奥术霸权的传统。"},sec={{t="翻修过的书籍的秘密",b="在幽暗城，被遗忘者学者约拉·安尼森仔细检查了寻回的“秘法会之书”残页，拼凑出其中晦涩的篇章。在对这笔罕见的知识财富感到满意的同时，约拉也传达了斯坦哈德·法尔杉发来的紧急指示。若要束缚地狱犬这种恶魔掠食者，仅有原始知识是不够的：术士必须拥有精确的能量仪器，能够将狂暴的恶魔能量汇聚到一个束缚法阵中。"},{t="冒险前往湿地",b="斯坦哈德需要三根通道法杖，这是由龙喉氏族的叛军兽人携带的特殊导管。这些龙喉兽人远离部落的核心领地，盘踞在湿地潮湿沼泽中的怒牙营地废墟里。猎杀他们需要进入被敌对氏族残党统治的争夺中领土，这些残党不仅痛恨现代部落，也像屠杀联盟探险家一样残忍。"},{t="返回棘齿城",b="拿着找回的法杖并确保“翻修过的书籍”安全，术士跨海返回棘齿城上方斯坦哈德·法尔杉的塔楼。斯坦哈德带着冷酷的满意迎接了归来的施法者。召唤仪式的组件已组装完毕，这为对抗扭曲虚空未驯服野兽的危险意志考验铺平了道路。"}},faq={{q="这个任务的目的是什么？",a="这是部落术士学习如何召唤地狱犬任务链的第三步。它要求将修复后的“秘法会之书”和三根通道法杖交给棘齿城上方的斯坦哈德·法尔杉。",al={"为什么做这个任务","任务目的","秘法会之书有什么用"}},{q="约拉·安尼森是谁？",a="约拉·安尼森是一位驻扎在幽暗城魔法区的被遗忘者术士兼学者。他研究深奥的黑暗文献，通过拼凑像“秘法会之书”这样破碎的法术书来协助同行。",al={"约拉是谁","约拉·安尼森背景故事"}},{q="为什么需要通道法杖？",a="召唤并强迫地狱犬服从需要精确的形而上学控制。法杖作为聚焦导管，用于稳定和塑造召唤法阵，这样术士才能制服恶魔，而不是被它吞噬。",al={"为什么需要通道法杖","法杖用途"}},{q="这个任务中龙喉兽人在哪里？",a="龙喉氏族占据着湿地内的怒牙营地，这是一个位于卡兹莫丹、由联盟控制的领土。具体来说，他们的骸骨卫士携带了梦寐以求的通道法杖。",al={"去哪里找龙喉兽人","湿地龙喉位置","怒牙营地"}},{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉是一位与部落黑暗施法者结盟的有影响力的术士，他在贫瘠之地棘齿城地精港口上方悬崖的一座孤塔中进行研究。",al={"斯坦哈德是谁","斯坦哈德·法尔杉棘齿城"}},{q="完成这个任务后会发生什么？",a="完成这次交付直接进入“束缚”任务，斯坦哈德会指示术士绘制召唤法阵，并在魔法战斗中面对召唤出的地狱犬，从而驾驭这头野兽。",al={"接下来是什么","书籍任务后的下一个任务"}}},fp="17,208,33.368.0,25.304.0,17.280.1,34.167.0,21.220.0,34.198.0,52.137.0,22.164.0,41.162.1"}
P.entries["quest:1806"] = {n="正义试炼",s="在铁炉堡外乔丹·斯迪威尔的熔炉旁，你带来了打造圣骑士战锤所需的材料。这些材料采集自东部王国和卡利姆多各地，帮助一名学徒成为备受认可的圣光勇士。",h="在铁炉堡外乔丹·斯迪威尔的熔炉旁，你带来了打造圣骑士战锤所需的材料。这些材料采集自东部王国和卡利姆多各地，帮助一名学徒成为备受认可的圣光勇士。",kw={"伯施·维里甘","丹莫罗","熔炉","战锤","铁炉堡","乔丹·斯迪威尔","圣骑士","正义试炼","维里甘"},ang={["class:Paladin"]="身为圣骑士，你在遥远土地上的冒险为你赢得了维里甘之拳，一件为捍卫正义而铸的武器。",["profession:Blacksmithing"]="身为铁匠，你能看出乔丹·斯迪威尔如何凭借精湛技艺，赋予未经锻造的钢铁与回收的材料以神圣使命。",["race:Dwarf"]="身为矮人，你手中的战锤是为纪念伯施·维里甘而铸，他是一位受人敬重的矮人圣骑士，体现了卡兹莫丹的坚韧。"},sec={{t="铁匠的献礼",b="乔丹·斯迪威尔在铁炉堡大门外的熔炉旁劳作。他羡慕那些游历四方的圣骑士，也为能效力于他们的事业而自豪。你为他带来了从幽暗墓穴、沉没遗迹和危险矿井中收集的稀有材料。这位锻造大师用这些材料履行承诺，锻造出一件配得上真正守护者的武器。"},{t="伯施·维里甘的传承",b="乔丹·斯迪威尔将铸成的战锤命名为维里甘之拳，以纪念伯施·维里甘，那位受人敬重的矮人圣骑士，也是他的挚友。他代表自己和妻子，将这件神圣的武器交到一位年轻勇士手中。借助这件武器，他逝去挚友的英勇与遗志得以延续，继续抗击威胁艾泽拉斯的黑暗。"}},faq={{q="任务的这一步会发生什么？",a="乔丹·斯迪威尔在铁砧上加工你收集的部件，锤打熔炉中烧热的金属。完工后，他将铸成的武器交给你。",al={"正义试炼结局","乔丹锻造武器","维里甘过场动画"}},{q="伯施·维里甘是谁？",a="伯施·维里甘曾是一位受人敬重的矮人圣骑士，也是乔丹·斯迪威尔的挚友。乔丹以他的名字为新铸成的双手锤命名，纪念他对圣光的虔诚。",al={"维里甘是谁","维里甘之拳名字由来","伯施·维里甘"}},{q="锻造在何处进行？",a="乔丹·斯迪威尔在丹莫罗的皑皑雪峰间、铁炉堡宏伟的大门外锻造这把战锤。他的熔炉和铁砧就在那里。",al={"乔丹·斯迪威尔位置","熔炉在哪里","丹莫罗铁砧"}},{q="乔丹为什么需要来自世界各地的稀有材料？",a="乔丹·斯迪威尔需要来自世界各处险境的稀有材料，才能锻造出一件平衡性出众、能与神圣之力共鸣的武器。这些矿石、木材和宝石，是打造一把足以承受圣骑士神圣怒火的战锤所必需的。",al={"为何收集材料","正义试炼任务部件"}},{q="乔丹·斯迪威尔会亲自上阵作战吗？",a="乔丹·斯迪威尔是一名铁匠，并非游历四方的战士。他羡慕那些漫游大地的人，但为圣光的守护者打造武器，也让他找到了自豪与使命。",al={"乔丹是战士吗","乔丹·斯迪威尔作战"}},{q="获得这把战锤对圣骑士意味着什么？",a="获得这把战锤，标志着圣骑士漫长试炼的结束。这证明持有者具备勇气、毅力和神圣的信念，足以在艾泽拉斯最危险的角落捍卫圣光。",al={"维里甘之拳意义","圣骑士成人礼"}}},fx={["49955bc3"]={q="乔丹·斯迪威尔为什么想锻造这把战锤？",a="乔丹·斯迪威尔坦言，看到艾泽拉斯各地勇士的英勇事迹时，他会有一丝羡慕，因为他是铁匠，而非冒险者。用你收集的稀有材料锻造维里甘之拳，能让他直接帮助一位圣光的捍卫者，以自己不可或缺的方式为守护国土出力。",al={"乔丹·斯迪威尔的动机","为什么锻造武器","乔丹为什么锻造战锤"}}},fp="25,221,17.330.0,27.317.0,43.161.0,21.181.0,35.137.0,59.239.0,50.168.0,54.191.0"}
P.entries["quest:181"] = {n="仰望星空",s="维克托·安特拉斯在夜色镇制作的望远镜还缺最后一个部件。镜架已经搭好，但当地没有足够大的玻璃，无法制成图纸所需的透镜。",h="维克托·安特拉斯在夜色镇制作的望远镜还缺最后一个部件。镜架已经搭好，但当地没有足够大的玻璃，无法制成图纸所需的透镜。",kw={"齿轮","夜色镇","仰望星空","单片眼镜","望远镜","维克托·安特拉斯","沃古尔食人魔山","扎克乌尔"},ang={["faction:Alliance"]="身为联盟旅人，你能看到夜色镇在周围恐怖之物与野兽的威胁下顽强支撑。维克托对星辰的追寻，让人得以窥见平民百姓的坚韧。",["profession:Engineering"]="身为工程师，你能体会到，用一副巨大的食人魔单片眼镜来满足天文透镜的要求，是何等大胆的构想。",["race:Gnome"]="身为侏儒，你知道巧思能将意外发现的东西变成实用的零件。维克托的望远镜图纸需要一块取自食人魔单片眼镜的透镜。"},sec={{t="最后一个部件",b="维克托·安特拉斯正在夜色镇按照侏儒工程师考格·旋轴的图纸制作一架望远镜。他已经从当地的物资中收集到了黄铜管和坚固的支架，但这份设计需要一块尺寸格外大的聚焦透镜。暴风城商人带来的放大镜和光学零件都太小，因此维克托开始从常规材料之外寻找所需的部件。"},{t="食人魔的目镜",b="沃古尔食人魔山位于南部群山的阴影下，盘踞着大批充满敌意的食人魔。其中一个名叫扎克乌尔的食人魔戴着一副玻璃单片眼镜，大小足以用于维克托的望远镜。从扎克乌尔手中夺取这副眼镜，就能为维克托提供考格的图纸所需的透镜，让他完成望远镜，观测暮色森林幽暗树冠上方的天空。"}},faq={{q="维克托·安特拉斯是谁？",a="维克托·安特拉斯是一位天文学家兼学者，住在夜色镇山坡上的一间小屋里。尽管暮色森林笼罩在阴霾之下，他仍一心想要完成望远镜，研究星辰。",al={"维克托是谁","维克托·安特拉斯"}},{q="在哪里能找到扎克乌尔？",a="扎克乌尔位于暮色森林南部的沃古尔食人魔山。他在营地和相互连通的洞穴间游荡，周围都是戒备森严的食人魔领地。",al={"扎克乌尔位置","食人魔在哪里","食人魔单片眼镜位置"}},{q="食人魔为什么会有单片眼镜？",a="扎克乌尔戴着一副硕大的单片眼镜。这是这一带唯一足够大、能够满足考格的望远镜图纸要求的透镜。",al={"为什么用食人魔单片眼镜","食人魔的单片眼镜背景"}},{q="这台装置完成后会怎样？",a="有了这副单片眼镜，维克托就能为望远镜装上最后一块透镜。装置完成后，他就能重新研究这片阴郁森林上方的星辰。",al={"望远镜完成","任务结局"}},{q="望远镜是谁设计的？",a="望远镜由侏儒工程师考格设计。他的图纸需要专用零件、金属镜架，以及一块远大于普通矮人或侏儒眼镜镜片的透镜。",al={"考格图纸","谁制作了望远镜"}},{q="独自进入沃古尔食人魔山安全吗？",a="不安全。沃古尔食人魔山到处都是充满敌意的食人魔，他们成群巡逻，把守着狭窄的道路。独行的旅人若要深入其中寻找扎克乌尔，会面临重重危险。",al={"沃古尔难度","食人魔山安全吗"}}},fp="17,161,15.381.0,19.316.1,28.197.0,27.130.0,35.114.0,42.145.0,27.166.0,42.159.0"}
P.entries["quest:1818"] = {n="迪林格尔",s="在布瑞尔的恐惧之末旅店，奥斯蒂尔·德·蒙派遣战士为希尔瓦娜斯执行一项危险的任务。这道命令要求身强力壮的新兵前往村庄西端，向亡灵卫兵迪林格尔报到。",h="在布瑞尔的恐惧之末旅店，奥斯蒂尔·德·蒙派遣战士为希尔瓦娜斯执行一项危险的任务。这道命令要求身强力壮的新兵前往村庄西端，向亡灵卫兵迪林格尔报到。",kw={"奥斯蒂尔·德·蒙","布瑞尔","亡灵卫兵迪林格尔","与迪林格尔交谈","提瑞斯法林地","切割者奥拉格","幽暗城"},ang={["class:Warrior"]="亡灵卫兵指挥官重视战斗中的坚韧，因此迪林格尔的召唤将考验你在前线的战斗技巧。",["faction:Horde"]="响应幽暗城的防御号召，能加强部落在卡利姆多的盟友与新近加入的被遗忘者之间的团结。",["race:Undead"]="作为一名刚刚获得自由的被遗忘者，响应迪林格尔的召唤，是证明你忠于黑暗女王并决心保卫提瑞斯法的重要方式。"},sec={{t="前线的召唤",b="在布瑞尔的恐惧之末旅店，战士训练师奥斯蒂尔·德·蒙正在寻找愿意为黑暗女王效力的战士。当亡灵卫兵需要能干的人手时，他便将未经考验的新兵派往战场。亡灵卫兵迪林格尔负责布瑞尔西侧的安全，他为一项紧急任务请求派来一名精通武艺的人。"},{t="忠诚者的试炼",b="被遗忘者必须在提瑞斯法林地的前线上不断证明自身的武力优势。在布瑞尔墓地附近，迪林格尔负责应对当地的入侵。向他报到，将考验你的战斗技巧，以及你对新近建立的被遗忘者国度的忠诚。"}},faq={{q="是谁派我执行这项任务？",a="布瑞尔恐惧之末旅店的战士训练师奥斯蒂尔·德·蒙会挑选有潜力的士兵，派他们去协助亡灵卫兵迪林格尔。",al={"任务给予者","奥斯蒂尔·德·蒙","谁给予与迪林格尔交谈任务"}},{q="在哪里可以找到亡灵卫兵迪林格尔？",a="亡灵卫兵迪林格尔驻守在提瑞斯法林地的布瑞尔西侧，靠近墓地入口。",al={"迪林格尔位置","迪林格尔在哪里","寻找迪林格尔"}},{q="向迪林格尔报到的目的是什么？",a="迪林格尔需要一名身强力壮的勇士执行战斗任务，保卫布瑞尔，并证明自己对被遗忘者事业的忠诚。",al={"为什么要与迪林格尔交谈","迪林格尔任务目的"}},{q="迪林格尔准备了什么任务？",a="当你向亡灵卫兵迪林格尔报到时，他会交给你追杀切割者奥拉格的任务，此人是个危险的威胁。",al={"迪林格尔需要什么","迪林格尔后续任务"}},{q="部落的其他种族也会接到这道命令吗？",a="任何受到幽暗城官员信任的部落战士都可以接受这项任务，不过，它主要是为了在新兵保卫提瑞斯法林地时评估他们的战斗能力。",al={"是否仅限亡灵","兽人能否接受"}},{q="为什么战士训练师要派我去找迪林格尔？",a="奥斯蒂尔·德·蒙在布瑞尔的恐惧之末旅店训练战士。他会将刚具备作战能力的冒险者派往急需人手的亡灵卫兵指挥官那里。",al={"为什么从幽暗城开始","奥斯蒂尔·德·蒙的职责"}}},fp="20,190,22.325.0,20.240.0,29.140.0,40.106.0,46.126.0,45.116.1,40.169.0,48.148.0"}
P.entries["quest:1819"] = {n="切割者奥拉格",s="“斩杀者”乌拉格是提瑞斯法林地年轻被遗忘者战士的一项成人礼。亡灵卫兵迪林格尔会指派你前去释放并处决一名被囚禁在北部陵墓中的亡灵天灾战士，以此考验你的战斗意志，并赢得亡灵卫兵的尊重。",h="“斩杀者”乌拉格是提瑞斯法林地年轻被遗忘者战士的一项成人礼。亡灵卫兵迪林格尔会指派你前去释放并处决一名被囚禁在北部陵墓中的亡灵天灾战士，以此考验你的战斗意志，并赢得亡灵卫兵的尊重。",kw={"布瑞尔","亡灵卫兵迪林格尔","迪林格尔","陵墓","天灾","颅骨石","乌拉格","斩杀者乌拉格"},ang={["class:Warrior"]="这项试炼是早期被遗忘者战士的试炼场，考验你在面对一位强大的、被精神控制的天灾勇士时的勇气。",["race:Undead"]="乌拉格的命运展现了天灾控制下恐怖的现实，揭示了那些获得自由的被遗忘者与那些思想仍受巫妖王奴役的亡灵之间悲剧性的区别。"},sec={{t="一个被束缚的天灾奴仆",b="当亡灵天灾席卷洛丹伦时，被遗忘者捕获了一名自称为“斩杀者”乌拉格的独特亡灵战士。虽然乌拉格拥有清醒且理智的头脑，但他的精神仍无法摆脱巫妖王的精神奴役。为了了解天灾军团是如何束缚自由意志的，被遗忘者将他封印在布瑞尔北部的一座陵墓下，希望能斩断他精神上的枷锁。"},{t="处刑者的试炼",b="所有试图将乌拉格从巫妖王的精神控制中解救出来的努力都以失败告终。认识到真正的自由只有通过毁灭才能实现后，亡灵卫兵迪林格尔将这名俘虏重新利用起来，作为新晋被遗忘者战士的一项战斗试炼。通过扰动墓穴外的颅骨石机关，战士可以打破保护结界，释放乌拉格，并用斧刃送他解脱。"}},faq={{q="谁是“斩杀者”乌拉格？",a="“斩杀者”乌拉格是在天灾军团入侵提瑞斯法林地期间被被遗忘者捕获的一名亡灵战士。他比较特殊，虽然保留了自由的意识和身份，但仍完全受控于巫妖王的精神命令。",al={"乌拉格背景故事","谁是乌拉格","斩杀者乌拉格的身份"}},{q="为什么乌拉格被囚禁在陵墓下？",a="被遗忘者的学者和士兵用魔法封印将他囚禁在下方，以研究巫妖王的精神控制是如何运作的。他们曾希望找到一种方法来斩断束缚他的精神链接，但实验最终失败了。",al={"为什么囚禁乌拉格","提瑞斯法陵墓囚犯"}},{q="为什么亡灵卫兵现在要处决乌拉格？",a="在承认无法打破巫妖王对乌拉格的控制后，被遗忘者认为死亡是唯一的慈悲。亡灵卫兵迪林格尔决定将这次处决作为对有抱负的战士进行战斗勇气和纪律测试的手段。",al={"为什么要杀死乌拉格","斩杀乌拉格的原因"}},{q="如何召唤乌拉格？",a="他被关押在布瑞尔正北部的一座陵墓下。与墓穴附近的颅骨石互动会解除束缚他的魔法封印，使他复苏并展开攻击。",al={"如何召唤乌拉格","乌拉格在哪里","乌拉格颅骨石"}},{q="谁指派了杀死乌拉格的任务？",a="驻守在提瑞斯法林地布瑞尔西侧道路上的亡灵卫兵迪林格尔，会专门将此任务指派给寻求进一步指导的被遗忘者战士。",al={"乌拉格任务发放者","谁派我去对付乌拉格"}},{q="打败乌拉格之后会发生什么？",a="在确认乌拉格被击败后，亡灵卫兵迪林格尔会认可你的英勇，并让你去找布瑞尔的库勒曼·法席恩，以继续你的训练。",al={"乌拉格之后","乌拉格任务后续"}}},fp="16,162,22.371.0,23.315.0,24.188.0,44.142.0,44.196.0,21.142.0,33.146.0,36.146.0"}
P.entries["quest:182"] = {n="巨魔洞穴",s="在寒脊山谷南部，格瑞林·白须派你去对付一群在洞穴中安家的霜鬃幼崽。他们的营地日渐壮大，威胁着附近的矮人家园。",h="在寒脊山谷南部，格瑞林·白须派你去对付一群在洞穴中安家的霜鬃幼崽。他们的营地日渐壮大，威胁着附近的矮人家园。",kw={"寒脊山谷","丹莫罗","霜鬃","格瑞林·白须","穴居人","巨魔","幼崽"},ang={["class:Hunter"]="身为猎人，你可以将南部洞穴周围的峭壁当作严酷的试炼场，从山间高处驱出敌对的猎物。",["race:Dwarf"]="身为铜须矮人，当你拿起武器对抗霜鬃战帮时，你面对的是边境的威胁，也是一场古老的山地世仇。",["race:Gnome"]="身为在诺莫瑞根陷落后栖身丹莫罗的侏儒，你可以凭借智慧和武器，帮助收留你的矮人应对周围的威胁。"},sec={{t="寒风中的哨眼",b="格瑞林在一处峭壁上监视着冰封的山谷，铁炉堡的士兵则在雪原各处与穴居人交战。他和兄弟森内尔奉山区当局之命来到这里，查明当地的冰巨魔是否威胁着腹地。如今，格瑞林独自守望，追踪他们在南部各条通路上的动向。"},{t="先发制人",b="格瑞林发现，当地的霜鬃氏族正在寒脊山谷南部山脊的一处深邃洞穴中安家。他认为全面动员会浪费矮人的兵力，于是雇用有能力的当地志愿者，去消灭那些好斗的幼崽。削减这些年轻战士的人数，或许能在霜鬃对附近矮人家园发动有组织的袭击之前，打乱他们的营地部署。"}},faq={{q="铁炉堡为什么不派正规军来对付这些巨魔？",a="穴居人突然大举入侵丹莫罗各地，造成了严重破坏，铁炉堡参议院和军方已疲于应付。格瑞林·白须这样的斥候便雇用独立冒险者，处理巨魔战帮等较小的威胁。",al={"为什么没有矮人大军","卫兵在哪里","为什么雇用冒险者"}},{q="霜鬃巨魔是什么人？",a="霜鬃是丹莫罗严寒群峰中的一个土著冰巨魔部族。为了猎场、领地和古老的山间通道，他们长期与铜须矮人及巡山人发生冲突。",al={"霜鬃氏族","丹莫罗巨魔","霜鬃是什么人"}},{q="巨魔洞穴在哪里？",a="洞穴位于寒脊山谷南部的山脊上，在格瑞林·白须的观察营地以南。",al={"巨魔洞穴位置","洞穴在哪里","幼崽在哪里"}},{q="格瑞林·白须是谁？",a="格瑞林·白须是驻守寒脊山谷的一名铁炉堡斥候。他的兄弟森内尔负责侦察丹莫罗的其他地区，格瑞林则追踪敌对巨魔群体的动向，并向矮人领袖汇报。",al={"格瑞林","任务给予者","白须"}},{q="格瑞林为什么专门对付霜鬃幼崽？",a="格瑞林盯上霜鬃幼崽，是因为他们在寒脊山谷南部的聚居地正不断壮大，其中还有尚未成年的战士。杀死这些年轻战士，或许能阻止这伙巨魔壮大到足以威胁矮人补给线的地步。",al={"为什么是幼崽","为什么对付年幼巨魔"}},{q="清剿洞穴之后会发生什么？",a="你清剿洞穴后，巨魔会在夜间展开报复。他们袭击格瑞林的营地，偷走他的私人野外日志，你必须深入他们的巢穴将其夺回。",al={"接下来会怎样","巨魔洞穴后续"}}},fx={["9e422164"]={q="格瑞林·白须为什么想要除掉那些巨魔？",a="格瑞林和他的兄弟森内尔奉命前往丹莫罗各地，评估当地的霜鬃巨魔是否对国土构成严重威胁。铁炉堡的参议院已经被其他地方的穴居人暴动弄得焦头烂额，因此格瑞林希望在这群巨魔的集结演变成需要正规军介入的危机之前，将其扼杀在萌芽中。",al={"为什么杀死巨魔","格瑞林·白须的动机","为什么清理巨魔洞穴"}}},fp="14,158,16.322.0,19.361.0,70.225.0,29.210.0,32.115.0,25.201.0,53.251.0,36.171.1"}
P.entries["quest:1820"] = {n="库勒曼",s="在布瑞尔，亡灵卫兵迪林格尔派久经考验的战士去帮助库勒曼·法席恩。在酒馆与他会面，将牵出一桩与阿加曼德家族旧地有关的私事。",h="在布瑞尔，亡灵卫兵迪林格尔派久经考验的战士去帮助库勒曼·法席恩。在酒馆与他会面，将牵出一桩与阿加曼德家族旧地有关的私事。",kw={"阿加曼德","布瑞尔","库勒曼·法席恩","亡灵卫兵迪林格尔","被遗忘者","恐惧之末旅店","部落","提瑞斯法林地"},ang={["faction:Horde"]="作为协助守卫洛丹伦的部落旅人，结识布瑞尔的镇民，能让你在提瑞斯法林地各处开展工作时有个立足之地。",["race:Undead"]="许多被遗忘者在效忠黑暗女王的同时，也背负着私人恩怨。库勒曼·法席恩的委托表明，个人的失落与提瑞斯法的防务紧密相连。"},sec={{t="卫兵的口信",b="你帮助遏制了布瑞尔附近的严重威胁，其中就有锋利的切肉刀奥拉格。因此，亡灵卫兵迪林格尔信任你的实力。他守望着通往镇内的道路，挑选能承担日常巡逻之外任务的人。见你已准备就绪，他便指引你去找那些需要专门援助的人。"},{t="私人恩怨",b="提瑞斯法林地的战斗，并非每一场都始于幽暗城的命令。洛丹伦幸存的亡灵仍对失去的土地、家人与财富心怀怨恨。库勒曼·法席恩在恐惧之末旅店等待一位战士，愿意出手打击阿加曼德磨坊等旧聚落附近的威胁。"}},faq={{q="在哪里能找到库勒曼·法席恩？",a="库勒曼·法席恩在提瑞斯法林地布瑞尔东侧的恐惧之末旅店里等候。",al={"库勒曼·法席恩位置","库勒曼·法席恩在哪里","布瑞尔寻找法席恩"}},{q="是谁派你去与库勒曼交谈？",a="亡灵卫兵迪林格尔守卫着通往布瑞尔的道路。你证明自己的战斗本领后，他便派你去找库勒曼。",al={"谁给予与库勒曼交谈","迪林格尔任务"}},{q="库勒曼·法席恩有什么差事？",a="库勒曼·法席恩正在寻找一位能干的战士，向被遗忘者的敌人复仇。阿加曼德家族旧产业周边的事务也牵涉其中。",al={"库勒曼想要什么","库勒曼·法席恩任务"}},{q="接到这项任务前需要满足哪些条件？",a="你击败锋利的切肉刀奥拉格，向被遗忘者证明自己的忠诚与战斗本领后，亡灵卫兵迪林格尔便会引荐你去找库勒曼。",al={"与库勒曼交谈前置条件","奥拉格条件"}},{q="这项任务会直接给予丰厚奖励吗？",a="在酒馆与法席恩交谈，就能接下他的私人委托。这次会面本身不会带来丰厚的装备或金钱奖励。",al={"与库勒曼交谈奖励","是否值得做"}},{q="恐惧之末旅店是什么地方？",a="恐惧之末旅店是布瑞尔的主要旅店，当地亡灵在此聚集、休憩。这里也是洽谈私人委托的非正式会面场所。",al={"布瑞尔酒馆","恐惧之末旅店"}}},fp="18,175,21.290.0,18.327.0,34.97.0,33.109.0,45.140.0,57.133.0,53.136.0,32.143.0"}
P.entries["quest:1821"] = {n="阿加曼德家传武器",s="在阿加曼德磨坊，库勒曼·法席恩派你前往家族墓穴，夺取传家宝。他将自己的死归咎于阿加曼德家族，想要夺走他们祖传的武器。",h="在阿加曼德磨坊，库勒曼·法席恩派你前往家族墓穴，夺取传家宝。他将自己的死归咎于阿加曼德家族，想要夺走他们祖传的武器。",kw={"阿加曼德家族墓穴","阿加曼德传家宝","阿加曼德磨坊","库勒曼·法席恩","祖传武器","天灾军团","提瑞斯法林地"},ang={["class:Rogue"]="身为潜行者，你知道如何潜行绕过潜伏的食尸鬼，从守卫森严的墓室中取走古老的武器。",["faction:Horde"]="身为部落的一员，你帮助削弱Scourge对提瑞斯法林地北部的控制，让旅人在这片土地上行走时更加安全。",["race:Undead"]="身为亡灵，你知道被遗忘者生前的仇怨，即使在死后也可能久久不散。"},sec={{t="仆人的深仇",b="在第三次大战摧毁洛丹伦之前，库勒曼·法席恩曾在提瑞斯法林地的磨坊里，为富有的阿加曼德家族效力。法席恩将自己的死归咎于昔日的主人。如今，他已被复生为亡灵，成为被遗忘者的一员，阿加曼德家族的衰败让他满怀怨恨的心感到快慰。这个曾经骄傲的家族，如今已沦为受巫妖王奴役的无脑爪牙。"},{t="亵渎墓穴",b="法席恩派你前往磨坊北部峭壁下方的阿加曼德家族墓穴。不安的死者与盘踞不去的天灾军团在石砌的厅堂中游荡。他要你夺取四件遗物：阿加曼德家传长剑、阿加曼德家传战斧、阿加曼德家传匕首和阿加曼德家传钉锤。失去这些遗物，这个家族仅存的荣耀也将荡然无存。"}},faq={{q="库勒曼·法席恩生前是什么人？",a="在天灾军团入侵洛丹伦之前，库勒曼·法席恩曾在阿加曼德磨坊为富有的阿加曼德家族效力。他死于那场浩劫，并将自己的死归咎于昔日的主人，即使化为亡灵，也依然怀着这份怨恨。",al={"库勒曼·法席恩是谁","库勒曼的身世","法席恩的过去"}},{q="库勒曼·法席恩为什么想要那些传家宝？",a="法席恩想向昔日的主人复仇。他想夺走他们祖传的长剑、战斧、匕首和钉锤，让这个衰败的家族失去最后的荣耀与念想。",al={"为何偷取传家宝","库勒曼的动机","为何夺取武器"}},{q="阿加曼德家族遭遇了什么？",a="天灾军团席卷提瑞斯法林地时，阿加曼德家族悉数丧命。他们被复生为受巫妖王控制的无脑亡灵奴仆，在破败的磨坊和墓穴中游荡。",al={"阿加曼德的命运","阿加曼德家族还活着吗","阿加曼德家族如今是什么"}},{q="阿加曼德家族墓穴在哪里？",a="阿加曼德家族墓穴位于阿加曼德磨坊北端的岩石峭壁中，俯瞰着提瑞斯法林地北部遭到瘟疫侵蚀的农庄。",al={"墓穴位置","墓穴在哪里","阿加曼德墓穴地图"}},{q="墓穴里存放着哪些武器？",a="墓穴里存放着四件祖传武器：阿加曼德家传长剑、阿加曼德家传战斧、阿加曼德家传匕首和阿加曼德家传钉锤。",al={"哪些传家宝","四件传家宝","阿加曼德的武器"}},{q="既然双方都是亡灵，被遗忘者为什么还要攻击阿加曼德家族？",a="被遗忘者拥有自由意志，为自身的生存而战。化为亡灵的阿加曼德家族依然是毫无心智的天灾军团奴隶，侍奉着被遗忘者所憎恨的巫妖王。",al={"亡灵对抗亡灵","为何攻击阿加曼德家族","被遗忘者与天灾军团的冲突"}}},fp="17,153,25.355.0,21.292.0,33.208.0,45.158.0,36.182.0,42.149.0,39.145.0,63.162.0"}
P.entries["quest:1824"] = {n="巨人旷野的试炼",s="在陶拉祖营地，鲁迦·狂暴图腾派遣战士学徒南下，迎战陌生的敌人。他们必须在巨人旷野杀死 异种蝎，并在半小时内带回几根仍在抽动的触角。",h="在陶拉祖营地，鲁迦·狂暴图腾派遣战士学徒南下，迎战陌生的敌人。他们必须在巨人旷野杀死 异种蝎，并在半小时内带回几根仍在抽动的触角。",kw={"贫瘠之地","陶拉祖营地","巨人旷野","鲁迦·狂暴图腾","异种蝎","颤抖的触角","战士试炼"},ang={["class:Warrior"]="身为战士，你会在二十级左右迎来这场成长试炼。它考验你能多快击败成群的敌人，以及能否承受严格时限带来的压力。",["faction:Horde"]="身为部落的一员，你要面对贫瘠之地南部不断扩张的 silithid。这些试炼也在收集有关这一悄然蔓延的威胁的情报。",["race:Tauren"]="身为牛头人守卫，你要直面巨人旷野遭到的亵渎，以及那里违背自然、侵占土地的虫巢，帮助保护陶拉祖营地周围的猎场。"},sec={{t="速度与钢铁的考验",b="在陶拉祖营地，鲁迦·狂暴图腾要求成长中的战士迎战陌生的对手，证明自己的实力。部落的战士训练师考验的不只是战斗技巧：学徒必须杀死这些生物，并在半小时内带回新鲜的触角。穿越贫瘠之地南部的奔跑考验着他们的速度与决心，而抵达陶拉祖时，触角必须仍在抽动。"},{t="不速之客",b="巨人旷野上，巨大的肋骨化石下方隆起了 异种蝎 的虫巢。这些四处爬行的怪异昆虫最近才出现在贫瘠之地，惊扰了守望草原的牛头人猎手和萨满祭司。鲁迦 说，它们的出现对卡利姆多而言是不祥之兆。这场试炼既考验年轻战士的战斗本能，也为这片土地上日益壮大的威胁收集情报。"}},faq={{q="为什么收集触角有时间限制？",a="鲁迦·狂暴图腾要求战士将触角带回陶拉祖营地时，它们必须仍在抽动，因此只给他们三十分钟完成猎杀并返回。新鲜的触角证明学徒是在正面交战中杀死了一只 异种虫，而不是从尸体上捡来的。",al={"为何限时","抽动的触角时限","多少时间"}},{q="巨人旷野生活着什么生物？",a="巨人旷野生活着怪异而凶猛的 异种虫 掘地虫。它们在古老的化石下挖出了巨大的土丘和虫巢，扰乱了当地的生态，也引起了部落的警觉。",al={"这些虫子是什么","巨人旷野怪物","异种蝎 是什么"}},{q="鲁迦·狂暴图腾是谁？",a="鲁迦·狂暴图腾是贫瘠之地南部陶拉祖营地的一位牛头人战士训练师。他负责为寻求晋升的部落战士主持试炼，考验他们的技巧、韧性和速度。",al={"鲁迦","任务发布者","鲁迦·狂暴图腾背景故事"}},{q="巨人旷野位于哪里？",a="巨人旷野位于陶拉祖营地正南方，就在通往千针石林的南部隘口前的道路旁。高耸的肋骨残骸和 异种虫 土丘是这片旷野的标志。",al={"巨人旷野在哪里","巨人旷野位置","虫子在哪里"}},{q="这条训练任务线接下来通往哪里？",a="战士及时带回仍在抽动的触角后，鲁迦 会派他们去找索恩格瑞姆·火眼，一位住在十字路口以东山丘上的年长兽人铁匠。索恩格瑞姆会为证明了自己的战士打造护甲。",al={"下一个任务","后续是什么","战士任务线后续"}},{q="牛头人为什么担忧这些昆虫？",a="鲁迦 说，异种虫 是最近才来到贫瘠之地的非自然生物，它们的到来对这片土地而言是不祥之兆。他怀疑它们肆意掘地、不断扩张的举动，预示着沙地下潜藏着更大的危险。",al={"牛头人为何在意","昆虫预兆","异种蝎 威胁"}}},fp="28,195,25.345.0,19.367.0,42.255.0,43.184.0,22.200.0,37.185.0,41.211.0,47.197.0"}
P.entries["quest:1825"] = {n="和索恩格瑞姆交谈",s="巨人旷野的试炼结束后，索恩格瑞姆·火眼召集战士前往他在贫瘠之地的营地。这位兽人铁匠为证明了自身勇气的战士量身打造护甲，并派他们收集制作野蛮护甲的材料。",h="巨人旷野的试炼结束后，索恩格瑞姆·火眼召集战士前往他在贫瘠之地的营地。这位兽人铁匠为证明了自身勇气的战士量身打造护甲，并派他们收集制作野蛮护甲的材料。",kw={"贫瘠之地","野蛮护甲","十字路口","火眼","怒图腾","鲁迦","索恩格瑞姆","战士"},ang={["class:Warrior"]="身为战士，你已从初出茅庐的斗士成长为备受认可的勇士，赢得了量身锻造护甲的资格。",["faction:Horde"]="身为部落的一员，你可以信赖部落的铸甲师，他们会为最勇猛的守卫者提供装备，酬谢他们在边疆立下的功绩。",["profession:Blacksmithing"]="身为铁匠，你能看出索恩格瑞姆·火眼秉持着兽人的传统信念：大师打造的护甲必须通过战斗试炼来赢取，不能用钱币购买。"},sec={{t="铁匠的召唤",b="战士们向鲁迦·狂暴图腾证明了自己的耐力与战斗技巧后，试炼的消息传到了索恩格瑞姆·火眼耳中。他的营地坐落在十字路口以东的一道山脊上。索恩格瑞姆想为他们锻造一套出众的战斗锁甲。"},{t="大师的标准",b="索恩格瑞姆·火眼只为达到他严苛标准的战士开炉锻造。他要求钢铁的品质配得上穿戴者的意志。能来到他的营地，意味着一名战士已超越了基础民兵训练，能够承担走遍卡利姆多收集稀有材料的艰苦任务。"}},faq={{q="索恩格瑞姆·火眼是谁？",a="索恩格瑞姆·火眼是一位著名的兽人铁匠，营地坐落在贫瘠之地十字路口以东的一道岩石山脊上。他为通过危险试炼证明自身勇气的部落战士量身打造护甲。",al={"索恩格瑞姆 是谁","索恩格瑞姆 的故事","索恩格瑞姆·火眼"}},{q="鲁迦·狂暴图腾为什么派我去找他？",a="鲁迦·狂暴图腾派你去找索恩格瑞姆，是因为你在贫瘠之地南部的异种虫威胁下活了下来，基础试炼已不足以考验你。这位铁匠为你打造专用护甲，以表彰你为部落效力。",al={"为什么与 索恩格瑞姆 交谈","鲁迦 派遣的原因"}},{q="在哪里能找到索恩格瑞姆的营地？",a="索恩格瑞姆的营地位于贫瘠之地十字路口以东的高耸峭壁上。",al={"索恩格瑞姆 在哪里","索恩格瑞姆 的位置","寻找索恩格瑞姆·火眼"}},{q="与索恩格瑞姆交谈后会发生什么？",a="与索恩格瑞姆交谈后，制作野蛮护甲的工作便开始了。你要远赴各地，收集 烟雾铁锭 和 铁锭 等材料，用于量身打造一件锁甲。",al={"索恩格瑞姆 之后的任务","索恩格瑞姆 想要什么"}},{q="所有职业都能接取这个任务吗？",a="不能。只有部落战士才能承担这项护甲制作任务。",al={"非战士能否接取","是否仅限战士"}},{q="这次会面之前需要完成什么试炼？",a="在与索恩格瑞姆见面之前，你要前往贫瘠之地南部，完成巨人旷野的试炼。收集抽搐的异种虫触角能证明你在战斗中的耐力。",al={"前置任务","此前完成了什么"}}},fx={["2df90612"]={q="鲁迦·狂暴图腾为什么派你去，而不是亲自前往？",a="鲁迦·狂暴图腾在陶拉祖营地负责训练和考验部落中崭露头角的战士。索恩格瑞姆·火眼听闻你在贫瘠之地的英勇事迹和历练后，特地托人来找你。鲁迦只是转达这份召唤，让你领取一套按你的身形打造的护甲。",al={"鲁迦为什么派我去","鲁迦·狂暴图腾为什么找我","鲁迦为什么需要我"}}},fp="20,226,21.244.0,19.287.0,26.204.0,39.207.0,34.77.0,43.186.0,39.54.0,44.173.0"}
P.entries["quest:183"] = {n="猎杀野猪",s="在寒脊山谷，塔林·锐眼请年轻的新兵减少威胁山路的峭壁野猪。这样，老练的猎人就能安心追踪猎物。",h="在寒脊山谷，塔林·锐眼请年轻的新兵减少威胁山路的峭壁野猪。这样，老练的猎人就能安心追踪猎物。",kw={"安威玛尔","野猪猎人","寒脊山谷","峭壁野猪","丹莫罗","狩猎","塔林·锐眼"},ang={["class:Hunter"]="身为猎人，你可以遵循塔林·锐眼朴实的追猎之道：瞄准目标，尊重野兽，在猎物变得凶猛时清理灌木丛。",["race:Dwarf"]="在山中生活，就得与凶猛的野生动物共享这片土地。对年轻的矮人而言，减少安威玛尔周围凶猛的crag boars，是熔炉之外的一场成人试炼。",["race:Gnome"]="身为刚从诺莫瑞根抵达此地的侏儒难民，面对丹莫罗凶猛的野猪，是适应崎岖矮人山地生活的艰难第一课。"},sec={{t="拥挤的山谷",b="寒脊山谷为年轻的巡山人和铁炉堡的学者提供了一处安静、安全的训练场所。严冬期间，小型峭壁野猪在山谷各处大量繁殖。如今，它们的袭击威胁着雪路上的每一个人。"},{t="雪地中的维护",b="狩猎为矮人提供肉食、兽皮和野外历练的机会。当猎物数量过多，见人就攻击时，适量捕杀便能恢复平衡。年轻的冒险者通过减少山谷坡地上的峭壁野猪，证明自己已经做好了战斗准备。当地猎人也能腾出空间追踪猎物，不再疲于招架。"}},faq={{q="塔林·锐眼是谁？",a="塔林·锐眼是一名矮人猎人，驻扎在寒脊山谷的安威玛尔附近。他在雪地里追踪猎物，并教导初出茅庐的冒险者如何对付凶猛的野兽。",al={"塔林·锐眼","猎杀野猪任务由谁发布","猎杀野猪任务发布者"}},{q="为什么峭壁野猪会造成这么大的麻烦？",a="寒脊山谷的小型峭壁野猪数量异常增多，而且会无故发起攻击。庞大的数量让当地居民出行和狩猎都变得危险。",al={"为什么要杀野猪","寒脊山谷野猪问题","野猪为什么危险"}},{q="在哪里能找到峭壁野猪？",a="小型峭壁野猪出没于安威玛尔周围开阔的雪原和稀疏的林地，遍布寒脊山谷。",al={"野猪在哪里","峭壁野猪位置","小型峭壁野猪地图"}},{q="这个任务与山谷中更大的威胁有关吗？",a="没有。穴居人侵扰着矮人的哨站，但峭壁野猪只是当地的野生动物问题。减少它们的数量能让小路更安全，也让塔林安心狩猎。",al={"有后续任务吗","猎杀野猪任务链","野猪背后的故事"}},{q="峭壁野猪为什么能适应丹莫罗？",a="峭壁野猪是一种皮糙肉厚的强壮野猪，能够忍受丹莫罗的严寒。凶悍的性情和锋利的獠牙帮助它们翻开冻土觅食，也能抵御山中的捕食者。",al={"峭壁野猪背景故事","矮人与野猪","丹莫罗野生动物"}},{q="塔林·锐眼为什么不亲自猎杀这些野猪？",a="塔林说，这些凶猛的野猪让他的狩猎变得危险，令他苦恼。他请途经安威玛尔、跃跃欲试的新人减少它们的数量，好让自己恢复平日的追猎生活。",al={"塔林为什么需要帮助","塔林懒惰","塔林为什么不能猎杀它们"}}},fx={aa61ef91={q="塔林·锐眼为什么要减少小型峭壁野猪的数量？",a="塔林·锐眼认为猎杀野猪是一项不错的消遣，但寒脊山谷泛滥成灾的小型峭壁野猪已经毁了他的乐趣。它们生性凶猛，数量暴增，让他每天的狩猎变得危机四伏，毫无悠闲可言。消灭十二头这样的野兽，就能让山谷恢复几分安宁，使他可以享受狩猎，而不必时时遭到成群野猪的围攻。",al={"为什么杀野猪","塔林·锐眼的动机","塔林·锐眼为什么要杀野猪"}},cf0c4f7e={q="小型峭壁野猪是什么，为什么会出现在寒脊山谷？",a="小型峭壁野猪是丹莫罗土生土长的顽强野猪，天生皮糙肉厚、性情凶猛，能够在严寒的山地生存。寒脊山谷积雪覆盖的山麓为它们提供了充足的食物，但最近它们的数量急剧增长，已经四处游荡，凶猛地冲向任何靠近的生物。",al={"峭壁野猪是什么","野猪为什么在这里","小型峭壁野猪的背景"}}},fp="15,143,16.234.0,17.295.0,21.165.0,38.164.0,34.116.0,57.168.0,43.204.0,49.186.0"}
P.entries["quest:1838"] = {n="野蛮护甲",s="一名身处贫瘠之地北部的战士正面临索恩格瑞姆·火眼的考验。这位近乎失明的铁匠派遣身经百战的部落战士远赴各地，寻找稀有材料和冶炼助剂。集齐他卷轴上列出的材料，便能开始打造一整套残暴的战甲。",h="一名身处贫瘠之地北部的战士正面临索恩格瑞姆·火眼的考验。这位近乎失明的铁匠派遣身经百战的部落战士远赴各地，寻找稀有材料和冶炼助剂。集齐他卷轴上列出的材料，便能开始打造一整套残暴的战甲。",kw={"贫瘠之地","野蛮护甲","野蛮锁甲","燃素","蓝铜粉","烟雾铁锭","索恩格瑞姆·火眼","战士任务"},ang={["class:Warrior"]="身为部落战士，你要跨越多片大陆，证明自己的勇气与耐力，赢得量身锻造的战甲。",["faction:Horde"]="身为部落的一员，你会看到兽人、牛头人、巨魔和被遗忘者铁匠将各自独特的工艺传统融入同一套战甲。",["profession:Blacksmithing"]="身为铁匠，你可以了解索恩格瑞姆的卷轴如何将烟熏铁、蓝铜粉和燃素结合起来，改进普通铁的冶炼工艺。"},sec={{t="大师的召唤",b="在贫瘠之地北部，索恩格瑞姆·火眼留意着战争的消息。这位经验丰富的兽人铁匠视力日渐衰退，但锻造技艺依然无人能及。他听闻有一名战士，力量与勇气远超寻常士兵。索恩格瑞姆决意打造一副锁甲，让它能经受住卡利姆多和东部王国最激烈的战斗。"},{t="横跨大陆的搜寻",b="索恩格瑞姆的护甲需要的远不止普通矿石。借着火光，他用日渐衰退的双眼辨认笔迹，在卷轴上为整套护甲的核心胸甲写下详尽的要求。所需材料包括精炼铁、穴居狗头人携带的烟熏铁锭、由海对岸矿工加工的蓝铜粉，以及一瓶性质不稳定的燃素。只有准备好远赴各地接受试炼的战士，才能集齐这些材料。"},{t="落下第一锤",b="索恩格瑞姆所需的稀有材料，只是一项更大工程的开端。材料送达后，他便点燃熔炉，锻造野蛮锁甲。老铁匠明白，单凭自己无法完成如此庞大的制甲工程。整套护甲还需要部落其他种族的能工巧匠参与：一位打造头盔的牛头人、一位制作护手的巨魔，以及一位锻造胫甲的亡灵，他们分散在各片大陆上。"}},faq={{q="索恩格瑞姆·火眼是谁？",a="索恩格瑞姆·火眼是一位经验丰富的兽人铁匠，住在一座俯瞰贫瘠之地北部的山丘上。尽管视力日渐衰退，他在铁砧前的直觉依然敏锐，为以勇武闻名的部落战士量身打造强大的战斗锁甲。",al={"索恩格瑞姆是谁","索恩格瑞姆·火眼的故事","索恩格瑞姆的过往"}},{q="野蛮护甲是什么？",a="野蛮护甲是一套为身经百战的部落战士锻造的战斗锁甲。部落铁匠合力施展各自的技艺来打造它，而每一件护甲都需要踏上危险的旅程，寻找稀有的炼金试剂、提纯矿石和古老技法。",al={"野蛮护甲是什么","野蛮护甲套装的故事","战士护甲任务线"}},{q="索恩格瑞姆为什么需要如此特殊的材料？",a="索恩格瑞姆需要特殊材料，是因为普通铁太脆，无法承受前线勇士所面对的沉重打击。他使用蓝铜粉、烟熏铁锭和性质不稳定的燃素作为熔剂与淬火助剂，增强金属的韧性和强度。",al={"为什么需要蓝铜粉","为什么需要燃素","试剂有什么用途"}},{q="整套护甲都是索恩格瑞姆亲手锻造的吗？",a="不是。索恩格瑞姆锻造核心的锁甲上衣，其他部落铁匠则制作配套的头盔、护手和护腿。他们包括奥姆·石蹄、尤拉莱克和维罗拉·奈特雷。",al={"全套都是索恩格瑞姆打造的吗","谁打造野蛮护甲的各个部件"}},{q="这条任务线接下来通向何处？",a="这场试炼最终促成野蛮锁甲的锻造，并让战士得以前往雷霆崖、森金村和幽暗城，向那里的铁匠求助，打造其余的残暴战斗锁甲。",al={"野蛮护甲之后是什么","野蛮护甲后续"}},{q="战士为什么必须远行，才能找到这些材料？",a="这段旅程考验着战士的坚韧和应变能力。要证明自己配得上大师锻造的护甲，战士必须穿越敌境，深入危险的矿洞，收集常人难以取得的材料。",al={"为什么要去东部王国","为什么需要这么多材料"}}},fp="12,277,18.352.0,26.396.0,30.377.1,26.247.0,21.225.0,49.278.0,44.174.1,38.183.1,61.213.0"}
P.entries["quest:1839"] = {n="尤拉莱克和野蛮护手",s="索恩格瑞姆·火眼派你从贫瘠之地前往森金村，寻求打造野蛮护手。在那里，黑暗之矛工匠尤拉莱克会为你锻造这双护手。",h="索恩格瑞姆·火眼派你从贫瘠之地前往森金村，寻求打造野蛮护手。在那里，黑暗之矛工匠尤拉莱克会为你锻造这双护手。",kw={"野蛮护手","黑暗之矛","杜隆塔尔","森金村","贫瘠之地","索恩格瑞姆·火眼","尤拉莱克","战士"},ang={["class:Warrior"]="身为部落战士，集齐野蛮护甲标志着你正迈向成为一名身经百战的前线勇士。",["faction:Horde"]="身为部落的一员，你见证贫瘠之地的兽人铁匠与杜隆塔尔的巨魔铁匠携手合作，让萨尔年轻的联盟更加紧密。",["race:Troll"]="身为巨魔，尤拉莱克的工作向你展示了黑暗之矛的锻造技艺与对诸灵的感应如何为部落的战事提供助力。"},sec={{t="前往海岸",b="你在贫瘠之地证明了自己的勇气，并开始收集野蛮护甲套装后，索恩格瑞姆·火眼派你向东进发。这位经验丰富的兽人铁匠依靠遍布部落领地的能工巧匠，而非在自己的山间居所锻造每一件护甲。为了打造厚重的锁甲护手，他指引你前往杜隆塔尔南部多岩的海岸。"},{t="洛阿神灵 的目光",b="在森金村，巨魔护甲匠尤拉莱克与黑暗之矛同胞一起劳作。索恩格瑞姆已经向他讲述了你的事迹，而尤拉莱克说，诸灵一直注视着你在战斗中取得的胜利。对于一名正努力跻身部落精锐之列的战士而言，精湛的工艺与诸灵的认可相辅相成。"}},faq={{q="谁提供尤拉莱克与野蛮护手任务？",a="在贫瘠之地群山之巅的兽人护甲匠索恩格瑞姆·火眼会交给你这项任务。",al={"任务给予者","谁开启尤拉莱克与 野蛮护手 任务","索恩格瑞姆·火眼 任务"}},{q="在哪里可以找到尤拉莱克？",a="你可以在杜隆塔尔南部海岸的森金村找到尤拉莱克。",al={"尤拉莱克位置","尤拉莱克在哪里","尤拉莱克 森金村"}},{q="野蛮护甲套装是什么？",a="野蛮护甲是为三十级左右、久经沙场的部落战士量身打造的锁甲套装。遍布卡利姆多的盟友铁匠分别打造其中的各个部件。",al={"野蛮护甲","野蛮护手 是什么","战士职业护甲 30"}},{q="找到尤拉莱克后会发生什么？",a="尤拉莱克欢迎你的到来，并认可了你在战斗中的功绩，随后请你收集打造野蛮护手所需的珍奇材料，首先是 萨特之蹄。",al={"后续任务","与尤拉莱克交谈后","萨特之蹄 任务"}},{q="为什么索恩格瑞姆派你去找一位巨魔护甲匠？",a="索恩格瑞姆将野蛮护甲套装的锻造工作分给部落最出色的专精铁匠，其中就包括负责制作护手的黑暗之矛工匠尤拉莱克。",al={"为什么找尤拉莱克","为什么去森金村","巨魔铁匠 野蛮护甲"}},{q="联盟玩家有对应的任务吗？",a="联盟战士也会接受类似的战斗试炼，以打造职业专属护甲，但野蛮护甲任务线和尤拉莱克的锻造工作属于部落。",al={"联盟 野蛮护手","联盟对应任务"}}},fp="33,148,22.282.0,19.294.0,54.98.0,26.62.0,29.140.0,37.157.0,50.147.0,53.141.0"}
P.entries["quest:184"] = {n="法布隆的地契",s="法布隆的地契是艾尔文森林里的迪菲亚潜行者劫走的一份土地所有权证明。将这份文件归还给西部荒野边界附近的流离失所的农夫法布隆，是这对正在逃难的夫妇有朝一日能够收回被窃家园的唯一希望。",h="法布隆的地契是艾尔文森林里的迪菲亚潜行者劫走的一份土地所有权证明。将这份文件归还给西部荒野边界附近的流离失所的农夫法布隆，是这对正在逃难的夫妇有朝一日能够收回被窃家园的唯一希望。",kw={"迪菲亚","艾尔文","法布隆","西奥多·法布隆","弗娜·法布隆","西部荒野","西部荒野地契"},ang={["class:Paladin"]="将不慎遗失的地契归还给穷困潦倒的难民，体现了保护弱小、为无法无天的边境地区带来正义的神圣誓言。",["faction:Alliance"]="法布隆一家的困境凸显了暴风城王室未能保护首都坚固城墙之外的纳税公民。"},sec={{t="被窃文件上的线索",b="在艾尔文森林与迪菲亚强盗交战时，旅行者经常能找回一张由西奥多·法布隆和弗娜·法布隆签署的皱巴巴的土地契据。在羊皮纸的背面，潦草的字迹揭露了强盗们的阴谋：他们强行将这位年迈的农夫从他的土地上赶走，并将这份文件偷运过河进入艾尔文，用作伪造其他被抢占土地地契的模板。这些涂鸦还记录道，有人看到法布隆夫妇被困在边界那边的路边，因为马车坏了而动弹不得。"},{t="西部荒野农民的困境",b="法布隆一家的损失是笼罩西部荒野的悲剧的缩影。随着暴风城军队的缺席和王国资源的匮乏，迪菲亚潜行者已经驱逐了数十个家庭离开他们祖祖辈辈耕耘的土地，利用武力和法律手段巩固了他们对这个王国粮仓的控制。虽然西奥多和弗娜为了自身安全不得不放弃农场，但保留这张合法的地契，让他们在西部荒野恢复秩序后，拥有了对抗那些不法之徒、收回土地的唯一凭证。"}},faq={{q="我可以在哪里找到这份地契？",a="这份地契会从潜伏在艾尔文森林南部和西部各处的迪菲亚潜行者成员身上掉落，例如杰罗德码头附近或藏身于当地营地中的那些敌人。",al={"地契掉落","如何获取法布隆的地契","地契在哪里掉落"}},{q="农夫法布隆在哪里？",a="农夫法布隆和他的妻子弗娜被困在刚跨过艾尔文森林西侧桥梁，进入西部荒野后的大路旁，他们的马车坏在那里。",al={"法布隆的位置","去哪里交还法布隆的地契","农夫在哪里"}},{q="迪菲亚潜行者当初为什么想要这份地契？",a="背面的一张字条显示，强盗们打算利用法布隆这份合法的地契作为模板，在该地区伪造其他房产的所有权证明，通过伪造的文件来巩固他们对被抢农场的控制。",al={"强盗为什么要偷地契","迪菲亚为什么想要地契"}},{q="法布隆夫妇会回到他们的农场吗？",a="短时间内不会。由于无法无天的局势和强盗的袭击，这对夫妇正在逃离该地区。然而，手里拿着地契能确保如果西部荒野日后恢复和平，他们可以合法地收回自己的土地。",al={"法布隆夫妇会回家吗","法布隆的农场会怎样"}},{q="为什么暴风城不保护这些农场？",a="暴风城因瓦里安·乌瑞恩国王的突然失踪和国内的政治紧张局势而陷入瘫痪。随着王室资源集中在首都，西部荒野这样的外围领土只能靠自己来抵御日益猖獗的迪菲亚潜行者。",al={"为什么西部荒野没有卫兵","为什么暴风城无视西部荒野"}},{q="这个任务中艾尔文森林和西部荒野有什么联系？",a="该任务起到了引导作用，将冒险者从艾尔文森林引向河对岸的西部荒野，展示了迪菲亚的势力网已经渗透到了王国的核心区域。",al={"为什么地契会在艾尔文森林","区域间的联系"}}},fx={["9b306b68"]={q="为什么要归还法布隆的地契？",a="地契本身不过是一张没有生命的纸，但背面潦草的留言揭示，迪菲亚恶徒曾威逼西奥多和弗娜·法布隆放弃他们的土地。那些盗贼打算以此为样本，伪造其他地产的所有权凭据。将它交还给逃难中的法布隆一家，就能让这个诚实的农户家庭拿回仅存的所有权证明，让他们心怀希望，盼望西部荒野恢复和平后，有朝一日能夺回被抢走的祖产。",al={"为什么归还地契","西部荒野地契的动机","法布隆的地契的用途"}}},fp="15,233,22.376.0,32.287.0,26.131.0,25.172.0,52.174.0,42.161.0,43.239.0,65.165.0"}
P.entries["quest:1840"] = {n="奥姆·石蹄和野蛮头盔",s="在雷霆崖，奥姆·石蹄能够锻造野蛮头盔。索恩格瑞姆·火眼会派战士去找他完成这项工作。",h="在雷霆崖，奥姆·石蹄能够锻造野蛮头盔。索恩格瑞姆·火眼会派战士去找他完成这项工作。",kw={"护甲任务","野蛮头盔","奥姆·石蹄","索恩格瑞姆·火眼","雷霆崖","战士"},ang={["class:Warrior"]="作为战士，你被派去拜访部落最出色的锻造大师之一，寻求厚重的头部防护。",["faction:Horde"]="作为部落的一员，你会看到贫瘠之地的兽人武器大师与雷霆崖高处的牛头人工匠携手合作。"},sec={{t="钢铁铸就的引荐",b="在贫瘠之地证明了自身实力，并收集到野蛮护甲部件的战士，会被派往雷霆崖。索恩格瑞姆·火眼是一位技艺精湛的护甲匠，但这项工作已超出了他的技艺所及。因此，他指引战士们去找奥姆·石蹄，他的技艺在卡利姆多广为人知。奥姆能用从凶猛野兽身上取得的稀有战利品，打造坚固的头盔。"},{t="水池旁的工匠",b="奥姆·石蹄在莫高雷的高耸台地上生活和工作，就在雷霆崖中央巨型图腾下方的水池附近。当战士带着索恩格瑞姆·火眼的引荐前来时，奥姆会放下手头的日常工作。他会与战士谈起那些难以取得的材料，用它们锻造一顶适合部落前线战斗的头盔。"}},faq={{q="奥姆·石蹄是谁？",a="奥姆·石蹄是一位居住在雷霆崖的牛头人护甲匠，技艺精湛。索恩格瑞姆·火眼看中他锻造战盔的本领，会派战士去找他。",al={"奥姆·石蹄","奥姆是谁"}},{q="在哪里能找到奥姆·石蹄？",a="奥姆·石蹄在雷霆崖中央巨型图腾下方的水池附近工作。",al={"奥姆在哪里","奥姆·石蹄位置","寻找奥姆"}},{q="索恩格瑞姆·火眼为什么派你去雷霆崖？",a="索恩格瑞姆·火眼能够制作野蛮套装的胸甲和其他部件，而奥姆·石蹄拥有锻造野蛮头盔的技艺。",al={"为什么去雷霆崖","为什么找奥姆"}},{q="野蛮头盔是什么？",a="野蛮头盔是为身经百战的部落战士锻造的头盔。锻造它所需的材料，必须冒险从卡利姆多各地的野兽身上取得。",al={"野蛮头盔任务","野蛮头盔是什么"}},{q="奥姆接下来有什么要求？",a="奥姆·石蹄要你收集野兽身上的战利品来锻造头盔，首先是从野生奇美拉身上取得一根奇美拉之角。",al={"下一个任务","奥姆·石蹄之后","奇美拉之角任务"}},{q="任何职业都能接取这个任务吗？",a="不能。这一系列任务面向武艺已有一定造诣，并且完成了索恩格瑞姆最初护甲制作工作的战士。",al={"是否仅限战士","谁能做这个任务"}}},fp="33,113,24.351.0,23.298.0,21.152.0,33.78.0,54.136.0,24.149.0,27.115.1,30.115.0"}
P.entries["quest:1841"] = {n="维罗拉·奈特雷和野蛮腿甲",s="索恩格瑞姆·火眼派遣部落战士横渡无尽之海，寻求维罗拉·奈特雷打造的野蛮腿甲。在幽暗城，这位被遗忘者铁匠凭借生前留存的技艺锻造护甲。她的手艺帮助部落战士凑齐一套坚固耐用的护甲。",h="索恩格瑞姆·火眼派遣部落战士横渡无尽之海，寻求维罗拉·奈特雷打造的野蛮腿甲。在幽暗城，这位被遗忘者铁匠凭借生前留存的技艺锻造护甲。她的手艺帮助部落战士凑齐一套坚固耐用的护甲。",kw={"野蛮护甲","野蛮腿甲","洛丹伦","索恩格瑞姆·火眼","贸易区","幽暗城","维罗拉·奈特雷","战士任务"},ang={["class:Warrior"]="身为战士，你会在三十级左右迎来部落护甲试炼中的一个重要阶段，远赴卡利姆多之外，寻求专属的职业护甲。",["faction:Horde"]="身为部落的一员，你参与的这项工作将来自卡利姆多的兽人、巨魔和牛头人与东部王国的被遗忘者工匠联系在一起。",["race:Undead"]="身为被遗忘者的一员，你能看到维罗拉·奈特雷仍在传承已经沦陷的洛丹伦的精湛技艺与艺术遗产。"},sec={{t="跨海之旅",b="索恩格瑞姆·火眼派你向东横渡无尽之海，寻找能打造野蛮腿甲的铁匠。你已在贫瘠之地证明了自己的实力，赢得这位坚守于此的资深铁匠的认可，如今他指引你去追寻传说中的野蛮护甲。索恩格瑞姆无法独自打造整套护甲，因此要仰仗部落各地技艺精湛的盟友。要打造腿甲，就得前往被遗忘者的地下王国，寻找一位在北方人类文明覆灭之前便已备受推崇的工匠。"},{t="维罗拉·奈特雷的技艺",b="维罗拉·奈特雷在幽暗城的贸易区工作，她昔日的手艺仍在为部落效力。在 北方的天灾浩劫 夺去她的生命之前，她曾是 洛丹伦王国 最杰出的护甲锻造师之一。她的故土遭到腐化，她也成了被遗忘者的一员，但死亡并未夺走她锻造金属的精湛技艺。如今，她用身为人类时掌握的手艺为部落战士打造护甲，谈及自己的亡灵之身时，还带着冷淡而阴森的幽默。"}},faq={{q="维罗拉·奈特雷是谁？",a="维罗拉·奈特雷曾被誉为洛丹伦王国最优秀的护甲锻造师之一。第三次大战之后，她作为被遗忘者的一员重新站起，在幽暗城的贸易区安家，继续凭借自己的手艺为部落效力。",al={"维罗拉·奈特雷背景故事","维罗拉·奈特雷是谁","被遗忘者 铁匠维罗拉·奈特雷"}},{q="索恩格瑞姆为什么派我去幽暗城？",a="索恩格瑞姆·火眼派你前往幽暗城，是因为打造全套野蛮护甲需要部落各地能工巧匠的协助。他深知维罗拉·奈特雷在护甲锻造方面的声望，因此派你前往洛丹伦，委托她打造腿甲。",al={"为什么去幽暗城","索恩格瑞姆 幽暗城任务","贫瘠之地到幽暗城战士"}},{q="在幽暗城哪里能找到维罗拉·奈特雷？",a="维罗拉·奈特雷在幽暗城贸易区的熔炉旁工作，周围都是为希尔瓦娜斯·风行者女士效力的铁匠和其他工艺大师。",al={"维罗拉·奈特雷位置","维罗拉·奈特雷在哪里","寻找维罗拉·奈特雷"}},{q="与维罗拉·奈特雷交谈后要做什么？",a="维罗拉·奈特雷会让你前往湿地，从龙喉氏族兽人身上收集胫骨，用来打造你的野蛮腿甲。",al={"维罗拉·奈特雷后续任务","龙喉氏族 胫骨任务","维罗拉·奈特雷需要什么"}},{q="维罗拉·奈特雷有没有谈及自己亡灵身份的对话？",a="有。维罗拉·奈特雷冷冷地开玩笑，说不知道究竟是她在为你打造护甲，还是反过来。她说，自己大约在失去嗅觉、不再呼吸的时候，也失去了幽默感。",al={"维罗拉·奈特雷的笑话","亡灵铁匠对话","维罗拉·奈特雷的幽默"}},{q="野蛮护甲只有战士能获取吗？",a="是的。野蛮护甲的试炼，包括寻找维罗拉·奈特雷打造腿甲，都是为逐渐成长为老兵的部落战士准备的。",al={"其他职业能否获取 野蛮护甲","战士专属任务 野蛮护甲"}}},fp="38,276,24.449.0,29.426.0,21.257.0,40.228.0,48.145.0,43.98.1,49.198.0,34.141.0"}
P.entries["quest:1842"] = {n="萨特之蹄",s="萨特蹄足是一项由森金村的巨魔工匠尤拉莱克发布的任务。为了打造一副强力的残酷护手，战士们必须北上前往灰谷，猎杀萨特并采集它们那因魔法而肿胀、不再分叉的蹄足。",h="萨特蹄足是一项由森金村的巨魔工匠尤拉莱克发布的任务。为了打造一副强力的残酷护手，战士们必须北上前往灰谷，猎杀萨特并采集它们那因魔法而肿胀、不再分叉的蹄足。",kw={"灰谷","残酷护手","杜隆塔尔","蹄足","萨特","森金村","尤拉莱克","未分叉"},ang={["class:Warrior"]="这项任务是战士进阶仪式的一部分，旨在考验他们在面对狡诈的恶魔伏击者时的武力韧性，以换取定制的护甲。",["faction:Horde"]="执行这次狩猎将迫使部落战士离开杜隆塔尔的干旱平原，深入到灰谷充满争议的暗夜精灵领地。",["race:Troll"]="尤拉莱克的方法展现了暗矛工艺务实的一面，通过从倒下的魔法敌人身上抽取原始精华，而非仅仅依赖传统的锻造技术。"},sec={{t="汲取腐化精华",b="为了打造出足以抗衡卡利姆多最野蛮力量的护甲，暗矛部族的工匠尤拉莱克将目光投向了寻常的铁块和皮革之外。他指引雄心勃勃的战士们北上，前往灰谷的古老森林，那里 lingering 的恶魔腐化正在当地的萨特聚集点中不断蔓延。"},{t="灰谷魔法的肿胀",b="据尤拉莱克所说，灰谷东北部的萨特通过汲取森林中潜藏的纯净能量并将其扭曲为邪恶的力量来维持自身。那些在这些借来的生命力中沉溺最深的恶魔，它们的蹄足会产生异常的肿胀，并失去原本分叉的形态。尤拉莱克打算抽取这种集中的魔法能量，并将其直接编织进他所打造的护手中。"}},faq={{q="尤拉莱克为什么需要萨特蹄足？",a="尤拉莱克需要这些蹄足来增强他正在打造的残酷护手。他打算抽取萨特从森林中吸取并腐化进它们肿胀足部里的浓缩魔法。",al={"为什么需要萨特蹄足","蹄足的用途","蹄足有什么用"}},{q="萨特在哪里？",a="它们栖息在灰谷的东北部，在那里它们盘踞在受腐化的古代遗迹之中，并靠汲取深林中的残留魔法能量为生。",al={"萨特在哪里","萨特位置","在哪里寻找萨特蹄足"}},{q="为什么未分叉的蹄足很特别？",a="蹄足不再分叉意味着这只萨特已经吞噬了过量的灰谷纯净魔法，导致它的肢体因窃取的力量而肿胀。",al={"未分叉蹄足的背景知识","为什么没有分叉","肿胀的蹄足"}},{q="尤拉莱克是谁？",a="尤拉莱克是一位居住在杜隆塔尔南部森金村的熟练暗矛巨魔护甲匠，以协助战士制造试炼装备而闻名。",al={"尤拉莱克是谁","任务发布者","森金村的巨魔"}},{q="尤拉莱克在打造什么护甲？",a="他正准备打造一副残酷护手，这是一种为崛起的部落战士准备的重型防护手部装备，灌注了窃取的魔法效力。",al={"什么是残酷护手","护手任务","奖励护甲"}},{q="这里的萨特效忠于燃烧军团吗？",a="是的。萨特是因恶魔契约而发生转化的上古暗夜精灵，卡利姆多林地中残存的聚集点仍在为恶魔力量效劳，进行着邪能腐化。",al={"萨特的效忠对象","萨特属于军团吗"}}},fp="12,136,28.233.0,30.265.0,36.148.0,27.122.0,36.127.0,16.130.0,31.126.0,44.167.0"}
P.entries["quest:1843"] = {n="野蛮护手",s="尤拉莱克为一位久经沙场的部落战士打造好了一副野蛮护手。这件作品融入了从遥远各地收集的稀有材料，旨在为制作者和佩戴者双方赢得荣耀。",h="尤拉莱克为一位久经沙场的部落战士打造好了一副野蛮护手。这件作品融入了从遥远各地收集的稀有材料，旨在为制作者和佩戴者双方赢得荣耀。",kw={"护甲锻造","野蛮护手","杜隆塔尔","部落","萨特之蹄","尤拉莱克","战士护甲"},ang={["class:Warrior"]="身为战士，你佩戴着为高强度近战打造的护手。它们标志着你向纪律严明的军事领袖之路迈出了一步。",["faction:Horde"]="身为部落的一员，你将工匠们的传统和尚武的自豪带入战场。他们的作品承载着精神的分量与荣耀。"},sec={{t="工匠的杰作",b="尤拉莱克凭借祖传技艺和自身本领，为一位久经沙场的前线战士锻造护甲。在杜隆塔尔，这位部落工匠用从危险敌人身上取得的坚硬战利品打造残暴的护手。制成的护甲能够抵御猛烈打击，并增强佩戴者的攻击。"},{t="先祖的荣耀",b="对兽人和巨魔而言，精良的武器与护甲将熔炉的声望和制作者的精神带入战场。尤拉莱克交出制成的护手时，也将先祖的传承托付给了一位战士。佩戴它们的勇士应当以勇气、严明的武纪和力量，不负这份匠心。"}},faq={{q="尤拉莱克是谁？",a="尤拉莱克是杜隆塔尔的一位工匠，为部落战士量身打造护甲。他要求收集珍奇的材料，好让自己的作品无愧于这门手艺和先祖的传统。",al={"尤拉莱克","谁给予野蛮护手","任务给予者"}},{q="这些护手为什么需要萨特之蹄？",a="萨特的蹄子肿胀而不分瓣，蕴含着从灰谷魔法中汲取的力量。尤拉莱克提取出这股力量，将其注入护手，赋予它们强大的魔力。",al={"为何需要萨特之蹄","萨特身体部位","所用材料"}},{q="在尤拉莱克看来，佩戴这些护手意味着什么？",a="在尤拉莱克看来，这些护手是他技艺的巅峰之作。将它们交给一位当之无愧的战士，既能为他的手艺和先祖赢得荣耀，也让他的辛劳与部落的战场胜利紧密相连。",al={"荣耀先祖","尤拉莱克的荣耀"}},{q="这项任务在哪里进行？",a="锻造工作最终在杜隆塔尔完成，这片干旱的土地是兽人和暗矛巨魔的家园。尤拉莱克在那里检查带回的材料，并交出制成的护甲。",al={"地点","野蛮护手在哪里交任务"}},{q="这项试炼适合所有冒险者吗？",a="这项试炼面向那些已证明自身耐力与尚武决心的前线战士。它标志着他们在部落中迈向更为老练的作战职责。",al={"是否仅限战士","职业要求"}},{q="领取护手之后会怎样？",a="领取护手便完成了这项锻造试炼。战士由此获得装备，能够在艾泽拉斯饱受战火摧残的各处战场上迎战更大的威胁。",al={"下一个任务","野蛮护手后续"}}},fp="16,172,25.252.0,15.308.0,16.160.0,49.172.0,52.179.0,32.161.0,43.165.0,41.142.0"}
P.entries["quest:1844"] = {n="奇美拉之角",s="在焦炭谷，一头饱受折磨的奇美拉族母考验着部落战士的力量与仁慈。奥姆·石蹄需要她的角来打造野蛮头盔，而这场狩猎将证明战士的决心。",h="在焦炭谷，一头饱受折磨的奇美拉族母考验着部落战士的力量与仁慈。奥姆·石蹄需要她的角来打造野蛮头盔，而这场狩猎将证明战士的决心。",kw={"野蛮头盔","焦炭谷","奇美拉族母","奇美拉之角","光滑的奇美拉角","奥姆·石蹄","石爪山脉","雷霆崖","战士任务"},ang={["class:Warrior"]="身为战士，你要在险恶之地猎杀一头独行的顶级猛兽，以此证明自己的本领。这样，你才能获得佩戴野蛮头盔的资格。",["faction:Horde"]="身为部落的一员，你从烈日石居出发，踏入石爪山脉中各方争夺的荒野。在那里，你锻造保卫卡利姆多所需的武装。",["race:Tauren"]="身为牛头人，你能从奥姆·石蹄的话语中听出敬畏。即使身处战斗，终结一头受尽折磨的野兽的痛苦，也是在向Earth Mother致敬。"},sec={{t="决心的考验",b="奥姆·石蹄会为部落战士锻造野蛮头盔，但依照传统，战士必须先证明自己，他才会动工。仅有金属和钱币还不够。战士必须展现武艺，并直面惨烈战火留下的创伤。"},{t="焦炭谷的创伤",b="焦炭谷位于石爪山脉西南部，被灰烬覆盖。这片山谷曾经草木葱茏，如今却被烧成了浓烟弥漫的荒地。野兽仍在覆满烟灰的坑地中游荡，痛苦与愤怒使它们变得扭曲。强大的奇美拉在枯树和灼热的蒸汽喷口之间筑巢。"},{t="战斗中的仁慈",b="对这位牛头人铁匠而言，奇美拉族母的角既是打造头盔所需的材料，也是战士力量的证明。然而，这场狩猎也会终结她的折磨。族母因家园被毁而陷入疯狂，战士将她击倒，便是赐予这个荒野生灵仁慈。"}},faq={{q="奥姆·石蹄是谁？",a="奥姆·石蹄是雷霆崖一位技艺精湛的牛头人铁匠，帮助身经百战的部落战士打造职业护甲，其中就包括野蛮头盔。",al={"奥姆·石蹄背景故事","奥姆·石蹄是谁","雷霆崖铁匠奥姆"}},{q="奥姆为什么需要光滑的奇美拉角？",a="奥姆需要光滑的奇美拉角，因为它是野蛮头盔中坚固耐用的部件。取得这只角，也证明战士有勇气在险恶的地形中追踪并击败一头危险的顶级掠食者。",al={"光滑的奇美拉角用途","为何获取光滑的奇美拉角","野蛮头盔所需的角"}},{q="石爪山脉的奇美拉是什么？",a="奇美拉是卡利姆多土生土长的大型双头飞兽。焦炭谷的烈火与毁灭使幸存的奇美拉陷入狂暴。",al={"石爪山脉奇美拉","奇美拉背景故事","奇美拉是什么"}},{q="这个任务与战士的训练有何关联？",a="到了第三十个历练之季左右，部落战士会拜访奥姆·石蹄这样的行家，接受危险的试炼。完成这些试炼后，他们才有资格穿上为战场勇士打造的厚重野蛮护甲套装，甲胄上布满尖刺。",al={"战士野蛮头盔任务链","三十级战士雷霆崖任务","野蛮护甲任务线"}},{q="奥姆为什么将这场狩猎视为仁慈之举？",a="牛头人的文化崇尚与大地及其生灵和谐共处。焦炭谷的生灵因家园遭到毁灭而饱受折磨，因此，杀死族母被视为终结她无休止的痛苦，而非毫无意义的屠戮。",al={"为何对族母施以仁慈","让她从痛苦中解脱"}}},fp="14,196,17.218.0,29.281.0,15.257.0,21.146.0,38.193.0,33.157.0,46.227.0,47.231.0"}
P.entries["quest:1845"] = {n="野蛮头盔",s="在雷霆崖，奥姆·石蹄以一顶野蛮头盔为战士的试炼画上句号。一名立志有所作为的战士在卡利姆多各地收集珍稀的野兽战利品后，会获得一顶带角的头盔，以此表彰其力量。",h="在雷霆崖，奥姆·石蹄以一顶野蛮头盔为战士的试炼画上句号。一名立志有所作为的战士在卡利姆多各地收集珍稀的野兽战利品后，会获得一顶带角的头盔，以此表彰其力量。",kw={"野蛮头盔","奇美拉之角","大地母亲","猎人高地","奥姆·石蹄","雷霆崖","战士"},ang={["class:Warrior"]="身为部落战士，你通过一项重要的成长仪式，穿上以凶猛野兽的材料打造、经资深训练师祝福的厚重护甲。",["faction:Horde"]="在部落的旗帜下，你证明自己拥有领袖所要求的体力与狩猎本领。",["race:Tauren"]="在雷霆崖，你的头盔体现了牛头人的传统：在Earthmother的恩泽下，将狩猎战利品制成护身的战具。"},sec={{t="战士的仪式",b="奥姆·石蹄是雷霆崖一位严厉的铁匠，负责引导部落战士完成艰苦的成长仪式。这些试炼考验他们的战斗技艺。初入门的战士要在险恶之地猎杀危险的生物，取得珍稀的战利品。唯有达到奥姆·石蹄严苛标准的人，才能来到他面前，完成自己的护甲。"},{t="大地母亲的馈赠",b="战士在荒野中证明自己的决心，为奥姆·石蹄带来一只珍稀的奇美拉之角。作为回报，奥姆·石蹄会赠予野蛮头盔，这顶厚重的锁甲头盔既向野兽致敬，也让佩戴者在前线更加强大。赠予头盔时，奥姆·石蹄会祈求大地母亲的祝福。他期待这名战士在艾泽拉斯各地成就注定属于自己的更伟大的功业。"}},faq={{q="谁会赠予野蛮头盔？",a="奥姆·石蹄是雷霆崖的一位牛头人铁匠，他会将野蛮头盔赠予完成其试炼的部落战士。",al={"谁赠予野蛮头盔","野蛮头盔任务人物","奥姆·石蹄任务"}},{q="获得头盔前必须完成什么任务？",a="获得头盔前，你要完成名为奇美拉之角的试炼。你要在荒野中猎杀凶猛的野兽，将它们的角带给雷霆崖的奥姆·石蹄。",al={"野蛮头盔前置任务","奇美拉之角任务"}},{q="奥姆·石蹄在哪里？",a="奥姆·石蹄就在建于高耸台地上的雷霆崖城中，靠近中央巨型图腾旁的水池。",al={"奥姆·石蹄位置","奥姆·石蹄在哪里"}},{q="奥姆·石蹄为何祈求大地母亲的祝福？",a="身为牛头人，奥姆·石蹄尊奉大地母亲为世界的创造者与精神守护者。她对战士完工头盔的祝福，体现了牛头人的信念：战斗的力量必须与精神上的敬畏相平衡。",al={"为何提及大地母亲","大地母亲背景故事"}},{q="任何冒险者都能参加这项试炼吗？",a="不能。这项试炼及其野蛮护甲奖励，只属于通过专门的职业试炼证明自身勇武的部落战士。",al={"任何人都能获得野蛮头盔吗","野蛮头盔职业"}},{q="野蛮护甲套装有何意义？",a="野蛮护甲的各个部件，标志着一名战士从新兵成长为部落的精锐勇士。它们的制作材料取自卡利姆多最凶猛的掠食者。",al={"野蛮护甲背景故事","为何叫野蛮头盔"}}},fx={["3a1185bd"]={q="奥姆·石蹄为什么要把野蛮头盔奖给你？",a="奥姆·石蹄赐予你头盔，并非因为迫切需要或突发危机，而是为了表彰你在战斗技艺上的成长。你从卡利姆多各地收集稀有材料，并通过战士试炼证明了自己的实力，表明你已准备好承担身经百战的勇士所肩负的重任。奥姆赞许你的坚毅，并祈求大地母亲赐福，让这件护甲在你迎接更艰巨的战斗时保护你。",al={"奥姆为什么把头盔给你","奥姆·石蹄赠予野蛮头盔的原因","为什么要野蛮头盔"}}},fp="11,227,16.312.0,27.358.0,27.116.0,53.168.0,31.98.0,46.223.0,37.120.0,49.179.0"}
P.entries["quest:1846"] = {n="龙喉胫骨",s="“龙喉胫骨”是部落战士的一个任务，由幽暗城的护甲商维罗拉·奈特雷发布。为了打造耐用的野蛮腿甲，战士们被派往湿地南部，从敌对的龙喉兽人身上收集异常粗壮的胫骨。",h="“龙喉胫骨”是部落战士的一个任务，由幽暗城的护甲商维罗拉·奈特雷发布。为了打造耐用的野蛮腿甲，战士们被派往湿地南部，从敌对的龙喉兽人身上收集异常粗壮的胫骨。",kw={"怒牙营地","野蛮腿甲","龙喉氏族","胫骨","萨多尔大桥","幽暗城","维罗拉·奈特雷","湿地"},ang={["class:Warrior"]="这项试炼不仅考验了战士在野外的身体耐力，也考验了他们为了打造高级盔甲而收集阴森材料的意愿。",["faction:Horde"]="击溃卡兹莫丹的龙喉叛军氏族，既削弱了一个危险的旧部落残党，又增强了萨尔新联盟的勇士们的实力。",["race:Orc"]="对于效忠奥格瑞玛的兽人来说，肃清顽固不化的龙喉氏族是对他们族人邪能过去以及救赎所付出的惨痛代价的深刻提醒。",["race:Undead"]="维罗拉·奈特雷务实地利用人型生物残骸的做法，体现了被遗忘者将一切可用资源武器化的心态，无论这些资源有多么骇人。"},sec={{t="恐怖的骨架",b="锻造适合前线身经百战的战士的盔甲需要非同寻常的材料。当要求打造野蛮腿甲时，被遗忘者护甲商维罗拉·奈特雷指定需要一种由坚硬、有弹性的骨骼构成的结构支撑。她没有利用普通的野兽，而是将这些有志向的战士指向了湿地的龙喉兽人，因为他们致密的骨骼结构能提供在战斗中抵御重击所需的韧性。"},{t="测试骨髓",b="从龙喉兽人身上采集骨头只是艰巨任务的一半。维罗拉指示战士们手动测试在野外采集的每一根骨头；任何脆弱到徒手就能折断的样本对锻造来说都是毫无用处的。战士们必须搜寻湿地峭壁沿线的这些叛军营地，折断脆弱的骨头，直到有八根真正坚固的样本通过力量测试。"}},faq={{q="为什么维罗拉·奈特雷特别需要兽人胫骨？",a="维罗拉需要致密、粗壮的材料来作为野蛮腿甲的支撑框架。她认为湿地的龙喉兽人尤其合适，因为他们沉重、强壮的骨骼结构比普通的猎物或残骸能提供更强的结构刚性。",al={"为什么需要兽人胫骨","为什么需要龙喉氏族的骨头","维罗拉的骨头盔甲"}},{q="为什么龙喉兽人是部落战士可以随意猎杀的目标？",a="盘踞在湿地的龙喉氏族残党是敌对的叛军，他们固守着第二次战争的黑暗遗产。他们并不效忠于萨尔领导下的现代部落，因此他们是国家的敌人，也是部落冒险者可以随意讨伐的对象。",al={"龙喉兽人属于部落吗","为什么要攻击龙喉兽人","龙喉氏族在部落的立场"}},{q="为了完成这个任务，在哪里可以找到龙喉兽人？",a="他们居住在湿地，穿过萨多尔大桥，位于阿拉希高地以南。战士们通常会在怒牙营地周围的山崖边搜寻他们，该营地位于北部主干道的西南方。",al={"龙喉氏族的位置","哪里寻找龙喉胫骨","怒牙营地位置"}},{q="为什么任务过程中会有这么多骨头折断？",a="维罗拉只要求最致密的骨髓框架用于锻造盔甲。作为她指示的一部分，战士们需要手工测试每一根骨头；任何在原始物理力量下折断的骨头都会被丢弃，因为它们太脆弱，无法在战斗中保护战士的双腿。",al={"断裂的胫骨","为什么胫骨会折断","坚固骨骼测试"}},{q="维罗拉·奈特雷是谁？",a="维罗拉·奈特雷是一位在幽暗城工作的被遗忘者护甲商。她性格粗暴、冷漠刻薄，而且喜欢讲些阴沉的冷笑话。她协助部落战士制造适合久经沙场的老兵使用的专业武备。",al={"维罗拉·奈特雷背景故事","维罗拉是谁","幽暗城护甲商"}},{q="用这些骨头锻造的是什么护甲部件？",a="这些收集来的骨头构成了野蛮腿甲的内部框架，这是一套为中等级别部落战士制作的耐用锁甲腿铠。",al={"胫骨任务奖励","胫骨的用途","野蛮腿甲锻造"}}},fp="19,193,19.254.0,18.232.0,55.172.0,56.195.0,44.198.0,51.185.0,21.178.0,44.95.0"}
P.entries["quest:1848"] = {n="野蛮锁甲",s="在贫瘠之地，部落战士必须经受考验，索恩格瑞姆·火眼才会为他们锻造锁甲。他们奔走各地，收集稀有材料，在危险的敌人面前证明自己，再将收获带给这位隐居的铁匠。他将这些材料锤炼成征战所需的护甲。",h="在贫瘠之地，部落战士必须经受考验，索恩格瑞姆·火眼才会为他们锻造锁甲。他们奔走各地，收集稀有材料，在危险的敌人面前证明自己，再将收获带给这位隐居的铁匠。他将这些材料锤炼成征战所需的护甲。",kw={"野蛮护甲","野蛮锁甲","十字路口","兽人锻造技艺","贫瘠之地","索恩格瑞姆·火眼","战士锁甲"},ang={["class:Warrior"]="作为一名年轻的部落战士，你在赢得野蛮锁甲的过程中，从青涩的新兵成长为身披定制锁甲、久经沙场的战士。",["faction:Horde"]="作为部落的一员，你能从这件以卡利姆多荒野中夺得的战利品制成的锁甲上，看到部落崇尚自立与力量的尚武精神。",["profession:Blacksmithing"]="作为一名铁匠，你可以学习索恩格瑞姆的传统兽人锻造技艺，将尚武精神与坚韧意志一同锤炼进钢铁。"},sec={{t="铁匠的杰作",b="在贫瘠之地北部，索恩格瑞姆·火眼只为达到他要求的战士锻造护甲。这位隐居的兽人会让他们奔赴四方，收集坚韧的野兽肢体、稀有金属和炼金试剂，然后才拉动风箱。制成的锁甲既能提供防护，也彰显穿戴者展现出的耐力与毅力，让他们赢得部落各地老兵的认可。"},{t="苦难中锻成",b="索恩格瑞姆有意将要求定得极为严苛。部落的武器和护甲从制成的那一刻起，就应承载使用者的汗水与鲜血。当你交上制成的野蛮锁甲时，这位铁匠不会给予赞许。他期待你在残酷的战斗中检验这件护甲，带着鲜血与荣耀的故事归来。"}},faq={{q="野蛮锁甲是什么？",a="野蛮锁甲是兽人铁匠索恩格瑞姆·火眼打造的一件坚固胸甲。部落战士需要证明自己的战斗本领，并在数片危险的土地上收集稀有材料，才能获得它。",al={"野蛮锁甲 是什么","野蛮锁甲 任务","谁打造 野蛮锁甲"}},{q="索恩格瑞姆·火眼是谁？",a="索恩格瑞姆·火眼是一位隐居的资深铁匠，住在贫瘠之地北部的一处山脊上，就在十字路口通往奥格瑞玛的道路东侧。他考验初出茅庐的战士，并在他们证明自身价值后，为他们锻造专用护甲。",al={"索恩格瑞姆 是谁","索恩格瑞姆·火眼","索恩格瑞姆 在哪里"}},{q="为什么索恩格瑞姆要求战士付出如此多的努力，才肯打造护甲？",a="部落的战士传统既重视武艺，也推崇磨难。索恩格瑞姆相信，精良的锁甲应属于那些流过自己的血，并为收集锻造所需的稀有材料付出辛劳的人。",al={"为何收集这么多材料","野蛮护甲 所需条件","索恩格瑞姆 的试炼"}},{q="这条任务线接下来通向何处？",a="索恩格瑞姆将制成的锁甲交给你后，他为你所做的工作便告完成。你可以穿着这件护甲，在卡利姆多和东部王国各地征战。",al={"野蛮锁甲 之后是什么","野蛮锁甲 的下一个任务","有后续任务吗"}},{q="联盟能接到野蛮锁甲任务吗？",a="不能。野蛮锁甲是部落的试炼。联盟战士会在铁炉堡及周边矮人领地的铁匠那里，经历另一套战士仪式，锻造属于自己的标志性护甲。",al={"联盟能获得 野蛮锁甲 吗","联盟对应护甲","是否仅限部落"}},{q="在贫瘠之地的哪里可以找到索恩格瑞姆？",a="索恩格瑞姆住在贫瘠之地北部的一道高耸山脊上，就在荆棘岭以南、十字路口以东。",al={"索恩格瑞姆 的位置","索恩格瑞姆 在贫瘠之地的哪里","如何找到 索恩格瑞姆"}}},fp="14,256,21.404.0,18.329.0,27.207.0,26.253.0,68.202.0,38.162.0,54.195.0,44.109.0"}
P.entries["quest:185"] = {n="猎虎",s="在荆棘谷北部的狩猎营地，猎人艾耶克·罗欧克提出要传授冒险者追踪大型猫科动物的技巧。她会让新手去对抗营地附近潜行的幼虎，以此来测试他们基本的狩猎和追踪能力。",h="在荆棘谷北部的狩猎营地，猎人艾耶克·罗欧克提出要传授冒险者追踪大型猫科动物的技巧。她会让新手去对抗营地附近潜行的幼虎，以此来测试他们基本的狩猎和追踪能力。",kw={"艾耶克·罗欧克","狩猎","奈辛瓦里","荆棘谷","猎虎大师","年幼的荆棘谷猛虎"},sec={{t="丛林里的第一课",b="艾耶克·罗欧克在儿时就从她父亲那里学会了猎虎的艺术，现在她将这项技艺分享给那些在完成“丛林欢迎仪式”后来到奈辛瓦里远征队营地的旅人们。她坚持认为，追踪并猎杀最年幼的猫科动物是任何猎人进阶去挑战更高级猎物前必须具备的基础。"},{t="猎杀潜行者",b="年幼的荆棘谷猛虎通常出没在靠近远征队营地的丛林中。罗欧克要求必须猎杀十只这样的野兽，以证明其实力足以胜任，她才会提供进一步的训练。"}},faq={{q="谁会教你如何猎虎？",a="驻扎在荆棘谷北部奈辛瓦里远征队营地的资深猎人艾耶克·罗欧克提供此项训练。",al={"谁提供猎虎大师训练","艾耶克·罗欧克任务","猎虎任务发布者"}},{q="为什么艾耶克·罗欧克首先选择幼虎作为目标？",a="罗欧克认为这些年幼的猫科动物更容易追踪和猎杀，因此它们是检验猎人追踪技能的理想入门试炼，在尝试更危险的猎物之前必须先通过这一关。",al={"为什么是幼虎","为什么猎虎大师训练要从简单的开始"}},{q="在哪里可以找到幼虎？",a="年幼的荆棘谷猛虎通常潜伏在远征队营地附近的丛林地带。",al={"年幼的荆棘谷猛虎在哪里","幼虎位置"}},{q="这项狩猎之前有什么前置任务？",a="这项狩猎试炼紧随前置任务“丛林欢迎仪式”之后，该任务旨在引导旅人前往狩猎营地。",al={"猎虎大师训练前置要求","猎虎大师之前是什么任务"}}},fp="13,177,27.272.0,20.170.0,41.108.0,48.162.0,33.78.0,28.92.0"}
P.entries["quest:1858"] = {n="碎手氏族",s="在奥格瑞玛，瑟祖克考验着那些寻求加入碎手氏族的潜行者。他要求他们从一名毫不知情的同伙身上取走钥匙，打开找回的塔赞的背包。",h="在奥格瑞玛，瑟祖克考验着那些寻求加入碎手氏族的潜行者。他要求他们从一名毫不知情的同伙身上取走钥匙，打开找回的塔赞的背包。",kw={"暗影裂口","加摩尔","奥格瑞玛","偷窃","潜行者","碎手氏族","塔赞","瑟祖克"},ang={["class:Rogue"]="身为潜行者，你将学会在人群中跟踪毫无察觉的目标，悄无声息地取走钥匙，并获取重要情报。",["faction:Horde"]="萨尔的新部落崇尚战士的荣誉，但暗中的侦察仍不可或缺。碎手氏族在奥格瑞玛深处悄然承担着这项工作。"},sec={{t="精妙手法的考验",b="取回上锁的塔赞的背包后，你发现没有钥匙便无法打开它。碎手氏族要求你凭借技巧打开这把复杂的锁，而非诉诸蛮力。瑟祖克派你去找加摩尔，一个经常出入奥格瑞玛旅店的牛头人酒鬼。加摩尔很容易分心，而且曾帮助过塔赞，正适合作为悄然行窃的目标。"},{t="踏入暗影",b="从加摩尔身上取走钥匙，不要惊动旅店里的任何人，然后打开背包，取出塔赞的日志。将窃得的物品带给暗影裂口的瑟祖克，以达到碎手氏族的要求。干净利落地完成任务，你就能正式获准成为其中的一名密探。"}},faq={{q="加摩尔是谁，他为什么有钥匙？",a="加摩尔曾协助过塔赞，也就是瑟祖克正在调查的那名密探。塔赞随身带着背包，却将钥匙留给了加摩尔，这个毫无戒心的酒鬼整日在奥格瑞玛中央的旅店里饮酒。",al={"为什么是加摩尔","谁有钥匙","加摩尔的钥匙"}},{q="塔赞的背包里有什么？",a="塔赞的日志就在上锁的背包里。日志中记载着瑟祖克和碎手氏族感兴趣的情报，而取回日志则是为了考验你秘密获取重要情报的能力。",al={"塔赞的日志","背包里的东西","背包里有什么"}},{q="奥格瑞玛的碎手氏族是什么组织？",a="碎手氏族最初是来自德拉诺的一个臭名昭著的兽人氏族，以自残和残忍无情闻名。在奥格瑞玛，它已成为部落的刺客、间谍和潜行者公会，以地下的暗影裂口为据点。",al={"碎手氏族是什么","碎手氏族潜行者","奥格瑞玛潜行者"}},{q="瑟祖克在哪里活动？",a="瑟祖克以暗影裂口为据点，那是奥格瑞玛岩石山脊下的一片昏暗洞穴。术士、潜行者和暗影技艺汇聚于此，远离日光。",al={"瑟祖克在哪里","瑟祖克的位置","暗影裂口潜行者训练师"}},{q="瑟祖克为什么不直接砸开背包？",a="背包上有一把复杂的锁，而瑟祖克正在考验潜行者的自制力。比起声响巨大的破坏，碎手氏族更看重精准的偷窃和精妙的手法。",al={"为什么要偷窃","为什么需要钥匙"}},{q="完成这个任务后会怎样？",a="交出塔赞的日志，你的入会考验就完成了。瑟祖克会承认你是碎手氏族的一员，并交给你用于秘密行动的工具。",al={"碎手氏族奖励","任务链结尾"}}},fp="18,163,18.320.0,22.248.0,42.210.0,31.187.0,40.227.0,27.162.0,48.152.0,30.149.1"}
P.entries["quest:1859"] = {n="瑟祖克",s="在奥格瑞玛，瑟祖克正等待一位来自杜隆塔尔、颇有潜力的潜行者。卡普拉克见识过你杀戮与潜行的本领，便派你前往暗影裂口，与一名碎手氏族密探会面。",h="在奥格瑞玛，瑟祖克正等待一位来自杜隆塔尔、颇有潜力的潜行者。卡普拉克见识过你杀戮与潜行的本领，便派你前往暗影裂口，与一名碎手氏族密探会面。",kw={"刺客","暗影裂口","杜隆塔尔","卡普拉克","奥格瑞玛","潜行者","碎手氏族","瑟祖克"},ang={["class:Rogue"]="身为潜行者，这份召唤将你引入碎手氏族，让你在杜隆塔尔独自执行的工作与部落有组织的间谍网络联系起来。",["faction:Horde"]="身为部落的一员，你知道萨尔宣扬荣耀与战士精神。瑟祖克的网络表明，部落也依靠暗处的利刃和秘密搜集情报的人。"},sec={{t="低语中的召唤",b="当有潜力的年轻潜行者开始在杜隆塔尔崭露头角，卡普拉克便会将他们叫到一旁。新生的部落尊崇萨尔，但并非所有为部落效力的人都会在他的旗帜下公开作战。一名战士擅长杀戮与潜行，并愿意打破正面交战的规矩，这样的消息传到了奥格瑞玛的地下公会。"},{t="深入暗影裂口",b="卡普拉克派你前往奥格瑞玛赤红岩壁下的暗影裂口。瑟祖克在那里的幽暗中等候，避开城中步兵的视线。在那里，独来独往的扒手与伏击者被招入碎手氏族，这是部落的秘密网络，如同隐于黑暗中的匕首。"}},faq={{q="瑟祖克是谁？",a="瑟祖克是碎手氏族的一名密探，身处奥格瑞玛的暗影裂口。他接见从杜隆塔尔训练场赶来的、有潜力的年轻潜行者，并招募他们为公会效力。",al={"瑟祖克是谁","瑟祖克的故事","非玩家角色 瑟祖克"}},{q="卡普拉克为什么派我去找他？",a="卡普拉克看到了你的战斗本领，以及潜行和诡诈方面的天赋。他知道碎手氏族正在寻找能干的恶徒，因此向你转达了瑟祖克的招募请求。",al={"为何被派去找瑟祖克","卡普拉克的任务","为何前往奥格瑞玛"}},{q="奥格瑞玛的碎手氏族是什么组织？",a="在奥格瑞玛，碎手氏族是一个由刺客、间谍和盗贼组成、为部落效力的秘密公会。他们处理那些必须完成、却有违道义的工作，而萨尔麾下崇尚荣耀的战士无法公开承担这些任务。",al={"碎手氏族是什么","奥格瑞玛的碎手氏族","部落潜行者公会"}},{q="暗影裂口在哪里？",a="暗影裂口是奥格瑞玛中央地下的一处洞穴。幽暗的通道从力量谷和暗巷区向下延伸，通往这里，让城中的术士和潜行者得以避开公众的审视。",al={"暗影裂口在哪里","如何找到瑟祖克","暗影裂口的位置"}},{q="见到瑟祖克之后会怎样？",a="你向瑟祖克致意后，他会介绍为碎手氏族效力的职责，并分派任务，考验你的能力、潜行本领，以及对这个网络的忠诚。",al={"后续任务","瑟祖克想要什么","见过瑟祖克之后"}},{q="其他职业能接到这个任务吗？",a="不能。只有潜行者积累了一定经验后，才会收到这份召唤，标志着他们从地方上的小规模冲突走入部落的情报网络。",al={"其他职业能否接取","是否仅限潜行者","潜行者任务"}}},fp="7,190,19.238.0,24.246.0,15.172.0,31.188.0,40.190.0,37.193.0,33.157.0,33.166.0"}
P.entries["quest:186"] = {n="猎虎",s="在北荆棘谷的奈辛瓦里远征队营地，艾耶克·罗欧克升级了他的狩猎试炼。在见识过你对幼年潜行者展现出的潜力后，他现在派你深入丛林，去猎杀成年荆棘谷猛虎。",h="在北荆棘谷的奈辛瓦里远征队营地，艾耶克·罗欧克升级了他的狩猎试炼。在见识过你对幼年潜行者展现出的潜力后，他现在派你深入丛林，去猎杀成年荆棘谷猛虎。",kw={"艾耶克·罗欧克","奈辛瓦里远征队营地","荆棘谷猛虎","荆棘谷","猛虎大师"},sec={{t="猎杀成年猫科动物",b="继你在对付年幼掠食者时初试身手并取得成功后，艾耶克·罗欧克希望考验你日益精进的狩猎技巧，让你去对付更老练的野兽。他指引你重返荆棘谷的荒野，在追求更艰巨的挑战之前，先猎杀十只成年荆棘谷猛虎。"}},faq={{q="谁发布了这个狩猎任务？",a="艾耶克·罗欧克，一位驻扎在北荆棘谷奈辛瓦里远征队营地的猎人，发布了这项试炼。",al={"谁发布了猛虎大师","艾耶克·罗欧克位置","谁发布了这个任务"}},{q="你需要猎杀什么野兽？",a="你需要追踪并击杀徘徊在周围丛林中的十只成年荆棘谷猛虎。",al={"我需要杀什么老虎","哪些猫科动物","猛虎大师目标"}},{q="这项试炼在狩猎任务链中处于什么位置？",a="这项试炼紧随最初的猛虎大师狩猎任务之后，并直接引向艾耶克·罗欧克指引下的第三阶段。",al={"猛虎大师2之前是什么","接下来是什么","猛虎大师系列任务"}}},fp="13,191,23.212.0,22.99.0,40.89.0,38.106.0"}
P.entries["quest:1860"] = {n="和詹妮亚交谈",s="来自闪金镇的见习法师在完成艾尔文森林的基础训练后，会前往暴风城拜见詹妮亚·坎农。扎尔迪玛·维夫希尔特指引他们前去。",h="来自闪金镇的见习法师在完成艾尔文森林的基础训练后，会前往暴风城拜见詹妮亚·坎农。扎尔迪玛·维夫希尔特指引他们前去。",kw={"艾尔文森林","闪金镇","詹妮亚·坎农","法师区","与詹妮亚交谈","暴风城","巫师圣殿","扎尔迪玛·维夫希尔特"},ang={["class:Mage"]="身为法师，你将告别在闪金镇乡间施法的日子，前往暴风城的巫师圣殿，与高阶法师一起承担正式职责。",["faction:Alliance"]="身为联盟的一员，你依靠首都法师以奥术保持警戒，协助保护艾尔文森林和暴风城。"},sec={{t="巫师圣殿的召唤",b="在法师区，巫师圣殿汇聚了王国的资深法师，供他们研习和传授奥术。他们协调王国各地的魔法事务，如今你的训练也成为这项广泛工作的一部分。"},{t="王国安危之事",b="詹妮亚·坎农负责当地的任务，包括有关艾尔文森林和暴风城安全状况的报告，也指导你的学业。她对向初来乍到的学徒透露重大秘密持谨慎态度，并将你的汇报视为你开始为法师组织效力的第一步。"}},faq={{q="谁派我来执行这项任务？",a="当你的奥术技艺足够精进时，闪金镇狮王之傲旅店的法师训练师扎尔迪玛·维夫希尔特就会派你前来。",al={"任务给予者","谁提供任务","扎尔迪玛"}},{q="在哪里能找到詹妮亚·坎农？",a="詹妮亚·坎农位于暴风城法师区中心的巫师圣殿。",al={"詹妮亚·坎农位置","詹妮亚在哪里","寻找詹妮亚"}},{q="巫师圣殿是什么？",a="巫师圣殿是暴风城法师区中一座醒目的魔法高塔。王国的法师和奥术学者将这里用作学院、图书馆和行动基地。",al={"巫师圣殿是什么","暴风城法师塔"}},{q="为什么扎尔迪玛派我去找詹妮亚，而不亲自处理？",a="扎尔迪玛在闪金镇向年轻法师传授基础知识。詹妮亚·坎农等地位更高的学者则坐镇首都，负责应对更大范围的地区威胁，以及影响王国的专门事务。",al={"为什么去暴风城","为什么找詹妮亚"}},{q="向詹妮亚·坎农报到后会发生什么？",a="詹妮亚会派你调查艾尔文森林明镜湖周围神秘的魔法异常现象。",al={"接下来做什么","后续任务","下一步"}},{q="所有职业都能接到这项任务吗？",a="不能。只有法师才能经历这一从乡村训练迈入暴风城奥术界的入门仪式。",al={"非法师能做吗","仅限法师","职业要求"}}},fx={["8f9ffa7f"]={q="扎尔迪玛·维夫希尔特为什么要你与詹妮亚交谈？",a="扎尔迪玛·维夫希尔特此举是出于对暴风城和艾尔文森林安全的担忧。一件紧急事务需要有能力的法师出面，但他没有亲自处理，而是指引有潜力的学徒前往巫师圣殿，去找负责这项敏感任务具体事宜的詹妮亚·坎农。",al={"扎尔迪玛的动机","为何拜访詹妮亚","为何派去找詹妮亚"}}},fp="17,156,30.230.0,27.284.0,27.129.0,31.89.0,29.173.0,67.196.0,46.97.1,37.98.0"}
P.entries["quest:1861"] = {n="明镜湖",s="在暴风城的法师区，联盟的法师新手被派去检测明镜湖是否受到魔法污染。詹妮亚·坎农派他们前往城门西南方，采集瀑布溅起的水花。",h="在暴风城的法师区，联盟的法师新手被派去检测明镜湖是否受到魔法污染。詹妮亚·坎农派他们前往城门西南方，采集瀑布溅起的水花。",kw={"奥术污染","艾尔文森林","詹妮亚·坎农","魔网","明镜湖","水样","巫师圣殿"},ang={["class:Mage"]="身为法师，你从在巫师圣殿学习，转向调查世界各地的奥术现象。这项工作会让你获得第一根法师专用法杖或第一颗副手宝珠。",["faction:Alliance"]="身为联盟的一员，你可以协助巫师圣殿的法师，保护艾尔文的自然资源和王国的腹地。",["race:Human"]="身为人类，你知道明镜湖滋养着艾尔文的农田与水道，因此，湖水是否纯净关系着暴风城的居民。"},sec={{t="魔网与变动的能量流",b="从黑暗之门开启，到第三次大战和海加尔山之战，接连的冲突震动了艾泽拉斯的奥术能量流。这些冲击使古老的能量流偏离了原本稳定的通道。\n\n在暴风城的巫师圣殿，詹妮亚·坎农等法师密切关注着这些变化。他们担心，偏离原位的奥术能量可能蔓延到荒野，破坏当地的生态系统。"},{t="检测湖水",b="明镜湖位于暴风城城门西南方的峭壁下，是一座由山间瀑布补给的天然蓄水池。周围乡野都依赖这里的水源。\n\n詹妮亚派法师新手带着玻璃瓶前往瀑布底部，采集刚刚溅起的水花。随后，密室便能通过占卜和试剂检测，查明是否有失控的魔法渗入公共水源。"}},faq={{q="詹妮亚·坎农为什么需要明镜湖的水样？",a="遍及艾泽拉斯的冲突撕裂了天然的魔网能量流。詹妮亚·坎农担心，动荡的奥术能量正在渗入暴风城周围的地下水层，可能伤害所有饮用湖水的人。",al={"为何采集明镜湖水","詹妮亚水样","这个任务有何用途"}},{q="明镜湖究竟在哪里？",a="明镜湖位于艾尔文森林西北部，紧邻暴风城正门西南方的高耸峭壁。水样取自湖边瀑布下方的水潭。",al={"明镜湖在哪里","明镜湖位置","寻找明镜湖"}},{q="如果湖水受到污染，会发生什么？",a="詹妮亚担心，长期饮用受到魔法污染的水，可能伤害那些依赖湖水的人。具体影响尚不清楚。",al={"水是否有毒","水中有魔法会怎样","魔法污染的影响"}},{q="谁能执行这项任务？",a="接受训练的联盟法师新手会执行这项任务，这是他们为巫师圣殿开展的最早几项实地研究之一。",al={"谁能接明镜湖任务","明镜湖是否仅限法师"}},{q="这个任务会引出后续调查吗？",a="由詹妮亚·坎农的召唤开启的最初任务，到这里便结束了。它让学徒获得第一件正式的法师用具，也确立了他们留意王国各地魔法异动的职责。",al={"明镜湖之后是什么","明镜湖任务链"}},{q="魔法能量流最初为什么会失去稳定？",a="詹妮亚认为，能量流的变化源于世界上重大的魔法冲突，但没有指出具体的战役或事件。",al={"魔网为何受损","魔法冲突的含义","什么破坏了魔法"}}},fx={["66ca747e"]={q="明镜湖水的样本有什么用？",a="詹妮亚·坎农需要这个样本，来检验明镜湖的湖水是否受到了魔法污染。席卷艾泽拉斯的剧烈魔法动荡，使奥术流偏离了原有的路径，法师区的法师们担心，这些不稳定的能量正直接渗入当地的水源。检验湖水，就能查明饮用这些水的人是否面临魔法腐蚀的危险。",al={"明镜湖水的样本用途","为何采集水样","样本有什么用"}}},fp="11,190,31.402.0,18.382.0,60.200.0,29.169.0,37.139.0,31.124.0,47.206.0,67.112.0"}
P.entries["quest:187"] = {n="猎虎",s="在奈辛瓦里远征队营地的丛林深处，艾耶克·罗欧克提高了狩猎试炼的难度。他要求你杀死十只年长的荆棘谷幼虎，以在最终测试前证明你的实力。",h="在奈辛瓦里远征队营地的丛林深处，艾耶克·罗欧克提高了狩猎试炼的难度。他要求你杀死十只年长的荆棘谷幼虎，以在最终测试前证明你的实力。",kw={"艾耶克·罗欧克","大型狩猎","年长的荆棘谷幼虎","奈辛瓦里","荆棘谷","虎类狩猎大师"},sec={{t="技能测试",b="在之前的狩猎之后，艾耶克·罗欧克要求你在荒野中追踪十只年长的荆棘谷幼虎。他认为这些野兽既最难追踪，也是最凶猛的对手。击杀十只这样的野兽是最终试炼的前奏，完成之后，他承诺会在奈辛瓦里大师面前宣布你是一位虎类狩猎大师。"}},faq={{q="谁负责布置这项试炼？",a="艾耶克·罗欧克在荆棘谷北部的奈辛瓦里远征队营地提供这项试炼。",al={"谁发布虎类狩猎大师","艾耶克·罗欧克任务","任务发布者"}},{q="你需要追踪什么猎物？",a="你必须猎杀十只年长的荆棘谷幼虎。",al={"我需要杀什么","哪种老虎","虎类狩猎大师目标"}},{q="为什么要特别挑选年长的荆棘谷幼虎？",a="艾耶克·罗欧克指出，年长的荆棘谷幼虎是当地猫科动物中最难找到且最凶猛的。",al={"为什么是年长的老虎","年长老虎的难度"}},{q="这项狩猎之前的内容是什么？",a="这项试炼紧随艾耶克·罗欧克的虎类狩猎大师系列任务的第二阶段之后。",al={"前置任务","先决条件"}}},fp="13,146,15.280.0,23.94.0,29.47.0,47.113.0,28.74.0"}
P.entries["quest:1878"] = {n="收集水袋",s="操作员鲁格伦克再次向你致意，希望你能再带五个荒芜游荡者水袋来，并为你准备好了一份补给包。",h="操作员鲁格伦克再次向你致意，希望你能再带五个荒芜游荡者水袋来，并为你准备好了一份补给包。",kw={"补给包","操作员鲁格伦克","塔纳利斯","荒芜游荡者水袋","水袋赏金"},sec={{t="再次光临",b="在“水袋赏金”任务之后，鲁格伦克欢迎你的回归，并询问你的背包里是否还有五个荒芜游荡者水袋。如果是，一份写着你名字的补给包已经为你留好了。"},{t="多多益善",b="鲁格伦克对回收的水袋感到满意，因为每一个水袋都能让大家远离灾难。鲁格伦克承诺，你每上交五个水袋，都会得到应有的回报。"}},faq={{q="谁在提供这项赏金任务？",a="加基森的操作员鲁格伦克。",al={"谁提供水袋赏金任务","鲁格伦克任务","谁回收水袋"}},{q="需要多少个水袋？",a="五个荒芜游荡者水袋，和之前一样。",al={"多少个水袋","水袋数量","每次上交的水袋数"}},{q="鲁格伦克准备了什么？",a="一份补给包，专门为你预留的。",al={"什么是补给包","我能得到什么"}},{q="这一步之前是什么？",a="它是之前“水袋赏金”任务的后续，在那项任务中，你首次将水袋带给了鲁格伦克。",al={"前置任务","我首先要做什么"}}},fp="18,141,10.135.0,16.168.1,28.63.0,34.67.0,31.55.0,28.89.0"}
P.entries["quest:1879"] = {n="和彬克交谈",s="玛济斯·石衣派你前往铁炉堡寻找彬克，她的研究需要一位奥术专家。",h="玛济斯·石衣派你前往铁炉堡寻找彬克，她的研究需要一位奥术专家。",kw={"彬克","丹莫罗","秘法大厅","铁炉堡","法师","玛济斯·石衣","秘法区"},ang={["class:Mage"]="身为法师，你告别山谷中的入门训练，投身铁炉堡奥术学者更广阔的研究工作。",["faction:Alliance"]="身为联盟的一员，你在秘法大厅见证侏儒的智慧与矮人的热忱在研究中交融。",["race:Gnome"]="身为侏儒，你看到诺莫瑞根沦陷后，彬克和玛济斯·石衣仍在铁炉堡热情接纳他们的厅堂中延续着侏儒的奥术传统。"},sec={{t="同僚的召唤",b="彬克正在寻找能够施展魔法、协助她开展研究的人。在卡拉诺斯附近，玛济斯·石衣派遣已经完成初步练习的学徒，前去响应彬克的召唤。"},{t="秘法大厅",b="在铁炉堡的秘法区，彬克于秘法大厅中开展研究。学者、牧师和奥术师齐聚于此。她仔细观察每一位前来的学徒，因为在奥术研究中，缺乏自律的天赋可能让施法者变得危险。"}},faq={{q="谁提供这个任务？",a="当来自丹莫罗的联盟新手法师完成初步训练后，玛济斯·石衣便会派他们去找彬克。",al={"任务给予者","任务起点","谁提供和彬克交谈任务"}},{q="在哪里可以找到彬克？",a="彬克位于铁炉堡北部秘法区的秘法大厅中。",al={"彬克位置","彬克在哪里","寻找彬克"}},{q="为什么彬克只需要法师？",a="彬克研究奥术能量和精密的监测设备。她认为，其他职业无法应对其中涉及的魔法细节和危险。",al={"为何仅限法师","法师职业要求","彬克只需要法师"}},{q="见到彬克后会发生什么？",a="彬克向你问候并评估你的能力后，会请你协助她的研究，接下来便是法师文档存储器任务。",al={"下一个任务","彬克后续任务","和彬克交谈后续任务"}},{q="法师以外的职业能接到这个任务吗？",a="不能。彬克的召唤面向法师，引领他们从当地的新手训练迈向主城中的专门研究。",al={"其他职业能否完成","是否仅限法师","法师专属"}},{q="秘法大厅是什么地方？",a="秘法大厅是铁炉堡研究奥术与神圣力量的中心。这里的训练师、学者和研究人员代表着矮人与侏儒的魔法技艺。",al={"铁炉堡秘法大厅","秘法大厅是什么"}}},fx={["96ce9827"]={q="玛济斯·石衣为什么派你去找彬克？",a="玛济斯·石衣是驻守卡拉诺斯的侏儒法师训练师，负责指导成长中的施法者。他在铁炉堡的同僚彬克特意传来消息，请求派遣一名技艺娴熟的法师，参与一项重要任务。玛济斯看出你对奥术的掌握日益精进，便指引你前往矮人的都城，响应她的召唤，继续深造魔法。",al={"玛济斯为何派人","玛济斯·石衣的动机","为何与彬克交谈"}}},fp="15,94,21.170.0,21.245.0,21.122.0,22.75.0,31.143.0,32.134.0,52.104.0,30.162.0"}
P.entries["quest:188"] = {n="猎虎",s="艾耶克·罗欧克在北荆棘谷的一系列狩猎任务中提供了终极挑战。在追踪一只难以捉摸的野兽数周后，他向你发出挑战，要求你找到老虎辛达尔并带回她的爪子。",h="艾耶克·罗欧克在北荆棘谷的一系列狩猎任务中提供了终极挑战。在追踪一只难以捉摸的野兽数周后，他向你发出挑战，要求你找到老虎辛达尔并带回她的爪子。",kw={"艾耶克·罗欧克","猛虎狩猎大师","奈辛瓦里远征队营地","辛达尔的爪子","辛达尔","荆棘谷","猛虎狩猎"},sec={{t="最后的猛虎",b="在完成了之前针对荆棘谷猛虎的试炼后，奈辛瓦里远征队营地的艾耶克·罗欧克为你提供了最后一个挑战。狩猎营地已经在丛林中追踪了一只异常难以捉摸的猛虎，名为辛达尔，时间长达数周。艾耶克向你发出挑战，要求你追踪并击倒这头野兽，夺取她的爪子作为无可辩驳的证据。"},{t="猛虎狩猎大师",b="带着辛达尔的爪子回到奈辛瓦里营地，证明了你无可置疑的追踪技术。艾耶克·罗欧克认可了你的成就，宣布你为真正的猛虎狩猎大师。"}},faq={{q="谁提供了这次狩猎任务？",a="艾耶克·罗欧克，一位驻扎在北荆棘谷奈辛瓦里远征队营地的资深猎人，发布了这次最终的猛虎挑战。",al={"任务发布者","谁发布猛虎狩猎","艾耶克·罗欧克位置"}},{q="辛达尔是什么？",a="辛达尔是一只难以捉摸的猛虎，奈辛瓦里远征队的猎人们已经在荆棘谷的丛林中追踪了她数周。",al={"辛达尔是什么","辛达尔背景故事","辛达尔是谁"}},{q="艾耶克·罗欧克需要什么证据？",a="艾耶克·罗欧克要求你带回辛达尔的爪子，以证明这头野兽确实已被击败。",al={"我需要带回什么","猛虎狩猎证明","辛达尔的爪子"}},{q="这次狩猎之前有什么任务？",a="这次狩猎是艾耶克·罗欧克系列任务的第四步，也是最后一步，紧接在北荆棘谷的第三次猛虎狩猎试炼之后。",al={"前置条件","猛虎狩猎任务线","前序任务"}}},fp="13,188,15.256.0,19.146.1,21.120.0,17.131.0,37.87.0,24.137.0"}
P.entries["quest:1881"] = {n="安娜斯塔西娅",s="在幽暗城，凯恩·火歌派一位前途可期的被遗忘者法师去见安娜斯塔西娅·哈特威尔。她召你前往魔法区，参与被遗忘者法师的实务工作，之后还要前往提瑞斯法林地开展实地调查。",h="在幽暗城，凯恩·火歌派一位前途可期的被遗忘者法师去见安娜斯塔西娅·哈特威尔。她召你前往魔法区，参与被遗忘者法师的实务工作，之后还要前往提瑞斯法林地开展实地调查。",kw={"安娜斯塔西娅·哈特威尔","巴尼尔农场","凯恩·火歌","法师任务","魔法区","幽暗城"},ang={["class:Mage"]="身为法师，你从基础奥术训练迈向实际行动，开始为幽暗城的法师效力。",["race:Undead"]="身为被遗忘者奥术师，你可以运用洛丹伦昔日的学识，对抗如今威胁这片土地的危险。"},sec={{t="魔法区的召唤",b="凯恩·火歌在布瑞尔训练年轻的被遗忘者法师。当他发现某个学生有潜力时，就会派其前往幽暗城。在那里，被遗忘者法师钻研奥术，并筹划洛丹伦各地的防御。凯恩决定哪些学生已经准备好，可以为更有经验的施法者效力。真正有天赋的人会被派去见安娜斯塔西娅·哈特威尔，她需要能干的人手在外执行任务。"},{t="安娜斯塔西娅·哈特威尔的抱负",b="安娜斯塔西娅·哈特威尔是幽暗城杰出的法师训练师之一。她派有潜力的学生参与实际工作，为被遗忘者的利益与领土效力，而非让他们安稳地钻研咒语。响应她的召唤，你便开始在天灾军团肆虐后的岁月里，为被遗忘者法师效力，参与他们的魔法实务。"}},faq={{q="谁派你去与安娜斯塔西娅·哈特威尔交谈？",a="凯恩·火歌是你在布瑞尔的被遗忘者法师训练师。当他认为你的奥术天赋足以应对幽暗城更艰巨的工作时，就会派你去见安娜斯塔西娅·哈特威尔。",al={"谁提供与安娜斯塔西娅交谈","与安娜斯塔西娅交谈任务给予者","凯恩·火歌的召唤"}},{q="在哪里可以找到安娜斯塔西娅·哈特威尔？",a="安娜斯塔西娅·哈特威尔位于幽暗城的魔法区，在那里指导研习奥术的被遗忘者施法者。",al={"安娜斯塔西娅·哈特威尔在哪里","安娜斯塔西娅·哈特威尔位置","寻找安娜斯塔西娅"}},{q="这次召唤的目的是什么？",a="安娜斯塔西娅正在寻找一名能干的施法者，承担城墙之外的实际工作。实地任务从提瑞斯法林地开始，包括调查巴尼尔农场等工作。",al={"她为什么召见","与安娜斯塔西娅交谈目的","安娜斯塔西娅需要什么"}},{q="和安娜斯塔西娅交谈之后是什么任务？",a="向安娜斯塔西娅报到后，她会派你前往提瑞斯法林地东部的巴尼尔农场，从那里的花园中采集金鱼草。",al={"下一个任务是什么","与安娜斯塔西娅交谈之后的任务","与安娜斯塔西娅交谈后续"}},{q="这个任务是否有职业限制？",a="是的。这次召唤面向被遗忘者法师，是他们在十级左右初步掌握本领时，职业训练中的一个环节。",al={"是否为法师专属任务","谁能做与安娜斯塔西娅交谈","职业要求"}},{q="为什么被遗忘者法师在幽暗城设有自己的区域？",a="魔法区为被遗忘者的奥术师、术士和研究者提供了研习与施法的场所，与其他实体区域分开。在洛丹伦地下，他们延续着第三次大战之前的传统。",al={"为什么设有魔法区","被遗忘者法师幽暗城"}}},fp="20,225,27.367.0,29.353.0,47.157.0,38.120.0,36.172.0,40.134.0,41.131.0,67.206.0"}
P.entries["quest:1882"] = {n="巴尼尔农场",s="“巴尼尔农场”是年轻被遗忘者法师早期的一项试炼，由幽暗城法师区的安娜斯塔西娅·哈特威尔指导。新兵们被派往提瑞斯法林地东部，从一座离瘟疫之地边界极其危险的废弃农场中收集金鱼草。这些花卉样本可作为晴雨表，用于检测从天灾军团肆虐的东方蔓延而来的魔法腐蚀。",h="“巴尼尔农场”是年轻被遗忘者法师早期的一项试炼，由幽暗城法师区的安娜斯塔西娅·哈特威尔指导。新兵们被派往提瑞斯法林地东部，从一座离瘟疫之地边界极其危险的废弃农场中收集金鱼草。这些花卉样本可作为晴雨表，用于检测从天灾军团肆...",kw={"安娜斯塔西娅","巴尼尔","农场","哈特威尔","法师","瘟疫之地","金鱼草","提瑞斯法","幽暗城"},ang={["class:Mage"]="这次早期的试炼教会了新手法师，他们对奥术的研究对于监测和防御外来的魔法腐蚀至关重要。",["profession:Herbalism"]="巴尼尔金鱼草提供了一个例子，说明植物样本如何能够成为魔法污染的直接蓄积池和指示器。",["race:Undead"]="对于被遗忘者来说，保护提瑞斯法林地的边界免受天灾军团的侵害，事关他们的生存和主权。"},sec={{t="一种魔法晴雨表",b="尽管皇家药剂师学会经常研究死灵术和腐朽的影响，但被遗忘者的法师们也一直密切注视着边境地区。安娜斯塔西娅·哈特威尔指派新手施法者前往提瑞斯法林地东部的巴尼尔农场。农场花园中土生土长的金鱼草天生对变动的魔法流非常敏感，会从土壤和大气中吸收环境能量。通过检查这些花朵，幽暗城的奥术学者们就能测量巫妖王领地的腐蚀性传染是否已经穿过亡灵壁垒渗透到了提瑞斯法。"},{t="东部边界",b="巴尼尔农场坐落在林地边缘，离西瘟疫之地那片被枯萎病蹂躏的荒野近得令人不安。被遗忘者深知巫妖王的瘟疫是一种无法控制且具有破坏性的力量，会主动腐蚀土地本身。虽然被遗忘者也利用自己的黑暗技艺，但不受控制的天灾军团腐蚀威胁着他们的领土边界和安全。安娜斯塔西娅打算将收集到的金鱼草交给药剂师，将奥术观察与炼金调查结合起来，以保卫洛丹伦收复的核心领土。"}},faq={{q="为什么安娜斯塔西娅·哈特威尔特别需要金鱼草？",a="巴尼尔金鱼草对周围的魔法力量具有独特的天然敏感性。因为它们直接从大地和空气中吸收能量，研究它们可以让被遗忘者法师确定附近的瘟疫之地产生的奥术和死灵枯萎是否正在污染提瑞斯法林地。",al={"为什么选择金鱼草","巴尼尔金鱼草的用途","金鱼草有什么用"}},{q="巴尼尔农场在哪里？",a="该农场位于提瑞斯法林地东部，靠近林地与西瘟疫之地枯萎前线接壤的边界。金鱼草生长在破旧农舍周围杂草丛生的地块和花园里。",al={"巴尼尔农场位置","巴尼尔农场在哪里","寻找巴尼尔农场"}},{q="安娜斯塔西娅·哈特威尔是谁？",a="安娜斯塔西娅·哈特威尔是一位著名的被遗忘者法师和训练师，居住在幽暗城的法师区。她指导新生的亡灵施法者，教导他们纪律、奥术平衡以及针对敌对势力的实际边境防御。",al={"安娜斯塔西娅·哈特威尔背景故事","安娜斯塔西娅是谁"}},{q="为什么被遗忘者法师关心阻止瘟疫？",a="虽然被遗忘者也在试验他们自己的瘟疫和枯萎病，但巫妖王那种具有传染性的天灾魔法被视为一种不受控制的变异。如果不加遏制，天灾军团的腐蚀将吞噬整个提瑞斯法林地，并损害被遗忘者的独立性。",al={"为什么阻止瘟疫","被遗忘者是否憎恨瘟疫"}},{q="收集花朵后会怎样？",a="在收到金鱼草后，安娜斯塔西娅准备将其交给幽暗城的药剂师。炼金术士和法师们会一起解剖这些样本，以评估土壤和植物群受到天灾军团腐蚀的程度。",al={"安娜斯塔西娅如何处理这些花","谁来接收金鱼草"}},{q="这个任务只限法师吗？",a="是的。这项任务是专门为年轻的被遗忘者法师提供的职业任务，他们已经完成了丧钟镇的初步课程，并到达了首都以证明他们对奥术理论的掌握。",al={"巴尼尔农场任务是法师专属吗","法师职业任务"}}},fp="20,208,19.379.0,18.456.0,58.214.0,38.182.0,26.203.0,53.231.0,51.176.0,34.176.0"}
P.entries["quest:1884"] = {n="魂能骨堆",s="在回音群岛，安苏瓦请你摧毁扎拉赞恩的魂能骨堆。它们散发的腐化力量威胁着杜隆塔尔的魔法流动。",h="在回音群岛，安苏瓦请你摧毁扎拉赞恩的魂能骨堆。它们散发的腐化力量威胁着杜隆塔尔的魔法流动。",kw={"杜隆塔尔","回音群岛","魂能骨堆","魔法","森金村","被污染的神像","安苏瓦","扎拉赞恩"},ang={["faction:Horde"]="Un'thuwa说，这是你为族人所做的贡献，你已经向部落的各个职业证明了自己的价值。"},sec={{t="被污染的堆积物",b="森金村的Un'thuwa请你摧毁扎拉赞恩放在回音群岛主岛上、他的小屋之间的堆积物。这些被污染的神像会腐化野生动物，增强术士和地狱生物的力量。如果放任不管，它们可能会永远改变杜隆塔尔的魔法流动。"},{t="Un'thuwa的感知",b="Un'thuwa感应到那些堆积物已经被摧毁。她相信，只要有足够的时间和好运，杜隆塔尔的魔法就会恢复正常流动。她赞扬你为族人所做的事，并说你已经向部落的各个职业证明了自己的价值。"}},faq={{q="是谁放置了魂能骨堆？",a="回音群岛的术士扎拉赞恩将这些被污染的堆积物放在了主岛上他的小屋之间。",al={"谁制造了堆积物","扎拉赞恩的堆积物","ju ju的来源"}},{q="这些堆积物有什么作用？",a="这些堆积物会腐化野生动物，增强术士和地狱生物的力量。",al={"巫毒堆是什么","堆积物的作用","为何摧毁巫毒"}},{q="魂能骨堆在哪里？",a="扎拉赞恩把它们放在了回音群岛主岛上他的小屋之间。",al={"堆积物在哪","回音群岛主岛的堆积物","ju ju的位置"}},{q="是谁请我摧毁它们？",a="森金村的安苏瓦请你摧毁魂能骨堆。",al={"谁交付任务","安苏瓦的请求","谁想清除堆积物"}},{q="这里的杜隆塔尔魔法为何如此重要？",a="这些堆积物扰乱了杜隆塔尔正常的魔法流动。如果它们继续存在，魔法的流动可能会永远改变。",al={"魔法流动","杜隆塔尔魔法","为何关心魔法"}}},fp="11,123,13.261.0,16.225.1,27.96.0,21.74.0,26.58.0,28.64.0,37.95.0"}
P.entries["quest:1885"] = {n="米奈特·卡加德",s="在幽暗城，马里恩·考尔派你向米奈特·卡加德报到。在潜行者区深处，他为亡灵哨兵考验有潜力的密探。",h="在幽暗城，马里恩·考尔派你向米奈特·卡加德报到。在潜行者区深处，他为亡灵哨兵考验有潜力的密探。",kw={"刺客","亡灵哨兵","被遗忘者潜行者","马里恩·考尔","米奈特·卡加德","潜行者区","幽暗城"},ang={["class:Rogue"]="身为潜行者，你响应召唤，从未经考验的扒手，成为获得认可的亡灵哨兵干员，跻身被遗忘者的精英暗影网络。",["race:Undead"]="身为亡灵，你知道亡灵哨兵帮助被遗忘者维系生存。他们猎杀血色十字军的狂热者和Scourge残部，保护Sylvanas女王免受暗中威胁。"},sec={{t="暗影中的召唤",b="马里恩·考尔带来了米奈特·卡加德的召令。在幽暗城，高层首领会留意秘密行动的人员，而当斥候或刺客奉召报到时，马里恩便会传达消息。被遗忘者的情报机构因其致命手段而令人畏惧。违抗它的命令，实在算不上什么选择。"},{t="加入亡灵哨兵",b="米奈特·卡加德在潜行者区等候，在那里观察新兵，判断他们是否已准备就绪。响应他召唤的人，要接受加入亡灵哨兵的考验，这是被遗忘者令人畏惧的间谍与暗杀机构。要在暗影中为黑暗女王效力，首先就得服从命令。"}},faq={{q="米奈特·卡加德是谁？",a="米奈特·卡加德在幽暗城的潜行者区训练潜行者，并监管亡灵哨兵。他留意有潜力的密探，为他们指派替被遗忘者高层执行的重要任务。",al={"米奈特·卡加德背景故事","卡加德是谁"}},{q="无视米奈特·卡加德的召令会有什么后果？",a="马里恩·考尔警告你，不要打听那些无视卡加德召令的人的下场。她没有说明他们究竟遭遇了什么。",al={"无视卡加德","无视召令的后果"}},{q="亡灵哨兵是什么组织？",a="亡灵哨兵是由潜行者、间谍和刺客组成的精英组织，为被遗忘者效力。他们从幽暗城的暗影中出击，消灭重要目标，收集情报，保卫洛丹伦，抵御血色十字军和天灾军团等敌人。",al={"亡灵哨兵背景故事","亡灵哨兵是什么组织"}},{q="在哪里能找到米奈特·卡加德？",a="你可以在幽暗城的潜行者区找到米奈特·卡加德，那里聚集着秘密行动人员、训练师，还有供暗影行者使用的物资。",al={"卡加德位置","米奈特·卡加德在哪里"}},{q="谁会交付寻找米奈特·卡加德的任务？",a="马里恩·考尔在布瑞尔的恐惧之末旅店派你去找米奈特·卡加德。她注意到了你日益精进的技艺，并提醒你，卡加德要求你立即服从。",al={"谁交付这个任务","马里恩·考尔任务"}},{q="向米奈特·卡加德报到后会发生什么？",a="向米奈特·卡加德报到后，你便会直接开始为亡灵哨兵效力。最初的职责是为了证明你的机敏，以及你对被遗忘者事业的忠诚。",al={"卡加德之后的任务","卡加德有何要求"}}},fp="13,149,26.283.0,25.290.0,21.185.0,56.121.0,26.257.0,31.123.0,46.161.0,44.163.0"}
P.entries["quest:1886"] = {n="亡灵哨兵",s="米奈特·卡加德在幽暗城考验有志加入亡灵哨兵的人，派他们去追截一名途经此地的信使。只有冷酷无情的人，才能在瓦里玛萨斯大人的秘密组织中占据一席之地。",h="米奈特·卡加德在幽暗城考验有志加入亡灵哨兵的人，派他们去追截一名途经此地的信使。只有冷酷无情的人，才能在瓦里玛萨斯大人的秘密组织中占据一席之地。",kw={"阿斯托·哈德恩","亡灵哨兵","米奈特·卡加德","潜行者区","银松森林","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="身为被遗忘者盗贼，加入亡灵哨兵就意味着跻身为国效力的最高阶层。在那里，深谙街头生存之道的无赖会立下誓言，成为瓦里玛萨斯和黑暗女王的爪牙。",["faction:Horde"]="作为部落的一员，你或许并不知道亡灵哨兵的行动有多么隐秘。他们维系着至关重要的情报网络，而部落在南方的盟友对被遗忘者内部那些更阴暗的事务大多一无所知。",["race:Undead"]="身为亡灵，你目睹亡灵哨兵以铁腕维护洛丹伦的内部安全。他们既提防被遗忘者之外的敌人，也警惕内部潜在的叛徒。"},sec={{t="暗影中的试炼",b="在潜行者区，米奈特·卡加德为每个想要加入亡灵哨兵的人设下试炼。他们效命于瓦里玛萨斯，是被遗忘者的秘密警察与精锐刺客。有志加入的密探必须展现出机智与谨慎，再证明自己有决心除掉目标。卡加德要将弱者和心存太多顾忌的人拒之门外。"},{t="拦截信使",b="阿斯托·哈德恩带着一封信，往来于幽暗城和银松森林之间的道路上。卡加德让你自行决定如何下手。要取得哈德恩的私人介绍信，你必须拦截他，夺取他的身份证明。这样，亡灵哨兵就能让你冒充他去见安德隆。"}},faq={{q="亡灵哨兵是什么组织？",a="亡灵哨兵是被遗忘者的秘密组织，也是专司潜行与暗杀的精锐分支。他们以幽暗城的潜行者区为据点，搜集情报，开展间谍活动，并执行秘密处决。他们直接向瓦里玛萨斯大人汇报。",al={"亡灵哨兵 背景故事","亡灵哨兵 是什么","亡灵盗贼"}},{q="米奈特·卡加德是谁？",a="米奈特·卡加德是幽暗城潜行者区的一名亡灵哨兵联络官。他负责初期试炼，考验那些希望加入秘密组织的新兵。",al={"米奈特·卡加德 职责","谁提供任务"}},{q="米奈特为什么需要阿斯托·哈德恩的信？",a="阿斯托·哈德恩的介绍信能让一名新特工冒充他的身份。亡灵哨兵可以用它来蒙骗安德隆。",al={"阿斯托·哈德恩 的信","为何拦截信使","阿斯托 的介绍信"}},{q="阿斯托·哈德恩在哪里往来？",a="阿斯托·哈德恩往来于幽暗城和银松森林之间的道路上，为他的联络人传递信件。",al={"阿斯托·哈德恩 路线","阿斯托·哈德恩 位置","阿斯托 在哪里"}},{q="瓦里玛萨斯大人是谁？",a="瓦里玛萨斯大人是一名 纳斯雷兹姆 恐惧魔王，为了保全自身而与希尔瓦娜斯·风行者女王结盟。他坐镇皇家区，负责幽暗城的治安、防务和盗贼行动。",al={"瓦里玛萨斯职责","幽暗城的恐惧魔王"}},{q="这场试炼之后会怎样？",a="通过试炼便证明了特工的能力。接下来是一项秘密冒名任务：递交阿斯托的文书，打入安德隆的交易活动。",al={"接下来是什么","亡灵哨兵 后续任务线"}}},fp="17,175,21.348.0,16.280.1,26.245.0,21.152.0,43.122.0,31.116.0,24.207.0,30.155.1"}
P.entries["quest:189"] = {n="血顶巨魔的耳朵",s="藏宝海湾的科博克在与血顶部族的丛林冲突中不断损失卫兵和密探。开支节节攀升，又得向大财主里维加兹交代，他忧心忡忡，便悬赏招募冒险者，猎杀这些巨魔并带回击杀凭证。",h="藏宝海湾的科博克在与血顶部族的丛林冲突中不断损失卫兵和密探。开支节节攀升，又得向大财主里维加兹交代，他忧心忡忡，便悬赏招募冒险者，猎杀这些巨魔并带回击杀凭证。",kw={"血顶","藏宝海湾","耳朵","科博克","大财主里维加兹","荆棘谷","巨魔"},sec={{t="不断攀升的开支",b="在繁忙的港口藏宝海湾，科博克正面临严峻的经营困境。荆棘谷的当地巨魔一直在丛林中杀害他的密探，他也在与他们的交战中损失了许多最精锐的卫兵。伤亡不断增加，开支也随之攀升，让他焦急万分，不知该如何向大财主里维加兹交代。"},{t="定额悬赏",b="科博克不愿让损失继续扩大，转而寻求外援。他向旅人开出赏金，要他们深入丛林，猎杀血顶巨魔，并带回十五只割下的耳朵，作为这些巨魔已死的确凿证据。"}},faq={{q="科博克是谁？",a="科博克是藏宝海湾的一名地精，他在丛林中派驻了密探和卫兵，必须向大财主里维加兹交代这些人的开销。",al={"科博克","科博克是谁","谁提供 血顶巨魔的耳朵"}},{q="科博克为什么要血顶的耳朵？",a="血顶巨魔一直在丛林中杀害他的密探，还让他在交战中损失了许多最精锐的卫兵。开支不断累积，他却找不到合适的说辞向大财主里维加兹交代。",al={"为什么要耳朵","为什么要 血顶 的耳朵","为什么收集耳朵"}},{q="需要多少只耳朵？",a="科博克要求你交出十五只血顶的耳朵，才会支付报酬。",al={"多少只耳朵","耳朵数量"}},{q="这项悬赏接下来通向哪里？",a="科博克付清血顶耳朵的赏金后，便在《裂颅者的獠牙》中将注意力转向当地的另一股威胁。",al={"接下来是什么","血顶巨魔的耳朵 后续","下一个任务"}}},fp="15,179,14.215.0,16.142.0,13.124.0,36.165.0,27.71.0,33.100.1"}
P.entries["quest:1898"] = {n="亡灵哨兵",s="在幽暗城，亡灵哨兵追查被遗忘者内部的叛乱嫌疑。在瓦里玛萨斯大人的授意下，你冒充一名即将到来的信使，盘问一名可能在资助外部势力的商人。",h="在幽暗城，亡灵哨兵追查被遗忘者内部的叛乱嫌疑。在瓦里玛萨斯大人的授意下，你冒充一名即将到来的信使，盘问一名可能在资助外部势力的商人。",kw={"安德隆·甘特","炼金房","阿斯托·哈德恩","亡灵哨兵","间谍活动","被遗忘者","米奈特·卡加德","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="身为盗贼，你借用一名死者的身份，引出一个疏于防备的密谋者。亡灵哨兵对这种手段十分熟悉。",["faction:Horde"]="身为部落的一员，你知道政治阴谋也延伸到了幽暗城之下。即使在部落疆域之内，信任也十分稀缺。",["race:Undead"]="身为被遗忘者，你知道警惕意味着生存。公民一旦被发现援助外部势力，就有被 黑暗女王 的秘密警察清洗的危险。"},sec={{t="欺诈之网",b="在瓦里玛萨斯大人的授意下，亡灵哨兵米奈特·卡加德开始部署一次潜入行动。亡灵哨兵监视被遗忘者公民时，与防范外部威胁时同样严密。你拿着阿斯托·哈德恩的介绍信，前去接近当地商人安德隆·甘特，这封信可能是伪造的，也可能是设法弄来的。你试图冒充他正在等候的信使。"},{t="炼金房附近的商店",b="安德隆·甘特在炼金房附近经营一家商店。米奈特认为，这位店主没有识破冒名者的头脑。你出示信件后，甘特相信了你的信使身份，放松了警惕。随后，他开始谈起自己与某个身份不明的第三方之间的交易。"}},faq={{q="安德隆·甘特是谁？",a="安德隆·甘特是幽暗城的一名店主，店铺位于炼金房附近。亡灵哨兵和瓦里玛萨斯大人怀疑，他正在向一股不明的外部势力输送情报和援助。",al={"安德隆·甘特","甘特是谁","安德隆·甘特在哪里"}},{q="瓦里玛萨斯大人为何关注这名商人？",a="瓦里玛萨斯大人怀疑，甘特正在与被遗忘者之外的某个组织合作。他想取得有关甘特的联络对象和意图的证据，以保护这座城市，铲除颠覆势力。",al={"瓦里玛萨斯为何关注","瓦里玛萨斯 安德隆·甘特","为何监视安德隆"}},{q="玩家如何欺骗安德隆·甘特？",a="米奈特·卡加德将阿斯托的介绍信交给你。甘特正在等候一名信使，而亡灵哨兵认为他很容易受骗，因此这封信赢得了他的信任。",al={"阿斯托 的信","如何欺骗安德隆·甘特","信使伪装"}},{q="亡灵哨兵是什么组织？",a="亡灵哨兵是被遗忘者的精锐盗贼组织，也是秘密情报机构。他们听命于 希尔瓦娜斯 女王和瓦里玛萨斯大人，在暗影中行动，揭露叛乱、破坏敌方行动，并清除内部威胁。",al={"亡灵哨兵 背景故事","亡灵哨兵 是谁","幽暗城盗贼"}},{q="在哪里可以找到安德隆·甘特？",a="安德隆·甘特在幽暗城炼金房区入口附近的店铺里工作。他在皇家药剂师学会和亡灵哨兵的监视下做生意。",al={"安德隆·甘特位置","甘特的商店在哪里"}},{q="甘特接受信件后会发生什么？",a="甘特毫不怀疑地接受了信件，把你当成了一名没有任何隐瞒的信使。他暗示自己与双方共同的熟人有所合作，让你有机会寻找更多有关他背叛行为的证据。",al={"甘特做什么","甘特的反应"}}},fp="17,205,15.336.0,30.268.1,19.183.0,52.180.0,40.165.0,33.235.0,31.181.0,43.203.1"}
P.entries["quest:1899"] = {n="亡灵哨兵",s="在幽暗城，亡灵哨兵利用安德隆·甘特的信任来对付他。甘特以为你就是他等候的信使，便把一本账本交给你，让你送给他的秘密联络人。你将账本带给了潜行者区的米奈特·卡加德，由此得以为被遗忘者政权执行更深入的秘密任务。",h="在幽暗城，亡灵哨兵利用安德隆·甘特的信任来对付他。甘特以为你就是他等候的信使，便把一本账本交给你，让你送给他的秘密联络人。你将账本带给了潜行者区的米奈特·卡加德，由此得以为被遗忘者政权执行更深入的秘密任务。",kw={"安德隆·甘特","刺客","亡灵哨兵","间谍活动","账本","米奈特·卡加德","潜行者区","幽暗城"},ang={["class:Rogue"]="作为幽暗城的一名盗贼，你可以为米奈特·卡加德递送敏感消息，同时避开不必要的注意，以此展现你的谨慎。",["race:Undead"]="身为亡灵，你明白幽暗城的安全关乎生存。协助亡灵哨兵，可以巩固黑暗女王对首都的控制，抵御生者渗透者和敌对亡灵。"},sec={{t="暗影中的信使",b="安德隆·甘特在幽暗城用一本私人账本记录姓名和情报。他以为你就是他等候的信使，便把账本交给你，让你送给他的秘密联络人。甘特要求今后的消息也由同一名信使传递。他并不知道，这本账本将落入亡灵哨兵手中。"},{t="潜行者区的情报",b="米奈特·卡加德在潜行者区收到甘特的账本，发现其中有用的情报比预想的更多。账本中的细节为卡加德提供了线索，让亡灵哨兵得以扩大调查范围。被遗忘者的国度戒备森严，这些记录或许能帮助他们及早发现境内的颠覆活动与境外的威胁，防止其波及首都。"}},faq={{q="安德隆的账本里有什么？",a="安德隆·甘特的账本中保存着他搜集的敏感信息和记录。米奈特·卡加德从中发现的细节和有价值的情报，比亡灵哨兵预想的更多。",al={"安德隆的账本内容","账本写了什么","亡灵哨兵 账本"}},{q="亡灵哨兵是什么组织？",a="亡灵哨兵是被遗忘者的秘密组织兼刺客公会。他们以幽暗城的潜行者区为基地，充当希尔瓦娜斯·风行者女士的耳目与暗中利刃。他们在洛丹伦各地从事间谍活动、搜集情报，并执行定点暗杀。",al={"亡灵哨兵 背景故事","亡灵哨兵 是谁","幽暗城盗贼"}},{q="甘特为什么希望今后仍由同一名信使送信？",a="甘特希望今后的敏感文件由他信任的信使递送。使用同一名信使可以维持双方的合作安排，也能降低文件遭窃或被篡改的风险。",al={"甘特为什么喜欢你","安德隆·甘特的信任","甘特的信使"}},{q="米奈特·卡加德是谁？",a="米奈特·卡加德是亡灵哨兵驻潜行者区的一名特工。他协调当地特工的行动，从安德隆·甘特这样的线人手中搜集实地情报，并指挥遍及首都及周边地区的秘密任务。",al={"米奈特·卡加德 背景故事","卡加德 是谁"}},{q="潜行者区位于何处？",a="潜行者区位于幽暗城南部。这里是被遗忘者潜行特工、窃贼和刺客的主要基地，设有训练场和阴暗的隐蔽角落，远离上层废墟中的公共广场。",al={"潜行者区 位置","潜行者区 在哪里","幽暗城 潜行者区"}},{q="被遗忘者为什么需要内部情报机构？",a="被遗忘者需要内部情报来揭露洛丹伦境内的颠覆活动。亡灵哨兵致力于帮助这个年轻的国家抵御 天灾军团、血色十字军、心怀戒备的联盟残余势力，以及渗透和叛乱带来的威胁。",al={"亡灵哨兵 为何存在","被遗忘者 间谍","幽暗城情报"}}},fp="17,280,24.297.0,35.334.1,27.170.0,26.272.0,55.170.0,21.242.0,37.231.0,57.245.0"}
P.entries["quest:19"] = {n="萨瑞尔祖恩",s="在石堡要塞附近，治安官马瑞斯悬赏捉拿萨瑞尔祖恩，他麾下的斥候不断袭扰道路。除掉他是打破黑石氏族对赤脊山北部控制的关键一步，而将他的首级带回湖畔镇，则标志着镇上的守卫赢得了一场艰苦的胜利。",h="在石堡要塞附近，治安官马瑞斯悬赏捉拿萨瑞尔祖恩，他麾下的斥候不断袭扰道路。除掉他是打破黑石氏族对赤脊山北部控制的关键一步，而将他的首级带回湖畔镇，则标志着镇上的守卫赢得了一场艰苦的胜利。",kw={"黑石","湖畔镇","治安官马瑞斯","斥候","赤脊山","石堡","石堡要塞","萨瑞尔祖恩"},ang={["faction:Alliance"]="湖畔镇基本处于孤立无援的境地，没有来自暴风城的直接增援。悬赏捉拿萨瑞尔祖恩，是当地为避免城镇遭到围困而采取的重要措施。",["race:Human"]="身为人类，赤脊山的黑石势力让你想起First and Second Wars。杀死萨瑞尔祖恩，就是夺回王国遭侵占的土地。",["race:Orc"]="身为兽人，你面对的萨瑞尔祖恩是黑石旗下一名Old Horde的黑暗余孽，他所侍奉的主人拒绝接受萨尔在大洋彼岸建立的新秩序。"},sec={{t="通往石堡之路",b="湖畔镇与石堡要塞之间的山道已是危机四伏，伏击随时可能发生。黑石斥候和叛徒在岩石嶙峋的山脊间游荡，截击侦察兵，威胁试图赶往要塞的援军。治安官马瑞斯指出，萨瑞尔祖恩正是这些协同袭击背后的指挥官。他说，必须除掉萨瑞尔祖恩，否则湖畔镇可能会被彻底围困。"},{t="斥候斩首行动",b="萨瑞尔祖恩是个危险的战场指挥官：凶残、狡诈，还能将散乱的兽人劫掠者集结成一支精干的突袭部队。要在石堡的阴影下取下他的首级，你必须杀穿黑石严密设防的前哨。他的死使斥候巡逻队失去协同，为联盟扫清道路，迎战要塞内的驻军。"}},faq={{q="萨瑞尔祖恩是谁？",a="萨瑞尔祖恩是一名强悍的黑石兽人指挥官，率领斥候和叛徒，在湖畔镇与石堡要塞之间的小径上设伏。",al={"萨瑞尔祖恩是谁","萨瑞尔祖恩背景故事","萨瑞尔祖恩首领"}},{q="在哪里可以找到萨瑞尔祖恩？",a="萨瑞尔祖恩位于赤脊山东北部的石堡要塞附近，指挥斥候巡逻周围的山道和前哨。",al={"萨瑞尔祖恩在哪里","萨瑞尔祖恩位置","寻找萨瑞尔祖恩"}},{q="治安官马瑞斯为什么要他的首级？",a="玛瑞斯认为，萨瑞尔祖恩就是指挥伏击、袭扰赤脊山的狡诈战术家。他要求带回萨瑞尔祖恩的首级，以铲除斥候的指挥者，并证明威胁已被消灭。",al={"为什么杀萨瑞尔祖恩","萨瑞尔祖恩悬赏原因"}},{q="击败萨瑞尔祖恩之后会发生什么？",a="击败萨瑞尔祖恩会重创斥候的协同能力，让湖畔镇的守军和冒险者得以深入石堡要塞，迎战黑石驻军的主力。",al={"萨瑞尔祖恩后续任务","萨瑞尔祖恩之后是什么"}},{q="黑石兽人为什么会出现在赤脊山？",a="黑石氏族的残部从燃烧平原南下，进入赤脊山。他们加固了石堡要塞等人类旧哨所，趁暴风城兵力捉襟见肘之际，威胁东部王国。",al={"黑石兽人为什么在赤脊山","石堡兽人背景"}},{q="追杀萨瑞尔祖恩之前必须完成什么前置任务？",a="治安官马瑞斯派你追杀萨瑞尔祖恩之前，会要求你在“黑石氏族的威胁”任务中削减入侵部队的兵力，证明自己的实力。",al={"萨瑞尔祖恩前置任务","如何解锁萨瑞尔祖恩任务"}}},fp="10,267,22.374.0,27.334.0,18.149.0,30.130.0,38.197.0,42.184.0,45.212.0,62.141.0"}
P.entries["quest:190"] = {n="猎豹",s="奈辛瓦里远征队营地的埃尔加丁爵士为那些想要证明自己是荆棘谷大型狩猎追踪者的冒险者们提供了一项试炼。为了加入赫米特的狩猎团，冒险者们必须先猎杀十只幼年黑豹，以此证明他们最基本的追踪能力。",h="奈辛瓦里远征队营地的埃尔加丁爵士为那些想要证明自己是荆棘谷大型狩猎追踪者的冒险者们提供了一项试炼。为了加入赫米特的狩猎团，冒险者们必须先猎杀十只幼年黑豹，以此证明他们最基本的追踪能力。",kw={"赫米特","奈辛瓦里","黑豹的掌控","埃尔加丁爵士","荆棘谷","幼年黑豹"},sec={{t="精英猎手小队",b="在荆棘谷北部广袤的荒野中，赫米特·奈辛瓦里集结了一群经验丰富的大型猎物猎人。任何想要参与狩猎的人，埃尔加丁爵士都会告诉他们：必须先证明自己是一名合格的黑豹猎手。"},{t="追踪潜行者",b="在埃尔加丁把更重要的猎物交给任何人之前，他会发布一个入门测试：找到并杀死十只幼年黑豹。仅仅找到这些野兽只是挑战的一半。"}},faq={{q="谁发布了这个狩猎挑战？",a="埃尔加丁爵士在荆棘谷北部的奈辛瓦里远征队营地发布了这个挑战，旨在测试想要加入赫米特狩猎队的后来者。",al={"黑豹的掌控任务发布者","谁开启黑豹的掌控","埃尔加丁任务"}},{q="需要猎杀什么猎物？",a="埃尔加丁爵士要求猎人们追踪并杀死潜伏在周围丛林灌木丛中的十只幼年黑豹。",al={"黑豹的掌控杀什么","黑豹的掌控目标","幼年黑豹"}},{q="为什么埃尔加丁爵士要布置这个测试？",a="赫米特·奈辛瓦里聚集了一支经验丰富的狩猎队，而埃尔加丁希望新人在加入狩猎之前证明自己是合格的黑豹猎手。",al={"为什么要杀幼年黑豹","黑豹的掌控目的"}},{q="完成这次狩猎后接下来要做什么？",a="完成这个入门试炼后直接开启“黑豹的掌控（2）”，届时埃尔加丁爵士会提高猎物的难度。",al={"黑豹的掌控后续任务","黑豹的掌控之后是什么"}}},fp="15,166,24.181.0,21.163.0,33.161.0,27.79.0,45.135.0,43.87.0"}
P.entries["quest:191"] = {n="猎豹",s="埃尔加丁爵士要求你证明自己有资格与奈辛瓦里远征队营地的大型猎物猎手为伍。在你初步清剿了年幼的野兽之后，他要你前往荆棘谷的荒野，追踪并杀死十只成年黑豹。",h="埃尔加丁爵士要求你证明自己有资格与奈辛瓦里远征队营地的大型猎物猎手为伍。在你初步清剿了年幼的野兽之后，他要你前往荆棘谷的荒野，追踪并杀死十只成年黑豹。",kw={"大型猎物","艾尔加丁","狩猎","精通","奈辛瓦里","黑豹","荆棘谷"},sec={{t="更高的标准",b="在你消灭了丛林中的幼年黑豹之后，埃尔加丁爵士要求你挑战更强的猎物。为了证明你有资格与经验丰富的大型猎物猎手为伍，你被派去猎杀十只成年黑豹，它们比年幼的同类强悍得多，也危险得多。"}},faq={{q="谁提出了这项试炼？",a="埃尔加丁爵士是一位驻扎在荆棘谷北部奈辛瓦里远征队营地的猎人，负责这一阶段的狩猎。",al={"谁给予猎豹任务","埃尔加丁任务","任务给予者"}},{q="要求你猎杀什么猎物？",a="你需要在周围的丛林中追踪并击杀十只成年黑豹，它们比先前猎杀的幼年黑豹更加强悍。",al={"要杀什么黑豹","哪些野兽","猎豹目标"}},{q="这项挑战之前是什么？",a="在此之前还有一项同样名为猎豹的试炼，艾尔加丁让你猎杀丛林中的幼年黑豹，以此考验你的胆识。",al={"前一个任务","上一步","猎豹前置任务"}},{q="猎杀这些黑豹的目的是什么？",a="埃尔加丁爵士要求你证明自己具备足够的技巧和毅力，能够与远征队中经验丰富的大型猎物猎手交往并一同狩猎。",al={"为什么杀黑豹","埃尔加丁的动机","奈辛瓦里的目的"}}},fp="15,204,17.279.0,22.120.0,34.140.0,33.97.0,46.144.0"}
P.entries["quest:1918"] = {n="被污染的水元素",s="在密斯特拉湖周围，你从被杀死的元素身上发现了发光的污水球。你带着一份样本前往碎木岗哨，交给马斯托克·维尔西斯，想要查明是什么毒害了湖水与其中的元素之灵。",h="在密斯特拉湖周围，你从被杀死的元素身上发现了发光的污水球。你带着一份样本前往碎木岗哨，交给马斯托克·维尔西斯，想要查明是什么毒害了湖水与其中的元素之灵。",kw={"灰谷","被污染的水球","被腐化的元素","大地之环","马斯托克·维尔西斯","密斯特拉湖","碎木岗哨"},ang={["class:Shaman"]="身为萨满祭司，你听得见密斯特拉湖中扭曲的元素之灵发出的痛苦呼声，也知道大地之环必须介入。",["faction:Horde"]="身为部落的一员，你知道，在联盟哨兵和熊怪威胁着部落补给线的同时，碎木岗哨不能再任由元素在自己的后方构成威胁。",["race:Tauren"]="身为牛头人，你深感治愈大地上遭到腐化的水源是族人赋予你的责任，因此，恢复密斯特拉湖的纯净成了一项刻不容缓的灵性使命。"},sec={{t="密斯特拉湖的污水",b="密斯特拉湖位于灰谷中南部，湖中的水元素变得异常狂暴，显露出明显的腐化迹象。它们死后留下的并非纯净的元素精华，而是散发着强烈光芒、充满腐臭液体的奇异球体。这些水球蕴含着笼罩湖泊的腐化力量，表明这一切并非只是出于守卫领地的天性。"},{t="寻求碎木的指点",b="部落斥候前往碎木岗哨寻求指点，马斯托克·维尔西斯负责管理这座岗哨。他对这份污秽的样本感到十分厌恶。马斯托克·维尔西斯 是一名士兵，而非学者，他知道寻常刀剑无法净化染病的湖水，于是指引你去找大地之环中精通元素之道的人。"}},faq={{q="被污染的水球里有什么？",a="被污染的水球中浓缩着毒害密斯特拉湖的腐化物质，令人作呕。它由被杀死的元素凝成，表明它们灵魂中的腐化已经化为有形且强大的存在。",al={"被污染的水球内容物","水球里有什么","密斯特拉湖水球"}},{q="这个任务从哪里开始？",a="你在灰谷中南部的密斯特拉湖与狂怒或被污染的水元素战斗时，会发现这种水球。",al={"哪里能找到水球","如何开始 被污染的元素","任务起点"}},{q="为什么马斯托克·维尔西斯不愿插手此事？",a="马斯托克·维尔西斯是一名部落军官，专注于碎木岗哨的生存与后勤事务。他并不擅长查明魔法之水染病的原因，因此指引你去找大地之环。",al={"马斯托克 是谁","为何找 马斯托克 交谈","马斯托克·维尔西斯的职责"}},{q="大地之环为何关注此事？",a="大地之环是一个萨满祭司组织，致力于研究、安抚元素，并使它们重归和谐。密斯特拉湖中那些遭到腐化的元素，正是他们在灵性上需要照料的对象。",al={"为何找大地之环","与大地之环的关联","大地之环是什么组织"}},{q="接下来要去哪里调查？",a="马斯托克 指引你去找耶努萨克雷，一位驻守在灰谷西海岸 佐拉姆加海岸 的大地之环萨满祭司。耶努能够检验这件受到污染的遗物。",al={"接下来是什么","被污染的元素 后续任务","接下来去哪里"}}},fp="20,197,30.323.0,30.288.1,40.214.0,28.114.0,53.201.0,44.190.0,39.164.1"}
P.entries["quest:192"] = {n="猎豹",s="奈辛瓦里远征队营地的埃尔加丁爵士向大型猎物猎人们发起挑战，要求他们追踪并猎杀荆棘谷中最致命的豹子。继你之前的试炼之后，你现在必须寻找并杀死十只影牙豹。",h="奈辛瓦里远征队营地的埃尔加丁爵士向大型猎物猎人们发起挑战，要求他们追踪并猎杀荆棘谷中最致命的豹子。继你之前的试炼之后，你现在必须寻找并杀死十只影牙豹。",kw={"大型猎物","奈辛瓦里","豹子大师","影牙豹","埃尔加丁爵士","荆棘谷"},ang={["class:Hunter"]="埃尔加丁直接向你作为大型猎物猎人的声望发起挑战，期待你精通这种丛林中最凶猛掠食者的追踪与猎杀。"},sec={{t="最致命的猎物",b="埃尔加丁爵士认为影牙豹是徘徊在荆棘谷丛林中最危险的猫科动物。要证明你作为一名真正追踪者的实力，你需要穿过茂密的灌木丛，追踪并猎杀十只这种难以捉摸的野兽，它们凶猛的习性使得猎杀它们比找到它们要困难得多。"}},faq={{q="谁提供了这次狩猎？",a="埃尔加丁爵士在北荆棘谷的奈辛瓦里远征队营地提供了这项挑战。",al={"谁给予豹子大师任务","豹子大师任务给予者","谁给予此任务"}},{q="你要猎杀什么野兽？",a="你需要猎杀十只影牙豹，埃尔加丁称它们为整个荆棘谷中最致命的豹子。",al={"我要杀什么","豹子大师的目标","哪种豹子"}},{q="这在狩猎试炼中处于什么位置？",a="这是豹子狩猎系列试炼中的第三个任务，紧接在第二个豹子大师试炼之后，在第四个试炼之前。",al={"在此任务之前的任务是什么","豹子大师任务链","前置任务"}}},fp="15,145,20.247.0,21.103.0,28.101.0,42.102.0"}
P.entries["quest:1920"] = {n="Investigate the Blue Recluse",s="詹妮亚·坎农请你调查蓝色隐士旅店里奇怪的隐形生物。她担心那里出现了一道法力裂隙。",h="詹妮亚·坎农请你调查蓝色隐士旅店里奇怪的隐形生物。她担心那里出现了一道法力裂隙。",kw={"蓝色隐士","显形卷轴","收容箱","隐形生物","詹妮亚·坎农","法师区","法力裂隙"},ang={["class:Mage"]="身为法师，你将捕获的生物带给詹妮亚·坎农，以供研究。"},sec={{t="蓝色隐士旅店",b="詹妮亚·坎农报告说，法师区的蓝色隐士旅店出现了异常。如今，隐形生物在旅店里游荡，她担心那里已经形成了一道法力裂隙。你受命让这些生物显形，再用收容箱捕获它们。詹妮亚需要研究捕获的生物。"}},faq={{q="蓝色隐士旅店发生了什么？",a="隐形生物正在蓝色隐士旅店里游荡，詹妮亚·坎农担心那里已经形成了一道法力裂隙。",al={"蓝色隐士异常","旅店出了什么事"}},{q="是谁派我去调查的？",a="詹妮亚·坎农请你调查蓝色隐士旅店的异常情况。",al={"谁委托的","詹妮亚蓝色隐士"}},{q="詹妮亚为什么需要这些生物？",a="詹妮亚想研究这些生物，查明它们为何来到这里。",al={"为何捕获它们","这些生物有何用途"}},{q="我该如何让这些生物显形？",a="显形卷轴能让旅店里的这些生物显形。",al={"卷轴用途","让生物显形"}},{q="詹妮亚担心发生了什么？",a="詹妮亚担心蓝色隐士旅店已经形成了一道法力裂隙。",al={"法力裂隙旅店","蓝色隐士裂隙"}}},fp="28,133,19.289.0,38.105.0,27.74.0,35.66.0,36.77.0,35.56.0"}
P.entries["quest:193"] = {n="猎豹",s="在荆棘谷北部，埃尔加丁爵士向你提出了猎豹行动的最后一项试炼。你已在猎杀当地黑豹的过程中证明了自己的身手，如今你要寻找巴尔瑟拉，这头行踪不定的猛兽至今仍未被远征队的猎手捕获。带回这头猛兽的牙齿，就能确立你作为狩猎大师的地位。",h="在荆棘谷北部，埃尔加丁爵士向你提出了猎豹行动的最后一项试炼。你已在猎杀当地黑豹的过程中证明了自己的身手，如今你要寻找巴尔瑟拉，这头行踪不定的猛兽至今仍未被远征队的猎手捕获。带回这头猛兽的牙齿，就能确立你作为狩猎大师的地位...",kw={"巴尔瑟拉","巴尔瑟拉的牙齿","奈辛瓦里远征队营地","猎豹","埃尔加丁爵士","荆棘谷"},sec={{t="行踪不定的潜猎者",b="在奈辛瓦里远征队营地，埃尔加丁爵士认为你的试炼已接近尾声。只剩最后一头猎物，便能证明你有实力对付丛林中的掠食者：一头名叫巴尔瑟拉的黑豹。这头猛兽在荆棘谷的荒野中游荡，至今仍未被远征队自己的猎手捕获。埃尔加丁爵士要你追踪这头强大的潜猎者，取回巴尔瑟拉的牙齿，作为你身手的证明。"}},faq={{q="谁提供这项狩猎任务？",a="埃尔加丁爵士在荆棘谷北部的奈辛瓦里远征队营地提出这项挑战。",al={"任务给予者","谁提供猎豹","埃尔加丁爵士的任务"}},{q="要猎杀什么猛兽？",a="猎物是巴尔瑟拉，一头在丛林中游荡的大黑豹，至今仍未被远征队的猎手捕获。",al={"目标是什么","巴尔瑟拉是谁","黑豹目标"}},{q="需要带回什么战利品？",a="埃尔加丁爵士要求你带回巴尔瑟拉的牙齿，作为击败这头猛兽的证据。",al={"需要什么证明","需要什么物品","巴尔瑟拉的战利品"}},{q="这次狩猎之前是什么任务？",a="这项挑战接续猎豹系列的第三项试炼，在先前猎杀黑豹的基础上展开。",al={"前置任务","猎豹前置任务"}}},fp="15,243,19.234.0,21.94.0,27.105.0,24.88.0,27.103.0"}
P.entries["quest:1938"] = {n="乌尔的暗影魔法研究论文",s="“乌尔的暗影魔法研究论文”是一个由暴风城法师区的高阶法师安多玛斯发布的任务。他派遣冒险者从叛逃法师摩根斯手中夺回一本被魔法封印的禁忌典籍，摩根斯带着它逃到了赤脊山的伊尔加拉之塔。",h="“乌尔的暗影魔法研究论文”是一个由暴风城法师区的高阶法师安多玛斯发布的任务。他派遣冒险者从叛逃法师摩根斯手中夺回一本被魔法封印的禁忌典籍，摩根斯带着它逃到了赤脊山的伊尔加拉之塔。",kw={"安多玛斯","伊尔加拉","摩根斯","暗影魔法","暴风城","论文","乌尔","法师圣殿"},ang={["class:Mage"]="暴风城的法师们非常重视内部纪律问题，他们委托受信任的施法者清理一名堕落至禁忌暗影魔法的同僚所造成的危险后果。",["class:Warlock"]="虽然肯瑞托和暴风城的法师们对乌尔关于暗影的研究感到恐惧，但术士们却经常觊觎书中封印的跨位面召唤和黑暗施法的力量。",["faction:Alliance"]="找回被盗的典籍既能保障赤脊山的边境免受摩根斯日益增长的魔法威胁，又能保护暴风城王国免受流亡奥术的侵害。"},sec={{t="塔中的分裂",b="很久以前，三位前途无量的法师曾在暴风城的法师区共同学习。随着时间推移，其中一人，摩根斯，屈服于黑暗艺术和暗影魔法的诱惑。尽管他的同伴们苦苦规劝他远离这种腐蚀性的力量，但他拒绝放弃自己的执念。他被正式逐出了城市的魔法组织，但他并没有空手而归——他偷走了一部由乌尔撰写的危险著作，乌尔是一位臭名昭著的大法师，他的研究超出了正统奥术的范畴。"},{t="堕落法师的巢穴",b="摩根斯在远离暴风城监视的地方建立了一个新的据点，占据了赤脊山高处的伊尔加拉之塔。高阶法师安多玛斯绝不能允许这种危险的知识留在一个修炼禁忌魔法的叛徒手中。安多玛斯委托联盟冒险者突破塔楼的防御，旨在封印被破解之前找回这本典籍。"},{t="完好的封印",b="在从伊尔加拉的图书馆找回论文并将其带回法师圣殿后，安多玛斯深感宽慰。他曾担心摩根斯已经解开了书中的保护性附魔，或者将其藏到了无法触及的地方。幸运的是，施加在“乌尔的暗影魔法研究论文”上的魔法封印依然稳固，阻止了这位流亡法师释放书中蕴含的灾难性秘密。"}},faq={{q="这篇论文是谁写的？",a="这篇论文由乌尔撰写，他是一位传奇的达拉然法师，以其对跨位面实体和暗影魔法的深奥研究而闻名。",al={"谁是乌尔","论文作者","乌尔的暗影魔法研究论文作者"}},{q="是谁偷走了“乌尔的暗影魔法研究论文”？",a="摩根斯，一位暴风城的前法师，他在堕落于黑暗魔法并被逐出法师圣殿时偷走了这本书。",al={"谁偷了这本书","谁拿走了论文","摩根斯的书"}},{q="这本书存放在哪里？",a="这本书存放在伊尔加拉之塔内的图书馆里，塔楼高耸在赤脊山，摩根斯在那里建立了他的新避难所。",al={"论文在哪里","伊尔加拉之塔的书籍位置","乌尔的论文在哪里找到"}},{q="摩根斯读过这本书吗？",a="没有。当论文被归还给高阶法师安多玛斯时，他确认施加在书上的保护封印依然稳固，这意味着摩根斯从未成功打开过它。",al={"摩根斯打开书了吗","论文被打开了吗","封印破了吗"}},{q="为什么暴风城的法师要收回这本书？",a="这本典籍包含了暗影魔法的深奥秘密，可能会给未经训练的人带来毁灭。暴风城的法师们认为，让它留在像摩根斯这样的叛徒手中实在太危险了。",al={"为什么要回收这本书","为什么论文很危险","安多玛斯的目标"}},{q="谁发布了这个任务？",a="该任务由高阶法师安多玛斯提供，他位于暴风城法师区的法师圣殿内。",al={"任务发布者","在哪里接乌尔的论文任务","安多玛斯的任务"}}},fx={["705e1c6d"]={q="乌尔的暗影魔法研究论文是什么？",a="这是一本力量强大而又危险的典籍，探索着暗影魔法的黑暗奥秘。它由肯瑞托法师Ur撰写，未经训练者不应触及其中的深奥内容，因为钻研这些禁忌知识可能直接招致毁灭与灾祸。为防止它被滥用，暴风城的法师们用魔法封印将这本书封存起来。",al={"乌尔的暗影魔法研究论文","研究论文是什么","ur的研究论文有什么用"}}},fp="29,173,21.306.0,22.300.0,12.300.1,23.129.0,40.138.0,23.129.0,37.130.1,49.191.0,21.87.0"}
P.entries["quest:1939"] = {n="高阶巫师安多玛斯",s="高等法师安多玛斯是一个简短的召唤，旨在引导联盟法师前往暴风城法师区的高塔顶端。高等法师安多玛斯是除了在废墟中的达拉然以外，王国中最杰出的大法师之一。",h="高等法师安多玛斯是一个简短的召唤，旨在引导联盟法师前往暴风城法师区的高塔顶端。高等法师安多玛斯是除了在废墟中的达拉然以外，王国中最杰出的大法师之一。",kw={"安多玛斯","奥术","达拉然","詹妮亚·坎农","法师区","暴风城","法师区高塔"},ang={["class:Mage"]="这次召唤标志着从詹妮亚·坎农指导下的常规法术练习，过渡到与暴风城最顶尖的大法师之一共同研究危险、专业的知识。",["faction:Alliance"]="随着达拉然的幸存法师们全神贯注于重建他们被毁的城市，联盟在很大程度上依赖暴风城自己的法师区来培养法师并对抗超自然的威胁。"},sec={{t="前往高塔的召唤",b="在暴风城的法师区内，学徒协调员詹妮亚·坎农会将有前途的施法者指引至法师区高塔的顶端。高等法师安多玛斯是南部王国中依然活跃的最资深的奥术施法者之一，他特别要求与那些准备好承担更重责任的初露锋芒的法师进行面谈。"},{t="达拉然之外的大师",b="随着北方魔法王国达拉然在第三次战争中沦为废墟，幸存的巫师们全都忙于重建工作，像安多玛斯这样的施法者就具有了至关重要的战略意义。由于无法轻易接触到紫罗兰城堡的图书馆，联盟只能直接依靠驻扎在暴风城内的资深大法师来研究古代威胁，并指导对阴暗、禁忌艺术的研究。"}},faq={{q="高等法师安多玛斯是谁？",a="高等法师安多玛斯是一位受人尊敬的资深法师，居住在暴风城法师区的高塔顶端。他的同僚公认他是达拉然之外，世界上最强大、知识最渊博的活跃施法者之一。",al={"安多玛斯是谁","安多玛斯背景故事","暴风城高等法师"}},{q="我在哪里可以找到高等法师安多玛斯？",a="他位于暴风城法师区螺旋高塔的顶端。",al={"安多玛斯位置","安多玛斯在哪里","找到高等法师安多玛斯"}},{q="詹妮亚·坎农为什么要让我去找他？",a="詹妮亚·坎农会发掘那些已经超越了基础指导水平、有前途的施法者，并将他们送往安多玛斯那里，以获得更高级的建议和进行专门的危险研究任务。",al={"为什么要找安多玛斯谈话","詹妮亚·坎农的引荐"}},{q="安多玛斯需要什么帮助？",a="安多玛斯招募有能力的法师来调查黑暗的奥术秘密，具体来说是派遣他们去取回一本危险的历史文献：《乌尔的暗影魔法研究论文》。",al={"安多玛斯任务线","安多玛斯想要什么"}},{q="为什么说达拉然“与世隔绝”？",a="詹妮亚的话反映了肯瑞托自第三次战争以来一直处于隐居状态。在天灾军团和燃烧军团摧毁了他们的城市后，达拉然的幸存巫师们转而专注于重建工作，很少有人参与外界事务。",al={"为什么达拉然与世隔绝","达拉然现状","达拉然发生了什么"}},{q="这个任务是法师专属的吗？",a="是的。这个召唤是联盟法师在进阶职业道路上专属训练和任务的一部分。",al={"非职业法师能做这个吗","法师专属任务"}}},fx={["56d3f2e8"]={q="詹妮亚·坎农为什么派我去，而不亲自处理？",a="詹妮亚·坎农在巫师圣殿担任导师，指导成长中的奥术施法者。高阶巫师安多玛斯特意要求与你交谈，因为你是一名技艺有成、崭露头角的法师，已经准备好接触更高深的事务，无须让学院的导师们放下教学职责。",al={"为何派我","詹妮亚为何不去","安多玛斯为何找我"}}},fp="23,179,20.301.0,24.281.0,31.191.0,41.104.0,42.142.0,35.154.1,42.229.0,33.87.0"}
P.entries["quest:194"] = {n="猎龙",s="在荆棘谷北部的探险营地中，赫米特·奈辛瓦里向过往的旅行者发出挑战，要求他们证明自己在荒野中的实力。这位著名的猎人要求击杀十只荆棘谷迅猛龙，以测试你是否具备真正的狩猎天赋。",h="在荆棘谷北部的探险营地中，赫米特·奈辛瓦里向过往的旅行者发出挑战，要求他们证明自己在荒野中的实力。这位著名的猎人要求击杀十只荆棘谷迅猛龙，以测试你是否具备真正的狩猎天赋。",kw={"大型猎物猎人","赫米特·奈辛瓦里","迅猛龙狩猎","荆棘谷迅猛龙","荆棘谷"},ang={["class:Hunter"]="对于那些走在猎人道路上的人来说，赫米特·奈辛瓦里在荒野中的试炼是检验追踪和射击技巧的经典试金石。"},sec={{t="技能测试",b="在完成“欢迎来到丛林”任务并抵达丛林后，赫米特·奈辛瓦里会提出测试你的追踪和狩猎能力。他没有提供地图或方向指引，而是坚持认为亲自找到荆棘谷迅猛龙也是考验的一部分，并挑战你深入灌木丛，猎杀十只凶猛的野兽。"}},faq={{q="谁发布了这个狩猎挑战？",a="驻扎在荆棘谷北部探险营地的著名大型猎物猎人赫米特·奈辛瓦里发布了这项挑战。",al={"谁发布了迅猛龙狩猎","迅猛龙狩猎任务发布者","赫米特·奈辛瓦里迅猛龙"}},{q="你需要追踪哪些野兽？",a="你需要追踪并击杀散布在丛林荒野中的十只荆棘谷迅猛龙。",al={"哪种迅猛龙","迅猛龙狩猎要杀什么","迅猛龙狩猎的目标"}},{q="为什么赫米特拒绝告诉你迅猛龙的栖息地？",a="赫米特认为，追踪并定位猎物是成为一名真正的大型猎物猎人必经的考验，因此他让你完全依靠自己去寻找。",al={"迅猛龙在哪里","为什么不给迅猛龙的位置","迅猛龙位置"}},{q="这项考验之前有什么任务？",a="这项狩猎考验是在荒野中的初步问候任务“欢迎来到丛林”之后进行的。",al={"迅猛龙狩猎的前置条件","迅猛龙狩猎的前置任务","迅猛龙狩猎任务线起点"}}},fp="14,134,15.245.0,33.122.0,40.92.0,57.120.0,34.80.0"}
P.entries["quest:1940"] = {n="新鲜的蜘蛛丝",s="“新鲜的蜘蛛丝”是暴风城高阶法师安多玛斯委托给联盟新晋法师的一项试炼任务。为了获得与精通者身份相符的服装，施法者会被派遣至阴暗的暮色森林，从腐食隐居者身上采集优质的蛛丝。收集到的丝线需送往法师区的裁缝维恩·拉尔森处，以制作附魔长袍。",h="“新鲜的蜘蛛丝”是暴风城高阶法师安多玛斯委托给联盟新晋法师的一项试炼任务。为了获得与精通者身份相符的服装，施法者会被派遣至阴暗的暮色森林，从腐食隐居者身上采集优质的蛛丝。收集到的丝线需送往法师区的裁缝维恩·拉尔森处，以制...",kw={"安多玛斯","腐食隐居者","暮色森林","拉尔森裁缝店","法师长袍","新鲜的蜘蛛丝","巫师圣殿","维恩·拉尔森"},ang={["class:Mage"]="这项通过仪式连接了学徒生涯与真正的精通者阶段，确保每位暴风城法师所穿的长袍，都是由他们亲手克服的危险所化。",["faction:Alliance"]="暮色森林对于暴风城的子民来说仍然是一片危险的边境，要求法师必须走出首都的庇护，去获取稀有的区域资源。",["profession:Tailoring"]="维恩·拉尔森的方法展示了如何将高级野生怪物纤维转化为具有魔法亲和力的织物，其品质远超普通的羊毛或亚麻。"},sec={{t="精通者法衣",b="在巫师圣殿内，认可的标准不仅在于对奥术的掌握，还在于从业者所穿的礼服。高阶法师安多玛斯在学生脱离了学徒工作后，会指引他们去定制与精通者身份相符的法衣。法师不能简单地购买成品，必须亲自从危险的野兽身上采集新鲜、无瑕的蛛丝，以证明其实地能力和辨别力。"},{t="暮色森林的织布机",b="所需材料无法在普通的商人货摊上找到。它必须从潜伏在暮色森林闹鬼阴影中的剧毒腐食隐居者蜘蛛身上小心提取。收集齐八份优质样本后，将其带往城内法师区的拉尔森裁缝店，裁缝维恩·拉尔森已做好准备，将这些精致的丝线纺织成具有奥术意义的长袍。"}},faq={{q="谁会派遣法师执行这项任务？",a="暴风城巫师圣殿的负责人高阶法师安多玛斯，会将此任务交给那些证明了自己的奉献精神的施法者。",al={"谁给予新鲜的蜘蛛丝任务","新鲜的蜘蛛丝任务发布者","安多玛斯任务"}},{q="这种蛛丝是在哪里采集的？",a="蛛丝是从出没在暮色森林闹鬼森林和布满蛛网的空地中的腐食隐居者蜘蛛身上采集的。",al={"在哪里获取新鲜的蛛丝","蜘蛛位置","腐食隐居者位置"}},{q="谁用这种蛛丝制作长袍？",a="维恩·拉尔森，一位在暴风城法师区的拉尔森裁缝店工作的专业裁缝，负责编织和裁剪工作。",al={"谁编织蛛丝","维恩·拉尔森","拉尔森裁缝店"}},{q="为什么法师要用蜘蛛丝制作服装？",a="新鲜的蜘蛛丝具有天然的韧性和极细的织纹，能创造出轻便的布料，既能承载微妙的附魔，又不会增加施法者的负担。",al={"为什么使用蜘蛛丝","蜘蛛丝魔法长袍"}},{q="交付蛛丝后会发生什么？",a="在维恩检查过蛛丝并进行织造后，她会将制作完成的星结长袍交给法师。",al={"新鲜的蜘蛛丝后续任务","接下来发生什么"}},{q="暮色森林里的任何蜘蛛丝都可以吗？",a="不行。拉尔森裁缝店所编织的精妙附魔，需要专门从腐食隐居者身上小心提取的新鲜样本，那些更粗糙的蛛网是无法使用的。",al={"能使用普通蜘蛛丝吗","新鲜与普通蛛丝对比"}}},fx={a495a13a={q="高阶巫师安多玛斯为什么派你去收集蜘蛛丝？",a="高阶巫师安多玛斯看到了你对奥术之道坚定不移的投入，认为是时候让你的衣着体现日益精进的造诣了。巫师圣殿期望你冒着暮色森林的危险，收集制作一件行家法衣所需的稀有材料，以此赢得它，而非直接交给你一件做好的长袍。",al={"安多玛斯为何要蜘蛛丝","安多玛斯的动机","安多玛斯为何交付此任务"}},["8d44c073"]={q="要获得蜘蛛丝，你必须猎杀什么生物？",a="你受命猎杀潜伏在暮色森林幽暗林地中的腐肉潜伏者蜘蛛。这些有毒的蛛类能吐出格外坚韧、富有共鸣的丝线，但只有其中最优质、毫无瑕疵的丝线，才适合织成附魔法衣。",al={"猎杀什么获取新鲜的蜘蛛丝","什么蜘蛛掉落蜘蛛丝","暮色森林腐肉潜伏者"}}},fp="20,201,22.284.0,20.289.0,35.133.0,28.102.0,34.79.0,42.150.0,37.113.0,44.141.0"}
P.entries["quest:1941"] = {n="法纹长袍",s="在暴风城，维恩·拉尔森自豪地展示着她完工的法纹长袍，借此展现家族店铺的手艺。她用上等材料织成了这件长袍，如今这份委托已完成。",h="在暴风城，维恩·拉尔森自豪地展示着她完工的法纹长袍，借此展现家族店铺的手艺。她用上等材料织成了这件长袍，如今这份委托已完成。",kw={"学徒长袍","制衣商","拉尔森服装店","法师区","法纹长袍","暴风城","裁缝","维恩·拉尔森"},ang={["class:Mage"]="作为在暴风城高塔中研习的法师，你穿上量身裁制的manaweave robe，标志着你已学有所成，开始从事严谨的实地研究，并独立施展法术。",["faction:Alliance"]="当你通过首都的一家本地店铺为一位前途无量的勇士置办装备时，你也在帮助暴风城将其声望与自给自足的实力传遍动荡之地。",["profession:Tailoring"]="维恩·拉尔森的作品展现了人类裁缝的高超水准。她的手艺将世间的材料织成衣物，用以驾驭并缓和不稳定的奥术能量。"},sec={{t="拉尔森服装店",b="在暴风城的法师区，拉尔森服装店为应对不稳定能量的施法者制作衣物。精良的魔法长袍需要稀有材料、细致的针线活，以及在魔法共鸣中仍能保持牢固的丝线。维恩·拉尔森以店里的每一件作品为傲。每一件穿到野外的长袍都承载着拉尔森之名。"},{t="织入魔法",b="法纹长袍穿着舒适，便于行动，也足够坚韧，适合在纷争之地旅行。你交齐所需材料后，维恩·拉尔森会亲手缝完最后一针，将成衣交给你。这件长袍充分展现了拉尔森的裁缝手艺，旨在赢得赞赏，让店铺的名声传遍王国。"}},faq={{q="谁制作了法纹长袍？",a="维恩·拉尔森在暴风城法师区的拉尔森服装店制作法纹长袍。",al={"谁制作法纹长袍","维恩·拉尔森的长袍","拉尔森服装店"}},{q="维恩·拉尔森为何希望你自豪地穿上这件长袍？",a="维恩认为这件长袍是她最出色的作品之一。她请冒险者在他人赞赏长袍的工艺时，向他们介绍拉尔森服装店，为她的店铺做活广告。",al={"为何向别人介绍拉尔森","拉尔森宣传","维恩对话"}},{q="拉尔森服装店在哪里？",a="拉尔森服装店位于暴风城的法师区，靠近联盟施法者聚集的学院和圣所。",al={"拉尔森店铺位置","维恩·拉尔森在哪里","法师区裁缝店"}},{q="法纹长袍是什么样的衣物？",a="法纹长袍是一件供魔法修习者穿着的附魔布袍。它经过精心裁制，既能引导魔法能量，也适合危险的旅途。",al={"法纹长袍背景故事","法纹长袍是什么","长袍有什么作用"}},{q="这是一个较长任务线的一部分吗？",a="是的。它是一系列法师任务的终点，最初的任务由詹妮亚·坎农交付。在调查蓝色隐士的一道法力裂隙后，你需要收集亚麻布和充能的裂隙宝石，交给维恩·拉尔森制作长袍。",al={"法纹任务链","长袍任务链","任务线终点"}},{q="哪个阵营可以接受这个任务？",a="只有联盟成员可以接受这个任务。维恩·拉尔森的工作范围完全在联盟首都暴风城内。",al={"联盟还是部落的长袍","部落能否获得法纹长袍","阵营要求"}}},fp="14,176,16.323.0,13.352.0,30.94.0,59.193.0,34.127.0,41.162.0,35.182.0,38.114.0"}
P.entries["quest:1942"] = {n="星结之衣",s="在暴风城，维恩·拉尔森用新鲜的蜘蛛丝织成衣装，既适合危险的旅途，也适合上流社会的聚会。冒险者从荒野带来稀有的蛛丝，她将其织成蕴含魔力的织物。",h="在暴风城，维恩·拉尔森用新鲜的蜘蛛丝织成衣装，既适合危险的旅途，也适合上流社会的聚会。冒险者从荒野带来稀有的蛛丝，她将其织成蕴含魔力的织物。",kw={"星结之衣","布甲","法师区","新鲜的蜘蛛丝","丝质长袍","暴风城","裁缝","维恩·拉尔森"},ang={["class:Mage"]="身为法师，你能从这件衣装中看出暴风城奥术传统的庄严气度，而实用的附魔则适合远行至王国坚固城墙之外。",["faction:Alliance"]="身为联盟的勇士，你能领略暴风城的精湛工艺，无论置身王室殿堂还是危险的前线，都能穿着得宜。",["profession:Tailoring"]="维恩·拉尔森以精湛手艺，将新鲜的蜘蛛丝制成华美的衣装。"},sec={{t="织者的妙趣",b="在暴风城的法师区，裁缝们为奥术精英和来访的贵族服务。维恩·拉尔森用新鲜的蜘蛛丝织成结实耐用、附有魔法的衣装。交付成衣之前，她会打趣说，要留几块珍贵的边角料给自己添置衣服，尽显她的俏皮幽默。"},{t="优雅应万变",b="穿着布甲的施法者看重星结之衣的坚韧与雅致。它的丝料来自危险的蜘蛛，织成的衣装足以经受战斗的考验。即使出席暴风要塞的正式宴会，它也能保持场合所要求的体面仪容。"}},faq={{q="星结之衣是什么？",a="维恩·拉尔森在暴风城用新鲜的蜘蛛丝制作星结之衣。这件衣装专为穿着布甲的施法者而制，适合战斗，也适合上流社会的社交活动。",al={"星结之衣是什么","星结长袍","星结法衣"}},{q="谁制作星结之衣？",a="维恩·拉尔森是暴风城法师区的一名裁缝，只要交给她所需的珍奇材料，她就能制作这件衣装。",al={"谁制作星结","维恩·拉尔森任务","星结裁缝"}},{q="完成这件衣装需要哪些材料？",a="这件衣装需要新鲜的蜘蛛丝，采自世界各地荒野中的致命蜘蛛。裁缝工艺保留了蛛丝天然的强韧，也保留了它承载附魔的能力。",al={"星结材料","所需蛛丝","如何制作"}},{q="维恩·拉尔森为什么打趣说要留下剩余的蛛丝？",a="维恩开玩笑说，要把衣装做短些，好留几块稀有珍贵的蛛丝边角料。她最终交付的成衣并未短缺。",al={"她偷了我的蛛丝吗","维恩·拉尔森的玩笑","短长袍"}},{q="这件衣装是在暴风城的哪里制作的？",a="制作地点在暴风城的法师区，这里聚集着学者、奥术师，以及精于制作附魔织物的裁缝。",al={"维恩·拉尔森在哪","星结位置","星结在哪交任务"}},{q="通常是谁穿着星结之衣？",a="联盟法师青睐星结之衣，既看重它轻盈而具防护力的织物，也欣赏它庄重的外观。",al={"谁使用星结","适合什么职业","谁穿这件衣装"}}},fx={["96918ee1"]={q="维恩·拉尔森为什么制作星结之衣？",a="维恩·拉尔森是暴风城一位技艺精湛的裁缝，她答应织成这件法衣，为你的努力画上句号。她派你穿越危机四伏的土地，收集新鲜的蜘蛛丝等稀有材料，并以制作专为施法者量身打造的卓越法衣为荣，将实用的防护与精美庄重的风雅融为一体。",al={"维恩·拉尔森为何制作法衣","维恩·拉尔森制作星结之衣的动机","维恩为何制作长袍"}}},fp="19,217,14.294.0,18.245.0,32.180.0,35.110.0,53.172.0,56.144.0,50.134.0,44.102.0"}
P.entries["quest:1943"] = {n="巨魔法师迪诺",s="“与迪诺交谈”是一项召唤任务，旨在指引有前途的部落法师前往奥格瑞玛寻找一位技术精湛的施法者。迪诺是一位在精神谷活动的巨魔法师，她需要一名高手代她执行至关重要的法术工作。回应她的召唤，将开启深入钻研奥术之路，并承担起遍布卡利姆多的艰巨任务。",h="“与迪诺交谈”是一项召唤任务，旨在指引有前途的部落法师前往奥格瑞玛寻找一位技术精湛的施法者。迪诺是一位在精神谷活动的巨魔法师，她需要一名高手代她执行至关重要的法术工作。回应她的召唤，将开启深入钻研奥术之路，并承担起遍布卡...",kw={"安娜斯塔西娅·哈特威尔","黑暗荆棘旅店","迪诺","法师任务","奥格瑞玛","奎萨斯","精神谷","萨维亚之水"},ang={["class:Mage"]="此任务是你正统奥术训练中的关键一步，它将你与奥格瑞玛的高级施法者联系了起来。",["faction:Horde"]="这次召唤将洛丹伦和杜隆塔尔的地区训练师，与聚集在奥格瑞玛的奥术核心领导层连接在了一起。",["race:Troll"]="迪诺代表了暗矛部族中少数人所修习的、专注的奥术准则。"},sec={{t="前往奥格瑞玛的召唤",b="随着部落的奥术修行者们不断磨练自己的能力，导师们也会敏锐地察觉到学生何时准备好迎接更具挑战性的冒险。像幽暗城的安娜斯塔西娅·哈特威尔这样的导师，会将成长中的法师指引至奥格瑞玛。在那里，在那个巨魔聚居的区域深处，有着更专业的知识和危险的任务在等待着他们。"},{t="精神谷与黑暗荆棘旅店",b="迪诺居住在奥格瑞玛精神谷的黑暗荆棘旅店中。在暗矛巨魔中，专门从事奥术研究的修行者比起巫医和祭司相对较少，这使得迪诺成为了都城中一位显赫的权威。她不仅为当地事务奔走，更为了部落奥术修行者的长远利益，寻找那些愿意挑战遥远险境的有志法师。"}},faq={{q="是谁让你去与迪诺交谈的？",a="当法师达到足够的技能水平时，幽暗城魔法区的法师训练师（例如安娜斯塔西娅·哈特威尔）会将他们派遣至奥格瑞玛。",al={"任务发布者","谁开启此任务","在哪里接到与迪诺交谈任务"}},{q="我在哪里可以找到迪诺？",a="迪诺位于奥格瑞玛西侧精神谷中的黑暗荆棘旅店里。",al={"迪诺位置","迪诺在哪里","黑暗荆棘旅店位置"}},{q="为什么迪诺需要帮助？",a="迪诺负责监督部落法师群体中至关重要的研究与任务。她征召有能力的施法者前往危险之地，以获取珍贵的奥术资源。",al={"迪诺为何需要帮助","迪诺想要什么"}},{q="向迪诺报到后会发生什么？",a="一旦你向迪诺报到，她会向你简要说明任务目标，并派遣你执行下一个任务，首先就是去收集萨维亚之水。",al={"下一个任务","之后是什么","后续任务"}},{q="这个任务所有职业都能接吗？",a="不能。此任务仅提供给部落的法师，作为他们职业进阶与训练的一部分。",al={"这是法师专属任务吗","术士能做吗","职业限制"}},{q="巨魔法师在部落中常见吗？",a="对于暗矛巨魔来说，奥术魔法并不像精神萨满教义、巫毒或洛阿祭司那样常见。然而，像迪诺这样的人物表明，一些巨魔已经彻底掌握了对奥术力量的正统研究。",al={"巨魔使用奥术","暗矛法师背景知识"}}},fp="16,223,22.271.0,41.309.0,34.140.0,23.98.0,31.142.0,38.93.0,39.79.0,36.175.0"}
P.entries["quest:1944"] = {n="克萨维亚之水",s="“萨维亚之水”是一个部落法师任务，由奥格瑞玛的迪诺发布。为了探寻古老的精灵秘密，她指派学徒前往灰谷的萨维亚废墟，从那里最高的瀑布处取回样本。",h="“萨维亚之水”是一个部落法师任务，由奥格瑞玛的迪诺发布。为了探寻古老的精灵秘密，她指派学徒前往灰谷的萨维亚废墟，从那里最高的瀑布处取回样本。",kw={"灰谷","迪诺","瓶子","法师任务","奥格瑞玛","萨特","碎木岗哨","萨维亚之水","萨维亚"},ang={["class:Mage"]="此任务是部落法师专属的学习仪式，旨在测试他们冒险进入敌对荒野提取未受驯服的奥术试剂的能力。",["faction:Horde"]="碎木岗哨是部落在东灰谷最近的补给站，方便法师在萨维亚周围那片被萨特占据的荒野中穿行。"},sec={{t="法师的好奇心",b="在精神谷昏暗的裂隙中，巨魔法师迪诺一直在搜寻卡利姆多各地残留的原始奥术能量池。她的目光投向了萨维亚，这是一座隐藏在灰谷东部林冠深处的古老暗夜精灵城市。学者间的传说低语道，这座城市在天崩地裂前就沉浸于魔法知识之中，据说那里的水保留着强大的奥术特性，令现代施法者渴望解析。"},{t="萨维亚废墟",b="到达这些水源的源头绝非易事。萨维亚不再属于宁静的精灵贤者；它已沦为废墟，现在被野蛮、堕落的萨特占据，它们凶猛地守护着领地，抵御外来者。想一探究竟的法师必须穿过萨提纳尔，踏过危险的水道，在避开徘徊的野兽和恶魔哨兵的同时，在城市高耸的瀑布底部装满迪诺的瓶子。"}},faq={{q="谁是迪诺？",a="迪诺是一位巨魔法师训练师和学者，位于奥格瑞玛的精神谷。她负责指导部落法师，并调查古卡利姆多魔法的遗物。",al={"谁发布萨维亚之水任务","迪诺 奥格瑞玛"}},{q="萨维亚在哪里？",a="萨维亚是一座古老的废墟城市，位于灰谷东北部，碎木岗哨以北，萨特据点萨提纳尔的西北方。",al={"萨维亚位置","萨维亚在哪里","寻找萨维亚"}},{q="迪诺为什么要这种水？",a="学术记录声称萨维亚曾拥有广博的魔法知识，人们相信那里的水蕴含着残留的奥术力量。迪诺想要一份来自瀑布源头的新鲜样本来分析其特性。",al={"为什么获取萨维亚之水","萨维亚之水的用途"}},{q="萨维亚废墟由什么守卫？",a="废墟中到处都是萨特——那些厌恶入侵者并激烈捍卫领地以抵御窥探法师的恶魔化堕落生物。",al={"萨维亚的敌人","谁控制了萨维亚"}},{q="水样具体在哪里收集？",a="必须在萨维亚废墟内最高瀑布底部的池塘中，将水舀入迪诺的瓶子。",al={"瀑布位置","在哪里装满瓶子","萨维亚瀑布"}},{q="把样本还给迪诺后接下来要做什么？",a="迪诺对水样感到满意，随后派遣法师进行下一步的研究，涉及灰谷的树妖，任务名为“欢笑的姐妹”。",al={"萨维亚之水后续","萨维亚之水后的下一个任务"}}},fp="16,174,18.362.0,19.301.0,13.145.0,24.105.0,31.190.0,39.119.0,44.109.0,52.78.1"}
P.entries["quest:1945"] = {n="欢笑姐妹",s="在灰谷，树妖的头发是制作魔法长袍所需的材料。十字路口经验丰富的巨魔裁缝基尔哈拉需要这些附魔发丝来编织法师长袍，而部落法师正向这片林地的原生守卫步步进逼。",h="在灰谷，树妖的头发是制作魔法长袍所需的材料。十字路口经验丰富的巨魔裁缝基尔哈拉需要这些附魔发丝来编织法师长袍，而部落法师正向这片林地的原生守卫步步进逼。",kw={"灰谷","十字路口","迪诺","树妖","头发","基尔哈拉","欢笑姐妹","林中树居","术士长袍"},ang={["class:Mage"]="身为法师，这场历练让你看到，就连灰谷神圣的林地精魂，也会成为奥术工艺的材料。",["faction:Horde"]="身为部落的一员，你向灰谷的树妖发起攻击，加深了与那些同暗夜精灵结盟的神圣森林守护者之间的冲突。",["profession:Tailoring"]="身为裁缝，你见识到将鲜活的魔法纤维织成布甲的罕见工艺，这正是基尔哈拉在十字路口运用的高超技艺。"},sec={{t="编织奥术",b="从萨维亚取水之后，正在成长的法师会受奥格瑞玛的迪诺指派，协助制作自己的附魔法衣。这些奥术服饰需要蕴含原始魔力的材料。树妖的发丝承载着森林古老的生命力，可用来编织精巧的长袍，为施法者提供保护并增强其力量。"},{t="林中树居的追猎",b="法师在灰谷的林中树居附近寻找 欢笑姐妹。这些敏捷的树妖与暗夜精灵结盟，奋力守护自己的林地，抵御伐木者和外来者。她们不愿将头发交给部落施法者，因此，在古树之下，这些发丝被强行夺走。"},{t="织者的特权",b="这些发丝被带往南方，越过边界，送到贫瘠之地尘土飞扬的十字路口聚落。在那里，巨魔裁缝基尔哈拉毫无愧疚地收下了它们。基尔哈拉略带讥讽地提及林地生灵的损失，随后便用起这些附魔发丝，深知部落的力量需要坚定的决心。"}},faq={{q="是谁指派猎杀欢笑姐妹的任务？",a="迪诺是奥格瑞玛 暗棘小屋 的一名巨魔法师，他派遣法师收集制作法师职业长袍所需的材料。",al={"谁发布 欢笑姐妹 任务","欢笑姐妹 任务发布者","迪诺任务"}},{q="欢笑姐妹 是什么？",a="欢笑姐妹 是树妖，也是半神塞纳留斯的女儿。她们的上半身如同暗夜精灵女性，下半身则如同幼鹿，守护着灰谷的林地与神圣的林间空地。",al={"欢笑的姐妹 是什么","欢笑的姐妹 树妖","欢笑姐妹 是树妖吗"}},{q="在哪里可以找到 欢笑姐妹？",a="她们在灰谷中部的林中树居附近，以及欢笑的姐妹林间空地一带的森林中游荡，离商道不远。",al={"欢笑姐妹 位置","欢笑姐妹 在哪里","哪里能找到 欢笑姐妹"}},{q="基尔哈拉为什么需要树妖的头发？",a="树妖的头发带有天然魔力，适合用作丝线，让基尔哈拉编织出与魔法共鸣、适合奥术技艺的特制长袍。",al={"为什么需要树妖的头发","为什么需要 欢笑的姐妹 的头发","头发有什么用"}},{q="收集到头发后，该交到哪里？",a="将头发交给基尔哈拉，他是贫瘠之地十字路口的一名裁缝。",al={"基尔哈拉在哪里","欢笑姐妹 任务交付","十字路口裁缝术士"}},{q="基尔哈拉收下头发后会发生什么？",a="基尔哈拉会花一点时间处理头发，然后提供虚空法袍，以完成长袍的制作。",al={"欢笑姐妹 后续任务","欢笑姐妹 之后","虚空法袍后续"}}},fp="16,223,18.311.0,18.298.0,24.301.0,51.117.0,30.188.0,40.127.0,34.161.0,49.69.0,43.89.0"}
P.entries["quest:1946"] = {n="虚灵长袍",s="虚空蕾丝法衣标志着裁缝基尔哈拉在贫瘠之地的专业制作工作告一段落。通过将收集到的树妖毛发编织成精美的布料，这位裁缝制作出了适合施法者的附魔服饰。",h="虚空蕾丝法衣标志着裁缝基尔哈拉在贫瘠之地的专业制作工作告一段落。通过将收集到的树妖毛发编织成精美的布料，这位裁缝制作出了适合施法者的附魔服饰。",kw={"灰谷","贫瘠之地","十字路口","迪诺","基尔哈拉","欢笑姐妹","法师","虚空蕾丝"},ang={["class:Mage"]="虚空蕾丝法衣是施法者进阶的一个重要里程碑，它连接了灰谷的荒野试炼与迪诺指导下基尔哈拉的精湛工艺。",["faction:Horde"]="从卡利姆多的圣林中获取组件来装备部落施法者，展示了部落与灰谷的林地守护者之间持续的对抗。",["profession:Tailoring"]="基尔哈拉的工艺展示了如何将诸如树妖毛发之类的奇异试剂纺织成带有先天魔法防护的织物。"},sec={{t="编织虚空蕾丝",b="基尔哈拉在贫瘠之地的十字路口工作，负责虚空蕾丝的精细制作工艺。这需要稀有且具有魔法共鸣的组件——特别是从灰谷中被称为欢笑姐妹的树妖身上采集到的发束——裁缝将天然的林地附魔直接融入舒适耐用的布料中。"},{t="奥格瑞玛的恩惠",b="除了单纯经营生意，基尔哈拉在确保服装质量方面还有个人的动机。他特别渴望讨好迪诺，一位居住在奥格瑞玛精神谷的受人尊敬的巨魔法师。通过为有抱负的施法者制作精良的服装，基尔哈拉希望获得并维持迪诺的好感。"}},faq={{q="什么是虚空蕾丝？",a="虚空蕾丝是由基尔哈拉制作的一种附魔织物。它由魔法材料编织而成，特别是使用了欢笑姐妹的发束，使其既坚韧又天然地充满了奥术共鸣。",al={"虚空蕾丝布料","什么是虚空蕾丝法衣"}},{q="谁制作虚空蕾丝法衣？",a="基尔哈拉，一位驻扎在贫瘠之地十字路口的熟练部落裁缝，在获得必要的灰谷树妖毛发后会制作这种服饰。",al={"谁制作虚空蕾丝","基尔哈拉 虚空蕾丝"}},{q="为什么基尔哈拉会提到迪诺？",a="迪诺是一位有影响力的巨魔法师训练师，居住在奥格瑞玛的精神谷。基尔哈拉渴望博得她的好感，并希望你对他裁缝手艺的满意能为他带来好评。",al={"谁是迪诺","为什么提到迪诺"}},{q="服饰的材料来自哪里？",a="核心材料是采集自欢笑姐妹的毛发，这是一群出没于灰谷森林中难以捉摸的树妖。",al={"虚空蕾丝材料","树妖毛发织物"}},{q="这件服饰是为谁制作的？",a="它主要是为施法者，特别是需要能够传导奥术能量且不影响行动的长袍的见习法师而制作的。",al={"谁使用虚空蕾丝法衣","虚空蕾丝职业"}},{q="基尔哈拉在哪里？",a="基尔哈拉居住在十字路口，这是一个位于贫瘠之地中心的中央枢纽定居点。",al={"基尔哈拉位置","基尔哈拉在哪里"}}},fp="19,144,23.287.0,20.243.0,20.151.0,35.126.0,32.185.0,50.112.0,29.132.0,26.85.0"}
P.entries["quest:1947"] = {n="沼泽之旅",s="你受职业指派前往尘泥沼泽，塔贝萨的学识能帮助你获得魔杖。",h="你受职业指派前往尘泥沼泽，塔贝萨的学识能帮助你获得魔杖。",kw={"小屋","尘泥沼泽","沼泽之旅","石槌废墟","塔贝萨","塞拉摩","魔杖"},sec={{t="塔贝萨的小屋",b="塔贝萨住在塞拉摩以西、石槌废墟正北方不远处的一间小屋里。你的职业要求你与这位隐士交谈，向学识渊博的她请教。"}},faq={{q="塔贝萨是谁？",a="塔贝萨是尘泥沼泽的一位隐士，以学识渊博著称。",al={"塔贝萨","沼泽隐士","隐士是谁"}},{q="塔贝萨的小屋在哪里？",a="塔贝萨的小屋位于塞拉摩以西、石槌废墟正北方不远处。",al={"塔贝萨位置","塔贝萨在哪里","塔贝萨的小屋"}},{q="为什么派我去找塔贝萨？",a="与塔贝萨交谈，是你争取获得职业魔杖的第一步。",al={"为什么找塔贝萨","魔杖任务","获得我的魔杖"}}},fp="20,98,19.164.0,15.70.0,29.79.0,31.69.0"}
P.entries["quest:195"] = {n="猎龙",s="在荆棘谷的丛林深处，赫米特·奈辛瓦里向猎人们发起挑战，要求他们去对付更危险的猎物。在完成早先的一次迅猛龙狩猎后，他指派冒险者们去追踪并击杀十只鞭尾迅猛龙。",h="在荆棘谷的丛林深处，赫米特·奈辛瓦里向猎人们发起挑战，要求他们去对付更危险的猎物。在完成早先的一次迅猛龙狩猎后，他指派冒险者们去追踪并击杀十只鞭尾迅猛龙。",kw={"格罗姆高营地","赫米特·奈辛瓦里","狩猎","鞭尾迅猛龙","迅猛龙狩猎","荆棘谷"},ang={["class:Hunter"]="对于追踪者和野兽猎手来说，赫米特·奈辛瓦里的挑战旨在考验他们面对荆棘谷中出没的致命捕食者时的基本狩猎素养。"},sec={{t="更严峻的挑战",b="在展示了初步的狩猎本领后，赫米特·奈辛瓦里希望大家不仅仅是围在营地的篝火旁虚度光阴。为了证明真正的专注与技巧，猎人们被派往格罗姆高营地以北茂密的丛林灌木丛中，去追踪并击杀十只凶猛的鞭尾迅猛龙。"},{t="炉边的战利品",b="从丛林中凯旋归来，将会赢得奈辛瓦里的热烈赞许。这位经验丰富的猎人认为这些危险的捕食者是很有价值的猎物，非常适合作为挂在炉火上方的战利品，他也正准备为冒险者提供更艰巨的挑战。"}},faq={{q="谁提供了这项狩猎挑战？",a="著名的大型猎物猎人赫米特·奈辛瓦里在荆棘谷北部的探险营地发出了这项挑战。",al={"谁开启了迅猛龙狩猎2","迅猛龙狩猎任务发布者","哪里领取迅猛龙狩猎"}},{q="你的狩猎目标是什么？",a="你接受的挑战是深入丛林，击杀十只鞭尾迅猛龙。",al={"要击杀什么迅猛龙","哪一个迅猛龙任务","鞭尾迅猛龙目标"}},{q="在哪里可以找到鞭尾迅猛龙？",a="鞭尾迅猛龙潜伏在荆棘谷北部荒野的丛林中，尤其是在格罗姆高营地的北面。",al={"鞭尾迅猛龙在哪里","鞭尾迅猛龙位置","到哪里寻找鞭尾迅猛龙"}},{q="这次狩猎在奈辛瓦里的考验中处于什么位置？",a="这是迅猛龙系列任务中的第二项考验，接在入门级的“迅猛龙狩猎”之后，并通向挑战的第三部分。",al={"这个迅猛龙狩猎之前有什么任务","迅猛龙狩猎任务进度","迅猛龙任务链"}}},fp="14,160,19.240.0,23.221.1,34.122.0,40.59.0,37.110.0,50.147.0"}
P.entries["quest:1950"] = {n="解封咒语",s="大法师提尔斯把一本至关重要的法术书锁进了用魔法封住的保险箱，却想不起开启它的口令。要取出这本典籍，你必须在闪光平原的赛道周围找到他失踪的学徒，从学徒口中问出那句被遗忘的口令。",h="大法师提尔斯把一本至关重要的法术书锁进了用魔法封住的保险箱，却想不起开启它的口令。要取出这本典籍，你必须在闪光平原的赛道周围找到他失踪的学徒，从学徒口中问出那句被遗忘的口令。",kw={"打探消息","约翰森","大法师提尔斯","沙漠赛道","闪光平原","保险箱","千针石林","魔杖任务"},ang={["class:Mage"]="与提尔斯打交道，能让人以一种诙谐却又令人警醒的方式，见识变形诅咒的危险，以及强大学者也可能有的健忘毛病。"},sec={{t="大法师的记性",b="大法师提尔斯是一位古怪的施法者，住在千针石林闪光平原干裂的盐床上。他掌握着进修中的法师迫切寻求的秘法知识和典籍，但与他打交道需要耐心。提尔斯十分依赖助手来处理日常琐事，包括记住守护他那些奥术藏品的口令。前来求学的施法者奉命取回一本蕴含力量的书籍时，很快就会发现，提尔斯用魔法口令把书锁了起来，而他自己早已把口令忘得一干二净。"},{t="家禽闹剧",b="要找到提尔斯的学徒约翰森，可不是在沙漠赛道的围场里转转就行的。向经营赛道的地精和侏儒打听后，就会发现约翰森遭遇了侍奉一位喜怒无常的巫师时最典型的职业风险：变形。他被师父诅咒，变成了一只普通的鸡，在盐滩上游荡，无法开口说话，直到有旅人靠近，短暂驱散魔法造成的迷乱，他才能咯咯叫着说出那句遗失的口令。"}},faq={{q="大法师提尔斯是谁？",a="大法师提尔斯是一位离群索居的人类巫师，住在千针石林闪光平原的沙漠赛道附近。他掌握着高深的奥术知识，吸引着希望精进技艺的法师前来求教。",al={"提尔斯背景故事","大法师提尔斯是谁","提尔斯闪光平原"}},{q="提尔斯为什么需要自己箱子的口令？",a="提尔斯用一句口令施法锁住了保险箱，并依靠助手记住口令之类的琐事。他一向丢三落四，学徒一失踪，他就把口令忘了。",al={"提尔斯为什么忘了","提尔斯保险箱口令"}},{q="学徒去了哪里？",a="约翰森并没有逃远。他就在提尔斯营地东边的赛道附近游荡，不过提尔斯把他变成了一只鸡，让寻找他变得颇为麻烦。",al={"寻找提尔斯的助手","学徒约翰森在哪里","约翰森位置"}},{q="学徒为什么被变成了鸡？",a="提尔斯对约翰森施了诅咒，随后就忘了自己做过这件事。得知助手的遭遇后，提尔斯含糊地认定，这个不知感恩的学生一定是罪有应得。",al={"约翰森为什么变成鸡","提尔斯变形术学徒"}},{q="提尔斯的保险箱里有什么？",a="这个用魔法封住的箱子里装着一本书，记载了法师继续研习和制作魔法器具所必需的仪式与指引。",al={"提尔斯保险箱里的东西","箱子里是什么书"}},{q="谁能接下这项任务？",a="这趟差事是一项专门试炼的一部分，仅供寻求专门指导和材料、以制作强大魔杖的法师完成。",al={"非法师能做解封的咒语吗","这个任务仅限法师吗"}}},fx={["25c94f6f"]={q="大法师提尔斯为什么派你去，而不亲自寻找学徒？",a="既然是你求大法师提尔斯传授知识，他自然不会亲自去闪光平原搜寻。你前来求取他珍藏的魔法典籍，而他失去了助手，自己又想不起打开魔法封印宝箱的咒语，于是便以帮他找人为条件，换取他的帮助。",al={"为什么派我去","提尔斯为什么不去找约翰逊","为什么我必须去找学徒"}}},fp="13,192,22.417.0,9.319.1,19.165.0,48.164.0,28.119.1,45.169.1,33.123.0,28.105.0"}
P.entries["quest:1959"] = {n="向安娜斯塔西娅报告",s="卡利姆多和东部王国各地的部落法师都收到了前往幽暗城的召唤。安娜斯塔西娅·哈特威尔在那里感知到了一股不明的魔法扰动，需要有能力的施法者前去调查。",h="卡利姆多和东部王国各地的部落法师都收到了前往幽暗城的召唤。安娜斯塔西娅·哈特威尔在那里感知到了一股不明的魔法扰动，需要有能力的施法者前去调查。",kw={"安娜斯塔西娅·哈特威尔","凯恩·火歌","调查炼金店","法师","魔法区","向安娜斯塔西娅报告","瑟斯顿·科萨恩","安苏瓦","幽暗城","尤塞尔奈"},ang={["class:Mage"]="身为部落法师，你离开所在地区的训练哨站，前往幽暗城。洛丹伦的废墟之下，潜藏着更深的奥术谜团与危险。",["faction:Horde"]="这道召唤让被遗忘者法师与其他部落法师聚集起来，守护他们共同的利益。",["race:Undead"]="身为被遗忘者，你受召前往幽暗城的魔法区，帮助你们年轻的王国抵御城墙之内的奥术威胁。"},sec={{t="奥术的召唤",b="卡利姆多和东部王国各地的部落法师都听到了同样的召唤。无论是在雷霆崖顶研习，身处杜隆塔尔尘土飞扬的酷热之中，还是置身于洛丹伦的废墟间，他们都收到了消息。幽暗城的法师在自己的领地内感知到了原因不明的扰动。他们需要帮助，查明这意味着什么。"},{t="幽暗城的法师",b="安娜斯塔西娅·哈特威尔负责幽暗城魔法区的奥术事务。那里的法师在城中探测到了奇异的能量，但无人知道这股魔法是无害的，还是怀有敌意。安娜斯塔西娅需要一位有能力的法师暗中调查。调查从炼金房开始。"}},faq={{q="安娜斯塔西娅·哈特威尔是谁？",a="安娜斯塔西娅·哈特威尔是幽暗城魔法区的一位被遗忘者法师，也是奥术导师。她指导初学者，并留意被遗忘者首都中的奥术扰动。",al={"安娜斯塔西娅·哈特威尔背景故事","安娜斯塔西娅是谁","哈特威尔幽暗城"}},{q="安娜斯塔西娅·哈特威尔在哪里？",a="安娜斯塔西娅·哈特威尔位于幽暗城北部环区的魔法区。她是城中的施法训练师和奥术研究者之一。",al={"安娜斯塔西娅在哪里","哈特威尔位置","安娜斯塔西娅幽暗城地图"}},{q="为什么雷霆崖或贫瘠之地的法师会被召往幽暗城？",a="幽暗城的法师探测到了异常扰动，部落在洛丹伦的利益可能受到威胁。卡利姆多的导师们派遣有潜力的学徒前去协助，并积累应对复杂魔法现象的经验。",al={"为什么前往幽暗城","为什么向安娜斯塔西娅报到","雷霆崖法师任务"}},{q="安娜斯塔西娅正在调查什么样的扰动？",a="法师们在幽暗城内探测到了原因不明的魔法波动。安娜斯塔西娅·哈特威尔不知道这股能量是怀有敌意、意外产生，还是并无危害，因此开始了谨慎的调查。",al={"什么扰动","幽暗城魔法扰动","幽暗城出了什么问题"}},{q="谁提供这个任务？",a="当你积累了足够的经验后，部落的法师训练师就可以派你去见安娜斯塔西娅。他们包括奥格瑞玛的尤塞尔奈、雷霆崖的瑟斯顿·科萨恩、布瑞尔的凯恩·火歌，以及森金村的安苏瓦。",al={"谁提供向安娜斯塔西娅报告","向安娜斯塔西娅报告任务提供者"}},{q="向安娜斯塔西娅报到后会发生什么？",a="与安娜斯塔西娅交谈并听取她的情况说明后，她会指引你前往城中的炼金房调查扰动。你将从调查炼金店开始。",al={"向安娜斯塔西娅报告之后的任务","向安娜斯塔西娅报告后续任务"}}},fp="19,196,20.293.0,25.285.0,26.179.0,36.146.0,80.216.0,52.196.0,21.204.0,42.176.0"}
P.entries["quest:196"] = {n="猎龙",s="赫米特·奈辛瓦里要求你猎杀一种难以捉摸的迅猛龙：丛林潜行者，以此提升他狩猎远征的难度。在荆棘谷成功追踪并猎杀十只这种狡猾的迅猛龙，将证明你作为一名真正的野兽追踪者所具备的实力。",h="赫米特·奈辛瓦里要求你猎杀一种难以捉摸的迅猛龙：丛林潜行者，以此提升他狩猎远征的难度。在荆棘谷成功追踪并猎杀十只这种狡猾的迅猛龙，将证明你作为一名真正的野兽追踪者所具备的实力。",kw={"大型狩猎专家","古拉巴什竞技场","赫米特·奈辛瓦里","丛林潜行者","迅猛龙大师","荆棘谷"},ang={["class:Hunter"]="在赫米特·奈辛瓦里的注视下，追踪像丛林潜行者这样机警的猎物，是展示追踪能力和荒野射击技巧的最佳方式。"},sec={{t="狡猾的猎物",b="在测试过你对付低等级迅猛龙的瞄准能力后，赫米特·奈辛瓦里提出了一个更具挑战性的猎物。丛林潜行者异常狡猾，比之前猎杀的品种更难追踪和击杀。赫米特希望你深入丛林，猎杀十只这种机警的掠食者，然后回到营地，以获得参与他最棒狩猎活动的资格。"}},faq={{q="谁提供了这次狩猎任务？",a="驻扎在荆棘谷北部的著名大型狩猎专家赫米特·奈辛瓦里发布了这项挑战。",al={"任务发布者","谁开启迅猛龙大师3","赫米特·奈辛瓦里狩猎"}},{q="你需要追踪哪种野兽？",a="你的任务是找到并击杀十只丛林潜行者，这是一种特别狡猾且难以捉摸的迅猛龙。",al={"什么迅猛龙","目标迅猛龙","要击杀哪种迅猛龙"}},{q="丛林潜行者在哪里出没？",a="丛林潜行者在荆棘谷游荡，特别是在古拉巴什竞技场以北和以西的区域。",al={"丛林潜行者位置","丛林潜行者在哪里游荡","寻找丛林潜行者"}},{q="这项挑战之前是什么任务？",a="这次狩猎紧随“迅猛龙大师”挑战的第二阶段，是赫米特·奈辛瓦里对当地迅猛龙品种狩猎进度的延续。",al={"前置任务","之前的迅猛龙大师","之前的任务是什么"}}},fp="14,128,14.247.0,21.101.0,39.87.0,32.90.0,33.127.0"}
P.entries["quest:1960"] = {n="调查炼金店",s="在奥格诺恩的店里，隐形生物游荡于炼金器具之间。安娜斯塔西娅·哈特威尔派部落法师去让它们显形，并在它们造成危害前将其收容。",h="在奥格诺恩的店里，隐形生物游荡于炼金器具之间。安娜斯塔西娅·哈特威尔派部落法师去让它们显形，并在它们造成危害前将其收容。",kw={"奥格诺恩","安娜斯塔西娅·哈特威尔","炼金房","显形卷轴","封灵箱","魔法区","裂隙怒灵","幽暗城"},ang={["class:Mage"]="身为法师，你通过显形咒文和收容容器检验自己对奥术力量的掌控，运用的不只是破坏性的力量。",["race:Undead"]="身为被遗忘者，你看到幽暗城的奥术学者与专注于炼金术和瘟疫研制的药剂师一道，守护城市，抵御魔法渗透。"},sec={{t="炼金房的骚动",b="安娜斯塔西娅·哈特威尔派奥术学徒前往炼金房调查一场骚动。隐形的魔法生物在奥格诺恩的炼金商店里游荡，穿行于坩埚和试剂之间。幽暗城的法师训练师怀疑魔力流中出现了一道裂口。必须在这些生物造成严重破坏前将其收容。"},{t="显形与收容",b="安娜斯塔西娅给学生们一份显形卷轴，用来让隐形生物现身，还给了他们坚固的封灵箱来关住这些生物。常规的追踪手段无法找到完全由原始奥术能量构成的生物。裂隙怒灵显形后，必须先削弱它们，再将它们封入箱中，以免它们进一步溃散，或伤害正在工作的炼金师。"},{t="意外还是奥术袭击？",b="安娜斯塔西娅想查明这些生物的来历。魔力流中自发形成的裂隙已令人不安，而人为制造的裂口则可能意味着有人正对被遗忘者的首都发动有组织的魔法袭击。幽暗城的学者将研究被捕获的生物，查明炼金房究竟遭遇了一场意外，还是面临有针对性的威胁。"}},faq={{q="谁发布这个任务，在哪里能找到？",a="法师训练师安娜斯塔西娅·哈特威尔在幽暗城的魔法区发布这个任务。",al={"任务发布者","从哪里开始","安娜斯塔西娅位置"}},{q="骚动发生在哪里？",a="骚动发生在奥格诺恩的炼金商店，位于幽暗城的炼金房区。",al={"去哪里","炼金商店位置","奥格诺恩在哪里"}},{q="在店里游荡的是什么生物？",a="这些生物是裂隙怒灵，是由浓缩的魔法能量构成的隐形生物，因当地魔力流的异常而出现。",al={"怪物是什么","隐形生物","裂隙怒灵"}},{q="如何捕获这些生物？",a="在店内诵读显形卷轴，让裂隙怒灵现身，用法术削弱它们，再用封灵箱将其捕获。",al={"如何捕获","箱子用法","如何完成"}},{q="安娜斯塔西娅为什么要活捉这些生物？",a="安娜斯塔西娅和幽暗城的学者需要活体样本，以查明魔力中的裂口究竟是自然形成的裂隙，还是外界魔法势力蓄意袭击这座城市所致。",al={"为何捕获","封灵箱用途","为何研究"}},{q="法师以外的职业能做这个任务吗？",a="只有部落法师可以参与；这是他们早期训练的一部分。",al={"法师专属","谁能接这个任务"}}},fp="30,153,33.330.0,29.345.0,27.342.1,46.83.0,33.88.0,42.144.0,33.149.0,55.184.0,43.69.0"}
P.entries["quest:1961"] = {n="收集原料",s="在幽暗城，收集原料让部落的法师新秀前往银松森林，收集达拉然的法力宝石。他们还需要亚麻布，来制作第一件真正的法师长袍。",h="在幽暗城，收集原料让部落的法师新秀前往银松森林，收集达拉然的法力宝石。他们还需要亚麻布，来制作第一件真正的法师长袍。",kw={"安伯米尔","安娜斯塔西娅·哈特威尔","达拉然法力宝石","收集原料","乔瑟夫·格里高利","亚麻布","魔法区","魔焰长袍","幽暗城"},ang={["class:Mage"]="身为部落法师，当你脱下简朴的学徒服饰，换上织入了夺来的奥术力量的定制长袍时，你便迈过了一道重要的门槛。",["profession:Tailoring"]="身为裁缝，你将普通亚麻布与强大的法力宝石结合，制成经久耐用的附魔衣物。",["race:Undead"]="身为Undead，你见识到被遗忘者冷酷无情的处世之道。即使与达拉然巫师有着相近的奥术理念，当那些巫师无力守住银松森林时，也得不到半分怜悯。"},sec={{t="确立奥术地位的仪式",b="幽暗城的学徒收集一卷普通的亚麻布和蕴含强大力量的达拉然法力宝石，用来制作第一件真正的长袍。这件长袍象征着他们的地位与个人价值。安娜斯塔西娅·哈特威尔指引新手收集原料，用来织造附魔布料。"},{t="被遗忘者的务实之道",b="这些法力宝石既买不到，也无法凭空变出。达拉然法师驻扎在银松森林各处，尤其是安伯米尔附近，宝石必须从他们手中夺取。安娜斯塔西娅·哈特威尔说，达拉然的奥术理念与被遗忘者如出一辙。然而，幽暗城容不下感情用事。在被遗忘者看来，无力守护自身宝物的巫师，也就失去了保有财宝与性命的资格。"},{t="魔法区的裁缝",b="乔瑟夫·格里高利是幽暗城魔法区的一名裁缝，收集到的布料和宝石都要送到他那里。他缺乏魔法天赋，无法鉴别达拉然附魔宝石的纯净品质。但他拥有罕见的工艺，能将宝石中未经驾驭的力量织入长袍。"}},faq={{q="收集原料的目的是什么？",a="这项仪式标志着部落法师开始穿上第一件正式的附魔长袍。亚麻布和法力宝石会交给裁缝乔瑟夫·格里高利，由他用这些材料制作长袍。",al={"为什么做收集原料","收集原料任务目的","幽暗城法师长袍任务"}},{q="安娜斯塔西娅·哈特威尔为什么派你去对付达拉然法师？",a="驻扎在银松森林各处的达拉然巫师携带着精炼的法力宝石，能够引导强大的魔法能量。安娜斯塔西娅·哈特威尔明白双方有着相近的奥术理念，但她认为，无力自保的人便失去了保有性命和资源的资格，只能任由被遗忘者夺取。",al={"为什么杀达拉然法师","达拉然法力宝石背景故事","为什么对付银松森林法师"}},{q="达拉然巫师在哪里？",a="达拉然巫师驻扎在银松森林各处，尤其是安伯米尔附近，以及瑟伯切尔东南方一带。",al={"哪里能找到达拉然法力宝石","银松森林法师位置","安伯米尔法师"}},{q="乔瑟夫·格里高利是谁？",a="乔瑟夫·格里高利是幽暗城魔法区的一名亡灵裁缝。他并非奥术施法者，却擅长缝制附魔衣物，例如魔焰长袍。",al={"乔瑟夫·格里高利幽暗城","魔法区的裁缝是谁","格里高利裁缝"}},{q="这些材料能制成什么长袍？",a="乔瑟夫·格里高利用亚麻布和达拉然法力宝石缝制魔焰长袍。这件长袍标志着学徒成长为一名正式的法师。",al={"能获得什么长袍","魔焰长袍奖励","收集原料奖励长袍"}},{q="为什么安娜斯塔西娅对杀死达拉然法师有些反感？",a="安娜斯塔西娅·哈特威尔对此感到反感，是因为达拉然法师与被遗忘者法师有许多相同的奥术信念和理念。尽管如此，生存与现实所需仍比情感更重要。",al={"哈特威尔对达拉然的感情","被遗忘者法师与达拉然","安娜斯塔西娅·哈特威尔背景故事"}}},fp="19,166,25.248.0,26.389.0,31.272.0,43.168.0,57.270.0,38.132.0,23.168.0,44.147.0,67.184.0"}
P.entries["quest:1962"] = {n="魔焰长袍",s="在幽暗城，魔焰长袍标志着年轻的部落法师正迈向精通魔法的道路。学徒从各地带回稀有材料后，乔瑟夫·格里高利便会完成这些长袍。",h="在幽暗城，魔焰长袍标志着年轻的部落法师正迈向精通魔法的道路。学徒从各地带回稀有材料后，乔瑟夫·格里高利便会完成这些长袍。",kw={"奥术长袍","收集原料","乔瑟夫·格里高利","法师任务","魔法区","魔焰长袍","幽暗城"},ang={["class:Mage"]="作为部落法师，你获得这些长袍，便完成了早期的一场成长试炼。精心裁制的布料能够承受不稳定的火焰与奥术能量。",["profession:Tailoring"]="作为裁缝，你能看出奇异的施法材料如何增强普通布料，使其抵御强大的魔法能量流。",["race:Undead"]="作为幽暗城的被遗忘者施法者，你延续着达拉然式的奥术修习。你的技艺将古老的魔法传统与你在洛丹伦废墟中的新生融为一体。"},sec={{t="法师的衣袍",b="在洛丹伦，要引导并护持你日益增长的魔力，普通布料远远不够。乔瑟夫·格里高利是幽暗城魔法区的一名裁缝。他用前途可期的部落施法者收集的特殊材料制作魔法衣袍。最后一针落下，标志着你已超越基础咒语，开始迈向奥术与火焰魔法的领域。"},{t="织入魔力",b="乔瑟夫·格里高利需要炼金与奥术材料，才能制作出汇聚强大魔力的长袍。你历经危险的试炼收集材料，再将它们带到他位于幽暗城的居所。在那里，格里高利将这些材料编织在一起。长袍标志着你地位的提升，也为立志精进的法师提供保护。"}},faq={{q="魔焰长袍任务的目的是什么？",a="这些长袍为部落法师早期的一场成长试炼画上句号。收集齐裁缝所需的材料后，你会从乔瑟夫·格里高利那里获得经过特殊附魔的长袍。",al={"魔焰长袍 用途","魔焰长袍 有什么用","为什么做这个任务"}},{q="乔瑟夫·格里高利是谁？",a="乔瑟夫·格里高利是幽暗城魔法区的一名被遗忘者裁缝。安娜斯塔西娅·哈特威尔将初出茅庐的法师派到他这里，由他为这些法师缝制第一套正式的职业衣袍。",al={"乔瑟夫是谁","谁制作长袍","乔瑟夫·格里高利 幽暗城"}},{q="这个任务在哪里进行？",a="你会在幽暗城魔法区的裁缝店里见到乔瑟夫·格里高利。",al={"魔焰长袍 位置","魔焰长袍 在哪里交任务"}},{q="为什么这个任务不需要你再出去完成另一项差事？",a="你已在前一个任务收集原料中收集好了材料。将施法材料交给乔瑟夫，他就会织成衣袍，并将成品交给你。",al={"为什么能立即完成","如何完成 魔焰长袍","长袍任务自动完成"}},{q="法师以外的职业能获得这些长袍吗？",a="不能。只有效忠部落的法师才能获得这些附魔长袍。",al={"是否仅限法师","术士能否获得","谁能做 魔焰长袍"}},{q="制作这些长袍需要哪些材料？",a="这些长袍需要用到先前收集的稀有物资，包括亚麻布，以及从银松森林的肯瑞托法师身上取得的达拉然法力宝石。",al={"制作长袍需要什么","长袍材料","收集原料 交任务"}}},fp="15,180,17.341.0,11.308.0,49.164.0,23.172.0,33.77.0,62.164.0,48.71.0,49.146.0"}
P.entries["quest:1963"] = {n="碎手氏族",s="瑟祖克考验着奥格瑞玛中那些寻求加入神秘组织碎手氏族的潜行者。试炼要求他们追杀巨魔走私贩塔赞，并夺取他上锁的背包。",h="瑟祖克考验着奥格瑞玛中那些寻求加入神秘组织碎手氏族的潜行者。试炼要求他们追杀巨魔走私贩塔赞，并夺取他上锁的背包。",kw={"暗影裂口","奥格瑞玛","棘齿城","潜行者","背包","碎手氏族","塔赞","瑟祖克"},ang={["class:Rogue"]="身为部落潜行者，你通过一场入会试炼加入碎手氏族，这场试炼看重冷酷高效、暗杀与实用，胜过正面交锋。",["faction:Horde"]="身为部落的一员，你看到了碎手氏族对萨尔为年轻部落勾画的谨慎愿景所发起的暗中挑战。"},sec={{t="大断崖中的暗影",b="碎手氏族在奥格瑞玛地下的暗影裂口活动。这个由刺客和盗贼组成的组织遵循着古老的兽人传统。大酋长萨尔以荣誉、外交和谨慎治理着年轻的部落，但碎手氏族的首领们认为，克制会削弱他们的族人。他们试图通过隐秘的暴力重振武力霸权，在战场冲锋可能失败时，便动用利刃与毒药。"},{t="走私贩的命运",b="瑟祖克用一份刺杀塔赞的契约来考验潜行者，这名巨魔在贫瘠之地的棘齿城附近活动。塔赞与沿海的海盗做交易，身上带着公会想要的情报。夺回他上锁的背包，便能证明潜行者有能力在城墙之外追踪猎物，但要打开背包，还需要更高的技艺。"}},faq={{q="奥格瑞玛的碎手氏族是什么组织？",a="碎手氏族是部落的一个秘密公会，由潜行者、斥候和刺客组成，以奥格瑞玛的暗影裂口为据点。它曾是一个以残酷自残闻名的古老兽人氏族，如今则负责搜集情报、执行暗杀，比起萨尔谨慎的外交手段，更推崇冷酷务实的行事方式。",al={"碎手氏族是谁","碎手氏族潜行者","碎手氏族的目的"}},{q="瑟祖克是谁？",a="瑟祖克是碎手氏族在暗影裂口的一名联络人。他考验有意加入的潜行者，检验他们是否具备公会要求的狡诈与杀人本领，并公开质疑萨尔的克制。",al={"瑟祖克的职责","任务发布者是谁","瑟祖克奥格瑞玛"}},{q="瑟祖克为什么要杀死塔赞？",a="塔赞是一名巨魔走私贩，在棘齿城附近与南海海盗做交易。他随身的背包里装着情报，碎手氏族想用这些情报开展秘密行动。",al={"为什么杀塔赞","塔赞的背景故事","塔赞做了什么"}},{q="塔赞在哪里？",a="塔赞在贫瘠之地活动，靠近棘齿城以南的海岸和海盗出没的地带。",al={"塔赞的位置","塔赞在哪里","寻找塔赞"}},{q="夺回塔赞的背包后会发生什么？",a="背包送回后，瑟祖克发现它上了锁。虽然他对塔赞的死很满意，但他还需要里面的情报，于是将打开背包作为对潜行者开锁技艺的又一次考验。",al={"后续任务","上锁的背包","背包如何处理"}},{q="萨尔知道碎手氏族的行事手段吗？",a="碎手氏族名义上效忠部落，但其成员在暗影中活动，蔑视萨尔谨慎的领导方式。他们悄悄建立情报网络，力求在大酋长的外交手段拖延行动之前清除威胁。",al={"萨尔与碎手氏族","大酋长是否赞同","萨尔与潜行者"}}},fp="18,160,20.413.0,17.294.1,40.297.0,15.174.0,33.163.0,23.83.0,46.188.1,52.240.0"}
P.entries["quest:197"] = {n="猎龙",s="在荆棘谷深处，赫米特·奈辛瓦里向老练的追踪者发出挑战，要他们猎杀一头连他也未能捕获的神出鬼没的掠食者。你已在对付较弱野兽的狩猎中证明了自己的实力，如今受命追踪那头名叫泰希斯的狡猾迅猛龙，并带回它的利爪。",h="在荆棘谷深处，赫米特·奈辛瓦里向老练的追踪者发出挑战，要他们猎杀一头连他也未能捕获的神出鬼没的掠食者。你已在对付较弱野兽的狩猎中证明了自己的实力，如今受命追踪那头名叫泰希斯的狡猾迅猛龙，并带回它的利爪。",kw={"艾耶克·罗欧克","古拉巴什竞技场","赫米特·奈辛瓦里","猎龙","荆棘谷","泰希斯 的利爪","泰希斯"},sec={{t="谷中的狡猾掠食者",b="在你完成先前的丛林试炼后，赫米特·奈辛瓦里告诉你，这里有一头名叫泰希斯的迅猛龙，格外凶残。当那些本领平平的猎人还在草木间追逐猎物时，泰希斯却始终未被捕获，连远征队的首领也拿它无可奈何。艾耶克·罗欧克为这头野兽取了这个名字，将它视为荆棘谷那些身披鳞甲的恐怖野兽中最值得猎取的目标。"},{t="夺取利爪",b="要获得顶尖大型猎物猎人的认可，你受命前往古拉巴什竞技场以北一带搜寻，那里是泰希斯时常出没的地方。杀死这头可怕的野兽并带回它的利爪，你就能赢得迅猛龙猎杀大师的称号，这是其他大型猎物猎人都未曾达成的壮举。"}},faq={{q="谁派你去猎杀泰希斯？",a="在你猎杀普通的丛林迅猛龙、证明了自己的追踪本领后，赫米特·奈辛瓦里便从荆棘谷北部的远征队营地指派你展开这场狩猎。",al={"谁发布 猎龙","猎龙 任务发布者","谁想杀死 泰希斯"}},{q="在哪里能找到泰希斯？",a="这头凶猛的野兽在古拉巴什竞技场周围的丛林荒野中游荡，最常有人在竞技场以北的灌木丛中发现它。",al={"泰希斯 位置","泰希斯 在哪里","哪里能找到 泰希斯"}},{q="赫米特 要求用什么证明猎杀成功？",a="赫米特 要求带回泰希斯的利爪，以此确凿地证明这头狡猾的野兽终于被杀死了。",al={"要给 赫米特 带什么","泰希斯 猎杀证明","猎龙 任务交付物品"}},{q="最初是谁给这头迅猛龙取名为泰希斯？",a="奈辛瓦里远征队营地的猎人之一艾耶克·罗欧克，为这头神出鬼没的掠食者取名为泰希斯。",al={"谁给 泰希斯 取的名字","泰希斯 名字的由来"}}},fp="14,192,29.229.0,18.187.0,29.173.0,26.100.0,42.77.0,39.98.0"}
P.entries["quest:1978"] = {n="亡灵哨兵",s="此项差事标志着一名能干的特工正式加入死亡追踪者——这个被遗忘者的刺客与间谍组织。信使的任务是将安德隆的账本直接递交给恐惧魔王瓦里玛萨斯，从而将辛迪加进行秘密活动的证据呈送给幽暗城最高层的领导者。",h="此项差事标志着一名能干的特工正式加入死亡追踪者——这个被遗忘者的刺客与间谍组织。信使的任务是将安德隆的账本直接递交给恐惧魔王瓦里玛萨斯，从而将辛迪加进行秘密活动的证据呈送给幽暗城最高层的领导者。",kw={"奥特兰克","安德隆的账本","死亡追踪者","黑暗女王之殿","曼内特·卡卡德","辛迪加","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="此次入职代表着正式进入被遗忘者专业的潜行者队伍，将普通的扒手提升为国家资助的情报特工。",["faction:Horde"]="虽然这是被遗忘者内部的安全事务，但监视奥特兰克的人类残部可以保护北部部落领土免受颠覆性的破坏。",["race:Undead"]="对于被遗忘者而言，加入死亡追踪者就是一项直接的誓言：保护洛丹伦脆弱的主权，抵御人类幸存者和潜伏的叛徒。"},sec={{t="踏入阴影",b="在从安德隆·甘特手中发掘出确凿的罪证后，曼内特·卡卡德正式欢迎这位特工加入死亡追踪者。该组织是希尔瓦娜斯女王在洛丹伦各地的耳目与利刃，依靠情报网络、残酷的效率和隐秘行动在威胁显露之前将其消灭。对于幽暗城中任何有志于成为潜行者或斥候的人来说，获得该组织的正式认可是一个重要的里程碑。"},{t="辛迪加的勾结",b="这项秘密调查的战利品就是安德隆的账本，它揭露了当地特工与辛迪加之间的非法勾结。辛迪加曾是已陨落的人类王国奥特兰克的贵族，但在第二次战争王国覆灭后，他们转而从事强盗行径和颠覆活动。卡卡德对这些奥特兰克陨落贵族的堕落程度感到惊讶与鄙夷，他们竟沦落到靠琐碎的阴谋来夺回权力的地步。"},{t="觐见恐惧魔王",b="由于这份情报极其敏感，账本被直接送到了幽暗城皇家区的瓦里玛萨斯手中。这位纳斯雷兹姆指挥官在希尔瓦娜斯·风行者的麾下监管着被遗忘者的战术情报工作。瓦里玛萨斯对死亡追踪者的主动出击感到满意，欢迎这位特工展示出的能力，并指出他的情报部门总是需要像这样能交付成果的人。"}},faq={{q="什么是死亡追踪者？",a="死亡追踪者是被遗忘者首屈一指的间谍、侦察和暗杀组织。他们的总部位于幽暗城的盗贼区，在整个洛丹伦展开行动，以清除政治对手、渗透敌对派系，并保护被遗忘者的疆域免受外部和内部的颠覆。",al={"谁是死亡追踪者","死亡追踪者背景","被遗忘者刺客"}},{q="为什么辛迪加会卷入其中？",a="缴获的账本揭示了与辛迪加的秘密往来，这些流离失所的奥特兰克贵族已经沦为有组织犯罪的强盗。被遗忘者时刻监视着在他们领土内活动的奥特兰克残部，因为辛迪加特工一直在寻找机会夺回失地并掠夺整个北洛丹伦的资源。",al={"为什么是辛迪加","奥特兰克关联","辛迪加账本"}},{q="为什么要直接向瓦里玛萨斯汇报？",a="瓦里玛萨斯担任希尔瓦娜斯女王的战术顾问，负责监督幽暗城的安全和情报行动。涉及外国阴谋的重大发现（例如辛迪加的秘密行动）需要最高行政级别的审查，以便协调更广泛的军事和外交应对措施。",al={"为什么是瓦里玛萨斯","瓦里玛萨斯是谁","恐惧魔王职责"}},{q="曼内特·卡卡德是谁？",a="曼内特·卡卡德是死亡追踪者在幽暗城的一名资深联络员和负责人。他负责监管外勤特工，评估新兵，并在将关键发现上报指挥链之前筛选搜集到的情报。",al={"曼内特·卡卡德职责","任务发布者卡卡德"}},{q="觐见在什么地方举行？",a="觐见在位于幽暗城深处皇家区的黑暗女王之殿举行。瓦里玛萨斯站在希尔瓦娜斯·风行者女王身边，位于被遗忘者权力中心的核心地带。",al={"瓦里玛萨斯在哪里","黑暗女王之殿位置"}},{q="加入死亡追踪者后会发生什么？",a="随着你的资历得到认可，且你对曼内特·卡卡德和瓦里玛萨斯的可靠性也已得到证明，你被视为被遗忘者值得信赖的外勤特工，这也为你未来在洛丹伦纷争不断的土地上执行侦察和清除任务铺平了道路。",al={"死亡追踪者后续任务","接下来做什么"}}},fp="17,155,26.343.0,24.340.1,27.317.0,27.280.0,30.283.0,35.236.0,22.208.0,36.180.0,45.249.0"}
P.entries["quest:198"] = {n="列兵索尔森的补给物资",s="藏宝海湾的克拉兹克雇用一名信使，将地精杂货补给运往北方多伦上尉的营地。当地巨魔的袭击使例行运输陷入停顿，需要外人出手，确保货物送到北部边界附近的列兵索尔森手中。",h="藏宝海湾的克拉兹克雇用一名信使，将地精杂货补给运往北方多伦上尉的营地。当地巨魔的袭击使例行运输陷入停顿，需要外人出手，确保货物送到北部边界附近的列兵索尔森手中。",kw={"藏宝海湾","暮色森林","地精补给","克拉兹克","库尔森","多伦上尉","列兵索尔森","荆棘谷"},ang={["faction:Alliance"]="多伦上尉的士兵守卫着从暮色森林进入荆棘谷的北部入口，依靠地精提供的补给坚守阵地。"},sec={{t="受阻的运输路线",b="多伦上尉和他的部队驻扎在荆棘谷与暮色森林交界处附近，依靠克拉兹克安排的定期补给。当地巨魔接连发动袭击，使常规运输变得危险，促使这位地精商人雇用一名独立信使。这件包裹必须沿着丛林道路一路向北运送，由列兵索尔森接收，他可能在道路西北方的营地里，也可能在南面的巡逻路线上。"},{t="货物的真实内容",b="这批货物虽然只被列为地精杂货补给，里面装的却是地雷。列兵索尔森透露，这些爆炸物将用于协助守卫哨所，抵御库尔森上校及其手下。"}},faq={{q="这些补给是谁送来的？",a="在藏宝海湾做生意的地精商人克拉兹克负责安排运输并提供补给。",al={"谁给索尔森提供补给","克拉兹克送货","谁发布列兵索尔森的补给物资"}},{q="补给为什么迟迟未到？",a="荆棘谷当地巨魔的袭击打乱了常规运输，多伦上尉的手下只能等待原定送达的货物。",al={"为何延误","巨魔袭击运输","为何没有送达"}},{q="在哪里可以找到列兵索尔森？",a="他可能在多伦上尉的营地里，营地位于从暮色森林进入荆棘谷的入口附近，在主路的西北方；他也可能在紧邻营地南侧的小路上巡逻。",al={"索尔森在哪里","索尔森位置","寻找列兵索尔森"}},{q="如果补给丢失了会怎样？",a="克拉兹克警告说，任何未能送达货物的人都要承担经济责任，向他作出赔偿。",al={"补给丢了怎么办","克拉兹克赔偿","未完成克拉兹克的委托"}}},fp="27,181,17.387.0,28.190.1,30.90.0,35.142.0,35.182.0,38.120.0"}
P.entries["quest:199"] = {n="水坝危机",s="巨石水坝正面临蓄意破坏的威胁，这道屏障拦蓄着洛克莫丹的湖水。你在岸边发现了一只桶，并将里面的怪味粉末带给主工程师辛德维尔七世。",h="巨石水坝正面临蓄意破坏的威胁，这道屏障拦蓄着洛克莫丹的湖水。你在岸边发现了一只桶，并将里面的怪味粉末带给主工程师辛德维尔七世。",kw={"水坝危机","辛德维尔七世","洛克莫丹","蓄意破坏","巨石水坝","怪味粉末","可疑的桶"},ang={["profession:Engineering"]="身为工程师，你明白将不稳定的粉末刻意放在大型水坝的受力点上有多么危险。",["race:Dwarf"]="身为矮人，你知道巨石水坝是铁炉堡矮人最伟大的建筑成就之一。任何针对它的威胁，都会危及卡兹莫丹的安全与荣耀。",["race:Gnome"]="身为侏儒，你深知矮人土木工程的精密。因此，这种粗劣破坏手段所用的化学物质格外令人担忧。"},sec={{t="可疑的发现",b="有人企图破坏巨石水坝的传闻，已传到了水坝周围的湖岸。一只桶出现在水边，本不该放在那里。桶里装着气味刺鼻的怪异粉末，远离水坝的维修物资。"},{t="水坝告急",b="你带来的样本令主工程师辛德维尔七世大为震惊。他的反应证实了洛克莫丹最深的忧虑：一股外来势力正密谋破坏水坝。为了守护这片地区，调查已刻不容缓。"}},faq={{q="怪味粉末是什么？",a="桶里的怪味粉末是一种炸药或炼金制剂，被人放在巨石水坝底部附近。它证明有敌人正密谋摧毁或削弱这道屏障。",al={"奇怪的粉末","桶里有什么","可疑的桶里的粉末"}},{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世是一位矮人工程大师，负责洛克莫丹巨石水坝的维护、结构完好与安全。",al={"辛德维尔七世是谁","主工程师辛德维尔七世","水坝工程师"}},{q="可疑的桶在哪里？",a="可疑的桶藏在洛克莫丹北部的湖岸边，靠近巨石水坝的地基。",al={"桶的位置","桶在哪里","洛克莫丹的桶"}},{q="为什么有人要破坏巨石水坝？",a="巨石水坝拦蓄着洛克莫丹浩瀚的湖水。一旦决堤，灾难性的洪水便会席卷下方的湿地，重创联盟的贸易路线，并摧毁矮人遍布卡兹莫丹的领地。",al={"为什么要摧毁水坝","破坏水坝","洛克莫丹面临的威胁"}},{q="是谁把可疑的桶留在这里的？",a="这只桶是企图扰乱矮人领地的密探放置的。主工程师辛德维尔七世已展开更广泛的调查，追查这场阴谋的幕后主使。",al={"谁放置了桶","破坏者","谁放了粉末"}},{q="收集粉末后该做什么？",a="将样本带给巨石水坝顶上的主工程师辛德维尔七世，让他检查并准备应对措施。",al={"接下来做什么","交付粉末","找谁交谈"}}},fp="19,205,22.211.0,16.224.1,36.192.0,37.149.0,37.114.0,43.219.0,36.151.0,45.119.0"}
P.entries["quest:1998"] = {n="芬维克·萨托斯",s="在幽暗城，米奈特·卡加德奉瓦里玛萨斯大人之命，派遣有潜力的潜行者去杀死芬威克萨托斯。萨托斯被怀疑在银松森林沿岸集结不受统属的亡灵。他的死能向亡灵哨兵证明一名密探的本领，并为其赢得接受进阶技艺训练的机会。",h="在幽暗城，米奈特·卡加德奉瓦里玛萨斯大人之命，派遣有潜力的潜行者去杀死芬威克萨托斯。萨托斯被怀疑在银松森林沿岸集结不受统属的亡灵。他的死能向亡灵哨兵证明一名密探的本领，并为其赢得接受进阶技艺训练的机会。",kw={"亡灵哨兵","芬威克 萨托斯","洛丹米尔湖","米奈特·卡加德","潜行者区","银松森林","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="作为一名潜行者，你通过这份契约证明自己的潜行本领与致命手段。之后，亡灵哨兵或许会信任你，传授更深奥的行内技艺。",["race:Undead"]="身为被遗忘者的一员，你知道敌对的亡灵阵营不能在如此靠近首都的地方宣称主权。芬威克萨托斯的头颅，是政治上的必需之物。"},sec={{t="恐惧魔王的命令",b="在幽暗城的潜行者区，米奈特·卡加德负责处理亡灵哨兵的契约任务，并训练潜行者。亡灵哨兵是被遗忘者的秘密情报组织。瓦里玛萨斯大人已将芬威克萨托斯列为优先铲除的目标，这项任务太过重大，不能交给初入行的新兵。萨托斯已在银松森林不受统属的亡灵中建立了据点。如果放任不管，这些独立的首领可能会威胁被遗忘者对洛丹伦旧日领地的控制。"},{t="洛丹米尔湖 的破败码头",b="亡灵哨兵的斥候发现，芬威克萨托斯就在银松森林洛丹米尔湖的一座破败码头附近。要找到他，你必须穿过被凶猛野兽、腐皮豺狼人和 天灾军团 残部占据的荒野。瓦里玛萨斯要求带回击杀的证据：萨托斯被斩下的头颅。将它带回来，你便可能获准参与更深入的秘密行动。"}},faq={{q="芬威克萨托斯是谁？",a="芬威克萨托斯统领着银松森林洛丹米尔湖附近的亡灵。与效忠 希尔瓦娜斯 女士的被遗忘者不同，他指挥着一些不归属幽暗城、甚至与幽暗城为敌的亡灵群体。瓦里玛萨斯大人已下令将他处死。",al={"芬威克背景故事","萨托斯是谁","芬威克 萨托斯背景"}},{q="瓦里玛萨斯为何要杀死芬威克萨托斯？",a="瓦里玛萨斯要杀死芬威克萨托斯，是因为他可能集结银松森林四散的亡灵，对抗被遗忘者。为了确保幽暗城边境的安全，必须铲除那些威胁 希尔瓦娜斯 对这一地区控制的敌对首领。",al={"瓦里玛萨斯 萨托斯","为何杀死芬威克"}},{q="亡灵哨兵是什么组织？",a="亡灵哨兵是被遗忘者负责间谍、暗杀和侦察事务的机构。他们以幽暗城的潜行者区为基地，在洛丹伦各地行动，清除内部威胁，刺探敌对阵营的情报，并为黑暗女王巩固领地。",al={"亡灵哨兵背景故事","亡灵哨兵是什么组织","亡灵潜行者阵营"}},{q="芬威克萨托斯在哪里？",a="据亡灵哨兵的报告，芬威克萨托斯就在银松森林东北部、洛丹米尔湖岸边的一座废弃码头附近。",al={"芬威克在哪里","芬威克码头位置","萨托斯 洛丹米尔湖"}},{q="完成这项任务能从亡灵哨兵那里获得什么？",a="杀死芬威克萨托斯，能向米奈特·卡加德和亡灵哨兵证明你的能力与忠诚。当你证明自己值得信任后，卡加德就会提供专门的暗影技艺训练。",al={"芬威克奖励背景","芬威克之后是什么"}},{q="米奈特·卡加德是谁？",a="米奈特·卡加德在幽暗城的潜行者区训练潜行者，并处理亡灵哨兵的事务。他负责督管外勤密探，并分派与被遗忘者领地安全有关的任务。",al={"米奈特·卡加德","谁发布芬威克任务"}}},fp="15,300,28.448.0,30.338.0,23.232.0,47.226.0,26.253.0,33.122.0,62.190.0,21.177.0"}
P.entries["quest:1999"] = {n="交易工具",s="在幽暗城，部落盗贼受命前往安伯米尔窃取一份报告。瓦里玛萨斯大人命令他们取得开锁工具，并从肯瑞托的情报中了解达拉然的状况。",h="在幽暗城，部落盗贼受命前往安伯米尔窃取一份报告。瓦里玛萨斯大人命令他们取得开锁工具，并从肯瑞托的情报中了解达拉然的状况。",kw={"安伯米尔","达拉然","亡灵哨兵","艾斯特蕾·根德瑞","肯瑞托","开锁","米奈特·卡加德","潜行者区","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="作为一名部落盗贼，你凭借正规的开锁工具、潜行和精巧的手法证明自己的价值，而非蛮力。",["faction:Horde"]="作为部落的一员，你协助获取银松森林的人类情报，并巩固部落在洛丹伦北部对抗联盟残余势力的立足点。",["race:Undead"]="作为一名亡灵，你协助被遗忘者以智谋对抗那些企图收复洛丹伦的肯瑞托法师。"},sec={{t="目光投向安伯米尔",b="对一名囚犯的审讯让亡灵哨兵得知，安伯米尔藏着一份情报。银松森林仍是局势不稳的前线，人类法师严密守护着村庄的通信。瓦里玛萨斯大人命令亡灵哨兵联络人米奈特·卡加德，引导有潜力的特工绕过肯瑞托哨兵，取回达拉然形势报告。"},{t="潜入之道",b="潜入与开锁考验的是暗杀之外的本领。进入肯瑞托领地之前，特工们要从艾斯特蕾·根德瑞那里领取专用的盗贼工具。打开安伯米尔那只严密上锁的箱子，便证明一名特工能够超越街头的暴力手段，为被遗忘者的谍报工作效力。"}},faq={{q="谁下令执行这项任务？",a="幽暗城潜行者区的亡灵哨兵盗贼米奈特·卡加德负责分派这项工作。瓦里玛萨斯大人下达命令，并监督被遗忘者的情报收集工作。",al={"谁发布交易工具","任务发布者","米奈特 卡加德任务"}},{q="达拉然形势报告是什么？",a="达拉然形势报告是一份密封的肯瑞托公文，记载着达拉然的状况。亡灵哨兵审讯者从一名囚犯口中得知了它的下落，暴露出有关被遗忘者南方邻居的重要情报是多么容易泄露。",al={"文件是什么","肯瑞托文件","形势报告"}},{q="报告存放在哪里？",a="报告放在银松森林南部的肯瑞托前哨安伯米尔，藏于一只上锁的箱子中。",al={"文件在哪里","安伯米尔箱子位置","形势报告在哪里"}},{q="谁提供开锁工具？",a="幽暗城潜行者区的装备商艾斯特蕾·根德瑞提供打开上锁箱子所需的盗贼工具。",al={"工具在哪里领取","艾斯特蕾·根德瑞的职责","装备商工具"}},{q="为什么达拉然眼下对被遗忘者如此重要？",a="达拉然幸存的法师正在重建他们的城市，与银松森林隔着洛丹米尔湖相望。被遗忘者监视着肯瑞托，以保护他们在洛丹伦的领地。",al={"为何关注达拉然","被遗忘者与达拉然","肯瑞托的威胁"}},{q="接受这项任务前必须完成什么前置任务？",a="特工必须先完成刺杀委托“芬威克萨托斯”，在银松森林猎杀一名目标，米奈特·卡加德才会放心将需要谨慎行事的潜入工作交给他们。",al={"前置条件","前置任务是什么","芬威克 萨托斯任务"}}},fp="18,191,17.363.0,21.305.0,24.170.0,34.238.0,25.104.0,35.129.0,51.176.0,63.178.0"}
P.entries["quest:2"] = {n="沙普塔隆的爪子",s="将沙普塔隆的爪子带离森林后，灰谷的林间小径便会更安全。把这件战利品交给碎木岗哨的塞娜尼·雷心，证明沙普塔隆已被击杀，并保护部落的补给线。",h="将沙普塔隆的爪子带离森林后，灰谷的林间小径便会更安全。把这件战利品交给碎木岗哨的塞娜尼·雷心，证明沙普塔隆已被击杀，并保护部落的补给线。",kw={"灰谷","灰谷狩猎","角鹰兽","苦工","塞娜尼·雷心","沙普塔隆","碎木岗哨","战歌"},ang={["class:Hunter"]="身为猎人，你将挑战沙普塔隆，检验自己的追踪本领与射击技艺，它是灰谷茂密林冠下令人畏惧的飞行掠食者。",["faction:Horde"]="身为部落的一员，你帮助保障战歌伐木作业所用道路的安全，并保护往来于前沿哨站和碎木岗哨之间的苦工。",["race:Orc"]="身为兽人，你清除森林上空的威胁，让Warsong clan艰辛的伐木工作轻松一些。",["race:Tauren"]="身为牛头人，你遵循塞娜尼·雷心的狩猎指引，依照牛头人的传统，挑战自然界最凶猛的野兽来考验自己。"},sec={{t="林间小径的祸患",b="部落在灰谷寻求资源时，沙普塔隆在通往碎木岗哨的道路上猎食。这头凶猛的角鹰兽袭击往来于前沿伐木营地与岗哨之间的苦工和信使。它的袭击阻碍了部落在这一带的工作，而暗夜精灵哨兵与危险的野兽也都在威胁着这些新来者。"},{t="狩猎的证明",b="牛头人女猎手塞娜尼·雷心指引部落猎人对付灰谷最致命的掠食者。沙普塔隆的利爪能证明这头角鹰兽已被击杀。将这件战利品带到碎木岗哨，那里的守卫会向这次狩猎致敬，惊恐的劳工穿行林间时也能少些畏惧。"}},faq={{q="沙普塔隆是什么？",a="沙普塔隆是一头在灰谷猎食的凶猛角鹰兽。它会伏击穿行林间的旅人。",al={"沙普塔隆是谁","沙普塔隆怪物","沙普塔隆是什么野兽"}},{q="塞娜尼·雷心为什么想要这只爪子？",a="塞娜尼·雷心想用这只爪子证明，威胁部落工人和补给路线的掠食者沙普塔隆已被击杀。",al={"为什么交付爪子","塞娜尼·雷心战利品","沙普塔隆的爪子的用途"}},{q="在哪里交付沙普塔隆的爪子？",a="将爪子交给灰谷东部碎木岗哨的塞娜尼·雷心。",al={"在哪里交付","谁收取爪子","爪子交付地点"}},{q="击杀沙普塔隆对部落有什么帮助？",a="沙普塔隆会袭击往来于偏远伐木场和碎木岗哨之间的苦工。击杀它能让补给、木材的运输和信使的往来更加安全。",al={"击杀沙普塔隆的背景","部落为何关注沙普塔隆"}},{q="这个任务属于更大的任务链吗？",a="是的。它属于灰谷狩猎，这是塞娜尼·雷心的一系列野兽狩猎任务，以狩猎完成结束。",al={"灰谷狩猎任务链","沙普塔隆任务链"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是碎木岗哨的一名牛头人女猎手。她关注森林的平衡，并让部落猎人挑战灰谷最危险的生物，以此考验他们。",al={"塞娜尼背景","塞娜尼是谁"}}},fp="17,164,30.325.0,17.293.0,19.118.0,43.127.0,37.80.0,43.153.0,37.124.0,27.165.0"}
P.entries["quest:20"] = {n="黑石氏族的威胁",s="赤脊山的黑石兽人从北方和东南方步步进逼，让湖畔镇陷入围困。治安官马瑞斯号召冒险者削减他们的兵力，并带回他们的破斧。",h="赤脊山的黑石兽人从北方和东南方步步进逼，让湖畔镇陷入围困。治安官马瑞斯号召冒险者削减他们的兵力，并带回他们的破斧。",kw={"斧头","黑石","燃烧平原","湖畔镇","玛瑞斯","兽人","赤脊山","石堡","萨瑞尔祖恩"},ang={["class:Warrior"]="身为战士，在前线上与身经百战的黑石掠夺者持盾交锋，将考验你的战斗纪律与力量。",["faction:Alliance"]="对联盟而言，保卫湖畔镇有助于守住暴风城的南部边境，抵御旧世界的仇敌。",["race:Human"]="身为人类，在赤脊山面对黑石氏族会勾起沉痛的悲伤：他们曾在第一次兽人战争中摧毁了最初的暴风城王国。"},sec={{t="受困的小镇",b="湖畔镇面临来自多方的威胁，但黑石兽人是最大的危险。这些身经百战的掠夺者从烈焰熊熊的燃烧平原南下，进入赤脊山。他们占据据点，在崎岖的山口间游荡。他们的存在让镇民困守湖畔镇，北方道路上的贸易、采集和出行都被切断。"},{t="打击先头部队",b="治安官马瑞斯统领着湖畔镇处境艰难的卫兵，却抽不出兵力进攻兽人的阵地。他号召你出击，打击他们的前哨斥候和步兵。他们粗陋的破斧将成为死亡的凭证。马瑞斯希望削减北方石堡周围，以及赤脊山东南部崎岖地带的入侵者兵力。"}},faq={{q="这些黑石兽人从何而来？",a="他们从燃烧平原穿过险峻的山口向南进军，他们祖传的堡垒就坐落在那里的黑石山周围。",al={"兽人来自哪里","黑石入侵赤脊山","兽人为何在赤脊山"}},{q="谁发布了这项任务？",a="命令由湖畔镇的高级军官治安官马瑞斯发布。随着小镇逐渐被包围，他肩负着保卫小镇、维持秩序的职责。",al={"谁发布黑石氏族的威胁","黑石氏族的威胁任务发布者","治安官马瑞斯的任务"}},{q="在哪里能找到黑石入侵者？",a="黑石入侵者占据了石堡要塞周围的北部高地，也在赤脊山东南部的一片地带建立了据点。",al={"黑石兽人在哪里","破斧位置","赤脊山兽人营地"}},{q="治安官马瑞斯为什么要收集破斧？",a="这些破斧能向治安官马瑞斯提供实物凭证，证明你与威胁山谷的黑石掠夺者交过手，并杀死了他们。",al={"为何收集斧头","死亡凭证","破斧用途"}},{q="击败这些斥候之后会发生什么？",a="先头部队遭到削弱后，治安官马瑞斯会下令进攻萨瑞尔祖恩，这名当地的黑石首领盘踞在群山之中。",al={"黑石氏族的威胁之后是什么","黑石氏族的威胁的后续任务","谁统领兽人"}},{q="这些兽人隶属于萨尔的部落吗？",a="不。这里的黑石氏族由旧部落的残余势力组成。他们依旧极端仇视联盟，行动独立于萨尔在卡利姆多建立的新部落。",al={"这些是部落兽人吗","黑石氏族属于萨尔的部落吗","赤脊山的友善兽人"}}},fp="16,173,18.325.0,21.350.0,41.140.0,21.166.0,42.141.0,48.129.0,45.137.1,44.164.0"}
P.entries["quest:200"] = {n="书呆子赫罗德",s="在库尔森发现了索森的秘密后，多伦上尉担心他的人中混入了间谍。为了查明秘密是如何泄露的，调查者必须潜入库尔森的营地，并找回库尔森的后勤军官所保存的记录。",h="在库尔森发现了索森的秘密后，多伦上尉担心他的人中混入了间谍。为了查明秘密是如何泄露的，调查者必须潜入库尔森的营地，并找回库尔森的后勤军官所保存的记录。",kw={"赫洛德","库尔森上校","库尔森的营地","多伦上尉","荆棘谷","索森"},ang={["faction:Alliance"]="多伦上尉和他的手下曾与库尔森上校站在同一阵线，后来脱离了队伍，现在他们正在自己的队伍中搜寻间谍。"},sec={{t="队伍中的内鬼",b="在索森的秘密被发现后，多伦上尉怀疑他们之中出了叛徒。这次情报泄露威胁到了他们的行动，找出叛徒已成了当务之急。索森通过赫洛德——这位上校的后勤军官，与库尔森的营地保持着直接的通讯联系。由于赫洛德熟悉库尔森的营地日常运作方式，多伦认为这位军官的书面记录中藏着这次行动是如何暴露的真相。"},{t="后勤办公室",b="想要拿到赫洛德的文件，就必须冒险进入库尔森的营地。在多伦曾效力于库尔森的那段时间里，赫洛德将他的办公室设在营地唯一一栋两层建筑的顶楼。在那里，在物资征用单和库尔森上校亲笔书写的公文之间，存放着能追查到秘密是如何被出卖的文件。"}},faq={{q="赫洛德是谁？",a="赫洛德是库尔森上校手下的后勤军官。他负责监管库尔森的营地物资和日常运作，并且此前一直是索森的内线联系人。",al={"赫洛德的职责","赫洛德是谁","赫洛德背景故事"}},{q="为什么多伦上尉想要赫洛德的记录？",a="多伦上尉认为有间谍出卖了他们的营地，因为库尔森上校知道了索森的秘密。多伦希望通过赫洛德的后勤日志和信件，查明情报是如何泄露的。",al={"为什么要获取赫洛德的记录","多伦的间谍","索森是如何被抓的"}},{q="赫洛德的记录在哪里？",a="赫洛德的办公室位于库尔森的营地内唯一一栋两层建筑的顶楼，多伦认为他的记录很可能还保存在那里。",al={"记录在哪里","赫洛德办公室位置","库尔森的两层建筑"}},{q="在这次调查之前发生了什么？",a="这次调查紧接着“丛林秘密”任务，在那个任务中，多伦上尉断定必然有人将索森的秘密出卖给了库尔森的手下。",al={"前置任务","赫洛德的前置条件"}}},fp="12,196,19.321.0,20.258.0,20.170.0,47.187.0,41.141.0,37.141.0"}
P.entries["quest:201"] = {n="调查营地",s="“调查营地”是一项源自藏宝海湾的探险任务，旨在侦察荆棘谷新建立的一个猎人营地。受克拉兹克委派，这项任务要求旅行者证实有关传奇矮人神枪手赫米特·奈辛瓦里已经抵达纳菲瑞提湖附近的传言。",h="“调查营地”是一项源自藏宝海湾的探险任务，旨在侦察荆棘谷新建立的一个猎人营地。受克拉兹克委派，这项任务要求旅行者证实有关传奇矮人神枪手赫米特·奈辛瓦里已经抵达纳菲瑞提湖附近的传言。",kw={"藏宝海湾","赫米特·奈辛瓦里","猎人营地","调查营地","克拉兹克","纳菲瑞提湖","荆棘谷","荆棘谷地精"},ang={["class:Hunter"]="一支由著名猎人赫米特·奈辛瓦里带领的大型猎物猎人团队的传闻聚会，自然吸引了许多希望在丛林中磨练技术的追踪和射击爱好者。",["race:Dwarf"]="赫米特·奈辛瓦里是最著名的矮人神枪手和冒险家之一，他的出现让荆棘谷遥远的南方荒野增添了一份自豪与好奇。"},sec={{t="丛林中的报告",b="在藏宝海湾的码头流传着一份报告，称有一群大型猎物的猎人探险队在荆棘谷的北部丛林中扎营。克拉兹克收到消息，营地位于纳菲瑞提湖附近荆棘谷地精繁忙的采矿点上游的河边。在一个充满危险和利益冲突的无法律地带，不明身份的武装营地总是需要警惕的目光。"},{t="一位著名的神枪手",b="这次探险之所以引人注目，是因为有传言称赫米特·奈辛瓦里本人也在其中。这位著名的矮人神枪手在各地都被视为拥有强大关系网的精英探险家。克拉兹克不希望对这些在边远地区活动的有影响力的人物掉以轻心，于是派遣侦察兵沿河而上，以确认这位传奇猎人是否真的已经到来。"}},faq={{q="谁发布了调查营地的任务？",a="克拉兹克，驻扎在藏宝海湾的中立地精港口的一名特工，委派旅行者前往寻找该营地并汇报其确切位置。",al={"谁想要调查营地","谁发布了这个任务","克拉兹克 藏宝海湾"}},{q="赫米特·奈辛瓦里是谁？",a="赫米特·奈辛瓦里是一位著名的大型猎物矮人猎人和探险家。消息传到藏宝海湾，称他正在纳菲瑞提湖附近的猎人营地中，由于他极高的声望和人脉，这一消息引起了人们的关注。",al={"赫米特·奈辛瓦里 荆棘谷","赫米特·奈辛瓦里是谁","著名矮人猎人 荆棘谷"}},{q="猎人营地在哪里？",a="猎人们在荆棘谷北部纳菲瑞提湖沿岸的荆棘谷地精采矿作业点的上游建立了营地。",al={"猎人营地位置","奈辛瓦里营地在哪里","上游营地在哪里"}},{q="为什么克拉兹克对这个狩猎营地感兴趣？",a="通常情况下，一个偏远的猎人营地不会引起藏宝海湾的太大兴趣，但关于赫米特·奈辛瓦里这样有影响力且关系广泛的人物出现在那里的报告，引起了警惕和好奇。",al={"克拉兹克为何关心","为何调查猎人","克拉兹克动机"}},{q="猎人与荆棘谷地精是什么关系？",a="猎人们并不属于荆棘谷地精；他们的营地只是位于纳菲瑞提湖附近该地精集团的采矿设施的上游，仅作为地理标志。",al={"荆棘谷地精关系","猎人是否属于荆棘谷地精","荆棘谷地精 纳菲瑞提湖"}},{q="找到营地后向谁汇报？",a="一旦定位并侦察了河边的营地，你需要回到南方的藏宝海湾，直接向克拉兹克交付报告。",al={"找到营地后做什么","向谁汇报","调查营地任务交还地点"}}},fp="20,145,21.270.0,19.230.0,43.87.0,24.198.0,35.129.0,46.112.0,57.154.0,45.101.0"}
P.entries["quest:202"] = {n="库尔森上校",s="多伦上尉要求你对库尔森上校及其内卫部队进行最后一击。你被派往库存区，去消灭这位叛变的指挥官和他剩余的头目，以确保反抗军营地的生存。",h="多伦上尉要求你对库尔森上校及其内卫部队进行最后一击。你被派往库存区，去消灭这位叛变的指挥官和他剩余的头目，以确保反抗军营地的生存。",kw={"库尔森上校","库尔森","多伦上尉","反抗军营地","库存区","荆棘谷"},ang={["faction:Alliance"]="消灭库尔森可以打破一位暴风城叛变军官对荆棘谷北部地区的控制。"},sec={{t="库存区的核心",b="多伦上尉和他的一群变节者已经达到了与前任指挥官斗争的高潮。在镇压了库尔森的精锐专家后，多伦认识到，只要库尔森还控制着他在丛林中的堡垒，反抗军就永远不会真正安全。他指引你进入库存区的洞穴，库尔森正和他的副官及精锐部队在那里指挥他的军队。"},{t="斩首行动",b="为了彻底消除威胁，多伦要求你带回库尔森的头颅作为他覆灭的决定性证据，并击败他的精锐和副官。进入洞穴直面库尔森的领导层，是反抗军在荆棘谷北部险境中唯一能喘息的机会。"}},faq={{q="谁指派了这个任务？",a="在完成“特种部队”任务后，多伦上尉会从位于荆棘谷北部的反抗军营地派你去追捕库尔森。",al={"任务发放者","任务给予者","库尔森上校任务接取地点"}},{q="库尔森上校在哪里？",a="库尔森在荆棘谷北部库尔森营地内的库存区洞穴深处指挥他的部队。",al={"库尔森在哪里","库尔森位置","如何找到库尔森上校"}},{q="多伦上尉需要什么证据？",a="多伦上尉要求你带回库尔森的头颅，以确凿地证明这位叛变的指挥官已经倒下，此外还需要击败他的精锐和副官。",al={"需要什么证明","库尔森的证明","任务交还物品"}},{q="在这次对抗之前发生了什么？",a="这次对抗紧接在“特种部队”任务之后，在那个任务中，你削弱了库尔森的特种战场作战人员，随后才将目标对准了他的核心指挥结构。",al={"前置任务","上一个任务是什么","库尔森任务线"}}},fp="14,137,26.318.0,27.260.0,22.113.0,32.123.0,41.139.0,36.127.0"}
P.entries["quest:203"] = {n="以彼之道还施彼身",s="在北荆棘谷的反抗军营地中，尤瓦中士正在寻求帮助，以对抗库尔森上校那势不可挡的军队。面对人数十倍于己的狡诈战术家，反抗军必须依靠迅捷的隐秘打击才能生存。消灭库尔森的丛林战士是减轻他们据点所受压力的第一步。",h="在北荆棘谷的反抗军营地中，尤瓦中士正在寻求帮助，以对抗库尔森上校那势不可挡的军队。面对人数十倍于己的狡诈战术家，反抗军必须依靠迅捷的隐秘打击才能生存。消灭库尔森的丛林战士是减轻他们据点所受压力的第一步。",kw={"库尔森上校","丛林战士","库尔森","反抗军营地","尤瓦中士","特种部队","荆棘谷","尤瓦"},sec={{t="节节败退",b="反抗军营地的士兵们面对库尔森上校时正处于极其不利的境地。尤瓦解释说，上校是一位杰出的军事战术家，其部队人数至少是反抗军的十倍。由于无法进行公开的消耗战，反抗军别无选择，只能采取上校自己的隐秘战术，对他的营地发动快速突袭以削减其兵力，并在重装援军赶来报复之前撤离。"},{t="突袭营地",b="为了扭转局势，尤瓦请求你向东深入库尔森的据点，消灭他麾下大量丛林战士。消灭这些步兵可以缓解反抗军营地所承受的压力。"}},faq={{q="尤瓦中士是谁？",a="尤瓦中士是一位驻扎在北荆棘谷反抗军营地的军官，负责协调针对库尔森上校所率领军队的隐秘打击行动。",al={"尤瓦","谁发布第二次叛乱","尤瓦中士"}},{q="库尔森上校的营地在哪里？",a="库尔森上校的营地位于反抗军营地以东，北荆棘谷茂密的荒野之中。",al={"库尔森营地位置","丛林战士在哪里","库尔森位置"}},{q="为什么反抗军使用隐秘战术而不是进行公开战争？",a="反抗军面对的是由杰出军事战略家库尔森上校所率领的部队，人数比例至少为一比十。面对如此悬殊的兵力差距，直接进攻是不可能的，这迫使反抗军只能依赖快速的游击战。",al={"为何隐秘行动","为何不与库尔森公开作战","反抗军战术"}},{q="“第二次叛乱”之后是什么？",a="在消灭了库尔森的丛林战士后，尤瓦中士会提供后续任务，名为“特种部队”。",al={"下一个任务","第二次叛乱之后是什么","第二次叛乱后续任务"}}},fp="20,293,15.380.0,21.217.0,22.139.0,39.112.0,60.200.0,38.97.0"}
P.entries["quest:2038"] = {n="宾格斯的补给品",s="在洛克莫丹的东南岸，宾格斯·雷管的装备被穴居人偷走，困在了那里。你可以找回他的工具和气压炸弹炸药，让他修好旋翼机，重返收复诺莫瑞根的战斗。",h="在洛克莫丹的东南岸，宾格斯·雷管的装备被穴居人偷走，困在了那里。你可以找回他的工具和气压炸弹炸药，让他修好旋翼机，重返收复诺莫瑞根的战斗。",kw={"宾格斯","气压炸弹","布拉斯腾海默","诺莫瑞根","旋翼机","锤子","洛克莫丹","螺丝刀","洛克湖","穴居人","扳手"},ang={["faction:Alliance"]="作为联盟的一员，在洛克莫丹帮助另一位飞行员，既能保障水路安全，也能为收复卡兹莫丹失地的大业出一份力。",["profession:Engineering"]="作为工程师，你知道专用工具和气压炸弹这类不稳定的炸药落在穴居人手中，既危险，也是对精湛工艺的亵渎。",["race:Dwarf"]="作为矮人，你知道洛克湖岛屿上的穴居人威胁着当地的贸易和出行。对他们营地的任何打击，都能帮助Mountaineers。",["race:Gnome"]="作为侏儒，你每找回一件工具，就让族人离空中反攻更近一步，去打击那些令诺莫瑞根窒息的穴居人和麻风侏儒。"},sec={{t="坠入寒水",b="宾格斯·雷管驾驶的旋翼机坠入了洛克莫丹冰冷的湖水中。他晕头转向地爬上岸，湖心岛屿上的穴居人便蜂拥而至。他们偷走了他最贵重的物品。"},{t="受困的侏儒巧思",b="穴居人把宾格斯的装备分散在各个岛上营地里。被偷走的东西包括扳手、螺丝刀和锤子，还有他发明的威力强大、性质不稳定的气压炸弹。这些炸药落在穴居人手里，随时危及过往旅人。"},{t="为了诺莫瑞根",b="宾格斯为解放故乡诺莫瑞根而战，要将地下的穴居人和受辐射的麻风侏儒赶出去。他设想着一场决定性的空袭，但没有工具和气压炸弹，就无法重建飞行器。他的战事仍困在芦苇丛中，无法起飞。"}},faq={{q="宾格斯·雷管为什么被困在洛克莫丹？",a="宾格斯·雷管的旋翼机坠毁后，他便被困在洛克莫丹。他挣扎着爬上东南岸，却遭到附近岛屿上的穴居人伏击，工具和实验炸药也被抢走。",al={"宾格斯为何在这里","宾格斯如何坠机","宾格斯坠机"}},{q="穴居人偷走了哪些物资？",a="穴居人偷走了宾格斯的扳手、螺丝刀、锤子，以及专用炸药气压炸弹。",al={"穴居人偷了什么","宾格斯的物资","宾格斯的哪些物品"}},{q="穴居人把宾格斯的装备带到哪里去了？",a="穴居人把宾格斯的装备带到了洛克湖北部岛屿上的营地。他们把工具和炸药散放在岩石遍布的湖岸上。",al={"宾格斯的工具在哪","穴居人岛屿位置","气压炸弹在哪"}},{q="气压炸弹是什么？",a="气压炸弹是宾格斯设计的一种爆炸装置，用于空袭占据诺莫瑞根的敌人。",al={"气压炸弹是什么","气压炸弹","宾格斯的炸药"}},{q="宾格斯说的是什么行动？",a="宾格斯指的是收复诺莫瑞根。他希望率领一次空中轰炸，打击占据侏儒首都的地下穴居人和麻风侏儒。",al={"什么行动","为了诺莫瑞根","宾格斯的事业"}},{q="宾格斯为什么不能自己取回物资？",a="宾格斯无法取回物资，因为坠机后他孤身一人、手无寸铁，也无法够到旋翼机。对一个孤身的工程师来说，没有武器或飞行器，渡过开阔水面去面对凶恶的穴居人，无异于自寻死路。",al={"宾格斯为何不自己取回","宾格斯为何等待"}}},fx={["008fc445"]={q="宾格斯·雷管为什么想找回他的补给品？",a="宾格斯在试飞时驾驶飞行器坠入了洛克湖，但丢失装备带来的危害远不止无法打捞残骸。他专门为侏儒夺回诺莫瑞根的空中攻势制作了特种工具，以及独有的气压炸弹炸药。没有工具来重建飞行器，也没有弹药可供投放，轰炸那些占据他家园的穴居人和麻风侏儒的行动就无法展开。",al={"宾格斯的动机","宾格斯为什么需要工具","为什么帮助宾格斯"}},["0d3e655b"]={q="谁拿走了宾格斯的补给品，他们为什么会在这里？",a="盘踞在洛克莫丹湖中岛屿上的穴居人在宾格斯坠机后不久伏击了他，并搜走了他的装备。这些原始而凶蛮的地下生物是在矮人遍及卡兹莫丹的挖掘中被发现的。出于凶暴的领地本能，加上抢夺闪亮机械奇物的习性，他们将宾格斯的工具箱和不稳定的炸药拖回了湖畔营地。",al={"谁偷了宾格斯的工具","穴居人 洛克莫丹 宾格斯","穴居人为什么在岛上"}}},fp="25,227,14.206.0,29.266.0,14.264.0,52.217.0,40.116.0,40.153.0,26.129.0,38.157.0,48.233.0"}
P.entries["quest:2039"] = {n="寻找宾格斯",s="“寻找宾格斯”是联盟的一项引导任务，由铁炉堡的侏儒诺恩发起。由于担心一位在一周前执行飞往陷落的诺莫瑞根的空中侦察任务时失踪的飞行员，诺恩指示冒险者去搜寻洛克莫丹的岸边。追踪这位失踪的飞行员会直接找到宾格斯·雷管，他安然无恙，但急需机械打捞。",h="“寻找宾格斯”是联盟的一项引导任务，由铁炉堡的侏儒诺恩发起。由于担心一位在一周前执行飞往陷落的诺莫瑞根的空中侦察任务时失踪的飞行员，诺恩指示冒险者去搜寻洛克莫丹的岸边。追踪这位失踪的飞行员会直接找到宾格斯·雷管，他安然无...",kw={"宾格斯","雷管","飞行器","诺恩","诺莫瑞根","铁炉堡","洛克莫丹","侦察","侏儒区"},ang={["faction:Alliance"]="联盟侦察兵经常在铁炉堡大厅和洛克莫丹的实地行动之间架起通讯桥梁。",["profession:Engineering"]="工程师们能够理解侏儒航空的职业危害，在那里，丢掉一个翼螺母或引擎爆炸只是实地工作中平常的周二。",["race:Gnome"]="对侏儒来说，找回宾格斯意味着保持收复诺莫瑞根的希望，每一个侦察兵和飞行器都很重要。"},sec={{t="失踪的飞行员",b="在铁炉堡繁华的侏儒聚集区侏儒区，人们对失踪的亲人和丢失的机械感到焦虑。侏儒飞行员宾格斯·雷管被派遣去诺莫瑞根的辐射废墟上空执行空中侦察任务。当一周多过去仍杳无音讯时，诺恩预感到了最坏的结果——怀疑宾格斯遭受了侏儒工程学特有的职业危害，把自己炸飞出了天空。最后一次有人目击这位古怪的飞行员是在洛克湖水域上空。"},{t="在洛克湖",b="搜索者并没有发现一堆悲惨的冒烟残骸，而是发现宾格斯在洛克莫丹的岸边活蹦乱跳。这位搁浅的发明家对自己的长期失踪毫不在意，甚至因为自己的飞行技术受到质疑而感到些许冒犯，他完全专注于自己更宏大的事业。宾格斯没有立即回去向诺恩汇报，而是立即请求他的救援者帮助找回被穴居人偷走的工具和雷管炸药，这样他才能继续为侏儒的事业履行职责。"}},faq={{q="宾格斯·雷管是谁？",a="宾格斯·雷管是一位古怪的侏儒飞行员和机械师。他被派往高空对沦陷的诺莫瑞根进行空中监视，随后他的飞行器在洛克莫丹附近坠毁。",al={"宾格斯是谁","宾格斯·雷管背景故事","飞行员是谁"}},{q="为什么宾格斯要在诺莫瑞根上空飞行？",a="在诺莫瑞根因穴居人和辐射而悲惨沦陷后，侏儒的领导层和技师们一直在持续监控它。宾格斯飞上天空从高处侦察敌人的阵地和环境状况，为收复家园的更大努力做出贡献。",al={"宾格斯的任务","为什么宾格斯在飞行","诺莫瑞根侦察"}},{q="宾格斯在哪里？",a="宾格斯可以在洛克莫丹的洛克湖岸边找到，他在东南岸，正试图整理他坠毁的飞行器。",al={"宾格斯在哪里","寻找宾格斯的位置","去哪里找宾格斯"}},{q="诺恩是谁？",a="诺恩是铁炉堡侏儒区的一名侏儒协调员。他负责追踪侏儒人员和任务，并在宾格斯未能按时返回时发起搜救。",al={"诺恩是谁","任务发布者诺恩"}},{q="找到宾格斯之后会发生什么？",a="找到宾格斯会开启后续任务“宾格斯的失物”，在该任务中，冒险者需要从洛克湖岛屿上的穴居人那里找回他的扳手、螺丝刀、锤子和雷管炸药。",al={"找到宾格斯后接下来做什么","翼螺母任务","宾格斯后续任务"}},{q="宾格斯在坠机中受伤了吗？",a="宾格斯完全没有受伤，尽管因为诺恩怀疑他的飞行技术，他的自尊心受到了些许伤害。他真正关心的是找回被穴居人偷走的工具和炸药。",al={"宾格斯受伤了吗","宾格斯死了吗"}}},fx={b67b7bf8={q="诺恩为什么想找到宾格斯？",a="宾格斯奉命飞越沦陷的诺莫瑞根，执行一项关键的侦察任务，却已经一个多星期没有回报消息了。考虑到侏儒机械的不稳定性，以及宾格斯总能惹出灾祸的本事，诺恩担心这名飞行员已经在荒野的某处把自己炸上了天。他需要有人前往宾格斯最后被目击的洛克莫丹附近搜寻，查明他的下落。",al={"为什么寻找宾格斯","诺恩的动机","为什么派人寻找宾格斯"}}},fp="12,264,15.329.0,16.390.0,29.150.0,39.209.0,25.95.0,14.162.0,35.144.0,31.170.0"}
P.entries["quest:204"] = {n="库尔森的药物",s="在北荆棘谷的反抗军营地，尤瓦中士试图通过打击库尔森上校的医疗支援来削弱其军事优势。这些叛军依靠他们的医务人员调配的强效药物和毒药，迫使反抗军战士们渴望能将这些药物化为己用。",h="在北荆棘谷的反抗军营地，尤瓦中士试图通过打击库尔森上校的医疗支援来削弱其军事优势。这些叛军依靠他们的医务人员调配的强效药物和毒药，迫使反抗军战士们渴望能将这些药物化为己用。",kw={"丛林药物","库尔森","库尔森营地","巫医","反抗军营地","尤瓦中士","荆棘谷","毒草汁液"},ang={["faction:Alliance"]="切断库尔森的治疗支援能让更多的反抗军战士在对抗他的部队时幸存下来。"},sec={{t="切断营地的补给",b="库尔森上校在他的丛林部队中配置了许多巫医，他们不仅治疗库尔森的部队，还用毒草汁液毒害尤瓦的战士。为了扭转战局，尤瓦中士指派冒险者进入库尔森营地搜寻这些关键物资。获得他们的丛林药物将有助于治疗反抗军营地的伤员，而捕获一份毒草汁液的样本则能让反抗军得以研究这种毒素并制造出相应的解药。"}},faq={{q="是谁发布了这个任务？",a="位于北荆棘谷反抗军营地的尤瓦中士请求你找回这些医疗物资。",al={"谁发布了坏药任务","坏药任务发布者","尤瓦任务"}},{q="尤瓦中士为什么需要丛林药物？",a="库尔森的巫医使用这些药物来治疗他们自己的士兵。反抗军战士需要同样的物资来治疗并维持他们伤员的生命。",al={"为何需要丛林药物","丛林药物的作用"}},{q="毒草汁液是用来做什么的？",a="库尔森的部队使用毒草汁液来毒害尤瓦的战士。尤瓦中士需要一份样本，以便营地能研究这种化合物并研制出对抗它的解药。",al={"为何需要毒草汁液","汁液用途"}},{q="这些医疗物资存放在哪里？",a="这两样物资都存放在库尔森营地内。巫医随身携带药物，而毒草汁液则存放在营地各处的补给箱里。",al={"哪里能找到丛林药物","汁液位置"}}},fp="12,226,32.332.0,27.106.0,45.130.0,40.149.0,38.148.0"}
P.entries["quest:2040"] = {n="地底突袭",s="沉默的舒尼派遣联盟冒险者进入死亡矿井，寻找一枚动力核心。流离失所的侏儒需要用它为钻机提供动力，钻穿诺莫瑞根周围的岩石，帮助他们夺回家园。",h="沉默的舒尼派遣联盟冒险者进入死亡矿井，寻找一枚动力核心。流离失所的侏儒需要用它为钻机提供动力，钻穿诺莫瑞根周围的岩石，帮助他们夺回家园。",kw={"死亡矿井","小型高能发动机","诺莫瑞根","地精伐木机","回旋钻探","沉默的舒尼","穴居人","地底突袭"},ang={["faction:Alliance"]="作为联盟冒险者，你既能巩固暴风城与流离失所的侏儒盟友之间的情谊，也能打击迪菲亚的补给线。",["profession:Engineering"]="作为工程师，你能领略这项大胆改造的巧思：拆用凶悍地精伐木机的动力核心，为精密的侏儒挖掘机械提供动力。",["race:Gnome"]="作为流亡的侏儒冒险者，你帮助回收的动力核心，能驱动钻机穿透沦陷家园的岩壁，帮助将穴居人赶出诺莫瑞根。"},sec={{t="绝境中的巧思",b="诺莫瑞根惨遭原始穴居人攻陷后，幸存的侏儒工匠逃往卡兹莫丹和暴风城各地。沉默的舒尼便是那些已经开始筹划如何钻穿失落家园周围岩层的工程师之一。她的回旋钻探挖掘机需要强大的动力，才能钻透地下的岩石。人类领地没有可供使用的本地电网，侏儒只好将目光转向犯罪势力手中的地精重型机械。"},{t="夺取迪菲亚铸造厂的零件",b="在西部荒野死亡矿井蜿蜒曲折的矿道深处，艾德温·范克里夫的迪菲亚潜行者雇用了地精工程师，制造战争机器。其中一台是正在运转的地精伐木机，一具行动笨重的自动机械。舒尼派遣联盟人员摧毁或拆解它，取回它那特殊的心脏——小型高能发动机。流亡的侏儒需要这套地精动力装置，驱动钻机穿透地下岩层，展开夺回诺莫瑞根的反攻。"}},faq={{q="谁提供地底突袭任务？",a="任务由沉默的舒尼提供，她是暴风城矮人区的一名侏儒工程师。其他侏儒常常会在提到她雄心勃勃的计划后，指引冒险者去找她。",al={"地底突袭任务提供者","谁提供地底突袭","舒尼任务"}},{q="在哪里能找到小型高能发动机？",a="你可以从西部荒野死亡矿井铸造厂隧道深处的一台正在运转的地精伐木机上，取回小型高能发动机。",al={"小型高能发动机位置","小型高能发动机在哪里","死亡矿井伐木机零件"}},{q="舒尼为什么需要地精伐木机的零件？",a="侏儒的回旋钻探挖掘机需要极为强大的便携动力，才能突破诺莫瑞根周围加固的地下边界。驱动迪菲亚地精伐木机的重型动力核心，恰好能提供钻机所需的机械动力。",al={"为什么需要地精零件","为什么需要伐木机动力装置","小型高能发动机用途"}},{q="这次任务更长远的目标是什么？",a="流亡的侏儒计划为重型挖掘钻机提供动力，钻穿沦陷的诺莫瑞根外围岩层，向占据城中的穴居人发动突袭。",al={"为什么做地底突袭","夺回诺莫瑞根任务","侏儒进攻计划"}},{q="诺莫瑞根发生了什么，才让侏儒筹划这次进攻？",a="穴居人从诺莫瑞根地下深处涌出，发起入侵，攻陷了这座城市。在混乱的防御战中，有毒辐射污染了城市，迫使幸存者沦为难民，逃往铁炉堡和暴风城。",al={"诺莫瑞根为何沦陷","诺莫瑞根发生了什么","穴居人入侵"}},{q="迪菲亚潜行者和穴居人是盟友吗？",a="不是，迪菲亚潜行者和穴居人没有任何联系。迪菲亚雇用了地精工匠，在西部荒野制造战争机器，而舒尼则利用他们在死亡矿井的铸造厂，便捷地获取高功率地精技术。",al={"迪菲亚与穴居人","穴居人和迪菲亚是一伙的吗"}}},fp="19,187,21.404.0,28.462.0,40.170.0,43.120.0,49.243.0,41.178.0,67.215.0,49.212.0"}
P.entries["quest:2041"] = {n="沉默的舒尼",s="铁炉堡的联盟旅人被派往暴风城，寻找沉默的舒尼，她的部队正为进军诺莫瑞根做准备。",h="铁炉堡的联盟旅人被派往暴风城，寻找沉默的舒尼，她的部队正为进军诺莫瑞根做准备。",kw={"矿道地铁","矮人区","诺莫瑞根","自动挖掘机","铁炉堡","沉默的舒尼","暴风城","侏儒区","地底突袭"},ang={["faction:Alliance"]="身为联盟旅人，你可以利用矿道地铁，在铁炉堡与暴风城之间运送人员。",["profession:Engineering"]="身为工程师，你可以看出舒尼的计划需要gyrodrillmatic excavationators，这些复杂的侏儒机械专为在地底深处挖掘隧道而造。",["race:Gnome"]="身为铁炉堡的侏儒，你可以遵循舒尼的命令，加入夺回诺莫瑞根的行动，帮助收复遭辐射污染的家园。"},sec={{t="来自侏儒区的召唤",b="诺莫瑞根遭辐射侵袭而沦陷后，幸存的侏儒在铁炉堡建立了一处流亡者聚居区。这里的工程师、技师和战略家一直在寻找重返失落家园的办法。侏儒区统筹着这项行动，但筹备工作已延伸到卡兹莫丹之外。如今，冒险者被派往南方的暴风城，那里正在筹备地下作战所需的军事装备。"},{t="地下的雄心",b="在暴风城的矮人区，沉默的舒尼指挥着一支受过地下突袭训练的精锐队伍。她的工兵需要自动钻探机，以便挖掘通道，进军穴居人占据的区域。矿道地铁在铁炉堡与暴风城之间的群山下穿行，让前往舒尼所在之处的旅程十分便捷。"}},faq={{q="沉默的舒尼是谁？",a="沉默的舒尼是驻扎在暴风城的一名侏儒军官。她指挥着一支地下突袭部队，制造并部署重型挖掘装备，协助夺回诺莫瑞根。",al={"舒尼是谁","沉默的舒尼","非玩家角色是谁"}},{q="在哪里可以找到沉默的舒尼？",a="舒尼位于暴风城的矮人区，在锻造训练师和熔炉附近，距离矿道地铁站仅几步之遥。",al={"舒尼在哪里","舒尼位置","舒尼坐标"}},{q="如何从铁炉堡前往暴风城？",a="从铁炉堡前往暴风城最快的方式，是搭乘位于侏儒区东北侧的矿道地铁。它载着旅人穿过群山地下，直达暴风城的矮人区。",al={"前往暴风城","铁炉堡到暴风城","如何到达暴风城"}},{q="舒尼需要什么帮助？",a="舒尼正在为一支地下突袭队伍配备装备，需要自动旋转挖掘机的零件。这项行动最终会将冒险者带往西部荒野和死亡矿井。",al={"舒尼任务目标","舒尼需要什么"}},{q="必须完成这个任务才能接取地底突袭吗？",a="不必。这只是一个可选的指引任务。你可以直接前往暴风城的矮人区，与舒尼交谈，接取地底突袭。",al={"与舒尼交谈是否必做","能否直接找舒尼"}},{q="这与诺莫瑞根有什么联系？",a="侏儒领袖们正在集结兵力和挖掘技术，以突破诺莫瑞根的防御。舒尼的队伍正在研发地下钻探设备，用于攻入这座遭到污染的城市。",al={"为何前往诺莫瑞根","与侏儒的联系"}}},fx={["3fdd7df6"]={q="任务发布者为什么派你去找沉默的舒尼？",a="侏儒正在艰难奋战，试图夺回沦陷的家园诺莫瑞根。沉默的舒尼指挥着一支地下突击队，为战事筹备专用的陀螺钻探挖掘机，但她在暴风城的行动缺少人手。铁炉堡的中央指挥部需要有能力的冒险者南下，支援她这项关键的工程计划，攻势才能继续推进。",al={"为什么与舒尼交谈","为什么派人去找舒尼","为什么拜访舒尼"}}},fp="16,117,22.360.0,22.321.0,25.171.0,35.133.0,41.188.0,31.179.0,50.139.0,36.189.0"}
P.entries["quest:205"] = {n="巨魔巫术",s="尼麦兹修士试图通过检查黑暗巨魔的附魔来洞察库尔森上校的腐化原因。在完成“库尔森的秘密”之后，他请求你冒险前往南方的裂颅者领地，从他们的施法者手中获取巫毒咒符。",h="尼麦兹修士试图通过检查黑暗巨魔的附魔来洞察库尔森上校的腐化原因。在完成“库尔森的秘密”之后，他请求你冒险前往南方的裂颅者领地，从他们的施法者手中获取巫毒咒符。",kw={"尼麦兹修士","库尔森上校","秘术师","反抗军营地","裂颅者","荆棘谷","巨魔巫术","巫医"},ang={["faction:Alliance"]="尼麦兹修士在反抗军营地开展工作，征召联盟旅行者去揭开腐化库尔森上校的真相。"},sec={{t="揭开腐化的真相",b="在回顾从丛林中找回的传说时，尼麦兹修士将注意力转向了徘徊在更南方的第二个巨魔部落。他怀疑黑暗巨魔巫术可能是导致库尔森上校堕落成魔的原因。为了验证他的理论，他请求你冒险进入裂颅者的领地，直接从他们的巫医和秘术师手中夺取巫毒咒符，以便他能在反抗军营地研究这些魔法。"}},faq={{q="谁发布了“巨魔巫术”这个任务？",a="尼麦兹修士在荆棘谷北部的反抗军营地发布该任务。",al={"巨魔巫术任务发布者","谁开启巨魔巫术","哪里领取巨魔巫术"}},{q="尼麦兹修士为什么要收集裂颅者巫毒咒符？",a="尼麦兹修士打算研究这些黑暗魔法器具，看看巨魔巫术是否能解释库尔森上校为何陷入邪恶。",al={"为什么尼麦兹修士需要巫毒咒符","巨魔巫术的目的","库尔森腐化巫毒咒符"}},{q="哪些敌人携带巫毒咒符？",a="巫毒咒符由裂颅者领地内的裂颅者巫医和裂颅者秘术师携带。",al={"谁掉落裂颅者巫毒咒符","哪些巨魔有巫毒咒符","巨魔巫术巫毒咒符来源"}},{q="“巨魔巫术”的前置任务是什么？",a="该任务紧随“库尔森的秘密”之后，继续尼麦兹修士对这位上校疯狂行为的调查。",al={"巨魔巫术任务线","巨魔巫术的前置任务是什么","巨魔巫术的前提条件"}}},fp="14,183,25.327.0,35.85.0,52.134.0,33.96.0,35.112.0"}
P.entries["quest:206"] = {n="麦佐斯",s="尼麦兹修士认为库尔森上校是被一股依然存在的隐藏力量逼入了邪道。一个被称为麦佐斯的食人魔术士潜伏在东部的群山之中，掌控着一件据说能扭曲并控制心智的神器。消灭他并收回这件圣物，是为了确保不再有其他指挥官遭受同样的腐蚀。",h="尼麦兹修士认为库尔森上校是被一股依然存在的隐藏力量逼入了邪道。一个被称为麦佐斯的食人魔术士潜伏在东部的群山之中，掌控着一件据说能扭曲并控制心智的神器。消灭他并收回这件圣物，是为了确保不再有其他指挥官遭受同样的腐蚀。",kw={"尼麦兹修士","库尔森","麦佐斯","心灵之眼","食人魔土堆","反抗军营地","荆棘谷"},ang={["faction:Alliance"]="尼麦兹修士在荆棘谷北部的反抗军营地开展工作，寻求联盟的勇士来终结那个腐蚀了库尔森的隐藏邪恶。"},sec={{t="腐蚀的源头",b="尽管库尔森已经倒下，但尼麦兹修士坚称导致叛乱的主要诱因依然存在。他的调查指向了麦佐斯，一个居住在荆棘谷东部高地深处的一座食人魔土堆里的食人魔术士。尼麦兹确信麦佐斯利用了能改变心智的巫术来扭曲库尔森的思想，并警告说如果留下这个食人魔，可能会导致另一位指挥官屈服于同样的邪恶影响。"},{t="回收圣物",b="为了彻底消除威胁，你被要求击杀麦佐斯，从他手中夺取心灵之眼，并将这件具有腐蚀性的神器带回反抗军营地。"},{t="交付之后",b="尼麦兹会给予带回心灵之眼的人以祝福，并打算研究这件神器，看看它的力量是否能为正义所用。如果不能，他说这件东西必须被销毁。"}},faq={{q="麦佐斯是谁？",a="麦佐斯是一个居住在荆棘谷东部群山中一座食人魔土堆里的食人魔术士。尼麦兹修士认为他通过邪恶的魔法在精神上腐蚀了库尔森上校，因此他对此负有责任。",al={"麦佐斯是谁","麦佐斯背景故事","食人魔术士麦佐斯"}},{q="什么是心灵之眼？",a="心灵之眼是一件由麦佐斯持有的神器，据说拥有精神控制魔法，这位食人魔术士利用它来腐蚀并影响他人。",al={"心灵之眼背景故事","这个神器是什么","心灵之眼"}},{q="为什么尼麦兹修士想要杀死麦佐斯？",a="尼麦兹修士担心，只要麦佐斯活着，他的腐蚀力量就可能将其他人变成另一个库尔森。",al={"尼麦兹的动机","为什么要杀麦佐斯","追捕麦佐斯的原因"}}},fp="8,232,24.322.0,18.112.0,18.166.1,16.175.0,23.130.0,44.115.0"}
P.entries["quest:207"] = {n="库尔森的秘密",s="反抗军营地的尼麦兹修士想知道是什么让库尔森上校堕落腐化。尼麦兹怀疑巨魔魔法控制了他，因此派你去荆棘谷的巨魔废墟，抄录刻在四块石板上的传说。",h="反抗军营地的尼麦兹修士想知道是什么让库尔森上校堕落腐化。尼麦兹怀疑巨魔魔法控制了他，因此派你去荆棘谷的巨魔废墟，抄录刻在四块石板上的传说。",kw={"巴拉尔废墟","尼麦兹修士","库尔森上校","反抗军营地","荆棘谷","巨魔传说","暗礁海","祖昆达"},sec={{t="寻找答案",b="库尔森上校曾经是一位伟大而高尚的人，尼麦兹修士想要查明是什么导致了他的堕落。尼麦兹怀疑巨魔魔法控制了上校。为了验证这一点，必须阅读古老的巨魔传说，它们被刻在藏于荆棘谷巨魔废墟中的四块石板上。你被要求抄录每一块石板上的铭文，并将这些副本带回来。"},{t="石板所在地",b="一块石板位于巴拉尔废墟。另一块位于海岸外的深水区，也就是暗礁海，靠近一个被盐鳞鱼人占据的沉没城市。最后两块在祖昆达废墟。"}},faq={{q="谁发起了寻找巨魔石板的任务？",a="在反抗军营地由尼麦兹修士给予。",al={"谁给予库尔森的秘密","在哪里开始库尔森的秘密","尼麦兹修士任务"}},{q="为什么尼麦兹修士想要巨魔传说的副本？",a="尼麦兹修士想知道曾经伟大而高尚的库尔森上校为何会堕落。巨魔魔法可能是罪魁祸首，而石板上的传说或许能证实这一点。",al={"为什么要巨魔石板","库尔森的秘密目的","为什么尼麦兹想要传说"}},{q="四块巨魔石板位于何处？",a="巴拉尔废墟有一块。另一块位于格罗姆高西边的暗礁海深处。还有两块在祖昆达废墟。",al={"石板位置","石板在哪里","库尔森石板地图"}},{q="带回四块石板后接下来会发生什么？",a="尼麦兹修士会研究这些传说，寻找巨魔与库尔森上校堕落之间的联系，故事随后在“巨魔巫术”中继续。",al={"库尔森的秘密之后是什么","库尔森的秘密后续","石板之后的任务线"}}},fp="16,185,21.297.0,21.198.0,44.51.0,53.162.0,41.149.0,51.133.0"}
P.entries["quest:2078"] = {n="基尔卡克的报复",s="基尔卡克·旋杆正寻求向当地的鱼人复仇，因为它们洗劫了他搁浅在黑海岸边的沉船。为了实施他的复仇计划，这位古怪的船长派遣冒险者去重新启动他的机械大副——“重击者4100型”。",h="基尔卡克·旋杆正寻求向当地的鱼人复仇，因为它们洗劫了他搁浅在黑海岸边的沉船。为了实施他的复仇计划，这位古怪的船长派遣冒险者去重新启动他的机械大副——“重击者4100型”。",kw={"黑海岸","基尔卡克","魔像","旋杆","钥匙","鱼人","重击者","重击者4100型"},ang={["faction:Alliance"]="清理掉故障机器和具有攻击性的鱼人，有助于确保黑海岸线对于联盟在奥伯丁与南部地区之间的往来畅通无阻。",["profession:Engineering"]="基尔卡克的机械大副展示了一位搁浅的船长对他的工程设备有多么依赖。",["race:Gnome"]="侏儒或许会将这把发条钥匙认作是一种激活机械自动装置的常用手段。"},sec={{t="船长的复仇",b="搁浅在黑海岸迷雾笼罩的沙滩上，基尔卡克·旋杆拒绝接受被岸上的鱼人击败的命运。在打捞出实施计划所需的零件后，这位古怪的船长将目标锁定为向这个鱼人部落及其首领进行彻底的报复。基尔卡克没有手持弯刀冲入海浪，而是依靠精湛的工程学来实施他的复仇。他将一把发条钥匙交给任何勇敢的陆地生物，委托他们去操控他的机械下属。"},{t="大副的叛变",b="基尔卡克信赖的大副并非什么矮人或水手，而是“重击者4100型”——一个被遗弃在沉船以南浅滩上的叮当作响的机械魔像。虽然发条自动化装置预示着能轻松屠杀鱼人，但这台机器却证明极其不可靠。在被上好发条并带回船长身边后，该构装体发生了灾难性的故障，将它的救助者和制造者误判为敌对目标，从而在海滩上引发了一场战斗。"}},faq={{q="基尔卡克的大副是谁？",a="基尔卡克的大副是“重击者4100型”，这是一个停留在搁浅船长营地南面海岸上的自动化机械魔像。",al={"大副","基尔卡克的大副","谁是大副"}},{q="基尔卡克为什么要复仇？",a="基尔卡克的船在黑海岸遇难，当地的灰雾鱼人搜刮了残骸，并偷走了他大副钥匙的一部分。基尔卡克打算利用他的魔像来粉碎该部落及其首领。",al={"为什么复仇","鱼人复仇","基尔卡克的动机"}},{q="把“重击者”带回去会发生什么？",a="用钥匙激活大副后，将其引导回基尔卡克身边。它抵达船长身边后的行为将在护送过程中揭晓。",al={"重击者攻击","机器人故障","为什么魔像会攻击"}},{q="任务完成后，我该如何处理基尔卡克的钥匙？",a="这把钥匙用于激活“重击者”。任务完成后，它就没有任何用途了。",al={"旋杆的钥匙用途","保留旋杆的钥匙","我可以删除钥匙吗"}},{q="基尔卡克从哪里弄来的“重击者”？",a="该魔像是基尔卡克在卡利姆多北部那次厄运航行中打捞出的货物和装备的一部分，旨在为其船员提供强大的机械助力。",al={"谁制造了重击者","重击者来源"}},{q="魔像被毁后，基尔卡克会放弃吗？",a="当你把他的大副带回时，基尔卡克的计划以及他对你工作的反应将会揭晓。",al={"基尔卡克会怎样","旋杆的复仇之后"}}},fp="18,171,20.354.0,23.352.1,27.120.0,29.200.0,54.150.1,59.101.1,42.173.0,49.76.1"}
P.entries["quest:208"] = {n="王牌猎人",s="在荆棘谷猎杀过该地区最致命的猛兽并证明了自己的实力后，赫米特·奈辛瓦里提出了最后一项终极挑战。这位著名的神枪手要求得到国王邦加拉什的头颅，这是一头巨大的白虎，也是赫米特来到这片丛林的真正原因。",h="在荆棘谷猎杀过该地区最致命的猛兽并证明了自己的实力后，赫米特·奈辛瓦里提出了最后一项终极挑战。这位著名的神枪手要求得到国王邦加拉什的头颅，这是一头巨大的白虎，也是赫米特来到这片丛林的真正原因。",kw={"邦加拉什","巴格拉","王牌猎人","赫米特·奈辛瓦里","辛达尔","荆棘谷","泰希斯","白虎"},ang={["class:Hunter"]="赫米特·奈辛瓦里认为，击倒国王邦加拉什是追踪和狩猎大师能力的终极证明。"},sec={{t="大师的猎物",b="在完成了探险队猎人设下的考验——击杀辛达尔、巴格拉和泰希斯之后，赫米特·奈辛瓦里认可了你的武艺。据这位老牌神枪手所言，他将你的实力与从洛丹伦战场到丛林深处见过的最出色的表现相提并论，认为只有最后一次狩猎才能证明你无人能及的实力：击倒国王邦加拉什，这头巨大的白虎正是探险队队长真正的目标。"},{t="传奇野兽",b="赫米特透露，国王邦加拉什就是他来到荆棘谷的原因。这头强大的野兽曾多次让这位探险队队长本人惨败而归。献上这头野兽的头颅将证明你的狩猎技巧无人能及。"}},faq={{q="谁发布了这个狩猎任务？",a="在你完成之前所有的狩猎大师任务后，赫米特·奈辛瓦里本人会在荆棘谷北部的探险队营地发布这个任务。",al={"任务发布者","谁开启王牌猎人","赫米特·奈辛瓦里任务"}},{q="必须先完成哪些前置狩猎任务？",a="你必须完成营地的整个狩猎系列任务：在“虎之大师”任务中击杀辛达尔，在“豹之大师”任务中击杀巴格拉，以及在“迅猛龙之大师”任务中击杀泰希斯。",al={"前置条件","王牌猎人的前置任务","邦加拉什要求"}},{q="为什么赫米特·奈辛瓦里想要猎杀国王邦加拉什？",a="国王邦加拉什是赫米特前往荆棘谷的全部原因。这头大白虎屡次从他手中逃脱，多次迫使这位老牌神枪手退回营地。",al={"为什么是国王邦加拉什","为什么猎杀邦加拉什","邦加拉什背景故事"}},{q="赫米特需要什么证明？",a="赫米特需要国王邦加拉什的头颅来确认这头大白虎已被确实击杀。",al={"我需要什么物品","邦加拉什任务目标","击杀证明"}},{q="赫米特说他在哪里经历过战斗？",a="赫米特没有讲述他自己的战斗经历；他只是将你使用武器的技巧与他在洛丹伦战场和丛林深处所见过的表现相提并论，并称他很少见到比这更好的水平。",al={"赫米特战争经历","赫米特过往","洛丹伦猎人"}}},fp="15,156,19.353.0,15.203.0,20.141.0,47.136.0,46.157.0,30.88.0,47.145.0"}
P.entries["quest:209"] = {n="劈颅巨魔的獠牙",s="藏宝海湾的科博克需要材料，以满足销往南海的虎牙出口需求。由于猎杀真正的丛林猛兽成本过高，他想出了一种难辨真伪的伪造工艺，原料就是从裂颅者巨魔身上取下的獠牙。",h="藏宝海湾的科博克需要材料，以满足销往南海的虎牙出口需求。由于猎杀真正的丛林猛兽成本过高，他想出了一种难辨真伪的伪造工艺，原料就是从裂颅者巨魔身上取下的獠牙。",kw={"藏宝海湾","伪造","科博克","裂颅者","南海","荆棘谷","虎牙","獠牙"},sec={{t="有利可图的替代品",b="靠常规狩猎为南海遥远岛屿上的买家供应虎牙，已经变得过于昂贵且困难。科博克没有放弃这门生意，而是想出了一种难辨真伪的伪造方法，能把普通的角状物制成足以乱真的仿品。当地裂颅者巨魔嘴里的獠牙，与虎牙的形态最为接近，因此科博克雇用冒险者，从这个丛林部族收集十八颗獠牙，以备齐即将出口的货物。"}},faq={{q="科博克为什么需要裂颅者獠牙？",a="要猎杀足够多的真老虎来满足南海买家的需求，实在过于昂贵且困难。科博克发现，巨魔的獠牙可以加工成难辨真伪的虎牙仿品，让他的生意能够完成每月的出口订单。",al={"为何需要裂颅者獠牙","科博克的獠牙计划","为何伪造虎牙"}},{q="谁在购买这些虎牙？",a="制成的假虎牙会运往遍布南海各个岛屿的贸易伙伴手中。",al={"谁购买獠牙","南海买家","虎牙运往何处"}},{q="这项任务在科博克的任务线中排在哪里？",a="这项任务接在科博克先前要求收集血顶巨魔的耳朵的任务之后。",al={"裂颅者獠牙之前的任务","裂颅者獠牙前置任务","科博克任务顺序"}}},fp="19,166,22.369.0,40.209.0,24.80.0,43.59.0"}
P.entries["quest:2098"] = {n="基尔卡克的钥匙",s="在黑海岸的海边，基尔卡克·旋杆需要有人帮他修复机械大副。他的发条钥匙在礁石上摔成了三块，被野兽和鱼人捡走了。找回这些碎片，是让他的船员恢复正常的第一步。",h="在黑海岸的海边，基尔卡克·旋杆需要有人帮他修复机械大副。他的发条钥匙在礁石上摔成了三块，被野兽和鱼人捡走了。找回这些碎片，是让他的船员恢复正常的第一步。",kw={"黑海岸","大副","森林陆行鸟","基尔卡克·旋杆","灰雾","旋杆的回收行动","海盗","礁石爬行者","蛇颈龙"},ang={["profession:Engineering"]="身为工程师，你能体会到，一场猛烈的海上船难过后，要让浸过海水的发条装置继续运转有多么困难。",["race:Gnome"]="身为侏儒，你或许能理解基尔卡克依靠发条装置充当船员的做法，尽管海盗生涯在你的同族中并不常见。"},sec={{t="流落黑海岸",b="基尔卡克·旋杆是一名侏儒海盗，流落在远离南海的黑海岸。他说，凶猛的蛇颈龙在近海袭击并击沉了他的船。他随着船只残骸被冲上岸，困在这里，与船员失散。"},{t="被捡走的钥匙",b="基尔卡克最牵挂的是他的大副，而非补给或金币。这位伙伴需要一把特制钥匙才能运转，但基尔卡克在礁石浅滩遇难时，钥匙摔成了三块。他还没来得及收集，海滩上的礁石爬行者、树林附近的森林陆行鸟，以及灰雾鱼人部族的拾荒者，就把闪亮的碎片叼走或捡走了。"},{t="奇特的伙伴",b="基尔卡克谈起他的大副时，流露出一位船长坚定不移的忠诚。他说，这位伙伴需要修好才能运转，而那把断裂的钥匙是重新给它上发条的关键。"}},faq={{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是一名侏儒海盗，他的船在黑海岸近海遭到捕食的蛇颈龙袭击并沉没。",al={"基尔卡克·旋杆","侏儒海盗是谁","黑海岸侏儒海盗"}},{q="这把钥匙有什么用途？",a="这把钥匙用来给基尔卡克的机械大副上发条，重新启动它。它在船难中停止了运转。",al={"基尔卡克为什么需要钥匙","基尔卡克钥匙用途","大副钥匙"}},{q="钥匙的三块碎片去了哪里？",a="钥匙在岸上摔碎后，上半截被森林陆行鸟带走，中间部分落到了灰雾鱼人手里，下半截则被沿海的礁石爬行者带走。",al={"钥匙碎片在哪里","谁偷走了钥匙","黑海岸断裂的钥匙"}},{q="一名侏儒海盗为什么会在黑海岸附近航行？",a="基尔卡克原本在卡利姆多北部近海航行，寻找劫掠的机会，却被凶猛的蛇颈龙终结了航程。",al={"基尔卡克为什么在黑海岸","黑海岸的海盗"}},{q="钥匙重新拼好后会发生什么？",a="拿到钥匙的全部三块碎片后，基尔卡克就能给他的伙伴上发条，并继续进行基尔卡克的报复。",al={"找到钥匙后做什么","旋杆的寻回任务后续"}},{q="拿着钥匙碎片的是哪些鱼人？",a="灰雾鱼人捡走了钥匙的中间部分。他们的部族住在黑海岸浅滩一带的沉船残骸之间。",al={"黑海岸鱼人","灰雾鱼人钥匙","沉船鱼人"}}},fp="20,189,21.241.0,17.309.0,20.172.1,23.101.0,25.113.0,41.142.0,46.104.0,42.104.1,42.122.0"}
P.entries["quest:21"] = {n="回音山清剿行动",s="在回音山，治安官玛克布莱德派你进入一座被狗头人占据的矿洞。驻军担心，若是放任不管，它们就会站稳脚跟。",h="在回音山，治安官玛克布莱德派你进入一座被狗头人占据的矿洞。驻军担心，若是放任不管，它们就会站稳脚跟。",kw={"回音山","回音山矿洞","艾尔文","狗头人","劳工","治安官玛克布莱德","玛克布莱德","北郡","小规模战斗","暴风城军队"},ang={["class:Warrior"]="身为战士，你要与成群的狗头人苦工近身搏斗，它们是你最早遇到的一批据守阵地的敌人。",["faction:Alliance"]="身为联盟的一员，你协助夺回出产石料和矿石的矿洞，为战后人类定居点的重建和加固提供物资。",["profession:Mining"]="身为矿工，你的努力让人们能够在北郡山谷各处安全地开采珍贵矿脉，并冶炼矿石。",["race:Human"]="身为人类，清剿回音山是你保卫祖辈王国的第一次真正的武力考验。你向暴风城的军官证明自己的勇气与实力。"},sec={{t="清剿矿洞",b="狗头人在回音山矿洞深处挖掘，囤积偷来的东西，数量也越来越多。趁它们还未蔓延到北郡山谷各处，侵扰农场和静修之地，立刻削减它们的数量。"},{t="薄弱的防线",b="玛克布莱德能抽调的士兵寥寥无几。驻军守卫着南部边境，而艾尔文各地也传来了动乱的消息。在回音山证明自己值得信赖，你就能赢得军队的尊重，并做好准备，前往王国其他地方承担更艰巨的任务。"}},faq={{q="为什么回音山矿洞里到处都是狗头人？",a="矿藏丰富的坑道和废弃的采石场吸引着狗头人。暴风城的兵力捉襟见肘，它们便进入回音山这样无人看守的地方挖掘洞穴、囤积黄金，在地下占据栖身之所。",al={"矿洞里为什么有狗头人","回音山狗头人","狗头人在做什么"}},{q="是谁下令发起这场小规模战斗？",a="治安官玛克布莱德下令发起这场小规模战斗。他指挥驻扎在北郡修道院的暴风城军队部队，以有限的人手负责山谷的防务。",al={"谁发布小规模战斗任务","治安官玛克布莱德的命令"}},{q="回音山矿洞有何战略意义？",a="回音山矿洞出产的石料和矿石，是维持北郡运转和协助重建暴风城所需的物资。盘踞在北郡北部边界的狗头人威胁着修道院和附近的葡萄园。",al={"回音山为何重要","回音山矿洞的重要性"}},{q="这项任务接下来会引向何处？",a="清除矿洞里的第一批狗头人劳工后，治安官玛克布莱德会派你前往闪金镇，协助当地的防务。",al={"小规模战斗之后的任务","回音山之后的下一步"}},{q="为什么暴风城军队不亲自清剿矿洞？",a="暴风城的部队既要守卫遥远的边境，又要应对艾尔文各地的强盗袭击，兵力不足。玛克布莱德依靠新兵处理当地的威胁，而经验丰富的卫兵则坚守防线。",al={"为什么派新兵","暴风城的士兵在哪里"}},{q="狗头人的智慧足以让它们构成有组织的军事威胁吗？",a="落单的狗头人劳工胆小怯懦，头脑简单，但数量一多，就会变得凶悍好斗，极力捍卫领地。若不加以遏制，它们就会挖掘蜿蜒的地道，在洞穴中布设陷阱，引来体型更大、装备更精良的害兽。",al={"狗头人聪明吗","狗头人的危险程度"}}},fx={a391cdc3={q="治安官玛克布莱德为什么要削减回音山矿洞里的狗头人数量？",a="治安官玛克布莱德知道，回音山矿洞里的狗头人越久无人阻挠，就越能在北郡站稳脚跟。放任不管只会让他们进一步扎根，威胁整个山谷，使日后的清剿付出更惨重的伤亡，甚至危及北郡修道院本身的安全。",al={"为什么杀回音山的狗头人","玛克布莱德的动机 回音山","为什么清理回音山矿洞"}}},fp="22,134,16.190.0,14.235.0,46.210.0,24.149.0,52.176.0,34.132.0,57.211.0,66.194.0"}
P.entries["quest:210"] = {n="克拉兹克的烹调锅",s="卡雷布下士从藏宝海湾的地精商人那里买来的机械烹调锅，原本是件神奇的宝贝，后来却坏了。卡雷布请你把它带回地精克拉兹克那里修理。",h="卡雷布下士从藏宝海湾的地精商人那里买来的机械烹调锅，原本是件神奇的宝贝，后来却坏了。卡雷布请你把它带回地精克拉兹克那里修理。",kw={"藏宝海湾","卡雷布下士","烹调锅","克拉兹克","荆棘谷"},sec={{t="坏掉的烹调锅",b="卡雷布下士负责营地里大部分的烹饪工作。这原本是件苦差事，直到卡雷布从藏宝海湾的地精商人那里买来一口机械烹调锅，才省下了许多时间。后来，锅坏了。克拉兹克的烹调锅必须送回地精克拉兹克那里修理，卡雷布希望你能把它带过去。"},{t="克拉兹克检查烹调锅",b="克拉兹克说，这口锅设计精巧，只是偶尔会蹦出一根弹簧，或是有个齿轮滑脱。检查之后，克拉兹克发现蒸汽增压器锈坏了，关节垫圈裂了，调节器也掉了几个齿。克拉兹克能修好它，不过照老规矩，修理是要收费的。"}},faq={{q="谁派你去找克拉兹克？",a="是卡雷布下士，他负责营地里大部分的烹饪工作。他买来的机械烹调锅坏了。",al={"谁提供克拉兹克的烹调锅","谁开启克拉兹克的烹调锅","卡雷布下士任务"}},{q="在哪里能找到克拉兹克？",a="克拉兹克是藏宝海湾的地精商人，就是他把锅卖给了卡雷布。",al={"克拉兹克在哪里","克拉兹克位置","克拉兹克藏宝海湾"}},{q="卡雷布下士想让你把什么带给克拉兹克？",a="一口名叫克拉兹克的烹调锅的机械烹调锅，它曾替卡雷布省下许多工夫，后来却坏了。",al={"克拉兹克的烹调锅是什么","给克拉兹克带什么"}},{q="卡雷布为什么向克拉兹克买烹调锅？",a="卡雷布负责营地里大部分的烹饪工作，这口锅在坏掉之前，替他省下了许多时间。",al={"为什么买机械烹调锅","卡雷布烹调锅"}}},fp="16,145,12.269.0,19.247.1,24.127.0,26.71.0,48.116.0,44.99.0"}
P.entries["quest:2118"] = {n="瘟疫蔓延",s="“瘟疫之地”是联盟的一项任务，由黑海岸的萨纳瑞恩·绿树提供。为了消除折磨本地野生动物的蔓延腐化，萨纳瑞恩委托冒险者使用一件附魔圣物活捉一只狂暴的蓟熊，试图寻找治愈之法。",h="“瘟疫之地”是联盟的一项任务，由黑海岸的萨纳瑞恩·绿树提供。为了消除折磨本地野生动物的蔓延腐化，萨纳瑞恩委托冒险者使用一件附魔圣物活捉一只狂暴的蓟熊，试图寻找治愈之法。",kw={"净化感染者","黑海岸","瘟疫之地","狂暴的蓟熊","萨纳瑞恩·绿树","萨纳瑞恩的希望","蓟熊"},ang={["class:Druid"]="德鲁伊们在目睹自然遭受腐化后与萨纳瑞恩感同身受，而熊的悲惨死亡更加凸显了这片土地上蔓延的疾病是多么阴险。",["faction:Alliance"]="在卡利姆多北部旅行的联盟旅者必须面对那些正逼近定居领土边界的未受遏制的腐化。",["race:NightElf"]="对于卡多雷而言，看到黑海岸的本土动植物腐朽成狂暴的癫狂，是对塞纳留斯以及他们誓死捍卫的自然平衡的亵渎。"},sec={{t="荒野之灾",b="一种邪恶的疾病正在黑海岸的森林中蔓延，将这里的野兽扭曲成了疯狂而具有攻击性的旧日残影。当地的蓟熊受到的折磨最深，它们陷入了狂暴的癫狂，威胁着过往的旅人和海岸脆弱的生态平衡。暗夜精灵哨兵通常会用刀剑回应，而德鲁伊则试图理解并治愈其根源。"},{t="萨纳瑞恩的希望",b="萨纳瑞恩·绿树拒绝在尝试拯救之前就屠杀这些受腐化的野兽，于是制造了一种名为“萨纳瑞恩的希望”的特制陷阱。冒险者将该装置放置在森林地面上，利用其柔和的光芒暂时平复狂怒蓟熊的心智。一旦被安抚，野兽就会温顺地跟随旅行者回到萨纳瑞恩的前哨站接受研究。"},{t="悲剧的药剂",b="当冒险者成功将一只受感染的熊引导至营地时，萨纳瑞恩立即尝试用恢复魔法来净化疾病。遗憾的是，他的初步尝试带来了灾难性的后果：旋转的净化能量超出了野兽虚弱的体质承受极限，导致它当场倒地死亡。这次失败揭示了黑暗瘟疫的渗透究竟有多深。"}},faq={{q="谁提供了“瘟疫之地”任务？",a="该任务由萨纳瑞恩·绿树提供，他是一位位于黑海岸奥伯丁的暗夜精灵德鲁伊，致力于治愈受感染的野生动物。",al={"瘟疫之地任务发布者","萨纳瑞恩黑海岸任务","谁开启瘟疫之地任务"}},{q="“瘟疫之地”的任务目标是什么？",a="你必须使用提供的物品“萨纳瑞恩的希望”来诱捕并安抚黑海岸的狂暴的蓟熊，然后将受控的野兽活着带回给萨纳瑞恩。",al={"瘟疫之地目标","瘟疫之地怎么做","如何在黑海岸抓熊"}},{q="当你把熊带回来时会发生什么？",a="萨纳瑞恩试图用治疗魔法净化这种动物，但病情已经恶化得太深了。压力超出了野兽的承受极限，它在治疗后立即死亡。",al={"熊会死吗","萨纳瑞恩的治愈结果","瘟疫之地熊死亡"}},{q="你用什么物品来捕获这只熊？",a="萨纳瑞恩提供了一个名为“萨纳瑞恩的希望”的附魔捕获装置，它发出的平静光芒可以安抚狂怒的熊，使其跟随你。",al={"瘟疫之地陷阱","萨纳瑞恩的希望物品","黑海岸捕熊"}},{q="“瘟疫之地”之后的任务是什么？",a="“瘟疫之地”是一个三部分任务链的第一章。完成它可以解锁后续任务“净化感染者”，该任务最终通向最终任务“萨纳瑞恩的希望”。",al={"瘟疫之地后续任务","瘟疫之地任务链","萨纳瑞恩后续"}},{q="为什么蓟熊会狂暴？",a="一种潜行的腐化瘟疫正在黑海岸蔓延，毒害着当地野生动物的身心，驱使高贵的蓟熊陷入无脑的攻击状态。",al={"为什么黑海岸的熊生病了","黑海岸瘟疫熊","黑海岸腐化"}}},fp="13,195,26.284.0,17.281.0,15.276.1,34.128.0,39.114.0,48.154.1,41.126.0,33.80.0,32.126.0"}
P.entries["quest:213"] = {n="恶性竞争",s="盖尔瑞兹一直在排挤贸易大王任命的权贵，现在更是向最臭名昭著的海盗发难，大财主里维加兹绝不会坐视不理。作为回应，藏宝海湾的科博克指派冒险者去偷取风险投资公司地质学家在纳菲瑞提湖附近发现的奇怪蓝色水晶。",h="盖尔瑞兹一直在排挤贸易大王任命的权贵，现在更是向最臭名昭著的海盗发难，大财主里维加兹绝不会坐视不理。作为回应，藏宝海湾的科博克指派冒险者去偷取风险投资公司地质学家在纳菲瑞提湖附近发现的奇怪蓝色水晶。",kw={"藏宝海湾","盖尔瑞兹","吉格尔方特","科博克","纳菲瑞提湖","里维加兹","翻滚的水晶","风险投资公司"},sec={{t="商业问题",b="盖尔瑞兹不仅排挤贸易大王任命的权贵，还向最臭名昭著的海盗发难，此举已然越界。大财主里维加兹无法容忍这种傲慢，指示科博克采取任何必要手段处理这次入侵。科博克选择的对策是直接窃取，目标就是风险投资公司采矿队挖掘出的那些奇怪的蓝色石头。"},{t="地质学家的藏品",b="在纳菲瑞提湖周围活动的风险投资公司地质学家对这些不同寻常的水晶表现出了极大的兴趣。科博克想要八份样本带回藏宝海湾，他并不关心这些样本是如何获取的，只要能落到他手里就行。"},{t="翻滚的发现",b="对归还的标本进行检查后发现，它们经过了翻滚工艺处理，这表明风险投资公司打算将其用作燃料或工业催化剂。科博克打算将样本送往首席药剂师吉格尔方特处进行更详细的研究。"}},faq={{q="谁给予了“恶意收购”这个任务？",a="科博克，他在荆棘谷的海盗避风港藏宝海湾活动，代表大财主里维加兹下达了这项任务。",al={"恶意收购任务发布者","谁开启恶意收购","科博克任务"}},{q="大财主里维加兹为什么对盖尔瑞兹感到愤怒？",a="盖尔瑞兹排挤了贸易大王任命的权贵，现在又向最臭名昭著的海盗发难，里维加兹无法容忍这一点。",al={"里维加兹为何愤怒","盖尔瑞兹里维加兹冲突","科博克为什么想要水晶"}},{q="水晶位于何处？",a="水晶由在纳菲瑞提湖周围工作的风险投资公司地质学家携带。",al={"去哪里寻找翻滚的水晶","翻滚的水晶位置","纳菲瑞提湖水晶"}}},fp="16,308,20.175.0,21.243.0,20.197.1,37.96.0,40.147.0,31.76.0"}
P.entries["quest:2138"] = {n="清除疫病",s="在黑海岸，萨纳瑞恩·绿树面对染病的蓟熊，陷入了艰难的抉择。他试图治好一头蓟熊，却以失败告终，如今他请你杀死这些狂暴的野兽，以免它们伤害其他生物，或让疾病蔓延。",h="在黑海岸，萨纳瑞恩·绿树面对染病的蓟熊，陷入了艰难的抉择。他试图治好一头蓟熊，却以失败告终，如今他请你杀死这些狂暴的野兽，以免它们伤害其他生物，或让疾病蔓延。",kw={"奥伯丁","净化","黑海岸","染病","狂暴的蓟熊","萨纳瑞恩","护树者"},ang={["class:Druid"]="身为德鲁伊，Tharnariun的命令或许会让你格外痛苦。这是出于仁慈和对森林的关爱，而非寻常的狩猎。",["class:Hunter"]="身为猎人，你明白，即使病因尚不明确，扑杀染病的掠食者也能保护更广阔的生态环境。",["race:NightElf"]="身为kaldorei，下令杀死遭到腐化的野兽，让你背负着沉重的负担。自战争以来，疾病已深入你祖先的家园。"},sec={{t="痛苦的抉择",b="萨纳瑞恩·绿树一直在寻找良方，医治在黑海岸野生动物中蔓延的疾病。他曾试图净化一头被捕获的熊，但蓟熊依然疾病缠身，凶暴异常。如今，他请你结束它们的生命。他担心它们会撕咬其他生物，让疾病进一步蔓延到古老的林地深处。"},{t="遏制荒野之患",b="萨纳瑞恩请你杀死二十头狂暴的熊，尽管他知道这无法根治瘟疫。杀死这些熊，能为奥伯丁的守卫争取时间。在有人找到并切断森林腐化的源头之前，这座聚居地别无他法，只能以此抵挡凶猛的兽群及其带来的危险。"}},faq={{q="萨纳瑞恩为什么要杀死蓟熊，而不是治好它们？",a="萨纳瑞恩曾试图净化一头被捕获的熊，但治疗失败，那头野兽也死了。如今，染病的熊威胁着其他生物，因此杀死它们成了他减缓疾病蔓延的最后手段。",al={"为什么杀熊","为什么不治好熊","萨纳瑞恩的熊任务"}},{q="萨纳瑞恩·绿树是谁？",a="萨纳瑞恩是奥伯丁的一位暗夜精灵看护者。他研究侵袭黑海岸动植物的疾病，努力维护自然的平衡，抵御不断蔓延的腐化。",al={"萨纳瑞恩的职责","谁提供清除疫病任务"}},{q="杀死狂暴的熊，真的能终结瘟疫吗？",a="不能。萨纳瑞恩提醒你，杀死狂暴的熊并不能阻止瘟疫。这只能减缓感染与暴力的蔓延，为森林和奥伯丁的居民争取时间。",al={"这能解决黑海岸的问题吗","瘟疫治好了吗"}},{q="清除疫病之后是什么任务？",a="你回去复命后，萨纳瑞恩会让你准备迎接更多的流血，并交给你萨纳瑞恩的希望，继续处理那些遭受疫病侵袭的野生动物。",al={"清除疫病之后的任务","清除疫病后续任务"}},{q="狂暴的蓟熊在哪里？",a="狂暴的蓟熊在黑海岸中部的沿海与内陆森林中游荡，出没于奥伯丁以南和以东雾气笼罩的松林间。",al={"狂暴的蓟熊位置","黑海岸的熊在哪里"}},{q="是什么让蓟熊变得狂暴？",a="一股席卷卡利姆多北部林地的神秘污秽腐化了这些熊，让原本温顺的野生动物变成疯狂而凶猛的野兽，萨纳瑞恩尝试的疗法也无法治愈它们。",al={"熊为什么生病","黑海岸熊的疾病"}}},fp="25,196,18.299.0,20.306.1,67.199.0,29.187.0,53.174.0,43.165.0,40.128.0,42.197.0"}
P.entries["quest:2139"] = {n="萨纳瑞恩的希望",s="“萨纳瑞恩的希望”是萨纳瑞恩·绿树为遏制黑海岸野生动物疫病所做努力的沉重总结。在击杀森林中无数感染的野兽以使其解脱后，联盟勇士被指派去消灭奥伯丁东北部那头患有狂犬病的“大兽穴”之母。",h="“萨纳瑞恩的希望”是萨纳瑞恩·绿树为遏制黑海岸野生动物疫病所做努力的沉重总结。在击杀森林中无数感染的野兽以使其解脱后，联盟勇士被指派去消灭奥伯丁东北部那头患有狂犬病的“大兽穴”之母。",kw={"奥伯丁","巴莎兰","净化感染者","黑海岸","大兽穴之母","染病的刺鬃熊","萨纳瑞恩·绿树","萨纳瑞恩的希望"},ang={["class:Druid"]="德鲁伊通过乌索克的教导，在精神上非常尊崇熊。处决一头被腐蚀的大兽穴之母，是关于自然的微妙平衡以及腐蚀所带来的悲剧的一次庄严提醒。",["class:Hunter"]="猎人们理解被疾病折磨至疯狂的顶级掠食者的悲剧，懂得在何时扑杀感染的野兽才是真正的仁慈之举。",["faction:Alliance"]="保护奥伯丁加强了联盟在卡利姆多北部海岸的据点，证明了他们捍卫暗夜精灵领地免受日益严重的荒野威胁的决心。",["race:NightElf"]="对于暗夜精灵而言，杀害林地野兽——尤其是母熊——违背了他们对自然的基本敬畏，这使得这项职责成为一种痛苦而悲伤的必然。"},sec={{t="悲剧性的必要之举",b="第三次战争后，黑海岸的野生生物开始染上一种非自然的狂犬病。驻守奥伯丁的萨纳瑞恩·绿树花费了数日时间，指派过往的旅者去解决那些受感染的野兽，以减轻森林的苦痛。然而，扑杀染病的刺鬃熊仅仅是治标。为了阻止瘟疫蔓延，他断定必须根除当地熊群中的源头：那位被称为“大兽穴”之母的雌兽。"},{t="大兽穴之母",b="“大兽穴”之母潜伏在奥伯丁东北部、巴莎兰古迹附近的一个洞穴中，它曾是林地动物群的重要守护者。受困于席卷卡利姆多北部的疯狂折磨，它不断产下并抚育着患有狂犬病的幼崽。通过在洞穴中猎杀这位母亲，联盟英雄结束了它的痛苦，也遏制了那群在沿海公路上徘徊的狂暴熊群。"},{t="卡利姆多的严酷现实",b="在大兽穴之母死后，萨纳瑞恩表达了深切的感激，但同时也笼罩在忧郁之中。对于卡多雷来说，对林地生物举起武器是一种痛苦的职责。然而，随着黑暗力量压向他们的新家园，许多人感到绝望或寻求庇护，像这样的行动证明了奥伯丁的保卫者们愿意承担起保护荒野所必需的沉重道德负担。"}},faq={{q="谁是萨纳瑞恩·绿树？",a="萨纳瑞恩·绿树是驻扎在奥伯丁的一位暗夜精灵照看者。由于黑海岸的野生动物被枯萎和疯狂所扭曲，他深感不安，并负责监督对这些受苦动物的研究、追踪以及最终让它们解脱的工作。",al={"萨纳瑞恩","谁提供萨纳瑞恩的希望","绿树 奥伯丁"}},{q="大兽穴之母位于何处？",a="它栖息在奥伯丁东北部山丘中的一个洞穴里，就在巴莎兰遗迹的东面。",al={"大兽穴之母在哪里","大兽穴之母洞穴位置","找到大兽穴之母"}},{q="为什么必须杀死大兽穴之母，而不是治愈它？",a="肆虐黑海岸野生动物的瘟疫已经深入骨髓，并正驱使野兽陷入狂暴。由于目前没有立竿见影的治疗方法，且大兽穴之母还在不断繁育染病的后代，萨纳瑞恩断定，将其击杀是阻止瘟疫进一步蔓延的唯一途径。",al={"大兽穴之母能被拯救吗","为什么要杀大兽穴之母","治疗大兽穴之母"}},{q="哪些任务引导至“萨纳瑞恩的希望”？",a="该任务是三部分任务链的最后一步。它始于“被瘟疫感染的土地”，经过“净化感染者”，最后以“萨纳瑞恩的希望”结束。",al={"萨纳瑞恩的希望前置任务","萨纳瑞恩任务链"}},{q="是什么让黑海岸的动物生病？",a="萨纳瑞恩没有指明源头。他只知道某种瘟疫正在黑海岸蔓延，控制着它所触及的一切生物的思想和身体，而刺鬃熊受到的影响最为严重。",al={"为什么黑海岸的熊会患狂犬病","黑海岸动物瘟疫起因","什么腐蚀了这些熊"}},{q="为什么萨纳瑞恩会提到人们逃往防御更严密的领地？",a="奥伯丁是一个暴露在外的沿海哨所，饱受幽灵、堕落野生动物和敌对生物的困扰。随着暗夜精灵文明在燃烧军团入侵后的废墟上艰难重建，一些居民感到不堪重负，选择躲藏起来或撤往更安全的联盟堡垒。",al={"逃离奥伯丁","防御严密的联盟领地"}}},fp="17,235,18.381.0,14.390.1,28.324.0,29.234.0,32.107.0,51.259.0,41.159.0,45.176.0,63.268.0"}
